    static void *
alloc(size_t size)
{
    return lalloc(size, TRUE);
}

    static void *
alloc_clear(size_t size)
{
    void *p;

    p = lalloc(size, TRUE);
    if (p != NULL)
    {
        (void) memset((p), (0), (size)) ;
    }
    return p;
}

    static void *
lalloc_clear(size_t size, int message)
{
    void *p;

    p = lalloc(size, message);
    if (p != NULL)
    {
        (void) memset((p), (0), (size)) ;
    }
    return p;
}

    static void *
lalloc(size_t size, int message)
{
    void        *p;
    static int  releasing = FALSE;
    int         try_again;

    if (size == 0)
    {
        emsg_silent = 0;
        iemsg(e_internal_error_lalloc_zero);
        return NULL;
    }

    for (;;)
    {
        if ((p = malloc(size)) != NULL)
        {
            goto theend;
        }
        if (releasing)
        {
            break;
        }
        releasing = TRUE;

        clear_sb_text(TRUE);
        try_again = mf_release_all();

        releasing = FALSE;
        if (!try_again)
        {
            break;
        }
    }

    if (message && p == NULL)
    {
        do_outofmem_msg(size);
    }

theend:
    return p;
}

    static void
do_outofmem_msg(size_t size)
{
    if (did_outofmem_msg)
    {
        return;
    }

    emsg_silent = 0;

    did_outofmem_msg = TRUE;

    semsg(_(e_out_of_memory_allocating_nr_bytes), (long_u)size);

    if (starting == NO_SCREEN)
    {
        mch_exit(123);
    }
}

    static char_u *
vim_memsave(char_u *p, size_t len)
{
    char_u *ret = alloc(len);

    if (ret != NULL)
    {
         memmove((char *)(ret), (char *)(p), len) ;
    }
    return ret;
}

    static void
vim_free(void *x)
{
    if (x != NULL && !really_exiting)
    {
        free(x);
    }
}

    static void
ga_clear(garray_T *gap)
{
    vim_free(gap->ga_data);
    ga_init(gap);
}

    static void
ga_clear_strings(garray_T *gap)
{
    int         i;

    if (gap->ga_data != NULL)
    {
        for (i = 0; i < gap->ga_len; ++i)
        {
            vim_free(((char_u **)(gap->ga_data))[i]);
        }
    }
    ga_clear(gap);
}

    static void
ga_init(garray_T *gap)
{
    gap->ga_data = NULL;
    gap->ga_maxlen = 0;
    gap->ga_len = 0;
}

    static void
ga_init2(garray_T *gap, size_t itemsize, int growsize)
{
    ga_init(gap);
    gap->ga_itemsize = (int)itemsize;
    gap->ga_growsize = growsize;
}

    static int
ga_grow(garray_T *gap, int n)
{
    if (gap->ga_maxlen - gap->ga_len < n)
    {
        return ga_grow_inner(gap, n);
    }
    return OK;
}

    static int
ga_grow_inner(garray_T *gap, int n)
{
    size_t      old_len;
    size_t      new_len;
    char_u      *pp;

    if (n < gap->ga_growsize)
    {
        n = gap->ga_growsize;
    }

    if (n < gap->ga_len / 2)
    {
        n = gap->ga_len / 2;
    }

    if (n > 0 && (size_t)(gap->ga_len + n) > SIZE_MAX / gap->ga_itemsize)
    {
        return FAIL;
    }
    new_len = (size_t)gap->ga_itemsize * (gap->ga_len + n);
    pp =  realloc((gap->ga_data), (new_len)) ;
    if (pp == NULL)
    {
        return FAIL;
    }
    old_len = (size_t)gap->ga_itemsize * gap->ga_maxlen;
     memset((pp + old_len), (0), (new_len - old_len)) ;
    gap->ga_maxlen = gap->ga_len + n;
    gap->ga_data = pp;
    return OK;
}

    static char_u *
ga_concat_strings(garray_T *gap, char *sep)
{
    int         i;
    int         len = 0;
    int         sep_len = (int) strlen((char *)(sep)) ;
    char_u      *s;
    char_u      *p;

    for (i = 0; i < gap->ga_len; ++i)
    {
        len += (int) strlen((char *)(((char_u **)(gap->ga_data))[i])) ;
    }

    if (gap->ga_len > 1)
    {
        len += (gap->ga_len - 1) * sep_len;
    }

    s = alloc(len + 1);
    if (s == NULL)
    {
        return NULL;
    }

    *s = NUL;
    p = s;
    for (i = 0; i < gap->ga_len; ++i)
    {
        if (p != s)
        {
             strcpy((char *)(p), (char *)(sep)) ;
            p += sep_len;
        }
         strcpy((char *)(p), (char *)(((char_u **)(gap->ga_data))[i])) ;
        p +=  strlen((char *)(p)) ;
    }
    return s;
}

    static int
ga_copy_string(garray_T *gap, char_u *p)
{
    char_u *cp = vim_strsave(p);

    if (cp == NULL)
    {
        return FAIL;
    }

    if (ga_grow(gap, 1) == FAIL)
    {
        vim_free(cp);
        return FAIL;
    }
    ((char_u **)(gap->ga_data))[gap->ga_len++] = cp;
    return OK;
}

    static int
ga_add_string(garray_T *gap, char_u *p)
{
    if (ga_grow(gap, 1) == FAIL)
    {
        return FAIL;
    }
    ((char_u **)(gap->ga_data))[gap->ga_len++] = p;
    return OK;
}

    static void
ga_concat(garray_T *gap, char_u *s)
{
    int    len;

    if (s == NULL || *s == NUL)
    {
        return;
    }
    len = (int) strlen((char *)(s)) ;
    if (ga_grow(gap, len) == OK)
    {
         memmove((char *)((char *)gap->ga_data + gap->ga_len), (char *)(s), (size_t)len) ;
        gap->ga_len += len;
    }
}

    static void
ga_concat_len(garray_T *gap, char_u *s, size_t len)
{
    if (s == NULL || *s == NUL || len == 0)
    {
        return;
    }
    if (ga_grow(gap, (int)len) == OK)
    {
         memmove((char *)((char *)gap->ga_data + gap->ga_len), (char *)(s), len) ;
        gap->ga_len += (int)len;
    }
}

    static int
ga_append(garray_T *gap, int c)
{
    if (ga_grow(gap, 1) == FAIL)
    {
        return FAIL;
    }
    *((char *)gap->ga_data + gap->ga_len) = c;
    ++gap->ga_len;
    return OK;
}

// ==================== arglist.c ====================

enum { AL_SET = 1 };
enum { AL_ADD = 2 };
enum { AL_DEL = 3 };

static int arglist_locked = FALSE;

    static int
check_arglist_locked(void)
{
    if (arglist_locked)
    {
        emsg(_(e_cannot_change_arglist_recursively));
        return FAIL;
    }
    return OK;
}

    static void
alist_clear(alist_T *al)
{
    if (check_arglist_locked() == FAIL)
    {
        return;
    }
    while (--al->al_ga.ga_len >= 0)
    {
        vim_free( ((aentry_T *)((al)->al_ga.ga_data)) [al->al_ga.ga_len].ae_fname);
    }
    ga_clear(&al->al_ga);
}

    static void
alist_init(alist_T *al)
{
    ga_init2(&al->al_ga, sizeof(aentry_T), 5);
}

    static void
alist_unlink(alist_T *al)
{
    if (al != &global_alist && --al->al_refcount <= 0)
    {
        alist_clear(al);
        vim_free(al);
    }
}

    static void
alist_new(void)
{
    curwin->w_alist =  (alist_T *)alloc(sizeof(alist_T)) ;
    if (curwin->w_alist == NULL)
    {
        curwin->w_alist = &global_alist;
        ++global_alist.al_refcount;
    }
    else
    {
        curwin->w_alist->al_refcount = 1;
        curwin->w_alist->id = ++max_alist_id;
        alist_init(curwin->w_alist);
    }
}

    static void
alist_set(alist_T     *al, int         count, char_u      **files, int         use_curbuf, int         *fnum_list, int         fnum_len)
{
    int         i;

    if (check_arglist_locked() == FAIL)
    {
        return;
    }

    alist_clear(al);
    if (  __builtin_expect(((((&al->al_ga)->ga_maxlen - (&al->al_ga)->ga_len < (count)) ? ga_grow_inner((&al->al_ga), (count)) : OK) == OK), 1)  )
    {
        for (i = 0; i < count; ++i)
        {
            if (got_int)
            {
                while (i < count)
                {
                    vim_free(files[i++]);
                }
                break;
            }

            if (fnum_list != NULL && i < fnum_len)
            {
                arglist_locked = TRUE;
                buf_set_name(fnum_list[i], files[i]);
                arglist_locked = FALSE;
            }

            alist_add(al, files[i], use_curbuf ? 2 : 1);
            ui_breakcheck();
        }
        vim_free(files);
    }
    else
    {
        FreeWild(count, files);
    }
    if (al == &global_alist)
    {
        arg_had_last = FALSE;
    }
}

    static void
alist_add(alist_T     *al, char_u      *fname, int         set_fnum)
{
    win_T       *wp = curwin;

    if (fname == NULL)
    {
        return;
    }
    if (check_arglist_locked() == FAIL)
    {
        return;
    }
    arglist_locked = TRUE;
    ++wp->w_locked;

     ((aentry_T *)((al)->al_ga.ga_data)) [al->al_ga.ga_len].ae_fname = fname;
    if (set_fnum > 0)
    {
         ((aentry_T *)((al)->al_ga.ga_data)) [al->al_ga.ga_len].ae_fnum =
            buflist_add(fname, BLN_LISTED | (set_fnum == 2 ? BLN_CURBUF : 0));
    }
    ++al->al_ga.ga_len;

    arglist_locked = FALSE;
    --wp->w_locked;
}

    static char_u *
do_one_arg(char_u *str)
{
    char_u      *p;
    int         inbacktick;

    inbacktick = FALSE;
    for (p = str; *str; ++str)
    {
        if (rem_backslash(str))
        {
            *p++ = *str++;
            *p++ = *str;
        }
        else
        {
            if (!inbacktick && vim_isspace(*str))
            {
                break;
            }
            if (*str == '`')
            {
                inbacktick ^= TRUE;
            }
            *p++ = *str;
        }
    }
    str = skipwhite(str);
    *p = NUL;

    return str;
}

    static int
get_arglist(garray_T *gap, char_u *str, int escaped)
{
    ga_init2(gap, sizeof(char_u *), 20);
    while (*str != NUL)
    {
        if (ga_grow(gap, 1) == FAIL)
        {
            ga_clear(gap);
            return FAIL;
        }
        ((char_u **)gap->ga_data)[gap->ga_len++] = str;

        if (!escaped)
        {
            return OK;
        }

        str = do_one_arg(str);
    }
    return OK;
}

    static void
alist_check_arg_idx(void)
{
    win_T       *win;
    tabpage_T   *tp;

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
     {
         for ((win) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (win); (win) = (win)->w_next)
         {
        if (win->w_alist == curwin->w_alist)
        {
            check_arg_idx(win);
        }
         }
     }
}

    static void
alist_add_list(int         count, char_u      **files, int         after, int         will_edit)
{
    int         i;
    int         old_argcount =  ( (curwin)->w_alist ->al_ga.ga_len) ;

    if (check_arglist_locked() != FAIL &&   __builtin_expect(((((& (curwin)->w_alist ->al_ga)->ga_maxlen - (& (curwin)->w_alist ->al_ga)->ga_len < (count)) ? ga_grow_inner((& (curwin)->w_alist ->al_ga), (count)) : OK) == OK), 1)  )
    {
        win_T   *wp = curwin;

        if (after < 0)
        {
            after = 0;
        }
        if (after >  ( (curwin)->w_alist ->al_ga.ga_len) )
        {
            after =  ( (curwin)->w_alist ->al_ga.ga_len) ;
        }
        if (after <  ( (curwin)->w_alist ->al_ga.ga_len) )
        {
             memmove((char *)(&( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [after + count])), (char *)(&( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [after])), ( ( (curwin)->w_alist ->al_ga.ga_len)  - after) * sizeof(aentry_T)) ;
        }
        arglist_locked = TRUE;
        ++wp->w_locked;
        for (i = 0; i < count; ++i)
        {
            int flags = BLN_LISTED | (will_edit ? BLN_CURBUF : 0);

             ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [after + i].ae_fname = files[i];
             ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [after + i].ae_fnum = buflist_add(files[i], flags);
        }
        arglist_locked = FALSE;
        --wp->w_locked;
         (wp)->w_alist ->al_ga.ga_len += count;
        if (old_argcount > 0 && wp->w_arg_idx >= after)
        {
            wp->w_arg_idx += count;
        }
        return;
    }

    for (i = 0; i < count; ++i)
    {
        vim_free(files[i]);
    }
}

    static void
arglist_del_files(garray_T *alist_ga)
{
    regmatch_T  regmatch;
    int         didone;
    int         i;
    char_u      *p;
    int         match;

    regmatch.rm_ic = p_fic;
    for (i = 0; i < alist_ga->ga_len && !got_int; ++i)
    {
        p = ((char_u **)alist_ga->ga_data)[i];
        p = file_pat_to_reg_pat(p, NULL, NULL, FALSE);
        if (p == NULL)
        {
            break;
        }
        regmatch.regprog = vim_regcomp(p, magic_isset() ? RE_MAGIC : 0);
        if (regmatch.regprog == NULL)
        {
            vim_free(p);
            break;
        }

        didone = FALSE;
        for (match = 0; match <  ( (curwin)->w_alist ->al_ga.ga_len) ; ++match)
        {
            if (vim_regexec(&regmatch, alist_name(& ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [match]), (colnr_T)0))
            {
                didone = TRUE;
                vim_free( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [match].ae_fname);
                 memmove((char *)( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data)  + match), (char *)( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data)  + match + 1), ( ( (curwin)->w_alist ->al_ga.ga_len)  - match - 1) * sizeof(aentry_T)) ;
                -- ( (curwin)->w_alist ->al_ga.ga_len) ;
                if (curwin->w_arg_idx > match)
                {
                    --curwin->w_arg_idx;
                }
                --match;
            }
        }

        vim_regfree(regmatch.regprog);
        vim_free(p);
        if (!didone)
        {
            semsg(_(e_no_match_str_2), ((char_u **)alist_ga->ga_data)[i]);
        }
    }
    ga_clear(alist_ga);
}

    static int
do_arglist(char_u      *str, int         what, int         after  __attribute__((unused)) , int         will_edit)
{
    garray_T    new_ga;
    int         exp_count;
    char_u      **exp_files;
    int         i;
    int         arg_escaped = TRUE;

    if (check_arglist_locked() == FAIL)
    {
        return FAIL;
    }

    if (what == AL_ADD && *str == NUL)
    {
        if (curbuf->b_ffname == NULL)
        {
            return FAIL;
        }
        str = curbuf->b_fname;
        arg_escaped = FALSE;
    }

    if (get_arglist(&new_ga, str, arg_escaped) == FAIL)
    {
        return FAIL;
    }

    if (what == AL_DEL)
    {
        arglist_del_files(&new_ga);
    }
    else
    {
        i = expand_wildcards(new_ga.ga_len, (char_u **)new_ga.ga_data, &exp_count, &exp_files, EW_DIR|EW_FILE|EW_ADDSLASH|EW_NOTFOUND);
        ga_clear(&new_ga);
        if (i == FAIL || exp_count == 0)
        {
            emsg(_(e_no_match));
            return FAIL;
        }

        if (what == AL_ADD)
        {
            alist_add_list(exp_count, exp_files, after, will_edit);
            vim_free(exp_files);
        }
        else
        {
            alist_set( (curwin)->w_alist , exp_count, exp_files, will_edit, NULL, 0);
        }
    }

    alist_check_arg_idx();

    return OK;
}

    static void
set_arglist(char_u *str)
{
    do_arglist(str, AL_SET, 0, TRUE);
}

    static int
editing_arg_idx(win_T *win)
{
    return !(win->w_arg_idx >=  ( (win)->w_alist ->al_ga.ga_len)  || (win->w_buffer->b_fnum !=  ((aentry_T *) (win)->w_alist ->al_ga.ga_data) [win->w_arg_idx].ae_fnum && (win->w_buffer->b_ffname == NULL || !(fullpathcmp(alist_name(& ((aentry_T *) (win)->w_alist ->al_ga.ga_data) [win->w_arg_idx]), win->w_buffer->b_ffname, TRUE, TRUE) & FPC_SAME))));
}

    static void
check_arg_idx(win_T *win)
{
    if ( ( (win)->w_alist ->al_ga.ga_len)  > 1 && !editing_arg_idx(win))
    {
        win->w_arg_idx_invalid = true;
        if (win->w_arg_idx !=  ( (win)->w_alist ->al_ga.ga_len)  - 1 && arg_had_last == FALSE &&  (win)->w_alist  == &global_alist &&  (global_alist.al_ga.ga_len)  > 0 && win->w_arg_idx <  (global_alist.al_ga.ga_len)  && (win->w_buffer->b_fnum ==  ((aentry_T *)global_alist.al_ga.ga_data) [ (global_alist.al_ga.ga_len)  - 1].ae_fnum || (win->w_buffer->b_ffname != NULL && (fullpathcmp(alist_name(& ((aentry_T *)global_alist.al_ga.ga_data) [ (global_alist.al_ga.ga_len)  - 1]), win->w_buffer->b_ffname, TRUE, TRUE) & FPC_SAME))))
        {
            arg_had_last = TRUE;
        }
    }
    else
    {
        win->w_arg_idx_invalid = false;
        if (win->w_arg_idx ==  ( (win)->w_alist ->al_ga.ga_len)  - 1 && win->w_alist == &global_alist)
        {
            arg_had_last = TRUE;
        }
    }
}

    static void
ex_args(exarg_T *eap)
{
    int         i;

    if (eap->cmdidx != CMD_args)
    {
        if (check_arglist_locked() == FAIL)
        {
            return;
        }
        alist_unlink( (curwin)->w_alist );
        if (eap->cmdidx == CMD_argglobal)
        {
             (curwin)->w_alist  = &global_alist;
        }
        else
        {
            alist_new();
        }
    }

    if (*eap->arg != NUL)
    {
        if (check_arglist_locked() == FAIL)
        {
            return;
        }
        ex_next(eap);
        return;
    }

    if (eap->cmdidx == CMD_args)
    {
        char_u **items;

        if ( ( (curwin)->w_alist ->al_ga.ga_len)  <= 0)
        {
            return;
        }

        items =  (char_u * *)alloc(sizeof(char_u *) * ( ( (curwin)->w_alist ->al_ga.ga_len) )) ;
        if (items == NULL)
        {
            return;
        }

        gotocmdline(TRUE);

        for (i = 0; i <  ( (curwin)->w_alist ->al_ga.ga_len) ; ++i)
        {
            items[i] = alist_name(& ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [i]);
        }
        list_in_columns(items,  ( (curwin)->w_alist ->al_ga.ga_len) , curwin->w_arg_idx);
        vim_free(items);

        return;
    }

    if (eap->cmdidx == CMD_arglocal)
    {
        garray_T        *gap = &curwin->w_alist->al_ga;

        if (  __builtin_expect(((((gap)->ga_maxlen - (gap)->ga_len < ( (global_alist.al_ga.ga_len) )) ? ga_grow_inner((gap), ( (global_alist.al_ga.ga_len) )) : OK) == FAIL), 0)  )
        {
            return;
        }

        for (i = 0; i <  (global_alist.al_ga.ga_len) ; ++i)
        {
            if ( ((aentry_T *)global_alist.al_ga.ga_data) [i].ae_fname != NULL)
            {
                 ((aentry_T *)((curwin->w_alist)->al_ga.ga_data)) [gap->ga_len].ae_fname =
                    vim_strsave( ((aentry_T *)global_alist.al_ga.ga_data) [i].ae_fname);
                 ((aentry_T *)((curwin->w_alist)->al_ga.ga_data)) [gap->ga_len].ae_fnum =
                     ((aentry_T *)global_alist.al_ga.ga_data) [i].ae_fnum;
                ++gap->ga_len;
            }
        }
    }
}

    static void
ex_previous(exarg_T *eap)
{
    if (curwin->w_arg_idx - (int)eap->line2 >=  ( (curwin)->w_alist ->al_ga.ga_len) )
    {
        do_argfile(eap,  ( (curwin)->w_alist ->al_ga.ga_len)  - 1);
    }
    else
    {
        do_argfile(eap, curwin->w_arg_idx - (int)eap->line2);
    }
}

    static void
ex_rewind(exarg_T *eap)
{
    do_argfile(eap, 0);
}

    static void
ex_last(exarg_T *eap)
{
    do_argfile(eap,  ( (curwin)->w_alist ->al_ga.ga_len)  - 1);
}

    static void
ex_argument(exarg_T *eap)
{
    int         i;

    if (eap->addr_count > 0)
    {
        i = eap->line2 - 1;
    }
    else
    {
        i = curwin->w_arg_idx;
    }
    do_argfile(eap, i);
}

    static void
do_argfile(exarg_T *eap, int argn)
{
    int         other;
    char_u      *p;
    int         old_arg_idx = curwin->w_arg_idx;
    int is_split_cmd = *eap->cmd == 's';

    if (ERROR_IF_ANY_POPUP_WINDOW)
    {
        return;
    }
    if (argn < 0 || argn >=  ( (curwin)->w_alist ->al_ga.ga_len) )
    {
        if ( ( (curwin)->w_alist ->al_ga.ga_len)  <= 1)
        {
            emsg(_(e_there_is_only_one_file_to_edit));
        }
        else if (argn < 0)
        {
            emsg(_(e_cannot_go_before_first_file));
        }
        else
        {
            emsg(_(e_cannot_go_beyond_last_file));
        }

        return;
    }

    if (!is_split_cmd && (& ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [argn])->ae_fnum != curbuf->b_fnum && !check_can_set_curbuf_forceit(eap->forceit))
    {
        return;
    }

    setpcmark();

    if (is_split_cmd || cmdmod.cmod_tab != 0)
    {
        if (win_split(0, 0) == FAIL)
        {
            return;
        }
         (curwin)-> w_onebuf_opt.wo_scb  = FALSE;
         (curwin)-> w_onebuf_opt.wo_crb  = FALSE;
    }
    else
    {
        other = TRUE;
        if (buf_hide(curbuf))
        {
            p = fix_fname(alist_name(& ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [argn]));
            other = otherfile(p);
            vim_free(p);
        }
        if ((!buf_hide(curbuf) || !other) && check_changed(curbuf, CCGD_AW | (other ? 0 : CCGD_MULTWIN) | (eap->forceit ? CCGD_FORCEIT : 0) | CCGD_EXCMD))
        {
            return;
        }
    }

    curwin->w_arg_idx = argn;
    if (argn ==  ( (curwin)->w_alist ->al_ga.ga_len)  - 1 && curwin->w_alist == &global_alist)
    {
        arg_had_last = TRUE;
    }

    if (do_ecmd(0, alist_name(& ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [curwin->w_arg_idx]), NULL, eap,  ((linenr_T)-1) , (buf_hide(curwin->w_buffer) ? ECMD_HIDE : 0) + (eap->forceit ? ECMD_FORCEIT : 0), curwin) == FAIL)
    {
        curwin->w_arg_idx = old_arg_idx;
    }
    else if (eap->cmdidx != CMD_argdo)
    {
        setmark('\'');
    }
}

    static void
ex_next(exarg_T *eap)
{
    int         i;

    if (       buf_hide(curbuf) || eap->cmdidx == CMD_snext || !check_changed(curbuf, CCGD_AW | (eap->forceit ? CCGD_FORCEIT : 0) | CCGD_EXCMD))
    {
        if (*eap->arg != NUL)
        {
            if (do_arglist(eap->arg, AL_SET, 0, TRUE) == FAIL)
            {
                return;
            }
            i = 0;
        }
        else
        {
            i = curwin->w_arg_idx + (int)eap->line2;
        }
        do_argfile(eap, i);
    }
}

    static void
ex_argdedupe(exarg_T *eap  __attribute__((unused)) )
{
    int i;
    int j;

    for (i = 0; i <  ( (curwin)->w_alist ->al_ga.ga_len) ; ++i)
    {
        char_u *firstFullname = FullName_save( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [i].ae_fname, FALSE);
        if (firstFullname == NULL)
        {
            return;
        }

        for (j = i + 1; j <  ( (curwin)->w_alist ->al_ga.ga_len) ; ++j)
        {
            char_u *secondFullname = FullName_save( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [j].ae_fname, FALSE);
            if (secondFullname == NULL)
            {
                break;
            }
            int areNamesDuplicate =
                                   vim_fnamecmp((char_u *)(firstFullname), (char_u *)(secondFullname))  == 0;
            vim_free(secondFullname);

            if (areNamesDuplicate)
            {
                vim_free( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [j].ae_fname);
                 memmove((char *)( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data)  + j), (char *)( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data)  + j + 1), ( ( (curwin)->w_alist ->al_ga.ga_len)  - j - 1) * sizeof(aentry_T)) ;
                -- ( (curwin)->w_alist ->al_ga.ga_len) ;

                if (curwin->w_arg_idx == j)
                {
                    curwin->w_arg_idx = i;
                }
                else if (curwin->w_arg_idx > j)
                {
                    --curwin->w_arg_idx;
                }

                --j;
            }
        }

        vim_free(firstFullname);
    }
}

    static void
ex_argedit(exarg_T *eap)
{
    int i = eap->addr_count ? (int)eap->line2 : curwin->w_arg_idx + 1;
    int curbuf_is_reusable = curbuf_reusable();

    if (do_arglist(eap->arg, AL_ADD, i, TRUE) == FAIL)
    {
        return;
    }
    maketitle();

    if (curwin->w_arg_idx == 0 && (curbuf->b_ml.ml_flags & ML_EMPTY) && (curbuf->b_ffname == NULL || curbuf_is_reusable))
    {
        i = 0;
    }
    if (i <  ( (curwin)->w_alist ->al_ga.ga_len) )
    {
        do_argfile(eap, i);
    }
}

    static void
ex_argadd(exarg_T *eap)
{
    do_arglist(eap->arg, AL_ADD, eap->addr_count > 0 ? (int)eap->line2 : curwin->w_arg_idx + 1, FALSE);
    maketitle();
}

    static void
ex_argdelete(exarg_T *eap)
{
    int         i;
    int         n;

    if (check_arglist_locked() == FAIL)
    {
        return;
    }

    if (eap->addr_count > 0 || *eap->arg == NUL)
    {
        if (eap->addr_count == 0)
        {
            if (curwin->w_arg_idx >=  ( (curwin)->w_alist ->al_ga.ga_len) )
            {
                emsg(_(e_no_argument_to_delete));
                return;
            }
            eap->line1 = eap->line2 = curwin->w_arg_idx + 1;
        }
        else if (eap->line2 >  ( (curwin)->w_alist ->al_ga.ga_len) )
        {
            eap->line2 =  ( (curwin)->w_alist ->al_ga.ga_len) ;
        }
        n = eap->line2 - eap->line1 + 1;
        if (*eap->arg != NUL)
        {
            emsg(_(e_invalid_argument));
            return;
        }
        if (n <= 0)
        {
            if (eap->line1 != 1 || eap->line2 != 0)
            {
                emsg(_(e_invalid_range));
            }
            return;
        }

        for (i = eap->line1; i <= eap->line2; ++i)
        {
            vim_free( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [i - 1].ae_fname);
        }
         memmove((char *)( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data)  + eap->line1 - 1), (char *)( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data)  + eap->line2), (size_t)(( ( (curwin)->w_alist ->al_ga.ga_len)  - eap->line2) * sizeof(aentry_T))) ;
         ( (curwin)->w_alist ->al_ga.ga_len)  -= n;
        if (curwin->w_arg_idx >= eap->line2)
        {
            curwin->w_arg_idx -= n;
        }
        else if (curwin->w_arg_idx > eap->line1)
        {
            curwin->w_arg_idx = eap->line1;
        }
    }
    else
    {
        do_arglist(eap->arg, AL_DEL, 0, FALSE);
    }

    if ( ( (curwin)->w_alist ->al_ga.ga_len)  == 0)
    {
        curwin->w_arg_idx = 0;
    }
    else if (curwin->w_arg_idx >=  ( (curwin)->w_alist ->al_ga.ga_len) )
    {
        curwin->w_arg_idx =  ( (curwin)->w_alist ->al_ga.ga_len)  - 1;
    }

    maketitle();
}

    static char_u *
get_arglist_name(expand_T *xp  __attribute__((unused)) , int idx)
{
    if (idx >=  ( (curwin)->w_alist ->al_ga.ga_len) )
    {
        return NULL;
    }

    return alist_name(& ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [idx]);
}

    static char_u *
alist_name(aentry_T *aep)
{
    buf_T       *bp;

    bp = buflist_findnr(aep->ae_fnum);
    if (bp == NULL || bp->b_fname == NULL)
    {
        return aep->ae_fname;
    }
    return bp->b_fname;
}

typedef struct {
    alist_T     *alist;
    int         had_tab;
    int         keep_tabs;
    int         forceit;

    int         use_firstwin;
    char_u      *opened;
    int         opened_len;
    win_T       *new_curwin;
    tabpage_T   *new_curtab;
} arg_all_state_T;

    static void
arg_all_close_unused_windows(arg_all_state_T *aall)
{
    win_T       *wp;
    win_T       *wpnext;
    tabpage_T   *tpnext;
    buf_T       *buf;
    int         i;
    win_T       *old_curwin;
    tabpage_T   *old_curtab;

    old_curwin = curwin;
    old_curtab = curtab;

    if (aall->had_tab > 0)
    {
        goto_tabpage_tp(first_tabpage, TRUE, TRUE);
    }

    tabpage_move_disallowed++;
    for (;;)
    {
        tpnext = curtab->tp_next;
        for (wp = firstwin; wp != NULL; wp = wpnext)
        {
            wpnext = wp->w_next;
            buf = wp->w_buffer;
            if (buf->b_ffname == NULL || (!aall->keep_tabs && (buf->b_nwindows > 1 || wp->w_width != cmdline_width)))
            {
                i = aall->opened_len;
            }
            else
            {
                for (i = 0; i < aall->opened_len; ++i)
                {
                    if (i < aall->alist->al_ga.ga_len && ( ((aentry_T *)((aall->alist)->al_ga.ga_data)) [i].ae_fnum == buf->b_fnum || fullpathcmp(alist_name(& ((aentry_T *)((aall->alist)->al_ga.ga_data)) [i]), buf->b_ffname, TRUE, TRUE) & FPC_SAME))
                    {
                        int weight = 1;

                        if (old_curtab == curtab)
                        {
                            ++weight;
                            if (old_curwin == wp)
                            {
                                ++weight;
                            }
                        }

                        if (weight > (int)aall->opened[i])
                        {
                            aall->opened[i] = (char_u)weight;
                            if (i == 0)
                            {
                                if (aall->new_curwin != NULL)
                                {
                                    aall->new_curwin->w_arg_idx =
                                                              aall->opened_len;
                                }
                                aall->new_curwin = wp;
                                aall->new_curtab = curtab;
                            }
                        }
                        else if (aall->keep_tabs)
                        {
                            i = aall->opened_len;
                        }

                        if (wp->w_alist != aall->alist)
                        {
                            alist_unlink(wp->w_alist);
                            wp->w_alist = aall->alist;
                            ++wp->w_alist->al_refcount;
                        }
                        break;
                    }
                }
            }
            wp->w_arg_idx = i;

            if (i == aall->opened_len && !aall->keep_tabs)
            {
                if (buf_hide(buf) || aall->forceit || buf->b_nwindows > 1 || !bufIsChanged(buf))
                {
                    if (!buf_hide(buf) && buf->b_nwindows <= 1 && bufIsChanged(buf))
                    {
                        bufref_T    bufref;

                        set_bufref(&bufref, buf);

                        (void)autowrite(buf, FALSE);

                        if (!win_valid(wp) || !bufref_valid(&bufref))
                        {
                            wpnext = firstwin;
                            continue;
                        }
                    }
                    if ( (firstwin == lastwin)  && (first_tabpage->tp_next == NULL || !aall->had_tab))
                    {
                        aall->use_firstwin = TRUE;
                    }
                    else
                    {
                        win_close(wp, !buf_hide(buf) && !bufIsChanged(buf));

                        if (!win_valid(wpnext))
                        {
                            wpnext = firstwin;
                        }
                    }
                }
            }
        }

        if (aall->had_tab == 0 || tpnext == NULL)
        {
            break;
        }

        if (!valid_tabpage(tpnext))
        {
            tpnext = first_tabpage;
        }

        goto_tabpage_tp(tpnext, TRUE, TRUE);
    }
    tabpage_move_disallowed--;
}

    static void
arg_all_open_windows(arg_all_state_T *aall, int count)
{
    win_T       *wp;
    int         tab_drop_empty_window = FALSE;
    int         i;
    int         split_ret = OK;
    int         p_ea_save;

    if (aall->keep_tabs &&  (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL)  && curbuf->b_nwindows == 1 && curbuf->b_ffname == NULL && !curbuf->b_changed)
    {
        aall->use_firstwin = TRUE;
        tab_drop_empty_window = TRUE;
    }

    for (i = 0; i < count && !got_int; ++i)
    {
        if (aall->alist == &global_alist && i == global_alist.al_ga.ga_len - 1)
        {
            arg_had_last = TRUE;
        }
        if (aall->opened[i] > 0)
        {
            if (curwin->w_arg_idx != i)
            {
                 for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
                {
                    if (wp->w_arg_idx == i)
                    {
                        if (aall->keep_tabs)
                        {
                            aall->new_curwin = wp;
                            aall->new_curtab = curtab;
                        }
                        else if (wp->w_frame->fr_parent != curwin->w_frame->fr_parent)
                        {
                            emsg(_(e_window_layout_changed_unexpectedly));
                            i = count;
                            break;
                        }
                        else
                        {
                            win_move_after(wp, curwin);
                        }
                        break;
                    }
                }
            }
        }
        else if (split_ret == OK)
        {
            if (tab_drop_empty_window && i == count - 1)
            {
                --autocmd_no_enter;
            }
            if (!aall->use_firstwin)
            {
                p_ea_save = p_ea;
                p_ea = TRUE;
                split_ret = win_split(0, WSP_ROOM | WSP_BELOW);
                p_ea = p_ea_save;
                if (split_ret == FAIL)
                {
                    continue;
                }
            }
            else
            {
                --autocmd_no_leave;
            }

            curwin->w_arg_idx = i;
            if (i == 0)
            {
                aall->new_curwin = curwin;
                aall->new_curtab = curtab;
            }
            (void)do_ecmd(0, alist_name(& ((aentry_T *)((aall->alist)->al_ga.ga_data)) [i]), NULL, NULL,  (linenr_T)1 , ((buf_hide(curwin->w_buffer) || bufIsChanged(curwin->w_buffer)) ? ECMD_HIDE : 0) + ECMD_OLDBUF, curwin);
            if (tab_drop_empty_window && i == count - 1)
            {
                ++autocmd_no_enter;
            }
            if (aall->use_firstwin)
            {
                ++autocmd_no_leave;
            }
            aall->use_firstwin = FALSE;
        }
        ui_breakcheck();

        if (aall->had_tab > 0 && tabpage_index(NULL) <= p_tpm)
        {
            cmdmod.cmod_tab = 9999;
        }
    }
}

    static void
do_arg_all(int count, int forceit, int keep_tabs)
{
    arg_all_state_T     aall;
    win_T               *last_curwin;
    tabpage_T           *last_curtab;
    int                 prev_arglist_locked = arglist_locked;

    if (cmdwin_type != 0)
    {
        emsg(_(e_invalid_in_cmdline_window));
        return;
    }
    if ( ( (curwin)->w_alist ->al_ga.ga_len)  <= 0)
    {
        return;
    }
    setpcmark();

    aall.use_firstwin = FALSE;
    aall.had_tab = cmdmod.cmod_tab;
    aall.new_curwin = NULL;
    aall.new_curtab = NULL;
    aall.forceit = forceit;
    aall.keep_tabs = keep_tabs;
    aall.opened_len =  ( (curwin)->w_alist ->al_ga.ga_len) ;
    aall.opened = alloc_clear(aall.opened_len);
    if (aall.opened == NULL)
    {
        return;
    }

    aall.alist = curwin->w_alist;
    ++aall.alist->al_refcount;
    arglist_locked = TRUE;

    tabpage_T *new_lu_tp = curtab;

    reset_VIsual_and_resel();

    arg_all_close_unused_windows(&aall);

    if (count > aall.opened_len || count <= 0)
    {
        count = aall.opened_len;
    }

    ++autocmd_no_enter;
    ++autocmd_no_leave;
    last_curwin = curwin;
    last_curtab = curtab;
    win_enter(lastwin, FALSE);

    arg_all_open_windows(&aall, count);

    alist_unlink(aall.alist);
    arglist_locked = prev_arglist_locked;

    --autocmd_no_enter;

    if (last_curtab != aall.new_curtab)
    {
        if (valid_tabpage(last_curtab))
        {
            goto_tabpage_tp(last_curtab, TRUE, TRUE);
        }
        if (win_valid(last_curwin))
        {
            win_enter(last_curwin, FALSE);
        }
    }
    if (valid_tabpage(aall.new_curtab))
    {
        goto_tabpage_tp(aall.new_curtab, TRUE, TRUE);
    }

    if (valid_tabpage(new_lu_tp))
    {
        lastused_tabpage = new_lu_tp;
    }

    if (win_valid(aall.new_curwin))
    {
        win_enter(aall.new_curwin, FALSE);
    }

    --autocmd_no_leave;
    vim_free(aall.opened);
}

    static void
ex_all(exarg_T *eap)
{
    if (eap->addr_count == 0)
    {
        eap->line2 = 9999;
    }
    do_arg_all((int)eap->line2, eap->forceit, eap->cmdidx == CMD_drop);
}

    static char_u *
arg_all(void)
{
    int         len;
    int         idx;
    char_u      *retval = NULL;
    char_u      *p;

    for (;;)
    {
        len = 0;
        for (idx = 0; idx <  ( (curwin)->w_alist ->al_ga.ga_len) ; ++idx)
        {
            p = alist_name(& ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [idx]);
            if (p == NULL)
            {
                continue;
            }
            if (len > 0)
            {
                if (retval != NULL)
                {
                    retval[len] = ' ';
                }
                ++len;
            }
            for ( ; *p != NUL; ++p)
            {
                if (*p == ' ' || *p == '\\' || *p == '`')
                {
                    if (retval != NULL)
                    {
                        retval[len] = '\\';
                    }
                    ++len;
                }
                if (retval != NULL)
                {
                    retval[len] = *p;
                }
                ++len;
            }
        }

        if (retval != NULL)
        {
            retval[len] = NUL;
            break;
        }

        retval = alloc(len + 1);
        if (retval == NULL)
        {
            break;
        }
    }

    return retval;
}

