static int      last_group;
static int      autocmd_blocked = 0;

    static char_u *
get_deleted_augroup(void)
{
    if (deleted_augroup == NULL)
    {
        deleted_augroup = (char_u *)_("--Deleted--");
    }
    return deleted_augroup;
}

    static void
show_autocmd(AutoPat *ap, event_T event)
{
    AutoCmd *ac;

    if (got_int)
    {
        return;
    }
    if (ap->pat == NULL)
    {
        return;
    }

    ++autocmd_busy;

    msg_putchar('\n');
    if (got_int)
    {
        goto theend;
    }
    if (event != last_event || ap->group != last_group)
    {
        string_T    *event_name;

        if (ap->group !=  (-1) )
        {
            if ( (((char_u **)augroups.ga_data)[ap->group])  == NULL)
            {
                msg_puts_attr((char *)get_deleted_augroup(),  highlight_attr[(int)(HLF_E)] );
            }
            else
            {
                msg_puts_attr((char *) (((char_u **)augroups.ga_data)[ap->group]) ,  highlight_attr[(int)(HLF_T)] );
            }
            msg_puts("  ");
        }
        event_name = event_nr2name(event);
        msg_puts_attr((char *)event_name->string,  highlight_attr[(int)(HLF_T)] );
        last_event = event;
        last_group = ap->group;
        msg_putchar('\n');
        if (got_int)
        {
            goto theend;
        }
    }

    if (ap->pat == NULL)
    {
        goto theend;
    }

    msg_col = 4;
    msg_outtrans(ap->pat);

    for (ac = ap->cmds; ac != NULL; ac = ac->next)
    {
        if (ac->cmd == NULL)
        {
            continue;
        }

        if (msg_col >= 14)
        {
            msg_putchar('\n');
        }
        msg_col = 14;
        if (got_int)
        {
            goto theend;
        }
        msg_outtrans(ac->cmd);
        if (got_int)
        {
            goto theend;
        }
        if (ac->next != NULL)
        {
            msg_putchar('\n');
            if (got_int)
            {
                goto theend;
            }
        }
    }

theend:
    --autocmd_busy;
}

    static void
au_remove_pat(AutoPat *ap)
{
     vim_free(ap->pat);
     (ap->pat) = NULL;
    ap->buflocal_nr = -1;
    au_need_clean = TRUE;
}

    static void
au_remove_cmds(AutoPat *ap)
{
    AutoCmd *ac;

    for (ac = ap->cmds; ac != NULL; ac = ac->next)
    {
         vim_free(ac->cmd);
         (ac->cmd) = NULL;
    }
    au_need_clean = TRUE;
}

static void au_del_cmd(AutoCmd *ac)
{
     vim_free(ac->cmd);
     (ac->cmd) = NULL;
    au_need_clean = TRUE;
}

    static void
au_cleanup(void)
{
    AutoPat *ap;
    AutoPat **prev_ap;
    AutoCmd *ac;
    AutoCmd **prev_ac;
    event_T     event;

    if (autocmd_busy || !au_need_clean)
    {
        return;
    }

    for (event = (event_T)0; (int)event < NUM_EVENTS; event = (event_T)((int)event + 1))
    {
        prev_ap = &(first_autopat[(int)event]);
        for (ap = *prev_ap; ap != NULL; ap = *prev_ap)
        {
            int has_cmd = FALSE;

            prev_ac = &(ap->cmds);
            for (ac = *prev_ac; ac != NULL; ac = *prev_ac)
            {
                if (ap->pat == NULL || ac->cmd == NULL)
                {
                    *prev_ac = ac->next;
                    vim_free(ac->cmd);
                    vim_free(ac);
                }
                else
                {
                    has_cmd = TRUE;
                    prev_ac = &(ac->next);
                }
            }

            if (ap->pat != NULL && !has_cmd)
            {
                au_remove_pat(ap);
            }

            if (ap->pat == NULL)
            {
                if (ap->next == NULL)
                {
                    if (prev_ap == &(first_autopat[(int)event]))
                    {
                        last_autopat[(int)event] = NULL;
                    }
                    else
                    {
                        last_autopat[(int)event] = (AutoPat *)prev_ap;
                    }
                }
                *prev_ap = ap->next;
                vim_regfree(ap->reg_prog);
                vim_free(ap);
            }
            else
            {
                prev_ap = &(ap->next);
            }
        }
    }

    au_need_clean = FALSE;
}

    static void
aubuflocal_remove(buf_T *buf)
{
    AutoPat         *ap;
    event_T         event;
    AutoPatCmd_T    *apc;

    for (apc = active_apc_list; apc; apc = apc->next)
    {
        if (buf->b_fnum == apc->arg_bufnr)
        {
            apc->arg_bufnr = 0;
        }
    }

    for (event = (event_T)0; (int)event < NUM_EVENTS; event = (event_T)((int)event + 1))
    {
         for ((ap) = first_autopat[(int)(event)]; (ap) != NULL; (ap) = (ap)->next) 
         {
            if (ap->buflocal_nr == buf->b_fnum)
            {
                au_remove_pat(ap);
                if (p_verbose >= 6)
                {
                    string_T    *event_name;

                    verbose_enter();
                    event_name = event_nr2name(event);
                    smsg(_("auto-removing autocommand: %s <buffer=%d>"), event_name->string, buf->b_fnum);
                    verbose_leave();
                }
            }
         }
    }
    au_cleanup();
}

    static int
au_new_group(char_u *name)
{
    int         i;

    i = au_find_group(name);
    if (i !=  (-2) )
    {
        return i;
    }

    for (i = 0; i < augroups.ga_len; ++i)
    {
        if ( (((char_u **)augroups.ga_data)[i])  == NULL)
        {
            break;
        }
    }
    if (i == augroups.ga_len && ga_grow(&augroups, 1) == FAIL)
    {
        return  (-2) ;
    }

     (((char_u **)augroups.ga_data)[i])  = vim_strsave(name);
    if ( (((char_u **)augroups.ga_data)[i])  == NULL)
    {
        return  (-2) ;
    }
    if (i == augroups.ga_len)
    {
        ++augroups.ga_len;
    }

    return i;
}

    static void
au_del_group(char_u *name)
{
    int         i;
    event_T     event;
    AutoPat     *ap;
    int         in_use = FALSE;

    i = au_find_group(name);
    if (i ==  (-2) )
    {
        semsg(_(e_no_such_group_str), name);
        return;
    }
    if (i == current_augroup)
    {
        emsg(_(e_cannot_delete_current_group));
        return;
    }

    for (event = (event_T)0; (int)event < NUM_EVENTS; event = (event_T)((int)event + 1))
    {
         for ((ap) = first_autopat[(int)(event)]; (ap) != NULL; (ap) = (ap)->next) 
         {
            if (ap->group == i && ap->pat != NULL)
            {
                give_warning((char_u *)_("W19: Deleting augroup that is still in use"), TRUE);
                in_use = TRUE;
                event = NUM_EVENTS;
                break;
            }
         }
    }
    vim_free( (((char_u **)augroups.ga_data)[i]) );
    if (in_use)
    {
         (((char_u **)augroups.ga_data)[i])  = get_deleted_augroup();
    }
    else
    {
         (((char_u **)augroups.ga_data)[i])  = NULL;
    }
}

    static int
au_find_group(char_u *name)
{
    int     i;

    for (i = 0; i < augroups.ga_len; ++i)
    {
        if ( (((char_u **)augroups.ga_data)[i])  != NULL &&  (((char_u **)augroups.ga_data)[i])  != get_deleted_augroup() &&  strcmp((char *)( (((char_u **)augroups.ga_data)[i]) ), (char *)(name))  == 0)
        {
            return i;
        }
    }
    return  (-2) ;
}

    static int
au_has_group(char_u *name)
{
    return au_find_group(name) !=  (-2) ;
}

    static void
do_augroup(char_u *arg, int del_group)
{
    int     i;

    if (del_group)
    {
        if (*arg == NUL)
        {
            emsg(_(e_argument_required));
        }
        else
        {
            au_del_group(arg);
        }
    }
    else if ( strcasecmp((char *)(arg), (char *)("end"))  == 0)
    {
        current_augroup =  (-1) ;
    }
    else if (*arg)
    {
        i = au_new_group(arg);
        if (i !=  (-2) )
        {
            current_augroup = i;
        }
    }
    else
    {
        msg_start();
        for (i = 0; i < augroups.ga_len; ++i)
        {
            if ( (((char_u **)augroups.ga_data)[i])  != NULL)
            {
                msg_puts((char *) (((char_u **)augroups.ga_data)[i]) );
                msg_puts("  ");
            }
        }
        msg_clr_eos();
        msg_end();
    }
}

    static void
autocmd_init(void)
{
      memset((&(aucmd_win)), (0), (sizeof(aucmd_win)))  ;
}

    static int
is_aucmd_win(win_T *win)
{
    for (int i = 0; i < AUCMD_WIN_COUNT; ++i)
    {
        if (aucmd_win[i].auc_win_used && aucmd_win[i].auc_win == win)
        {
            return TRUE;
        }
    }
    return FALSE;
}

    static event_T
event_name2nr(char_u *start, char_u **end)
{
    char_u      *p;
    keyvalue_T target;
    keyvalue_T *entry;
    static keyvalue_T *bufnewfile = &event_tab[BUFNEWFILE_INDEX];
    static keyvalue_T *bufread = &event_tab[BUFREAD_INDEX];

    for (p = start; *p && ! ((*p) == ' ' || (*p) == '\t')  && *p != ',' && *p != '|'; ++p)
    {
        ;
    }

    target.key = 0;
    target.value.string = start;
    target.value.length = (size_t)(p - start);

    if (cmp_keyvalue_value_ni(&target, bufnewfile) == 0)
    {
        entry = bufnewfile;
    }
    else if (cmp_keyvalue_value_ni(&target, bufread) == 0)
    {
        entry = bufread;
    }
    else
    {
        entry = (keyvalue_T *)bsearch(&target, &event_tab, NUM_EVENTS, sizeof(event_tab[0]), cmp_keyvalue_value_ni);
    }

    if (*p == ',')
    {
        ++p;
    }
    *end = p;

    return (entry == NULL) ? NUM_EVENTS : (event_T)abs(entry->key);
}

    static string_T *
event_nr2name(event_T event)
{
    int     i;
    enum {CACHE_SIZE = 12};
    static int cache_tab[CACHE_SIZE];
    static int cache_last_index = -1;
    static string_T unknown =  {(char_u *)("Unknown"),  (sizeof("Unknown" "") - 1) } ;

    if (cache_last_index < 0)
    {
        for (i = 0; i < CACHE_SIZE; ++i)
        {
            cache_tab[i] = -1;
        }
        cache_last_index = CACHE_SIZE - 1;
    }

    for (i = cache_last_index; cache_tab[i] >= 0; )
    {
        if ((event_T)abs(event_tab[cache_tab[i]].key) == event)
        {
            return &event_tab[cache_tab[i]].value;
        }

        if (i == 0)
        {
            i = CACHE_SIZE - 1;
        }
        else
        {
            --i;
        }

        if (i == cache_last_index)
        {
            break;
        }
    }

    for (i = 0; i < NUM_EVENTS; ++i)
    {
        if ((event_T)abs(event_tab[i].key) == event)
        {
            if (cache_last_index == CACHE_SIZE - 1)
            {
                cache_last_index = 0;
            }
            else
            {
                ++cache_last_index;
            }
            cache_tab[cache_last_index] = i;
            return &event_tab[i].value;
        }
    }

    return &unknown;
}

    static char_u *
find_end_event(char_u  *arg, int     have_group)
{
    char_u  *pat;
    char_u  *p;

    if (*arg == '*')
    {
        if (arg[1] && ! ((arg[1]) == ' ' || (arg[1]) == '\t') )
        {
            semsg(_(e_illegal_character_after_star_str), arg);
            return NULL;
        }
        pat = arg + 1;
    }
    else
    {
        for (pat = arg; *pat && *pat != '|' && ! ((*pat) == ' ' || (*pat) == '\t') ; pat = p)
        {
            if ((int)event_name2nr(pat, &p) >= NUM_EVENTS)
            {
                if (have_group)
                {
                    semsg(_(e_no_such_event_str), pat);
                }
                else
                {
                    semsg(_(e_no_such_group_or_event_str), pat);
                }
                return NULL;
            }
        }
    }
    return pat;
}

    static char_u *
au_find_cmd_arg(char_u *arg)
{
    char_u      *pat;
    char_u      *cmd;
    int         group;

    if (*arg == '|')
    {
        return NULL;
    }

    ++emsg_off;
    group = au_get_grouparg(&arg);
    pat = group ==  (-2) 
                          ? NULL : find_end_event(arg, group !=  (-3) );
    --emsg_off;
    if (pat == NULL)
    {
        return NULL;
    }

    pat = skipwhite(pat);
    if (*pat == NUL || *pat == '|')
    {
        return NULL;
    }

    cmd = pat;
    while (*cmd != NUL && (! ((*cmd) == ' ' || (*cmd) == '\t')  || (cmd > pat && *(cmd - 1) == '\\')))
    {
        ++cmd;
    }
    cmd = skipwhite(cmd);

    for (int i = 0; i < 2; ++i)
    {
        if ( strncmp((char *)(cmd), (char *)("++once"), (6))  == 0 &&  ((cmd[6]) == ' ' || (cmd[6]) == '\t') )
        {
            cmd = skipwhite(cmd + 6);
        }
        if ( strncmp((char *)(cmd), (char *)("++nested"), (8))  == 0 &&  ((cmd[8]) == ' ' || (cmd[8]) == '\t') )
        {
            cmd = skipwhite(cmd + 8);
        }
        if (!in_vim9script() &&  strncmp((char *)(cmd), (char *)("nested"), (6))  == 0 &&  ((cmd[6]) == ' ' || (cmd[6]) == '\t') )
        {
            cmd = skipwhite(cmd + 6);
        }
    }

    return *cmd == NUL ? NULL : cmd;
}

    static int
event_ignored(event_T event, char_u *ei)
{
    int ignored = FALSE;
    while (*ei != NUL)
    {
        int unignore = *ei == '-';
        ei += unignore;
        if ( strncasecmp((char *)(ei), (char *)("all"), (3))  == 0 && (ei[3] == NUL || ei[3] == ','))
        {
            ignored = ei == p_ei || (event_tab[event].key <= 0);
            ei += 3 + (ei[3] == ',');
        }
        else if (event_name2nr(ei, &ei) == event)
        {
            if (unignore)
            {
                return FALSE;
            }
            else
            {
                ignored = TRUE;
            }
        }
    }

    return ignored;
}

    static int
check_ei(char_u *ei)
{
    int win = ei != p_ei;

    while (*ei)
    {
        if ( strncasecmp((char *)(ei), (char *)("all"), (3))  == 0 && (ei[3] == NUL || ei[3] == ','))
        {
            ei += 3 + (ei[3] == ',');
        }
        else
        {
            ei += (*ei == '-');
            event_T event = event_name2nr(ei, &ei);
            if (event == NUM_EVENTS || (win && event_tab[event].key > 0))
            {
                return FAIL;
            }
        }
    }

    return OK;
}

    static void
do_autocmd(exarg_T *eap, char_u *arg_in, int forceit)
{
    char_u      *arg = arg_in;
    char_u      *pat;
    char_u      *envpat = NULL;
    char_u      *cmd;
    int         cmd_need_free = FALSE;
    event_T     event;
    char_u      *tofree = NULL;
    int         nested = FALSE;
    int         once = FALSE;
    int         group;
    int         i;
    int         flags = 0;

    if (*arg == '|')
    {
        eap->nextcmd = arg + 1;
        arg = (char_u *)"";
        group =  (-3) ;
    }
    else
    {
        group = au_get_grouparg(&arg);
        if (arg == NULL)
        {
            return;
        }
    }

    pat = find_end_event(arg, group !=  (-3) );
    if (pat == NULL)
    {
        return;
    }

    pat = skipwhite(pat);
    if (*pat == '|')
    {
        eap->nextcmd = pat + 1;
        pat = (char_u *)"";
        cmd = (char_u *)"";
    }
    else
    {
        cmd = pat;
        while (*cmd && (! ((*cmd) == ' ' || (*cmd) == '\t')  || cmd[-1] == '\\'))
        {
            cmd++;
        }
        if (*cmd)
        {
            *cmd++ = NUL;
        }

        if (vim_strchr(pat, '$') != NULL || vim_strchr(pat, '~') != NULL)
        {
            envpat = expand_env_save(pat);
            if (envpat != NULL)
            {
                pat = envpat;
            }
        }

        cmd = skipwhite(cmd);
        for (i = 0; i < 2; i++)
        {
            if (*cmd == NUL)
            {
                continue;
            }

            if ( strncmp((char *)(cmd), (char *)("++once"), (6))  == 0 &&  ((cmd[6]) == ' ' || (cmd[6]) == '\t') )
            {
                if (once)
                {
                    semsg(_(e_duplicate_argument_str), "++once");
                    goto err_exit;
                }
                once = TRUE;
                cmd = skipwhite(cmd + 6);
            }

            if (( strncmp((char *)(cmd), (char *)("++nested"), (8))  == 0 &&  ((cmd[8]) == ' ' || (cmd[8]) == '\t') ))
            {
                if (nested)
                {
                    semsg(_(e_duplicate_argument_str), "++nested");
                    goto err_exit;
                }
                nested = TRUE;
                cmd = skipwhite(cmd + 8);
            }

            if ( strncmp((char *)(cmd), (char *)("nested"), (6))  == 0 &&  ((cmd[6]) == ' ' || (cmd[6]) == '\t') )
            {
                if (in_vim9script())
                {
                    emsg(_(e_invalid_command_nested_did_you_mean_plusplus_nested));
                    goto err_exit;
                }
                if (nested)
                {
                    semsg(_(e_duplicate_argument_str), "nested");
                    goto err_exit;
                }
                nested = TRUE;
                cmd = skipwhite(cmd + 6);
            }
        }

        if (*cmd != NUL)
        {
            if (eap != NULL)
            {
                cmd = may_get_cmd_block(eap, cmd, &tofree, &flags);
            }

            cmd = expand_sfile(cmd);
            if (cmd == NULL)
            {
                goto err_exit;
            }
            cmd_need_free = TRUE;
        }
    }

    if (!forceit && *cmd == NUL)
    {
        msg_puts_title(_("\n--- Autocommands ---"));
    }

    last_event = (event_T)-1;
    last_group =  (-2) ;
    if (*arg == '*' || *arg == NUL || *arg == '|')
    {
        if (*cmd != NUL)
        {
            emsg(_(e_cannot_define_autocommands_for_all_events));
        }
        else
        {
            for (event = (event_T)0; (int)event < NUM_EVENTS; event = (event_T)((int)event + 1))
            {
                if (do_autocmd_event(event, pat, once, nested, cmd, forceit, group, flags) == FAIL)
                {
                    break;
                }
            }
        }
    }
    else
    {
        while (*arg && *arg != '|' && ! ((*arg) == ' ' || (*arg) == '\t') )
        {
            if (do_autocmd_event(event_name2nr(arg, &arg), pat, once, nested, cmd, forceit, group, flags) == FAIL)
            {
                break;
            }
        }
    }

err_exit:
    if (cmd_need_free)
    {
        vim_free(cmd);
    }
    vim_free(tofree);
    vim_free(envpat);
}

    static int
au_get_grouparg(char_u **argp)
{
    char_u      *group_name;
    char_u      *p;
    char_u      *arg = *argp;
    int         group =  (-3) ;

    for (p = arg; *p && ! ((*p) == ' ' || (*p) == '\t')  && *p != '|'; ++p)
    {
        ;
    }
    if (p <= arg)
    {
        return  (-3) ;
    }

    group_name = vim_strnsave(arg, p - arg);
    if (group_name == NULL)
    {
        return  (-2) ;
    }
    group = au_find_group(group_name);
    if (group ==  (-2) )
    {
        group =  (-3) ;
    }
    else
    {
        *argp = skipwhite(p);
    }
    vim_free(group_name);
    return group;
}

    static int
do_autocmd_event(event_T     event, char_u      *pat, int         once, int         nested, char_u      *cmd, int         forceit, int         group, int         flags)
{
    AutoPat     *ap;
    AutoPat     **prev_ap;
    AutoCmd     *ac;
    AutoCmd     **prev_ac;
    int         brace_level;
    char_u      *endpat;
    int         findgroup;
    int         allgroups;
    int         patlen;
    int         is_buflocal;
    int         buflocal_nr;
    char_u      buflocal_pat[25];

    if (group ==  (-3) )
    {
        findgroup = current_augroup;
    }
    else
    {
        findgroup = group;
    }
    allgroups = (group ==  (-3)  && !forceit && *cmd == NUL);

    if (*pat == NUL)
    {
         for ((ap) = first_autopat[(int)(event)]; (ap) != NULL; (ap) = (ap)->next) 
        {
            if (forceit)
            {
                if (ap->group == findgroup)
                {
                    au_remove_pat(ap);
                }
            }
            else if (group ==  (-3)  || ap->group == group)
            {
                show_autocmd(ap, event);
            }
        }
    }

    for ( ; *pat; pat = (*endpat == ',' ? endpat + 1 : endpat))
    {
        brace_level = 0;
        for (endpat = pat; *endpat && (*endpat != ',' || brace_level || (endpat > pat && endpat[-1] == '\\')); ++endpat)
        {
            if (*endpat == '{')
            {
                brace_level++;
            }
            else if (*endpat == '}')
            {
                brace_level--;
            }
        }
        if (pat == endpat)
        {
            continue;
        }
        patlen = (int)(endpat - pat);

        is_buflocal = FALSE;
        buflocal_nr = 0;

        if (patlen >= 8 &&  strncmp((char *)(pat), (char *)("<buffer"), (7))  == 0 && pat[patlen - 1] == '>')
        {
            is_buflocal = TRUE;
            if (patlen == 8)
            {
                buflocal_nr = curbuf->b_fnum;
            }
            else if (patlen > 9 && pat[7] == '=')
            {
                if (patlen == 13 &&  strncasecmp((char *)(pat), (char *)("<buffer=abuf>"), (13))  == 0)
                {
                    buflocal_nr = autocmd_bufnr;
                }
                else if (skipdigits(pat + 8) == pat + patlen - 1)
                {
                    buflocal_nr = atoi((char *)pat + 8);
                }
            }
        }

        if (is_buflocal)
        {
            sprintf((char *)buflocal_pat, "<buffer=%d>", buflocal_nr);
            pat = buflocal_pat;
            patlen = (int) strlen((char *)(buflocal_pat)) ;
        }

        if (!forceit && *cmd != NUL && last_autopat[(int)event] != NULL)
        {
            prev_ap = &last_autopat[(int)event];
        }
        else
        {
            prev_ap = &first_autopat[(int)event];
        }
        while ((ap = *prev_ap) != NULL)
        {
            if (ap->pat != NULL)
            {
                if ((allgroups || ap->group == findgroup) && ap->patlen == patlen &&  strncmp((char *)(pat), (char *)(ap->pat), (patlen))  == 0)
                {
                    if (forceit)
                    {
                        if (*cmd != NUL && ap->next == NULL)
                        {
                            au_remove_cmds(ap);
                            break;
                        }
                        au_remove_pat(ap);
                    }

                    else if (*cmd == NUL)
                    {
                        show_autocmd(ap, event);
                    }

                    else if (ap->next == NULL)
                    {
                        break;
                    }
                }
            }
            prev_ap = &ap->next;
        }

        if (*cmd != NUL)
        {
            if (ap == NULL)
            {
                if (is_buflocal && (buflocal_nr == 0 || buflist_findnr(buflocal_nr) == NULL))
                {
                    semsg(_(e_buffer_nr_invalid_buffer_number), buflocal_nr);
                    return FAIL;
                }

                ap =  (AutoPat *)alloc(sizeof(AutoPat)) ;
                if (ap == NULL)
                {
                    return FAIL;
                }
                ap->pat = vim_strnsave(pat, patlen);
                ap->patlen = patlen;
                if (ap->pat == NULL)
                {
                    vim_free(ap);
                    return FAIL;
                }

                if ((event == EVENT_WINSCROLLED || event == EVENT_WINRESIZED) && !(has_winscrolled() || has_winresized()))
                {
                    tabpage_T *save_curtab = curtab;
                    tabpage_T *tp;
                     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
                    {
                        unuse_tabpage(curtab);
                        use_tabpage(tp);
                        snapshot_windows_scroll_size();
                    }
                    unuse_tabpage(curtab);
                    use_tabpage(save_curtab);
                }

                if (is_buflocal)
                {
                    ap->buflocal_nr = buflocal_nr;
                    ap->reg_prog = NULL;
                }
                else
                {
                    char_u      *reg_pat;

                    ap->buflocal_nr = 0;
                    reg_pat = file_pat_to_reg_pat(pat, endpat, &ap->allow_dirs, TRUE);
                    if (reg_pat != NULL)
                    {
                        ap->reg_prog = vim_regcomp(reg_pat, RE_MAGIC);
                    }
                    vim_free(reg_pat);
                    if (reg_pat == NULL || ap->reg_prog == NULL)
                    {
                        vim_free(ap->pat);
                        vim_free(ap);
                        return FAIL;
                    }
                }
                ap->cmds = NULL;
                *prev_ap = ap;
                last_autopat[(int)event] = ap;
                ap->next = NULL;
                if (group ==  (-3) )
                {
                    ap->group = current_augroup;
                }
                else
                {
                    ap->group = group;
                }
            }

            prev_ac = &(ap->cmds);
            while ((ac = *prev_ac) != NULL)
            {
                prev_ac = &ac->next;
            }
            ac =  (AutoCmd *)alloc(sizeof(AutoCmd)) ;
            if (ac == NULL)
            {
                return FAIL;
            }
            ac->cmd = vim_strsave(cmd);
            ac->script_ctx = current_sctx;
            if (flags & UC_VIM9)
            {
                ac->script_ctx.sc_version = SCRIPT_VERSION_VIM9;
            }
            if (ac->cmd == NULL)
            {
                vim_free(ac);
                return FAIL;
            }
            ac->next = NULL;
            *prev_ac = ac;
            ac->once = once;
            ac->nested = nested;
        }
    }

    au_cleanup();
    return OK;
}

    static int
do_doautocmd(char_u      *arg_start, int         do_msg, int         *did_something)
{
    char_u      *arg = arg_start;
    char_u      *fname;
    int         nothing_done = TRUE;
    int         group;

    if (did_something != NULL)
    {
        *did_something = FALSE;
    }

    group = au_get_grouparg(&arg);
    if (arg == NULL)
    {
        return FAIL;
    }

    if (*arg == '*')
    {
        emsg(_(e_cant_execute_autocommands_for_all_events));
        return FAIL;
    }

    fname = find_end_event(arg, group !=  (-3) );
    if (fname == NULL)
    {
        return FAIL;
    }

    fname = skipwhite(fname);

    while (*arg && !ends_excmd(*arg) && ! ((*arg) == ' ' || (*arg) == '\t') )
    {
        if (apply_autocmds_group(event_name2nr(arg, &arg), fname, NULL, TRUE, group, curbuf, NULL))
        {
            nothing_done = FALSE;
        }
    }

    if (nothing_done && do_msg)
    {
        smsg(_("No matching autocommands: %s"), arg_start);
    }
    if (did_something != NULL)
    {
        *did_something = !nothing_done;
    }

    return OK;
}

    static void
ex_doautoall(exarg_T *eap)
{
    int         retval = OK;
    aco_save_T  aco;
    buf_T       *buf;
    bufref_T    bufref;
    char_u      *arg = eap->arg;
    int         call_do_modelines = check_nomodeline(&arg);
    int         did_aucmd;

     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
    {
        if (buf->b_ml.ml_mfp == NULL || buf == curbuf)
        {
            continue;
        }

        aucmd_prepbuf(&aco, buf);
        if (curbuf != buf)
        {
            retval = FAIL;
            break;
        }

        set_bufref(&bufref, buf);

        retval = do_doautocmd(arg, FALSE, &did_aucmd);

        if (call_do_modelines && did_aucmd)
        {
            do_modelines(is_aucmd_win(curwin) ? OPT_NOWIN : 0);
        }

        aucmd_restbuf(&aco);

        if (retval == FAIL || !bufref_valid(&bufref))
        {
            retval = FAIL;
            break;
        }
    }

    if (retval == OK)
    {
        do_doautocmd(arg, FALSE, &did_aucmd);
        if (call_do_modelines && did_aucmd)
        {
            do_modelines(0);
        }
    }
}

    static int
check_nomodeline(char_u **argp)
{
    if ( strncmp((char *)(*argp), (char *)("<nomodeline>"), (12))  == 0)
    {
        *argp = skipwhite(*argp + 12);
        return FALSE;
    }
    return TRUE;
}

    static void
aucmd_prepbuf(aco_save_T  *aco, buf_T       *buf)
{
    win_T       *win;
    int         save_ea;
    int         same_buffer = buf == curbuf;

    if (same_buffer)
    {
        win = curwin;
    }
    else
    {
         for ((win) = firstwin; (win) != NULL; (win) = (win)->w_next) 
         {
            if (win->w_buffer == buf)
            {
                break;
            }
         }
    }

    win_T *auc_win = NULL;
    int auc_idx = AUCMD_WIN_COUNT;
    if (win == NULL)
    {
        for (auc_idx = 0; auc_idx < AUCMD_WIN_COUNT; ++auc_idx)
        {
            if (!aucmd_win[auc_idx].auc_win_used)
            {
                if (aucmd_win[auc_idx].auc_win == NULL)
                {
                    aucmd_win[auc_idx].auc_win = win_alloc_popup_win();
                }
                auc_win = aucmd_win[auc_idx].auc_win;
                if (auc_win != NULL)
                {
                    aucmd_win[auc_idx].auc_win_used = TRUE;
                }
                break;
            }
        }

        if (auc_win == NULL)
        {
            return;
        }
    }

    aco->save_curwin_id = curwin->w_id;
    aco->save_prevwin_id = prevwin == NULL ? 0 : prevwin->w_id;

    if (win != NULL)
    {
        aco->use_aucmd_win_idx = -1;
        curwin = win;
    }
    else
    {
        aco->use_aucmd_win_idx = auc_idx;

        win_init_popup_win(auc_win, buf);

        aco->tp_localdir = curtab->tp_localdir;
        curtab->tp_localdir = NULL;
        aco->globaldir = globaldir;
        globaldir = NULL;

        block_autocmds();
        make_snapshot(SNAP_AUCMD_IDX);
        save_ea = p_ea;
        p_ea = FALSE;

        (void)win_split_ins(0, WSP_TOP | WSP_FORCE_ROOM, auc_win, 0, NULL);
        win_comp_pos();
        p_ea = save_ea;
        unblock_autocmds();
        curwin = auc_win;
    }
    curbuf = buf;
    aco->new_curwin_id = curwin->w_id;
    set_bufref(&aco->new_curbuf, curbuf);

    aco->save_VIsual_active = VIsual_active;
    if (!same_buffer)
    {
        VIsual_active = FALSE;
    }
}

    static void
aucmd_restbuf(aco_save_T  *aco)
{
    int     dummy;
    win_T   *save_curwin;

    if (aco->use_aucmd_win_idx >= 0)
    {
        win_T *awp = aucmd_win[aco->use_aucmd_win_idx].auc_win;

        block_autocmds();
        if (curwin != awp)
        {
            tabpage_T   *tp;
            win_T       *wp;

             for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
             {
                 for ((wp) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next)
            {
                if (wp == awp)
                {
                    if (tp != curtab)
                    {
                        goto_tabpage_tp(tp, TRUE, TRUE);
                    }
                    win_goto(awp);
                    goto win_found;
                }
            }
             }
        }
win_found:
        --curbuf->b_nwindows;
        (void)winframe_remove(curwin, &dummy, NULL, NULL);
        win_remove(curwin, NULL);

        aucmd_win[aco->use_aucmd_win_idx].auc_win_used = FALSE;
        last_status(FALSE);

        if (!valid_tabpage_win(curtab))
        {
            close_tabpage(curtab);
        }

        restore_snapshot(SNAP_AUCMD_IDX, FALSE);
        win_comp_pos();
        unblock_autocmds();

        save_curwin = win_find_by_id(aco->save_curwin_id);
        if (save_curwin != NULL)
        {
            curwin = save_curwin;
        }
        else
        {
            curwin = firstwin;
        }
        curbuf = curwin->w_buffer;
        prevwin = win_find_by_id(aco->save_prevwin_id);
        if (awp->w_localdir != NULL)
        {
            win_fix_current_dir();
        }
        vim_free(curtab->tp_localdir);
        curtab->tp_localdir = aco->tp_localdir;
        vim_free(globaldir);
        globaldir = aco->globaldir;

        VIsual_active = aco->save_VIsual_active;
        check_cursor();
        if (curwin->w_topline > curbuf->b_ml.ml_line_count)
        {
            curwin->w_topline = curbuf->b_ml.ml_line_count;
        }
    }
    else
    {
        save_curwin = win_find_by_id(aco->save_curwin_id);
        if (save_curwin != NULL)
        {
            if (curwin->w_id == aco->new_curwin_id && curbuf != aco->new_curbuf.br_buf && bufref_valid(&aco->new_curbuf) && aco->new_curbuf.br_buf->b_ml.ml_mfp != NULL)
            {
                --curbuf->b_nwindows;
                curbuf = aco->new_curbuf.br_buf;
                curwin->w_buffer = curbuf;
                ++curbuf->b_nwindows;
            }

            curwin = save_curwin;
            curbuf = curwin->w_buffer;
            prevwin = win_find_by_id(aco->save_prevwin_id);

            VIsual_active = aco->save_VIsual_active;
            check_cursor();
        }
    }

    VIsual_active = aco->save_VIsual_active;
    check_cursor();
    if (VIsual_active)
    {
        check_pos(curbuf, &VIsual);
    }
}

static int      autocmd_nested = FALSE;

    static int
apply_autocmds(event_T     event, char_u      *fname, char_u      *fname_io, int         force, buf_T       *buf)
{
    return apply_autocmds_group(event, fname, fname_io, force,  (-3) , buf, NULL);
}

    static int
apply_autocmds_exarg(event_T     event, char_u      *fname, char_u      *fname_io, int         force, buf_T       *buf, exarg_T     *eap)
{
    return apply_autocmds_group(event, fname, fname_io, force,  (-3) , buf, eap);
}

    static int
apply_autocmds_retval(event_T     event, char_u      *fname, char_u      *fname_io, int         force, buf_T       *buf, int         *retval)
{
    int         did_cmd;

    did_cmd = apply_autocmds_group(event, fname, fname_io, force,  (-3) , buf, NULL);
    if (did_cmd)
    {
        *retval = FAIL;
    }
    return did_cmd;
}

    static int
has_cursorhold(void)
{
    return (first_autopat[(int)(get_real_state() ==  (0x1000 | MODE_NORMAL)  ? EVENT_CURSORHOLD : EVENT_CURSORHOLDI)] != NULL);
}

    static int
trigger_cursorhold(void)
{
    int         state;

    if (!did_cursorhold && has_cursorhold() && reg_recording == 0 && typebuf.tb_len == 0 && !ins_compl_active())
    {
        state = get_real_state();
        if (state ==  (0x1000 | MODE_NORMAL)  || (state & MODE_INSERT) != 0)
        {
            return TRUE;
        }
    }
    return FALSE;
}

    static int
has_winresized(void)
{
    return (first_autopat[(int)EVENT_WINRESIZED] != NULL);
}

    static int
has_winscrolled(void)
{
    return (first_autopat[(int)EVENT_WINSCROLLED] != NULL);
}

    static int
has_cursormoved(void)
{
    return (first_autopat[(int)EVENT_CURSORMOVED] != NULL);
}

    static int
has_cursormovedI(void)
{
    return (first_autopat[(int)EVENT_CURSORMOVEDI] != NULL);
}

    static int
has_textchanged(void)
{
    return (first_autopat[(int)EVENT_TEXTCHANGED] != NULL);
}

    static int
has_textchangedI(void)
{
    return (first_autopat[(int)EVENT_TEXTCHANGEDI] != NULL);
}

    static int
has_textchangedP(void)
{
    return (first_autopat[(int)EVENT_TEXTCHANGEDP] != NULL);
}

    static int
has_insertcharpre(void)
{
    return (first_autopat[(int)EVENT_INSERTCHARPRE] != NULL);
}

    static int
has_cmdundefined(void)
{
    return (first_autopat[(int)EVENT_CMDUNDEFINED] != NULL);
}

    static int
apply_autocmds_group(event_T     event, char_u      *fname, char_u      *fname_io, int         force, int         group, buf_T       *buf, exarg_T     *eap  __attribute__((unused)) )
{
    char_u      *sfname = NULL;
    char_u      *tail;
    int         save_changed;
    buf_T       *old_curbuf;
    int         retval = FALSE;
    char_u      *save_autocmd_fname;
    int         save_autocmd_fname_full;
    int         save_autocmd_bufnr;
    char_u      *save_autocmd_match;
    int         save_autocmd_busy;
    int         save_autocmd_nested;
    static int  nesting = 0;
    AutoPatCmd_T patcmd;
    AutoPat     *ap;
    sctx_T      save_current_sctx;
    static int  filechangeshell_busy = FALSE;
    int         did_save_redobuff = FALSE;
    save_redo_T save_redo;
    int         save_KeyTyped = KeyTyped;

    if (event == NUM_EVENTS || first_autopat[(int)event] == NULL || autocmd_blocked > 0)
    {
        goto BYPASS_AU;
    }

    if (autocmd_busy && !(force || autocmd_nested))
    {
        goto BYPASS_AU;
    }

    if (filechangeshell_busy && (event == EVENT_FILECHANGEDSHELL || event == EVENT_FILECHANGEDSHELLPOST))
    {
        goto BYPASS_AU;
    }

    if (event_ignored(event, p_ei))
    {
        goto BYPASS_AU;
    }

    int win_ignore = FALSE;
    if (buf == curbuf && event_tab[event].key <= 0)
    {
        win_ignore = event_ignored(event, curwin-> w_onebuf_opt.wo_eiw );
    }
    else if (buf != NULL && event_tab[event].key <= 0 && buf->b_nwindows > 0)
    {
        tabpage_T *tp;
        win_T *wp;

        win_ignore = TRUE;
         for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
         {
             for ((wp) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next)
             {
            if (wp->w_buffer == buf && !event_ignored(event, wp-> w_onebuf_opt.wo_eiw ))
            {
                win_ignore = FALSE;
                break;
            }
             }
         }
    }
    if (win_ignore)
    {
        goto BYPASS_AU;
    }

    if (nesting == 10)
    {
        emsg(_(e_autocommand_nesting_too_deep));
        goto BYPASS_AU;
    }

    if (       (autocmd_no_enter && (event == EVENT_WINENTER || event == EVENT_BUFENTER)) || (autocmd_no_leave && (event == EVENT_WINLEAVE || event == EVENT_BUFLEAVE)))
    {
        goto BYPASS_AU;
    }

    if (event == EVENT_CMDLINECHANGED)
    {
        ++aucmd_cmdline_changed_count;
    }

    save_autocmd_fname = autocmd_fname;
    save_autocmd_fname_full = autocmd_fname_full;
    save_autocmd_bufnr = autocmd_bufnr;
    save_autocmd_match = autocmd_match;
    save_autocmd_busy = autocmd_busy;
    save_autocmd_nested = autocmd_nested;
    save_changed = curbuf->b_changed;
    old_curbuf = curbuf;

    if (fname_io == NULL)
    {
        if (event == EVENT_COLORSCHEME || event == EVENT_COLORSCHEMEPRE || event == EVENT_OPTIONSET || event == EVENT_MODECHANGED || event == EVENT_TERMRESPONSEALL)
        {
            autocmd_fname = NULL;
        }
        else if (fname != NULL && !ends_excmd(*fname))
        {
            autocmd_fname = fname;
        }
        else if (buf != NULL)
        {
            autocmd_fname = buf->b_ffname;
        }
        else
        {
            autocmd_fname = NULL;
        }
    }
    else
    {
        autocmd_fname = fname_io;
    }
    if (autocmd_fname != NULL)
    {
        autocmd_fname = vim_strsave(autocmd_fname);
    }
    autocmd_fname_full = FALSE;

    if (buf == NULL)
    {
        autocmd_bufnr = 0;
    }
    else
    {
        autocmd_bufnr = buf->b_fnum;
    }

    if (fname == NULL || *fname == NUL)
    {
        if (buf == NULL)
        {
            fname = NULL;
        }
        else
        {
                if (event == EVENT_FILETYPE)
                {
                    fname = buf->b_p_ft;
                }
                else
                {
                    if (buf->b_sfname != NULL)
                    {
                        sfname = vim_strsave(buf->b_sfname);
                    }
                    fname = buf->b_ffname;
                }
        }
        if (fname == NULL)
        {
            fname = (char_u *)"";
        }
        fname = vim_strsave(fname);
    }
    else
    {
        sfname = vim_strsave(fname);
        if (event == EVENT_FILETYPE || event == EVENT_SYNTAX || event == EVENT_CMDLINECHANGED || event == EVENT_CMDLINEENTER || event == EVENT_CMDLINELEAVEPRE || event == EVENT_CMDLINELEAVE || event == EVENT_CURSORMOVEDC || event == EVENT_CMDWINENTER || event == EVENT_CMDWINLEAVE || event == EVENT_CMDUNDEFINED || event == EVENT_FUNCUNDEFINED || event == EVENT_KEYINPUTPRE || event == EVENT_REMOTEREPLY || event == EVENT_SPELLFILEMISSING || event == EVENT_QUICKFIXCMDPRE || event == EVENT_COLORSCHEME || event == EVENT_COLORSCHEMEPRE || event == EVENT_OPTIONSET || event == EVENT_QUICKFIXCMDPOST || event == EVENT_DIRCHANGED || event == EVENT_DIRCHANGEDPRE || event == EVENT_MODECHANGED || event == EVENT_MENUPOPUP || event == EVENT_USER || event == EVENT_WINCLOSED || event == EVENT_WINRESIZED || event == EVENT_WINSCROLLED || event == EVENT_TERMRESPONSEALL)
        {
            fname = vim_strsave(fname);
            autocmd_fname_full = TRUE;
        }
        else
        {
            fname = FullName_save(fname, FALSE);
        }
    }
    if (fname == NULL)
    {
        vim_free(sfname);
        retval = FALSE;
        goto BYPASS_AU;
    }

    autocmd_match = fname;

    ++RedrawingDisabled;

    estack_push(ETYPE_AUCMD, NULL, 0);

    save_current_sctx = current_sctx;

    if (!autocmd_busy)
    {
        save_search_patterns();
        if (!ins_compl_active())
        {
            saveRedobuff(&save_redo);
            did_save_redobuff = TRUE;
        }
        curbuf->b_did_filetype = curbuf->b_keep_filetype;
    }

    autocmd_busy = TRUE;
    filechangeshell_busy = (event == EVENT_FILECHANGEDSHELL);
    ++nesting;

    if (event == EVENT_FILETYPE)
    {
        curbuf->b_did_filetype = true;
    }

    tail = gettail(fname);

      memset((&(patcmd)), (0), (sizeof(patcmd)))  ;
    patcmd.curpat = first_autopat[(int)event];
    patcmd.group = group;
    patcmd.fname = fname;
    patcmd.sfname = sfname;
    patcmd.tail = tail;
    patcmd.event = event;
    patcmd.arg_bufnr = autocmd_bufnr;
    auto_next_pat(&patcmd, FALSE);

    if (patcmd.curpat != NULL)
    {
        patcmd.next = active_apc_list;
        active_apc_list = &patcmd;

        retval = TRUE;
        for (ap = patcmd.curpat; ap->next != NULL; ap = ap->next)
        {
            ap->last = FALSE;
        }
        ap->last = TRUE;

        if (nesting == 1)
        {
            check_lnums(TRUE);
        }
        else
        {
            check_lnums_nested(TRUE);
        }

        int save_did_emsg = did_emsg;
        int save_ex_pressedreturn = get_pressedreturn();

        do_cmdline(NULL, getnextac, (void *)&patcmd, DOCMD_NOWAIT|DOCMD_VERBOSE|DOCMD_REPEAT);

        did_emsg += save_did_emsg;
        set_pressedreturn(save_ex_pressedreturn);

        if (nesting == 1)
        {
            reset_lnums();
        }

        if (active_apc_list == &patcmd)
        {
            active_apc_list = patcmd.next;
        }
    }

    if (RedrawingDisabled > 0)
    {
        --RedrawingDisabled;
    }
    autocmd_busy = save_autocmd_busy;
    filechangeshell_busy = FALSE;
    autocmd_nested = save_autocmd_nested;
    vim_free( (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_name) );
    estack_pop();
    vim_free(autocmd_fname);
    autocmd_fname = save_autocmd_fname;
    autocmd_fname_full = save_autocmd_fname_full;
    autocmd_bufnr = save_autocmd_bufnr;
    autocmd_match = save_autocmd_match;
    current_sctx = save_current_sctx;
    KeyTyped = save_KeyTyped;
    vim_free(fname);
    vim_free(sfname);
    --nesting;

    if (!autocmd_busy)
    {
        restore_search_patterns();
        if (did_save_redobuff)
        {
            restoreRedobuff(&save_redo);
        }
        curbuf->b_did_filetype = false;
        while (au_pending_free_buf != NULL)
        {
            buf_T *b = au_pending_free_buf->b_next;

            vim_free(au_pending_free_buf);
            au_pending_free_buf = b;
        }
        while (au_pending_free_win != NULL)
        {
            win_T *w = au_pending_free_win->w_next;

            vim_free(au_pending_free_win);
            au_pending_free_win = w;
        }
    }

    if (curbuf == old_curbuf && (event == EVENT_BUFREADPOST || event == EVENT_BUFWRITEPOST || event == EVENT_FILEAPPENDPOST || event == EVENT_VIMLEAVE || event == EVENT_VIMLEAVEPRE))
    {
        if (curbuf->b_changed != save_changed)
        {
            need_maketitle = TRUE;
        }
        curbuf->b_changed = save_changed;
    }

    au_cleanup();

BYPASS_AU:
    if (event == EVENT_BUFWIPEOUT && buf != NULL)
    {
        aubuflocal_remove(buf);
    }

    if (retval == OK && event == EVENT_FILETYPE)
    {
        curbuf->b_au_did_filetype = true;
    }

    return retval;
}

    static void
block_autocmds(void)
{
    ++autocmd_blocked;
}

    static void
unblock_autocmds(void)
{
    --autocmd_blocked;

}

    static int
is_autocmd_blocked(void)
{
    return autocmd_blocked != 0;
}

    static void
auto_next_pat(AutoPatCmd_T *apc, int         stop_at_last)
{
    AutoPat     *ap;
    estack_T    *entry;

    entry = ((estack_T *)exestack.ga_data) + exestack.ga_len - 1;

     vim_free(entry->es_name);
     (entry->es_name) = NULL;
    entry->es_info.aucmd = NULL;

    for (ap = apc->curpat; ap != NULL && !got_int; ap = ap->next)
    {
        apc->curpat = NULL;

        if (ap->pat != NULL && ap->cmds != NULL && (apc->group ==  (-3)  || apc->group == ap->group))
        {
            if (ap->buflocal_nr == 0 ? (match_file_pat(NULL, &ap->reg_prog, apc->fname, apc->sfname, apc->tail, ap->allow_dirs)) : ap->buflocal_nr == apc->arg_bufnr)
            {
                string_T    *event_name;
                char        *fmt;
                char_u      *namep;
                AutoCmd     *cp;

                event_name = event_nr2name(apc->event);
                fmt = _("%s Autocommands for \"%s\"");
                namep = alloc( strlen((char *)(fmt))  + event_name->length + ap->patlen + 1);
                if (namep != NULL)
                {
                    sprintf((char *)namep, fmt, (char *)event_name->string, (char *)ap->pat);
                    if (p_verbose >= 8)
                    {
                        verbose_enter();
                        smsg(_("Executing %s"), namep);
                        verbose_leave();
                    }
                }

                entry->es_name = namep;
                entry->es_info.aucmd = apc;

                apc->curpat = ap;
                apc->nextcmd = ap->cmds;
                for (cp = ap->cmds; cp->next != NULL; cp = cp->next)
                {
                    cp->last = FALSE;
                }
                cp->last = TRUE;
            }
            line_breakcheck();
            if (apc->curpat != NULL)
            {
                break;
            }
        }
        if (stop_at_last && ap->last)
        {
            break;
        }
    }
}

    static char_u *
getnextac(int c  __attribute__((unused)) , void *cookie, int indent  __attribute__((unused)) , getline_opt_T options  __attribute__((unused)) )
{
    AutoPatCmd_T    *acp = (AutoPatCmd_T *)cookie;
    char_u          *retval;
    AutoCmd         *ac;

    if (acp->curpat == NULL)
    {
        return NULL;
    }

    for (;;)
    {
        while (acp->nextcmd != NULL && acp->nextcmd->cmd == NULL)
        {
            if (acp->nextcmd->last)
            {
                acp->nextcmd = NULL;
            }
            else
            {
                acp->nextcmd = acp->nextcmd->next;
            }
        }

        if (acp->nextcmd != NULL)
        {
            break;
        }

        if (acp->curpat->last)
        {
            acp->curpat = NULL;
        }
        else
        {
            acp->curpat = acp->curpat->next;
        }
        if (acp->curpat != NULL)
        {
            auto_next_pat(acp, TRUE);
        }
        if (acp->curpat == NULL)
        {
            return NULL;
        }
    }

    ac = acp->nextcmd;

    if (p_verbose >= 9)
    {
        verbose_enter_scroll();
        smsg(_("autocommand %s"), ac->cmd);
        msg_puts("\n");
        verbose_leave_scroll();
    }
    retval = vim_strsave(ac->cmd);
    if (ac->once)
    {
        au_del_cmd(ac);
    }
    autocmd_nested = ac->nested;
    current_sctx = ac->script_ctx;
    acp->script_ctx = current_sctx;
    if (ac->last)
    {
        acp->nextcmd = NULL;
    }
    else
    {
        acp->nextcmd = ac->next;
    }
    return retval;
}

    static int
has_autocmd(event_T event, char_u *sfname, buf_T *buf)
{
    AutoPat     *ap;
    char_u      *fname;
    char_u      *tail = gettail(sfname);
    int         retval = FALSE;

    fname = FullName_save(sfname, FALSE);
    if (fname == NULL)
    {
        return FALSE;
    }

     for ((ap) = first_autopat[(int)(event)]; (ap) != NULL; (ap) = (ap)->next) 
     {
        if (ap->pat != NULL && ap->cmds != NULL && (ap->buflocal_nr == 0 ? match_file_pat(NULL, &ap->reg_prog, fname, sfname, tail, ap->allow_dirs) : buf != NULL && ap->buflocal_nr == buf->b_fnum))
        {
            retval = TRUE;
            break;
        }
     }

    vim_free(fname);

    return retval;
}

    static char_u *
get_augroup_name(expand_T *xp  __attribute__((unused)) , int idx)
{
    if (idx == augroups.ga_len)
    {
        return (char_u *)"END";
    }
    if (idx < 0 || idx >= augroups.ga_len)
    {
        return NULL;
    }
    if ( (((char_u **)augroups.ga_data)[idx])  == NULL ||  (((char_u **)augroups.ga_data)[idx])  == get_deleted_augroup())
    {
        return (char_u *)"";
    }
    return  (((char_u **)augroups.ga_data)[idx]) ;
}

static int include_groups = FALSE;

    static char_u  *
set_context_in_autocmd(expand_T    *xp, char_u      *arg, int         doautocmd)
{
    char_u      *p;
    int         group;

    include_groups = FALSE;
    p = arg;
    group = au_get_grouparg(&arg);
    if (group ==  (-2) )
    {
        return NULL;
    }
    if (*arg == NUL && group !=  (-3)  && ! ((arg[-1]) == ' ' || (arg[-1]) == '\t') )
    {
        arg = p;
        group =  (-3) ;
    }

    for (p = arg; *p != NUL && ! ((*p) == ' ' || (*p) == '\t') ; ++p)
    {
        if (*p == ',')
        {
            arg = p + 1;
        }
    }
    if (*p == NUL)
    {
        if (group ==  (-3) )
        {
            include_groups = TRUE;
        }
        xp->xp_context = EXPAND_EVENTS;
        xp->xp_pattern = arg;
        return NULL;
    }

    arg = skipwhite(p);
    while (*arg && (! ((*arg) == ' ' || (*arg) == '\t')  || arg[-1] == '\\'))
    {
        arg++;
    }
    if (*arg)
    {
        return arg;
    }

    if (doautocmd)
    {
        xp->xp_context = EXPAND_FILES;
    }
    else
    {
        xp->xp_context = EXPAND_NOTHING;
    }
    return NULL;
}

    static char_u *
get_event_name(expand_T *xp  __attribute__((unused)) , int idx)
{
    int i;

    if (idx < augroups.ga_len)
    {
        if (!include_groups ||  (((char_u **)augroups.ga_data)[idx])  == NULL ||  (((char_u **)augroups.ga_data)[idx])  == get_deleted_augroup())
        {
            return (char_u *)"";
        }
        return  (((char_u **)augroups.ga_data)[idx]) ;
    }

    i = idx - augroups.ga_len;
    if (i < 0 || i >= NUM_EVENTS)
    {
        return NULL;
    }

    return event_tab[i].value.string;
}

    static char_u *
get_event_name_no_group(expand_T *xp  __attribute__((unused)) , int idx, int win)
{
    if (idx < 0 || idx >= NUM_EVENTS)
    {
        return NULL;
    }

    if (!win)
    {
        return event_tab[idx].value.string;
    }

    int j = 0;
    for (int i = 0; i < NUM_EVENTS; ++i)
    {
        j += event_tab[i].key <= 0;
        if (j == idx + 1)
        {
            return event_tab[i].value.string;
        }
    }

    return NULL;
}

    static int
has_tabclosedpre(void)
{
    return (first_autopat[(int)EVENT_TABCLOSEDPRE] != NULL);
}

