    static void
trigger_undo_ftplugin(buf_T *buf, win_T *win)
{
    window_layout_lock();
    ++buf->b_locked;
    ++win->w_locked;
    do_cmdline_cmd((char_u*)"if exists('b:undo_ftplugin') | :legacy :exe \t    b:undo_ftplugin | endif");
    --buf->b_locked;
    --win->w_locked;
    window_layout_unlock();
}

    static int
calc_percentage(long part, long whole)
{
    return (part > 1000000L)
        ? (int)(part / (whole / 100L))
        : (int)((part * 100L) / whole);
}

    static int
get_highest_fnum(void)
{
    return top_file_num - 1;
}

    static int
read_buffer(int         read_stdin, exarg_T     *eap, int         flags)
{
    int         retval = OK;
    linenr_T    line_count;

    line_count = curbuf->b_ml.ml_line_count;
    retval = readfile(read_stdin ? NULL : curbuf->b_ffname, read_stdin ? NULL : curbuf->b_fname, line_count, (linenr_T)0, (linenr_T) LONG_MAX , eap, flags | READ_BUFFER);
    if (retval == OK)
    {
        while (--line_count >= 0)
        {
            ml_delete((linenr_T)1);
        }
    }
    else
    {
        while (curbuf->b_ml.ml_line_count > line_count)
        {
            ml_delete(line_count);
        }
    }
    curwin->w_cursor.lnum = 1;
    curwin->w_cursor.col = 0;

    if (read_stdin)
    {
        if (!readonlymode && ! (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) )
        {
            changed();
        }
        else if (retval == OK)
        {
            unchanged(curbuf, FALSE, TRUE);
        }

        if (retval == OK)
        {
            apply_autocmds(EVENT_STDINREADPOST, NULL, NULL, FALSE, curbuf);
        }
    }
    return retval;
}

    static int
open_buffer(int         read_stdin, exarg_T     *eap, int         flags_arg)
{
    int         flags = flags_arg;
    int         retval = OK;
    bufref_T    old_curbuf;
    int         read_fifo = FALSE;

    if (readonlymode && curbuf->b_ffname != NULL && (curbuf->b_flags & BF_NEVERLOADED))
    {
        curbuf->b_p_ro = TRUE;
    }

    if (ml_open(curbuf) == FAIL)
    {
        close_buffer(curwin, curbuf, 0, FALSE, FALSE, FALSE);
         for ((curbuf) = firstbuf; (curbuf) != NULL; (curbuf) = (curbuf)->b_next) 
         {
            if (curbuf->b_ml.ml_mfp != NULL)
            {
                break;
            }
         }
        if (curbuf == NULL)
        {
            emsg(_(e_cannot_allocate_any_buffer_exiting));

            v_dying = 2;
            getout(2);
        }

        emsg(_(e_cannot_allocate_buffer_using_other_one));
        enter_buffer(curbuf);
        return FAIL;
    }

    if (curbuf->b_ml.ml_mfp != NULL)
    {
        curbuf->b_ml.ml_mfp->mf_dirty = MF_DIRTY_YES_NOSYNC;
    }

    set_bufref(&old_curbuf, curbuf);
    curbuf->b_modified_was_set = false;

    curwin->w_valid = 0;

    if (bt_nofileread(curbuf))
    {
        flags |= READ_NOFILE;
    }

    if (curbuf->b_ffname != NULL)
    {
        int old_msg_silent = msg_silent;
        int     save_bin = curbuf->b_p_bin;
        int perm;
        perm = mch_getperm(curbuf->b_ffname);
        if (perm >= 0 && (S_ISFIFO(perm) || S_ISSOCK(perm)))
        {
                read_fifo = TRUE;
        }
        if (read_fifo)
        {
            curbuf->b_p_bin = TRUE;
        }
        if (shortmess(SHM_FILEINFO))
        {
            msg_silent = 1;
        }
        retval = readfile(curbuf->b_ffname, curbuf->b_fname, (linenr_T)0, (linenr_T)0, (linenr_T) LONG_MAX , eap, flags | READ_NEW | (read_fifo ? READ_FIFO : 0));
        if (read_fifo)
        {
            curbuf->b_p_bin = save_bin;
            if (retval == OK)
            {
                retval = read_buffer(FALSE, eap, flags);
            }
        }
        msg_silent = old_msg_silent;
        if (bt_help(curbuf))
        {
            fix_help_buffer();
        }
    }
    else if (read_stdin)
    {
        int     save_bin = curbuf->b_p_bin;

        curbuf->b_p_bin = TRUE;
        retval = readfile(NULL, NULL, (linenr_T)0, (linenr_T)0, (linenr_T) LONG_MAX , NULL, flags | (READ_NEW + READ_STDIN));
        curbuf->b_p_bin = save_bin;
        if (retval == OK)
        {
            retval = read_buffer(TRUE, eap, flags);
        }
    }

    if (curbuf->b_ml.ml_mfp != NULL && curbuf->b_ml.ml_mfp->mf_dirty == MF_DIRTY_YES_NOSYNC)
    {
        curbuf->b_ml.ml_mfp->mf_dirty = MF_DIRTY_YES;
    }

    if (curbuf->b_flags & BF_NEVERLOADED)
    {
        (void)buf_init_chartab(curbuf, FALSE);
        parse_cino(curbuf);
    }

    if ((got_int && vim_strchr(p_cpo, CPO_INTMOD) != NULL) || curbuf->b_modified_was_set)
    {
        changed();
    }
    else if (retval == OK && !read_stdin && !read_fifo)
    {
        unchanged(curbuf, FALSE, TRUE);
    }
    save_file_ff(curbuf);

    curbuf->b_last_changedtick =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
    curbuf->b_last_changedtick_i =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
    curbuf->b_last_changedtick_pum =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;

    if (got_int)
    {
        curbuf->b_flags |= BF_READERR;
    }

    if (!(curwin->w_valid & VALID_TOPLINE))
    {
        curwin->w_topline = 1;
    }
    apply_autocmds(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf);

    if (retval != OK)
    {
        return retval;
    }

    if (bufref_valid(&old_curbuf) && old_curbuf.br_buf->b_ml.ml_mfp != NULL)
    {
        aco_save_T      aco;

        aucmd_prepbuf(&aco, old_curbuf.br_buf);
        if (curbuf == old_curbuf.br_buf)
        {
            do_modelines(0);
            curbuf->b_flags &= ~(BF_CHECK_RO | BF_NEVERLOADED);

            if ((flags & READ_NOWINENTER) == 0)
            {
            apply_autocmds(EVENT_BUFWINENTER, NULL, NULL, FALSE, curbuf);
            }

            aucmd_restbuf(&aco);
        }
    }

    return retval;
}

    static void
set_bufref(bufref_T *bufref, buf_T *buf)
{
    bufref->br_buf = buf;
    bufref->br_fnum = buf == NULL ? 0 : buf->b_fnum;
    bufref->br_buf_free_count = buf_free_count;
}

    static int
bufref_valid(bufref_T *bufref)
{
    return bufref->br_buf_free_count == buf_free_count
        ? TRUE : buf_valid(bufref->br_buf)
                                  && bufref->br_fnum == bufref->br_buf->b_fnum;
}

    static int
buf_valid(buf_T *buf)
{
    buf_T       *bp;

     for ((bp) = lastbuf; (bp) != NULL; (bp) = (bp)->b_prev) 
     {
        if (bp == buf)
        {
            return TRUE;
        }
     }
    return FALSE;
}

static hashtab_T buf_hashtab;

    static void
buf_hashtab_add(buf_T *buf)
{
    vim_snprintf((char *)buf->b_key, sizeof(buf->b_key), "%x", buf->b_fnum);
    if (hash_add(&buf_hashtab, buf->b_key, "create buffer") == FAIL)
    {
        emsg(_(e_buffer_cannot_be_registered));
    }
}

    static void
buf_hashtab_remove(buf_T *buf)
{
    hashitem_T *hi = hash_find(&buf_hashtab, buf->b_key);

    if (! ((hi)->hi_key == NULL || (hi)->hi_key == &hash_removed) )
    {
        hash_remove(&buf_hashtab, hi, "close buffer");
    }
}

    static int
can_unload_buffer(buf_T *buf)
{
    int     can_unload = !buf->b_locked;

    if (can_unload && updating_screen)
    {
        win_T   *wp;

         for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
         {
            if (wp->w_buffer == buf)
            {
                can_unload = FALSE;
                break;
            }
         }
    }
    if (can_unload && buf->b_saving)
    {
        can_unload = FALSE;
    }

    if (!can_unload)
    {
        char_u *fname = buf->b_fname != NULL ? buf->b_fname : buf->b_ffname;

        semsg(_(e_attempt_to_delete_buffer_that_is_in_use_str), fname != NULL ? fname : (char_u *)"[No Name]");
    }
    return can_unload;
}

    static int
close_buffer(win_T       *win, buf_T       *buf, int         action, int         abort_if_last, int         ignore_abort, int         set_context)
{
    int         hiding_buf;
    bufref_T    bufref;
    int         is_curwin = (curwin != NULL && curwin == win && curwin->w_buffer == buf);
    tabpage_T   *the_curtab = curtab;
    int         unload_buf = (action != 0);
    int         wipe_buf = (action == DOBUF_WIPE || action == DOBUF_WIPE_REUSE);
    int         del_buf = (action == DOBUF_DEL || wipe_buf);
    int         win_valid = win_valid_any_tab(win);
    int         closed_popup = win && !win_valid &&  0 ;

    if (buf->b_p_bh[0] == 'd')
    {
        del_buf = TRUE;
        unload_buf = TRUE;
    }
    else if (buf->b_p_bh[0] == 'w')
    {
        del_buf = TRUE;
        unload_buf = TRUE;
        wipe_buf = TRUE;
    }
    else if (buf->b_p_bh[0] == 'u')
    {
        unload_buf = TRUE;
    }

    if ((del_buf || wipe_buf) && !can_unload_buffer(buf))
    {
        return FALSE;
    }

    if (set_context && win_valid && win->w_buffer == buf)
    {
        if (buf->b_nwindows == 1)
        {
            set_last_cursor(win);
        }
        buflist_setfpos(buf, win, win->w_cursor.lnum == 1 ? 0 : win->w_cursor.lnum, win->w_cursor.col, TRUE);
    }

    set_bufref(&bufref, buf);

    if ((win_valid || closed_popup) && win->w_buffer == buf && buf->b_nwindows == 1)
    {
        ++buf->b_locked;
        ++buf->b_locked_split;
        if (apply_autocmds(EVENT_BUFWINLEAVE, buf->b_fname, buf->b_fname, FALSE, buf) && !bufref_valid(&bufref))
        {
aucmd_abort:
            emsg(_(e_autocommands_caused_command_to_abort));
            return FALSE;
        }
        --buf->b_locked;
        --buf->b_locked_split;
        if (abort_if_last && one_window())
        {
            goto aucmd_abort;
        }

        if (!unload_buf)
        {
            ++buf->b_locked;
            ++buf->b_locked_split;
            if (apply_autocmds(EVENT_BUFHIDDEN, buf->b_fname, buf->b_fname, FALSE, buf) && !bufref_valid(&bufref))
            {
                goto aucmd_abort;
            }
            --buf->b_locked;
            --buf->b_locked_split;
            if (abort_if_last && one_window())
            {
                goto aucmd_abort;
            }
        }
        win_valid = win_valid && win_valid_any_tab(win);
    }

    if (is_curwin && curwin != win && win_valid)
    {
        block_autocmds();
        goto_tabpage_win(the_curtab, win);
        unblock_autocmds();
    }

    if (bt_quickfix(buf) && win_valid && win->w_buffer == buf)
    {
        win-> w_onebuf_opt.wo_wfh  = FALSE;
    }

    hiding_buf = buf->b_nwindows <= 0 || ((win_valid || closed_popup) && win->w_buffer == buf && buf->b_nwindows == 1);

    if (!hiding_buf || !unload_buf)
    {
        return FALSE;
    }

    if (buf->b_ffname == NULL)
    {
        del_buf = TRUE;
    }

    if (!buf_freeall(buf, (del_buf ? BFA_DEL : 0) + (wipe_buf ? BFA_WIPE : 0) + (ignore_abort ? BFA_IGNORE_ABORT : 0)))
    {
        return FALSE;
    }

    win_valid = win_valid && win_valid_any_tab(win);
    if ((win_valid || closed_popup) && win->w_buffer == buf)
    {
        --buf->b_nwindows;
        win->w_buffer = NULL;
    }

    if (wipe_buf && buf->b_nwindows <= 0 && (buf->b_prev != NULL || buf->b_next != NULL))
    {
        tabpage_T       *tp;
        win_T           *wp;

         for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
         {
             for ((wp) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next)
             {
            mark_forget_file(wp, buf->b_fnum);
             }
         }

        if (action == DOBUF_WIPE_REUSE)
        {
            if (buf_reuse.ga_itemsize == 0)
            {
                ga_init2(&buf_reuse, sizeof(int), 50);
            }
            if (ga_grow(&buf_reuse, 1) == OK)
            {
                ((int *)buf_reuse.ga_data)[buf_reuse.ga_len++] = buf->b_fnum;
            }
        }
        if (buf->b_sfname != buf->b_ffname)
        {
             vim_free(buf->b_sfname);
             (buf->b_sfname) = NULL;
        }
        else
        {
            buf->b_sfname = NULL;
        }
         vim_free(buf->b_ffname);
         (buf->b_ffname) = NULL;
        if (buf->b_prev == NULL)
        {
            firstbuf = buf->b_next;
        }
        else
        {
            buf->b_prev->b_next = buf->b_next;
        }
        if (buf->b_next == NULL)
        {
            lastbuf = buf->b_prev;
        }
        else
        {
            buf->b_next->b_prev = buf->b_prev;
        }
        free_buffer(buf);
    }
    else
    {
        if (del_buf)
        {
            free_buffer_stuff(buf, TRUE);

            buf->b_flags = BF_CHECK_RO | BF_NEVERLOADED;

            buf->b_p_initialized = false;
        }
        buf_clear_file(buf);
        if (del_buf)
        {
            buf->b_p_bl = FALSE;
        }
    }

    return TRUE;
}

    static void
buf_clear_file(buf_T *buf)
{
    buf->b_ml.ml_line_count = 1;
    unchanged(buf, TRUE, TRUE);
    buf->b_shortname = false;
    buf->b_p_eof = FALSE;
    buf->b_start_eof = FALSE;
    buf->b_p_eol = TRUE;
    buf->b_start_eol = TRUE;
    buf->b_ml.ml_mfp = NULL;
    buf->b_ml.ml_flags = ML_EMPTY;
}

    static int
buf_freeall(buf_T *buf, int flags)
{
    int         is_curbuf = (buf == curbuf);
    bufref_T    bufref;
    int         is_curwin = (curwin != NULL && curwin->w_buffer == buf);
    win_T       *the_curwin = curwin;
    tabpage_T   *the_curtab = curtab;

    ++buf->b_locked;
    ++buf->b_locked_split;
    set_bufref(&bufref, buf);
    if (buf->b_ml.ml_mfp != NULL)
    {
        if (apply_autocmds(EVENT_BUFUNLOAD, buf->b_fname, buf->b_fname, FALSE, buf) && !bufref_valid(&bufref))
        {
            return FALSE;
        }
    }
    if ((flags & BFA_DEL) && buf->b_p_bl)
    {
        if (apply_autocmds(EVENT_BUFDELETE, buf->b_fname, buf->b_fname, FALSE, buf) && !bufref_valid(&bufref))
        {
            return FALSE;
        }
    }
    if (flags & BFA_WIPE)
    {
        if (apply_autocmds(EVENT_BUFWIPEOUT, buf->b_fname, buf->b_fname, FALSE, buf) && !bufref_valid(&bufref))
        {
            return FALSE;
        }
    }
    --buf->b_locked;
    --buf->b_locked_split;

    if (is_curwin && curwin != the_curwin && win_valid_any_tab(the_curwin))
    {
        block_autocmds();
        goto_tabpage_win(the_curtab, the_curwin);
        unblock_autocmds();
    }

    if (buf == curbuf && !is_curbuf)
    {
        return FALSE;
    }

    if (buf == curbuf && VIsual_active)
    {
        end_visual_mode();
    }

    ml_close(buf, TRUE);
    buf->b_ml.ml_line_count = 0;
    if ((flags & BFA_KEEP_UNDO) == 0)
    {
        u_clearallandblockfree(buf);
    }
    buf->b_flags &= ~BF_READERR;
    return TRUE;
}

    static void
free_buffer(buf_T *buf)
{
    ++buf_free_count;
    free_buffer_stuff(buf, TRUE);

    buf_hashtab_remove(buf);

    aubuflocal_remove(buf);

    if (autocmd_busy)
    {
        buf->b_next = au_pending_free_buf;
        au_pending_free_buf = buf;
    }
    else
    {
        vim_free(buf);
        if (curbuf == buf)
        {
            curbuf = NULL;
        }
    }
}

    static void
init_changedtick(buf_T *buf)
{
    dictitem_T *di = (dictitem_T *)&buf->b_ct_di;

    di->di_flags = DI_FLAGS_FIX | DI_FLAGS_RO;
    di->di_tv.v_type = VAR_NUMBER;
    di->di_tv.v_lock = VAR_FIXED;
    di->di_tv.vval.v_number = 0;

}

    static void
clear_wininfo(buf_T *buf)
{
    wininfo_T   *wip;

    while (buf->b_wininfo != NULL)
    {
        wip = buf->b_wininfo;
        buf->b_wininfo = wip->wi_next;
        free_wininfo(wip);
    }
}

    static void
free_buffer_stuff(buf_T       *buf, int         free_options)
{
    if (free_options)
    {
        clear_wininfo(buf);
        free_buf_options(buf, TRUE);
    }
    uc_clear(&buf->b_ucmds);
    map_clear_mode(buf, MAP_ALL_MODES, TRUE, FALSE);
    map_clear_mode(buf, MAP_ALL_MODES, TRUE, TRUE);
}

    static void
free_wininfo(wininfo_T *wip)
{
    if (wip->wi_optset)
    {
        clear_winopt(&wip->wi_opt);
    }
    vim_free(wip);
}

    static void
goto_buffer(exarg_T     *eap, int         start, int         dir, int         count)
{
    bufref_T    old_curbuf;
    int         save_sea = swap_exists_action;
    int         skip_help_buf;

    switch (eap->cmdidx)
    {
        case CMD_bnext:
        case CMD_sbnext:
        case CMD_bNext:
        case CMD_bprevious:
        case CMD_sbNext:
        case CMD_sbprevious:
            skip_help_buf = TRUE;
            break;
        default:
            skip_help_buf = FALSE;
            break;
    }

    set_bufref(&old_curbuf, curbuf);

    if (swap_exists_action == SEA_NONE)
    {
        swap_exists_action = SEA_DIALOG;
    }
    (void)do_buffer_ext(*eap->cmd == 's' ? DOBUF_SPLIT : DOBUF_GOTO, start, dir, count, (eap->forceit ? DOBUF_FORCEIT : 0) | (skip_help_buf ? DOBUF_SKIPHELP : 0));
    if (swap_exists_action == SEA_QUIT && *eap->cmd == 's')
    {
        win_close(curwin, TRUE);
        swap_exists_action = save_sea;
        swap_exists_did_quit = TRUE;

    }
    else
    {
        handle_swap_exists(&old_curbuf);
    }
}

    static void
handle_swap_exists(bufref_T *old_curbuf)
{
    buf_T       *buf;

    if (swap_exists_action == SEA_QUIT)
    {
        swap_exists_action = SEA_NONE;
        swap_exists_did_quit = TRUE;
        close_buffer(curwin, curbuf, DOBUF_UNLOAD, FALSE, FALSE, TRUE);
        if (old_curbuf == NULL || !bufref_valid(old_curbuf) || old_curbuf->br_buf == curbuf)
        {
            block_autocmds();
            buf = buflist_new(NULL, NULL, 1L, BLN_CURBUF | BLN_LISTED);
            unblock_autocmds();
        }
        else
        {
            buf = old_curbuf->br_buf;
        }
        if (buf != NULL)
        {
            int old_msg_silent = msg_silent;

            if (shortmess(SHM_FILEINFO))
            {
                msg_silent = 1;
            }
            enter_buffer(buf);
            msg_silent = old_msg_silent;

        }

    }
    swap_exists_action = SEA_NONE;
}

    static int
empty_curbuf(int close_others, int forceit, int action)
{
    int     retval;
    buf_T   *buf = curbuf;
    bufref_T bufref;

    if (action == DOBUF_UNLOAD)
    {
        emsg(_(e_cannot_unload_last_buffer));
        return FAIL;
    }

    set_bufref(&bufref, buf);
    if (close_others)
    {
        close_windows(buf, TRUE);
    }

    setpcmark();
    retval = do_ecmd(0, NULL, NULL, NULL,  (linenr_T)1 , forceit ? ECMD_FORCEIT : 0, curwin);

    if (buf != curbuf && bufref_valid(&bufref) && buf->b_nwindows == 0)
    {
        close_buffer(NULL, buf, action, FALSE, FALSE, FALSE);
    }
    if (!close_others)
    {
        need_fileinfo = FALSE;
    }
    else if (retval == OK && !shortmess(SHM_FILEINFO))
    {
        need_fileinfo = TRUE;
    }
    return retval;
}

    static int
do_buffer_ext(int         action, int         start, int         dir, int         count, int         flags)
{
    buf_T       *buf;
    buf_T       *bp;
    int         unload = (action == DOBUF_UNLOAD || action == DOBUF_DEL || action == DOBUF_WIPE || action == DOBUF_WIPE_REUSE);

    switch (start)
    {
        case DOBUF_FIRST:
            buf = firstbuf;
            break;
        case DOBUF_LAST:
            buf = lastbuf;
            break;
        default:
            buf = curbuf;
            break;
    }
    if (start == DOBUF_MOD)
    {
        while (count-- > 0)
        {
            do
            {
                buf = buf->b_next;
                if (buf == NULL)
                {
                    buf = firstbuf;
                }
            }
            while (buf != curbuf && !bufIsChanged(buf))
                ;
        }
        if (!bufIsChanged(buf))
        {
            emsg(_(e_no_modified_buffer_found));
            return FAIL;
        }
    }
    else if (start == DOBUF_FIRST && count)
    {
        while (buf != NULL && buf->b_fnum != count)
        {
            buf = buf->b_next;
        }
    }
    else
    {
        int help_only = (flags & DOBUF_SKIPHELP) != 0 && buf->b_help;

        bp = NULL;
        while (count > 0 || (bp != buf && !unload && !(help_only ? buf->b_help : buf->b_p_bl)))
        {
            if (bp == NULL)
            {
                bp = buf;
            }
            if (dir == FORWARD)
            {
                buf = buf->b_next;
                if (buf == NULL)
                {
                    buf = firstbuf;
                }
            }
            else
            {
                buf = buf->b_prev;
                if (buf == NULL)
                {
                    buf = lastbuf;
                }
            }
            if (unload || (help_only ? buf->b_help : (buf->b_p_bl && ((flags & DOBUF_SKIPHELP) == 0 || !buf->b_help))))
            {
                --count;
                bp = NULL;
            }
            if (bp == buf)
            {
                emsg(_(e_there_is_no_listed_buffer));
                return FAIL;
            }
        }
    }

    if (buf == NULL)
    {
        if (start == DOBUF_FIRST)
        {
            if (!unload)
            {
                semsg(_(e_buffer_nr_does_not_exist), count);
            }
        }
        else if (dir == FORWARD)
        {
            emsg(_(e_cannot_go_beyond_last_buffer));
        }
        else
        {
            emsg(_(e_cannot_go_before_first_buffer));
        }
        return FAIL;
    }
    if (action == DOBUF_GOTO && buf != curbuf && !check_can_set_curbuf_forceit((flags & DOBUF_FORCEIT) != 0))
    {
        return FAIL;
    }

    if ((action == DOBUF_GOTO || action == DOBUF_SPLIT) && (buf->b_flags & BF_DUMMY))
    {
        semsg(_(e_buffer_nr_does_not_exist), count);
        return FAIL;
    }

    if (unload)
    {
        int     forward;
        bufref_T bufref;

        if (!can_unload_buffer(buf))
        {
            return FAIL;
        }

        set_bufref(&bufref, buf);

        if (action != DOBUF_WIPE && action != DOBUF_WIPE_REUSE && buf->b_ml.ml_mfp == NULL && !buf->b_p_bl)
        {
            return FAIL;
        }

        if ((flags & DOBUF_FORCEIT) == 0 && bufIsChanged(buf))
        {
            {
                no_write_message_buf(buf);
                return FAIL;
            }
        }

        if (buf == curbuf && VIsual_active)
        {
            end_visual_mode();
        }

         for ((bp) = firstbuf; (bp) != NULL; (bp) = (bp)->b_next) 
         {
            if (bp->b_p_bl && bp != buf)
            {
                break;
            }
         }
        if (bp == NULL && buf == curbuf)
        {
            return empty_curbuf(TRUE, (flags & DOBUF_FORCEIT), action);
        }

        while (buf == curbuf && !(win_locked(curwin) || curwin->w_buffer->b_locked > 0) && (! (firstwin == lastwin)  || first_tabpage->tp_next != NULL))
        {
            if (win_close(curwin, FALSE) == FAIL)
            {
                break;
            }
        }

        if (buf != curbuf)
        {
            close_windows(buf, FALSE);
            if (buf != curbuf && bufref_valid(&bufref) && buf->b_nwindows <= 0)
            {
                    close_buffer(NULL, buf, action, FALSE, FALSE, FALSE);
            }
            return OK;
        }

        buf = NULL;
        bp = NULL;
        if (au_new_curbuf.br_buf != NULL && bufref_valid(&au_new_curbuf) && !au_new_curbuf.br_buf->b_locked_split)
        {
            buf = au_new_curbuf.br_buf;
        }
        else if (curwin->w_jumplistlen > 0)
        {
            int     jumpidx;

            jumpidx = curwin->w_jumplistidx - 1;
            if (jumpidx < 0)
            {
                jumpidx = curwin->w_jumplistlen - 1;
            }

            forward = jumpidx;
            while (jumpidx != curwin->w_jumplistidx)
            {
                buf = buflist_findnr(curwin->w_jumplist[jumpidx].fmark.fnum);
                if (buf != NULL)
                {
                    if (buf == curbuf || !buf->b_p_bl || bt_quickfix(buf) || buf->b_locked_split)
                    {
                        buf = NULL;
                    }
                    else if (buf->b_ml.ml_mfp == NULL)
                    {
                        if (bp == NULL)
                        {
                            bp = buf;
                        }
                        buf = NULL;
                    }
                }
                if (buf != NULL)
                {
                    break;
                }
                if (!jumpidx && curwin->w_jumplistidx == curwin->w_jumplistlen)
                {
                    break;
                }
                if (--jumpidx < 0)
                {
                    jumpidx = curwin->w_jumplistlen - 1;
                }
                if (jumpidx == forward)
                {
                    break;
                }
            }
        }

        if (buf == NULL)
        {
            forward = TRUE;
            buf = curbuf->b_next;
            for (;;)
            {
                if (buf == NULL)
                {
                    if (!forward)
                    {
                        break;
                    }
                    buf = curbuf->b_prev;
                    forward = FALSE;
                    continue;
                }
                if (buf->b_help == curbuf->b_help && buf->b_p_bl && !bt_quickfix(buf) && !buf->b_locked_split)
                {
                    if (buf->b_ml.ml_mfp != NULL)
                    {
                        break;
                    }
                    if (bp == NULL)
                    {
                        bp = buf;
                    }
                }
                if (forward)
                {
                    buf = buf->b_next;
                }
                else
                {
                    buf = buf->b_prev;
                }
            }
        }
        if (buf == NULL)
        {
            buf = bp;
        }
        if (buf == NULL)
        {
             for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
             {
                if (buf->b_p_bl && buf != curbuf && !bt_quickfix(buf) && !buf->b_locked_split)
                {
                    break;
                }
             }
        }
        if (buf == NULL)
        {
            if (curbuf->b_next != NULL)
            {
                buf = curbuf->b_next;
            }
            else
            {
                buf = curbuf->b_prev;
            }
            if (bt_quickfix(buf) || (buf != NULL && buf != curbuf && buf->b_locked_split))
            {
                buf = NULL;
            }
        }
    }

    if (buf == NULL)
    {
        return empty_curbuf(FALSE, (flags & DOBUF_FORCEIT), action);
    }

    if (action == DOBUF_SPLIT && swbuf_goto_win_with_buf(buf) != NULL)
    {
        return OK;
    }
    if (buf != curbuf && buf->b_locked_split)
    {
        emsg(_(e_cannot_switch_to_a_closing_buffer));
        return FAIL;
    }
    if (action == DOBUF_SPLIT && win_split(0, 0) == FAIL)
    {
        return FAIL;
    }

    if (buf == curbuf)
    {
        return OK;
    }

    if (action == DOBUF_GOTO && !can_abandon(curbuf, (flags & DOBUF_FORCEIT)))
    {
        {
            no_write_message();
            return FAIL;
        }
    }

    set_curbuf(buf, action);

    if (action == DOBUF_SPLIT)
    {
         (curwin)-> w_onebuf_opt.wo_scb  = FALSE;
         (curwin)-> w_onebuf_opt.wo_crb  = FALSE;
    }

    return OK;
}

    static int
do_buffer(int         action, int         start, int         dir, int         count, int         forceit)
{
    return do_buffer_ext(action, start, dir, count, forceit ? DOBUF_FORCEIT : 0);
}

    static char *
do_bufdel(int         command, char_u      *arg, int         addr_count, int         start_bnr, int         end_bnr, int         forceit)
{
    int         do_current = 0;
    int         deleted = 0;
    char        *errormsg = NULL;
    int         bnr;
    char_u      *p;

    if (addr_count == 0)
    {
        (void)do_buffer(command, DOBUF_CURRENT, FORWARD, 0, forceit);
    }
    else
    {
        if (addr_count == 2)
        {
            if (*arg)
            {
                return ex_errmsg(e_trailing_characters_str, arg);
            }
            bnr = start_bnr;
        }
        else
        {
            bnr = end_bnr;
        }

        for ( ;!got_int; ui_breakcheck())
        {
            if (bnr == curbuf->b_fnum)
            {
                do_current = bnr;
            }
            else if (do_buffer_ext(command, DOBUF_FIRST, FORWARD, bnr, DOBUF_NOPOPUP | (forceit ? DOBUF_FORCEIT : 0)) == OK)
            {
                ++deleted;
            }

            if (addr_count == 2)
            {
                if (++bnr > end_bnr)
                {
                    break;
                }
            }
            else
            {
                arg = skipwhite(arg);
                if (*arg == NUL)
                {
                    break;
                }
                if (! ((unsigned)(*arg) - '0' < 10) )
                {
                    p = skiptowhite_esc(arg);
                    bnr = buflist_findpat(arg, p, command == DOBUF_WIPE || command == DOBUF_WIPE_REUSE, FALSE, FALSE);
                    if (bnr < 0)
                    {
                        break;
                    }
                    arg = p;
                }
                else
                {
                    bnr = getdigits(&arg);
                }
            }
        }
        if (!got_int && do_current && do_buffer(command, DOBUF_FIRST, FORWARD, do_current, forceit) == OK)
        {
            ++deleted;
        }

        if (deleted == 0)
        {
            if (command == DOBUF_UNLOAD)
            {
                 strcpy((char *)(IObuff), (char *)(_(e_no_buffers_were_unloaded))) ;
            }
            else if (command == DOBUF_DEL)
            {
                 strcpy((char *)(IObuff), (char *)(_(e_no_buffers_were_deleted))) ;
            }
            else
            {
                 strcpy((char *)(IObuff), (char *)(_(e_no_buffers_were_wiped_out))) ;
            }
            errormsg = (char *)IObuff;
        }
        else if (deleted >= p_report)
        {
            if (command == DOBUF_UNLOAD)
            {
                smsg(NGETTEXT("%d buffer unloaded", "%d buffers unloaded", deleted), deleted);
            }
            else if (command == DOBUF_DEL)
            {
                smsg(NGETTEXT("%d buffer deleted", "%d buffers deleted", deleted), deleted);
            }
            else
            {
                smsg(NGETTEXT("%d buffer wiped out", "%d buffers wiped out", deleted), deleted);
            }
        }
    }

    return errormsg;
}

    static void
set_curbuf(buf_T *buf, int action)
{
    buf_T       *prevbuf;
    int         unload = (action == DOBUF_UNLOAD || action == DOBUF_DEL || action == DOBUF_WIPE || action == DOBUF_WIPE_REUSE);
    bufref_T    newbufref;
    bufref_T    prevbufref;
    int         valid;

    setpcmark();
    if ((cmdmod.cmod_flags & CMOD_KEEPALT) == 0)
    {
        curwin->w_alt_fnum = curbuf->b_fnum;
    }
    buflist_altfpos(curwin);

    VIsual_reselect = FALSE;

    prevbuf = curbuf;
    set_bufref(&prevbufref, prevbuf);
    set_bufref(&newbufref, buf);

    if (!apply_autocmds(EVENT_BUFLEAVE, NULL, NULL, FALSE, curbuf) || (bufref_valid(&prevbufref) && bufref_valid(&newbufref)))
    {
        if (unload)
        {
            close_windows(prevbuf, FALSE);
        }
        if (bufref_valid(&prevbufref))
        {
            if (prevbuf == curbuf && ((State & MODE_INSERT) == 0 || curbuf->b_nwindows <= 1))
            {
                u_sync(FALSE);
            }
            close_buffer(curwin, prevbuf, unload ? action : (action == DOBUF_GOTO && !buf_hide(prevbuf) && !bufIsChanged(prevbuf)) ? DOBUF_UNLOAD : 0, FALSE, FALSE, TRUE);
        }
    }
    valid = buf_valid(buf);
    if ((valid && buf != curbuf) || curwin->w_buffer == NULL)
    {
        if (!valid)
        {
            enter_buffer(lastbuf);
        }
        else
        {
            enter_buffer(buf);
        }
    }
}

    static void
enter_buffer(buf_T *buf)
{
    if (VIsual_active)
    {
        end_visual_mode();
    }

    if (curwin->w_buffer != NULL)
    {
        --curwin->w_buffer->b_nwindows;
    }

    curwin->w_buffer = buf;
    curbuf = buf;
    ++curbuf->b_nwindows;

    buf_copy_options(buf, BCO_ENTER | BCO_NOHELP);
    if (!buf->b_help)
    {
        get_winopts(buf);
    }

    curwin->w_cursor.lnum = 1;
    curwin->w_cursor.col = 0;
    curwin->w_cursor.coladd = 0;
    curwin->w_set_curswant = true;
    curwin->w_topline_was_set = false;

    curwin->w_valid = 0;

    if (curbuf->b_ml.ml_mfp == NULL)
    {
        if (*curbuf->b_p_ft == NUL)
        {
            curbuf->b_did_filetype = false;
        }

        open_buffer(FALSE, NULL, 0);
    }
    else
    {
        if (!msg_silent && !shortmess(SHM_FILEINFO))
        {
            need_fileinfo = TRUE;
        }

        curwin->w_topline = 1;
        apply_autocmds(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf);
        apply_autocmds(EVENT_BUFWINENTER, NULL, NULL, FALSE, curbuf);
    }

    if (curwin->w_cursor.lnum == 1 && inindent(0))
    {
        buflist_getfpos();
    }

    check_arg_idx(curwin);
    maketitle();
    if (curwin->w_topline == 1 && !curwin->w_topline_was_set)
    {
        scroll_cursor_halfway(FALSE, FALSE);
    }

    redraw_later(UPD_NOT_VALID);
}

    static void
no_write_message_buf(buf_T *buf)
{
        semsg(_(e_no_write_since_last_change_for_buffer_nr_add_bang_to_override), buf->b_fnum);
}

    static void
no_write_message(void)
{
        emsg(_(e_no_write_since_last_change_add_bang_to_override));
}

    static void
no_write_message_nobang(buf_T *buf  __attribute__((unused)) )
{
        emsg(_(e_no_write_since_last_change));
}

    static int
curbuf_reusable(void)
{
    return (curbuf != NULL && curbuf->b_ffname == NULL && curbuf->b_nwindows <= 1 && (curbuf->b_ml.ml_mfp == NULL ||  (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) ) && !bt_quickfix(curbuf) && !curbufIsChanged());
}

    static buf_T *
buflist_new(char_u      *ffname_arg, char_u      *sfname_arg, linenr_T    lnum, int         flags)
{
    char_u      *ffname = ffname_arg;
    char_u      *sfname = sfname_arg;
    buf_T       *buf;
    stat_T      st;

    if (top_file_num == 1)
    {
        hash_init(&buf_hashtab);
    }

    fname_expand(curbuf, &ffname, &sfname);

    if (sfname == NULL ||  stat(((char *)sfname), (&st))  < 0)
    {
        st.st_dev = ( dev_t )-1;
    }
    if (ffname != NULL && !(flags & (BLN_DUMMY | BLN_NEW)) && (buf = buflist_findname_stat(ffname, &st)) != NULL)
    {
        vim_free(ffname);
        if (lnum != 0)
        {
            buflist_setfpos(buf, (flags & BLN_NOCURWIN) ? NULL : curwin, lnum, (colnr_T)0, FALSE);
        }

        if ((flags & BLN_NOOPT) == 0)
        {
            buf_copy_options(buf, 0);
        }

        if ((flags & BLN_LISTED) && !buf->b_p_bl)
        {
            bufref_T bufref;

            buf->b_p_bl = TRUE;
            set_bufref(&bufref, buf);
            if (!(flags & BLN_DUMMY))
            {
                if (apply_autocmds(EVENT_BUFADD, NULL, NULL, FALSE, buf) && !bufref_valid(&bufref))
                {
                    return NULL;
                }
            }
        }
        return buf;
    }

    buf = NULL;
    if ((flags & BLN_CURBUF) && curbuf_reusable())
    {
        bufref_T bufref;

        buf = curbuf;
        set_bufref(&bufref, buf);
        trigger_undo_ftplugin(buf, curwin);
        buf_freeall(buf, BFA_WIPE | BFA_DEL);
        if (!bufref_valid(&bufref))
        {
            buf = NULL;
        }
    }
    if (buf != curbuf || curbuf == NULL)
    {
        buf =  (buf_T *)alloc_clear(sizeof(buf_T)) ;
        if (buf == NULL)
        {
            vim_free(ffname);
            return NULL;
        }
        init_changedtick(buf);
    }

    if (ffname != NULL)
    {
        buf->b_ffname = ffname;
        buf->b_sfname = vim_strsave(sfname);
    }

    clear_wininfo(buf);
    buf->b_wininfo =  (wininfo_T *)alloc_clear(sizeof(wininfo_T)) ;

    if ((ffname != NULL && (buf->b_ffname == NULL || buf->b_sfname == NULL)) || buf->b_wininfo == NULL)
    {
        if (buf->b_sfname != buf->b_ffname)
        {
             vim_free(buf->b_sfname);
             (buf->b_sfname) = NULL;
        }
        else
        {
            buf->b_sfname = NULL;
        }
         vim_free(buf->b_ffname);
         (buf->b_ffname) = NULL;
        if (buf != curbuf)
        {
            free_buffer(buf);
        }
        return NULL;
    }

    if (buf == curbuf)
    {
        free_buffer_stuff(buf, FALSE);

        buf->b_p_initialized = false;
        buf_copy_options(buf, BCO_ENTER);

    }
    else
    {
        buf->b_next = NULL;
        if (firstbuf == NULL)
        {
            buf->b_prev = NULL;
            firstbuf = buf;
        }
        else
        {
            lastbuf->b_next = buf;
            buf->b_prev = lastbuf;
        }
        lastbuf = buf;

        if ((flags & BLN_REUSE) && buf_reuse.ga_len > 0)
        {
            --buf_reuse.ga_len;
            buf->b_fnum = ((int *)buf_reuse.ga_data)[buf_reuse.ga_len];

            while (buf->b_prev != NULL && buf->b_fnum < buf->b_prev->b_fnum)
            {
                buf_T   *prev = buf->b_prev;

                prev->b_next = buf->b_next;
                if (prev->b_next != NULL)
                {
                    prev->b_next->b_prev = prev;
                }
                buf->b_next = prev;
                buf->b_prev = prev->b_prev;
                if (buf->b_prev != NULL)
                {
                    buf->b_prev->b_next = buf;
                }
                prev->b_prev = buf;
                if (lastbuf == buf)
                {
                    lastbuf = prev;
                }
                if (firstbuf == prev)
                {
                    firstbuf = buf;
                }
            }
        }
        else
        {
            buf->b_fnum = top_file_num++;
        }
        if (top_file_num < 0)
        {
            emsg(_("W14: Warning: List of file names overflow"));
            if (emsg_silent == 0 && !in_assert_fails)
            {
                out_flush();
                ui_delay(3001L, TRUE);
            }
            top_file_num = 1;
        }
        buf_hashtab_add(buf);

        buf_copy_options(buf, BCO_ALWAYS);
    }

    buf->b_wininfo->wi_fpos.lnum = lnum;
    buf->b_wininfo->wi_win = curwin;

    buf->b_fname = buf->b_sfname;
    if (st.st_dev == ( dev_t )-1)
    {
        buf->b_dev_valid = false;
    }
    else
    {
        buf->b_dev_valid = true;
        buf->b_dev = st.st_dev;
        buf->b_ino = st.st_ino;
    }
    buf->b_u_synced = true;
    buf->b_flags = BF_CHECK_RO | BF_NEVERLOADED;
    if (flags & BLN_DUMMY)
    {
        buf->b_flags |= BF_DUMMY;
    }
    buf_clear_file(buf);
    clrallmarks(buf);
    fmarks_check_names(buf);
    buf->b_p_bl = (flags & BLN_LISTED) ? TRUE : FALSE;
    if (!(flags & BLN_DUMMY))
    {
        bufref_T bufref;

        set_bufref(&bufref, buf);
        if (apply_autocmds(EVENT_BUFNEW, NULL, NULL, FALSE, buf) && !bufref_valid(&bufref))
        {
            return NULL;
        }
        if (flags & BLN_LISTED)
        {
            if (apply_autocmds(EVENT_BUFADD, NULL, NULL, FALSE, buf) && !bufref_valid(&bufref))
            {
                return NULL;
            }
        }
    }

    return buf;
}

