    static int
buflist_getfile(int         n, linenr_T    lnum, int         options, int         forceit)
{
    buf_T       *buf;
    win_T       *wp = NULL;
    pos_T       *fpos;
    colnr_T     col;

    buf = buflist_findnr(n);
    if (buf == NULL)
    {
        if ((options & GETF_ALT) && n == 0)
        {
            emsg(_(e_no_alternate_file));
        }
        else
        {
            semsg(_(e_buffer_nr_not_found), n);
        }
        return FAIL;
    }

    if (buf == curbuf)
    {
        return OK;
    }

    if (text_or_buf_locked())
    {
        return FAIL;
    }

    if (lnum == 0)
    {
        fpos = buflist_findfpos(buf);
        lnum = fpos->lnum;
        col = fpos->col;
    }
    else
    {
        col = 0;
    }

    if (options & GETF_SWITCH)
    {
        wp = swbuf_goto_win_with_buf(buf);

        if (wp == NULL && (swb_flags & (SWB_VSPLIT | SWB_SPLIT | SWB_NEWTAB)) && ! (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) )
        {
            if (swb_flags & SWB_NEWTAB)
            {
                tabpage_new();
            }
            else if (win_split(0, (swb_flags & SWB_VSPLIT) ? WSP_VERT : 0) == FAIL)
            {
                return FAIL;
            }
             (curwin)-> w_onebuf_opt.wo_scb  = FALSE;
             (curwin)-> w_onebuf_opt.wo_crb  = FALSE;
        }
    }

    ++RedrawingDisabled;
    int retval = FAIL;
    if ( ((getfile(buf->b_fnum, NULL, NULL, (options & GETF_SETMARK), lnum, forceit)) <= 0) )
    {
        if (!p_sol && col != 0)
        {
            curwin->w_cursor.col = col;
            check_cursor_col();
            curwin->w_cursor.coladd = 0;
            curwin->w_set_curswant = true;
        }
        retval = OK;
    }

    if (RedrawingDisabled > 0)
    {
        --RedrawingDisabled;
    }
    return retval;
}

    static void
buflist_getfpos(void)
{
    pos_T       *fpos;

    fpos = buflist_findfpos(curbuf);

    curwin->w_cursor.lnum = fpos->lnum;
    check_cursor_lnum();

    if (p_sol)
    {
        curwin->w_cursor.col = 0;
    }
    else
    {
        curwin->w_cursor.col = fpos->col;
        check_cursor_col();
        curwin->w_cursor.coladd = 0;
        curwin->w_set_curswant = true;
    }
}

