                        for (col = 0; col < our_paren_pos.col; ++col)
                        {
                            switch (l[col])
                            {
                                case '(':
                                case '{':
                                    ++n;
                                          break;

                                case ')':
                                case '}':
                                    if (n > 1)
                                    {
                                              --n;
                                    }
                                          break;
                            }
                        }

                        our_paren_pos.col = 0;
                        amount += n * curbuf->b_ind_unclosed_wrapped;
