    static int
get_lcs_ext(win_T *wp)
{
    if (wp-> w_onebuf_opt.wo_wrap )
    {
        return NUL;
    }
    if (wp-> w_onebuf_opt.wo_wrap_flags  & P_INSECURE)
    {
        return '>';
    }
    return wp-> w_onebuf_opt.wo_list  ? wp->w_lcs_chars.ext : NUL;
}

