    static int
ins_tab(void)
{
    int         ind;
    int         i;
    int         temp;

    if (Insstart_blank_vcol == MAXCOL && curwin->w_cursor.lnum == Insstart.lnum)
    {
        Insstart_blank_vcol = get_nolist_virtcol();
    }
    if (echeck_abbr(TAB + ABBR_OFF))
    {
        return FALSE;
    }

    ind = inindent(0);
    if (ind)
    {
        can_cindent = FALSE;
    }

    if (!curbuf->b_p_et && !(p_sta && ind && curbuf->b_p_ts != get_sw_value(curbuf)) && get_sts_value() == 0)
    {
        return TRUE;
    }

    if (stop_arrow() == FAIL)
    {
        return TRUE;
    }

    did_ai = FALSE;
    did_si = FALSE;
    can_si = FALSE;
    can_si_back = FALSE;
    AppendToRedobuff((char_u *)"\t");

    if (p_sta && ind)
    {
        temp = (int)get_sw_value(curbuf);
    }
    else if (curbuf->b_p_sts != 0)
    {
        temp = (int)get_sts_value();
    }
    else
    {
        temp = (int)curbuf->b_p_ts;
    }
    temp -= get_nolist_virtcol() % temp;

    ins_char(' ');
    while (--temp > 0)
    {
        if (State & VREPLACE_FLAG)
        {
            ins_char(' ');
        }
        else
        {
            ins_str((char_u *)" ", 1);
            if (State & REPLACE_FLAG)
            {
                replace_push(NUL);
            }
        }
    }

    if (!curbuf->b_p_et && (get_sts_value() || (p_sta && ind)))
    {
        char_u          *ptr;
        char_u          *saved_line = NULL;
        pos_T           pos;
        pos_T           fpos;
        pos_T           *cursor;
        colnr_T want_vcol;
        colnr_T vcol;
        int             change_col = -1;
        int             save_list = curwin-> w_onebuf_opt.wo_list ;
        char_u          *tab = (char_u *)"\t";
        chartabsize_T   cts;

        if (State & VREPLACE_FLAG)
        {
            pos = curwin->w_cursor;
            cursor = &pos;
            saved_line = vim_strnsave(ml_get_curline(), ml_get_curline_len());
            if (saved_line == NULL)
            {
                return FALSE;
            }
            ptr = saved_line + pos.col;
        }
        else
        {
            ptr = ml_get_cursor();
            cursor = &curwin->w_cursor;
        }

        if (vim_strchr(p_cpo, CPO_LISTWM) == NULL)
        {
            curwin-> w_onebuf_opt.wo_list  = FALSE;
        }

        fpos = curwin->w_cursor;
        while (fpos.col > 0 &&  ((ptr[-1]) == ' ' || (ptr[-1]) == '\t') )
        {
            --fpos.col;
            --ptr;
        }

        if ((State & REPLACE_FLAG) && fpos.lnum == Insstart.lnum && fpos.col < Insstart.col)
        {
            ptr += Insstart.col - fpos.col;
            fpos.col = Insstart.col;
        }

        getvcol(curwin, &fpos, &vcol, NULL, NULL, 0);
        getvcol(curwin, cursor, &want_vcol, NULL, NULL, 0);

        init_chartabsize_arg(&cts, curwin, 0, vcol, tab, tab);

        while ( ((*ptr) == ' ' || (*ptr) == '\t') )
        {
            i = lbr_chartabsize(&cts);
            if (cts.cts_vcol + i > want_vcol)
            {
                break;
            }
            if (*ptr != TAB)
            {
                *ptr = TAB;
                if (change_col < 0)
                {
                    change_col = fpos.col;
                    if (fpos.lnum == Insstart.lnum && fpos.col < Insstart.col)
                    {
                        Insstart.col = fpos.col;
                    }
                }
            }
            ++fpos.col;
            ++ptr;
            cts.cts_vcol += i;
        }
        vcol = cts.cts_vcol;
        clear_chartabsize_arg(&cts);

        if (change_col >= 0)
        {
            int             repl_off = 0;

            init_chartabsize_arg(&cts, curwin, 0, vcol, ptr, ptr);
            while (cts.cts_vcol < want_vcol && *cts.cts_ptr == ' ')
            {
                cts.cts_vcol += lbr_chartabsize(&cts);
                ++cts.cts_ptr;
                ++repl_off;
            }
            ptr = cts.cts_ptr;
            vcol = cts.cts_vcol;
            clear_chartabsize_arg(&cts);

            if (vcol > want_vcol)
            {
                --ptr;
                --repl_off;
            }
            fpos.col += repl_off;

            i = cursor->col - fpos.col;
            if (i > 0)
            {
                      memmove((char *)((ptr)), (char *)((ptr + i)),  strlen((char *)(ptr + i))  + 1)  ;
                if ((State & REPLACE_FLAG) && !(State & VREPLACE_FLAG))
                {
                    for (temp = i; --temp >= 0; )
                    {
                        replace_join(repl_off);
                    }
                }
            }
            cursor->col -= i;

            if (State & VREPLACE_FLAG)
            {
                backspace_until_column(change_col);

                ins_bytes_len(saved_line + change_col, cursor->col - change_col);
            }
        }

        if (State & VREPLACE_FLAG)
        {
            vim_free(saved_line);
        }
        curwin-> w_onebuf_opt.wo_list  = save_list;
    }

    return FALSE;
}

    static int
ins_eol(int c)
{
    int     i;

    if (echeck_abbr(c + ABBR_OFF))
    {
        return OK;
    }
    if (stop_arrow() == FAIL)
    {
        return FAIL;
    }
    undisplay_dollar();

    if ((State & REPLACE_FLAG) && !(State & VREPLACE_FLAG))
    {
        replace_push(NUL);
    }

    if (virtual_active() && curwin->w_cursor.coladd > 0)
    {
        coladvance(getviscol());
    }

    AppendToRedobuff( (char_u *)"\012" );
    i = open_line(FORWARD, has_format_option(FO_RET_COMS) ? OPENLINE_DO_COM : 0, old_indent, NULL);
    old_indent = 0;
    can_cindent = TRUE;

    return i;
}

    static int
ins_copychar(linenr_T lnum)
{
    int             c;
    char_u *ptr;
    char_u *prev_ptr;
    char_u          *line;
    chartabsize_T   cts;

    if (lnum < 1 || lnum > curbuf->b_ml.ml_line_count)
    {
        vim_beep(BO_COPY);
        return NUL;
    }

    validate_virtcol();
    line = ml_get(lnum);
    prev_ptr = line;
    init_chartabsize_arg(&cts, curwin, lnum, 0, line, line);
    while (cts.cts_vcol < curwin->w_virtcol && *cts.cts_ptr != NUL)
    {
        prev_ptr = cts.cts_ptr;
        cts.cts_vcol += lbr_chartabsize_adv(&cts);
    }
    if (cts.cts_vcol > curwin->w_virtcol)
    {
        ptr = prev_ptr;
    }
    else
    {
        ptr = cts.cts_ptr;
    }
    clear_chartabsize_arg(&cts);

    c = (*mb_ptr2char)(ptr);
    if (c == NUL)
    {
        vim_beep(BO_COPY);
    }
    return c;
}

    static int
ins_ctrl_ey(int tc)
{
    int     c = tc;

    if (ctrl_x_mode_scroll())
    {
        if (c == Ctrl_Y)
        {
            scrolldown_clamp();
        }
        else
        {
            scrollup_clamp();
        }
        redraw_later(UPD_VALID);
    }
    else
    {
        c = ins_copychar(curwin->w_cursor.lnum + (c == Ctrl_Y ? -1 : 1));
        if (c != NUL)
        {
            long        tw_save;

            if (c < 256 && ! (isalnum ((unsigned char)(c))) )
            {
                AppendToRedobuff((char_u *) "\026" );
            }
            tw_save = curbuf->b_p_tw;
            curbuf->b_p_tw = -1;
            insert_special(c, TRUE, FALSE);
            curbuf->b_p_tw = tw_save;
            c = Ctrl_V;
            auto_format(FALSE, TRUE);
        }
    }
    return c;
}

    static colnr_T
get_nolist_virtcol(void)
{
    if (curwin->w_buffer == NULL || curwin->w_buffer->b_ml.ml_mfp == NULL || curwin->w_cursor.lnum > curwin->w_buffer->b_ml.ml_line_count)
    {
        return 0;
    }
    if (curwin-> w_onebuf_opt.wo_list  && vim_strchr(p_cpo, CPO_LISTWM) == NULL)
    {
        return getvcol_nolist(&curwin->w_cursor);
    }
    validate_virtcol();
    return curwin->w_virtcol;
}

