    static void
do_ascii(exarg_T *eap  __attribute__((unused)) )
{
    int         c;
    int         cval;
    char        buf1[20];
    char        buf2[20];
    char_u      buf3[7];
    int         cc[MAX_MCO];
    int         ci = 0;
    int         len;

    if (enc_utf8)
    {
        c = utfc_ptr2char(ml_get_cursor(), cc);
    }
    else
    {
        c = gchar_cursor();
    }
    if (c == NUL)
    {
        msg("NUL");
        return;
    }

    IObuff[0] = NUL;
    if (!has_mbyte || (enc_dbcs != 0 && c < 0x100) || c < 0x80)
    {
        if (c == NL)
        {
            c = NUL;
        }
        if (c == CAR && get_fileformat(curbuf) == EOL_MAC)
        {
            cval = NL;
        }
        else
        {
            cval = c;
        }
        if (vim_isprintc_strict(c) && (c < ' ' || c > '~'))
        {
            transchar_nonprint(curbuf, buf3, c);
            vim_snprintf(buf1, sizeof(buf1), "  <%s>", (char *)buf3);
        }
        else
        {
            buf1[0] = NUL;
        }
        if (c >= 0x80)
        {
            vim_snprintf(buf2, sizeof(buf2), "  <M-%s>", (char *)transchar(c & 0x7f));
        }
        else
        {
            buf2[0] = NUL;
        }
            vim_snprintf((char *)IObuff,  (1024+1) , _("<%s>%s%s  %d,  Hex %02x,  Octal %03o"), transchar(c), buf1, buf2, cval, cval, cval);
        if (enc_utf8)
        {
            c = cc[ci++];
        }
        else
        {
            c = 0;
        }
    }

    while (has_mbyte && (c >= 0x100 || (enc_utf8 && c >= 0x80)))
    {
        len = (int) strlen((char *)(IObuff)) ;
        if (len > 0)
        {
            IObuff[len++] = ' ';
        }
        IObuff[len++] = '<';
        if (enc_utf8 && utf_iscomposing(c))
        {
            IObuff[len++] = ' ';
        }
        len += (*mb_char2bytes)(c, IObuff + len);
            vim_snprintf((char *)IObuff + len,  (1024+1)  - len, c < 0x10000 ? _("> %d, Hex %04x, Octal %o") : _("> %d, Hex %08x, Octal %o"), c, c, c);
        if (ci == MAX_MCO)
        {
            break;
        }
        if (enc_utf8)
        {
            c = cc[ci++];
        }
        else
        {
            c = 0;
        }
    }

    msg((char *)IObuff);
}

    static void
ex_align(exarg_T *eap)
{
    pos_T       save_curpos;
    int         len;
    int         indent = 0;
    int         new_indent;
    int         has_tab;
    int         width;

    width = atoi((char *)eap->arg);
    save_curpos = curwin->w_cursor;
    if (eap->cmdidx == CMD_left)
    {
        if (width >= 0)
        {
            indent = width;
        }
    }
    else
    {
        if (width <= 0)
        {
            width = curbuf->b_p_tw;
        }
        if (width == 0 && curbuf->b_p_wm > 0)
        {
            width = curwin->w_width - curbuf->b_p_wm;
        }
        if (width <= 0)
        {
            width = 80;
        }
    }

    if (u_save((linenr_T)(eap->line1 - 1), (linenr_T)(eap->line2 + 1)) == FAIL)
    {
        return;
    }

    for (curwin->w_cursor.lnum = eap->line1; curwin->w_cursor.lnum <= eap->line2; ++curwin->w_cursor.lnum)
    {
        if (eap->cmdidx == CMD_left)
        {
            new_indent = indent;
        }
        else
        {
            has_tab = FALSE;
            len = linelen(eap->cmdidx == CMD_right ? &has_tab : NULL) - get_indent();

            if (len <= 0)
            {
                continue;
            }

            if (eap->cmdidx == CMD_center)
            {
                new_indent = (width - len) / 2;
            }
            else
            {
                new_indent = width - len;

                if (has_tab)
                {
                    while (new_indent > 0)
                    {
                        (void)set_indent(new_indent, 0);
                        if (linelen(NULL) <= width)
                        {
                            do
                            {
                                (void)set_indent(++new_indent, 0);
                            }
                            while (linelen(NULL) <= width)
                                ;
                            --new_indent;
                            break;
                        }
                        --new_indent;
                    }
                }
            }
        }
        if (new_indent < 0)
        {
            new_indent = 0;
        }
        (void)set_indent(new_indent, 0);
    }
    changed_lines(eap->line1, 0, eap->line2 + 1, 0L);
    curwin->w_cursor = save_curpos;
    beginline(BL_WHITE | BL_FIX);
}

    static int
linelen(int *has_tab)
{
    char_u  *line;
    char_u  *first;
    char_u  *last;
    int     save;
    int     len;

    line = ml_get_curline();
    if (*line == NUL)
    {
        return 0;
    }

    first = skipwhite(line);

    for (last = first +  strlen((char *)(first)) ; last > first &&  ((last[-1]) == ' ' || (last[-1]) == '\t') ; --last)
    {
        ;
    }
    save = *last;
    *last = NUL;
    len = linetabsize_str(line);
    if (has_tab != NULL)
    {
        *has_tab = (vim_strchr(first, TAB) != NULL);
    }
    *last = save;

    return len;
}

