    static int
string_sort_compare(const void *s1, const void *s2)
{
    sorti_T     l1 = *(sorti_T *)s1;
    sorti_T     l2 = *(sorti_T *)s2;
    int         result = 0;

    if (sort_abort)
    {
        return 0;
    }
    fast_breakcheck();
    if (got_int)
    {
        sort_abort = TRUE;
    }

    if (sort_nr)
    {
        if (l1.st_u.num.is_number != l2.st_u.num.is_number)
        {
            result = l1.st_u.num.is_number > l2.st_u.num.is_number ? 1 : -1;
        }
        else
        {
            result = l1.st_u.num.value == l2.st_u.num.value ? 0
                             : l1.st_u.num.value > l2.st_u.num.value ? 1 : -1;
        }
    }
    else if (sort_flt)
    {
        result = l1.st_u.value_flt == l2.st_u.value_flt ? 0
                             : l1.st_u.value_flt > l2.st_u.value_flt ? 1 : -1;
    }
    else
    {
         strncpy((char *)(sortbuf1), (char *)(ml_get(l1.lnum) + l1.st_u.line.start_col_nr), (l1.st_u.line.end_col_nr - l1.st_u.line.start_col_nr + 1)) ;
        sortbuf1[l1.st_u.line.end_col_nr - l1.st_u.line.start_col_nr] = 0;
         strncpy((char *)(sortbuf2), (char *)(ml_get(l2.lnum) + l2.st_u.line.start_col_nr), (l2.st_u.line.end_col_nr - l2.st_u.line.start_col_nr + 1)) ;
        sortbuf2[l2.st_u.line.end_col_nr - l2.st_u.line.start_col_nr] = 0;

        result = string_compare(sortbuf1, sortbuf2);
    }

    if (result == 0)
    {
        return (int)(l1.lnum - l2.lnum);
    }
    return result;
}

    static void
ex_sort(exarg_T *eap)
{
    regmatch_T  regmatch;
    int         len;
    linenr_T    lnum;
    long        maxlen = 0;
    sorti_T     *nrs;
    size_t      count = (size_t)(eap->line2 - eap->line1 + 1);
    size_t      i;
    char_u      *p;
    char_u      *s;
    char_u      *s2;
    char_u      c;
    int         unique = FALSE;
    long        deleted;
    colnr_T     start_col;
    colnr_T     end_col;
    int         sort_what = 0;
    int         format_found = 0;
    int         change_occurred = FALSE;

    if (count <= 1)
    {
        return;
    }

    if (u_save((linenr_T)(eap->line1 - 1), (linenr_T)(eap->line2 + 1)) == FAIL)
    {
        return;
    }
    sortbuf1 = NULL;
    sortbuf2 = NULL;
    regmatch.regprog = NULL;
    nrs =  (sorti_T *)alloc(sizeof(sorti_T) * (count)) ;
    if (nrs == NULL)
    {
        goto sortend;
    }

    sort_abort = sort_ic = sort_lc = sort_rx = sort_nr = 0;
    sort_flt = 0;

    for (p = eap->arg; *p != NUL; ++p)
    {
        if ( ((*p) == ' ' || (*p) == '\t') )
        {
            ;
        }
        else if (*p == 'i')
        {
            sort_ic = TRUE;
        }
        else if (*p == 'l')
        {
            sort_lc = TRUE;
        }
        else if (*p == 'r')
        {
            sort_rx = TRUE;
        }
        else if (*p == 'n')
        {
            sort_nr = 1;
            ++format_found;
        }
        else if (*p == 'f')
        {
            sort_flt = 1;
            ++format_found;
        }
        else if (*p == 'b')
        {
            sort_what = STR2NR_BIN + STR2NR_FORCE;
            ++format_found;
        }
        else if (*p == 'o')
        {
            sort_what = STR2NR_OCT + STR2NR_FORCE;
            ++format_found;
        }
        else if (*p == 'x')
        {
            sort_what = STR2NR_HEX + STR2NR_FORCE;
            ++format_found;
        }
        else if (*p == 'u')
        {
            unique = TRUE;
        }
        else if (*p == '"')
        {
            break;
        }
        else if (eap->nextcmd == NULL && check_nextcmd(p) != NULL)
        {
            eap->nextcmd = check_nextcmd(p);
            break;
        }
        else if (! ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  && regmatch.regprog == NULL)
        {
            s = skip_regexp_err(p + 1, *p, TRUE);
            if (s == NULL)
            {
                goto sortend;
            }
            *s = NUL;
            if (s == p + 1)
            {
                if (last_search_pat() == NULL)
                {
                    emsg(_(e_no_previous_regular_expression));
                    goto sortend;
                }
                regmatch.regprog = vim_regcomp(last_search_pat(), RE_MAGIC);
            }
            else
            {
                regmatch.regprog = vim_regcomp(p + 1, RE_MAGIC);
            }
            if (regmatch.regprog == NULL)
            {
                goto sortend;
            }
            p = s;
            regmatch.rm_ic = p_ic;
        }
        else
        {
            semsg(_(e_invalid_argument_str), p);
            goto sortend;
        }
    }

    if (format_found > 1)
    {
        emsg(_(e_invalid_argument));
        goto sortend;
    }

    sort_nr += sort_what;

    for (lnum = eap->line1; lnum <= eap->line2; ++lnum)
    {
        s = ml_get(lnum);
        len = ml_get_len(lnum);
        if (maxlen < len)
        {
            maxlen = len;
        }

        start_col = 0;
        end_col = len;
        if (regmatch.regprog != NULL && vim_regexec(&regmatch, s, 0))
        {
            if (sort_rx)
            {
                start_col = (colnr_T)(regmatch.startp[0] - s);
                end_col = (colnr_T)(regmatch.endp[0] - s);
            }
            else
            {
                start_col = (colnr_T)(regmatch.endp[0] - s);
            }
        }
        else
        {
            if (regmatch.regprog != NULL)
            {
                end_col = 0;
            }
        }

        if (sort_nr || sort_flt)
        {
            s2 = s + end_col;
            c = *s2;
            *s2 = NUL;
            p = s + start_col;
            if (sort_nr)
            {
                if (sort_what & STR2NR_HEX)
                {
                    s = skiptohex(p);
                }
                else if (sort_what & STR2NR_BIN)
                {
                    s = skiptobin(p);
                }
                else
                {
                    s = skiptodigit(p);
                }
                if (s > p && s[-1] == '-')
                {
                    --s;
                }
                if (*s == NUL)
                {
                    nrs[lnum - eap->line1].st_u.num.is_number = FALSE;
                    nrs[lnum - eap->line1].st_u.num.value = 0;
                }
                else
                {
                    nrs[lnum - eap->line1].st_u.num.is_number = TRUE;
                    vim_str2nr(s, NULL, NULL, sort_what, &nrs[lnum - eap->line1].st_u.num.value, NULL, 0, FALSE, NULL);
                }
            }
            else
            {
                s = skipwhite(p);
                if (*s == '+')
                {
                    s = skipwhite(s + 1);
                }

                if (*s == NUL)
                {
                    nrs[lnum - eap->line1].st_u.value_flt = -DBL_MAX;
                }
                else
                {
                    nrs[lnum - eap->line1].st_u.value_flt =
                                                      strtod((char *)s, NULL);
                }
            }
            *s2 = c;
        }
        else
        {
            nrs[lnum - eap->line1].st_u.line.start_col_nr = start_col;
            nrs[lnum - eap->line1].st_u.line.end_col_nr = end_col;
        }

        nrs[lnum - eap->line1].lnum = lnum;

        if (regmatch.regprog != NULL)
        {
            fast_breakcheck();
        }
        if (got_int)
        {
            goto sortend;
        }
    }

    sortbuf1 = alloc(maxlen + 1);
    if (sortbuf1 == NULL)
    {
        goto sortend;
    }
    sortbuf2 = alloc(maxlen + 1);
    if (sortbuf2 == NULL)
    {
        goto sortend;
    }

    qsort((void *)nrs, count, sizeof(sorti_T), string_sort_compare);

    if (sort_abort)
    {
        goto sortend;
    }

    lnum = eap->line2;
    for (i = 0; i < count; ++i)
    {
        linenr_T get_lnum = nrs[eap->forceit ? count - i - 1 : i].lnum;

        if (get_lnum + ((linenr_T)count - 1) != lnum)
        {
            change_occurred = TRUE;
        }

        s = ml_get(get_lnum);
        if (!unique || i == 0 || string_compare(s, sortbuf1) != 0)
        {
             strcpy((char *)(sortbuf1), (char *)(s)) ;
            if (ml_append(lnum++, sortbuf1, (colnr_T)0, FALSE) == FAIL)
            {
                break;
            }
        }
        fast_breakcheck();
        if (got_int)
        {
            goto sortend;
        }
    }

    if (i == count)
    {
        for (i = 0; i < count; ++i)
        {
            ml_delete(eap->line1);
        }
    }
    else
    {
        count = 0;
    }

    deleted = (long)(count - (lnum - eap->line2));
    if (deleted > 0)
    {
        mark_adjust(eap->line2 - deleted, eap->line2, (long) LONG_MAX , -deleted);
        msgmore(-deleted);
    }
    else if (deleted < 0)
    {
        mark_adjust(eap->line2,  LONG_MAX , -deleted, 0L);
    }

    if (change_occurred || deleted != 0)
    {
        changed_lines(eap->line1, 0, eap->line2 + 1, -deleted);
    }

    curwin->w_cursor.lnum = eap->line1;
    beginline(BL_WHITE | BL_FIX);

sortend:
    vim_free(nrs);
    vim_free(sortbuf1);
    vim_free(sortbuf2);
    vim_regfree(regmatch.regprog);
    if (got_int)
    {
        emsg(_(e_interrupted));
    }
}

    static void
ex_uniq(exarg_T *eap)
{
    regmatch_T  regmatch;
    int         len;
    linenr_T    lnum;
    long        maxlen = 0;
    linenr_T    count = eap->line2 - eap->line1 + 1;
    char_u      *p;
    char_u      *s;
    char_u      save_c = 0;
    int         keep_only_unique = FALSE;
    int         keep_only_not_unique = eap->forceit ? TRUE : FALSE;
    long        deleted = 0;
    colnr_T     start_col;
    colnr_T     end_col;
    int         change_occurred = FALSE;

    if (count <= 1)
    {
        return;
    }

    if (u_save((linenr_T)(eap->line1 - 1), (linenr_T)(eap->line2 + 1)) == FAIL)
    {
        return;
    }
    sortbuf1 = NULL;
    regmatch.regprog = NULL;

    sort_abort = sort_ic = sort_lc = sort_rx = sort_nr = 0;
    sort_flt = 0;

    for (p = eap->arg; *p != NUL; ++p)
    {
        if ( ((*p) == ' ' || (*p) == '\t') )
        {
            ;
        }
        else if (*p == 'i')
        {
            sort_ic = TRUE;
        }
        else if (*p == 'l')
        {
            sort_lc = TRUE;
        }
        else if (*p == 'r')
        {
            sort_rx = TRUE;
        }
        else if (*p == 'u')
        {
            if (!keep_only_not_unique)
            {
                keep_only_unique = TRUE;
            }
        }
        else if (*p == '"')
        {
            break;
        }
        else if (eap->nextcmd == NULL && check_nextcmd(p) != NULL)
        {
            eap->nextcmd = check_nextcmd(p);
            break;
        }
        else if (! ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  && regmatch.regprog == NULL)
        {
            s = skip_regexp_err(p + 1, *p, TRUE);
            if (s == NULL)
            {
                goto uniqend;
            }
            *s = NUL;
            if (s == p + 1)
            {
                if (last_search_pat() == NULL)
                {
                    emsg(_(e_no_previous_regular_expression));
                    goto uniqend;
                }
                regmatch.regprog = vim_regcomp(last_search_pat(), RE_MAGIC);
            }
            else
            {
                regmatch.regprog = vim_regcomp(p + 1, RE_MAGIC);
            }
            if (regmatch.regprog == NULL)
            {
                goto uniqend;
            }
            p = s;
            regmatch.rm_ic = p_ic;
        }
        else
        {
            semsg(_(e_invalid_argument_str), p);
            goto uniqend;
        }
    }

    for (lnum = eap->line1; lnum <= eap->line2; ++lnum)
    {
        len = ml_get_len(lnum);
        if (maxlen < len)
        {
            maxlen = len;
        }

        if (got_int)
        {
            goto uniqend;
        }
    }

    sortbuf1 = alloc(maxlen + 1);
    if (sortbuf1 == NULL)
    {
        goto uniqend;
    }

    int match_continue = FALSE;
    int next_is_unmatch = FALSE;
    int is_match;
    linenr_T done_lnum = eap->line1 - 1;
    linenr_T delete_lnum = 0;
    for (linenr_T i = 0; i < count; ++i)
    {
        linenr_T get_lnum = eap->line1 + i;

        s = ml_get(get_lnum);
        len = ml_get_len(get_lnum);

        start_col = 0;
        end_col = len;
        if (regmatch.regprog != NULL && vim_regexec(&regmatch, s, 0))
        {
            if (sort_rx)
            {
                start_col = (colnr_T)(regmatch.startp[0] - s);
                end_col = (colnr_T)(regmatch.endp[0] - s);
            }
            else
            {
                start_col = (colnr_T)(regmatch.endp[0] - s);
            }
        }
        else
        {
            if (regmatch.regprog != NULL)
            {
                end_col = 0;
            }
        }
        if (end_col > 0)
        {
            save_c = s[end_col];
            s[end_col] = NUL;
        }

        is_match = i > 0 ? !string_compare(&s[start_col], sortbuf1) : FALSE;
        delete_lnum = 0;
        if (next_is_unmatch)
        {
            is_match = FALSE;
            next_is_unmatch = FALSE;
        }

        if (!keep_only_unique && !keep_only_not_unique)
        {
            if (is_match)
            {
                delete_lnum = get_lnum;
            }
            else
            {
                 strcpy((char *)(sortbuf1), (char *)(&s[start_col])) ;
            }
        }
        else if (keep_only_not_unique)
        {
            if (is_match)
            {
                done_lnum = get_lnum - 1;
                delete_lnum = get_lnum;
                match_continue = TRUE;
            }
            else
            {
                if (i > 0 && !match_continue && get_lnum - 1 > done_lnum)
                {
                    delete_lnum = get_lnum - 1;
                    next_is_unmatch = TRUE;
                }
                else if (i >= count - 1)
                {
                    delete_lnum = get_lnum;
                }
                match_continue = FALSE;
                 strcpy((char *)(sortbuf1), (char *)(&s[start_col])) ;
            }
        }
        else
        {
            if (is_match)
            {
                if (!match_continue)
                {
                    delete_lnum = get_lnum - 1;
                }
                else
                {
                    delete_lnum = get_lnum;
                }
                match_continue = TRUE;
            }
            else
            {
                if (i == 0 && match_continue)
                {
                    delete_lnum = get_lnum;
                }
                match_continue = FALSE;
                 strcpy((char *)(sortbuf1), (char *)(&s[start_col])) ;
            }
        }

        if (end_col > 0)
        {
            s[end_col] = save_c;
        }

        if (delete_lnum > 0)
        {
            ml_delete(delete_lnum);
            i -= get_lnum - delete_lnum + 1;
            count--;
            deleted++;
            change_occurred = TRUE;
        }

        fast_breakcheck();
        if (got_int)
        {
            goto uniqend;
        }
    }

    mark_adjust(eap->line2 - deleted, eap->line2, (long) LONG_MAX , -deleted);
    msgmore(-deleted);

    if (change_occurred)
    {
        changed_lines(eap->line1, 0, eap->line2 + 1, -deleted);
    }

    curwin->w_cursor.lnum = eap->line1;
    beginline(BL_WHITE | BL_FIX);

uniqend:
    vim_free(sortbuf1);
    vim_regfree(regmatch.regprog);
    if (got_int)
    {
        emsg(_(e_interrupted));
    }
}

    static int
do_move(linenr_T line1, linenr_T line2, linenr_T dest)
{
    char_u      *str;
    linenr_T    l;
    linenr_T    extra;
    linenr_T    num_lines;
    linenr_T    last_line;

    if (dest >= line1 && dest < line2)
    {
        emsg(_(e_cannot_move_range_of_lines_into_itself));
        return FAIL;
    }

    if (dest == line1 - 1 || dest == line2)
    {
        if (dest >= line1)
        {
            curwin->w_cursor.lnum = dest;
        }
        else
        {
            curwin->w_cursor.lnum = dest + (line2 - line1) + 1;
        }

        return OK;
    }

    num_lines = line2 - line1 + 1;

    if (u_save(dest, dest + 1) == FAIL)
    {
        return FAIL;
    }
    extra = 0;
    for (l = line1; l <= line2; l++)
    {
        str = vim_strnsave(ml_get(l + extra), ml_get_len(l + extra));
        if (str != NULL)
        {
            ml_append(dest + l - line1, str, (colnr_T)0, FALSE);
            vim_free(str);
            if (dest < line1)
            {
                extra++;
            }
        }
    }

    last_line = curbuf->b_ml.ml_line_count;
    mark_adjust_nofold(line1, line2, last_line - line2, 0L);
    if (dest >= line2)
    {
        mark_adjust_nofold(line2 + 1, dest, -num_lines, 0L);
        if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
        {
            curbuf->b_op_start.lnum = dest - num_lines + 1;
            curbuf->b_op_end.lnum = dest;
        }
    }
    else
    {
        mark_adjust_nofold(dest + 1, line1 - 1, num_lines, 0L);
        if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
        {
            curbuf->b_op_start.lnum = dest + 1;
            curbuf->b_op_end.lnum = dest + num_lines;
        }
    }
    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
        curbuf->b_op_start.col = curbuf->b_op_end.col = 0;
    }
    mark_adjust_nofold(last_line - num_lines + 1, last_line, -(last_line - dest - extra), 0L);

    if (u_save(line1 + extra - 1, line2 + extra + 1) == FAIL)
    {
        return FAIL;
    }

    for (l = line1; l <= line2; l++)
    {
        ml_delete_flags(line1 + extra, ML_DEL_MESSAGE);
    }

    if (!global_busy && num_lines > p_report)
    {
        smsg(NGETTEXT("%ld line moved", "%ld lines moved", num_lines), (long)num_lines);
    }

    if (dest >= line1)
    {
        curwin->w_cursor.lnum = dest;
    }
    else
    {
        curwin->w_cursor.lnum = dest + (line2 - line1) + 1;
    }

    if (line1 < dest)
    {
        dest += num_lines + 1;
        last_line = curbuf->b_ml.ml_line_count;
        if (dest > last_line + 1)
        {
            dest = last_line + 1;
        }
        changed_lines(line1, 0, dest, 0L);
    }
    else
    {
        changed_lines(dest + 1, 0, line1 + num_lines, 0L);
    }

    return OK;
}

    static void
ex_copy(linenr_T line1, linenr_T line2, linenr_T n)
{
    linenr_T    count;
    char_u      *p;

    count = line2 - line1 + 1;
    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
        curbuf->b_op_start.lnum = n + 1;
        curbuf->b_op_end.lnum = n + count;
        curbuf->b_op_start.col = curbuf->b_op_end.col = 0;
    }

    if (u_save(n, n + 1) == FAIL)
    {
        return;
    }

    curwin->w_cursor.lnum = n;
    while (line1 <= line2)
    {
        p = vim_strnsave(ml_get(line1), ml_get_len(line1));
        if (p != NULL)
        {
            ml_append(curwin->w_cursor.lnum, p, (colnr_T)0, FALSE);
            vim_free(p);
        }
        if (line1 == n)
        {
            line1 = curwin->w_cursor.lnum;
        }
        ++line1;
        if (curwin->w_cursor.lnum < line1)
        {
            ++line1;
        }
        if (curwin->w_cursor.lnum < line2)
        {
            ++line2;
        }
        ++curwin->w_cursor.lnum;
    }

    appended_lines_mark(n, count);
    if (VIsual_active)
    {
        check_pos(curbuf, &VIsual);
    }

    msgmore((long)count);
}

static char_u   *prevcmd = NULL;

    static int
prevcmd_is_set(void)
{
    if (prevcmd == NULL)
    {
        emsg(_(e_no_previous_command));
        return FALSE;
    }
    return TRUE;
}

    static void
do_bang(int         addr_count, exarg_T     *eap, int         forceit, int         do_in, int         do_out)
{
    char_u              *arg = eap->arg;
    linenr_T            line1 = eap->line1;
    linenr_T            line2 = eap->line2;
    char_u              *newcmd = NULL;
    int                 free_newcmd = FALSE;
    int                 ins_prevcmd;
    char_u              *t;
    char_u              *p;
    char_u              *trailarg;
    int                 len;
    int                 scroll_save = msg_scroll;

    if (check_secure())
    {
        return;
    }

    if (addr_count == 0)
    {
        msg_scroll = FALSE;
        autowrite_all();
        msg_scroll = scroll_save;
    }

    ins_prevcmd = forceit;

    trailarg = skipwhite(arg);
    do
    {
        len = (int) strlen((char *)(trailarg))  + 1;
        if (newcmd != NULL)
        {
            len += (int) strlen((char *)(newcmd)) ;
        }
        if (ins_prevcmd)
        {
            if (!prevcmd_is_set())
            {
                vim_free(newcmd);
                return;
            }
            len += (int) strlen((char *)(prevcmd)) ;
        }
        if ((t = alloc(len)) == NULL)
        {
            vim_free(newcmd);
            return;
        }
        *t = NUL;
        if (newcmd != NULL)
        {
             strcat((char *)(t), (char *)(newcmd)) ;
        }
        if (ins_prevcmd)
        {
             strcat((char *)(t), (char *)(prevcmd)) ;
        }
        p = t +  strlen((char *)(t)) ;
         strcat((char *)(t), (char *)(trailarg)) ;
        vim_free(newcmd);
        newcmd = t;

        trailarg = NULL;
        while (*p)
        {
            if (*p == '!')
            {
                if (p > newcmd && p[-1] == '\\')
                {
                      memmove((char *)((p - 1)), (char *)((p)),  strlen((char *)(p))  + 1)  ;
                }
                else
                {
                    trailarg = p;
                    *trailarg++ = NUL;
                    ins_prevcmd = TRUE;
                    break;
                }
            }
            ++p;
        }
    } while (trailarg != NULL);

    if ( strlen((char *)(newcmd))  > 0)
    {
        vim_free(prevcmd);
        prevcmd = newcmd;
    }
    else
    {
        free_newcmd = TRUE;
    }

    if (bangredo)
    {
        if (!prevcmd_is_set())
        {
            goto theend;
        }

        char_u *cmd = vim_strsave_escaped(prevcmd, (char_u *)"%#");

        if (cmd != NULL)
        {
            AppendToRedobuffLit(cmd, -1);
            vim_free(cmd);
        }
        else
        {
            AppendToRedobuffLit(prevcmd, -1);
        }
        AppendToRedobuff((char_u *)"\n");
        bangredo = FALSE;
    }
    if (*p_shq != NUL)
    {
        if (free_newcmd)
        {
            vim_free(newcmd);
        }
        newcmd = alloc( strlen((char *)(prevcmd))  + 2 *  strlen((char *)(p_shq))  + 1);
        if (newcmd == NULL)
        {
            return;
        }
         strcpy((char *)(newcmd), (char *)(p_shq)) ;
         strcat((char *)(newcmd), (char *)(prevcmd)) ;
         strcat((char *)(newcmd), (char *)(p_shq)) ;
        free_newcmd = TRUE;
    }
    if (addr_count == 0)
    {
        msg_start();
        msg_putchar(':');
        msg_putchar('!');
        msg_outtrans(newcmd);
        msg_clr_eos();
        windgoto(msg_row, cmdline_col_off + msg_col);

        do_shell(newcmd, 0);
    }
    else
    {
        do_filter(line1, line2, eap, newcmd, do_in, do_out);
        apply_autocmds(EVENT_SHELLFILTERPOST, NULL, NULL, FALSE, curbuf);
    }

theend:
    if (free_newcmd)
    {
        vim_free(newcmd);
    }
}

    static void
do_filter(linenr_T    line1, linenr_T    line2, exarg_T     *eap, char_u      *cmd, int         do_in, int         do_out)
{
    emsg(_(e_sorry_command_is_not_available_in_this_version));
}

    static void
do_shell(char_u      *cmd, int         flags)
{
    emsg(_(e_sorry_command_is_not_available_in_this_version));
}

    static void
do_fixdel(exarg_T *eap  __attribute__((unused)) )
{
    char_u  *p;

    p = find_termcode((char_u *)"kb");
    add_termcode((char_u *)"kD", p != NULL && *p == DEL ? (char_u *) "\010"  :  (char_u *)"\177" , FALSE);
}

    static void
print_line_no_prefix(linenr_T    lnum, int         use_number, int         list)
{
    char        numbuf[30];

    if (curwin-> w_onebuf_opt.wo_nu  || use_number)
    {
        vim_snprintf(numbuf, sizeof(numbuf), "%*ld ",  7 , (long)lnum);
        msg_puts_attr(numbuf,  highlight_attr[(int)(HLF_N)] );
    }
    msg_prt_line(ml_get(lnum), list);
}

    static void
print_line(linenr_T lnum, int use_number, int list)
{
    int         save_silent = silent_mode;

    if (message_filtered(ml_get(lnum)))
    {
        return;
    }

    msg_start();
    silent_mode = FALSE;
    info_message = TRUE;
    print_line_no_prefix(lnum, use_number, list);
    if (save_silent)
    {
        msg_putchar('\n');
        cursor_on();
        out_flush();
        silent_mode = save_silent;
    }
    info_message = FALSE;
}

    static int
rename_buffer(char_u *new_fname)
{
    char_u *fname;
    char_u *sfname;
    char_u *xfname;
    buf_T       *buf;

    buf = curbuf;
    apply_autocmds(EVENT_BUFFILEPRE, NULL, NULL, FALSE, curbuf);
    if (buf != curbuf)
    {
        return FAIL;
    }
    fname = curbuf->b_ffname;
    sfname = curbuf->b_sfname;
    xfname = curbuf->b_fname;
    curbuf->b_ffname = NULL;
    curbuf->b_sfname = NULL;
    if (setfname(curbuf, new_fname, NULL, TRUE) == FAIL)
    {
        curbuf->b_ffname = fname;
        curbuf->b_sfname = sfname;
        return FAIL;
    }
    curbuf->b_flags |= BF_NOTEDITED;
    if (xfname != NULL && *xfname != NUL)
    {
        buf = buflist_new(fname, xfname, curwin->w_cursor.lnum, 0);
        if (buf != NULL && (cmdmod.cmod_flags & CMOD_KEEPALT) == 0)
        {
            curwin->w_alt_fnum = buf->b_fnum;
        }
    }
    vim_free(fname);
    vim_free(sfname);
    apply_autocmds(EVENT_BUFFILEPOST, NULL, NULL, FALSE, curbuf);

    return OK;
}

    static void
ex_file(exarg_T *eap)
{
    if (eap->addr_count > 0 && (*eap->arg != NUL || eap->line2 > 0 || eap->addr_count > 1))
    {
        emsg(_(e_invalid_argument));
        return;
    }

    if (*eap->arg != NUL || eap->addr_count == 1)
    {
        if (rename_buffer(eap->arg) == FAIL)
        {
            return;
        }
        redraw_tabline = TRUE;
    }

    if (*eap->arg == NUL || !shortmess(SHM_FILEINFO))
    {
        fileinfo(FALSE, FALSE, eap->forceit);
    }
}

    static void
ex_update(exarg_T *eap)
{
    if (curbufIsChanged())
    {
        (void)do_write(eap);
    }
}

    static void
ex_write(exarg_T *eap)
{
    if (eap->cmdidx == CMD_saveas)
    {
        eap->line1 = 1;
        eap->line2 = curbuf->b_ml.ml_line_count;
    }

    if (eap->usefilter)
    {
        do_bang(1, eap, FALSE, TRUE, FALSE);
    }
    else
    {
        (void)do_write(eap);
    }
}

    static int
check_writable(char_u *fname)
{
    if (mch_nodetype(fname) == NODE_OTHER)
    {
        semsg(_(e_str_is_not_file_or_writable_device), fname);
        return FAIL;
    }
    return OK;
}

    static int
do_write(exarg_T *eap)
{
    int         other;
    char_u      *fname = NULL;
    char_u      *ffname;
    int         retval = FAIL;
    char_u      *free_fname = NULL;
    buf_T       *alt_buf = NULL;
    int         name_was_missing;

    if (not_writing())
    {
        return FAIL;
    }

    ffname = eap->arg;
    if (*ffname == NUL)
    {
        if (eap->cmdidx == CMD_saveas)
        {
            emsg(_(e_argument_required));
            goto theend;
        }
        other = FALSE;
    }
    else
    {
        fname = ffname;
        free_fname = fix_fname(ffname);
        if (free_fname != NULL)
        {
            ffname = free_fname;
        }
        other = otherfile(ffname);
    }

    if (other)
    {
        if (vim_strchr(p_cpo, CPO_ALTWRITE) != NULL || eap->cmdidx == CMD_saveas)
        {
            alt_buf = setaltfname(ffname, fname, (linenr_T)1);
        }
        else
        {
            alt_buf = buflist_findname(ffname);
        }
        if (alt_buf != NULL && alt_buf->b_ml.ml_mfp != NULL)
        {
            emsg(_(e_file_is_loaded_in_another_buffer));
            goto theend;
        }
    }

    if (!other && (bt_dontwrite_msg(curbuf) || check_fname() == FAIL || check_writable(curbuf->b_ffname) == FAIL || check_readonly(&eap->forceit, curbuf)))
    {
        goto theend;
    }

    if (!other)
    {
        ffname = curbuf->b_ffname;
        fname = curbuf->b_fname;
        if (       (eap->line1 != 1 || eap->line2 != curbuf->b_ml.ml_line_count) && !eap->forceit && !eap->append && !p_wa)
        {
            {
                emsg(_(e_use_bang_to_write_partial_buffer));
                goto theend;
            }
        }
    }

    if (check_overwrite(eap, curbuf, fname, ffname, other) == OK)
    {
        if (eap->cmdidx == CMD_saveas && alt_buf != NULL)
        {
            buf_T       *was_curbuf = curbuf;

            apply_autocmds(EVENT_BUFFILEPRE, NULL, NULL, FALSE, curbuf);
            apply_autocmds(EVENT_BUFFILEPRE, NULL, NULL, FALSE, alt_buf);
            if (curbuf != was_curbuf)
            {
                retval = FAIL;
                goto theend;
            }
            fname = alt_buf->b_fname;
            alt_buf->b_fname = curbuf->b_fname;
            curbuf->b_fname = fname;
            fname = alt_buf->b_ffname;
            alt_buf->b_ffname = curbuf->b_ffname;
            curbuf->b_ffname = fname;
            fname = alt_buf->b_sfname;
            alt_buf->b_sfname = curbuf->b_sfname;
            curbuf->b_sfname = fname;
            buf_name_changed(curbuf);

            apply_autocmds(EVENT_BUFFILEPOST, NULL, NULL, FALSE, curbuf);
            apply_autocmds(EVENT_BUFFILEPOST, NULL, NULL, FALSE, alt_buf);
            if (!alt_buf->b_p_bl)
            {
                alt_buf->b_p_bl = TRUE;
                apply_autocmds(EVENT_BUFADD, NULL, NULL, FALSE, alt_buf);
            }
            if (curbuf != was_curbuf)
            {
                retval = FAIL;
                goto theend;
            }

            if (*curbuf->b_p_ft == NUL)
            {
                if (au_has_group((char_u *)"filetypedetect"))
                {
                    (void)do_doautocmd((char_u *)"filetypedetect BufRead", TRUE, NULL);
                }
                do_modelines(0);
            }

            fname = curbuf->b_sfname;
        }

        name_was_missing = curbuf->b_ffname == NULL;

        retval = buf_write(curbuf, ffname, fname, eap->line1, eap->line2, eap, eap->append, eap->forceit, TRUE, FALSE);

        if (eap->cmdidx == CMD_saveas)
        {
            if (retval == OK)
            {
                curbuf->b_p_ro = FALSE;
                redraw_tabline = TRUE;
            }
        }

        if (eap->cmdidx == CMD_saveas || name_was_missing)
        {
        }
    }

theend:
    vim_free(free_fname);
    return retval;
}

    static int
check_overwrite(exarg_T     *eap, buf_T       *buf, char_u      *fname, char_u      *ffname, int         other)
{
    if (       (other || (!bt_nofilename(buf) && ((buf->b_flags & BF_NOTEDITED) || ((buf->b_flags & BF_NEW) && vim_strchr(p_cpo, CPO_OVERNEW) == NULL) || (buf->b_flags & BF_READERR)))) && !p_wa && vim_fexists(ffname))
    {
        if (!eap->forceit && !eap->append)
        {
            if (mch_isdir(ffname))
            {
                semsg(_(e_str_is_directory), ffname);
                return FAIL;
            }
            {
                emsg(_(e_file_exists));
                return FAIL;
            }
        }

        if (other && !emsg_silent)
        {
            char_u      *dir;
            char_u      *p;
            int         r;
            char_u      *swapname;

            if (*p_dir == NUL)
            {
                dir = alloc(5);
                if (dir == NULL)
                {
                    return FAIL;
                }
                 strcpy((char *)(dir), (char *)(".")) ;
            }
            else
            {
                dir = alloc( PATH_MAX );
                if (dir == NULL)
                {
                    return FAIL;
                }
                p = p_dir;
                copy_option_part(&p, dir,  PATH_MAX , ",");
            }
            swapname = makeswapname(fname, ffname, curbuf, dir);
            vim_free(dir);
            r = vim_fexists(swapname);
            if (r)
            {
                {
                    semsg(_(e_swap_file_exists_str_silent_overrides), swapname);
                    vim_free(swapname);
                    return FAIL;
                }
            }
            vim_free(swapname);
        }
    }
    return OK;
}

    static void
ex_wnext(exarg_T *eap)
{
    int         i;

    if (eap->cmd[1] == 'n')
    {
        i = curwin->w_arg_idx + (int)eap->line2;
    }
    else
    {
        i = curwin->w_arg_idx - (int)eap->line2;
    }
    eap->line1 = 1;
    eap->line2 = curbuf->b_ml.ml_line_count;
    if (do_write(eap) != FAIL)
    {
        do_argfile(eap, i);
    }
}

    static void
do_wqall(exarg_T *eap)
{
    buf_T       *buf;
    int         error = 0;
    int         save_forceit = eap->forceit;
    int         save_exiting = exiting;

    if (eap->cmdidx == CMD_xall || eap->cmdidx == CMD_wqall)
    {
        if (before_quit_all(eap) == FAIL)
        {
            return;
        }
        exiting = TRUE;
    }

     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
    {
        if (bufIsChanged(buf) && !bt_dontwrite(buf))
        {
            if (not_writing())
            {
                ++error;
                break;
            }
            if (buf->b_ffname == NULL)
            {
                semsg(_(e_no_file_name_for_buffer_nr), (long)buf->b_fnum);
                ++error;
            }
            else if (check_readonly(&eap->forceit, buf) || check_overwrite(eap, buf, buf->b_fname, buf->b_ffname, FALSE) == FAIL)
            {
                ++error;
            }
            else
            {
                bufref_T bufref;

                set_bufref(&bufref, buf);
                if (buf_write_all(buf, eap->forceit) == FAIL)
                {
                    ++error;
                }
                if (!bufref_valid(&bufref))
                {
                    buf = firstbuf;
                }
            }
            eap->forceit = save_forceit;
        }
    }
    if (exiting)
    {
        if (!error)
        {
            getout(0);
        }
        not_exiting(save_exiting);
    }
}

    static int
not_writing(void)
{
    if (p_write)
    {
        return FALSE;
    }
    emsg(_(e_file_not_written_writing_is_disabled_by_write_option));
    return TRUE;
}

    static int
check_readonly(int *forceit, buf_T *buf)
{
    stat_T      st;

    if (!*forceit && (buf->b_p_ro || ( stat(((char *)buf->b_ffname), (&st))  >= 0 && check_file_readonly(buf->b_ffname, 0777))))
    {
        if (buf->b_p_ro)
        {
            emsg(_(e_readonly_option_is_set_add_bang_to_override));
        }
        else
        {
            semsg(_(e_str_is_read_only_add_bang_to_override), buf->b_fname);
        }
        return TRUE;
    }

    return FALSE;
}

    static int
getfile(int         fnum, char_u      *ffname_arg, char_u      *sfname_arg, int         setpm, linenr_T    lnum, int         forceit)
{
    char_u      *ffname = ffname_arg;
    char_u      *sfname = sfname_arg;
    int         other;
    int         retval;
    char_u      *free_me = NULL;

    if (!check_can_set_curbuf_forceit(forceit))
    {
        return GETFILE_ERROR;
    }

    if (text_locked())
    {
        return GETFILE_ERROR;
    }
    if (curbuf_locked())
    {
        return GETFILE_ERROR;
    }

    if (fnum == 0)
    {
        fname_expand(curbuf, &ffname, &sfname);
        other = otherfile(ffname);
        free_me = ffname;
    }
    else
    {
        other = (fnum != curbuf->b_fnum);
    }

    if (other)
    {
        ++no_wait_return;
    }
    if (other && !forceit && curbuf->b_nwindows == 1 && !buf_hide(curbuf) && curbufIsChanged() && autowrite(curbuf, forceit) == FAIL)
    {
        {
            --no_wait_return;
            no_write_message();
            retval = GETFILE_NOT_WRITTEN;
            goto theend;
        }
    }
    if (other)
    {
        --no_wait_return;
    }
    if (setpm)
    {
        setpcmark();
    }
    if (!other)
    {
        if (lnum != 0)
        {
            curwin->w_cursor.lnum = lnum;
        }
        check_cursor_lnum();
        beginline(BL_SOL | BL_FIX);
        retval = GETFILE_SAME_FILE;
    }
    else if (do_ecmd(fnum, ffname, sfname, NULL, lnum, (buf_hide(curbuf) ? ECMD_HIDE : 0) + (forceit ? ECMD_FORCEIT : 0), curwin) == OK)
    {
        retval =  (-1) ;
    }
    else
    {
        retval = GETFILE_ERROR;
    }

theend:
    vim_free(free_me);
    return retval;
}

    static int
do_ecmd(int         fnum, char_u      *ffname, char_u      *sfname, exarg_T     *eap, linenr_T    newlnum, int         flags, win_T       *oldwin)
{
    int         other_file;
    int         oldbuf;
    int         auto_buf = FALSE;
    char_u      *new_name = NULL;
    buf_T       *buf;
    bufref_T    bufref;
    bufref_T    old_curbuf;
    char_u      *free_fname = NULL;
    int         retval = FAIL;
    long        n;
    pos_T       orig_pos;
    linenr_T    topline = 0;
    int         newcol = -1;
    int         solcol = -1;
    pos_T       *pos;
    char_u      *command = NULL;
    int         readfile_flags = 0;
    int         did_inc_redrawing_disabled = FALSE;
    long        *so_ptr = curwin-> w_onebuf_opt.wo_so  >= 0 ? &curwin-> w_onebuf_opt.wo_so  : &p_so;

    if (eap != NULL)
    {
        command = eap->do_ecmd_cmd;
    }
    set_bufref(&old_curbuf, curbuf);

    if (fnum != 0)
    {
        if (fnum == curbuf->b_fnum)
        {
            return OK;
        }
        other_file = TRUE;
    }
    else
    {
        if (sfname == NULL)
        {
            sfname = ffname;
        }

        if ((flags & (ECMD_ADDBUF | ECMD_ALTBUF)) && (ffname == NULL || *ffname == NUL))
        {
            goto theend;
        }

        if (ffname == NULL)
        {
            other_file = TRUE;
        }
        else if (*ffname == NUL && curbuf->b_ffname == NULL)
        {
            other_file = FALSE;
        }
        else
        {
            if (*ffname == NUL)
            {
                ffname = curbuf->b_ffname;
                sfname = curbuf->b_fname;
            }
            free_fname = fix_fname(ffname);
            if (free_fname != NULL)
            {
                ffname = free_fname;
            }
            other_file = otherfile(ffname);
        }
    }

    if (  ((!other_file && !(flags & ECMD_OLDBUF)) || (curbuf->b_nwindows == 1 && !(flags & (ECMD_HIDE | ECMD_ADDBUF | ECMD_ALTBUF)))) && check_changed(curbuf, (p_awa ? CCGD_AW : 0) | (other_file ? 0 : CCGD_MULTWIN) | ((flags & ECMD_FORCEIT) ? CCGD_FORCEIT : 0) | (eap == NULL ? 0 : CCGD_EXCMD)))
    {
        if (fnum == 0 && other_file && ffname != NULL)
        {
            (void)setaltfname(ffname, sfname, newlnum < 0 ? 0 : newlnum);
        }
        goto theend;
    }

    reset_VIsual();

    if (oldwin != NULL && !win_valid(oldwin))
    {
        oldwin = NULL;
    }

    if (other_file)
    {
        int prev_alt_fnum = curwin->w_alt_fnum;

        if (!(flags & (ECMD_ADDBUF | ECMD_ALTBUF)))
        {
            if ((cmdmod.cmod_flags & CMOD_KEEPALT) == 0)
            {
                curwin->w_alt_fnum = curbuf->b_fnum;
            }
            if (oldwin != NULL)
            {
                buflist_altfpos(oldwin);
            }
        }

        if (fnum)
        {
            buf = buflist_findnr(fnum);
        }
        else
        {
            if (flags & (ECMD_ADDBUF | ECMD_ALTBUF))
            {
                linenr_T        tlnum = 0;
                buf_T           *newbuf;

                if (command != NULL)
                {
                    tlnum = atol((char *)command);
                    if (tlnum <= 0)
                    {
                        tlnum = 1L;
                    }
                }
                newbuf = buflist_new(ffname, sfname, tlnum, BLN_LISTED | BLN_NOCURWIN);
                if (newbuf != NULL)
                {
                    if (flags & ECMD_ALTBUF)
                    {
                        curwin->w_alt_fnum = newbuf->b_fnum;
                    }
                    if (tlnum > 0)
                    {
                        newbuf->b_last_cursor.lnum = tlnum;
                    }
                }
                goto theend;
            }
            buf = buflist_new(ffname, sfname, 0L, BLN_CURBUF | ((flags & ECMD_SET_HELP) ? 0 : BLN_LISTED));

            if (oldwin != NULL)
            {
                oldwin = curwin;
            }
            set_bufref(&old_curbuf, curbuf);
        }
        if (buf == NULL)
        {
            goto theend;
        }
        if (buf->b_locked_split)
        {
            emsg(_(e_cannot_switch_to_a_closing_buffer));
            goto theend;
        }
        if (curwin->w_alt_fnum == buf->b_fnum && prev_alt_fnum != 0)
        {
            curwin->w_alt_fnum = prev_alt_fnum;
        }

        if (buf->b_ml.ml_mfp == NULL)
        {
            oldbuf = FALSE;
        }
        else
        {
            oldbuf = TRUE;
            set_bufref(&bufref, buf);
            if (!bufref_valid(&bufref) || curbuf != old_curbuf.br_buf)
            {
                goto theend;
            }
        }

        if ((oldbuf && newlnum ==  (linenr_T)0 ) || newlnum ==  ((linenr_T)-1) )
        {
            pos = buflist_findfpos(buf);
            newlnum = pos->lnum;
            solcol = pos->col;
        }

        if (buf != curbuf)
        {
            bufref_T    save_au_new_curbuf;
            int         save_cmdwin_type = cmdwin_type;
            win_T       *save_cmdwin_win = cmdwin_win;

            cmdwin_type = 0;
            cmdwin_win = NULL;

            if (buf->b_fname != NULL)
            {
                new_name = vim_strsave(buf->b_fname);
            }
            save_au_new_curbuf = au_new_curbuf;
            set_bufref(&au_new_curbuf, buf);
            apply_autocmds(EVENT_BUFLEAVE, NULL, NULL, FALSE, curbuf);

            cmdwin_type = save_cmdwin_type;
            cmdwin_win = save_cmdwin_win;

            if (!bufref_valid(&au_new_curbuf))
            {
                delbuf_msg(new_name);
                au_new_curbuf = save_au_new_curbuf;
                goto theend;
            }
            if (buf == curbuf)
            {
                auto_buf = TRUE;
            }
            else
            {
                win_T       *the_curwin = curwin;

                ++the_curwin->w_locked;
                ++buf->b_locked;

                if (curbuf == old_curbuf.br_buf)
                {
                    buf_copy_options(buf, BCO_ENTER);
                }

                u_sync(FALSE);
                close_buffer(curwin, curbuf, (flags & ECMD_HIDE) ? 0 : DOBUF_UNLOAD, FALSE, FALSE, oldwin != NULL);

                if (win_valid(the_curwin))
                {
                    --the_curwin->w_locked;
                }
                --buf->b_locked;

                if (!bufref_valid(&au_new_curbuf))
                {
                    if (curwin->w_buffer == NULL)
                    {
                        buf = lastbuf;
                    }
                    else
                    {
                        delbuf_msg(new_name);
                        au_new_curbuf = save_au_new_curbuf;
                        goto theend;
                    }
                }
                if (buf == curbuf)
                {
                    auto_buf = TRUE;
                }
                else
                {
                    if (curwin->w_buffer != NULL)
                    {
                        --curwin->w_buffer->b_nwindows;
                    }

                    curwin->w_buffer = buf;
                    curbuf = buf;
                    ++curbuf->b_nwindows;

                    if (!oldbuf && eap != NULL)
                    {
                        set_file_options(TRUE, eap);
                        set_forced_fenc(eap);
                    }
                }

                get_winopts(curbuf);
            }
            vim_free(new_name);
            au_new_curbuf = save_au_new_curbuf;
        }

        curwin->w_pcmark.lnum = 1;
        curwin->w_pcmark.col = 0;
    }
    else
    {
        if ((flags & (ECMD_ADDBUF | ECMD_ALTBUF)) || check_fname() == FAIL)
        {
            goto theend;
        }

        oldbuf = (flags & ECMD_OLDBUF);
    }

    ++RedrawingDisabled;
    did_inc_redrawing_disabled = TRUE;

    buf = curbuf;
    if ((flags & ECMD_SET_HELP) || keep_help_flag)
    {
        prepare_help_buffer();
    }
    else
    {
        if (!curbuf->b_help)
        {
            set_buflisted(TRUE);
        }
    }

    if (buf != curbuf)
    {
        goto theend;
    }

    curbuf->b_did_filetype = false;

    if (!other_file && !oldbuf)
    {
        set_last_cursor(curwin);
        if (newlnum ==  ((linenr_T)-1)  || newlnum ==  (linenr_T)0 )
        {
            newlnum = curwin->w_cursor.lnum;
            solcol = curwin->w_cursor.col;
        }
        buf = curbuf;
        if (buf->b_fname != NULL)
        {
            new_name = vim_strsave(buf->b_fname);
        }
        else
        {
            new_name = NULL;
        }
        set_bufref(&bufref, buf);

        if (!(curbuf->b_flags & BF_NEVERLOADED) && (p_ur < 0 || curbuf->b_ml.ml_line_count <= p_ur))
        {
            u_sync(FALSE);
            if (u_savecommon(0, curbuf->b_ml.ml_line_count + 1, 0, TRUE) == FAIL)
            {
                vim_free(new_name);
                goto theend;
            }
            u_unchanged(curbuf);
            buf_freeall(curbuf, BFA_KEEP_UNDO);

            readfile_flags = READ_KEEP_UNDO;
        }
        else
        {
            buf_freeall(curbuf, 0);
        }

        if (!bufref_valid(&bufref))
        {
            delbuf_msg(new_name);
            goto theend;
        }
        vim_free(new_name);

        if (buf != curbuf)
        {
            goto theend;
        }
        buf_clear_file(curbuf);
        curbuf->b_op_start.lnum = 0;
        curbuf->b_op_end.lnum = 0;
    }

    retval = OK;

    if (!other_file)
    {
        curbuf->b_flags &= ~BF_NOTEDITED;
    }

    check_arg_idx(curwin);

    if (!auto_buf)
    {
        curwin_init();

        orig_pos = curwin->w_cursor;
        topline = curwin->w_topline;
        if (!oldbuf)
        {
            swap_exists_action = SEA_DIALOG;
            curbuf->b_flags |= BF_CHECK_RO;

            if (flags & ECMD_NOWINENTER)
            {
                readfile_flags |= READ_NOWINENTER;
            }
            (void)open_buffer(FALSE, eap, readfile_flags);

            if (swap_exists_action == SEA_QUIT)
            {
                retval = FAIL;
            }
            handle_swap_exists(&old_curbuf);
        }
        else
        {
            do_modelines(OPT_WINONLY);

            apply_autocmds_retval(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf, &retval);
            if ((flags & ECMD_NOWINENTER) == 0)
            {
                apply_autocmds_retval(EVENT_BUFWINENTER, NULL, NULL, FALSE, curbuf, &retval);
            }
        }
        check_arg_idx(curwin);

        if (! (((curwin->w_cursor).lnum == (orig_pos).lnum) && ((curwin->w_cursor).col == (orig_pos).col) && ((curwin->w_cursor).coladd == (orig_pos).coladd)) )
        {
            char_u *text = ml_get_curline();

            if (curwin->w_cursor.lnum != orig_pos.lnum || curwin->w_cursor.col != (int)(skipwhite(text) - text))
            {
                newlnum = curwin->w_cursor.lnum;
                newcol = curwin->w_cursor.col;
            }
        }
        if (curwin->w_topline == topline)
        {
            topline = 0;
        }

        changed_line_abv_curs();

        maketitle();
    }

    if (command == NULL)
    {
        if (newcol >= 0)
        {
            curwin->w_cursor.lnum = newlnum;
            curwin->w_cursor.col = newcol;
            check_cursor();
        }
        else if (newlnum > 0)
        {
            curwin->w_cursor.lnum = newlnum;
            check_cursor_lnum();
            if (solcol >= 0 && !p_sol)
            {
                curwin->w_cursor.col = solcol;
                check_cursor_col();
                curwin->w_cursor.coladd = 0;
                curwin->w_set_curswant = true;
            }
            else
            {
                beginline(BL_SOL | BL_FIX);
            }
        }
        else
        {
            if (exmode_active)
            {
                curwin->w_cursor.lnum = curbuf->b_ml.ml_line_count;
            }
            beginline(BL_WHITE | BL_FIX);
        }
    }

    check_lnums(FALSE);

    if (oldbuf && !auto_buf)
    {
        int     msg_scroll_save = msg_scroll;

        if (shortmess(SHM_OVERALL) && !exiting && p_verbose == 0)
        {
            msg_scroll = FALSE;
        }
        if (!msg_scroll)
        {
            check_for_delay(FALSE);
        }
        msg_start();
        msg_scroll = msg_scroll_save;
        msg_scrolled_ign = TRUE;

        if (!shortmess(SHM_FILEINFO))
        {
            fileinfo(FALSE, TRUE, FALSE);
        }

        msg_scrolled_ign = FALSE;
    }

    if (command != NULL)
    {
        do_cmdline(command, NULL, NULL, DOCMD_VERBOSE|DOCMD_RANGEOK);
    }

    if (RedrawingDisabled > 0)
    {
        --RedrawingDisabled;
    }
    did_inc_redrawing_disabled = FALSE;
    if (!skip_redraw)
    {
        n = *so_ptr;
        if (topline == 0 && command == NULL)
        {
            *so_ptr = 9999;
        }
        update_topline();
        curwin->w_scbind_pos = curwin->w_topline;
        *so_ptr = n;
        redraw_curbuf_later(UPD_NOT_VALID);
    }

    if (p_im && (State & MODE_INSERT) == 0)
    {
        need_start_insertmode = TRUE;
    }

theend:
    if (did_inc_redrawing_disabled && RedrawingDisabled > 0)
    {
        --RedrawingDisabled;
    }
    vim_free(free_fname);
    return retval;
}

    static void
delbuf_msg(char_u *name)
{
    semsg(_(e_autocommands_unexpectedly_deleted_new_buffer_str), name == NULL ? (char_u *)"" : name);
    vim_free(name);
    au_new_curbuf.br_buf = NULL;
    au_new_curbuf.br_buf_free_count = 0;
}

static int append_indent = 0;

    static void
ex_append(exarg_T *eap)
{
    char_u      *theline;
    int         did_undo = FALSE;
    linenr_T    lnum = eap->line2;
    int         indent = 0;
    char_u      *p;
    int         vcol;
    int         empty = (curbuf->b_ml.ml_flags & ML_EMPTY);

    if (eap->forceit)
    {
        curbuf->b_p_ai = !curbuf->b_p_ai;
    }

    if (eap->cmdidx != CMD_change && curbuf->b_p_ai && lnum > 0)
    {
        append_indent = get_indent_lnum(lnum);
    }

    if (eap->cmdidx != CMD_append)
    {
        --lnum;
    }

    if (empty && lnum == 1)
    {
        lnum = 0;
    }

    State = MODE_INSERT;
    if (curbuf->b_p_iminsert == B_IMODE_LMAP)
    {
        State |= MODE_LANGMAP;
    }

    for (;;)
    {
        msg_scroll = TRUE;
        need_wait_return = FALSE;
        if (curbuf->b_p_ai)
        {
            if (append_indent >= 0)
            {
                indent = append_indent;
                append_indent = -1;
            }
            else if (lnum > 0)
            {
                indent = get_indent_lnum(lnum);
            }
        }
        ex_keep_indent = FALSE;
        if (*eap->arg == '|')
        {
            theline = vim_strsave(eap->arg + 1);
            *eap->arg = NUL;
        }
        else if (eap->ea_getline == NULL)
        {
            if (eap->nextcmd == NULL)
            {
                break;
            }
            p = vim_strchr(eap->nextcmd, NL);
            if (p == NULL)
            {
                p = eap->nextcmd +  strlen((char *)(eap->nextcmd)) ;
            }
            theline = vim_strnsave(eap->nextcmd, p - eap->nextcmd);
            if (*p != NUL)
            {
                ++p;
            }
            else
            {
                p = NULL;
            }
            eap->nextcmd = p;
        }
        else
        {
            int save_State = State;

            State = MODE_CMDLINE;
            theline = eap->ea_getline(NUL, eap->cookie, indent, GETLINE_CONCAT_CONT);
            State = save_State;
        }
        lines_left = Rows - 1;
        if (theline == NULL)
        {
            break;
        }

        if (ex_keep_indent)
        {
            append_indent = indent;
        }

        vcol = 0;
        for (p = theline; indent > vcol; ++p)
        {
            if (*p == ' ')
            {
                ++vcol;
            }
            else if (*p == TAB)
            {
                vcol += 8 - vcol % 8;
            }
            else
            {
                break;
            }
        }
        if ((p[0] == '.' && p[1] == NUL) || (!did_undo && u_save(lnum, lnum + 1 + (empty ? 1 : 0)) == FAIL))
        {
            vim_free(theline);
            break;
        }

        if (p[0] == NUL)
        {
            theline[0] = NUL;
        }

        did_undo = TRUE;
        ml_append(lnum, theline, (colnr_T)0, FALSE);
        if (empty)
        {
            appended_lines(lnum, 1L);
        }
        else
        {
            appended_lines_mark(lnum, 1L);
        }

        vim_free(theline);
        ++lnum;

        if (empty)
        {
            ml_delete(2L);
            empty = FALSE;
        }
    }
    State = MODE_NORMAL;

    if (eap->forceit)
    {
        curbuf->b_p_ai = !curbuf->b_p_ai;
    }

    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
        curbuf->b_op_start.lnum = (eap->line2 < curbuf->b_ml.ml_line_count) ?
            eap->line2 + 1 : curbuf->b_ml.ml_line_count;
        if (eap->cmdidx != CMD_append)
        {
            --curbuf->b_op_start.lnum;
        }
        curbuf->b_op_end.lnum = (eap->line2 < lnum)
                                              ? lnum : curbuf->b_op_start.lnum;
        curbuf->b_op_start.col = curbuf->b_op_end.col = 0;
    }
    curwin->w_cursor.lnum = lnum;
    check_cursor_lnum();
    beginline(BL_SOL | BL_FIX);

    need_wait_return = FALSE;
    ex_no_reprint = TRUE;
}

    static void
ex_change(exarg_T *eap)
{
    linenr_T    lnum;

    if (eap->line2 >= eap->line1 && u_save(eap->line1 - 1, eap->line2 + 1) == FAIL)
    {
        return;
    }

    if (eap->forceit ? !curbuf->b_p_ai : curbuf->b_p_ai)
    {
        append_indent = get_indent_lnum(eap->line1);
    }

    for (lnum = eap->line2; lnum >= eap->line1; --lnum)
    {
        if (curbuf->b_ml.ml_flags & ML_EMPTY)
        {
            break;
        }
        ml_delete(eap->line1);
    }

    check_cursor_lnum();
    deleted_lines_mark(eap->line1, (long)(eap->line2 - lnum));

    eap->line2 = eap->line1;
    ex_append(eap);
}

    static void
ex_z(exarg_T *eap)
{
    char_u      *x;
    long        bigness;
    char_u      *kind;
    int         minus = 0;
    linenr_T start;
    linenr_T end;
    linenr_T curs;
    linenr_T i;
    int         j;
    linenr_T    lnum = eap->line2;

    if (eap->forceit)
    {
        bigness = Rows - 1;
    }
    else if (! (firstwin == lastwin) )
    {
        bigness = curwin->w_height - 3;
    }
    else
    {
        bigness = curwin-> w_onebuf_opt.wo_scr  * 2;
    }
    if (bigness < 1)
    {
        bigness = 1;
    }

    x = eap->arg;
    kind = x;
    if (*kind == '-' || *kind == '+' || *kind == '=' || *kind == '^' || *kind == '.')
    {
        ++x;
    }
    while (*x == '-' || *x == '+')
    {
        ++x;
    }

    if (*x != 0)
    {
        if (! ((unsigned)(*x) - '0' < 10) )
        {
            emsg(_(e_non_numeric_argument_to_z));
            return;
        }
        else
        {
            bigness = atol((char *)x);

            if (bigness > 2 * curbuf->b_ml.ml_line_count || bigness < 0)
            {
                bigness = 2 * curbuf->b_ml.ml_line_count;
            }

            p_window = bigness;
            if (*kind == '=')
            {
                bigness += 2;
            }
        }
    }

    if (*kind == '-' || *kind == '+')
    {
        for (x = kind + 1; *x == *kind; ++x)
        {
            ;
        }
    }

    switch (*kind)
    {
        case '-':
            start = lnum - bigness * (linenr_T)(x - kind) + 1;
            end = start + bigness - 1;
            curs = end;
            break;

        case '=':
            start = lnum - (bigness + 1) / 2 + 1;
            end = lnum + (bigness + 1) / 2 - 1;
            curs = lnum;
            minus = 1;
            break;

        case '^':
            start = lnum - bigness * 2;
            end = lnum - bigness;
            curs = lnum - bigness;
            break;

        case '.':
            start = lnum - (bigness + 1) / 2 + 1;
            end = lnum + (bigness + 1) / 2 - 1;
            curs = end;
            break;

        default:
            start = lnum;
            if (*kind == '+')
            {
                start += bigness * (linenr_T)(x - kind - 1) + 1;
            }
            else if (eap->addr_count == 0)
            {
                ++start;
            }
            end = start + bigness - 1;
            curs = end;
            break;
    }

    if (start < 1)
    {
        start = 1;
    }

    if (end > curbuf->b_ml.ml_line_count)
    {
        end = curbuf->b_ml.ml_line_count;
    }

    if (curs > curbuf->b_ml.ml_line_count)
    {
        curs = curbuf->b_ml.ml_line_count;
    }
    else if (curs < 1)
    {
        curs = 1;
    }

    for (i = start; i <= end; i++)
    {
        if (minus && i == lnum)
        {
            msg_putchar('\n');

            for (j = 1; j < Columns; j++)
            {
                msg_putchar('-');
            }
        }

        print_line(i, eap->flags & EXFLAG_NR, eap->flags & EXFLAG_LIST);

        if (minus && i == lnum)
        {
            msg_putchar('\n');

            for (j = 1; j < Columns; j++)
            {
                msg_putchar('-');
            }
        }
    }

    if (curwin->w_cursor.lnum != curs)
    {
        curwin->w_cursor.lnum = curs;
        curwin->w_cursor.col = 0;
    }
    ex_no_reprint = TRUE;
}

    static int
check_secure(void)
{
    if (secure)
    {
        secure = 2;
        emsg(_(e_command_not_allowed_from_vimrc_in_current_dir_or_tag_search));
        return TRUE;
    }
    return FALSE;
}

static char_u   *old_sub = NULL;
static int      global_need_beginline;

typedef struct {
    int do_all;
    int do_ask;
    int do_count;
    int do_error;
    int do_print;
    int do_list;
    int do_number;
    int do_ic;
} subflags_T;

    static char_u *
skip_substitute(char_u *start, int delimiter)
{
    char_u *p = start;

    while (p[0])
    {
        if (p[0] == delimiter)
        {
            *p++ = NUL;
            break;
        }
        if (p[0] == '\\' && p[1] != 0)
        {
            ++p;
        }
         p += (*mb_ptr2len)(p) ;
    }
    return p;
}

    static int
check_regexp_delim(int c)
{
    if ( (isalpha ((unsigned char)(c))) )
    {
        emsg(_(e_regular_expressions_cant_be_delimited_by_letters));
        return FAIL;
    }
    return OK;
}

    static void
ex_substitute(exarg_T *eap)
{
    linenr_T    lnum;
    long        i = 0;
    regmmatch_T regmatch;
    static subflags_T subflags = {FALSE, FALSE, FALSE, TRUE, FALSE,
                                                              FALSE, FALSE, 0};
    int         save_do_all;
    int         save_do_ask;
    char_u      *sub = NULL;
    string_T    pat = {NULL, 0};
    int         delimiter;
    size_t      sublen;
    int         got_quit = FALSE;
    int         got_match = FALSE;
    int         which_pat;
    char_u      *cmd;
    char_u      *p;
    int         save_State;
    linenr_T    first_line = 0;
    linenr_T    last_line = 0;
    linenr_T    old_line_count = curbuf->b_ml.ml_line_count;
    linenr_T    line2;
    long        nmatch;
    string_T    sub_firstline;
    int         endcolumn = FALSE;
    pos_T       old_cursor = curwin->w_cursor;
    int         start_nsubs;
    int         keeppatterns = cmdmod.cmod_flags & CMOD_KEEPPATTERNS;

    cmd = eap->arg;
    if (!global_busy)
    {
        sub_nsubs = 0;
        sub_nlines = 0;
    }
    start_nsubs = sub_nsubs;

    if (eap->cmdidx == CMD_tilde)
    {
        which_pat = RE_LAST;
    }
    else
    {
        which_pat = RE_SUBST;
    }

    if (eap->cmd[0] == 's' && *cmd != NUL && ! ((*cmd) == ' ' || (*cmd) == '\t')  && vim_strchr((char_u *)"0123456789cegriIp|\"", *cmd) == NULL)
    {
        if (check_regexp_delim(*cmd) == FAIL)
        {
            return;
        }

        if (*cmd == '\\')
        {
            if (in_vim9script())
            {
                emsg(_(e_cannot_use_s_backslash_in_vim9_script));
                return;
            }
            ++cmd;
            if (vim_strchr((char_u *)"/?&", *cmd) == NULL)
            {
                emsg(_(e_backslash_should_be_followed_by));
                return;
            }
            if (*cmd != '&')
            {
                which_pat = RE_SEARCH;
            }
             (pat).string = (char_u *)("");
             (pat).length =  (sizeof("" "") - 1) ;
            delimiter = *cmd++;
        }
        else
        {
            which_pat = RE_LAST;
            delimiter = *cmd++;
            pat.string = cmd;
            cmd = skip_regexp_ex(cmd, delimiter, magic_isset(), &eap->arg, NULL, NULL);
            pat.length = (size_t)(cmd - pat.string);
            if (cmd[0] == delimiter)
            {
                *cmd++ = NUL;
            }
        }

        p = cmd;
        cmd = skip_substitute(cmd, delimiter);
        sub = vim_strsave(p);
        if (sub == NULL)
        {
            return;
        }

        if (!eap->skip)
        {
            if ( strcmp((char *)(sub), (char *)("%"))  == 0 && vim_strchr(p_cpo, CPO_SUBPERCENT) != NULL)
            {
                if (old_sub == NULL)
                {
                    emsg(_(e_no_previous_substitute_regular_expression));
                    vim_free(sub);
                    return;
                }
                vim_free(sub);
                sub = vim_strsave(old_sub);
                if (sub == NULL)
                {
                    return;
                }
            }
            else if (!keeppatterns)
            {
                vim_free(old_sub);
                old_sub = vim_strsave(sub);
                if (old_sub == NULL)
                {
                    vim_free(sub);
                    return;
                }
            }
        }
    }
    else if (!eap->skip)
    {
        if (old_sub == NULL)
        {
            emsg(_(e_no_previous_substitute_regular_expression));
            return;
        }
        pat.string = NULL;
        pat.length = 0;
        sub = vim_strsave(old_sub);
        if (sub == NULL)
        {
            return;
        }

        endcolumn = (curwin->w_curswant == MAXCOL);
    }

    if (pat.string != NULL &&  strcmp((char *)(pat.string), (char *)("\\n"))  == 0 && *sub == NUL && (*cmd == NUL || (cmd[1] == NUL && (*cmd == 'g' || *cmd == 'l' || *cmd == 'p' || *cmd == '#'))))
    {
        linenr_T    joined_lines_count;

        if (eap->skip)
        {
            vim_free(sub);
            return;
        }
        curwin->w_cursor.lnum = eap->line1;
        if (*cmd == 'l')
        {
            eap->flags = EXFLAG_LIST;
        }
        else if (*cmd == '#')
        {
            eap->flags = EXFLAG_NR;
        }
        else if (*cmd == 'p')
        {
            eap->flags = EXFLAG_PRINT;
        }

        joined_lines_count = eap->line2 - eap->line1 + 1;
        if (eap->line2 < curbuf->b_ml.ml_line_count)
        {
            ++joined_lines_count;
        }
        if (joined_lines_count > 1)
        {
            (void)do_join(joined_lines_count, FALSE, TRUE, FALSE, TRUE);
            sub_nsubs = joined_lines_count - 1;
            sub_nlines = 1;
            (void)do_sub_msg(FALSE);
            ex_may_print(eap);
        }

        if (!keeppatterns)
        {
            save_re_pat(RE_SUBST, pat.string, pat.length, magic_isset());
        }
        add_to_history(HIST_SEARCH, pat.string, pat.length, TRUE, NUL);
        vim_free(sub);

        return;
    }

    if (*cmd == '&')
    {
        ++cmd;
    }
    else
    {
        if (!p_ed)
        {
            if (p_gd)
            {
                subflags.do_all = TRUE;
            }
            else
            {
                subflags.do_all = FALSE;
            }
            subflags.do_ask = FALSE;
        }
        subflags.do_error = TRUE;
        subflags.do_print = FALSE;
        subflags.do_list = FALSE;
        subflags.do_count = FALSE;
        subflags.do_number = FALSE;
        subflags.do_ic = 0;
    }
    while (*cmd)
    {
        if (*cmd == 'g')
        {
            subflags.do_all = !subflags.do_all;
        }
        else if (*cmd == 'c')
        {
            subflags.do_ask = !subflags.do_ask;
        }
        else if (*cmd == 'n')
        {
            subflags.do_count = TRUE;
        }
        else if (*cmd == 'e')
        {
            subflags.do_error = !subflags.do_error;
        }
        else if (*cmd == 'r')
        {
            which_pat = RE_LAST;
        }
        else if (*cmd == 'p')
        {
            subflags.do_print = TRUE;
        }
        else if (*cmd == '#')
        {
            subflags.do_print = TRUE;
            subflags.do_number = TRUE;
        }
        else if (*cmd == 'l')
        {
            subflags.do_print = TRUE;
            subflags.do_list = TRUE;
        }
        else if (*cmd == 'i')
        {
            subflags.do_ic = 'i';
        }
        else if (*cmd == 'I')
        {
            subflags.do_ic = 'I';
        }
        else
        {
            break;
        }
        ++cmd;
    }
    if (subflags.do_count)
    {
        subflags.do_ask = FALSE;
    }

    save_do_all = subflags.do_all;
    save_do_ask = subflags.do_ask;

    cmd = skipwhite(cmd);
    if ( ((unsigned)(*cmd) - '0' < 10) )
    {
        i = getdigits(&cmd);
        if (i <= 0 && !eap->skip && subflags.do_error)
        {
            emsg(_(e_positive_count_required));
            vim_free(sub);
            return;
        }
        else if (i >= INT_MAX)
        {
            char        buf[20];
            vim_snprintf(buf, sizeof(buf), "%ld", i);
            semsg(_(e_val_too_large), buf);
            vim_free(sub);
            return;
        }
        eap->line1 = eap->line2;
        eap->line2 += i - 1;
        if (eap->line2 > curbuf->b_ml.ml_line_count)
        {
            eap->line2 = curbuf->b_ml.ml_line_count;
        }
    }

    cmd = skipwhite(cmd);
    if (*cmd && *cmd != '"')
    {
        set_nextcmd(eap, cmd);
        if (eap->nextcmd == NULL)
        {
            semsg(_(e_trailing_characters_str), cmd);
            vim_free(sub);
            return;
        }
    }

    if (eap->skip)
    {
        vim_free(sub);
        return;
    }

    if (!subflags.do_count && !curbuf->b_p_ma)
    {
        emsg(_(e_cannot_make_changes_modifiable_is_off));
        vim_free(sub);
        return;
    }

    if (search_regcomp(pat.string, pat.length, NULL, RE_SUBST, which_pat, SEARCH_HIS, &regmatch) == FAIL)
    {
        if (subflags.do_error)
        {
            emsg(_(e_invalid_command));
        }
        vim_free(sub);
        return;
    }

    if (subflags.do_ic == 'i')
    {
        regmatch.rmm_ic = TRUE;
    }
    else if (subflags.do_ic == 'I')
    {
        regmatch.rmm_ic = FALSE;
    }

    sub_firstline.string = NULL;
    sub_firstline.length = 0;

    if (sub[0] == '\\' && sub[1] == '=')
    {
        p = vim_strsave(sub);
        vim_free(sub);
        if (p == NULL)
        {
            return;
        }
        sub = p;
    }
    else
    {
        p = regtilde(sub, magic_isset());

        if (p != sub)
        {
            vim_free(sub);
            sub = p;
        }
    }

    line2 = eap->line2;
    for (lnum = eap->line1; lnum <= line2 && !(got_quit); ++lnum)
    {
        nmatch = vim_regexec_multi(&regmatch, curwin, curbuf, lnum, (colnr_T)0, NULL);
        if (nmatch)
        {
            colnr_T     copycol;
            colnr_T     matchcol;
            colnr_T     prev_matchcol = MAXCOL;
            string_T    new_start = {NULL, 0};
            size_t      new_start_size = 0;
            char_u      *new_end;
            int         did_sub = FALSE;
            int         lastone;
            size_t      copy_len;
            size_t      needed_size;
            long        nmatch_tl = 0;
            int         do_again;
            int         skip_match = FALSE;
            linenr_T    sub_firstlnum;
            bool        did_split = false;

            sub_firstlnum = lnum;
            copycol = 0;
            matchcol = 0;

            if (!got_match)
            {
                setpcmark();
                got_match = TRUE;
            }

            for (;;)
            {
                string_T    tmp;
                char_u      *p1;
                size_t      n;

                if (regmatch.startpos[0].lnum > 0)
                {
                    lnum += regmatch.startpos[0].lnum;
                    sub_firstlnum += regmatch.startpos[0].lnum;
                    nmatch -= regmatch.startpos[0].lnum;
                     vim_free(sub_firstline.string);
                     (sub_firstline.string) = NULL;
                     sub_firstline.length = 0;
                }

                if (lnum > curbuf->b_ml.ml_line_count)
                {
                    break;
                }

                if (sub_firstline.string == NULL)
                {
                    sub_firstline.length = ml_get_len(sub_firstlnum);
                    sub_firstline.string =
                        vim_strnsave(ml_get(sub_firstlnum), sub_firstline.length);
                    if (sub_firstline.string == NULL)
                    {
                        vim_free(new_start.string);
                        goto outofmem;
                    }
                }

                curwin->w_cursor.lnum = lnum;
                do_again = FALSE;

                if (matchcol == prev_matchcol && regmatch.endpos[0].lnum == 0 && matchcol == regmatch.endpos[0].col)
                {
                    if (sub_firstline.string[matchcol] == NUL)
                    {
                        skip_match = TRUE;
                    }
                    else
                    {
                        if (has_mbyte)
                        {
                            matchcol += mb_ptr2len(sub_firstline.string + matchcol);
                        }
                        else
                        {
                            ++matchcol;
                        }
                    }
                    goto skip;
                }

                matchcol = regmatch.endpos[0].col;
                prev_matchcol = matchcol;

                if (subflags.do_count)
                {
                    if (nmatch > 1)
                    {
                        matchcol = (colnr_T)sub_firstline.length;
                        nmatch = 1;
                        skip_match = TRUE;
                    }
                    sub_nsubs++;
                    did_sub = TRUE;
                        goto skip;
                }

                if (subflags.do_ask)
                {
                    int typed = 0;

                    save_State = State;
                    State = MODE_CONFIRM;
                    setmouse();
                    curwin->w_cursor.col = regmatch.startpos[0].col;
                    if (curwin-> w_onebuf_opt.wo_crb )
                    {
                        do_check_cursorbind();
                    }

                    if (vim_strchr(p_cpo, CPO_UNDO) != NULL)
                    {
                        ++no_u_sync;
                    }

                    while (subflags.do_ask)
                    {
                        if (exmode_active)
                        {
                            char_u      *resp;
                            colnr_T sc;
                            colnr_T ec;

                            print_line_no_prefix(lnum, subflags.do_number, subflags.do_list);

                            getvcol(curwin, &curwin->w_cursor, &sc, NULL, NULL, 0);
                            curwin->w_cursor.col = regmatch.endpos[0].col - 1;
                            if (curwin->w_cursor.col < 0)
                            {
                                curwin->w_cursor.col = 0;
                            }
                            getvcol(curwin, &curwin->w_cursor, NULL, NULL, &ec, 0);
                            curwin->w_cursor.col = regmatch.startpos[0].col;
                            if (subflags.do_number || curwin-> w_onebuf_opt.wo_nu )
                            {
                                int numw =  7  + 1;
                                sc += numw;
                                ec += numw;
                            }
                            msg_start();
                            for (i = 0; i < (long)sc; ++i)
                            {
                                msg_putchar(' ');
                            }
                            for ( ; i <= (long)ec; ++i)
                            {
                                msg_putchar('^');
                            }

                            resp = getexmodeline('?', NULL, 0, GETLINE_CONCAT_CONT);
                            if (resp != NULL)
                            {
                                typed = *resp;
                                vim_free(resp);
                                if (ex_normal_busy && typed == NUL)
                                {
                                    typed = 'q';
                                }
                            }
                        }
                        else
                        {
                            string_T orig_line = {NULL, 0};
                            int    len_change = 0;
                            int    save_p_lz = p_lz;
                            int save_RedrawingDisabled = RedrawingDisabled;
                            RedrawingDisabled = 0;

                            p_lz = FALSE;

                            if (new_start.string != NULL)
                            {
                                orig_line.length = ml_get_len(lnum);
                                orig_line.string = vim_strnsave(ml_get(lnum), orig_line.length);
                                if (orig_line.string != NULL)
                                {
                                    string_T new_line;

                                    new_line.string = concat_str(new_start.string, sub_firstline.string + copycol);
                                    if (new_line.string == NULL)
                                    {
                                         vim_free(orig_line.string);
                                         (orig_line.string) = NULL;
                                         orig_line.length = 0;
                                    }
                                    else
                                    {
                                        new_line.length =
                                            new_start.length + (sub_firstline.length - copycol);
                                        len_change =
                                            (int)new_line.length - (int)orig_line.length;
                                        curwin->w_cursor.col += len_change;
                                        ml_replace(lnum, new_line.string, FALSE);
                                    }
                                }
                            }

                            search_match_lines = regmatch.endpos[0].lnum
                                                  - regmatch.startpos[0].lnum;
                            search_match_endcol = regmatch.endpos[0].col
                                                                 + len_change;
                            if (search_match_lines == 0 && search_match_endcol == 0)
                            {
                                search_match_endcol = 1;
                            }
                            highlight_match = TRUE;

                            update_topline();
                            validate_cursor();
                            update_screen(UPD_SOME_VALID);
                            highlight_match = FALSE;
                            redraw_later(UPD_SOME_VALID);

                            if (msg_row == Rows - 1)
                            {
                                msg_didout = FALSE;
                            }
                            msg_starthere();
                            i = msg_scroll;
                            msg_scroll = 0;
                            msg_no_more = TRUE;
                            smsg_attr( highlight_attr[(int)(HLF_R)] , _("replace with %s (y/n/a/q/l/^E/^Y)?"), sub);
                            msg_no_more = FALSE;
                            msg_scroll = i;
                            showruler(TRUE);
                            windgoto(msg_row, cmdline_col_off + msg_col);
                            RedrawingDisabled = save_RedrawingDisabled;

                            ++no_mapping;
                            ++allow_keys;
                            typed = plain_vgetc();
                            --allow_keys;
                            --no_mapping;

                            msg_didout = FALSE;
                            msg_col = 0;
                            gotocmdline(TRUE);
                            p_lz = save_p_lz;

                            if (orig_line.string != NULL)
                            {
                                ml_replace(lnum, orig_line.string, FALSE);
                            }
                        }

                        need_wait_return = FALSE;
                        if (typed == 'q' || typed == ESC || typed == Ctrl_C || typed == intr_char)
                        {
                            got_quit = TRUE;
                            break;
                        }
                        if (typed == 'n')
                        {
                            break;
                        }
                        if (typed == 'y')
                        {
                            break;
                        }
                        if (typed == 'l')
                        {
                            subflags.do_all = FALSE;
                            line2 = lnum;
                            break;
                        }
                        if (typed == 'a')
                        {
                            subflags.do_ask = FALSE;
                            break;
                        }
                        if (typed == Ctrl_E)
                        {
                            scrollup_clamp();
                        }
                        else if (typed == Ctrl_Y)
                        {
                            scrolldown_clamp();
                        }
                    }
                    State = save_State;
                    setmouse();
                    if (vim_strchr(p_cpo, CPO_UNDO) != NULL)
                    {
                        --no_u_sync;
                    }

                    if (typed == 'n')
                    {
                        if (nmatch > 1)
                        {
                            matchcol = (colnr_T)sub_firstline.length;
                            skip_match = TRUE;
                        }
                        goto skip;
                    }
                    if (got_quit)
                    {
                        goto skip;
                    }
                }

                curwin->w_cursor.col = regmatch.startpos[0].col;

                sublen = (size_t)vim_regsub_multi(&regmatch, sub_firstlnum - regmatch.startpos[0].lnum, sub, sub_firstline.string, 0, REGSUB_BACKSLASH | (magic_isset() ? REGSUB_MAGIC : 0));

                if (nmatch > curbuf->b_ml.ml_line_count - sub_firstlnum + 1)
                {
                    nmatch = curbuf->b_ml.ml_line_count - sub_firstlnum + 1;
                    skip_match = TRUE;
                    if (nmatch < 0)
                    {
                        goto skip;
                    }
                }

                if (nmatch == 1)
                {
                    tmp.string = sub_firstline.string;
                    tmp.length = sub_firstline.length;
                }
                else
                {
                    linenr_T    lastlnum = sub_firstlnum + nmatch - 1;
                    tmp.string = ml_get(lastlnum);
                    tmp.length = ml_get_len(lastlnum);
                    nmatch_tl += nmatch - 1;
                }

                copy_len = (size_t)(regmatch.startpos[0].col - copycol);
                needed_size = copy_len
                    + (tmp.length - (size_t)regmatch.endpos[0].col) + sublen + 1;

                if (new_start.string == NULL)
                {
                    new_start_size = needed_size + 50;
                    if ((new_start.string = alloc_clear(new_start_size)) == NULL)
                    {
                        goto outofmem;
                    }
                    *new_start.string = NUL;
                    new_start.length = 0;
                }
                else
                {
                    needed_size += new_start.length;
                    if (needed_size > new_start_size)
                    {
                        new_start_size = needed_size + 50;
                        if ((p1 = alloc_clear(new_start_size)) == NULL)
                        {
                            vim_free(new_start.string);
                            goto outofmem;
                        }
                         memmove((char *)(p1), (char *)(new_start.string), new_start.length + 1) ;
                        vim_free(new_start.string);
                        new_start.string = p1;
                    }
                }

                 memmove((char *)(new_start.string + new_start.length), (char *)(sub_firstline.string + copycol), copy_len) ;
                new_start.length += copy_len;

                new_end = new_start.string + new_start.length;

                if (new_start_size - copy_len < sublen)
                {
                    sublen = new_start_size - copy_len - 1;
                }

                n = (size_t)vim_regsub_multi(&regmatch, sub_firstlnum - regmatch.startpos[0].lnum, sub, new_end, (int)sublen, REGSUB_COPY | REGSUB_BACKSLASH | (magic_isset() ? REGSUB_MAGIC : 0));

                if (n > 0)
                {
                    new_start.length += n - 1;
                }

                sub_nsubs++;
                did_sub = TRUE;

                curwin->w_cursor.col = 0;

                if (nmatch > 1)
                {
                    sub_firstlnum += nmatch - 1;
                    vim_free(sub_firstline.string);
                    sub_firstline.length = ml_get_len(sub_firstlnum);
                    sub_firstline.string =
                        vim_strnsave(ml_get(sub_firstlnum), sub_firstline.length);
                    if (sub_firstline.string == NULL)
                    {
                        vim_free(new_start.string);
                        goto outofmem;
                    }
                    if (sub_firstlnum <= line2)
                    {
                        do_again = TRUE;
                    }
                    else
                    {
                        subflags.do_all = FALSE;
                    }
                }

                copycol = regmatch.endpos[0].col;

                if (skip_match)
                {
                    vim_free(sub_firstline.string);
                    sub_firstline.string = vim_strnsave((char_u *)"", 0);
                    if (sub_firstline.string == NULL)
                    {
                        vim_free(new_start.string);
                        goto outofmem;
                    }
                    sub_firstline.length = 0;
                    copycol = 0;
                }

                for (p1 = new_end; *p1; ++p1)
                {
                    if (p1[0] == '\\' && p1[1] != NUL)
                    {
                        n = (size_t)(new_start.length - (p1 - new_start.string));
                         memmove((char *)(p1), (char *)(p1 + 1), n + 1) ;
                        --new_start.length;
                    }
                    else if (*p1 == CAR)
                    {
                        if (u_inssub(lnum) == OK)
                        {
                            colnr_T     plen = (colnr_T)(p1 - new_start.string + 1);

                            *p1 = NUL;
                            ml_append(lnum - 1, new_start.string, plen, FALSE);
                            mark_adjust(lnum + 1, (linenr_T) LONG_MAX , 1L, 0L);
                            if (subflags.do_ask)
                            {
                                appended_lines(lnum - 1, 1L);
                            }
                            else
                            {
                                if (first_line == 0)
                                {
                                    first_line = lnum;
                                }
                                last_line = lnum + 1;
                            }
                            ++sub_firstlnum;
                            ++lnum;
                            ++line2;
                            did_split = true;
                            ++curwin->w_cursor.lnum;
                            n = new_start.length - (size_t)plen;
                             memmove((char *)(new_start.string), (char *)(p1 + 1), n + 1) ;
                            new_start.length = n;
                            p1 = new_start.string - 1;
                        }
                    }
                    else if (has_mbyte)
                    {
                        p1 += (*mb_ptr2len)(p1) - 1;
                    }
                }

skip:
                lastone = (skip_match || got_int || got_quit || lnum > line2 || !(subflags.do_all || do_again) || (sub_firstline.string[matchcol] == NUL && nmatch <= 1 && !re_multiline(regmatch.regprog)));
                nmatch = -1;

                if (lastone || nmatch_tl > 0 || (subflags.do_ask && did_split) || (nmatch = vim_regexec_multi(&regmatch, curwin, curbuf, sub_firstlnum, matchcol, NULL)) == 0 || regmatch.startpos[0].lnum > 0)
                {
                    if (new_start.string != NULL)
                    {
                         strcpy((char *)(new_start.string + new_start.length), (char *)(sub_firstline.string + copycol)) ;
                        new_start.length += sub_firstline.length - (size_t)copycol;
                        matchcol = (colnr_T)(sub_firstline.length - matchcol);
                        prev_matchcol = (colnr_T)(sub_firstline.length - prev_matchcol);

                        if (u_savesub(lnum) != OK)
                        {
                            break;
                        }
                        ml_replace(lnum, new_start.string, TRUE);
                        if (nmatch_tl > 0)
                        {
                            ++lnum;
                            if (u_savedel(lnum, nmatch_tl) != OK)
                            {
                                break;
                            }
                            for (i = 0; i < nmatch_tl; ++i)
                            {
                                ml_delete(lnum);
                            }
                            if (copycol > 0)
                            {
                                mark_adjust(lnum, lnum + nmatch_tl - 1, (long) LONG_MAX , -nmatch_tl);
                            }
                            else
                            {
                                mark_adjust(lnum - 1, lnum - 1, (long) LONG_MAX , -nmatch_tl);
                            }
                            if (subflags.do_ask)
                            {
                                deleted_lines(lnum, nmatch_tl);
                            }
                            --lnum;
                            line2 -= nmatch_tl;
                            nmatch_tl = 0;
                        }

                        if (subflags.do_ask)
                        {
                            changed_bytes(lnum, 0);
                        }
                        else
                        {
                            if (first_line == 0)
                            {
                                first_line = lnum;
                            }
                            last_line = lnum + 1;
                        }

                        sub_firstlnum = lnum;
                        vim_free(sub_firstline.string);
                        sub_firstline.string = new_start.string;
                        sub_firstline.length = new_start.length;
                        new_start.string = NULL;
                        new_start.length = 0;
                        matchcol = (colnr_T)(sub_firstline.length - matchcol);
                        prev_matchcol = (colnr_T)(sub_firstline.length - prev_matchcol);
                        copycol = 0;
                        did_split = false;
                    }
                    if (nmatch == -1 && !lastone)
                    {
                        nmatch = vim_regexec_multi(&regmatch, curwin, curbuf, sub_firstlnum, matchcol, NULL);
                    }

                    if (nmatch <= 0)
                    {
                        if (nmatch == -1)
                        {
                            lnum -= regmatch.startpos[0].lnum;
                        }
                        break;
                    }
                }

                line_breakcheck();
            }

            if (did_sub)
            {
                ++sub_nlines;
            }
            vim_free(new_start.string);
             vim_free(sub_firstline.string);
             (sub_firstline.string) = NULL;
             sub_firstline.length = 0;
        }

        line_breakcheck();
    }

    if (first_line != 0)
    {
        i = curbuf->b_ml.ml_line_count - old_line_count;
        changed_lines(first_line, 0, last_line - i, i);
    }

outofmem:
    vim_free(sub_firstline.string);

    if (subflags.do_count)
    {
        curwin->w_cursor = old_cursor;
    }

    if (sub_nsubs > start_nsubs)
    {
        if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
        {
            curbuf->b_op_start.lnum = eap->line1;
            curbuf->b_op_end.lnum = line2;
            curbuf->b_op_start.col = curbuf->b_op_end.col = 0;
        }

        if (!global_busy)
        {
            if (!subflags.do_ask)
            {
                if (endcolumn)
                {
                    coladvance((colnr_T)MAXCOL);
                }
                else
                {
                    beginline(BL_WHITE | BL_FIX);
                }
            }
            if (!do_sub_msg(subflags.do_count) && subflags.do_ask)
            {
                msg("");
            }
        }
        else
        {
            global_need_beginline = TRUE;
        }
        if (subflags.do_print)
        {
            print_line(curwin->w_cursor.lnum, subflags.do_number, subflags.do_list);
        }
    }
    else if (!global_busy)
    {
        if (got_int)
        {
            emsg(_(e_interrupted));
        }
        else if (got_match)
        {
            msg("");
        }
        else if (subflags.do_error)
        {
            semsg(_(e_pattern_not_found_str), get_search_pat());
        }
    }

    vim_regfree(regmatch.regprog);
    vim_free(sub);

    subflags.do_all = save_do_all;
    subflags.do_ask = save_do_ask;
}

    static int
do_sub_msg(int     count_only)
{
    if (((sub_nsubs > p_report && (KeyTyped || sub_nlines > 1 || p_report < 1)) || count_only) && messaging())
    {
        char    *msg_single;
        char    *msg_plural;

        if (got_int)
        {
             strcpy((char *)(msg_buf), (char *)(_("(Interrupted) "))) ;
        }
        else
        {
            *msg_buf = NUL;
        }

        msg_single = count_only
                    ? NGETTEXT("%ld match on %ld line", "%ld matches on %ld line", sub_nsubs)
                    : NGETTEXT("%ld substitution on %ld line", "%ld substitutions on %ld line", sub_nsubs);
        msg_plural = count_only
                    ? NGETTEXT("%ld match on %ld lines", "%ld matches on %ld lines", sub_nsubs)
                    : NGETTEXT("%ld substitution on %ld lines", "%ld substitutions on %ld lines", sub_nsubs);

        vim_snprintf_add(msg_buf, sizeof(msg_buf), NGETTEXT(msg_single, msg_plural, sub_nlines), sub_nsubs, (long)sub_nlines);

        if (msg(msg_buf))
        {
            set_keep_msg((char_u *)msg_buf, 0);
        }
        return TRUE;
    }
    if (got_int)
    {
        emsg(_(e_interrupted));
        return TRUE;
    }
    return FALSE;
}

    static void
global_exe_one(char_u *cmd, linenr_T lnum)
{
    curwin->w_cursor.lnum = lnum;
    curwin->w_cursor.col = 0;
    if (*cmd == NUL || *cmd == '\n')
    {
        do_cmdline((char_u *)"p", NULL, NULL, DOCMD_NOWAIT);
    }
    else
    {
        do_cmdline(cmd, NULL, NULL, DOCMD_NOWAIT);
    }
}

    static void
ex_global(exarg_T *eap)
{
    linenr_T    lnum;
    int         ndone = 0;
    int         type;
    char_u      *cmd;

    char_u      delim;
    char_u      *pat;
    size_t      patlen;
    char_u      *used_pat;
    regmmatch_T regmatch;
    int         match;
    int         which_pat;

    if (global_busy && (eap->line1 != 1 || eap->line2 != curbuf->b_ml.ml_line_count))
    {
        emsg(_(e_cannot_do_global_recursive_with_range));
        return;
    }

    if (eap->forceit)
    {
        type = 'v';
    }
    else
    {
        type = *eap->cmd;
    }
    cmd = eap->arg;
    which_pat = RE_LAST;

    if (*cmd == '\\')
    {
        ++cmd;
        if (vim_strchr((char_u *)"/?&", *cmd) == NULL)
        {
            emsg(_(e_backslash_should_be_followed_by));
            return;
        }
        if (*cmd == '&')
        {
            which_pat = RE_SUBST;
        }
        else
        {
            which_pat = RE_SEARCH;
        }
        ++cmd;
        pat = (char_u *)"";
        patlen = 0;
    }
    else if (*cmd == NUL)
    {
        emsg(_(e_regular_expression_missing_from_global));
        return;
    }
    else if (check_regexp_delim(*cmd) == FAIL)
    {
        return;
    }
    else
    {
        delim = *cmd;
        ++cmd;
        pat = cmd;
        cmd = skip_regexp_ex(cmd, delim, magic_isset(), &eap->arg, NULL, NULL);
        if (cmd[0] == delim)
        {
            *cmd++ = NUL;
        }
        patlen =  strlen((char *)(pat)) ;
    }

    if (search_regcomp(pat, patlen, &used_pat, RE_BOTH, which_pat, SEARCH_HIS, &regmatch) == FAIL)
    {
        emsg(_(e_invalid_command));
        return;
    }

    if (global_busy)
    {
        lnum = curwin->w_cursor.lnum;
        match = vim_regexec_multi(&regmatch, curwin, curbuf, lnum, (colnr_T)0, NULL);
        if ((type == 'g' && match) || (type == 'v' && !match))
        {
            global_exe_one(cmd, lnum);
        }
    }
    else
    {
        for (lnum = eap->line1; lnum <= eap->line2 && !got_int; ++lnum)
        {
            match = vim_regexec_multi(&regmatch, curwin, curbuf, lnum, (colnr_T)0, NULL);
            if (regmatch.regprog == NULL)
            {
                break;
            }
            if ((type == 'g' && match) || (type == 'v' && !match))
            {
                ml_setmarked(lnum);
                ndone++;
            }
            line_breakcheck();
        }

        if (got_int)
        {
            msg(_(e_interrupted));
        }
        else if (ndone == 0)
        {
            if (type == 'v')
            {
                if (in_vim9script())
                {
                    semsg(_(e_pattern_found_in_every_line_str), used_pat);
                }
                else
                {
                    smsg(_("Pattern found in every line: %s"), used_pat);
                }
            }
            else
            {
                if (in_vim9script())
                {
                    semsg(_(e_pattern_not_found_str), used_pat);
                }
                else
                {
                    smsg(_("Pattern not found: %s"), used_pat);
                }
            }
        }
        else
        {
            global_exe(cmd);
        }

        ml_clearmarked();
    }

    vim_regfree(regmatch.regprog);
}

    static void
global_exe(char_u *cmd)
{
    linenr_T old_lcount;
    buf_T    *old_buf = curbuf;
    linenr_T lnum;

    setpcmark();

    msg_didout = TRUE;

    sub_nsubs = 0;
    sub_nlines = 0;
    global_need_beginline = FALSE;
    global_busy = 1;
    old_lcount = curbuf->b_ml.ml_line_count;
    while (!got_int && (lnum = ml_firstmarked()) != 0 && global_busy == 1)
    {
        global_exe_one(cmd, lnum);
        ui_breakcheck();
    }

    global_busy = 0;
    if (global_need_beginline)
    {
        beginline(BL_WHITE | BL_FIX);
    }
    else
    {
        check_cursor();
    }

    changed_line_abv_curs();

    if (msg_col == 0 && msg_scrolled == 0)
    {
        msg_didout = FALSE;
    }

    if (!do_sub_msg(FALSE) && curbuf == old_buf)
    {
        msgmore(curbuf->b_ml.ml_line_count - old_lcount);
    }
}

