    static void
ex_drop(exarg_T *eap)
{
    int         split = FALSE;
    win_T       *wp;
    buf_T       *buf;
    tabpage_T   *tp;

    if (ERROR_IF_POPUP_WINDOW || ERROR_IF_TERM_POPUP_WINDOW)
    {
        return;
    }

    set_arglist(eap->arg);

    if ( ( (curwin)->w_alist ->al_ga.ga_len)  == 0)
    {
        return;
    }

    if (cmdmod.cmod_tab)
    {
        ex_all(eap);
        cmdmod.cmod_tab = 0;
        ex_rewind(eap);
        return;
    }

    buf = buflist_findnr( ((aentry_T *) (curwin)->w_alist ->al_ga.ga_data) [0].ae_fnum);

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
     {
         for ((wp) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next)
    {
        if (wp->w_buffer == buf)
        {
            goto_tabpage_win(tp, wp);
            curwin->w_arg_idx = 0;
            if (curbuf->b_ml.ml_flags & ML_EMPTY)
            {
                ex_rewind(eap);
            }
            return;
        }
    }
     }

    if (!buf_hide(curbuf))
    {
        ++emsg_off;
        split = check_changed(curbuf, CCGD_AW | CCGD_EXCMD);
        --emsg_off;
    }

    if (split)
    {
        eap->cmdidx = CMD_sfirst;
        eap->cmd[0] = 's';
    }
    else
    {
        eap->cmdidx = CMD_first;
    }
    ex_rewind(eap);
}

    static char_u *
skip_vimgrep_pat(char_u *p, char_u **s, int *flags)
{
    return skip_vimgrep_pat_ext(p, s, flags, NULL, NULL);
}

    static char_u *
skip_vimgrep_pat_ext(char_u *p, char_u **s, int *flags, char_u **nulp, int *cp)
{
    int         c;

    if (vim_isIDc(*p))
    {
        if (s != NULL)
        {
            *s = p;
        }
        p = skiptowhite(p);
        if (s != NULL && *p != NUL)
        {
            if (nulp != NULL)
            {
                *nulp = p;
                *cp = *p;
            }
            *p++ = NUL;
        }
    }
    else
    {
        if (s != NULL)
        {
            *s = p + 1;
        }
        c = *p;
        p = skip_regexp(p + 1, c, TRUE);
        if (*p != c)
        {
            return NULL;
        }

        if (s != NULL)
        {
            if (nulp != NULL)
            {
                *nulp = p;
                *cp = *p;
            }
            *p = NUL;
        }
        ++p;

        while (*p == 'g' || *p == 'j' || *p == 'f')
        {
            if (flags != NULL)
            {
                if (*p == 'g')
                {
                    *flags |= VGR_GLOBAL;
                }
                else if (*p == 'j')
                {
                    *flags |= VGR_NOJUMP;
                }
                else
                {
                    *flags |= VGR_FUZZY;
                }
            }
            ++p;
        }
    }
    return p;
}

// ==================== ex_cmds2.c ====================

    static int
autowrite(buf_T *buf, int forceit)
{
    int         r;
    bufref_T    bufref;

    if (!(p_aw || p_awa) || !p_write || bt_dontwrite(buf) || (!forceit && buf->b_p_ro) || buf->b_ffname == NULL)
    {
        return FAIL;
    }
    set_bufref(&bufref, buf);
    r = buf_write_all(buf, forceit);

    if (bufref_valid(&bufref) && bufIsChanged(buf))
    {
        r = FAIL;
    }
    return r;
}

    static void
autowrite_all(void)
{
    buf_T       *buf;

    if (!(p_aw || p_awa) || !p_write)
    {
        return;
    }
     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
     {
        if (bufIsChanged(buf) && !buf->b_p_ro && !bt_dontwrite(buf))
        {
            bufref_T    bufref;

            set_bufref(&bufref, buf);

            (void)buf_write_all(buf, FALSE);

            if (!bufref_valid(&bufref))
            {
                buf = firstbuf;
            }
        }
     }
}

    static int
check_changed(buf_T *buf, int flags)
{
    int         forceit = (flags & CCGD_FORCEIT);
    bufref_T    bufref;

    set_bufref(&bufref, buf);

    if (       !forceit && bufIsChanged(buf) && ((flags & CCGD_MULTWIN) || buf->b_nwindows <= 1) && (!(flags & CCGD_AW) || autowrite(buf, forceit) == FAIL))
    {
        if (flags & CCGD_EXCMD)
        {
            no_write_message();
        }
        else
        {
            no_write_message_nobang(curbuf);
        }
        return TRUE;
    }
    return FALSE;
}

    static int
can_abandon(buf_T *buf, int forceit)
{
    return (       buf_hide(buf) || !bufIsChanged(buf) || buf->b_nwindows > 1 || autowrite(buf, forceit) == OK || forceit);
}

    static void
add_bufnum(int *bufnrs, int *bufnump, int nr)
{
    int i;

    for (i = 0; i < *bufnump; ++i)
    {
        if (bufnrs[i] == nr)
        {
            return;
        }
    }
    bufnrs[*bufnump] = nr;
    *bufnump = *bufnump + 1;
}

    static int
check_changed_any(int         hidden, int         unload)
{
    int         ret = FALSE;
    buf_T       *buf;
    int         save;
    int         i;
    int         bufnum = 0;
    int         bufcount = 0;
    int         *bufnrs;
    tabpage_T   *tp;
    win_T       *wp;

     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
     {
        ++bufcount;
     }

    if (bufcount == 0)
    {
        return FALSE;
    }

    bufnrs =  (int *)alloc(sizeof(int) * (bufcount)) ;
    if (bufnrs == NULL)
    {
        return FALSE;
    }

    bufnrs[bufnum++] = curbuf->b_fnum;

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
     {
        if (wp->w_buffer != curbuf)
        {
            add_bufnum(bufnrs, &bufnum, wp->w_buffer->b_fnum);
        }
     }

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
     {
        if (tp != curtab)
        {
             for ((wp) = ((tp) == NULL || (tp) == curtab)             ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next) 
             {
                add_bufnum(bufnrs, &bufnum, wp->w_buffer->b_fnum);
             }
        }
     }

     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
     {
        add_bufnum(bufnrs, &bufnum, buf->b_fnum);
     }

    for (i = 0; i < bufnum; ++i)
    {
        buf = buflist_findnr(bufnrs[i]);
        if (buf == NULL)
        {
            continue;
        }
        if ((!hidden || buf->b_nwindows == 0) && bufIsChanged(buf))
        {
            bufref_T bufref;

            set_bufref(&bufref, buf);
            if (check_changed(buf, (p_awa ? CCGD_AW : 0) | CCGD_MULTWIN | CCGD_ALLBUF) && bufref_valid(&bufref))
            {
                break;
            }
        }
    }

    if (i >= bufnum)
    {
        goto theend;
    }

    ret = TRUE;
    exiting = FALSE;
    {
        if (vgetc_busy > 0)
        {
            msg_row = cmdline_row;
            msg_col = 0;
            msg_didout = FALSE;
        }
        if (semsg(_(e_no_write_since_last_change_for_buffer_str), buf_spname(buf) != NULL ? buf_spname(buf) : buf->b_fname))
        {
            save = no_wait_return;
            no_wait_return = FALSE;
            wait_return(FALSE);
            no_wait_return = save;
        }
    }

    if (buf != curbuf)
    {
         for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
         {
             for ((wp) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next)
             {
            if (wp->w_buffer == buf)
            {
                bufref_T bufref;

                set_bufref(&bufref, buf);

                goto_tabpage_win(tp, wp);

                if (!bufref_valid(&bufref))
                {
                    goto theend;
                }
                goto buf_found;
            }
             }
         }
    }
buf_found:

    if (buf != curbuf)
    {
        set_curbuf(buf, unload ? DOBUF_UNLOAD : DOBUF_GOTO);
    }

theend:
    vim_free(bufnrs);
    return ret;
}

    static int
check_fname(void)
{
    if (curbuf->b_ffname == NULL)
    {
        emsg(_(e_no_file_name));
        return FAIL;
    }
    return OK;
}

    static int
buf_write_all(buf_T *buf, int forceit)
{
    int     retval;
    buf_T       *old_curbuf = curbuf;

    retval = (buf_write(buf, buf->b_ffname, buf->b_fname, (linenr_T)1, buf->b_ml.ml_line_count, NULL, FALSE, forceit, TRUE, FALSE));
    if (curbuf != old_curbuf)
    {
        msg_source( highlight_attr[(int)(HLF_W)] );
        msg(_("Warning: Entered other buffer unexpectedly (check autocommands)"));
    }
    return retval;
}

    static void
ex_listdo(exarg_T *eap)
{
    int         i;
    win_T       *wp;
    tabpage_T   *tp;
    buf_T       *buf = curbuf;
    int         next_fnum = 0;

    if (curwin-> w_onebuf_opt.wo_wfb  && eap->cmdidx != CMD_windo && eap->cmdidx != CMD_tabdo)
    {
        if ((eap->cmdidx == CMD_ldo || eap->cmdidx == CMD_lfdo) && !eap->forceit)
        {
            emsg(_(e_winfixbuf_cannot_go_to_buffer));
            return;
        }

        if (win_valid(prevwin) && !prevwin-> w_onebuf_opt.wo_wfb )
        {
            win_goto(prevwin);
        }
        if (curwin-> w_onebuf_opt.wo_wfb )
        {
            (void)win_split(0, 0);

            if (curwin-> w_onebuf_opt.wo_wfb )
            {
                emsg(_(e_winfixbuf_cannot_go_to_buffer));
                return;
            }
        }
    }

    if (eap->cmdidx == CMD_cdo || eap->cmdidx == CMD_ldo || eap->cmdidx == CMD_cfdo || eap->cmdidx == CMD_lfdo)
    {
        ex_ni(eap);
        return;
    }

    if (eap->cmdidx == CMD_windo || eap->cmdidx == CMD_tabdo || buf_hide(curbuf) || !check_changed(curbuf, CCGD_AW | (eap->forceit ? CCGD_FORCEIT : 0) | CCGD_EXCMD))
    {
        i = 0;
        wp = firstwin;
        tp = first_tabpage;
        switch (eap->cmdidx)
        {
            case CMD_windo:
                for ( ; wp != NULL && i + 1 < eap->line1; wp = wp->w_next)
                {
                    i++;
                }
                break;
            case CMD_tabdo:
                for ( ; tp != NULL && i + 1 < eap->line1; tp = tp->tp_next)
                {
                    i++;
                }
                break;
            case CMD_argdo:
                i = eap->line1 - 1;
                break;
            default:
                break;
        }
        if (eap->cmdidx == CMD_bufdo)
        {
            for (buf = firstbuf; buf != NULL && (buf->b_fnum < eap->line1 || !buf->b_p_bl); buf = buf->b_next)
            {
                if (buf->b_fnum > eap->line2)
                {
                    buf = NULL;
                    break;
                }
            }
            if (buf != NULL)
            {
                goto_buffer(eap, DOBUF_FIRST, FORWARD, buf->b_fnum);
            }
        }
        else
        {
            setpcmark();
        }
        listcmd_busy = TRUE;

        while (!got_int && buf != NULL)
        {
            if (eap->cmdidx == CMD_argdo)
            {
                if (i ==  ( (curwin)->w_alist ->al_ga.ga_len) )
                {
                    break;
                }
                if (curwin->w_arg_idx != i || !editing_arg_idx(curwin))
                {
                    save_clear_shm_value();
                    do_argfile(eap, i);
                    restore_shm_value();
                }
                if (curwin->w_arg_idx != i)
                {
                    break;
                }
            }
            else if (eap->cmdidx == CMD_windo)
            {
                if (!win_valid(wp))
                {
                    break;
                }
                win_goto(wp);
                if (curwin != wp)
                {
                    break;
                }
                wp = curwin->w_next;
            }
            else if (eap->cmdidx == CMD_tabdo)
            {
                if (!valid_tabpage(tp))
                {
                    break;
                }
                goto_tabpage_tp(tp, TRUE, TRUE);
                tp = tp->tp_next;
            }
            else if (eap->cmdidx == CMD_bufdo)
            {
                next_fnum = -1;
                for (buf = curbuf->b_next; buf != NULL; buf = buf->b_next)
                {
                    if (buf->b_p_bl)
                    {
                        next_fnum = buf->b_fnum;
                        break;
                    }
                }
            }

            ++i;

            do_cmdline(eap->arg, eap->ea_getline, eap->cookie, DOCMD_VERBOSE + DOCMD_NOWAIT);

            if (eap->cmdidx == CMD_bufdo)
            {
                if (next_fnum < 0 || next_fnum > eap->line2)
                {
                    break;
                }
                 for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
                 {
                    if (buf->b_fnum == next_fnum)
                    {
                        break;
                    }
                 }
                if (buf == NULL)
                {
                    break;
                }

                save_clear_shm_value();
                goto_buffer(eap, DOBUF_FIRST, FORWARD, next_fnum);
                restore_shm_value();

                if (curbuf->b_fnum != next_fnum)
                {
                    break;
                }
            }

            if (eap->cmdidx == CMD_windo)
            {
                validate_cursor();

                if (curwin-> w_onebuf_opt.wo_scb )
                {
                    do_check_scrollbind(TRUE);
                }
            }

            if (eap->cmdidx == CMD_windo || eap->cmdidx == CMD_tabdo)
            {
                if (i+1 > eap->line2)
                {
                    break;
                }
            }
            if (eap->cmdidx == CMD_argdo && i >= eap->line2)
            {
                break;
            }
        }
        listcmd_busy = FALSE;
    }

}

