    static int
is_other_file(int fnum, char_u *ffname)
{
    if (fnum != 0)
    {
        if (fnum == curbuf->b_fnum)
        {
            return FALSE;
        }

        return TRUE;
    }

    if (ffname == NULL)
    {
        return TRUE;
    }

    if (*ffname == NUL)
    {
        return FALSE;
    }

    if (curbuf->b_sfname != NULL && *curbuf->b_sfname != NUL)
    {
        return  vim_fnamecmp((char_u *)(ffname), (char_u *)(curbuf->b_sfname))  != 0;
    }

    return otherfile(ffname);
}

    static void
do_exmode(int         improved)
{
    int         save_msg_scroll;
    int         prev_msg_row;
    linenr_T    prev_line;
    varnumber_T changedtick;

    if (improved)
    {
        exmode_active = EXMODE_VIM;
    }
    else
    {
        exmode_active = EXMODE_NORMAL;
    }
    State = MODE_NORMAL;
    may_trigger_modechanged();

    if (global_busy)
    {
        return;
    }

    save_msg_scroll = msg_scroll;
    ++RedrawingDisabled;
    ++no_wait_return;

    msg(_("Entering Ex mode.  Type \"visual\" to go to Normal mode."));
    while (exmode_active)
    {
        if (ex_normal_busy > 0 && typebuf.tb_len == 0)
        {
            exmode_active = FALSE;
            break;
        }
        msg_scroll = TRUE;
        need_wait_return = FALSE;
        ex_pressedreturn = FALSE;
        ex_no_reprint = FALSE;
        changedtick =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
        prev_msg_row = msg_row;
        prev_line = curwin->w_cursor.lnum;
        if (improved)
        {
            cmdline_row = msg_row;
            do_cmdline(NULL, getexline, NULL, 0);
        }
        else
        {
            do_cmdline(NULL, getexmodeline, NULL, DOCMD_NOWAIT);
        }
        lines_left = Rows - 1;

        if ((prev_line != curwin->w_cursor.lnum || changedtick !=  ((curbuf)->b_ct_di.di_tv.vval.v_number) ) && !ex_no_reprint)
        {
            if (curbuf->b_ml.ml_flags & ML_EMPTY)
            {
                emsg(_(e_empty_buffer));
            }
            else
            {
                if (ex_pressedreturn)
                {
                    msg_row = prev_msg_row;
                    if (prev_msg_row == Rows - 1)
                    {
                        msg_row--;
                    }
                }
                msg_col = 0;
                print_line_no_prefix(curwin->w_cursor.lnum, FALSE, FALSE);
                msg_clr_eos();
            }
        }
        else if (ex_pressedreturn && !ex_no_reprint)
        {
            if (curbuf->b_ml.ml_flags & ML_EMPTY)
            {
                emsg(_(e_empty_buffer));
            }
            else
            {
                emsg(_(e_at_end_of_file));
            }
        }
    }

    if (RedrawingDisabled > 0)
    {
        --RedrawingDisabled;
    }
    --no_wait_return;
    update_screen(UPD_CLEAR);
    need_wait_return = FALSE;
    msg_scroll = save_msg_scroll;
}

    static void
msg_verbose_cmd(linenr_T lnum, char_u *cmd)
{
    ++no_wait_return;
    verbose_enter_scroll();

    if (lnum == 0)
    {
        smsg(_("Executing: %s"), cmd);
    }
    else
    {
        smsg(_("line %ld: %s"), (long)lnum, cmd);
    }
    if (msg_silent == 0)
    {
        msg_puts("\n");
    }

    verbose_leave_scroll();
    --no_wait_return;
}

    static int
do_cmdline_cmd(char_u *cmd)
{
    return do_cmdline(cmd, NULL, NULL, DOCMD_VERBOSE|DOCMD_NOWAIT|DOCMD_KEYTYPED);
}

    static int
do_cmd_argument(char_u *cmd)
{
    return do_cmdline(cmd, NULL, NULL, DOCMD_VERBOSE|DOCMD_NOWAIT|DOCMD_KEYTYPED|DOCMD_RANGEOK);
}

    static int
do_cmdline(char_u      *cmdline, char_u      *(*fgetline)(int, void *, int, getline_opt_T), void        *cookie, int         flags)
{
    char_u      *next_cmdline;
    char_u      *cmdline_copy = NULL;
    int         used_getline = FALSE;
    static int  recursive = 0;
    int         msg_didout_before_start = 0;
    int         count = 0;
    int         did_inc_RedrawingDisabled = FALSE;
    int         retval = OK;
    static int  call_depth = 0;

    if (call_depth >= 200)
    {
        emsg(_(e_command_too_recursive));
        return FAIL;
    }
    ++call_depth;

    did_emsg = FALSE;

    if (!(flags & DOCMD_KEYTYPED) && !getline_equal(fgetline, cookie, getexline))
    {
        KeyTyped = FALSE;
    }

    next_cmdline = cmdline;
    do
    {
        if (next_cmdline == NULL)
        {
            did_emsg = FALSE;
        }

        if (next_cmdline == NULL)
        {
            if (count == 1 && getline_equal(fgetline, cookie, getexline))
            {
                msg_didout = TRUE;
            }
            if (fgetline == NULL || (next_cmdline = fgetline(':', cookie, 0, in_vim9script() ? GETLINE_CONCAT_CONTBAR : GETLINE_CONCAT_CONT)) == NULL)
            {
                if (KeyTyped && !(flags & DOCMD_REPEAT))
                {
                    need_wait_return = FALSE;
                }
                retval = FAIL;
                break;
            }
            used_getline = TRUE;

            if (flags & DOCMD_KEEPLINE)
            {
                vim_free(repeat_cmdline);
                if (count == 0)
                {
                    repeat_cmdline = vim_strsave(next_cmdline);
                }
                else
                {
                    repeat_cmdline = NULL;
                }
            }
        }

        else if (cmdline_copy == NULL)
        {
            next_cmdline = vim_strsave(next_cmdline);
            if (next_cmdline == NULL)
            {
                emsg(_(e_out_of_memory));
                retval = FAIL;
                break;
            }
        }
        cmdline_copy = next_cmdline;

        if (count++ == 0)
        {
            if (!(flags & DOCMD_NOWAIT) && !recursive)
            {
                msg_didout_before_start = msg_didout;
                msg_didany = FALSE;
                msg_start();
                msg_scroll = TRUE;
                ++no_wait_return;
                ++RedrawingDisabled;
                did_inc_RedrawingDisabled = TRUE;
            }
        }

        if ((p_verbose >= 15 &&  (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_name)  != NULL) || p_verbose >= 16)
        {
            msg_verbose_cmd( (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_lnum) , cmdline_copy);
        }

        ++recursive;
        next_cmdline = do_one_cmd(&cmdline_copy, flags,  fgetline ,  cookie );
        --recursive;

        if (next_cmdline == NULL)
        {
             vim_free(cmdline_copy);
             (cmdline_copy) = NULL;

            if (getline_equal(fgetline, cookie, getexline) && new_last_cmdline != NULL)
            {
                vim_free(last_cmdline);
                last_cmdline = new_last_cmdline;
                new_last_cmdline = NULL;
            }
        }
        else
        {
              memmove((char *)((cmdline_copy)), (char *)((next_cmdline)),  strlen((char *)(next_cmdline))  + 1)  ;
            next_cmdline = cmdline_copy;
        }

    }
    while (!((got_int)) && !(did_emsg && used_getline && (getline_equal(fgetline, cookie, getexmodeline) || getline_equal(fgetline, cookie, getexline))) && (next_cmdline != NULL || (flags & DOCMD_REPEAT)))
        ;

    vim_free(cmdline_copy);
    did_emsg_syntax = FALSE;

    if (did_inc_RedrawingDisabled)
    {
        if (RedrawingDisabled > 0)
        {
            --RedrawingDisabled;
        }
        --no_wait_return;
        msg_scroll = FALSE;

        if (retval == FAIL)
        {
            need_wait_return = FALSE;
            msg_didany = FALSE;
        }
        else if (need_wait_return)
        {
            msg_didout |= msg_didout_before_start;
            wait_return(FALSE);
        }
    }

    if_level = 0;

    --call_depth;
    return retval;
}

    static int
getline_equal(char_u      *(*fgetline)(int, void *, int, getline_opt_T), void        *cookie  __attribute__((unused)) , char_u      *(*func)(int, void *, int, getline_opt_T))
{
    return fgetline == func;
}

    static void *
getline_cookie(char_u      *(*fgetline)(int, void *, int, getline_opt_T)  __attribute__((unused)) , void        *cookie)
{
    return cookie;
}

    static int
compute_buffer_local_count(int addr_type, int lnum, int offset)
{
    buf_T   *buf;
    buf_T   *nextbuf;
    int     count = offset;

    buf = firstbuf;
    while (buf->b_next != NULL && buf->b_fnum < lnum)
    {
        buf = buf->b_next;
    }
    while (count != 0)
    {
        count += (offset < 0) ? 1 : -1;
        nextbuf = (offset < 0) ? buf->b_prev : buf->b_next;
        if (nextbuf == NULL)
        {
            break;
        }
        buf = nextbuf;
        if (addr_type == ADDR_LOADED_BUFFERS)
        {
            while (buf->b_ml.ml_mfp == NULL)
            {
                nextbuf = (offset < 0) ? buf->b_prev : buf->b_next;
                if (nextbuf == NULL)
                {
                    break;
                }
                buf = nextbuf;
            }
        }
    }
    if (addr_type == ADDR_LOADED_BUFFERS)
    {
        while (buf->b_ml.ml_mfp == NULL)
        {
            nextbuf = (offset >= 0) ? buf->b_prev : buf->b_next;
            if (nextbuf == NULL)
            {
                break;
            }
            buf = nextbuf;
        }
    }
    return buf->b_fnum;
}

    static int
current_win_nr(win_T *win)
{
    win_T       *wp;
    int         nr = 0;

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
    {
        ++nr;
        if (wp == win)
        {
            break;
        }
    }
    return nr;
}

    static int
current_tab_nr(tabpage_T *tab)
{
    tabpage_T   *tp;
    int         nr = 0;

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
    {
        ++nr;
        if (tp == tab)
        {
            break;
        }
    }
    return nr;
}

    static int
comment_start(char_u *p, int starts_with_colon  __attribute__((unused)) )
{
    if (in_vim9script())
    {
        return p[0] == '#' && !starts_with_colon;
    }
    return *p == '"';
}

    static char_u *
do_one_cmd(char_u      **cmdlinep, int         flags, char_u      *(*fgetline)(int, void *, int, getline_opt_T), void        *cookie)
{
    char_u      *p;
    linenr_T    lnum;
    long        n;
    char        *errormsg = NULL;
    char_u      *after_modifier = NULL;
    exarg_T     ea;
    cmdmod_T    save_cmdmod;
    int         save_reg_executing = reg_executing;
    int         save_pending_end_reg_executing = pending_end_reg_executing;
    int         ni;
    char_u      *cmd;
    int         starts_with_colon = FALSE;
    int         may_have_range;
    int         sourcing = flags & DOCMD_VERBOSE;
    int         did_append_cmd = FALSE;

      memset((&(ea)), (0), (sizeof(ea)))  ;
    ea.line1 = 1;
    ea.line2 = 1;

    if (quitmore && !getline_equal(fgetline, cookie, getnextac))
    {
        --quitmore;
    }

    save_cmdmod = cmdmod;

    if ((*cmdlinep)[0] == '#' && (*cmdlinep)[1] == '!')
    {
        goto doend;
    }

    ea.cmd = *cmdlinep;
    ea.cmdlinep = cmdlinep;
    ea.ea_getline = fgetline;
    ea.cookie = cookie;
    if (parse_command_modifiers(&ea, &errormsg, &cmdmod, FALSE) == FAIL)
    {
        goto doend;
    }
    apply_cmdmod(&cmdmod);
    after_modifier = ea.cmd;

    ea.skip = (if_level > 0);

    cmd = ea.cmd;

    int vim9script = in_vim9script();
    if (vim9script && (flags & DOCMD_RANGEOK) == 0)
    {
        may_have_range = FALSE;
        for (p = ea.cmd; p >= *cmdlinep; --p)
        {
            if (*p == ':')
            {
                may_have_range = TRUE;
            }
            if (p < ea.cmd && ! ((*p) == ' ' || (*p) == '\t') )
            {
                break;
            }
        }
    }
    else
    {
        may_have_range = TRUE;
    }
    if (may_have_range)
    {
        ea.cmd = skip_range(ea.cmd, TRUE, NULL);
    }

    if (vim9script && !may_have_range)
    {
        if (ea.cmd == cmd + 1 && *cmd == '$')
        {
            --ea.cmd;
        }
        p = find_ex_command(&ea, NULL, NULL, NULL);
        if (ea.cmdidx == CMD_SIZE)
        {
            char_u *ar = skip_range(ea.cmd, TRUE, NULL);

            if (ar > ea.cmd && !ea.skip)
            {
                semsg(_(e_colon_required_before_range_str), ea.cmd);
                goto doend;
            }
        }
    }
    else
    {
        p = find_ex_command(&ea, NULL, NULL, NULL);
    }

    ea.cmd = cmd;

    if (! ((int)(ea.cmdidx) < 0) )
    {
        if (ea.cmdidx != CMD_SIZE)
        {
            ea.addr_type = cmdnames[(int)ea.cmdidx].cmd_addr_type;
        }
        else
        {
            ea.addr_type = ADDR_LINES;
        }

        if (ea.cmdidx == CMD_wincmd && p != NULL)
        {
            get_wincmd_addr_type(skipwhite(p), &ea);
        }
    }

    if (!may_have_range)
    {
        ea.line1 = ea.line2 = default_address(&ea);
    }
    else if (parse_cmd_address(&ea, &errormsg, FALSE) == FAIL)
    {
        goto doend;
    }

    ea.cmd = skipwhite(ea.cmd);
    while (*ea.cmd == ':')
    {
        ea.cmd = skipwhite(ea.cmd + 1);
    }

    if (*ea.cmd == NUL || comment_start(ea.cmd, starts_with_colon) || (ea.nextcmd = check_nextcmd(ea.cmd)) != NULL)
    {
        if (ea.skip)
        {
            goto doend;
        }
        errormsg = ex_range_without_command(&ea);
        goto doend;
    }

    if (p != NULL && ea.cmdidx == CMD_SIZE && !ea.skip &&  ((unsigned)(*ea.cmd) - 'A' < 26)  && has_cmdundefined())
    {
        int ret;

        p = ea.cmd;
        while ( ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  ||  ((unsigned)(*p) - '0' < 10) ) )
        {
            ++p;
        }
        p = vim_strnsave(ea.cmd, p - ea.cmd);
        ret = apply_autocmds(EVENT_CMDUNDEFINED, p, p, TRUE, NULL);
        vim_free(p);
        p = (ret) ? find_ex_command(&ea, NULL, NULL, NULL) : ea.cmd;
    }

    if (p == NULL)
    {
        if (!ea.skip)
        {
            errormsg = _(e_ambiguous_use_of_user_defined_command);
        }
        goto doend;
    }
    if (*p == '!' && ea.cmd[1] == 0151 && ea.cmd[0] == 78 && ! ((int)(ea.cmdidx) < 0) )
    {
        errormsg = uc_fun_cmd();
        goto doend;
    }

    if (ea.cmdidx == CMD_SIZE)
    {
        if (!ea.skip)
        {
             strcpy((char *)(IObuff), (char *)(_(e_not_an_editor_command))) ;
            if (!sourcing)
            {
                if (after_modifier != NULL)
                {
                    append_command(after_modifier);
                }
                else
                {
                    append_command(*cmdlinep);
                }
                did_append_cmd = TRUE;
            }
            errormsg = (char *)IObuff;
            did_emsg_syntax = TRUE;
        }
        goto doend;
    }

    ni = (! ((int)(ea.cmdidx) < 0)  && (cmdnames[ea.cmdidx].cmd_func == ex_ni || cmdnames[ea.cmdidx].cmd_func == ex_script_ni));

    if (ea.cmdidx == CMD_if)
    {
        ++if_level;
    }
    if (if_level)
    {
        if (ea.cmdidx == CMD_endif)
        {
            --if_level;
        }
        goto doend;
    }

    if (*p == '!' && ea.cmdidx != CMD_substitute && ea.cmdidx != CMD_smagic && ea.cmdidx != CMD_snomagic)
    {
        ++p;
        ea.forceit = TRUE;
    }
    else
    {
        ea.forceit = FALSE;
    }

    if (! ((int)(ea.cmdidx) < 0) )
    {
        ea.argt = (long)cmdnames[(int)ea.cmdidx].cmd_argt;
    }

    if (!ea.skip)
    {
        if (!curbuf->b_p_ma && (ea.argt & EX_MODIFY))
        {
            errormsg = _(e_cannot_make_changes_modifiable_is_off);
            goto doend;
        }

        if (! ((int)(ea.cmdidx) < 0) )
        {
            if (cmdwin_type != 0 && !(ea.argt & EX_CMDWIN))
            {
                errormsg = _(e_invalid_in_cmdline_window);
                goto doend;
            }
            if (text_locked() && !(ea.argt & EX_LOCK_OK))
            {
                errormsg = _(get_text_locked_msg());
                goto doend;
            }
        }

        if (!(ea.argt & (EX_CMDWIN | EX_LOCK_OK)) && ea.cmdidx != CMD_checktime && ea.cmdidx != CMD_edit && ea.cmdidx != CMD_file && ! ((int)(ea.cmdidx) < 0)  && curbuf_locked())
        {
            goto doend;
        }

        if (!ni && !(ea.argt & EX_RANGE) && ea.addr_count > 0)
        {
            errormsg = _(e_no_range_allowed);
            goto doend;
        }
    }

    if (!ni && !(ea.argt & EX_BANG) && ea.forceit)
    {
        errormsg = _(e_no_bang_allowed);
        goto doend;
    }

    if (!ea.skip && !ni && (ea.argt & EX_RANGE))
    {
        if (!global_busy && ea.line1 > ea.line2)
        {
            if (msg_silent == 0)
            {
                if (sourcing || exmode_active)
                {
                    errormsg = _(e_backwards_range_given);
                    goto doend;
                }
                if (ask_yesno((char_u *) _("Backwards range given, OK to swap"), FALSE) != 'y')
                {
                    goto doend;
                }
            }
            lnum = ea.line1;
            ea.line1 = ea.line2;
            ea.line2 = lnum;
        }
        if ((errormsg = invalid_range(&ea)) != NULL)
        {
            goto doend;
        }
    }

    if ((ea.addr_type == ADDR_OTHER) && ea.addr_count == 0)
    {
        ea.line2 = 1;
    }

    correct_range(&ea);

    if (ea.cmdidx == CMD_bang)
    {
        ea.arg = p;
    }
    else
    {
        ea.arg = skipwhite(p);
    }

    if (ea.cmdidx == CMD_file && *ea.arg != NUL && curbuf_locked())
    {
        goto doend;
    }

    if (ea.argt & EX_ARGOPT)
    {
        while (ea.arg[0] == '+' && ea.arg[1] == '+')
        {
            if (getargopt(&ea) == FAIL && !ni)
            {
                errormsg = _(e_invalid_argument);
                goto doend;
            }
        }
    }

    if (ea.cmdidx == CMD_write || ea.cmdidx == CMD_update)
    {
        if (*ea.arg == '>')
        {
            if (*++ea.arg != '>')
            {
                errormsg = _(e_use_w_or_w_gt_gt);
                goto doend;
            }
            ea.arg = skipwhite(ea.arg + 1);
            ea.append = TRUE;
        }
        else if (*ea.arg == '!' && ea.cmdidx == CMD_write)
        {
            ++ea.arg;
            ea.usefilter = TRUE;
        }
    }

    if (ea.cmdidx == CMD_read)
    {
        if (ea.forceit)
        {
            ea.usefilter = TRUE;
            ea.forceit = FALSE;
        }
        else if (*ea.arg == '!')
        {
            ++ea.arg;
            ea.usefilter = TRUE;
        }
    }

    if (ea.cmdidx == CMD_lshift || ea.cmdidx == CMD_rshift)
    {
        ea.amount = 1;
        while (*ea.arg == *ea.cmd)
        {
            ++ea.arg;
            ++ea.amount;
        }
        ea.arg = skipwhite(ea.arg);
    }

    if ((ea.argt & EX_CMDARG) && !ea.usefilter)
    {
        ea.do_ecmd_cmd = getargcmd(&ea.arg);
    }

    if ((ea.argt & EX_TRLBAR) && !ea.usefilter)
    {
        separate_nextcmd(&ea, FALSE);
    }
    else if (ea.cmdidx == CMD_bang || ea.cmdidx == CMD_terminal || ea.cmdidx == CMD_global || ea.cmdidx == CMD_vglobal || ea.usefilter)
    {
        for (p = ea.arg; *p; ++p)
        {
            if (*p == '\\' && p[1] == '\n')
            {
                  memmove((char *)((p)), (char *)((p + 1)),  strlen((char *)(p + 1))  + 1)  ;
            }
            else if (*p == '\n' && !(ea.argt & EX_EXPR_ARG))
            {
                ea.nextcmd = p + 1;
                *p = NUL;
                break;
            }
        }
    }

    if ((ea.argt & EX_DFLALL) && ea.addr_count == 0)
    {
        address_default_all(&ea);
    }

    if (       (ea.argt & EX_REGSTR) && *ea.arg != NUL && (! ((int)(ea.cmdidx) < 0)  || *ea.arg != '=') && !((ea.argt & EX_COUNT) &&  ((unsigned)(*ea.arg) - '0' < 10) ))
    {
        if (*ea.arg == '*' || *ea.arg == '+')
        {
            errormsg = _(e_invalid_register_name);
            goto doend;
        }
        if (valid_yank_reg(*ea.arg, (! ((int)(ea.cmdidx) < 0)  && ea.cmdidx != CMD_put && ea.cmdidx != CMD_iput)))
        {
            ea.regname = *ea.arg++;
            ea.arg = skipwhite(ea.arg);
        }
    }

    if ((ea.argt & EX_COUNT) &&  ((unsigned)(*ea.arg) - '0' < 10)  && (!(ea.argt & EX_BUFNAME) || *(p = skipdigits(ea.arg + 1)) == NUL ||  ((*p) == ' ' || (*p) == '\t') ))
    {
        n = getdigits_quoted(&ea.arg);
        ea.arg = skipwhite(ea.arg);
        if (n <= 0 && !ni && (ea.argt & EX_ZEROR) == 0)
        {
            errormsg = _(e_positive_count_required);
            goto doend;
        }
        if (ea.addr_type != ADDR_LINES)
        {
            ea.line2 = n;
            if (ea.addr_count == 0)
            {
                ea.addr_count = 1;
            }
        }
        else
        {
            ea.line1 = ea.line2;
            if (ea.line2 >= LONG_MAX - (n - 1))
            {
                ea.line2 = LONG_MAX;
            }
            else
            {
                ea.line2 += n - 1;
            }
            ++ea.addr_count;
            if (ea.line2 > curbuf->b_ml.ml_line_count)
            {
                ea.line2 = curbuf->b_ml.ml_line_count;
            }
        }
    }

    if (ea.argt & EX_FLAGS)
    {
        get_flags(&ea);
    }
    if (!ni && !(ea.argt & EX_EXTRA) && *ea.arg != NUL && *ea.arg != '"' && (*ea.arg != '|' || (ea.argt & EX_TRLBAR) == 0))
    {
        errormsg = ex_errmsg(e_trailing_characters_str, ea.arg);
        goto doend;
    }

    if (!ni && (ea.argt & EX_NEEDARG) && *ea.arg == NUL)
    {
        errormsg = _(e_argument_required);
        goto doend;
    }

    if ((ea.argt & EX_XFILE) && expand_filename(&ea, cmdlinep, &errormsg) == FAIL)
    {
        goto doend;
    }

    if ((ea.argt & EX_BUFNAME) && *ea.arg != NUL && ea.addr_count == 0 && ! ((int)(ea.cmdidx) < 0) )
    {
        if (ea.cmdidx == CMD_bdelete || ea.cmdidx == CMD_bwipeout || ea.cmdidx == CMD_bunload)
        {
            p = skiptowhite_esc(ea.arg);
        }
        else
        {
            p = ea.arg +  strlen((char *)(ea.arg)) ;
            while (p > ea.arg &&  ((p[-1]) == ' ' || (p[-1]) == '\t') )
            {
                --p;
            }
        }
        ea.line2 = buflist_findpat(ea.arg, p, (ea.argt & EX_BUFUNL) != 0, FALSE, FALSE);
        if (ea.line2 < 0)
        {
            goto doend;
        }
        ea.addr_count = 1;
        ea.arg = skipwhite(p);
    }

    if (ea.cmdidx == CMD_try && cmdmod.cmod_did_esilent > 0)
    {
        emsg_silent -= cmdmod.cmod_did_esilent;
        if (emsg_silent < 0)
        {
            emsg_silent = 0;
        }
        cmdmod.cmod_did_esilent = 0;
    }

    if ( ((int)(ea.cmdidx) < 0) )
    {
        do_ucmd(&ea);
    }
    else
    {
        (cmdnames[ea.cmdidx].cmd_func)(&ea);
        if (ea.errmsg != NULL)
        {
            errormsg = ea.errmsg;
        }
    }

doend:
    if (curwin->w_cursor.lnum == 0)
    {
        curwin->w_cursor.lnum = 1;
        curwin->w_cursor.col = 0;
    }

    if (errormsg != NULL && *errormsg != NUL && !did_emsg)
    {
        if ((sourcing || !KeyTyped) && !did_append_cmd)
        {
            if (errormsg != (char *)IObuff)
            {
                 strcpy((char *)(IObuff), (char *)(errormsg)) ;
                errormsg = (char *)IObuff;
            }
            append_command(*cmdlinep);
        }
        emsg(errormsg);
    }

    undo_cmdmod(&cmdmod);
    cmdmod = save_cmdmod;
    reg_executing = save_reg_executing;
    pending_end_reg_executing = save_pending_end_reg_executing;

    if (ea.nextcmd && *ea.nextcmd == NUL)
    {
        ea.nextcmd = NULL;
    }

    return ea.nextcmd;
}

static char ex_error_buf[MSG_BUF_LEN];

    static char *
ex_errmsg(char *msg, char_u *arg)
{
    vim_snprintf(ex_error_buf, MSG_BUF_LEN, _(msg), arg);
    return ex_error_buf;
}

static const char exmode_plus[] = "+";

    static char *
ex_range_without_command(exarg_T *eap)
{
    char *errormsg = NULL;

    if ((*eap->cmd == '|' || (exmode_active && eap->cmd != (char_u *)exmode_plus + 1)))
    {
        eap->cmdidx = CMD_print;
        eap->argt = EX_RANGE+EX_COUNT+EX_TRLBAR;
        if ((errormsg = invalid_range(eap)) == NULL)
        {
            correct_range(eap);
            ex_print(eap);
        }
    }
    else if (eap->addr_count != 0)
    {
        if (eap->line2 > curbuf->b_ml.ml_line_count)
        {
            if (vim_strchr(p_cpo, CPO_MINUS) != NULL)
            {
                eap->line2 = -1;
            }
            else
            {
                eap->line2 = curbuf->b_ml.ml_line_count;
            }
        }

        if (eap->line2 < 0)
        {
            errormsg = _(e_invalid_range);
        }
        else
        {
            if (eap->line2 == 0)
            {
                curwin->w_cursor.lnum = 1;
            }
            else
            {
                curwin->w_cursor.lnum = eap->line2;
            }
            beginline(BL_SOL | BL_FIX);
        }
    }
    return errormsg;
}

    static int
checkforcmd_opt(char_u      **pp, char        *cmd, int         len, int         noparen)
{
    int         i;

    for (i = 0; cmd[i] != NUL; ++i)
    {
        if (((char_u *)cmd)[i] != (*pp)[i])
        {
            break;
        }
    }
    if (i >= len && ! ( ((unsigned)((*pp)[i]) - 'A' < 26)  ||  ((unsigned)((*pp)[i]) - 'a' < 26) )  && (*pp)[i] != '_' && (!noparen || ((*pp)[i] != '(' && (*pp)[i] != '.')))
    {
        *pp = skipwhite(*pp + i);
        return TRUE;
    }
    return FALSE;
}

    static int
checkforcmd(char_u      **pp, char        *cmd, int         len)
{
    return checkforcmd_opt(pp, cmd, len, FALSE);
}

    static int
checkforcmd_noparen(char_u      **pp, char        *cmd, int         len)
{
    return checkforcmd_opt(pp, cmd, len, TRUE);
}

    static char_u *
find_ucmd_repl(char_u *arg)
{
    char_u      *p = arg;

    while (*p == '-')
    {
        p = skipwhite(skiptowhite(p));
    }

    if (! ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) ) )
    {
        return NULL;
    }
    while ( ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  ||  ((unsigned)(*p) - '0' < 10) ) )
    {
        ++p;
    }

    return *p == NUL ? NULL : skipwhite(p);
}

    static char_u *
find_cmd_block_start(char_u *line)
{
    char_u      *p = skipwhite(line);

    for (;;)
    {
        char_u  *arg = p;

        if (*p == '{' && ends_excmd2(p, skipwhite(p + 1)))
        {
            return p;
        }

        if (checkforcmd_noparen(&arg, "autocmd", 2))
        {
            if (*arg == '!')
            {
                arg = skipwhite(arg + 1);
            }
            p = au_find_cmd_arg(arg);
        }
        else if (checkforcmd_noparen(&arg, "command", 3))
        {
            if (*arg == '!')
            {
                arg = skipwhite(arg + 1);
            }
            p = find_ucmd_repl(arg);
        }
        else
        {
            return NULL;
        }

        if (p == NULL)
        {
            return NULL;
        }
        p = skipwhite(p);
    }
}

    static int
parse_command_modifiers(exarg_T     *eap, char        **errormsg, cmdmod_T    *cmod, int         skip_only)
{
    char_u  *orig_cmd = eap->cmd;
    char_u  *cmd_start = NULL;
    int     use_plus_cmd = FALSE;
    int     starts_with_colon = FALSE;
    int     vim9script = in_vim9script();
    int     has_visual_range = FALSE;

      memset(((cmod)), (0), (sizeof(*(cmod))))  ;
    cmod->cmod_flags = sticky_cmdmod_flags;

    if ( strncmp((char *)(eap->cmd), (char *)("'<,'>"), (5))  == 0)
    {
        eap->cmd += 5;
        cmd_start = eap->cmd;
        has_visual_range = TRUE;
    }

    for (;;)
    {
        char_u  *p;

        while (*eap->cmd == ' ' || *eap->cmd == '\t' || *eap->cmd == ':')
        {
            if (*eap->cmd == ':')
            {
                starts_with_colon = TRUE;
            }
            ++eap->cmd;
        }

        if (*eap->cmd == NUL && exmode_active && (getline_equal(eap->ea_getline, eap->cookie, getexmodeline) || getline_equal(eap->ea_getline, eap->cookie, getexline)) && curwin->w_cursor.lnum < curbuf->b_ml.ml_line_count)
        {
            use_plus_cmd = TRUE;
            if (!skip_only)
            {
                ex_pressedreturn = TRUE;
            }
            break;
        }

        if (comment_start(eap->cmd, starts_with_colon))
        {
            eap->nextcmd = vim_strchr(eap->cmd, '\n');
            if (eap->nextcmd != NULL)
            {
                ++eap->nextcmd;
            }
            if (vim9script)
            {
                if (has_cmdmod(cmod, FALSE))
                {
                    *errormsg = _(e_command_modifier_without_command);
                }
            }
            return FAIL;
        }
        if (*eap->cmd == '\n')
        {
            eap->nextcmd = eap->cmd + 1;
            return FAIL;
        }
        if (*eap->cmd == NUL)
        {
            if (!skip_only)
            {
                ex_pressedreturn = TRUE;
                if (vim9script && has_cmdmod(cmod, FALSE))
                {
                    *errormsg = _(e_command_modifier_without_command);
                }
            }
            return FAIL;
        }

        p = skip_range(eap->cmd, TRUE, NULL);

        if (vim9script)
        {
            char_u *s;
            char_u *n;

            for (s = eap->cmd;  ( ((unsigned)(*s) - 'A' < 26)  ||  ((unsigned)(*s) - 'a' < 26) ) ; ++s)
            {
                ;
            }
            n = skipwhite(s);
            if (*n == '.' || *n == '=' || (*n != NUL && n[1] == '=') || *s == '[')
            {
                break;
            }
        }

        switch (*p)
        {
            case 'a':
                if (!checkforcmd_noparen(&eap->cmd, "aboveleft", 3))
                {
                            break;
                }
                        cmod->cmod_split |= WSP_ABOVE;
                        continue;

            case 'b':
                if (checkforcmd_noparen(&eap->cmd, "belowright", 3))
                        {
                            cmod->cmod_split |= WSP_BELOW;
                            continue;
                        }
                        if (checkforcmd_opt(&eap->cmd, "browse", 3, TRUE))
                        {
                            continue;
                        }
                        if (!checkforcmd_noparen(&eap->cmd, "botright", 2))
                        {
                            break;
                        }
                        cmod->cmod_split |= WSP_BOT;
                        continue;

            case 'c':
                if (!checkforcmd_opt(&eap->cmd, "confirm", 4, TRUE))
                {
                            break;
                }
                        continue;

            case 'k':
                if (checkforcmd_noparen(&eap->cmd, "keepmarks", 3))
                        {
                            cmod->cmod_flags |= CMOD_KEEPMARKS;
                            continue;
                        }
                        if (checkforcmd_noparen(&eap->cmd, "keepalt", 5))
                        {
                            cmod->cmod_flags |= CMOD_KEEPALT;
                            continue;
                        }
                        if (checkforcmd_noparen(&eap->cmd, "keeppatterns", 5))
                        {
                            cmod->cmod_flags |= CMOD_KEEPPATTERNS;
                            continue;
                        }
                        if (!checkforcmd_noparen(&eap->cmd, "keepjumps", 5))
                        {
                            break;
                        }
                        cmod->cmod_flags |= CMOD_KEEPJUMPS;
                        continue;

            case 'f':
                        {
                            char_u  *reg_pat;
                            char_u  *nulp = NULL;
                            int     c = 0;

                            if (!checkforcmd_noparen(&p, "filter", 4) || *p == NUL || (ends_excmd(*p)))
                            {
                                break;
                            }
                            if (*p == '!')
                            {
                                cmod->cmod_filter_force = TRUE;
                                p = skipwhite(p + 1);
                                if (*p == NUL || ends_excmd(*p))
                                {
                                    break;
                                }
                            }
                            if (skip_only)
                            {
                                p = skip_vimgrep_pat(p, NULL, NULL);
                            }
                            else
                            {
                                p = skip_vimgrep_pat_ext(p, &reg_pat, NULL, &nulp, &c);
                            }
                            if (p == NULL || *p == NUL)
                            {
                                break;
                            }
                            if (!skip_only)
                            {
                                cmod->cmod_filter_regmatch.regprog =
                                                vim_regcomp(reg_pat, RE_MAGIC);
                                if (cmod->cmod_filter_regmatch.regprog == NULL)
                                {
                                    break;
                                }
                                if (nulp != NULL)
                                {
                                    *nulp = c;
                                }
                            }
                            eap->cmd = p;
                            continue;
                        }

            case 'h':
                if (checkforcmd_noparen(&eap->cmd, "horizontal", 3))
                        {
                            cmod->cmod_split |= WSP_HOR;
                            continue;
                        }
                        if (p != eap->cmd || !checkforcmd_noparen(&p, "hide", 3) || *p == NUL || ends_excmd(*p))
                        {
                            break;
                        }
                        eap->cmd = p;
                        cmod->cmod_flags |= CMOD_HIDE;
                        continue;

            case 'l':
                if (checkforcmd_noparen(&eap->cmd, "lockmarks", 3))
                        {
                            cmod->cmod_flags |= CMOD_LOCKMARKS;
                            continue;
                        }
                        if (checkforcmd_noparen(&eap->cmd, "legacy", 3))
                        {
                            if (ends_excmd2(p, eap->cmd))
                            {
                                *errormsg =
                                      _(e_legacy_must_be_followed_by_command);
                                return FAIL;
                            }
                            cmod->cmod_flags &= ~CMOD_VIM9CMD;
                            cmod->cmod_flags |= CMOD_LEGACY;
                            continue;
                        }

                        if (!checkforcmd_noparen(&eap->cmd, "leftabove", 5))
                        {
                            break;
                        }
                        cmod->cmod_split |= WSP_ABOVE;
                        continue;

            case 'n':
                if (checkforcmd_noparen(&eap->cmd, "noautocmd", 3))
                        {
                            cmod->cmod_flags |= CMOD_NOAUTOCMD;
                            continue;
                        }
                        if (!checkforcmd_noparen(&eap->cmd, "noswapfile", 3))
                        {
                            break;
                        }
                        cmod->cmod_flags |= CMOD_NOSWAPFILE;
                        continue;

            case 'r':
                if (!checkforcmd_noparen(&eap->cmd, "rightbelow", 6))
                {
                            break;
                }
                        cmod->cmod_split |= WSP_BELOW;
                        continue;

            case 's':
                if (checkforcmd_noparen(&eap->cmd, "sandbox", 3))
                        {
                            cmod->cmod_flags |= CMOD_SANDBOX;
                            continue;
                        }
                        if (!checkforcmd_noparen(&eap->cmd, "silent", 3))
                        {
                            break;
                        }
                        cmod->cmod_flags |= CMOD_SILENT;
                        if (*eap->cmd == '!' && ! ((eap->cmd[-1]) == ' ' || (eap->cmd[-1]) == '\t') )
                        {
                            eap->cmd = skipwhite(eap->cmd + 1);
                            cmod->cmod_flags |= CMOD_ERRSILENT;
                        }
                        continue;

            case 't':
                if (checkforcmd_noparen(&p, "tab", 3))
                        {
                            if (!skip_only)
                            {
                                long tabnr = get_address(eap, &eap->cmd, ADDR_TABS, eap->skip, skip_only, FALSE, 1);
                                if (tabnr ==  LONG_MAX )
                                {
                                    cmod->cmod_tab = tabpage_index(curtab) + 1;
                                }
                                else
                                {
                                    if (tabnr < 0 || tabnr >  current_tab_nr(NULL) )
                                    {
                                        *errormsg = _(e_invalid_range);
                                        return FAIL;
                                    }
                                    cmod->cmod_tab = tabnr + 1;
                                }
                            }
                            eap->cmd = p;
                            continue;
                        }
                        if (!checkforcmd_noparen(&eap->cmd, "topleft", 2))
                        {
                            break;
                        }
                        cmod->cmod_split |= WSP_TOP;
                        continue;

            case 'u':
                if (!checkforcmd_noparen(&eap->cmd, "unsilent", 3))
                {
                            break;
                }
                        cmod->cmod_flags |= CMOD_UNSILENT;
                        continue;

            case 'v':
                if (checkforcmd_noparen(&eap->cmd, "vertical", 4))
                        {
                            cmod->cmod_split |= WSP_VERT;
                            continue;
                        }
                        if (checkforcmd_noparen(&eap->cmd, "vim9cmd", 4))
                        {
                            if (ends_excmd2(p, eap->cmd))
                            {
                                *errormsg =
                                      _(e_vim9cmd_must_be_followed_by_command);
                                return FAIL;
                            }
                            cmod->cmod_flags &= ~CMOD_LEGACY;
                            cmod->cmod_flags |= CMOD_VIM9CMD;
                            continue;
                        }
                        if (!checkforcmd_noparen(&p, "verbose", 4))
                        {
                            break;
                        }
                        if (vim_isdigit(*eap->cmd))
                        {
                            cmod->cmod_verbose = atoi((char *)eap->cmd) + 1;
                        }
                        else
                        {
                            cmod->cmod_verbose = 2;
                        }
                        eap->cmd = p;
                        continue;
        }
        break;
    }

    if (has_visual_range)
    {
        if (eap->cmd > cmd_start)
        {
            if (use_plus_cmd)
            {
                size_t len =  strlen((char *)(cmd_start)) ;

                 memmove((char *)(orig_cmd), (char *)(cmd_start), len) ;
                 strcpy((char *)(orig_cmd + len), (char *)(" *+")) ;
            }
            else
            {
                 memmove((char *)(cmd_start - 5), (char *)(cmd_start), eap->cmd - cmd_start) ;
                eap->cmd -= 5;
                 memmove((char *)(eap->cmd - 1), (char *)(":'<,'>"), 6) ;
            }
        }
        else
        {
            if (use_plus_cmd)
            {
                eap->cmd = (char_u *)"'<,'>+";
            }
            else
            {
                eap->cmd = orig_cmd;
            }
        }
    }
    else if (use_plus_cmd)
    {
        eap->cmd = (char_u *)exmode_plus;
    }

    return OK;
}

    static int
has_cmdmod(cmdmod_T *cmod, int ignore_silent)
{
    return (cmod->cmod_flags != 0 && (!ignore_silent || (cmod->cmod_flags & ~(CMOD_SILENT | CMOD_ERRSILENT | CMOD_UNSILENT)) != 0))
            || cmod->cmod_split != 0
            || cmod->cmod_verbose > 0
            || cmod->cmod_tab != 0
            || cmod->cmod_filter_regmatch.regprog != NULL;
}

    static void
apply_cmdmod(cmdmod_T *cmod)
{
    if (cmod->cmod_verbose > 0)
    {
        if (cmod->cmod_verbose_save == 0)
        {
            cmod->cmod_verbose_save = p_verbose + 1;
        }
        p_verbose = cmod->cmod_verbose - 1;
    }

    if ((cmod->cmod_flags & (CMOD_SILENT | CMOD_UNSILENT)) && cmod->cmod_save_msg_silent == 0)
    {
        cmod->cmod_save_msg_silent = msg_silent + 1;
        cmod->cmod_save_msg_scroll = msg_scroll;
    }
    if (cmod->cmod_flags & CMOD_SILENT)
    {
        ++msg_silent;
    }
    if (cmod->cmod_flags & CMOD_UNSILENT)
    {
        msg_silent = 0;
    }

    if (cmod->cmod_flags & CMOD_ERRSILENT)
    {
        ++emsg_silent;
        ++cmod->cmod_did_esilent;
    }

    if ((cmod->cmod_flags & CMOD_NOAUTOCMD) && cmod->cmod_save_ei == NULL)
    {
        cmod->cmod_save_ei = vim_strsave(p_ei);
        set_string_option_direct((char_u *)"ei", -1, (char_u *)"all", OPT_FREE,  (-6) );
    }
}

    static void
undo_cmdmod(cmdmod_T *cmod)
{
    if (cmod->cmod_verbose_save > 0)
    {
        p_verbose = cmod->cmod_verbose_save - 1;
        cmod->cmod_verbose_save = 0;
    }

    if (cmod->cmod_save_ei != NULL)
    {
        set_string_option_direct((char_u *)"ei", -1, cmod->cmod_save_ei, OPT_FREE,  (-6) );
        free_string_option(cmod->cmod_save_ei);
        cmod->cmod_save_ei = NULL;
    }

    vim_regfree(cmod->cmod_filter_regmatch.regprog);

    if (cmod->cmod_save_msg_silent > 0)
    {
        if (!did_emsg || msg_silent > cmod->cmod_save_msg_silent - 1)
        {
            msg_silent = cmod->cmod_save_msg_silent - 1;
        }
        emsg_silent -= cmod->cmod_did_esilent;
        if (emsg_silent < 0)
        {
            emsg_silent = 0;
        }
        msg_scroll = cmod->cmod_save_msg_scroll;

        if (redirecting())
        {
            msg_col = 0;
        }

        cmod->cmod_save_msg_silent = 0;
        cmod->cmod_did_esilent = 0;
    }
}

    static int
parse_cmd_address(exarg_T *eap, char **errormsg, int silent)
{
    int         address_count = 1;
    linenr_T    lnum;
    int         need_check_cursor = FALSE;
    int         ret = FAIL;

    for (;;)
    {
        eap->line1 = eap->line2;
        eap->line2 = default_address(eap);
        eap->cmd = skipwhite(eap->cmd);
        lnum = get_address(eap, &eap->cmd, eap->addr_type, eap->skip, silent, eap->addr_count == 0, address_count++);
        if (eap->cmd == NULL)
        {
            goto theend;
        }
        if (lnum ==  LONG_MAX )
        {
            if (*eap->cmd == '%')
            {
                ++eap->cmd;
                switch (eap->addr_type)
                {
                    case ADDR_LINES:
                    case ADDR_OTHER:
                        eap->line1 = 1;
                        eap->line2 = curbuf->b_ml.ml_line_count;
                        break;
                    case ADDR_LOADED_BUFFERS:
                        {
                            buf_T       *buf = firstbuf;

                            while (buf->b_next != NULL && buf->b_ml.ml_mfp == NULL)
                            {
                                buf = buf->b_next;
                            }
                            eap->line1 = buf->b_fnum;
                            buf = lastbuf;
                            while (buf->b_prev != NULL && buf->b_ml.ml_mfp == NULL)
                            {
                                buf = buf->b_prev;
                            }
                            eap->line2 = buf->b_fnum;
                            break;
                        }
                    case ADDR_BUFFERS:
                        eap->line1 = firstbuf->b_fnum;
                        eap->line2 = lastbuf->b_fnum;
                        break;
                    case ADDR_WINDOWS:
                    case ADDR_TABS:
                        if ( ((int)(eap->cmdidx) < 0) )
                        {
                            eap->line1 = 1;
                            eap->line2 = eap->addr_type == ADDR_WINDOWS
                                                  ?  current_win_nr(NULL)  :  current_tab_nr(NULL) ;
                        }
                        else
                        {
                            *errormsg = _(e_invalid_range);
                            goto theend;
                        }
                        break;
                    case ADDR_TABS_RELATIVE:
                    case ADDR_UNSIGNED:
                    case ADDR_QUICKFIX:
                        *errormsg = _(e_invalid_range);
                        goto theend;
                    case ADDR_ARGUMENTS:
                        if ( ( (curwin)->w_alist ->al_ga.ga_len)  == 0)
                        {
                            eap->line1 = eap->line2 = 0;
                        }
                        else
                        {
                            eap->line1 = 1;
                            eap->line2 =  ( (curwin)->w_alist ->al_ga.ga_len) ;
                        }
                        break;
                    case ADDR_QUICKFIX_VALID:
                        break;
                    case ADDR_NONE:
                        break;
                }
                ++eap->addr_count;
            }
            else if (*eap->cmd == '*' && vim_strchr(p_cpo, CPO_STAR) == NULL)
            {
                pos_T       *fp;

                if (eap->addr_type != ADDR_LINES)
                {
                    *errormsg = _(e_invalid_range);
                    goto theend;
                }

                ++eap->cmd;
                if (!eap->skip)
                {
                    fp = getmark('<', FALSE);
                    if (check_mark(fp) == FAIL)
                    {
                        goto theend;
                    }
                    eap->line1 = fp->lnum;
                    fp = getmark('>', FALSE);
                    if (check_mark(fp) == FAIL)
                    {
                        goto theend;
                    }
                    eap->line2 = fp->lnum;
                    ++eap->addr_count;
                }
            }
        }
        else
        {
            eap->line2 = lnum;
        }
        eap->addr_count++;

        if (*eap->cmd == ';')
        {
            if (!eap->skip)
            {
                curwin->w_cursor.lnum = eap->line2;

                if (eap->line2 > 0)
                {
                    check_cursor();
                }
                else
                {
                    check_cursor_col();
                }
                need_check_cursor = TRUE;
            }
        }
        else if (*eap->cmd != ',')
        {
            break;
        }
        ++eap->cmd;
    }

    if (eap->addr_count == 1)
    {
        eap->line1 = eap->line2;
        if (lnum ==  LONG_MAX )
        {
            eap->addr_count = 0;
        }
    }
    ret = OK;

theend:
    if (need_check_cursor)
    {
        check_cursor();
    }
    return ret;
}

    static void
append_command(char_u *cmd)
{
    size_t  len =  strlen((char *)(IObuff)) ;
    char_u  *s = cmd;
    char_u  *d;

    if (len >  (1024+1)  - 100)
    {
        d = IObuff +  (1024+1)  - 100;
        d -= mb_head_off(IObuff, d);
         strcpy((char *)(d), (char *)("...")) ;
    }
     strcat((char *)(IObuff), (char *)(": ")) ;
    d = IObuff +  strlen((char *)(IObuff)) ;
    while (*s != NUL && d - IObuff + 5 <  (1024+1) )
    {
        if (enc_utf8 ? (s[0] == 0xc2 && s[1] == 0xa0) : *s == 0xa0)
        {
            s += enc_utf8 ? 2 : 1;
             strcpy((char *)(d), (char *)("<a0>")) ;
            d += 4;
        }
        else if (d - IObuff + (*mb_ptr2len)(s) + 1 >=  (1024+1) )
        {
            break;
        }
        else
        {
             if (has_mbyte)
             {
                 mb_copy_char(&(s), &(d));
             }
             else
             {
                 *(d)++ = *(s)++;
             }
        }
    }
    *d = NUL;
}

    static int
one_letter_cmd(char_u *p, cmdidx_T *idx)
{
    if (in_vim9script())
    {
        return FALSE;
    }
    if (p[0] == 'k' && (p[1] != 'e' || (p[1] == 'e' && p[2] != 'e')))
    {
        *idx = CMD_k;
        return TRUE;
    }
    if (p[0] == 's' && ((p[1] == 'c' && (p[2] == NUL || (p[2] != 's' && p[2] != 'r' && (p[3] == NUL || (p[3] != 'i' && p[4] != 'p'))))) || p[1] == 'g' || (p[1] == 'i' && p[2] != 'm' && p[2] != 'l' && p[2] != 'g') || p[1] == 'I' || (p[1] == 'r' && p[2] != 'e')))
    {
        *idx = CMD_substitute;
        return TRUE;
    }
    return FALSE;
}

    static char_u *
find_ex_command(exarg_T *eap, int     *full  __attribute__((unused)) , int     (*lookup)(char_u *, size_t, int cmd, cctx_T *)  __attribute__((unused)) , cctx_T  *cctx  __attribute__((unused)) )
{
    int         len;
    char_u      *p;
    int         i;
    int         vim9 = FALSE;

    p = eap->cmd;
    if (one_letter_cmd(p, &eap->cmdidx))
    {
        ++p;
        if (full != NULL)
        {
            *full = TRUE;
        }
    }
    else
    {
        while ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) ) )
        {
            ++p;
        }
        if (eap->cmd[0] == 'p' && eap->cmd[1] == 'y')
        {
            while ( ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  ||  ((unsigned)(*p) - '0' < 10) ) )
            {
                ++p;
            }
        }
        else if (*p == '9' &&  strncmp((char *)("vim9"), (char *)(eap->cmd), (4))  == 0)
        {
            ++p;
            while ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) ) )
            {
                ++p;
            }
        }

        if (p == eap->cmd && vim_strchr((char_u *)"@*!=><&~#}", *p) != NULL)
        {
            ++p;
        }
        len = (int)(p - eap->cmd);
        if (!vim9 && *eap->cmd == 'd' && (p[-1] == 'l' || p[-1] == 'p'))
        {
            for (i = 0; i < len; ++i)
            {
                if (eap->cmd[i] != ((char_u *)"delete")[i])
                {
                    break;
                }
            }
            if (i == len - 1)
            {
                --len;
                if (p[-1] == 'l')
                {
                    eap->flags |= EXFLAG_LIST;
                }
                else
                {
                    eap->flags |= EXFLAG_PRINT;
                }
            }
        }

        if ( ((unsigned)(eap->cmd[0]) - 'a' < 26) )
        {
            int c1 = eap->cmd[0];
            int c2 = len == 1 ? NUL : eap->cmd[1];

            if (command_count != (int)CMD_SIZE)
            {
                iemsg(e_command_table_needs_to_be_updated_run_make_cmdidxs);
                getout(1);
            }

            eap->cmdidx = cmdidxs1[ ((c1) - 'a') ];
            if ( ((unsigned)(c2) - 'a' < 26) )
            {
                eap->cmdidx += cmdidxs2[ ((c1) - 'a') ][ ((c2) - 'a') ];
            }
        }
        else if ( ((unsigned)(eap->cmd[0]) - 'A' < 26) )
        {
            eap->cmdidx = CMD_Next;
        }
        else
        {
            eap->cmdidx = CMD_bang;
        }

        for ( ; (int)eap->cmdidx < (int)CMD_SIZE; eap->cmdidx = (cmdidx_T)((int)eap->cmdidx + 1))
        {
            if ( strncmp((char *)(cmdnames[(int)eap->cmdidx].cmd_name), (char *)((char *)eap->cmd), ((size_t)len))  == 0)
            {
                break;
            }
        }

        if (vim9 && eap->cmdidx != CMD_SIZE)
        {
            if (eap->cmdidx == CMD_mode || eap->cmdidx == CMD_Print)
            {
                eap->cmdidx = CMD_SIZE;
            }
            else if ((cmdnames[eap->cmdidx].cmd_argt & EX_WHOLE) && len < (int)cmdnames[eap->cmdidx].cmd_namelen)
            {
                semsg(_(e_command_cannot_be_shortened_str), eap->cmd);
                eap->cmdidx = CMD_SIZE;
            }
        }

        if (eap->cmdidx == CMD_star && vim_strchr(p_cpo, CPO_STAR) == NULL)
        {
            p = eap->cmd;
        }

        if ((eap->cmdidx == CMD_SIZE || eap->cmdidx == CMD_Print) && *eap->cmd >= 'A' && *eap->cmd <= 'Z')
        {
            while ( ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  ||  ((unsigned)(*p) - '0' < 10) ) )
            {
                ++p;
            }
            p = find_ucmd(eap, p, full, NULL, NULL);
        }
        if (p == NULL || p == eap->cmd)
        {
            eap->cmdidx = CMD_SIZE;
        }
    }

    if (eap->cmdidx == CMD_final && p - eap->cmd == 4 && !vim9)
    {
        eap->cmdidx = CMD_finally;
    }

    if (eap->cmdidx == CMD_horizontal && p - eap->cmd == 2)
    {
        eap->cmdidx = CMD_SIZE;
    }

    return p;
}

    static cmdidx_T
excmd_get_cmdidx(char_u *cmd, int len)
{
    cmdidx_T idx;

    if (!one_letter_cmd(cmd, &idx))
    {
        for (idx = (cmdidx_T)0; (int)idx < (int)CMD_SIZE; idx = (cmdidx_T)((int)idx + 1))
        {
            if ( strncmp((char *)(cmdnames[(int)idx].cmd_name), (char *)(cmd), ((size_t)len))  == 0)
            {
                break;
            }
        }
    }

    return idx;
}

    static long
excmd_get_argt(cmdidx_T idx)
{
    return (long)cmdnames[(int)idx].cmd_argt;
}

    static char_u *
skip_range(char_u      *cmd_start, int         skip_star, int         *ctx)
{
    char_u      *cmd = cmd_start;
    unsigned    delim;

    while (vim_strchr((char_u *)" \t0123456789.$%'/?-+,;\\", *cmd) != NULL)
    {
        if (*cmd == '\\')
        {
            if (cmd[1] == '?' || cmd[1] == '/' || cmd[1] == '&')
            {
                ++cmd;
            }
            else
            {
                break;
            }
        }
        else if (*cmd == '\'')
        {
            char_u *p = cmd;

            while (p > cmd_start)
            {
                --p;
                if (! ((*p) == ' ' || (*p) == '\t') )
                {
                    break;
                }
            }
            if (cmd > cmd_start && ! ((*p) == ' ' || (*p) == '\t')  && *p != ',' && *p != ';')
            {
                break;
            }
            if (*++cmd == NUL && ctx != NULL)
            {
                *ctx = EXPAND_NOTHING;
            }
        }
        else if (*cmd == '/' || *cmd == '?')
        {
            delim = *cmd++;
            while (*cmd != NUL && *cmd != delim)
            {
                if (*cmd++ == '\\' && *cmd != NUL)
                {
                    ++cmd;
                }
            }
            if (*cmd == NUL && ctx != NULL)
            {
                *ctx = EXPAND_NOTHING;
            }
        }
        if (*cmd != NUL)
        {
            ++cmd;
        }
    }

    while (*cmd == ':')
    {
        cmd = skipwhite(cmd + 1);
    }

    if (skip_star && *cmd == '*' && vim_strchr(p_cpo, CPO_STAR) == NULL)
    {
        cmd = skipwhite(cmd + 1);
    }

    return cmd;
}

    static void
addr_error(cmd_addr_T addr_type)
{
    if (addr_type == ADDR_NONE)
    {
        emsg(_(e_no_range_allowed));
    }
    else
    {
        emsg(_(e_invalid_range));
    }
}

    static linenr_T
default_address(exarg_T *eap)
{
    linenr_T lnum = 0;

    switch (eap->addr_type)
    {
        case ADDR_LINES:
        case ADDR_OTHER:
            if (curwin->w_cursor.lnum > curbuf->b_ml.ml_line_count)
            {
                lnum = curbuf->b_ml.ml_line_count;
            }
            else
            {
                lnum = curwin->w_cursor.lnum;
            }
            break;
        case ADDR_WINDOWS:
            lnum =  current_win_nr(curwin) ;
            break;
        case ADDR_ARGUMENTS:
            lnum = curwin->w_arg_idx + 1;
            if (lnum >  ( (curwin)->w_alist ->al_ga.ga_len) )
            {
                lnum =  ( (curwin)->w_alist ->al_ga.ga_len) ;
            }
            break;
        case ADDR_LOADED_BUFFERS:
        case ADDR_BUFFERS:
            lnum = curbuf->b_fnum;
            break;
        case ADDR_TABS:
            lnum =  current_tab_nr(curtab) ;
            break;
        case ADDR_TABS_RELATIVE:
        case ADDR_UNSIGNED:
            lnum = 1;
            break;
        case ADDR_QUICKFIX:
            break;
        case ADDR_QUICKFIX_VALID:
            break;
        case ADDR_NONE:
            break;
    }
    return lnum;
}

    static linenr_T
get_address(exarg_T     *eap  __attribute__((unused)) , char_u      **ptr, cmd_addr_T  addr_type, int         skip, int         silent, int         to_other_file, int         address_count  __attribute__((unused)) )
{
    int         c;
    int         i;
    long        n;
    char_u      *cmd;
    pos_T       pos;
    pos_T       *fp;
    linenr_T    lnum;
    buf_T       *buf;

    cmd = skipwhite(*ptr);
    lnum =  LONG_MAX ;
    do
    {
        switch (*cmd)
        {
            case '.':
                ++cmd;
                switch (addr_type)
                {
                    case ADDR_LINES:
                    case ADDR_OTHER:
                        lnum = curwin->w_cursor.lnum;
                        break;
                    case ADDR_WINDOWS:
                        lnum =  current_win_nr(curwin) ;
                        break;
                    case ADDR_ARGUMENTS:
                        lnum = curwin->w_arg_idx + 1;
                        break;
                    case ADDR_LOADED_BUFFERS:
                    case ADDR_BUFFERS:
                        lnum = curbuf->b_fnum;
                        break;
                    case ADDR_TABS:
                        lnum =  current_tab_nr(curtab) ;
                        break;
                    case ADDR_NONE:
                    case ADDR_TABS_RELATIVE:
                    case ADDR_UNSIGNED:
                        addr_error(addr_type);
                        cmd = NULL;
                        goto error;
                        break;
                    case ADDR_QUICKFIX:
                        break;
                    case ADDR_QUICKFIX_VALID:
                        break;
                }
                break;

            case '$':
                ++cmd;
                switch (addr_type)
                {
                    case ADDR_LINES:
                    case ADDR_OTHER:
                        lnum = curbuf->b_ml.ml_line_count;
                        break;
                    case ADDR_WINDOWS:
                        lnum =  current_win_nr(NULL) ;
                        break;
                    case ADDR_ARGUMENTS:
                        lnum =  ( (curwin)->w_alist ->al_ga.ga_len) ;
                        break;
                    case ADDR_LOADED_BUFFERS:
                        buf = lastbuf;
                        while (buf->b_ml.ml_mfp == NULL)
                        {
                            if (buf->b_prev == NULL)
                            {
                                break;
                            }
                            buf = buf->b_prev;
                        }
                        lnum = buf->b_fnum;
                        break;
                    case ADDR_BUFFERS:
                        lnum = lastbuf->b_fnum;
                        break;
                    case ADDR_TABS:
                        lnum =  current_tab_nr(NULL) ;
                        break;
                    case ADDR_NONE:
                    case ADDR_TABS_RELATIVE:
                    case ADDR_UNSIGNED:
                        addr_error(addr_type);
                        cmd = NULL;
                        goto error;
                        break;
                    case ADDR_QUICKFIX:
                        break;
                    case ADDR_QUICKFIX_VALID:
                        break;
                }
                break;

            case '\'':
                if (*++cmd == NUL)
                {
                    cmd = NULL;
                    goto error;
                }
                if (addr_type != ADDR_LINES)
                {
                    addr_error(addr_type);
                    cmd = NULL;
                    goto error;
                }
                if (skip)
                {
                    ++cmd;
                }
                else
                {
                    fp = getmark(*cmd, to_other_file && cmd[1] == NUL);
                    ++cmd;
                    if (fp == (pos_T *)-1)
                    {
                        lnum = curwin->w_cursor.lnum;
                    }
                    else
                    {
                        if (check_mark(fp) == FAIL)
                        {
                            cmd = NULL;
                            goto error;
                        }
                        lnum = fp->lnum;
                    }
                }
                break;

            case '/':
            case '?':
                c = *cmd++;
                if (addr_type != ADDR_LINES)
                {
                    addr_error(addr_type);
                    cmd = NULL;
                    goto error;
                }
                if (skip)
                {
                    cmd = skip_regexp(cmd, c, magic_isset());
                    if (*cmd == c)
                    {
                        ++cmd;
                    }
                }
                else
                {
                    int flags;

                    pos = curwin->w_cursor;

                    if (lnum > 0 && lnum !=  LONG_MAX )
                    {
                        curwin->w_cursor.lnum =
                                lnum > curbuf->b_ml.ml_line_count
                                           ? curbuf->b_ml.ml_line_count : lnum;
                    }

                    if (c == '/' && curwin->w_cursor.lnum > 0)
                    {
                        curwin->w_cursor.col = MAXCOL;
                    }
                    else
                    {
                        curwin->w_cursor.col = 0;
                    }
                    searchcmdlen = 0;
                    flags = silent ? SEARCH_KEEP : SEARCH_HIS | SEARCH_MSG;
                    if (!do_search(NULL, c, c, cmd,  strlen((char *)(cmd)) , 1L, flags, NULL))
                    {
                        curwin->w_cursor = pos;
                        cmd = NULL;
                        goto error;
                    }
                    lnum = curwin->w_cursor.lnum;
                    curwin->w_cursor = pos;
                    cmd += searchcmdlen;
                }
                break;

            case '\\':
                ++cmd;
                if (addr_type != ADDR_LINES)
                {
                    addr_error(addr_type);
                    cmd = NULL;
                    goto error;
                }
                if (*cmd == '&')
                {
                    i = RE_SUBST;
                }
                else if (*cmd == '?' || *cmd == '/')
                {
                    i = RE_SEARCH;
                }
                else
                {
                    emsg(_(e_backslash_should_be_followed_by));
                    cmd = NULL;
                    goto error;
                }

                if (!skip)
                {
                    if (lnum !=  LONG_MAX )
                    {
                        pos.lnum = lnum;
                    }
                    else
                    {
                        pos.lnum = curwin->w_cursor.lnum;
                    }

                    if (*cmd != '?')
                    {
                        pos.col = MAXCOL;
                    }
                    else
                    {
                        pos.col = 0;
                    }
                    pos.coladd = 0;
                    if (searchit(curwin, curbuf, &pos, NULL, *cmd == '?' ?  (-1)  : FORWARD, (char_u *)"", 0, 1L, SEARCH_MSG, i, NULL) != FAIL)
                    {
                        lnum = pos.lnum;
                    }
                    else
                    {
                        cmd = NULL;
                        goto error;
                    }
                }
                ++cmd;
                break;

            default:
                if ( ((unsigned)(*cmd) - '0' < 10) )
                {
                    lnum = getdigits(&cmd);
                }
        }

        for (;;)
        {
            cmd = skipwhite(cmd);
            if (*cmd != '-' && *cmd != '+' && ! ((unsigned)(*cmd) - '0' < 10) )
            {
                break;
            }

            if (lnum ==  LONG_MAX )
            {
                switch (addr_type)
                {
                    case ADDR_LINES:
                    case ADDR_OTHER:
                        lnum = curwin->w_cursor.lnum;
                        break;
                    case ADDR_WINDOWS:
                        lnum =  current_win_nr(curwin) ;
                        break;
                    case ADDR_ARGUMENTS:
                        lnum = curwin->w_arg_idx + 1;
                        break;
                    case ADDR_LOADED_BUFFERS:
                    case ADDR_BUFFERS:
                        lnum = curbuf->b_fnum;
                        break;
                    case ADDR_TABS:
                        lnum =  current_tab_nr(curtab) ;
                        break;
                    case ADDR_TABS_RELATIVE:
                        lnum = 1;
                        break;
                    case ADDR_QUICKFIX:
                        break;
                    case ADDR_QUICKFIX_VALID:
                        break;
                    case ADDR_NONE:
                    case ADDR_UNSIGNED:
                        lnum = 0;
                        break;
                }
            }

            if ( ((unsigned)(*cmd) - '0' < 10) )
            {
                i = '+';
            }
            else
            {
                i = *cmd++;
            }
            if (! ((unsigned)(*cmd) - '0' < 10) )
            {
                n = 1;
            }
            else
            {
                n = getdigits(&cmd);
                if (n ==  LONG_MAX )
                {
                    emsg(_(e_line_number_out_of_range));
                    cmd = NULL;
                    goto error;
                }
            }

            if (addr_type == ADDR_TABS_RELATIVE)
            {
                emsg(_(e_invalid_range));
                cmd = NULL;
                goto error;
            }
            else if (addr_type == ADDR_LOADED_BUFFERS || addr_type == ADDR_BUFFERS)
            {
                lnum = compute_buffer_local_count(addr_type, lnum, (i == '-') ? -1 * n : n);
            }
            else
            {
                if (i == '-')
                {
                    lnum -= n;
                }
                else
                {
                    if (lnum >= 0 && n >= LONG_MAX - lnum)
                    {
                        emsg(_(e_line_number_out_of_range));
                        cmd = NULL;
                        goto error;
                    }
                    lnum += n;
                }
            }
        }
    } while (*cmd == '/' || *cmd == '?');

error:
    *ptr = cmd;
    return lnum;
}

    static void
address_default_all(exarg_T *eap)
{
    eap->line1 = 1;
    switch (eap->addr_type)
    {
        case ADDR_LINES:
        case ADDR_OTHER:
            eap->line2 = curbuf->b_ml.ml_line_count;
            break;
        case ADDR_LOADED_BUFFERS:
            {
                buf_T *buf = firstbuf;

                while (buf->b_next != NULL && buf->b_ml.ml_mfp == NULL)
                {
                    buf = buf->b_next;
                }
                eap->line1 = buf->b_fnum;
                buf = lastbuf;
                while (buf->b_prev != NULL && buf->b_ml.ml_mfp == NULL)
                {
                    buf = buf->b_prev;
                }
                eap->line2 = buf->b_fnum;
            }
            break;
        case ADDR_BUFFERS:
            eap->line1 = firstbuf->b_fnum;
            eap->line2 = lastbuf->b_fnum;
            break;
        case ADDR_WINDOWS:
            eap->line2 =  current_win_nr(NULL) ;
            break;
        case ADDR_TABS:
            eap->line2 =  current_tab_nr(NULL) ;
            break;
        case ADDR_TABS_RELATIVE:
            eap->line2 = 1;
            break;
        case ADDR_ARGUMENTS:
            if ( ( (curwin)->w_alist ->al_ga.ga_len)  == 0)
            {
                eap->line1 = eap->line2 = 0;
            }
            else
            {
                eap->line2 =  ( (curwin)->w_alist ->al_ga.ga_len) ;
            }
            break;
        case ADDR_QUICKFIX_VALID:
            break;
        case ADDR_NONE:
        case ADDR_UNSIGNED:
        case ADDR_QUICKFIX:
            iemsg("Cannot use EX_DFLALL with ADDR_NONE, ADDR_UNSIGNED or ADDR_QUICKFIX");
            break;
    }
}

    static void
get_flags(exarg_T *eap)
{
    while (vim_strchr((char_u *)"lp#", *eap->arg) != NULL)
    {
        if (*eap->arg == 'l')
        {
            eap->flags |= EXFLAG_LIST;
        }
        else if (*eap->arg == 'p')
        {
            eap->flags |= EXFLAG_PRINT;
        }
        else
        {
            eap->flags |= EXFLAG_NR;
        }
        eap->arg = skipwhite(eap->arg + 1);
    }
}

    static void
ex_ni(exarg_T *eap)
{
    if (!eap->skip)
    {
        eap->errmsg =
                _(e_sorry_command_is_not_available_in_this_version);
    }
}

    static void
ex_script_ni(exarg_T *eap)
{
    if (!eap->skip)
    {
        ex_ni(eap);
    }
    else
    {
        vim_free(script_get(eap, eap->arg));
    }
}

    static char *
invalid_range(exarg_T *eap)
{
    buf_T       *buf;

    if (       eap->line1 < 0 || eap->line2 < 0 || eap->line1 > eap->line2)
    {
        return _(e_invalid_range);
    }

    if (eap->argt & EX_RANGE)
    {
        switch (eap->addr_type)
        {
            case ADDR_LINES:
                if (eap->line2 > curbuf->b_ml.ml_line_count)
                {
                    return _(e_invalid_range);
                }
                break;
            case ADDR_ARGUMENTS:
                if (eap->line2 >  ( (curwin)->w_alist ->al_ga.ga_len)  + (! ( (curwin)->w_alist ->al_ga.ga_len) ))
                {
                    return _(e_invalid_range);
                }
                break;
            case ADDR_BUFFERS:
                if (eap->line1 < 1 || eap->line2 > get_highest_fnum())
                {
                    return _(e_invalid_range);
                }
                break;
            case ADDR_LOADED_BUFFERS:
                buf = firstbuf;
                while (buf->b_ml.ml_mfp == NULL)
                {
                    if (buf->b_next == NULL)
                    {
                        return _(e_invalid_range);
                    }
                    buf = buf->b_next;
                }
                if (eap->line1 < buf->b_fnum)
                {
                    return _(e_invalid_range);
                }
                buf = lastbuf;
                while (buf->b_ml.ml_mfp == NULL)
                {
                    if (buf->b_prev == NULL)
                    {
                        return _(e_invalid_range);
                    }
                    buf = buf->b_prev;
                }
                if (eap->line2 > buf->b_fnum)
                {
                    return _(e_invalid_range);
                }
                break;
            case ADDR_WINDOWS:
                if (eap->line2 >  current_win_nr(NULL) )
                {
                    return _(e_invalid_range);
                }
                break;
            case ADDR_TABS:
                if (eap->line2 >  current_tab_nr(NULL) )
                {
                    return _(e_invalid_range);
                }
                break;
            case ADDR_TABS_RELATIVE:
            case ADDR_OTHER:
                break;
            case ADDR_QUICKFIX:
                break;
            case ADDR_QUICKFIX_VALID:
                break;
            case ADDR_UNSIGNED:
            case ADDR_NONE:
                break;
        }
    }
    return NULL;
}

    static void
correct_range(exarg_T *eap)
{
    if (!(eap->argt & EX_ZEROR))
    {
        if (eap->line1 == 0)
        {
            eap->line1 = 1;
        }
        if (eap->line2 == 0)
        {
            eap->line2 = 1;
        }
    }
}

    static int
expand_filename(exarg_T     *eap, char_u      **cmdlinep, char        **errormsgp)
{
    int         has_wildcards;
    char_u      *repl;
    size_t      srclen;
    char_u      *p;
    int         n;
    int         escaped;

    p = eap->arg;

    has_wildcards = mch_has_wildcard(p);
    while (*p != NUL)
    {
        if (vim_strchr((char_u *)"%#<", *p) == NULL)
        {
            ++p;
            continue;
        }

        repl = eval_vars(p, eap->arg, &srclen, &(eap->do_ecmd_lnum), errormsgp, &escaped, TRUE);
        if (*errormsgp != NULL)
        {
            return FAIL;
        }
        if (repl == NULL)
        {
            p += srclen;
            continue;
        }

        if (vim_strchr(repl, '$') != NULL || vim_strchr(repl, '~') != NULL)
        {
            char_u *l = repl;

            repl = expand_env_save(repl);
            vim_free(l);
        }

        if (!eap->usefilter && !escaped && eap->cmdidx != CMD_bang && eap->cmdidx != CMD_grep && eap->cmdidx != CMD_grepadd && eap->cmdidx != CMD_hardcopy && eap->cmdidx != CMD_lgrep && eap->cmdidx != CMD_lgrepadd && eap->cmdidx != CMD_lmake && eap->cmdidx != CMD_make && eap->cmdidx != CMD_terminal)
        {
            char_u      *l;

            for (l = repl; *l; ++l)
            {
                if (vim_strchr( escape_chars , *l) != NULL)
                {
                    l = vim_strsave_escaped(repl,  escape_chars );
                    if (l != NULL)
                    {
                        vim_free(repl);
                        repl = l;
                    }
                    break;
                }
            }
        }

        if ((eap->usefilter || eap->cmdidx == CMD_bang || eap->cmdidx == CMD_terminal) &&  (char_u *)strpbrk((char *)(repl), (char *)((char_u *)"!"))  != NULL)
        {
            char_u      *l;

            l = vim_strsave_escaped(repl, (char_u *)"!");
            if (l != NULL)
            {
                vim_free(repl);
                repl = l;
            }
        }

        p = repl_cmdline(eap, p, srclen, repl, cmdlinep);
        vim_free(repl);
        if (p == NULL)
        {
            return FAIL;
        }
    }

    if ((eap->argt & EX_NOSPC) && !eap->usefilter)
    {
        for (n = 1; n <= 2; ++n)
        {
            if (n == 2)
            {
                if (!has_wildcards)
                {
                    backslash_halve(eap->arg);
                }
            }

            if (has_wildcards)
            {
                if (n == 1)
                {
                    if (vim_strchr(eap->arg, '$') != NULL || vim_strchr(eap->arg, '~') != NULL)
                    {
                        expand_env_esc(eap->arg, NameBuff,  PATH_MAX , (char_u *)(" \t"  "*?[{" ), TRUE, NULL);
                        has_wildcards = mch_has_wildcard(NameBuff);
                        p = NameBuff;
                    }
                    else
                    {
                        p = NULL;
                    }
                }
                else
                {
                    expand_T    xpc;
                    int         options = WILD_LIST_NOTFOUND
                                               | WILD_NOERROR | WILD_ADD_SLASH;

                    ExpandInit(&xpc);
                    xpc.xp_context = EXPAND_FILES;
                    if (p_wic)
                    {
                        options += WILD_ICASE;
                    }
                    p = ExpandOne(&xpc, eap->arg, NULL, options, WILD_EXPAND_FREE);
                    if (p == NULL)
                    {
                        return FAIL;
                    }
                }
                if (p != NULL)
                {
                    (void)repl_cmdline(eap, eap->arg,  strlen((char *)(eap->arg)) , p, cmdlinep);
                    if (n == 2)
                    {
                        vim_free(p);
                    }
                }
            }
        }
    }
    return OK;
}

    static char_u *
repl_cmdline(exarg_T     *eap, char_u      *src, size_t      srclen, char_u      *repl, char_u      **cmdlinep)
{
    size_t      repllen;
    size_t      taillen;
    size_t      i;
    char_u      *new_cmdline;
    size_t      new_cmdlinelen;

    repllen =  strlen((char *)(repl)) ;
    taillen =  strlen((char *)(src + srclen)) ;
    i = (src - *cmdlinep) + repllen + taillen + 3;
    if (eap->nextcmd != NULL)
    {
        i +=  strlen((char *)(eap->nextcmd)) ;
    }
    if ((new_cmdline = alloc(i)) == NULL)
    {
        return NULL;
    }

    new_cmdlinelen = src - *cmdlinep;
     memmove((char *)(new_cmdline), (char *)(*cmdlinep), new_cmdlinelen) ;

     memmove((char *)(new_cmdline + new_cmdlinelen), (char *)(repl), repllen) ;
    new_cmdlinelen += repllen;
     strcpy((char *)(new_cmdline + new_cmdlinelen), (char *)(src + srclen)) ;
    src = new_cmdline + new_cmdlinelen;

    if (eap->nextcmd != NULL)
    {
        new_cmdlinelen += taillen + 1;
         strcpy((char *)(new_cmdline + new_cmdlinelen), (char *)(eap->nextcmd)) ;
        eap->nextcmd = new_cmdline + new_cmdlinelen;
    }
    eap->cmd = new_cmdline + (eap->cmd - *cmdlinep);
    eap->arg = new_cmdline + (eap->arg - *cmdlinep);
    if (eap->do_ecmd_cmd != NULL && eap->do_ecmd_cmd != dollar_command)
    {
        eap->do_ecmd_cmd = new_cmdline + (eap->do_ecmd_cmd - *cmdlinep);
    }
    vim_free(*cmdlinep);
    *cmdlinep = new_cmdline;

    return src;
}

    static void
separate_nextcmd(exarg_T *eap, int keep_backslash)
{
    int         vim9script = in_vim9script();
    char_u      *p;

    p = eap->arg;

    for ( ; *p;  p += (*mb_ptr2len)(p) )
    {
        if (*p == Ctrl_V)
        {
            if ((eap->argt & (EX_CTRLV | EX_XFILE)) || keep_backslash)
            {
                ++p;
            }
            else
            {
                  memmove((char *)((p)), (char *)((p + 1)),  strlen((char *)(p + 1))  + 1)  ;
            }
            if (*p == NUL)
            {
                break;
            }
        }

        else if ((*p == '"' && !vim9script && !(eap->argt & EX_NOTRLCOM) && ((eap->cmdidx != CMD_at && eap->cmdidx != CMD_star) || p != eap->arg) && (eap->cmdidx != CMD_redir || p != eap->arg + 1 || p[-1] != '@')) || (*p == '#' && vim9script && !(eap->argt & EX_NOTRLCOM) && p > eap->cmd &&  ((p[-1]) == ' ' || (p[-1]) == '\t') ) || (*p == '|' && eap->cmdidx != CMD_append && eap->cmdidx != CMD_change && eap->cmdidx != CMD_insert) || *p == '\n')
        {
            if ((vim_strchr(p_cpo, CPO_BAR) == NULL || !(eap->argt & EX_CTRLV)) && *(p - 1) == '\\')
            {
                if (!keep_backslash)
                {
                      memmove((char *)((p - 1)), (char *)((p)),  strlen((char *)(p))  + 1)  ;
                    --p;
                }
            }
            else
            {
                set_nextcmd(eap, p);
                *p = NUL;
                break;
            }
        }
    }

    if (!(eap->argt & EX_NOTRLCOM))
    {
        del_trailing_spaces(eap->arg);
    }
}

    static char_u *
getargcmd(char_u **argp)
{
    char_u *arg = *argp;
    char_u *command = NULL;

    if (*arg == '+')
    {
        ++arg;
        if (vim_isspace(*arg) || *arg == NUL)
        {
            command = dollar_command;
        }
        else
        {
            command = arg;
            arg = skip_cmd_arg(command, TRUE);
            if (*arg != NUL)
            {
                *arg++ = NUL;
            }
        }

        arg = skipwhite(arg);
        *argp = arg;
    }
    return command;
}

    static char_u *
skip_cmd_arg(char_u *p, int    rembs)
{
    while (*p && !vim_isspace(*p))
    {
        if (*p == '\\' && p[1] != NUL)
        {
            if (rembs)
            {
                  memmove((char *)((p)), (char *)((p + 1)),  strlen((char *)(p + 1))  + 1)  ;
            }
            else
            {
                ++p;
            }
        }
         p += (*mb_ptr2len)(p) ;
    }
    return p;
}

    static int
get_bad_opt(char_u *p, exarg_T *eap)
{
    if ( strcasecmp((char *)(p), (char *)("keep"))  == 0)
    {
        eap->bad_char =  (-1) ;
    }
    else if ( strcasecmp((char *)(p), (char *)("drop"))  == 0)
    {
        eap->bad_char =  (-2) ;
    }
    else if ( mb_bytelen_tab[*p]  == 1 && p[1] == NUL)
    {
        eap->bad_char = *p;
    }
    else
    {
        return FAIL;
    }
    return OK;
}

    static char_u *
get_bad_name(expand_T *xp  __attribute__((unused)) , int idx)
{
    static char *(p_bad_values[]) =
    {
        "?",
        "keep",
        "drop",
    };

    if (idx < 0 || idx >= (int) (sizeof(p_bad_values) / sizeof((p_bad_values)[0])) )
    {
        return NULL;
    }

    return (char_u*)p_bad_values[idx];
}

    static int
getargopt(exarg_T *eap)
{
    char_u      *arg = eap->arg + 2;
    int         *pp = NULL;
    int         bad_char_idx;
    char_u      *p;

    if ( strncmp((char *)(arg), (char *)("bin"), (3))  == 0 ||  strncmp((char *)(arg), (char *)("nobin"), (5))  == 0)
    {
        if (*arg == 'n')
        {
            arg += 2;
            eap->force_bin = FORCE_NOBIN;
        }
        else
        {
            eap->force_bin = FORCE_BIN;
        }
        if (!checkforcmd(&arg, "binary", 3))
        {
            return FAIL;
        }
        eap->arg = skipwhite(arg);
        return OK;
    }

    if ( strncmp((char *)(arg), (char *)("edit"), (4))  == 0)
    {
        eap->read_edit = TRUE;
        eap->arg = skipwhite(arg + 4);
        return OK;
    }

    if ( strncmp((char *)(arg), (char *)("ff"), (2))  == 0)
    {
        arg += 2;
        pp = &eap->force_ff;
    }
    else if ( strncmp((char *)(arg), (char *)("fileformat"), (10))  == 0)
    {
        arg += 10;
        pp = &eap->force_ff;
    }
    else if ( strncmp((char *)(arg), (char *)("enc"), (3))  == 0)
    {
        if ( strncmp((char *)(arg), (char *)("encoding"), (8))  == 0)
        {
            arg += 8;
        }
        else
        {
            arg += 3;
        }
        pp = &eap->force_enc;
    }
    else if ( strncmp((char *)(arg), (char *)("bad"), (3))  == 0)
    {
        arg += 3;
        pp = &bad_char_idx;
    }

    if (pp == NULL || *arg != '=')
    {
        return FAIL;
    }

    ++arg;
    *pp = (int)(arg - eap->cmd);
    arg = skip_cmd_arg(arg, FALSE);
    eap->arg = skipwhite(arg);
    *arg = NUL;

    if (pp == &eap->force_ff)
    {
        if (check_ff_value(eap->cmd + eap->force_ff) == FAIL)
        {
            return FAIL;
        }
        eap->force_ff = eap->cmd[eap->force_ff];
    }
    else if (pp == &eap->force_enc)
    {
        for (p = eap->cmd + eap->force_enc; *p != NUL; ++p)
        {
            *p =  (((*p) < 'A' || (*p) > 'Z') ? (*p) : (*p) + ('a' - 'A')) ;
        }
    }
    else
    {
        if (get_bad_opt(eap->cmd + bad_char_idx, eap) == FAIL)
        {
            return FAIL;
        }
    }

    return OK;
}

    static char_u *
get_argopt_name(expand_T *xp  __attribute__((unused)) , int idx)
{
    static char *(p_opt_values[]) =
    {
        "fileformat=",
        "encoding=",
        "binary",
        "nobinary",
        "bad=",
        "edit",
    };

    if (idx < 0 || idx >= (int) (sizeof(p_opt_values) / sizeof((p_opt_values)[0])) )
    {
        return NULL;
    }

    return (char_u*)p_opt_values[idx];
}

    static int
expand_argopt(char_u      *pat, expand_T    *xp, regmatch_T  *rmp, char_u      ***matches, int         *numMatches)
{
    if (xp->xp_pattern > xp->xp_line && *(xp->xp_pattern-1) == '=')
    {
        char_u *(*cb)(expand_T *, int) = NULL;

        char_u *name_end = xp->xp_pattern - 1;
        if (name_end - xp->xp_line >= 2 &&  strncmp((char *)(name_end - 2), (char *)("ff"), (2))  == 0)
        {
            cb = get_fileformat_name;
        }
        else if (name_end - xp->xp_line >= 10 &&  strncmp((char *)(name_end - 10), (char *)("fileformat"), (10))  == 0)
        {
            cb = get_fileformat_name;
        }
        else if (name_end - xp->xp_line >= 3 &&  strncmp((char *)(name_end - 3), (char *)("enc"), (3))  == 0)
        {
            cb = get_encoding_name;
        }
        else if (name_end - xp->xp_line >= 8 &&  strncmp((char *)(name_end - 8), (char *)("encoding"), (8))  == 0)
        {
            cb = get_encoding_name;
        }
        else if (name_end - xp->xp_line >= 3 &&  strncmp((char *)(name_end - 3), (char *)("bad"), (3))  == 0)
        {
            cb = get_bad_name;
        }

        if (cb != NULL)
        {
            return ExpandGeneric(pat, xp, rmp, matches, numMatches, cb, FALSE);
        }
        return FAIL;
    }

    if (xp->xp_pattern_len == 2 &&  strncmp((char *)(xp->xp_pattern), (char *)("ff"), (xp->xp_pattern_len))  == 0)
    {
        *matches =  (char_u * *)alloc(sizeof(char_u *) * (1)) ;
        if (*matches == NULL)
        {
            return FAIL;
        }
        *numMatches = 1;
        (*matches)[0] = vim_strsave((char_u*)"fileformat=");
        return OK;
    }

    return ExpandGeneric(pat, xp, rmp, matches, numMatches, get_argopt_name, FALSE);
}

