    static int
ends_excmd(int c)
{
    int comment_char = '"';

    if (in_vim9script())
    {
        comment_char = '#';
    }
    return (c == NUL || c == '|' || c == comment_char || c == '\n');
}

    static int
ends_excmd2(char_u *cmd_start  __attribute__((unused)) , char_u *cmd)
{
    int c = *cmd;

    if (c == NUL || c == '|' || c == '\n')
    {
        return TRUE;
    }
    if (in_vim9script())
    {
        return c == '#' && (cmd[1] != '{' || cmd[2] == '{')
                                 && (cmd == cmd_start ||  ((cmd[-1]) == ' ' || (cmd[-1]) == '\t') );
    }
    return c == '"';
}

    static char_u *
find_nextcmd(char_u *p)
{
    while (*p != '|' && *p != '\n')
    {
        if (*p == NUL)
        {
            return NULL;
        }
        ++p;
    }
    return (p + 1);
}

    static char_u *
check_nextcmd(char_u *p)
{
    char_u *s = skipwhite(p);

    if (*s == '|' || *s == '\n')
    {
        return (s + 1);
    }
    else
    {
        return NULL;
    }
}

    static void
set_nextcmd(exarg_T *eap, char_u *arg)
{
    char_u *p = skipwhite(arg);

    if (in_vim9script() && *p == '#')
    {
        char_u *nl = vim_strchr(p, NL);
        if (nl != NULL)
        {
            p = nl;
        }
    }

    p = check_nextcmd(p);

    if (eap->nextcmd == NULL)
    {
        eap->nextcmd = p;
    }
    else if (p != NULL)
    {
        semsg(_(e_cannot_use_bar_to_separate_commands_here_str), arg);
    }
}

    static int
check_more(int message, int forceit)
{
    int     n =  ( (curwin)->w_alist ->al_ga.ga_len)  - curwin->w_arg_idx - 1;

    if (!forceit && only_one_window() &&  ( (curwin)->w_alist ->al_ga.ga_len)  > 1 && !arg_had_last && n > 0 && quitmore == 0)
    {
        if (message)
        {
            semsg(NGETTEXT(e_nr_more_file_to_edit, e_nr_more_files_to_edit , n), n);
            quitmore = 2;
        }
        return FAIL;
    }
    return OK;
}

    static char_u *
get_command_name(expand_T *xp  __attribute__((unused)) , int idx)
{
    if (idx >= (int)CMD_SIZE)
    {
        return expand_user_command_name(idx);
    }
    if ( strncmp((char *)(cmdnames[idx].cmd_name), (char *)("{"), (1))  == 0 ||  strncmp((char *)(cmdnames[idx].cmd_name), (char *)("}"), (1))  == 0)
    {
        return (char_u *)"";
    }
    return cmdnames[idx].cmd_name;
}

