    static void
ex_splitview(exarg_T *eap)
{
    win_T       *old_curwin = curwin;
    char_u      *fname = NULL;
    int         use_tab = eap->cmdidx == CMD_tabedit
                       || eap->cmdidx == CMD_tabfind
                       || eap->cmdidx == CMD_tabnew;

    if (ERROR_IF_ANY_POPUP_WINDOW)
    {
        return;
    }

    if (eap->cmdidx == CMD_sfind || eap->cmdidx == CMD_tabfind)
    {
        char_u  *file_to_find = NULL;
        char    *search_ctx = NULL;

        if (*get_findfunc() != NUL)
        {
        }
        else
        {
            fname = find_file_in_path(eap->arg, (int) strlen((char *)(eap->arg)) , FNAME_MESS, TRUE, curbuf->b_ffname, &file_to_find, &search_ctx);
            vim_free(file_to_find);
            vim_findfile_cleanup(search_ctx);
        }
        if (fname == NULL)
        {
            goto theend;
        }
        eap->arg = fname;
    }

    if (use_tab)
    {
        if (win_new_tabpage(cmdmod.cmod_tab != 0 ? cmdmod.cmod_tab : eap->addr_count == 0 ? 0 : (int)eap->line2 + 1) != FAIL)
        {
            do_exedit(eap, old_curwin);

            if (curwin != old_curwin && win_valid(old_curwin) && old_curwin->w_buffer != curbuf && (cmdmod.cmod_flags & CMOD_KEEPALT) == 0)
            {
                old_curwin->w_alt_fnum = curbuf->b_fnum;
            }
        }
    }
    else if (win_split(eap->addr_count > 0 ? (int)eap->line2 : 0, *eap->cmd == 'v' ? WSP_VERT : 0) != FAIL)
    {
        if (*eap->arg != NUL)
        {
             (curwin)-> w_onebuf_opt.wo_scb  = FALSE;
             (curwin)-> w_onebuf_opt.wo_crb  = FALSE;
        }
        else
        {
            do_check_scrollbind(FALSE);
        }
        do_exedit(eap, old_curwin);
    }

theend:
    vim_free(fname);
}

    static void
tabpage_new(void)
{
    exarg_T     ea;

      memset((&(ea)), (0), (sizeof(ea)))  ;
    ea.cmdidx = CMD_tabnew;
    ea.cmd = (char_u *)"tabn";
    ea.arg = (char_u *)"";
    ex_splitview(&ea);
}

    static void
ex_tabnext(exarg_T *eap)
{
    int tab_number;

    if (ERROR_IF_POPUP_WINDOW)
    {
        return;
    }
    switch (eap->cmdidx)
    {
        case CMD_tabfirst:
        case CMD_tabrewind:
            goto_tabpage(1);
            break;
        case CMD_tablast:
            goto_tabpage(9999);
            break;
        case CMD_tabprevious:
        case CMD_tabNext:
            if (eap->arg && *eap->arg != NUL)
            {
                char_u *p = eap->arg;
                char_u *p_save = p;

                tab_number = getdigits(&p);
                if (p == p_save || *p_save == '-' || *p != NUL || tab_number == 0)
                {
                    eap->errmsg = ex_errmsg(e_invalid_argument_str, eap->arg);
                    return;
                }
            }
            else
            {
                if (eap->addr_count == 0)
                {
                    tab_number = 1;
                }
                else
                {
                    tab_number = eap->line2;
                    if (tab_number < 1)
                    {
                        eap->errmsg = _(e_invalid_range);
                        return;
                    }
                }
            }
            goto_tabpage(-tab_number);
            break;
        default:
            tab_number = get_tabpage_arg(eap);
            if (eap->errmsg == NULL)
            {
                goto_tabpage(tab_number);
            }
            break;
    }
}

    static void
ex_tabmove(exarg_T *eap)
{
    int tab_number;

    tab_number = get_tabpage_arg(eap);
    if (eap->errmsg == NULL)
    {
        tabpage_move(tab_number);
    }
}

    static void
ex_tabs(exarg_T *eap  __attribute__((unused)) )
{
    tabpage_T   *tp;
    win_T       *wp;
    int         tabcount = 1;

    msg_start();
    msg_scroll = TRUE;
    for (tp = first_tabpage; tp != NULL && !got_int; tp = tp->tp_next)
    {
        msg_putchar('\n');
        vim_snprintf((char *)IObuff,  (1024+1) , _("Tab page %d"), tabcount++);
        msg_outtrans_attr(IObuff,  highlight_attr[(int)(HLF_T)] );
        out_flush();
        ui_breakcheck();

        if (tp  == curtab)
        {
            wp = firstwin;
        }
        else
        {
            wp = tp->tp_firstwin;
        }
        for ( ; wp != NULL && !got_int; wp = wp->w_next)
        {
            msg_putchar('\n');
            msg_putchar(wp == curwin ? '>' : ' ');
            msg_putchar(' ');
            msg_putchar(bufIsChanged(wp->w_buffer) ? '+' : ' ');
            msg_putchar(' ');
            if (buf_spname(wp->w_buffer) != NULL)
            {
                vim_strncpy(IObuff, buf_spname(wp->w_buffer),  (1024+1)  - 1);
            }
            else
            {
                home_replace(wp->w_buffer, wp->w_buffer->b_fname, IObuff,  (1024+1) , TRUE);
            }
            msg_outtrans(IObuff);
            out_flush();
            ui_breakcheck();
        }
    }
}

