    static void
ex_resize(exarg_T *eap)
{
    int         n;
    win_T       *wp = curwin;

    if (eap->addr_count > 0)
    {
        n = eap->line2;
        for (wp = firstwin; wp->w_next != NULL && --n > 0; wp = wp->w_next)
        {
            ;
        }
    }

    n = atol((char *)eap->arg);
    if (cmdmod.cmod_split & WSP_VERT)
    {
        if (*eap->arg == '-' || *eap->arg == '+')
        {
            n += wp->w_width;
        }
        else if (n == 0 && eap->arg[0] == NUL)
        {
            n = 9999;
        }
        win_setwidth_win(n, wp);
    }
    else
    {
        if (*eap->arg == '-' || *eap->arg == '+')
        {
            n += wp->w_height;
        }
        else if (n == 0 && eap->arg[0] == NUL)
        {
            n = 9999;
        }
        win_setheight_win(n, wp);
    }
}

    static void
ex_open(exarg_T *eap)
{
    regmatch_T  regmatch;
    char_u      *p;

    curwin->w_cursor.lnum = eap->line2;
    beginline(BL_SOL | BL_FIX);
    if (*eap->arg == '/')
    {
        ++eap->arg;
        p = skip_regexp(eap->arg, '/', magic_isset());
        *p = NUL;
        regmatch.regprog = vim_regcomp(eap->arg, magic_isset() ? RE_MAGIC : 0);
        if (regmatch.regprog != NULL)
        {
            char_u *line = vim_strsave(ml_get_curline());

            regmatch.rm_ic = p_ic;
            if (vim_regexec(&regmatch, line, (colnr_T)0))
            {
                curwin->w_cursor.col = (colnr_T)(regmatch.startp[0] - line);
            }
            else
            {
                emsg(_(e_no_match));
            }
            vim_regfree(regmatch.regprog);
            vim_free(line);
        }
        eap->arg +=  strlen((char *)(eap->arg)) ;
    }
    check_cursor();

    eap->cmdidx = CMD_visual;
    do_exedit(eap, NULL);
}

    static void
ex_edit(exarg_T *eap)
{
    char_u *ffname = eap->cmdidx == CMD_enew ? NULL : eap->arg;

    if (eap->cmdidx != CMD_badd && eap->cmdidx != CMD_balt && (is_other_file(0, ffname) && !check_can_set_curbuf_forceit(eap->forceit)))
    {
        return;
    }

    do_exedit(eap, NULL);
}

    static void
do_exedit(exarg_T     *eap, win_T       *old_curwin)
{
    int         n;
    int         need_hide;
    int         exmode_was = exmode_active;

    if ((eap->cmdidx != CMD_pedit && ERROR_IF_POPUP_WINDOW) || ERROR_IF_TERM_POPUP_WINDOW)
    {
        return;
    }
    if (exmode_active && (eap->cmdidx == CMD_visual || eap->cmdidx == CMD_view))
    {
        exmode_active = FALSE;
        ex_pressedreturn = FALSE;
        if (*eap->arg == NUL)
        {
            if (global_busy)
            {
                if (eap->nextcmd != NULL)
                {
                    stuffReadbuff(eap->nextcmd);
                    eap->nextcmd = NULL;
                }

                if (exmode_was != EXMODE_VIM)
                {
                    settmode(TMODE_RAW);
                }
                int save_RedrawingDisabled = RedrawingDisabled;
                RedrawingDisabled = 0;
                int save_nwr = no_wait_return;
                no_wait_return = 0;
                need_wait_return = FALSE;
                int save_ms = msg_scroll;
                msg_scroll = 0;
                set_must_redraw(UPD_CLEAR);
                pending_exmode_active = TRUE;

                main_loop(FALSE, TRUE);

                pending_exmode_active = FALSE;
                RedrawingDisabled = save_RedrawingDisabled;
                no_wait_return = save_nwr;
                msg_scroll = save_ms;
            }
            return;
        }
    }

    if ((eap->cmdidx == CMD_new || eap->cmdidx == CMD_tabnew || eap->cmdidx == CMD_tabedit || eap->cmdidx == CMD_vnew) && *eap->arg == NUL)
    {
        setpcmark();
        (void)do_ecmd(0, NULL, NULL, eap,  (linenr_T)1 , ECMD_HIDE + (eap->forceit ? ECMD_FORCEIT : 0), old_curwin == NULL ? curwin : NULL);
    }
    else if ((eap->cmdidx != CMD_split && eap->cmdidx != CMD_vsplit) || *eap->arg != NUL)
    {
        if (*eap->arg != NUL && text_or_buf_locked())
        {
            return;
        }

        n = readonlymode;
        if (eap->cmdidx == CMD_view || eap->cmdidx == CMD_sview)
        {
            readonlymode = TRUE;
        }
        else if (eap->cmdidx == CMD_enew)
        {
            readonlymode = FALSE;
        }
        if (eap->cmdidx != CMD_balt && eap->cmdidx != CMD_badd)
        {
            setpcmark();
        }
        if (do_ecmd(0, (eap->cmdidx == CMD_enew ? NULL : eap->arg), NULL, eap, (*eap->arg == NUL && eap->do_ecmd_lnum == 0 && vim_strchr(p_cpo, CPO_GOTO1) != NULL) ?  (linenr_T)1  : eap->do_ecmd_lnum, (buf_hide(curbuf) ? ECMD_HIDE : 0) + (eap->forceit ? ECMD_FORCEIT : 0) + (old_curwin != NULL ? ECMD_OLDBUF : 0) + (eap->cmdidx == CMD_badd ? ECMD_ADDBUF : 0) + (eap->cmdidx == CMD_balt ? ECMD_ALTBUF : 0), old_curwin == NULL ? curwin : NULL) == FAIL)
        {
            if (old_curwin != NULL)
            {
                need_hide = (curbufIsChanged() && curbuf->b_nwindows <= 1);
                if (!need_hide || buf_hide(curbuf))
                {
                    win_close(curwin, !need_hide && !buf_hide(curbuf));

                }
            }
        }
        else if (readonlymode && curbuf->b_nwindows == 1)
        {
            curbuf->b_p_ro = TRUE;
        }
        readonlymode = n;
    }
    else
    {
        if (eap->do_ecmd_cmd != NULL)
        {
            do_cmd_argument(eap->do_ecmd_cmd);
        }
        n = curwin->w_arg_idx_invalid;
        check_arg_idx(curwin);
        if (n != curwin->w_arg_idx_invalid)
        {
            maketitle();
        }
    }

    if (old_curwin != NULL && *eap->arg != NUL && curwin != old_curwin && win_valid(old_curwin) && old_curwin->w_buffer != curbuf && (cmdmod.cmod_flags & CMOD_KEEPALT) == 0)
    {
        old_curwin->w_alt_fnum = curbuf->b_fnum;
    }

    ex_no_reprint = TRUE;
}

    static void
ex_nogui(exarg_T *eap)
{
    eap->errmsg = _(e_gui_cannot_be_used_not_enabled_at_compile_time);
}

    static void
ex_syncbind(exarg_T *eap  __attribute__((unused)) )
{
    win_T       *wp;
    win_T       *save_curwin = curwin;
    buf_T       *save_curbuf = curbuf;
    long        topline;
    long        y;
    linenr_T    old_linenr = curwin->w_cursor.lnum;

    setpcmark();

    if (curwin-> w_onebuf_opt.wo_scb )
    {
        topline = curwin->w_topline;
         for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
        {
            if (wp-> w_onebuf_opt.wo_scb  && wp->w_buffer)
            {
                y = wp->w_buffer->b_ml.ml_line_count - get_scrolloff_value();
                if (topline > y)
                {
                    topline = y;
                }
            }
        }
        if (topline < 1)
        {
            topline = 1;
        }
    }
    else
    {
        topline = 1;
    }

     for ((curwin) = firstwin; (curwin) != NULL; (curwin) = (curwin)->w_next) 
    {
        if (curwin-> w_onebuf_opt.wo_scb )
        {
            curbuf = curwin->w_buffer;
            y = topline - curwin->w_topline;
            if (y > 0)
            {
                scrollup(y, TRUE);
            }
            else
            {
                scrolldown(-y, TRUE);
            }
            curwin->w_scbind_pos = topline;
            redraw_later(UPD_VALID);
            cursor_correct();
            curwin->w_redr_status = true;
        }
    }
    curwin = save_curwin;
    curbuf = save_curbuf;
    if (curwin-> w_onebuf_opt.wo_scb )
    {
        did_syncbind = TRUE;
        checkpcmark();
        if (old_linenr != curwin->w_cursor.lnum)
        {
            char_u ctrl_o[2];

            ctrl_o[0] = Ctrl_O;
            ctrl_o[1] = 0;
            ins_typebuf(ctrl_o,  (-1) , 0, TRUE, FALSE);
        }
    }
}

    static void
ex_read(exarg_T *eap)
{
    int         i;
    int         empty = (curbuf->b_ml.ml_flags & ML_EMPTY);
    linenr_T    lnum;

    if (eap->usefilter)
    {
        do_bang(1, eap, FALSE, FALSE, TRUE);
        return;
    }

    if (u_save(eap->line2, (linenr_T)(eap->line2 + 1)) == FAIL)
    {
        return;
    }

        if (*eap->arg == NUL)
        {
            if (check_fname() == FAIL)
            {
                return;
            }
            i = readfile(curbuf->b_ffname, curbuf->b_fname, eap->line2, (linenr_T)0, (linenr_T) LONG_MAX , eap, 0);
        }
        else
        {
            if (vim_strchr(p_cpo, CPO_ALTREAD) != NULL)
            {
                (void)setaltfname(eap->arg, eap->arg, (linenr_T)1);
            }
            i = readfile(eap->arg, NULL, eap->line2, (linenr_T)0, (linenr_T) LONG_MAX , eap, 0);

        }
    if (i != OK)
    {
            semsg(_(e_cant_open_file_str), eap->arg);
    }
    else
    {
        if (empty && exmode_active)
        {
            if (eap->line2 == 0)
            {
                lnum = curbuf->b_ml.ml_line_count;
            }
            else
            {
                lnum = 1;
            }
            if (*ml_get(lnum) == NUL && u_savedel(lnum, 1L) == OK)
            {
                ml_delete(lnum);
                if (curwin->w_cursor.lnum > 1 && curwin->w_cursor.lnum >= lnum)
                {
                    --curwin->w_cursor.lnum;
                }
                deleted_lines_mark(lnum, 1L);
            }
        }
        redraw_curbuf_later(UPD_VALID);
    }
}

    static void
ex_equal(exarg_T *eap)
{
    smsg("%ld", (long)eap->line2);
    ex_may_print(eap);
}

    static void
ex_sleep(exarg_T *eap)
{
    int         n;
    long        len;

    if (cursor_valid())
    {
        n =  (curwin->w_winrow)  + curwin->w_wrow - msg_scrolled;
        if (n >= 0)
        {
            windgoto(n, curwin->w_wincol + curwin->w_wcol);
        }
    }

    len = eap->line2;
    switch (*eap->arg)
    {
        case 'm':
            break;
        case NUL:
            len *= 1000L;
            break;
        default:
            semsg(_(e_invalid_argument_str), eap->arg);
            return;
    }

    do_sleep(len, eap->forceit);
}

    static void
do_sleep(long msec, int hide_cursor)
{
    long        done = 0;
    long        wait_now;
    elapsed_T   start_tv;

     gettimeofday(&(start_tv), NULL) ;

    if (hide_cursor)
    {
        cursor_sleep();
    }
    else
    {
        cursor_on();
    }

    out_flush_cursor(FALSE, FALSE);
    while (!got_int && done < msec)
    {
        wait_now = msec - done > 1000L ? 1000L : msec - done;
        ui_delay(wait_now, TRUE);

            ui_breakcheck();

        done =  elapsed(&(start_tv)) ;
    }

    if (got_int)
    {
        (void)vpeekc();
    }

    if (hide_cursor)
    {
        cursor_unsleep();
    }
}

    static void
ex_winsize(exarg_T *eap)
{
    int w;
    int h;
    char_u      *arg = eap->arg;
    char_u      *p;

    if (! (isdigit ((unsigned char)(*arg))) )
    {
        semsg(_(e_invalid_argument_str), arg);
        return;
    }
    w = getdigits(&arg);
    arg = skipwhite(arg);
    p = arg;
    h = getdigits(&arg);
    if (*p != NUL && *arg == NUL)
    {
        set_shellsize(w, h, TRUE);
    }
    else
    {
        emsg(_(e_winsize_requires_two_number_arguments));
    }
}

    static void
ex_wincmd(exarg_T *eap)
{
    int         xchar = NUL;
    char_u      *p;

    if (*eap->arg == 'g' || *eap->arg == Ctrl_G)
    {
        if (eap->arg[1] == NUL)
        {
            emsg(_(e_invalid_argument));
            return;
        }
        xchar = eap->arg[1];
        p = eap->arg + 2;
    }
    else
    {
        p = eap->arg + 1;
    }

    set_nextcmd(eap, p);
    p = skipwhite(p);
    if (*p != NUL && *p != ('"') && eap->nextcmd == NULL)
    {
        emsg(_(e_invalid_argument));
    }
    else if (!eap->skip)
    {
        postponed_split_flags = cmdmod.cmod_split;
        postponed_split_tab = cmdmod.cmod_tab;
        do_window(*eap->arg, eap->addr_count > 0 ? eap->line2 : 0L, xchar);
        postponed_split_flags = 0;
        postponed_split_tab = 0;
    }
}

    static void
ex_winpos(exarg_T *eap)
{
    char_u      *arg = eap->arg;
    char_u      *p;

    if (*arg == NUL)
    {
            emsg(_(e_obtaining_window_position_not_implemented_for_this_platform));
    }
    else
    {
        (void)getdigits(&arg);
        arg = skipwhite(arg);
        p = arg;
        (void)getdigits(&arg);
        if (*p == NUL || *arg != NUL)
        {
            emsg(_(e_winpos_requires_two_number_arguments));
            return;
        }
    }
}

    static void
ex_operators(exarg_T *eap)
{
    oparg_T     oa;

    clear_oparg(&oa);
    oa.regname = eap->regname;
    oa.start.lnum = eap->line1;
    oa.end.lnum = eap->line2;
    oa.line_count = eap->line2 - eap->line1 + 1;
    oa.motion_type = MLINE;
    virtual_op = FALSE;
    if (eap->cmdidx != CMD_yank)
    {
        setpcmark();
        curwin->w_cursor.lnum = eap->line1;
        beginline(BL_SOL | BL_FIX);
    }

    if (VIsual_active)
    {
        end_visual_mode();
    }

    switch (eap->cmdidx)
    {
        case CMD_delete:
            oa.op_type = OP_DELETE;
            op_delete(&oa);
            break;

        case CMD_yank:
            oa.op_type = OP_YANK;
            (void)op_yank(&oa, FALSE, TRUE);
            break;

        default:
            if (eap->cmdidx == CMD_rshift)
            {
                oa.op_type = OP_RSHIFT;
            }
            else
            {
                oa.op_type = OP_LSHIFT;
            }
            op_shift(&oa, FALSE, eap->amount);
            break;
    }
    virtual_op = MAYBE;
    ex_may_print(eap);
}

