    static void
buf_store_time(buf_T *buf, stat_T *st, char_u *fname  __attribute__((unused)) )
{
    buf->b_mtime = (long)st->st_mtime;
    buf->b_mtime_ns = (long)st-> st_mtim.tv_nsec ;
    buf->b_orig_size = st->st_size;
    buf->b_orig_mode = (int)st->st_mode;
}

    static int
match_file_pat(char_u      *pattern, regprog_T   **prog, char_u      *fname, char_u      *sfname, char_u      *tail, int         allow_dirs)
{
    regmatch_T  regmatch;
    int         result = FALSE;

    regmatch.rm_ic = p_fic;
    if (prog != NULL)
    {
        regmatch.regprog = *prog;
    }
    else
    {
        regmatch.regprog = vim_regcomp(pattern, RE_MAGIC);
    }

    if (regmatch.regprog != NULL && ((allow_dirs && (vim_regexec(&regmatch, fname, (colnr_T)0) || (sfname != NULL && vim_regexec(&regmatch, sfname, (colnr_T)0)))) || (!allow_dirs && vim_regexec(&regmatch, tail, (colnr_T)0))))
    {
        result = TRUE;
    }

    if (prog != NULL)
    {
        *prog = regmatch.regprog;
    }
    else
    {
        vim_regfree(regmatch.regprog);
    }
    return result;
}

    static int
match_file_list(char_u *list, char_u *sfname, char_u *ffname)
{
    char_u      buf[ PATH_MAX ];
    char_u      *tail;
    char_u      *regpat;
    char        allow_dirs;
    int         match;
    char_u      *p;

    tail = gettail(sfname);

    p = list;
    while (*p)
    {
        copy_option_part(&p, buf,  PATH_MAX , ",");
        regpat = file_pat_to_reg_pat(buf, NULL, &allow_dirs, FALSE);
        if (regpat == NULL)
        {
            break;
        }
        match = match_file_pat(regpat, NULL, ffname, sfname, tail, (int)allow_dirs);
        vim_free(regpat);
        if (match)
        {
            return TRUE;
        }
    }
    return FALSE;
}

    static char_u *
file_pat_to_reg_pat(char_u      *pat, char_u      *pat_end, char        *allow_dirs, int         no_bslash  __attribute__((unused)) )
{
    int         size = 2;
    char_u      *endp;
    char_u      *reg_pat;
    char_u      *p;
    int         i;
    int         nested = 0;
    int         add_dollar = TRUE;

    if (allow_dirs != NULL)
    {
        *allow_dirs = FALSE;
    }
    if (pat_end == NULL)
    {
        pat_end = pat +  strlen((char *)(pat)) ;
    }

    for (p = pat; p < pat_end; p++)
    {
        switch (*p)
        {
            case '*':
            case '.':
            case ',':
            case '{':
            case '}':
            case '~':
                size += 2;
                break;
            default:
                size++;
                if (enc_dbcs != 0 && (*mb_ptr2len)(p) > 1)
                {
                    ++p;
                    ++size;
                }
                break;
        }
    }
    reg_pat = alloc(size + 1);
    if (reg_pat == NULL)
    {
        return NULL;
    }

    i = 0;

    if (pat[0] == '*')
    {
        while (pat[0] == '*' && pat < pat_end - 1)
        {
            pat++;
        }
    }
    else
    {
        reg_pat[i++] = '^';
    }
    endp = pat_end - 1;
    if (endp >= pat && *endp == '*')
    {
        while (endp - pat > 0 && *endp == '*')
        {
            endp--;
        }
        add_dollar = FALSE;
    }
    for (p = pat; *p && nested >= 0 && p <= endp; p++)
    {
        switch (*p)
        {
            case '*':
                reg_pat[i++] = '.';
                reg_pat[i++] = '*';
                while (p[1] == '*')
                {
                    ++p;
                }
                break;
            case '.':
            case '~':
                reg_pat[i++] = '\\';
                reg_pat[i++] = *p;
                break;
            case '?':
                reg_pat[i++] = '.';
                break;
            case '\\':
                if (p[1] == NUL)
                {
                    break;
                }
                if (*++p == '?')
                {
                    reg_pat[i++] = '?';
                }
                else
                {
                    if (*p == ',' || *p == '%' || *p == '#' || vim_isspace(*p) || *p == '{' || *p == '}')
                    {
                        reg_pat[i++] = *p;
                    }
                    else if (*p == '\\' && p[1] == '\\' && p[2] == '{')
                    {
                        reg_pat[i++] = '\\';
                        reg_pat[i++] = '{';
                        p += 2;
                    }
                    else
                    {
                        if (allow_dirs != NULL && vim_ispathsep(*p))
                        {
                            *allow_dirs = TRUE;
                        }
                        reg_pat[i++] = '\\';
                        if (enc_dbcs != 0 && (*mb_ptr2len)(p) > 1)
                        {
                            reg_pat[i++] = *p++;
                        }
                        reg_pat[i++] = *p;
                    }
                }
                break;
            case '{':
                reg_pat[i++] = '\\';
                reg_pat[i++] = '(';
                nested++;
                break;
            case '}':
                reg_pat[i++] = '\\';
                reg_pat[i++] = ')';
                --nested;
                break;
            case ',':
                if (nested)
                {
                    reg_pat[i++] = '\\';
                    reg_pat[i++] = '|';
                }
                else
                {
                    reg_pat[i++] = ',';
                }
                break;
            default:
                if (enc_dbcs != 0 && (*mb_ptr2len)(p) > 1)
                {
                    reg_pat[i++] = *p++;
                }
                else if (allow_dirs != NULL && vim_ispathsep(*p))
                {
                    *allow_dirs = TRUE;
                }
                reg_pat[i++] = *p;
                break;
        }
    }
    if (add_dollar)
    {
        reg_pat[i++] = '$';
    }
    reg_pat[i] = NUL;
    if (nested != 0)
    {
        if (nested < 0)
        {
            emsg(_(e_missing_open_curly));
        }
        else
        {
            emsg(_(e_missing_close_curly));
        }
         vim_free(reg_pat);
         (reg_pat) = NULL;
    }
    return reg_pat;
}

    static long
read_eintr(int fd, void *buf, size_t bufsize)
{
    long ret;

    for (;;)
    {
        ret =  read((fd), (char *)(buf), (bufsize)) ;
        if (ret >= 0 || errno != EINTR)
        {
            break;
        }
    }
    return ret;
}

    static long
write_eintr(int fd, void *buf, size_t bufsize)
{
    long    ret = 0;
    long    wlen;

    while (ret < (long)bufsize)
    {
        wlen =  write((fd), (char *)((char *)buf + ret), (bufsize - ret)) ;
        if (wlen < 0)
        {
            if (errno != EINTR)
            {
                break;
            }
        }
        else
        {
            ret += wlen;
        }
    }
    return ret;
}

// ==================== filepath.c ====================

    static int
modify_fname(char_u      *src, int         tilde_file, size_t      *usedlen, char_u      **fnamep, char_u      **bufp, size_t      *fnamelen)
{
    int         valid = 0;
    char_u      *tail;
    char_u *s;
    char_u *p;
    char_u *pbuf;
    char_u      dirname[ PATH_MAX ];
    int         c;
    int         has_fullname = 0;
    int         has_homerelative = 0;

repeat:
    if (src[*usedlen] == ':' && src[*usedlen + 1] == 'p')
    {
        has_fullname = 1;

        valid |= VALID_PATH;
        *usedlen += 2;

        if ((*fnamep)[0] == '~' && !(tilde_file && (*fnamep)[1] == NUL))
        {
            *fnamep = expand_env_save(*fnamep);
            vim_free(*bufp);
            *bufp = *fnamep;
            if (*fnamep == NULL)
            {
                return -1;
            }
        }

        for (p = *fnamep; *p != NUL;  p += (*mb_ptr2len)(p) )
        {
            if (vim_ispathsep(*p) && p[1] == '.' && (p[2] == NUL || vim_ispathsep(p[2]) || (p[2] == '.' && (p[3] == NUL || vim_ispathsep(p[3])))))
            {
                break;
            }
        }

        if (*p != NUL || !vim_isAbsName(*fnamep))
        {
            *fnamep = FullName_save(*fnamep, *p != NUL);
            vim_free(*bufp);
            *bufp = *fnamep;
            if (*fnamep == NULL)
            {
                return -1;
            }
        }

        if (mch_isdir(*fnamep))
        {
            *fnamep = vim_strnsave(*fnamep,  strlen((char *)(*fnamep))  + 2);
            vim_free(*bufp);
            *bufp = *fnamep;
            if (*fnamep == NULL)
            {
                return -1;
            }
            add_pathsep(*fnamep);
        }
    }

    while (src[*usedlen] == ':' && ((c = src[*usedlen + 1]) == '.' || c == '~' || c == '8'))
    {
        *usedlen += 2;
        if (c == '8')
        {
            continue;
        }
        pbuf = NULL;
        if (!has_fullname && !has_homerelative)
        {
            if (**fnamep == '~')
            {
                p = pbuf = expand_env_save(*fnamep);
            }
            else
            {
                p = pbuf = FullName_save(*fnamep, FALSE);
            }
        }
        else
        {
            p = *fnamep;
        }

        has_fullname = 0;

        if (p != NULL)
        {
            size_t  dirnamelen = 0;

            if (c == '.')
            {
                mch_dirname(dirname,  PATH_MAX );
                if (has_homerelative)
                {
                    s = vim_strsave(dirname);
                    if (s != NULL)
                    {
                        dirnamelen = home_replace(NULL, s, dirname,  PATH_MAX , TRUE);
                        vim_free(s);
                    }
                }

                if (dirnamelen == 0)
                {
                    dirnamelen =  strlen((char *)(dirname)) ;
                }

                if ( vim_fnamencmp((char_u *)(p), (char_u *)(dirname), (dirnamelen))  == 0)
                {
                    p += dirnamelen;
                    if (vim_ispathsep(*p))
                    {
                        while (*p && vim_ispathsep(*p))
                        {
                            ++p;
                        }
                        *fnamep = p;
                        if (pbuf != NULL)
                        {
                            vim_free(*bufp);
                            *bufp = pbuf;
                            pbuf = NULL;
                        }
                    }
                }
            }
            else
            {
                dirnamelen = home_replace(NULL, p, dirname,  PATH_MAX , TRUE);
                if (*dirname == '~')
                {
                    s = vim_strnsave(dirname, dirnamelen);
                    if (s != NULL)
                    {
                        *fnamep = s;
                        vim_free(*bufp);
                        *bufp = s;
                        has_homerelative = TRUE;
                    }
                }
            }
            vim_free(pbuf);
        }
    }

    tail = gettail(*fnamep);
    *fnamelen =  strlen((char *)(*fnamep)) ;

    while (src[*usedlen] == ':' && src[*usedlen + 1] == 'h')
    {
        valid |= VALID_HEAD;
        *usedlen += 2;
        s = get_past_head(*fnamep);
        while (tail > s && after_pathsep(s, tail))
        {
             tail -= has_mbyte ? ((*mb_head_off)(*fnamep, (tail) - 1) + 1) : 1 ;
        }
        *fnamelen = tail - *fnamep;
        if (*fnamelen == 0)
        {
            p = vim_strsave((char_u *)".");
            if (p == NULL)
            {
                return -1;
            }
            vim_free(*bufp);
            *bufp = *fnamep = tail = p;
            *fnamelen = 1;
        }
        else
        {
            while (tail > s && !after_pathsep(s, tail))
            {
                 tail -= has_mbyte ? ((*mb_head_off)(*fnamep, (tail) - 1) + 1) : 1 ;
            }
        }
    }

    if (src[*usedlen] == ':' && src[*usedlen + 1] == '8')
    {
        *usedlen += 2;
    }

    if (src[*usedlen] == ':' && src[*usedlen + 1] == 't')
    {
        *usedlen += 2;
        *fnamelen -= tail - *fnamep;
        *fnamep = tail;
    }

    while (src[*usedlen] == ':' && (src[*usedlen + 1] == 'e' || src[*usedlen + 1] == 'r'))
    {
        if (src[*usedlen + 1] == 'e' && *fnamep > tail)
        {
            s = *fnamep - 2;
        }
        else
        {
            s = *fnamep + *fnamelen - 1;
        }
        for ( ; s > tail; --s)
        {
            if (s[0] == '.')
            {
                break;
            }
        }
        if (src[*usedlen + 1] == 'e')
        {
            if (s > tail)
            {
                *fnamelen += (*fnamep - (s + 1));
                *fnamep = s + 1;
            }
            else if (*fnamep <= tail)
            {
                *fnamelen = 0;
            }
        }
        else
        {
            char_u *limit = *fnamep;

            if (limit < tail)
            {
                limit = tail;
            }
            if (s > limit)
            {
                *fnamelen = s - *fnamep;
            }
        }
        *usedlen += 2;
    }

    if (src[*usedlen] == ':' && (src[*usedlen + 1] == 's' || (src[*usedlen + 1] == 'g' && src[*usedlen + 2] == 's')))
    {
        char_u      *str;
        char_u      *pat;
        char_u      *sub;
        int         sep;
        char_u      *flags;
        int         didit = FALSE;

        flags = (char_u *)"";
        s = src + *usedlen + 2;
        if (src[*usedlen + 1] == 'g')
        {
            flags = (char_u *)"g";
            ++s;
        }

        sep = *s++;
        if (sep)
        {
            p = vim_strchr(s, sep);
            if (p != NULL)
            {
                pat = vim_strnsave(s, p - s);
                if (pat != NULL)
                {
                    s = p + 1;
                    p = vim_strchr(s, sep);
                    if (p != NULL)
                    {
                        sub = vim_strnsave(s, p - s);
                        str = vim_strnsave(*fnamep, *fnamelen);
                        if (sub != NULL && str != NULL)
                        {
                            size_t slen;

                            *usedlen = p + 1 - src;
                            s = do_string_sub(str, *fnamelen, pat, sub, NULL, flags, &slen);
                            if (s != NULL)
                            {
                                *fnamep = s;
                                *fnamelen = slen;
                                vim_free(*bufp);
                                *bufp = s;
                                didit = TRUE;
                            }
                        }
                        vim_free(sub);
                        vim_free(str);
                    }
                    vim_free(pat);
                }
            }
            if (didit)
            {
                goto repeat;
            }
        }
    }

    if (src[*usedlen] == ':' && src[*usedlen + 1] == 'S')
    {
        c = (*fnamep)[*fnamelen];
        if (c != NUL)
        {
            (*fnamep)[*fnamelen] = NUL;
        }
        p = vim_strsave_shellescape(*fnamep, FALSE, FALSE);
        if (c != NUL)
        {
            (*fnamep)[*fnamelen] = c;
        }
        if (p == NULL)
        {
            return -1;
        }
        vim_free(*bufp);
        *bufp = *fnamep = p;
        *fnamelen =  strlen((char *)(p)) ;
        *usedlen += 2;
    }

    return valid;
}

    static void
shorten_dir_len(char_u *str, int trim_len)
{
    char_u *tail;
    char_u *s;
    char_u *d;
    int         skip = FALSE;
    int         dirchunk_len = 0;

    tail = gettail(str);
    d = str;
    for (s = str; ; ++s)
    {
        if (s >= tail)
        {
            *d++ = *s;
            if (*s == NUL)
            {
                break;
            }
        }
        else if (vim_ispathsep(*s))
        {
            *d++ = *s;
            skip = FALSE;
            dirchunk_len = 0;
        }
        else if (!skip)
        {
            *d++ = *s;
            if (*s != '~' && *s != '.')
            {
                ++dirchunk_len;

                if (dirchunk_len >= trim_len)
                {
                    skip = TRUE;
                }
            }

            if (has_mbyte)
            {
                int l = mb_ptr2len(s);

                while (--l > 0)
                {
                    *d++ = *++s;
                }
            }
        }
    }
}

    static void
shorten_dir(char_u *str)
{
    shorten_dir_len(str, 1);
}

    static int
file_is_readable(char_u *fname)
{
    int         fd;

    if (*fname && !mch_isdir(fname) && (fd =  open(((char *)fname), (O_RDONLY | O_NONBLOCK), (0)) ) >= 0)
    {
        close(fd);
        return TRUE;
    }
    return FALSE;
}

    static size_t
home_replace(buf_T       *buf, char_u      *src, char_u      *dst, int         dstlen, int         one)
{
    size_t dirlen = 0;
    size_t envlen = 0;
    size_t      len;
    char_u *homedir_env;
    char_u *homedir_env_orig;
    char_u      *p;
    char_u      *dst_start;

    if (src == NULL)
    {
        *dst = NUL;
        return 0;
    }

    if (buf != NULL && buf->b_help)
    {
        return vim_snprintf_safelen((char *)dst, dstlen, "%s", gettail(src));
    }

    if (homedir != NULL)
    {
        dirlen =  strlen((char *)(homedir)) ;
    }

    homedir_env_orig = homedir_env =  (char_u *)getenv((char *)((char_u *)"HOME")) ;
    if (homedir_env != NULL && *homedir_env == NUL)
    {
        homedir_env = NULL;
    }

    if (homedir_env != NULL && *homedir_env == '~')
    {
        size_t  usedlen = 0;
        size_t  flen;
        char_u  *fbuf = NULL;

        flen =  strlen((char *)(homedir_env)) ;
        (void)modify_fname((char_u *)":p", FALSE, &usedlen, &homedir_env, &fbuf, &flen);
        flen =  strlen((char *)(homedir_env)) ;
        if (flen > 0 && vim_ispathsep(homedir_env[flen - 1]))
        {
            homedir_env[flen - 1] = NUL;
        }
    }

    if (homedir_env != NULL)
    {
        envlen =  strlen((char *)(homedir_env)) ;
    }

    if (!one)
    {
        src = skipwhite(src);
    }
    dst_start = dst;
    while (*src && dstlen > 0)
    {
        p = homedir;
        len = dirlen;
        for (;;)
        {
            if (   len &&  vim_fnamencmp((char_u *)(src), (char_u *)(p), (len))  == 0 && (vim_ispathsep(src[len]) || (!one && (src[len] == ',' || src[len] == ' ')) || src[len] == NUL))
            {
                src += len;
                if (--dstlen > 0)
                {
                    *dst++ = '~';
                }

                break;
            }
            if (p == homedir_env)
            {
                break;
            }
            p = homedir_env;
            len = envlen;
        }

        while (*src && (one || (*src != ',' && *src != ' ')) && --dstlen > 0)
        {
            *dst++ = *src++;
        }
        while ((*src == ' ' || *src == ',') && --dstlen > 0)
        {
            *dst++ = *src++;
        }
    }

    *dst = NUL;

    if (homedir_env != homedir_env_orig)
    {
        vim_free(homedir_env);
    }

    return (size_t)(dst - dst_start);
}

    static char_u  *
home_replace_save(buf_T       *buf, char_u      *src)
{
    char_u      *dst;
    unsigned    len;

    len = 3;
    if (src != NULL)
    {
        len += (unsigned) strlen((char *)(src)) ;
    }
    dst = alloc(len);
    if (dst != NULL)
    {
        home_replace(buf, src, dst, len, TRUE);
    }
    return dst;
}

    static int
fullpathcmp(char_u *s1, char_u *s2, int     checkname, int     expandenv)
{
    char_u          exp1[ PATH_MAX ];
    char_u          full1[ PATH_MAX ];
    char_u          full2[ PATH_MAX ];
    stat_T st1;
    stat_T st2;
    int r1;
    int r2;

    if (expandenv)
    {
        expand_env(s1, exp1,  PATH_MAX );
    }
    else
    {
        vim_strncpy(exp1, s1,  PATH_MAX  - 1);
    }
    r1 =  stat(((char *)exp1), (&st1)) ;
    r2 =  stat(((char *)s2), (&st2)) ;
    if (r1 != 0 && r2 != 0)
    {
        if (checkname)
        {
            if ( vim_fnamecmp((char_u *)(exp1), (char_u *)(s2))  == 0)
            {
                return FPC_SAMEX;
            }
            r1 = vim_FullName(exp1, full1,  PATH_MAX , FALSE);
            r2 = vim_FullName(s2, full2,  PATH_MAX , FALSE);
            if (r1 == OK && r2 == OK &&  vim_fnamecmp((char_u *)(full1), (char_u *)(full2))  == 0)
            {
                return FPC_SAMEX;
            }
        }
        return FPC_NOTX;
    }
    if (r1 != 0 || r2 != 0)
    {
        return FPC_DIFFX;
    }
    if (st1.st_dev == st2.st_dev && st1.st_ino == st2.st_ino)
    {
        return FPC_SAME;
    }
    return FPC_DIFF;
}

    static char_u *
gettail(char_u *fname)
{
    char_u *p1;
    char_u *p2;

    if (fname == NULL)
    {
        return (char_u *)"";
    }
    for (p1 = p2 = get_past_head(fname); *p2; )
    {
        if (vim_ispathsep_nocolon(*p2))
        {
            p1 = p2 + 1;
        }
         p2 += (*mb_ptr2len)(p2) ;
    }
    return p1;
}

    static char_u *
gettail_sep(char_u *fname)
{
    char_u      *p;
    char_u      *t;

    p = get_past_head(fname);
    t = gettail(fname);
    while (t > p && after_pathsep(fname, t))
    {
        --t;
    }
    return t;
}

    static char_u *
get_past_head(char_u *path)
{
    char_u  *retval;

    retval = path;

    while (vim_ispathsep(*retval))
    {
        ++retval;
    }

    return retval;
}

    static int
vim_ispathsep(int c)
{
    return (c == '/');
}

    static int
vim_ispathsep_nocolon(int c)
{
    return vim_ispathsep(c)
        ;
}

    static int
dir_of_file_exists(char_u *fname)
{
    char_u      *p;
    int         c;
    int         retval;

    p = gettail_sep(fname);
    if (p == fname)
    {
        return TRUE;
    }
    c = *p;
    *p = NUL;
    retval = mch_isdir(fname);
    *p = c;
    return retval;
}

    static int
vim_fnamecmp(char_u *x, char_u *y)
{
    if (p_fic)
    {
        return  mb_strnicmp((char_u *)(x), (char_u *)(y), (int)MAXCOL) ;
    }
    return  strcmp((char *)(x), (char *)(y)) ;
}

    static int
vim_fnamencmp(char_u *x, char_u *y, size_t len)
{
    if (p_fic)
    {
        return  mb_strnicmp((char_u *)(x), (char_u *)(y), (int)(len)) ;
    }
    return  strncmp((char *)(x), (char *)(y), (len)) ;
}

    static char_u  *
concat_fnames(char_u *fname1, size_t fname1len, char_u *fname2, size_t fname2len, int sep, string_T *ret)
{
    ret->string = alloc(fname1len + (sep ? sizeof( ((char_u)'/') ) : 0) + fname2len + 1);
    if (ret->string == NULL)
    {
        ret->length = 0;
    }
    else
    {
         strcpy((char *)(ret->string), (char *)(fname1)) ;
        ret->length = fname1len;
        if (sep && *ret->string != NUL && !after_pathsep(ret->string, ret->string + ret->length))
        {
             strcpy((char *)(ret->string + ret->length), (char *)( "/" )) ;
            ret->length += sizeof( ((char_u)'/') );
        }
         strcpy((char *)(ret->string + ret->length), (char *)(fname2)) ;
        ret->length += fname2len;
    }

    return ret->string;
}

    static void
add_pathsep(char_u *p)
{
    size_t  plen;

    if (*p == NUL)
    {
        return;
    }

    plen =  strlen((char *)(p)) ;
    if (!after_pathsep(p, p + plen))
    {
         strcpy((char *)(p + plen), (char *)( "/" )) ;
    }
}

    static char_u  *
FullName_save(char_u      *fname, int         force)
{
    char_u      *buf;
    char_u      *new_fname = NULL;

    if (fname == NULL)
    {
        return NULL;
    }

    buf = alloc( PATH_MAX );
    if (buf == NULL)
    {
        return NULL;
    }

    if (vim_FullName(fname, buf,  PATH_MAX , force) != FAIL)
    {
        new_fname = vim_strsave(buf);
    }
    else
    {
        new_fname = vim_strsave(fname);
    }
    vim_free(buf);
    return new_fname;
}

    static int
vim_fexists(char_u *fname)
{
    stat_T st;

    if ( stat(((char *)fname), (&st)) )
    {
        return FALSE;
    }
    return TRUE;
}

    static int
expand_wildcards_eval(char_u       **pat, int           *num_file, char_u      ***file, int            flags)
{
    int         ret = FAIL;
    char_u      *eval_pat = NULL;
    char_u      *exp_pat = *pat;
    char        *ignored_msg;
    size_t      usedlen;
    int         is_cur_alt_file = *exp_pat == '%' || *exp_pat == '#';
    int         star_follows = FALSE;

    if (is_cur_alt_file || *exp_pat == '<')
    {
        ++emsg_off;
        eval_pat = eval_vars(exp_pat, exp_pat, &usedlen, NULL, &ignored_msg, NULL, TRUE);
        --emsg_off;
        if (eval_pat != NULL)
        {
            star_follows =  strcmp((char *)(exp_pat + usedlen), (char *)("*"))  == 0;
            exp_pat = concat_str(eval_pat, exp_pat + usedlen);
        }
    }

    if (exp_pat != NULL)
    {
        ret = expand_wildcards(1, &exp_pat, num_file, file, flags);
    }

    if (eval_pat != NULL)
    {
        if (*num_file == 0 && is_cur_alt_file && star_follows)
        {
            *file =  (char_u * *)alloc(sizeof(char_u *)) ;
            if (*file != NULL)
            {
                **file = eval_pat;
                eval_pat = NULL;
                *num_file = 1;
                ret = OK;
            }
        }
        vim_free(exp_pat);
        vim_free(eval_pat);
    }

    return ret;
}

    static int
expand_wildcards(int            num_pat, char_u       **pat, int           *num_files, char_u      ***files, int            flags)
{
    int         retval;
    int i;
    int j;
    char_u      *p;
    int         non_suf_match;

    retval = gen_expand_wildcards(num_pat, pat, num_files, files, flags);

    if ((flags & EW_KEEPALL) || retval == FAIL)
    {
        return retval;
    }

    if (*p_wig)
    {
        char_u  *ffname;

        for (i = 0; i < *num_files; ++i)
        {
            ffname = FullName_save((*files)[i], FALSE);
            if (ffname == NULL)
            {
                break;
            }
            if (match_file_list(p_wig, (*files)[i], ffname))
            {
                vim_free((*files)[i]);
                for (j = i; j + 1 < *num_files; ++j)
                {
                    (*files)[j] = (*files)[j + 1];
                }
                --*num_files;
                --i;
            }
            vim_free(ffname);
        }

        if (*num_files == 0)
        {
             vim_free(*files);
             (*files) = NULL;
            return FAIL;
        }
    }

    if (*num_files > 1 && !got_int)
    {
        non_suf_match = 0;
        for (i = 0; i < *num_files; ++i)
        {
            if (!match_suffix((*files)[i]))
            {
                p = (*files)[i];
                for (j = i; j > non_suf_match; --j)
                {
                    (*files)[j] = (*files)[j - 1];
                }
                (*files)[non_suf_match++] = p;
            }
        }
    }

    return retval;
}

    static int
match_suffix(char_u *fname)
{
    int fnamelen;
    int setsuflen;
    char_u      *setsuf;
    char_u      suf_buf[MAXSUFLEN];

    fnamelen = (int) strlen((char *)(fname)) ;
    setsuflen = 0;
    for (setsuf = p_su; *setsuf; )
    {
        setsuflen = copy_option_part(&setsuf, suf_buf, MAXSUFLEN, ".,");
        if (setsuflen == 0)
        {
            char_u *tail = gettail(fname);

            if (vim_strchr(tail, '.') == NULL)
            {
                setsuflen = 1;
                break;
            }
        }
        else
        {
            if (fnamelen >= setsuflen &&  vim_fnamencmp((char_u *)(suf_buf), (char_u *)(fname + fnamelen - setsuflen), ((size_t)setsuflen))  == 0)
            {
                break;
            }
            setsuflen = 0;
        }
    }
    return (setsuflen != 0);
}

    static int
gen_expand_wildcards(int         num_pat, char_u      **pat, int         *num_file, char_u      ***file, int         flags)
{
    return save_patterns(num_pat, pat, num_file, file);
}

    static void
FreeWild(int count, char_u **files)
{
    if (count <= 0 || files == NULL)
    {
        return;
    }
    while (count--)
    {
        vim_free(files[count]);
    }
    vim_free(files);
}

    static int
pathcmp(const char *p, const char *q, int maxlen)
{
    int i;
    int j;
    int c1;
    int c2;
    const char  *s = NULL;

    i = 0;
    for (j = 0; maxlen < 0 || (i < maxlen && j < maxlen);)
    {
        c1 =  (has_mbyte ? mb_ptr2char((char_u *)p + i) : (int)*((char_u *)p + i)) ;
        c2 =  (has_mbyte ? mb_ptr2char((char_u *)q + j) : (int)*((char_u *)q + j)) ;

        if (c1 == NUL)
        {
            if (c2 == NUL)
            {
                return 0;
            }
            s = q;
            i = j;
            break;
        }

        if (c2 == NUL)
        {
            s = p;
            break;
        }

        if ((p_fic ?  vim_toupper(c1)  !=  vim_toupper(c2)  : c1 != c2))
        {
            if (vim_ispathsep(c1))
            {
                return -1;
            }
            if (vim_ispathsep(c2))
            {
                return 1;
            }
            return p_fic ?  vim_toupper(c1)  -  vim_toupper(c2) 
                    : c1 - c2;
        }

        i += mb_ptr2len((char_u *)p + i);
        j += mb_ptr2len((char_u *)q + j);
    }
    if (s == NULL)
    {
        return 0;
    }

    c1 =  (has_mbyte ? mb_ptr2char((char_u *)s + i) : (int)*((char_u *)s + i)) ;
    c2 =  (has_mbyte ? mb_ptr2char((char_u *)s + i + mb_ptr2len((char_u *)s + i)) : (int)*((char_u *)s + i + mb_ptr2len((char_u *)s + i))) ;
    if (c2 == NUL && i > 0 && !after_pathsep((char_u *)s, (char_u *)s + i) && c1 == '/')
    {
        return 0;
    }
    if (s == q)
    {
        return -1;
    }
    return 1;
}

    static int
vim_isAbsName(char_u *name)
{
    return (path_with_url(name) != 0 || mch_isFullName(name));
}

    static int
vim_FullName(char_u      *fname, char_u      *buf, int         len, int         force)
{
    int         retval = OK;
    int         url;

    *buf = NUL;
    if (fname == NULL)
    {
        return FAIL;
    }

    url = path_with_url(fname);
    if (!url)
    {
        retval = mch_FullName(fname, buf, len, force);
    }
    if (url || retval == FAIL)
    {
        vim_strncpy(buf, fname, len - 1);
    }
    return retval;
}

// ==================== findfile.c ====================

typedef struct ff_stack
{
    struct ff_stack     *ffs_prev;

    string_T            ffs_fix_path;
    string_T            ffs_wc_path;

    char_u              **ffs_filearray;
    int                 ffs_filearray_size;
    int                 ffs_filearray_cur;

    int                 ffs_stage;

    int                 ffs_level;

    int                 ffs_star_star_empty;
} ff_stack_T;

typedef struct ff_visited
{
    struct ff_visited   *ffv_next;

    char_u              *ffv_wc_path;

    int                 ffv_dev_valid;
    dev_t               ffv_dev;
    ino_t               ffv_ino;
    char_u              ffv_fname[1];
} ff_visited_T;

typedef struct ff_visited_list_hdr
{
    struct ff_visited_list_hdr  *ffvl_next;

    char_u                      *ffvl_filename;

    ff_visited_T                *ffvl_visited_list;

} ff_visited_list_hdr_T;

typedef struct ff_search_ctx_T
{
    ff_stack_T                  *ffsc_stack_ptr;
    ff_visited_list_hdr_T       *ffsc_visited_list;
    ff_visited_list_hdr_T       *ffsc_dir_visited_list;
    ff_visited_list_hdr_T       *ffsc_visited_lists_list;
    ff_visited_list_hdr_T       *ffsc_dir_visited_lists_list;
    string_T                    ffsc_file_to_search;
    string_T                    ffsc_start_dir;
    string_T                    ffsc_fix_path;
    string_T                    ffsc_wc_path;
    int                         ffsc_level;
    string_T                    *ffsc_stopdirs_v;
    int                         ffsc_find_what;
    int                         ffsc_tagfile;
} ff_search_ctx_T;

static void vim_findfile_free_visited(void *search_ctx_arg);
static void vim_findfile_free_visited_list(ff_visited_list_hdr_T **list_headp);
static void ff_free_visited_list(ff_visited_T *vl);

static ff_stack_T *ff_pop(ff_search_ctx_T *search_ctx);
static void ff_clear(ff_search_ctx_T *search_ctx);
static void ff_free_stack_element(ff_stack_T *stack_ptr);

    static void
vim_findfile_cleanup(void *ctx)
{
    if (ctx == NULL)
    {
        return;
    }

    vim_findfile_free_visited(ctx);
    ff_clear(ctx);
    vim_free(ctx);
}

    static void
vim_findfile_free_visited(void *search_ctx_arg)
{
    ff_search_ctx_T *search_ctx;

    if (search_ctx_arg == NULL)
    {
        return;
    }

    search_ctx = (ff_search_ctx_T *)search_ctx_arg;
    vim_findfile_free_visited_list(&search_ctx->ffsc_visited_lists_list);
    vim_findfile_free_visited_list(&search_ctx->ffsc_dir_visited_lists_list);
}

    static void
vim_findfile_free_visited_list(ff_visited_list_hdr_T **list_headp)
{
    ff_visited_list_hdr_T *vp;

    while (*list_headp != NULL)
    {
        vp = (*list_headp)->ffvl_next;
        ff_free_visited_list((*list_headp)->ffvl_visited_list);

        vim_free((*list_headp)->ffvl_filename);
        vim_free(*list_headp);
        *list_headp = vp;
    }
    *list_headp = NULL;
}

    static void
ff_free_visited_list(ff_visited_T *vl)
{
    ff_visited_T *vp;

    while (vl != NULL)
    {
        vp = vl->ffv_next;
        vim_free(vl->ffv_wc_path);
        vim_free(vl);
        vl = vp;
    }
    vl = NULL;
}

    static ff_stack_T *
ff_pop(ff_search_ctx_T *search_ctx)
{
    ff_stack_T  *sptr;

    sptr = search_ctx->ffsc_stack_ptr;
    if (search_ctx->ffsc_stack_ptr != NULL)
    {
        search_ctx->ffsc_stack_ptr = search_ctx->ffsc_stack_ptr->ffs_prev;
    }

    return sptr;
}

    static void
ff_free_stack_element(ff_stack_T *stack_ptr)
{
     vim_free(stack_ptr->ffs_fix_path.string);
     (stack_ptr->ffs_fix_path.string) = NULL;
     stack_ptr->ffs_fix_path.length = 0;
     vim_free(stack_ptr->ffs_wc_path.string);
     (stack_ptr->ffs_wc_path.string) = NULL;
     stack_ptr->ffs_wc_path.length = 0;

    if (stack_ptr->ffs_filearray != NULL)
    {
        FreeWild(stack_ptr->ffs_filearray_size, stack_ptr->ffs_filearray);
    }

    vim_free(stack_ptr);
}

    static void
ff_clear(ff_search_ctx_T *search_ctx)
{
    ff_stack_T   *sptr;

    while ((sptr = ff_pop(search_ctx)) != NULL)
    {
        ff_free_stack_element(sptr);
    }

    if (search_ctx->ffsc_stopdirs_v != NULL)
    {
        int  i = 0;

        while (search_ctx->ffsc_stopdirs_v[i].string != NULL)
        {
            vim_free(search_ctx->ffsc_stopdirs_v[i].string);
            i++;
        }
         vim_free(search_ctx->ffsc_stopdirs_v);
         (search_ctx->ffsc_stopdirs_v) = NULL;
    }

     vim_free(search_ctx->ffsc_file_to_search.string);
     (search_ctx->ffsc_file_to_search.string) = NULL;
     search_ctx->ffsc_file_to_search.length = 0;
     vim_free(search_ctx->ffsc_start_dir.string);
     (search_ctx->ffsc_start_dir.string) = NULL;
     search_ctx->ffsc_start_dir.length = 0;
     vim_free(search_ctx->ffsc_fix_path.string);
     (search_ctx->ffsc_fix_path.string) = NULL;
     search_ctx->ffsc_fix_path.length = 0;
     vim_free(search_ctx->ffsc_wc_path.string);
     (search_ctx->ffsc_wc_path.string) = NULL;
     search_ctx->ffsc_wc_path.length = 0;
    search_ctx->ffsc_level = 0;
}

    static char_u *
find_file_in_path(char_u      *ptr, int         len, int         options, int         first, char_u      *rel_fname, char_u      **file_to_find, char        **search_ctx)
{
    char_u      *name;

    if (!first)
    {
        return NULL;
    }

    name = vim_strnsave(ptr, len);
    if (name == NULL)
    {
        return NULL;
    }

    if (mch_getperm(name) < 0)
    {
        vim_free(name);
        return NULL;
    }

    return name;
}

    static char_u *
grab_file_name(long count, linenr_T *file_lnum)
{
    int options = FNAME_MESS|FNAME_EXP|FNAME_REL|FNAME_UNESC;

    if (VIsual_active)
    {
        int     len;
        char_u  *ptr;

        if (get_visual_text(NULL, &ptr, &len) == FAIL)
        {
            return NULL;
        }
        if (file_lnum != NULL && ptr[len] == ':' &&  (isdigit ((unsigned char)(ptr[len + 1]))) )
        {
            char_u *p = ptr + len + 1;

            *file_lnum = getdigits(&p);
        }
        return find_file_name_in_path(ptr, len, options, count, curbuf->b_ffname);
    }
    return file_name_at_cursor(options | FNAME_HYP, count, file_lnum);
}

    static char_u *
file_name_at_cursor(int options, long count, linenr_T *file_lnum)
{
    return file_name_in_line(ml_get_curline(), curwin->w_cursor.col, options, count, curbuf->b_ffname, file_lnum);
}

    static char_u *
file_name_in_line(char_u      *line, int         col, int         options, long        count, char_u      *rel_fname, linenr_T    *file_lnum)
{
    char_u      *ptr;
    int         len;
    int         in_type = TRUE;
    int         is_url = FALSE;

    ptr = line + col;
    while (*ptr != NUL && !vim_isfilec(*ptr))
    {
         ptr += (*mb_ptr2len)(ptr) ;
    }
    if (*ptr == NUL)
    {
        if (options & FNAME_MESS)
        {
            emsg(_(e_no_file_name_under_cursor));
        }
        return NULL;
    }

    while (ptr > line)
    {
        if (has_mbyte && (len = (*mb_head_off)(line, ptr - 1)) > 0)
        {
            ptr -= len + 1;
        }
        else if (vim_isfilec(ptr[-1]) || ((options & FNAME_HYP) && path_is_url(ptr - 1)))
        {
            --ptr;
        }
        else
        {
            break;
        }
    }

    len = 0;
    while (vim_isfilec(ptr[len]) || (ptr[len] == '\\' && ptr[len + 1] == ' ') || ((options & FNAME_HYP) && path_is_url(ptr + len)) || (is_url && vim_strchr((char_u *)":?&=", ptr[len]) != NULL))
    {
        if ((ptr[len] >= 'A' && ptr[len] <= 'Z') || (ptr[len] >= 'a' && ptr[len] <= 'z'))
        {
            if (in_type && path_is_url(ptr + len + 1))
            {
                is_url = TRUE;
            }
        }
        else
        {
            in_type = FALSE;
        }

        if (ptr[len] == '\\')
        {
            ++len;
        }
        if (has_mbyte)
        {
            len += (*mb_ptr2len)(ptr + len);
        }
        else
        {
            ++len;
        }
    }

    if (len > 2 && vim_strchr((char_u *)".,:;!", ptr[len - 1]) != NULL && ptr[len - 2] != '.')
    {
        --len;
    }

    if (file_lnum != NULL)
    {
        char_u  *p;
        char    *match_text = " line ";
        size_t  match_textlen = 6;

        p = ptr + len;
        if ( strncmp((char *)(p), (char *)(match_text), (match_textlen))  == 0)
        {
            p += match_textlen;
        }
        else
        {
            match_text = _(line_msg);
            match_textlen =  strlen((char *)(match_text)) ;

            if ( strncmp((char *)(p), (char *)(match_text), (match_textlen))  == 0)
            {
                p += match_textlen;
            }
            else
            {
                p = skipwhite(p);
            }
        }
        if (*p != NUL)
        {
            if (! (isdigit ((unsigned char)(*p))) )
            {
                ++p;
            }
            p = skipwhite(p);
            if ( (isdigit ((unsigned char)(*p))) )
            {
                *file_lnum = (int)getdigits(&p);
            }
        }
    }

    return find_file_name_in_path(ptr, len, options, count, rel_fname);
}

    static char_u *
find_file_name_in_path(char_u      *ptr, int         len, int         options, long        count, char_u      *rel_fname)
{
    char_u      *file_name;
    int         c;

    if (len == 0)
    {
        return NULL;
    }

    if (options & FNAME_EXP)
    {
        char_u  *file_to_find = NULL;
        char    *search_ctx = NULL;

        file_name = find_file_in_path(ptr, len, options & ~FNAME_MESS, TRUE, rel_fname, &file_to_find, &search_ctx);

        if (file_name == NULL && (options & FNAME_MESS))
        {
            c = ptr[len];
            ptr[len] = NUL;
            semsg(_(e_cant_find_file_str_in_path_2), ptr);
            ptr[len] = c;
        }

        while (file_name != NULL && --count > 0)
        {
            vim_free(file_name);
            file_name = find_file_in_path(ptr, len, options, FALSE, rel_fname, &file_to_find, &search_ctx);
        }

        vim_free(file_to_find);
        vim_findfile_cleanup(search_ctx);
    }
    else
    {
        file_name = vim_strnsave(ptr, len);
    }

    return file_name;
}

    static int
vim_ispathlistsep(int c)
{
    return (c == ':');
}

// ==================== fuzzy.c ====================

typedef double score_t;
static score_t match_positions(char_u *needle, char_u *haystack, int_u *positions);
static int has_match(char_u *needle, char_u *haystack);

enum { SCORE_SCALE = 1000 };

    static int
fuzzy_match(char_u      *str, char_u      *pat_arg, int         matchseq, int         *outScore, int_u       *matches, int         maxMatches)
{
    char_u      *save_pat;
    char_u      *pat;
    char_u      *p;
    int         complete = FALSE;
    int         score = 0;
    int         numMatches = 0;
    int         pat_chars = 0;
    score_t     fzy_score;

    *outScore = 0;

    save_pat = vim_strsave(pat_arg);
    if (save_pat == NULL)
    {
        return FALSE;
    }
    pat = save_pat;
    p = pat;

    while (TRUE)
    {
        if (matchseq)
        {
            complete = TRUE;
        }
        else
        {
            p = skipwhite(p);
            if (*p == NUL)
            {
                break;
            }
            pat = p;
            while (*p != NUL && ! (( (has_mbyte ? mb_ptr2char(p) : (int)*(p)) ) == ' ' || ( (has_mbyte ? mb_ptr2char(p) : (int)*(p)) ) == '\t') )
            {
                if (has_mbyte)
                {
                     p += (*mb_ptr2len)(p) ;
                }
                else
                {
                    ++p;
                }
            }
            if (*p == NUL)
            {
                complete = TRUE;
            }
            *p = NUL;
        }
        pat_chars =  (has_mbyte ? mb_charlen(pat) : (int) strlen((char *)(pat)) ) ;
        if (pat_chars > maxMatches)
        {
            pat_chars = maxMatches;
        }
        if (numMatches > maxMatches - pat_chars)
        {
            numMatches = 0;
            *outScore =  INT_MIN ;
            break;
        }

        score =  INT_MIN ;
        if (has_match(pat, str))
        {
            fzy_score = match_positions(pat, str, matches + numMatches);
            if (fzy_score !=  (-INFINITY) )
            {
                score = (fzy_score ==  INFINITY ) ? INT_MAX
                    : (fzy_score < 0) ? (int)ceil(fzy_score * SCORE_SCALE - 0.5)
                    : (int)floor(fzy_score * SCORE_SCALE + 0.5);
            }
        }

        if (score ==  INT_MIN )
        {
            numMatches = 0;
            *outScore =  INT_MIN ;
            break;
        }

        if (score > 0 && *outScore > INT_MAX - score)
        {
            *outScore = INT_MAX;
        }
        else if (score < 0 && *outScore < INT_MIN + 1 - score)
        {
            *outScore = INT_MIN + 1;
        }
        else
        {
            *outScore += score;
        }

        numMatches += pat_chars;

        if (complete || numMatches >= maxMatches)
        {
            break;
        }

        ++p;
    }

    vim_free(save_pat);
    return numMatches != 0;
}

    static int
fuzzy_match_str_compare(const void *s1, const void *s2)
{
    int         v1 = ((fuzmatch_str_T *)s1)->score;
    int         v2 = ((fuzmatch_str_T *)s2)->score;
    int         idx1 = ((fuzmatch_str_T *)s1)->idx;
    int         idx2 = ((fuzmatch_str_T *)s2)->idx;

    if (v1 == v2)
    {
        return idx1 == idx2 ? 0 : idx1 > idx2 ? 1 : -1;
    }
    else
    {
        return v1 > v2 ? -1 : 1;
    }
}

    static void
fuzzy_match_str_sort(fuzmatch_str_T *fm, int sz)
{
    qsort((void *)fm, (size_t)sz, sizeof(fuzmatch_str_T), fuzzy_match_str_compare);
}

    static int
fuzzy_match_func_compare(const void *s1, const void *s2)
{
    int         v1 = ((fuzmatch_str_T *)s1)->score;
    int         v2 = ((fuzmatch_str_T *)s2)->score;
    int         idx1 = ((fuzmatch_str_T *)s1)->idx;
    int         idx2 = ((fuzmatch_str_T *)s2)->idx;
    char_u      *str1 = ((fuzmatch_str_T *)s1)->str;
    char_u      *str2 = ((fuzmatch_str_T *)s2)->str;

    if (*str1 != '<' && *str2 == '<')
    {
        return -1;
    }
    if (*str1 == '<' && *str2 != '<')
    {
        return 1;
    }
    if (v1 == v2)
    {
        return idx1 == idx2 ? 0 : idx1 > idx2 ? 1 : -1;
    }
    else
    {
        return v1 > v2 ? -1 : 1;
    }
}

    static void
fuzzy_match_func_sort(fuzmatch_str_T *fm, int sz)
{
    qsort((void *)fm, (size_t)sz, sizeof(fuzmatch_str_T), fuzzy_match_func_compare);
}

    static int
fuzzy_match_str(char_u *str, char_u *pat)
{
    int         score =  INT_MIN ;
    int_u       matchpos[FUZZY_MATCH_MAX_LEN];

    if (str == NULL || pat == NULL)
    {
        return score;
    }

    fuzzy_match(str, pat, TRUE, &score, matchpos, sizeof(matchpos) / sizeof(matchpos[0]));

    return score;
}

    static garray_T *
fuzzy_match_str_with_pos(char_u *str  __attribute__((unused)) , char_u *pat  __attribute__((unused)) )
{
    int             score =  INT_MIN ;
    garray_T        *match_positions = NULL;
    int_u           matches[FUZZY_MATCH_MAX_LEN];
    int             j = 0;

    if (str == NULL || pat == NULL)
    {
        return NULL;
    }

    match_positions =  (garray_T *)alloc(sizeof(garray_T)) ;
    if (match_positions == NULL)
    {
        return NULL;
    }
    ga_init2(match_positions, sizeof(int_u), 10);

    if (!fuzzy_match(str, pat, FALSE, &score, matches, FUZZY_MATCH_MAX_LEN) || score ==  INT_MIN )
    {
        ga_clear(match_positions);
        vim_free(match_positions);
        return NULL;
    }

    for (char_u *p = pat; *p != NUL;  p += (*mb_ptr2len)(p) )
    {
        if (! (( (has_mbyte ? mb_ptr2char(p) : (int)*(p)) ) == ' ' || ( (has_mbyte ? mb_ptr2char(p) : (int)*(p)) ) == '\t') )
        {
            if (ga_grow(match_positions, 1) == FAIL)
            {
                ga_clear(match_positions);
                vim_free(match_positions);
                return NULL;
            }
            ((int_u *)match_positions->ga_data)[match_positions->ga_len] =
                                                                    matches[j];
            match_positions->ga_len++;
            j++;
        }
    }

    return match_positions;
}

    static int
fuzzy_match_str_in_line(char_u      **ptr, char_u      *pat, int         *len, pos_T       *current_pos, int         *score)
{
    char_u      *str = *ptr;
    char_u      *strBegin = str;
    char_u      *end = NULL;
    char_u      *start = NULL;
    int         found = FALSE;
    char        save_end;
    char_u      *line_end = NULL;

    if (str == NULL || pat == NULL)
    {
        return found;
    }
    line_end = find_line_end(str);

    while (str < line_end)
    {
        start = find_word_start(str);
        if (*start == NUL)
        {
            break;
        }
        end = find_word_end(start);

        save_end = *end;
        *end = NUL;

        *score = fuzzy_match_str(start, pat);
        *end = save_end;

        if (*score !=  INT_MIN )
        {
            *len = (int)(end - start);
            found = TRUE;
            *ptr = start;
            if (current_pos)
            {
                current_pos->col += (int)(end - strBegin);
            }
            break;
        }

        str = end;
        while (*str != NUL && !vim_iswordp(str))
        {
             str += (*mb_ptr2len)(str) ;
        }
    }

    if (!found)
    {
        *ptr = line_end;
    }

    return found;
}

    static int
search_for_fuzzy_match(buf_T       *buf, pos_T       *pos, char_u      *pattern, int         dir, pos_T       *start_pos, int         *len, char_u      **ptr, int         *score)
{
    pos_T       current_pos = *pos;
    pos_T       circly_end;
    int         found_new_match = FALSE;
    int         looped_around = FALSE;
    int         whole_line = ctrl_x_mode_whole_line();

    if (buf == curbuf)
    {
        circly_end = *start_pos;
    }
    else
    {
        circly_end.lnum = buf->b_ml.ml_line_count;
        circly_end.col = 0;
        circly_end.coladd = 0;
    }

    if (whole_line && start_pos->lnum != pos->lnum)
    {
        current_pos.lnum += dir;
    }

    do
    {
        if (looped_around && (whole_line ? current_pos.lnum == circly_end.lnum :  (((current_pos).lnum == (circly_end).lnum) && ((current_pos).col == (circly_end).col) && ((current_pos).coladd == (circly_end).coladd)) ))
        {
            break;
        }

        if (current_pos.lnum >= 1 && current_pos.lnum <= buf->b_ml.ml_line_count)
        {
            *ptr = ml_get_buf(buf, current_pos.lnum, FALSE);
            if (!whole_line)
            {
                *ptr += current_pos.col;
            }

            if (*ptr != NULL && **ptr != NUL)
            {
                if (!whole_line)
                {
                    found_new_match = fuzzy_match_str_in_line(ptr, pattern, len, &current_pos, score);
                    if (found_new_match)
                    {
                        *pos = current_pos;
                        break;
                    }
                    else if (looped_around && current_pos.lnum == circly_end.lnum)
                    {
                        break;
                    }
                }
                else
                {
                    char_u *line = *ptr;
                    char_u *p = skipwhite(line);
                    if (fuzzy_match_str(p, pattern) !=  INT_MIN )
                    {
                        found_new_match = TRUE;
                        *pos = current_pos;
                        *ptr = p;
                        *len = (int)ml_get_buf_len(buf, current_pos.lnum) -
                                                                (int)(p - line);
                        break;
                    }
                }
            }
        }

        if (dir == FORWARD)
        {
            if (++current_pos.lnum > buf->b_ml.ml_line_count)
            {
                if (p_ws)
                {
                    current_pos.lnum = 1;
                    looped_around = TRUE;
                }
                else
                {
                    break;
                }
            }
        }
        else
        {
            if (--current_pos.lnum < 1)
            {
                if (p_ws)
                {
                    current_pos.lnum = buf->b_ml.ml_line_count;
                    looped_around = TRUE;
                }
                else
                {
                    break;
                }

            }
        }
        current_pos.col = 0;
    } while (TRUE);

    return found_new_match;
}

    static void
fuzmatch_str_free(fuzmatch_str_T *fuzmatch, int count)
{
    if (fuzmatch == NULL)
    {
        return;
    }

    for (int i = 0; i < count; ++i)
    {
        vim_free(fuzmatch[i].str);
    }
    vim_free(fuzmatch);
}

    static int
fuzzymatches_to_strmatches(fuzmatch_str_T  *fuzmatch, char_u          ***matches, int             count, int             funcsort)
{
    if (count <= 0)
    {
        goto theend;
    }

    *matches =  (char_u * *)alloc(sizeof(char_u *) * (count)) ;
    if (*matches == NULL)
    {
        fuzmatch_str_free(fuzmatch, count);
        return FAIL;
    }

    if (funcsort)
    {
        fuzzy_match_func_sort((void *)fuzmatch, (size_t)count);
    }
    else
    {
        fuzzy_match_str_sort((void *)fuzmatch, (size_t)count);
    }

    for (int i = 0; i < count; i++)
    {
        (*matches)[i] = fuzmatch[i].str;
    }

theend:
    vim_free(fuzmatch);
    return OK;
}

    static int
has_match(char_u *needle, char_u *haystack)
{
    if (!needle || !haystack || !*needle)
    {
        return FAIL;
    }

    char_u *n_ptr = needle;
    char_u *h_ptr = haystack;

    while (*n_ptr)
    {
        int n_char = mb_ptr2char(n_ptr);
        int found = FALSE;

        while (*h_ptr)
        {
            int h_char = mb_ptr2char(h_ptr);
            if (h_char == n_char || h_char ==  vim_toupper(n_char) )
            {
                found = TRUE;
                h_ptr += mb_ptr2len(h_ptr);
                break;
            }
            h_ptr += mb_ptr2len(h_ptr);
        }

        if (!found)
        {
            return FAIL;
        }

        n_ptr += mb_ptr2len(n_ptr);
    }

    return OK;
}

typedef struct match_struct
{
    int needle_len;
    int haystack_len;
    int lower_needle[ FUZZY_MATCH_MAX_LEN ];
    int lower_haystack[ FUZZY_MATCH_MAX_LEN ];
    score_t match_bonus[ FUZZY_MATCH_MAX_LEN ];
} match_struct;

    static score_t
compute_bonus_codepoint(int last_c, int c)
{
    if ( ( ( ((unsigned)(c) - 'A' < 26)  ||  ((unsigned)(c) - 'a' < 26) )  ||  ((unsigned)(c) - '0' < 10) )  || vim_iswordc(c))
    {
        if ( ((last_c) == '/') )
        {
            return  0.9 ;
        }
        if ( ((last_c) == '-' || (last_c) == '_' || (last_c) == ' ') )
        {
            return  0.8 ;
        }
        if ( ((last_c) == '.') )
        {
            return  0.6 ;
        }
        if ( vim_isupper(c)  &&  vim_islower(last_c) )
        {
            return  0.7 ;
        }
    }
    return 0;
}

    static void
setup_match_struct(match_struct *match, char_u *needle, char_u *haystack)
{
    int i = 0;
    char_u *p = needle;
    while (*p != NUL && i <  FUZZY_MATCH_MAX_LEN )
    {
        int c = mb_ptr2char(p);
        match->lower_needle[i++] =  vim_tolower(c) ;
         p += (*mb_ptr2len)(p) ;
    }
    match->needle_len = i;

    i = 0;
    p = haystack;
    int prev_c = '/';
    while (*p != NUL && i <  FUZZY_MATCH_MAX_LEN )
    {
        int c = mb_ptr2char(p);
        match->lower_haystack[i] =  vim_tolower(c) ;
        match->match_bonus[i] = compute_bonus_codepoint(prev_c, c);
        prev_c = c;
         p += (*mb_ptr2len)(p) ;
        i++;
    }
    match->haystack_len = i;
}

    static inline void
match_row(const match_struct *match, int row, score_t *curr_D, score_t *curr_M, const score_t *last_D, const score_t *last_M)
{
    int n = match->needle_len;
    int m = match->haystack_len;
    int i = row;

    const int *lower_needle = match->lower_needle;
    const int *lower_haystack = match->lower_haystack;
    const score_t *match_bonus = match->match_bonus;

    score_t prev_score =  (-INFINITY) ;
    score_t gap_score = i == n - 1 ?  -0.005  :  -0.01 ;

    score_t prev_M =  (-INFINITY) ;
    score_t prev_D =  (-INFINITY) ;

    for (int j = 0; j < m; j++)
    {
        if (lower_needle[i] == lower_haystack[j])
        {
            score_t score =  (-INFINITY) ;
            if (!i)
            {
                score = (j *  -0.005 ) + match_bonus[j];
            }
            else if (j)
            {
                score = MAX(prev_M + match_bonus[j], prev_D +  1.0 );
            }
            prev_D = last_D[j];
            prev_M = last_M[j];
            curr_D[j] = score;
            curr_M[j] = prev_score = MAX(score, prev_score + gap_score);
        }
        else
        {
            prev_D = last_D[j];
            prev_M = last_M[j];
            curr_D[j] =  (-INFINITY) ;
            curr_M[j] = prev_score = prev_score + gap_score;
        }
    }
}

    static score_t
match_positions(char_u *needle, char_u *haystack, int_u *positions)
{
    if (!needle || !haystack || !*needle)
    {
        return  (-INFINITY) ;
    }

    match_struct match;
    setup_match_struct(&match, needle, haystack);

    int n = match.needle_len;
    int m = match.haystack_len;

    if (m >  FUZZY_MATCH_MAX_LEN  || n > m)
    {
        return  (-INFINITY) ;
    }
    else if (n == m)
    {
        bool equal = true;
        for (int i = 0; i < n; i++)
        {
            if (match.lower_needle[i] != match.lower_haystack[i])
            {
                equal = false;
                break;
            }
        }
        if (equal)
        {
            if (positions)
            {
                for (int i = 0; i < n; i++)
                {
                    positions[i] = i;
                }
            }
            return  INFINITY ;
        }
    }

    if ((size_t)n > (SIZE_MAX / sizeof(score_t)) /  FUZZY_MATCH_MAX_LEN  / 2)
    {
        return  (-INFINITY) ;
    }

    score_t *block = (score_t*)alloc(sizeof(score_t) *  FUZZY_MATCH_MAX_LEN  * n * 2);
    if (!block)
    {
        return  (-INFINITY) ;
    }

    score_t (*D)[ FUZZY_MATCH_MAX_LEN ] = (score_t(*)[ FUZZY_MATCH_MAX_LEN ])block;
    score_t (*M)[ FUZZY_MATCH_MAX_LEN ] = (score_t(*)[ FUZZY_MATCH_MAX_LEN ])(block +  FUZZY_MATCH_MAX_LEN  * n);

    match_row(&match, 0, D[0], M[0], D[0], M[0]);
    for (int i = 1; i < n; i++)
    {
        match_row(&match, i, D[i], M[i], D[i - 1], M[i - 1]);
    }

    if (positions)
    {
        int match_required = 0;
        for (int i = n - 1, j = m - 1; i >= 0; i--)
        {
            for (; j >= 0; j--)
            {
                if (D[i][j] !=  (-INFINITY)  && (match_required || D[i][j] == M[i][j]))
                {
                    match_required = i && j &&
                        M[i][j] == D[i - 1][j - 1] +  1.0 ;
                    positions[i] = j--;
                    break;
                }
            }
        }
    }

    score_t result = M[n - 1][m - 1];
    vim_free(block);
    return result;
}

// ==================== getchar.c ====================

enum { MINIMAL_SIZE = 20 };

static buffheader_T redobuff = {{NULL, 0, {NUL}}, NULL, 0, 0, FALSE};
static buffheader_T old_redobuff = {{NULL, 0, {NUL}}, NULL, 0, 0, FALSE};
static buffheader_T recordbuff = {{NULL, 0, {NUL}}, NULL, 0, 0, FALSE};

static int typeahead_char = 0;

static int      block_redo = FALSE;

static int      KeyNoremap = 0;

enum { RM_YES = 0 };
enum { RM_NONE = 1 };
enum { RM_SCRIPT = 2 };
enum { RM_ABBR = 4 };
enum { RM_SIMPLIFIED = 8 };

static char_u   typebuf_init[ (5 * (MAXMAPLEN + 3)) ];
static char_u   noremapbuf_init[ (5 * (MAXMAPLEN + 3)) ];

static size_t   last_recorded_len = 0;

static int      read_readbuf(buffheader_T *buf, int advance);
static void     init_typebuf(void);
static void     may_sync_undo(void);
static void     free_typebuf(void);
static void     closescript(void);
static void     updatescript(int c);
static int      vgetorpeek(int);
static int      inchar(char_u *buf, int maxlen, long wait_time);

    static void
free_buff(buffheader_T *buf)
{
    buffblock_T *p;
    buffblock_T *np;

    for (p = buf->bh_first.b_next; p != NULL; p = np)
    {
        np = p->b_next;
        vim_free(p);
    }
    buf->bh_first.b_next = NULL;
    buf->bh_curr = NULL;
}

    static char_u *
get_buffcont(buffheader_T        *buffer, int                 dozero, size_t              *len)
{
    long_u          count = 0;
    char_u          *p = NULL;
    char_u          *p2;
    char_u          *str;
    buffblock_T *bp;
    size_t          i = 0;

    for (bp = buffer->bh_first.b_next; bp != NULL; bp = bp->b_next)
    {
        count += (long_u)bp->b_strlen;
    }

    if ((count > 0 || dozero) && (p = alloc(count + 1)) != NULL)
    {
        p2 = p;
        for (bp = buffer->bh_first.b_next; bp != NULL; bp = bp->b_next)
        {
            for (str = bp->b_str; *str; )
            {
                *p2++ = *str++;
            }
        }
        *p2 = NUL;
        i = (size_t)(p2 - p);
    }

    if (len != NULL)
    {
        *len = i;
    }

    return p;
}

    static char_u *
get_recorded(void)
{
    char_u      *p;
    size_t      len;

    p = get_buffcont(&recordbuff, TRUE, &len);
    if (p == NULL)
    {
        return NULL;
    }

    free_buff(&recordbuff);

    if (len >= last_recorded_len)
    {
        len -= last_recorded_len;
        p[len] = NUL;
    }

    if (len > 0 && restart_edit != 0 && p[len - 1] == Ctrl_O)
    {
        p[len - 1] = NUL;
    }

    return (p);
}

    static string_T
get_inserted(void)
{
    size_t len = 0;
    char_u *str = get_buffcont(&redobuff, FALSE, &len);
    string_T ret = { str, len };
    return ret;
}

    static void
add_buff(buffheader_T        *buf, char_u              *s, long                slen)
{
    if (slen < 0)
    {
        slen = (long) strlen((char *)(s)) ;
    }
    if (slen == 0)
    {
        return;
    }

    if (buf->bh_first.b_next == NULL)
    {
        buf->bh_curr = &(buf->bh_first);
        buf->bh_create_newblock = TRUE;
    }
    else if (buf->bh_curr == NULL)
    {
        iemsg(e_add_to_internal_buffer_that_was_already_read_from);
        return;
    }
    else if (buf->bh_index != 0)
    {
         memmove((char *)(buf->bh_first.b_next->b_str), (char *)(buf->bh_first.b_next->b_str + buf->bh_index), (buf->bh_first.b_next->b_strlen - buf->bh_index) + 1) ;
        buf->bh_first.b_next->b_strlen -= buf->bh_index;
        buf->bh_space += buf->bh_index;
    }
    buf->bh_index = 0;

    if (!buf->bh_create_newblock && buf->bh_space >= (int)slen)
    {
        vim_strncpy(buf->bh_curr->b_str + buf->bh_curr->b_strlen, s, (size_t)slen);
        buf->bh_curr->b_strlen += slen;
        buf->bh_space -= slen;
    }
    else
    {
        long_u      len;
        buffblock_T *p;

        if (slen < MINIMAL_SIZE)
        {
            len = MINIMAL_SIZE;
        }
        else
        {
            len = slen;
        }
        p = alloc(offsetof(buffblock_T, b_str) + len + 1);
        if (p == NULL)
        {
            return;
        }
        vim_strncpy(p->b_str, s, (size_t)slen);
        p->b_strlen = slen;
        buf->bh_space = (int)(len - slen);
        buf->bh_create_newblock = FALSE;

        p->b_next = buf->bh_curr->b_next;
        buf->bh_curr->b_next = p;
        buf->bh_curr = p;
    }
}

    static void
delete_buff_tail(buffheader_T *buf, int slen)
{
    if (buf->bh_curr == NULL)
    {
        return;
    }
    if (buf->bh_curr->b_strlen < (size_t)slen)
    {
        return;
    }

    buf->bh_curr->b_str[buf->bh_curr->b_strlen - (size_t)slen] = NUL;
    buf->bh_curr->b_strlen -= slen;
    buf->bh_space += slen;
}

    static void
add_num_buff(buffheader_T *buf, long n)
{
    char_u      number[32];
    int         numberlen;

    numberlen = vim_snprintf((char *)number, sizeof(number), "%ld", n);
    add_buff(buf, number, (long)numberlen);
}

    static void
add_char_buff(buffheader_T *buf, int c)
{
    char_u      bytes[MB_MAXBYTES + 1];
    int         len;
    int         i;
    char_u      temp[4];
    long        templen;

    if ( ((c) < 0) )
    {
        len = 1;
    }
    else
    {
        len = (*mb_char2bytes)(c, bytes);
    }
    for (i = 0; i < len; ++i)
    {
        if (! ((c) < 0) )
        {
            c = bytes[i];
        }

        if ( ((c) < 0)  || c ==  (0x80)  || c == NUL)
        {
            temp[0] =  (0x80) ;
            temp[1] =  ((c) ==  (0x80)  ? KS_SPECIAL : (c) == NUL ? KS_ZERO :  ((-(c)) & 0xff) ) ;
            temp[2] =  (((c) ==  (0x80)  || (c) == NUL) ?  ('X')  :  (((unsigned)(-(c)) >> 8) & 0xff) ) ;
            temp[3] = NUL;
            templen = 3;
        }
        else
        {
            temp[0] = c;
            temp[1] = NUL;
            templen = 1;
        }
        add_buff(buf, temp, templen);
    }
}

static buffheader_T readbuf1 = {{NULL, 0, {NUL}}, NULL, 0, 0, FALSE};

static buffheader_T readbuf2 = {{NULL, 0, {NUL}}, NULL, 0, 0, FALSE};

    static int
read_readbuffers(int advance)
{
    int c;

    c = read_readbuf(&readbuf1, advance);
    if (c == NUL)
    {
        c = read_readbuf(&readbuf2, advance);
    }
    return c;
}

    static int
read_readbuf(buffheader_T *buf, int advance)
{
    char_u      c;
    buffblock_T *curr;

    if (buf->bh_first.b_next == NULL)
    {
        return NUL;
    }

    curr = buf->bh_first.b_next;
    c = curr->b_str[buf->bh_index];

    if (advance)
    {
        if (curr->b_str[++buf->bh_index] == NUL)
        {
            buf->bh_first.b_next = curr->b_next;
            vim_free(curr);
            buf->bh_index = 0;
        }
    }
    return c;
}

    static void
start_stuff(void)
{
    if (readbuf1.bh_first.b_next != NULL)
    {
        readbuf1.bh_curr = &(readbuf1.bh_first);
        readbuf1.bh_create_newblock = TRUE;
    }
    if (readbuf2.bh_first.b_next != NULL)
    {
        readbuf2.bh_curr = &(readbuf2.bh_first);
        readbuf2.bh_create_newblock = TRUE;
    }
}

    static int
stuff_empty(void)
{
    return (readbuf1.bh_first.b_next == NULL && readbuf2.bh_first.b_next == NULL);
}

    static void
typeahead_noflush(int c)
{
    typeahead_char = c;
}

    static void
flush_buffers(flush_buffers_T flush_typeahead)
{
    init_typebuf();

    start_stuff();
    while (read_readbuffers(TRUE) != NUL)
    {
        ;
    }

    if (flush_typeahead == FLUSH_MINIMAL)
    {
        if (typebuf.tb_off + typebuf.tb_maplen >= typebuf.tb_buflen)
        {
            typebuf.tb_off = MAXMAPLEN;
            typebuf.tb_len = 0;
        }
        else
        {
            typebuf.tb_off += typebuf.tb_maplen;
            typebuf.tb_len -= typebuf.tb_maplen;
        }
    }
    else
    {
        if (flush_typeahead == FLUSH_INPUT)
        {
            while (inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 10L) != 0)
            {
                ;
            }
        }
        typebuf.tb_off = MAXMAPLEN;
        typebuf.tb_len = 0;
    }
    typebuf.tb_maplen = 0;
    typebuf.tb_silent = 0;
    cmd_silent = FALSE;
    typebuf.tb_no_abbr_cnt = 0;
    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }
}

    static void
ResetRedobuff(void)
{
    if (block_redo)
    {
        return;
    }

    free_buff(&old_redobuff);
    old_redobuff = redobuff;
    redobuff.bh_first.b_next = NULL;
}

    static void
CancelRedo(void)
{
    if (block_redo)
    {
        return;
    }

    free_buff(&redobuff);
    redobuff = old_redobuff;
    old_redobuff.bh_first.b_next = NULL;
    start_stuff();
    while (read_readbuffers(TRUE) != NUL)
    {
        ;
    }
}

    static void
saveRedobuff(save_redo_T *save_redo)
{
    char_u      *s;
    size_t      slen;

    save_redo->sr_redobuff = redobuff;
    redobuff.bh_first.b_next = NULL;
    save_redo->sr_old_redobuff = old_redobuff;
    old_redobuff.bh_first.b_next = NULL;

    s = get_buffcont(&save_redo->sr_redobuff, FALSE, &slen);
    if (s == NULL)
    {
        return;
    }

    add_buff(&redobuff, s, (long)slen);
    vim_free(s);
}

    static void
restoreRedobuff(save_redo_T *save_redo)
{
    free_buff(&redobuff);
    redobuff = save_redo->sr_redobuff;
    free_buff(&old_redobuff);
    old_redobuff = save_redo->sr_old_redobuff;
}

    static void
AppendToRedobuff(char_u *s)
{
    if (!block_redo)
    {
        add_buff(&redobuff, s, -1L);
    }
}

    static void
AppendToRedobuffLit(char_u      *str, int         len)
{
    char_u      *s = str;
    int         c;
    char_u      *start;

    if (block_redo)
    {
        return;
    }

    while (len < 0 ? *s != NUL : s - str < len)
    {
        start = s;
        while (*s >= ' ' && *s < DEL && (len < 0 || s - str < len))
        {
            ++s;
        }

        if (*s == NUL && (s[-1] == '0' || s[-1] == '^'))
        {
            --s;
        }
        if (s > start)
        {
            add_buff(&redobuff, start, (long)(s - start));
        }

        if (*s == NUL || (len >= 0 && s - str >= len))
        {
            break;
        }

        if (has_mbyte)
        {
            c = mb_cptr2char_adv(&s);
        }
        else
        {
            c = *s++;
        }
        if (c < ' ' || c == DEL || (*s == NUL && (c == '0' || c == '^')))
        {
            add_char_buff(&redobuff, Ctrl_V);
        }

        if (*s == NUL && c == '0')
        {
            add_buff(&redobuff, (char_u *)"048", 3L);
        }
        else
        {
            add_char_buff(&redobuff, c);
        }
    }
}

    static void
AppendToRedobuffSpec(char_u *s)
{
    if (block_redo)
    {
        return;
    }

    while (*s != NUL)
    {
        if (*s ==  (0x80)  && s[1] != NUL && s[2] != NUL)
        {
            add_buff(&redobuff, s, 3L);
            s += 3;
        }
        else
        {
            add_char_buff(&redobuff, mb_cptr2char_adv(&s));
        }
    }
}

    static void
AppendCharToRedobuff(int c)
{
    if (!block_redo)
    {
        add_char_buff(&redobuff, c);
    }
}

    static void
AppendNumberToRedobuff(long n)
{
    if (!block_redo)
    {
        add_num_buff(&redobuff, n);
    }
}

    static void
stuffReadbuff(char_u *s)
{
    add_buff(&readbuf1, s, -1L);
}

    static void
stuffRedoReadbuff(char_u *s)
{
    add_buff(&readbuf2, s, -1L);
}

    static void
stuffReadbuffLen(char_u *s, long len)
{
    add_buff(&readbuf1, s, len);
}

    static void
stuffcharReadbuff(int c)
{
    add_char_buff(&readbuf1, c);
}

    static void
stuffnumReadbuff(long n)
{
    add_num_buff(&readbuf1, n);
}

    static void
stuffescaped(char_u *arg, int literally)
{
    int         c;
    char_u      *start;

    while (*arg != NUL)
    {
        start = arg;
        while ((*arg >= ' ' && *arg < DEL) || (*arg ==  (0x80)  && !literally))
        {
            ++arg;
        }
        if (arg > start)
        {
            stuffReadbuffLen(start, (long)(arg - start));
        }

        if (*arg != NUL)
        {
            if (has_mbyte)
            {
                c = mb_cptr2char_adv(&arg);
            }
            else
            {
                c = *arg++;
            }
            if (literally && ((c < ' ' && c != TAB) || c == DEL))
            {
                stuffcharReadbuff(Ctrl_V);
            }
            stuffcharReadbuff(c);
        }
    }
}

    static int
read_redo(int init, int old_redo)
{
    static buffblock_T  *bp;
    static char_u       *p;
    int                 c;
    int                 n;
    char_u              buf[MB_MAXBYTES + 1];
    int                 i;

    if (init)
    {
        if (old_redo)
        {
            bp = old_redobuff.bh_first.b_next;
        }
        else
        {
            bp = redobuff.bh_first.b_next;
        }
        if (bp == NULL)
        {
            return FAIL;
        }
        p = bp->b_str;
        return OK;
    }
    if ((c = *p) != NUL)
    {
        if (has_mbyte && (c !=  (0x80)  || p[1] == KS_SPECIAL))
        {
            n =  (((c) < 0 || (c) > 255) ? 1 : mb_bytelen_tab[c]) ;
        }
        else
        {
            n = 1;
        }
        for (i = 0; ; ++i)
        {
            if (c ==  (0x80) )
            {
                c =  ((p[1]) == KS_SPECIAL ?  (0x80)  : (p[1]) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((p[1]) + ((int)(p[2]) << 8))) ) ;
                p += 2;
            }
            if (*++p == NUL && bp->b_next != NULL)
            {
                bp = bp->b_next;
                p = bp->b_str;
            }
            buf[i] = c;
            if (i == n - 1)
            {
                if (n != 1)
                {
                    c = (*mb_ptr2char)(buf);
                }
                break;
            }
            c = *p;
            if (c == NUL)
            {
                break;
            }
        }
    }

    return c;
}

    static void
copy_redo(int old_redo)
{
    int     c;

    while ((c = read_redo(FALSE, old_redo)) != NUL)
    {
        add_char_buff(&readbuf2, c);
    }
}

    static int
start_redo(long count, int old_redo)
{
    int     c;

    if (read_redo(TRUE, old_redo) == FAIL)
    {
        return FAIL;
    }

    c = read_redo(FALSE, old_redo);

    if (c == '"')
    {
        add_buff(&readbuf2, (char_u *)"\"", 1L);
        c = read_redo(FALSE, old_redo);

        if (c >= '1' && c < '9')
        {
            ++c;
        }
        add_char_buff(&readbuf2, c);

        if (c == '=')
        {
            add_char_buff(&readbuf2, CAR);
            cmd_silent = TRUE;
        }

        c = read_redo(FALSE, old_redo);
    }

    if (c == 'v')
    {
        VIsual = curwin->w_cursor;
        VIsual_active = TRUE;
        VIsual_select = FALSE;
        VIsual_reselect = TRUE;
        redo_VIsual_busy = TRUE;
        c = read_redo(FALSE, old_redo);
    }

    if (count)
    {
        while ( ((unsigned)(c) - '0' < 10) )
        {
            c = read_redo(FALSE, old_redo);
        }
        add_num_buff(&readbuf2, count);
    }

    add_char_buff(&readbuf2, c);
    copy_redo(old_redo);
    return OK;
}

    static int
start_redo_ins(void)
{
    int     c;

    if (read_redo(TRUE, FALSE) == FAIL)
    {
        return FAIL;
    }
    start_stuff();

    while ((c = read_redo(FALSE, FALSE)) != NUL)
    {
        if (vim_strchr((char_u *)"AaIiRrOo", c) != NULL)
        {
            if (c == 'O' || c == 'o')
            {
                add_buff(&readbuf2,  (char_u *)"\012" , -1L);
            }
            break;
        }
    }

    copy_redo(FALSE);
    block_redo = TRUE;
    return OK;
}

    static void
stop_redo_ins(void)
{
    block_redo = FALSE;
}

    static void
init_typebuf(void)
{
    if (typebuf.tb_buf != NULL)
    {
        return;
    }

    typebuf.tb_buf = typebuf_init;
    typebuf.tb_noremap = noremapbuf_init;
    typebuf.tb_buflen =  (5 * (MAXMAPLEN + 3)) ;
    typebuf.tb_len = 0;
    typebuf.tb_off = MAXMAPLEN + 4;
    typebuf.tb_change_cnt = 1;
}

    static int
noremap_keys(void)
{
    return KeyNoremap & (RM_NONE|RM_SCRIPT);
}

    static int
ins_typebuf(char_u      *str, int         noremap, int         offset, int         nottyped, int         silent)
{
    char_u *s1;
    char_u *s2;
    int         newlen;
    int         addlen;
    int         i;
    int         newoff;
    int         val;
    int         nrm;

    init_typebuf();
    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }
    state_no_longer_safe("ins_typebuf()");

    addlen = (int) strlen((char *)(str)) ;

    if (offset == 0 && addlen <= typebuf.tb_off)
    {
        typebuf.tb_off -= addlen;
         memmove((char *)(typebuf.tb_buf + typebuf.tb_off), (char *)(str), (size_t)addlen) ;
    }
    else if (typebuf.tb_len == 0 && typebuf.tb_buflen >= addlen + 3 * (MAXMAPLEN + 4))
    {
        typebuf.tb_off = (typebuf.tb_buflen - addlen - 3 * (MAXMAPLEN + 4)) / 2;
         memmove((char *)(typebuf.tb_buf + typebuf.tb_off), (char *)(str), (size_t)addlen) ;
    }
    else
    {
        int extra;

        newoff = MAXMAPLEN + 4;
        extra = addlen + newoff + 4 * (MAXMAPLEN + 4);
        if (typebuf.tb_len > 2147483647 - extra)
        {
            emsg(_(e_command_too_complex));
            setcursor();
            return FAIL;
        }
        newlen = typebuf.tb_len + extra;
        s1 = alloc(newlen);
        if (s1 == NULL)
        {
            return FAIL;
        }
        s2 = alloc(newlen);
        if (s2 == NULL)
        {
            vim_free(s1);
            return FAIL;
        }
        typebuf.tb_buflen = newlen;

         memmove((char *)(s1 + newoff), (char *)(typebuf.tb_buf + typebuf.tb_off), (size_t)offset) ;
         memmove((char *)(s1 + newoff + offset), (char *)(str), (size_t)addlen) ;
         memmove((char *)(s1 + newoff + offset + addlen), (char *)(typebuf.tb_buf + typebuf.tb_off + offset), (size_t)(typebuf.tb_len - offset + 1)) ;
        if (typebuf.tb_buf != typebuf_init)
        {
            vim_free(typebuf.tb_buf);
        }
        typebuf.tb_buf = s1;

         memmove((char *)(s2 + newoff), (char *)(typebuf.tb_noremap + typebuf.tb_off), (size_t)offset) ;
         memmove((char *)(s2 + newoff + offset + addlen), (char *)(typebuf.tb_noremap + typebuf.tb_off + offset), (size_t)(typebuf.tb_len - offset)) ;
        if (typebuf.tb_noremap != noremapbuf_init)
        {
            vim_free(typebuf.tb_noremap);
        }
        typebuf.tb_noremap = s2;

        typebuf.tb_off = newoff;
    }
    typebuf.tb_len += addlen;

    if (noremap ==  (-2) )
    {
        val = RM_SCRIPT;
    }
    else if (noremap ==  (-3) )
    {
        val = RM_ABBR;
    }
    else
    {
        val = RM_NONE;
    }

    if (noremap ==  (-3) )
    {
        nrm = 1;
    }
    else if (noremap < 0)
    {
        nrm = addlen;
    }
    else
    {
        nrm = noremap;
    }
    for (i = 0; i < addlen; ++i)
    {
        typebuf.tb_noremap[typebuf.tb_off + i + offset] =
                                                  (--nrm >= 0) ? val : RM_YES;
    }

    if (nottyped || typebuf.tb_maplen > offset)
    {
        typebuf.tb_maplen += addlen;
    }
    if (silent || typebuf.tb_silent > offset)
    {
        typebuf.tb_silent += addlen;
        cmd_silent = TRUE;
    }
    if (typebuf.tb_no_abbr_cnt && offset == 0)
    {
        typebuf.tb_no_abbr_cnt += addlen;
    }

    return OK;
}

    static int
ins_char_typebuf(int c, int modifiers)
{
    char_u      buf[MB_MAXBYTES * 3 + 4];
    int         len = special_to_buf(c, modifiers, TRUE, buf);

    buf[len] = NUL;
    (void)ins_typebuf(buf, KeyNoremap, 0, !KeyTyped, cmd_silent);
    return len;
}

    static int
typebuf_changed(int         tb_change_cnt)
{
    return (tb_change_cnt != 0 && (typebuf.tb_change_cnt != tb_change_cnt));
}

    static int
typebuf_typed(void)
{
    return typebuf.tb_maplen == 0;
}

    static int
typebuf_maplen(void)
{
    return typebuf.tb_maplen;
}

    static void
del_typebuf(int len, int offset)
{
    int     i;

    if (len == 0)
    {
        return;
    }

    typebuf.tb_len -= len;

    if (offset == 0 && typebuf.tb_buflen - (typebuf.tb_off + len) >= 3 * MAXMAPLEN + 3)
    {
        typebuf.tb_off += len;
    }
    else
    {
        i = typebuf.tb_off + offset;
        if (typebuf.tb_off > MAXMAPLEN)
        {
             memmove((char *)(typebuf.tb_buf + MAXMAPLEN), (char *)(typebuf.tb_buf + typebuf.tb_off), (size_t)offset) ;
             memmove((char *)(typebuf.tb_noremap + MAXMAPLEN), (char *)(typebuf.tb_noremap + typebuf.tb_off), (size_t)offset) ;
            typebuf.tb_off = MAXMAPLEN;
        }
         memmove((char *)(typebuf.tb_buf + typebuf.tb_off + offset), (char *)(typebuf.tb_buf + i + len), (size_t)(typebuf.tb_len - offset + 1)) ;
         memmove((char *)(typebuf.tb_noremap + typebuf.tb_off + offset), (char *)(typebuf.tb_noremap + i + len), (size_t)(typebuf.tb_len - offset)) ;
    }

    if (typebuf.tb_maplen > offset)
    {
        if (typebuf.tb_maplen < offset + len)
        {
            typebuf.tb_maplen = offset;
        }
        else
        {
            typebuf.tb_maplen -= len;
        }
    }
    if (typebuf.tb_silent > offset)
    {
        if (typebuf.tb_silent < offset + len)
        {
            typebuf.tb_silent = offset;
        }
        else
        {
            typebuf.tb_silent -= len;
        }
    }
    if (typebuf.tb_no_abbr_cnt > offset)
    {
        if (typebuf.tb_no_abbr_cnt < offset + len)
        {
            typebuf.tb_no_abbr_cnt = offset;
        }
        else
        {
            typebuf.tb_no_abbr_cnt -= len;
        }
    }

    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }
}

typedef struct
{
    char_u      buf[MB_MAXBYTES * 3 + 4];
    int         prev_c;
    size_t      buflen;
    unsigned    pending_special;
    unsigned    pending_mbyte;
} gotchars_state_T;

    static int
gotchars_add_byte(gotchars_state_T *state, char_u byte)
{
    int         c = state->buf[state->buflen++] = byte;
    int         retval = FALSE;
    int         in_special = state->pending_special > 0;
    int         in_mbyte = state->pending_mbyte > 0;

    if (in_special)
    {
        state->pending_special--;
    }
    else if (c ==  (0x80) )
    {
        state->pending_special = 2;
    }

    if (state->pending_special > 0)
    {
        goto ret_false;
    }

    if (in_mbyte)
    {
        state->pending_mbyte--;
    }
    else
    {
        if (in_special)
        {
            if (state->prev_c == KS_MODIFIER)
            {
                goto ret_false;
            }
            c =  ((state->prev_c) == KS_SPECIAL ?  (0x80)  : (state->prev_c) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((state->prev_c) + ((int)(c) << 8))) ) ;
            if (c ==   (-((KS_EXTRA) + ((int)(KE_FOCUSGAINED) << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_FOCUSLOST) << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_COMPLETE_DELAY) << 8)))  )
            {
                state->buflen = 0;
            }
        }
        state->pending_mbyte =  (((c) < 0 || (c) > 255) ? 1 : mb_bytelen_tab[c])  - 1;
    }

    if (state->pending_mbyte > 0)
    {
        goto ret_false;
    }

    retval = TRUE;
ret_false:
    state->prev_c = c;
    return retval;
}

    static void
gotchars(char_u *chars, int len)
{
    char_u              *s = chars;
    size_t              i;
    int                 todo = len;
    static gotchars_state_T state;

    while (todo-- > 0)
    {
        if (!gotchars_add_byte(&state, *s++))
        {
            continue;
        }

        for (i = 0; i < state.buflen; ++i)
        {
            updatescript(state.buf[i]);
        }

        if (reg_recording != 0)
        {
            state.buf[state.buflen] = NUL;
            add_buff(&recordbuff, state.buf, (long)state.buflen);
            last_recorded_len += state.buflen;
        }
        state.buflen = 0;
    }

    may_sync_undo();

    ++maptick;
}

    static void
gotchars_ignore(void)
{
    char_u nop_buf[3] = {  (0x80) , KS_EXTRA, KE_IGNORE };
    gotchars(nop_buf, 3);
}

    static void
ungetchars(int len)
{
    if (reg_recording == 0)
    {
        return;
    }

    delete_buff_tail(&recordbuff, len);
    last_recorded_len -= len;
}

    static void
may_sync_undo(void)
{
    if ((!(State & (MODE_INSERT | MODE_CMDLINE)) || arrow_used) && scriptin[curscript] == NULL)
    {
        u_sync(FALSE);
    }
}

    static int
alloc_typebuf(void)
{
    typebuf.tb_buf = alloc( (5 * (MAXMAPLEN + 3)) );
    typebuf.tb_noremap = alloc( (5 * (MAXMAPLEN + 3)) );
    if (typebuf.tb_buf == NULL || typebuf.tb_noremap == NULL)
    {
        free_typebuf();
        return FAIL;
    }
    typebuf.tb_buflen =  (5 * (MAXMAPLEN + 3)) ;
    typebuf.tb_off = MAXMAPLEN + 4;
    typebuf.tb_len = 0;
    typebuf.tb_maplen = 0;
    typebuf.tb_silent = 0;
    typebuf.tb_no_abbr_cnt = 0;
    if (++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }
    return OK;
}

    static void
free_typebuf(void)
{
    if (typebuf.tb_buf == typebuf_init)
    {
        internal_error("Free typebuf 1");
    }
    else
    {
         vim_free(typebuf.tb_buf);
         (typebuf.tb_buf) = NULL;
    }
    if (typebuf.tb_noremap == noremapbuf_init)
    {
        internal_error("Free typebuf 2");
    }
    else
    {
         vim_free(typebuf.tb_noremap);
         (typebuf.tb_noremap) = NULL;
    }
}

static typebuf_T saved_typebuf[NSCRIPT];

    static int
save_typebuf(void)
{
    init_typebuf();
    saved_typebuf[curscript] = typebuf;
    if (alloc_typebuf() == FAIL)
    {
        closescript();
        return FAIL;
    }
    return OK;
}

static int old_char = -1;
static int old_mod_mask;
static int old_mouse_row;
static int old_mouse_col;
static int old_KeyStuffed;

static int can_get_old_char(void)
{
    return old_char != -1 && (old_KeyStuffed || stuff_empty());
}

    static void
save_typeahead(tasave_T *tp)
{
    tp->save_typebuf = typebuf;
    tp->typebuf_valid = (alloc_typebuf() == OK);
    if (!tp->typebuf_valid)
    {
        typebuf = tp->save_typebuf;
    }

    tp->old_char = old_char;
    tp->old_mod_mask = old_mod_mask;
    old_char = -1;

    tp->save_readbuf1 = readbuf1;
    readbuf1.bh_first.b_next = NULL;
    tp->save_readbuf2 = readbuf2;
    readbuf2.bh_first.b_next = NULL;
    tp->save_inputbuf = get_input_buf();
}

    static void
restore_typeahead(tasave_T *tp, int overwrite  __attribute__((unused)) )
{
    if (tp->typebuf_valid)
    {
        free_typebuf();
        typebuf = tp->save_typebuf;
    }

    old_char = tp->old_char;
    old_mod_mask = tp->old_mod_mask;

    free_buff(&readbuf1);
    readbuf1 = tp->save_readbuf1;
    free_buff(&readbuf2);
    readbuf2 = tp->save_readbuf2;
    set_input_buf(tp->save_inputbuf, overwrite);
}

    static void
openscript(char_u      *name, int         directly)
{
    if (curscript + 1 == NSCRIPT)
    {
        emsg(_(e_scripts_nested_too_deep));
        return;
    }

    if (check_secure())
    {
        return;
    }

    if (scriptin[curscript] != NULL)
    {
        ++curscript;
    }
    expand_env(name, NameBuff,  PATH_MAX );
    if ((scriptin[curscript] =  fopen(((char *)NameBuff), ( "r" )) ) == NULL)
    {
        semsg(_(e_cant_open_file_str), name);
        if (curscript)
        {
            --curscript;
        }
        return;
    }
    if (save_typebuf() == FAIL)
    {
        return;
    }

    if (directly)
    {
        oparg_T oa;
        int     oldcurscript;
        int     save_State = State;
        int     save_restart_edit = restart_edit;
        int     save_insertmode = p_im;
        int     save_finish_op = finish_op;
        int     save_msg_scroll = msg_scroll;

        State = MODE_NORMAL;
        msg_scroll = FALSE;
        restart_edit = 0;
        p_im = FALSE;
        clear_oparg(&oa);
        finish_op = FALSE;

        oldcurscript = curscript;
        do
        {
            update_topline_cursor();
            normal_cmd(&oa, FALSE);
            (void)vpeekc();
        }
        while (scriptin[oldcurscript] != NULL)
            ;

        State = save_State;
        msg_scroll = save_msg_scroll;
        restart_edit = save_restart_edit;
        p_im = save_insertmode;
        finish_op = save_finish_op;
    }
}

    static void
closescript(void)
{
    free_typebuf();
    typebuf = saved_typebuf[curscript];

    fclose(scriptin[curscript]);
    scriptin[curscript] = NULL;
    if (curscript > 0)
    {
        --curscript;
    }
}

    static int
using_script(void)
{
    return scriptin[curscript] != NULL;
}

    static void
before_blocking(void)
{
    term_set_sync_output(TERM_SYNC_OUTPUT_FLUSH);

    updatescript(0);
}

    static void
updatescript(int c)
{
    static int      count = 0;

    if (c && scriptout)
    {
        putc(c, scriptout);
    }
    if (c == 0 || (p_uc > 0 && ++count >= p_uc))
    {
        ml_sync_all(c == 0, TRUE);
        count = 0;
    }
}

    static int
merge_modifyOtherKeys(int c_arg, int *modifiers)
{
    int c = c_arg;

    if (*modifiers & MOD_MASK_CTRL)
    {
        if ((c >= '`' && c <= 0x7f) || (c >= '@' && c <= '_'))
        {
            c &= 0x1f;
            if (c == NUL)
            {
                c =   (-((KS_ZERO) + ((int)( ('X') ) << 8)))  ;
            }
        }
        else if (c == '6')
        {
            c = 0x1e;
        }
        if (c != c_arg)
        {
            *modifiers &= ~MOD_MASK_CTRL;
        }
    }

    if ((*modifiers & (MOD_MASK_META | MOD_MASK_ALT)) && c >= 0 && c <= 127)
    {
        if ((*modifiers & MOD_MASK_SHIFT) && c >= 'a' && c <= 'z')
        {
            c += 'a' - 'A';
            *modifiers &= ~MOD_MASK_SHIFT;
        }
        c += 0x80;
        *modifiers &= ~(MOD_MASK_META | MOD_MASK_ALT);
    }

    return c;
}

    static void
add_byte_to_showcmd(char_u byte)
{
    static gotchars_state_T state;
    char_u      *ptr;
    int         modifiers = 0;
    int         c = NUL;

    if (!p_sc || msg_silent != 0)
    {
        return;
    }

    if (!gotchars_add_byte(&state, byte))
    {
        return;
    }

    state.buf[state.buflen] = NUL;
    state.buflen = 0;

    ptr = state.buf;
    if (ptr[0] ==  (0x80)  && ptr[1] == KS_MODIFIER && ptr[2] != NUL)
    {
        modifiers = ptr[2];
        ptr += 3;
    }

    if (*ptr != NUL)
    {
        char_u          *mb_ptr = mb_unescape(&ptr);

        c = mb_ptr != NULL ? (*mb_ptr2char)(mb_ptr) : *ptr++;
        if (c <= 0x7f)
        {
            int         modifiers_after = modifiers;
            int         mod_c = merge_modifyOtherKeys(c, &modifiers_after);

            if (modifiers_after == 0)
            {
                modifiers = 0;
                c = mod_c;
            }
        }
    }

    if (modifiers != 0)
    {
        add_to_showcmd( (0x80) );
        add_to_showcmd(KS_MODIFIER);
        add_to_showcmd(modifiers);
    }
    if (c != NUL)
    {
        add_to_showcmd(c);
    }
    while (*ptr != NUL)
    {
        add_to_showcmd(*ptr++);
    }
}

    static int
vgetc(void)
{
    int c;
    int c2;
    int         n;
    char_u      buf[MB_MAXBYTES + 1];
    int         i;

    if (can_get_old_char())
    {
        c = old_char;
        old_char = -1;
        mod_mask = old_mod_mask;
        mouse_row = old_mouse_row;
        mouse_col = old_mouse_col;
    }
    else
    {
        static size_t   last_vgetc_recorded_len = 0;

        mod_mask = 0;
        vgetc_mod_mask = 0;
        vgetc_char = 0;

        last_recorded_len -= last_vgetc_recorded_len;

        for (;;)
        {
            int did_inc = FALSE;

            if (mod_mask)
            {
                ++no_mapping;
                ++allow_keys;
                did_inc = TRUE;
            }
            c = vgetorpeek(TRUE);
            if (did_inc)
            {
                --no_mapping;
                --allow_keys;
            }

            if (c ==  (0x80) )
            {
                int         save_allow_keys = allow_keys;

                ++no_mapping;
                allow_keys = 0;
                c2 = vgetorpeek(TRUE);
                c = vgetorpeek(TRUE);
                --no_mapping;
                allow_keys = save_allow_keys;
                if (c2 == KS_MODIFIER)
                {
                    mod_mask = c;
                    continue;
                }
                c =  ((c2) == KS_SPECIAL ?  (0x80)  : (c2) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((c2) + ((int)(c) << 8))) ) ;

                if (allow_osc_key == 0 && c ==   (-((KS_EXTRA) + ((int)(KE_OSC) << 8)))  )
                {
                    continue;
                }

                if (c ==   (-((KS_EXTRA) + ((int)(KE_ESC) << 8)))  )
                {
                    c = ESC;
                }

            }

            if (has_mbyte && (n =  (((c) < 0 || (c) > 255) ? 1 : mb_bytelen_tab[c]) ) > 1)
            {
                ++no_mapping;
                buf[0] = c;
                for (i = 1; i < n; ++i)
                {
                    buf[i] = vgetorpeek(TRUE);
                    if (buf[i] ==  (0x80) )
                    {
                        c = vgetorpeek(TRUE);
                        if (vgetorpeek(TRUE) == KE_CSI && c == KS_EXTRA)
                        {
                            buf[i] = CSI;
                        }
                    }
                }
                --no_mapping;
                c = (*mb_ptr2char)(buf);
            }

            if (vgetc_char == 0)
            {
                vgetc_mod_mask = mod_mask;
                vgetc_char = c;
            }

            switch (c)
            {
                case   (-(('K') + ((int)('6') << 8)))  :
                    c = '+';
                    break;
                case   (-(('K') + ((int)('7') << 8)))  :
                    c = '-';
                    break;
                case   (-(('K') + ((int)('8') << 8)))  :
                    c = '/';
                    break;
                case   (-(('K') + ((int)('9') << 8)))  :
                    c = '*';
                    break;
                case   (-(('K') + ((int)('A') << 8)))  :
                    c = CAR;
                    break;
                case   (-(('K') + ((int)('B') << 8)))  :
                                c = '.';
                                break;
                case   (-(('K') + ((int)('C') << 8)))  :
                    c = '0';
                    break;
                case   (-(('K') + ((int)('D') << 8)))  :
                    c = '1';
                    break;
                case   (-(('K') + ((int)('E') << 8)))  :
                    c = '2';
                    break;
                case   (-(('K') + ((int)('F') << 8)))  :
                    c = '3';
                    break;
                case   (-(('K') + ((int)('G') << 8)))  :
                    c = '4';
                    break;
                case   (-(('K') + ((int)('H') << 8)))  :
                    c = '5';
                    break;
                case   (-(('K') + ((int)('I') << 8)))  :
                    c = '6';
                    break;
                case   (-(('K') + ((int)('J') << 8)))  :
                    c = '7';
                    break;
                case   (-(('K') + ((int)('K') << 8)))  :
                    c = '8';
                    break;
                case   (-(('K') + ((int)('L') << 8)))  :
                    c = '9';
                    break;

                case   (-((KS_EXTRA) + ((int)(KE_XHOME) << 8)))  :
                case   (-((KS_EXTRA) + ((int)(KE_ZHOME) << 8)))  :
                    if (mod_mask == MOD_MASK_SHIFT)
                                {
                                    c =   (-(('#') + ((int)('2') << 8)))  ;
                                    mod_mask = 0;
                                }
                                else if (mod_mask == MOD_MASK_CTRL)
                                {
                                    c =   (-((KS_EXTRA) + ((int)(KE_C_HOME) << 8)))  ;
                                    mod_mask = 0;
                                }
                                else
                                {
                                    c =   (-(('k') + ((int)('h') << 8)))  ;
                                }
                                break;
                case   (-((KS_EXTRA) + ((int)(KE_XEND) << 8)))  :
                case   (-((KS_EXTRA) + ((int)(KE_ZEND) << 8)))  :
                    if (mod_mask == MOD_MASK_SHIFT)
                                {
                                    c =   (-(('*') + ((int)('7') << 8)))  ;
                                    mod_mask = 0;
                                }
                                else if (mod_mask == MOD_MASK_CTRL)
                                {
                                    c =   (-((KS_EXTRA) + ((int)(KE_C_END) << 8)))  ;
                                    mod_mask = 0;
                                }
                                else
                                {
                                    c =   (-(('@') + ((int)('7') << 8)))  ;
                                }
                                break;

                case   (-((KS_EXTRA) + ((int)(KE_XUP) << 8)))  :
                    c =   (-(('k') + ((int)('u') << 8)))  ;
                    break;
                case   (-((KS_EXTRA) + ((int)(KE_XDOWN) << 8)))  :
                    c =   (-(('k') + ((int)('d') << 8)))  ;
                    break;
                case   (-((KS_EXTRA) + ((int)(KE_XLEFT) << 8)))  :
                    c =   (-(('k') + ((int)('l') << 8)))  ;
                    break;
                case   (-((KS_EXTRA) + ((int)(KE_XRIGHT) << 8)))  :
                    c =   (-(('k') + ((int)('r') << 8)))  ;
                    break;
            }

            break;
        }

        last_vgetc_recorded_len = last_recorded_len;
    }

    if (c !=   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))  )
    {
        state_no_longer_safe("key typed");
    }

    return c;
}

    static int
safe_vgetc(void)
{
    int c;

    c = vgetc();
    if (c == NUL)
    {
        c = get_keystroke();
    }
    return c;
}

    static int
plain_vgetc_nopaste(void)
{
    int c;

    do
    {
        c = safe_vgetc();
    }
    while (c ==   (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))   || c ==   (-((KS_VER_SCROLLBAR) + ((int)( ('X') ) << 8)))   || c ==   (-((KS_HOR_SCROLLBAR) + ((int)( ('X') ) << 8)))   || c ==   (-((KS_EXTRA) + ((int)(KE_MOUSEMOVE) << 8)))  )
        ;
    return c;
}

    static int
plain_vgetc(void)
{
    int c = plain_vgetc_nopaste();

    if (c ==   (-(('P') + ((int)('S') << 8)))  )
    {
        c = bracketed_paste(PASTE_ONE_CHAR, FALSE, NULL);
    }

    return c;
}

    static int
vpeekc(void)
{
    if (can_get_old_char())
    {
        return old_char;
    }
    return vgetorpeek(FALSE);
}

    static int
vpeekc_any(void)
{
    int         c;

    c = vpeekc();
    if (c == NUL && typebuf.tb_len > 0)
    {
        c = ESC;
    }
    return c;
}

    static int
char_avail(void)
{
    int     retval;

    ++no_mapping;
    retval = vpeekc();
    --no_mapping;
    return (retval != NUL);
}

typedef enum {
    map_result_fail,
    map_result_get,
    map_result_retry,
    map_result_nomatch
} map_result_T;

    static int
at_ins_compl_key(void)
{
    char_u  *p = typebuf.tb_buf + typebuf.tb_off;
    int     c = *p;

    if (typebuf.tb_len > 3 && (c ==  (0x80)  || c == CSI) && p[1] == KS_MODIFIER && (p[2] & MOD_MASK_CTRL) && !(p[2] & MOD_MASK_SHIFT))
    {
        c = p[3] & 0x1f;
    }
    return !ctrl_x_mode_eval()
            && ((ctrl_x_mode_not_default() && vim_is_ctrl_x_key(c)) || (compl_status_local() && (c == Ctrl_N || c == Ctrl_P)));
}

    static int
check_simplify_modifier(int max_offset)
{
    int         offset;
    char_u      *tp;

    for (offset = 0; offset < max_offset; ++offset)
    {
        if (offset + 3 >= typebuf.tb_len)
        {
            break;
        }
        tp = typebuf.tb_buf + typebuf.tb_off + offset;
        if ((tp[0] ==  (0x80)  || tp[0] == CSI) && tp[1] == KS_MODIFIER)
        {
            int modifier = tp[2];
            int c = tp[3];
            int new_c = merge_modifyOtherKeys(c, &modifier);

            if (new_c != c)
            {
                char_u  new_string[MB_MAXBYTES];
                int     len;
                int     key_offset = offset;

                if (offset == 0)
                {
                    vgetc_char = c;
                    vgetc_mod_mask = tp[2];
                }
                if ( ((new_c) < 0) )
                {
                    new_string[0] =  (0x80) ;
                    new_string[1] =  ((new_c) ==  (0x80)  ? KS_SPECIAL : (new_c) == NUL ? KS_ZERO :  ((-(new_c)) & 0xff) ) ;
                    new_string[2] =  (((new_c) ==  (0x80)  || (new_c) == NUL) ?  ('X')  :  (((unsigned)(-(new_c)) >> 8) & 0xff) ) ;
                    len = 3;
                }
                else
                {
                    len = mb_char2bytes(new_c, new_string);
                }
                if (modifier == 0)
                {
                    if (put_string_in_typebuf(offset, 4, new_string, len, NULL, 0, NULL) == FAIL)
                    {
                        return -1;
                    }
                }
                else
                {
                    tp[2] = modifier;
                    key_offset = offset + 3;
                    if (put_string_in_typebuf(key_offset, 1, new_string, len, NULL, 0, NULL) == FAIL)
                    {
                        return -1;
                    }
                }

                for (int i = 0; i < len; ++i)
                {
                    typebuf.tb_noremap[typebuf.tb_off + key_offset + i]
                                                            |= RM_SIMPLIFIED;
                }
                return len;
            }
        }
    }
    return 0;
}

    static int
key_protocol_enabled(void)
{
    int using_mok = modify_otherkeys_state != MOKS_INITIAL
                        ? modify_otherkeys_state == MOKS_ENABLED
                        : seenModifyOtherKeys;
    return using_mok || kitty_protocol_state == KKPS_ENABLED;
}

    static int
handle_mapping(int *keylenp, int *timedout, int *mapdepth)
{
    mapblock_T  *mp = NULL;
    mapblock_T  *mp2;
    mapblock_T  *mp_match;
    int         mp_match_len = 0;
    int         max_mlen = 0;
    int         want_termcode = 0;
    int         tb_c1;
    int         mlen;
    int         keylen = *keylenp;
    int         i;
    int         local_State = get_real_state();
    int         is_plug_map = FALSE;
    bool        in_osc = in_osc_sequence();

    if (!in_osc && typebuf.tb_len >= 3 && typebuf.tb_buf[typebuf.tb_off] ==  (0x80)  && typebuf.tb_buf[typebuf.tb_off + 1] == KS_EXTRA && typebuf.tb_buf[typebuf.tb_off + 2] == KE_PLUG)
    {
        is_plug_map = TRUE;
    }

    tb_c1 = typebuf.tb_buf[typebuf.tb_off];
    if (!in_osc && no_mapping == 0 && is_maphash_valid() && (no_zero_mapping == 0 || tb_c1 != '0') && (typebuf.tb_maplen == 0 || is_plug_map || (p_remap && (typebuf.tb_noremap[typebuf.tb_off] & (RM_NONE|RM_ABBR)) == 0)) && !(p_paste && (State & (MODE_INSERT | MODE_CMDLINE))) && !(State ==  (0x2000 | MODE_NORMAL)  && (tb_c1 == CAR || tb_c1 == ' ')) && State != MODE_ASKMORE && State != MODE_CONFIRM && !at_ins_compl_key())
    {
        mp = get_buf_maphash_list(local_State, tb_c1);
        mp2 = get_maphash_list(local_State, tb_c1);
        if (mp == NULL)
        {
            mp = mp2;
            mp2 = NULL;
        }

        mp_match = NULL;
        mp_match_len = 0;
        for ( ; mp != NULL; mp->m_next == NULL ? (mp = mp2, mp2 = NULL) : (mp = mp->m_next))
        {
            if (mp->m_keys[0] == tb_c1 && (mp->m_mode & local_State) && !(mp->m_simplified && key_protocol_enabled() && typebuf.tb_maplen == 0 && (typebuf.tb_noremap[typebuf.tb_off] & RM_SIMPLIFIED) == 0) && ((mp->m_mode & MODE_LANGMAP) == 0 || typebuf.tb_maplen == 0))
            {
                for (mlen = 1; mlen < typebuf.tb_len; ++mlen)
                {
                    int c2 = typebuf.tb_buf[typebuf.tb_off + mlen];
                    if (mp->m_keys[mlen] != c2)
                    {
                        break;
                    }
                }

                {
                    char_u *p1 = mp->m_keys;
                    char_u *p2 = mb_unescape(&p1);

                    if (has_mbyte && p2 != NULL &&  mb_bytelen_tab[tb_c1]  > mb_ptr2len(p2))
                    {
                        mlen = 0;
                    }
                }

                keylen = mp->m_keylen;
                if (mlen == keylen || (mlen == typebuf.tb_len && typebuf.tb_len < keylen))
                {
                    char_u  *s;
                    int     n;

                    s = typebuf.tb_noremap + typebuf.tb_off;
                    if ((*s & ~RM_SIMPLIFIED) == RM_SCRIPT && (mp->m_keys[0] !=  (0x80)  || mp->m_keys[1] != KS_EXTRA || mp->m_keys[2] != KE_SNR))
                    {
                        continue;
                    }

                    for (n = mlen; --n >= 0; )
                    {
                        if (*s++ & (RM_NONE|RM_ABBR))
                        {
                            break;
                        }
                    }
                    if (!is_plug_map && n >= 0)
                    {
                        continue;
                    }

                    if (keylen > typebuf.tb_len)
                    {
                        if (!*timedout && !(mp_match != NULL && mp_match->m_nowait))
                        {
                            keylen =  (-2) ;
                            break;
                        }
                    }
                    else if (keylen > mp_match_len)
                    {
                        mp_match = mp;
                        mp_match_len = keylen;
                    }
                }
                else
                {
                    if (max_mlen < mlen)
                    {
                        max_mlen = mlen;
                        want_termcode = mp->m_keys[mlen] ==  (0x80) ;
                    }
                    else if (max_mlen == mlen && mp->m_keys[mlen] ==  (0x80) )
                    {
                        want_termcode = 1;
                    }

                    if ( ((unsigned)(mp->m_keys[mlen]) - 'A' < 26) )
                    {
                        want_termcode = 1;
                    }
                }
            }
        }

        if (keylen !=  (-2)  && mp_match != NULL)
        {
            mp = mp_match;
            keylen = mp_match_len;
        }
    }

    if (!in_osc && *p_pt != NUL && mp == NULL && (State & (MODE_INSERT | MODE_NORMAL)))
    {
        for (mlen = 0; mlen < typebuf.tb_len && p_pt[mlen]; ++mlen)
        {
            if (p_pt[mlen] != typebuf.tb_buf[typebuf.tb_off + mlen])
            {
                    break;
            }
        }
        if (p_pt[mlen] == NUL)
        {
            if (mlen > typebuf.tb_maplen)
            {
                gotchars(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_maplen, mlen - typebuf.tb_maplen);
            }

            del_typebuf(mlen, 0);
            set_option_value_give_err((char_u *)"paste", (long)!p_paste, NULL, 0);
            if (!(State & MODE_INSERT))
            {
                msg_col = 0;
                msg_row = Rows - 1;
                msg_clr_eos();
            }
            status_redraw_all();
            redraw_statuslines();
            showmode();
            setcursor();
            *keylenp = keylen;
            return map_result_retry;
        }
        if (mlen == typebuf.tb_len)
        {
            keylen =  (-1) ;
        }
        else if (max_mlen < mlen)
        {
            max_mlen = mlen + 1;
        }
    }

    if (in_osc || ((mp == NULL || max_mlen + want_termcode > mp_match_len || (mp_match_len == 1 && *mp->m_keys == ESC && !*timedout)) && keylen !=  (-2) ))
    {
        int     save_keylen = keylen;

        if (in_osc || no_mapping == 0 || allow_keys != 0)
        {
            if (in_osc || ((typebuf.tb_maplen == 0 || (p_remap && (typebuf.tb_noremap[typebuf.tb_off] & ~RM_SIMPLIFIED) == RM_YES)) && !*timedout))
            {
                keylen = check_termcode(max_mlen + 1, NULL, 0, NULL);
            }
            else
            {
                keylen = 0;
            }

            if (keylen == 0 && save_keylen ==  (-1)  && !*timedout)
            {
                keylen =  (-1) ;
            }

            if (keylen == 0 && !no_reduce_keys)
            {
                keylen = check_simplify_modifier(max_mlen + 1);
                if (keylen < 0)
                {
                    return map_result_fail;
                }
            }

            if (keylen < 0 && typebuf.tb_len == typebuf.tb_maplen)
            {
                keylen = 0;
            }
        }
        else
        {
            keylen = 0;
        }
        if (keylen == 0)
        {
                if (mp == NULL)
                {
                    *keylenp = keylen;
                    return map_result_get;
                }
        }

        if (keylen > 0)
        {
            *keylenp = keylen;
            return map_result_retry;
        }

        if (mp == NULL || keylen < 0)
        {
            keylen =  (-1) ;
        }
        else
        {
            keylen = mp_match_len;
        }
    }

    if (keylen >= 0 && keylen <= typebuf.tb_len)
    {
        char_u *map_str;

        if (keylen > typebuf.tb_maplen)
        {
            gotchars(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_maplen, keylen - typebuf.tb_maplen);
        }

        cmd_silent = (typebuf.tb_silent > 0);
        del_typebuf(keylen, 0);

        if (++*mapdepth >= p_mmd)
        {
            emsg(_(e_recursive_mapping));
            if (State & MODE_CMDLINE)
            {
                redrawcmdline();
            }
            else
            {
                setcursor();
            }
            flush_buffers(FLUSH_MINIMAL);
            *mapdepth = 0;
            *keylenp = keylen;
            return map_result_fail;
        }

        if (VIsual_active && VIsual_select && (mp->m_mode & MODE_VISUAL))
        {
            VIsual_select = FALSE;
            (void)ins_typebuf( (char_u *)"\200\365X" ,  (-1) , 0, TRUE, FALSE);
        }

            map_str = mp->m_str;

        if (map_str == NULL)
        {
            i = FAIL;
        }
        else
        {
            int noremap;

            if ( mp->m_noremap  != REMAP_YES)
            {
                noremap =  mp->m_noremap ;
            }
            else if ( strncmp((char *)(map_str), (char *)(mp->m_keys), ((size_t)keylen))  == 0 || (mp->m_alt != NULL &&  strncmp((char *)(map_str), (char *)(mp->m_alt->m_keys), ((size_t)mp->m_alt->m_keylen))  == 0))
            {
                noremap =  (-3) ;
            }
            else
            {
                noremap = REMAP_YES;
            }
            i = ins_typebuf(map_str, noremap, 0, TRUE, cmd_silent ||  mp->m_silent );
        }
        *keylenp = keylen;
        if (i == FAIL)
        {
            return map_result_fail;
        }
        return map_result_retry;
    }

    *keylenp = keylen;
    return map_result_nomatch;
}

    static void
vungetc(int c)
{
    old_char = c;
    old_mod_mask = mod_mask;
    old_mouse_row = mouse_row;
    old_mouse_col = mouse_col;
    old_KeyStuffed = KeyStuffed;
}

    static void
check_end_reg_executing(int advance)
{
    if (reg_executing != 0 && (typebuf.tb_maplen == 0 || pending_end_reg_executing))
    {
        if (advance)
        {
            reg_executing = 0;
            pending_end_reg_executing = FALSE;
        }
        else
        {
            pending_end_reg_executing = TRUE;
        }
    }

}

    static int
vgetorpeek(int advance)
{
    int         c;
    int         timedout = FALSE;
    int         mapdepth = 0;
    int         mode_deleted = FALSE;
    int new_wcol;
    int new_wrow;
    int         n;
    int old_wcol;
    int old_wrow;
    int         wait_tb_len;

    if (vgetc_busy > 0 && ex_normal_busy == 0)
    {
        return NUL;
    }

    ++vgetc_busy;

    if (advance)
    {
        KeyStuffed = FALSE;
        typebuf_was_empty = FALSE;
    }

    init_typebuf();
    start_stuff();
    check_end_reg_executing(advance);
    do
    {
        if (typeahead_char != 0)
        {
            c = typeahead_char;
            if (advance)
            {
                typeahead_char = 0;
            }
        }
        else
        {
            c = read_readbuffers(advance);
        }
        if (c != NUL && !got_int)
        {
            if (advance)
            {
                KeyStuffed = TRUE;
            }
            if (typebuf.tb_no_abbr_cnt == 0)
            {
                typebuf.tb_no_abbr_cnt = 1;
            }
        }
        else
        {
            for (;;)
            {
                long    wait_time;
                int     keylen = 0;
                int     showcmd_idx;
                check_end_reg_executing(advance);
                if (typebuf.tb_maplen)
                {
                    line_breakcheck();
                }
                else
                {
                    ui_breakcheck();
                }
                if (got_int)
                {
                    c = inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 0L);

                    if ((c || typebuf.tb_maplen) && (State & (MODE_INSERT | MODE_CMDLINE)))
                    {
                        c = ESC;
                    }
                    else
                    {
                        c = Ctrl_C;
                    }
                    flush_buffers(FLUSH_INPUT);

                    if (advance)
                    {
                        *typebuf.tb_buf = c;
                        gotchars(typebuf.tb_buf, 1);
                    }
                    cmd_silent = FALSE;

                    break;
                }
                else if (typebuf.tb_len > 0)
                {
                    map_result_T result = handle_mapping(&keylen, &timedout, &mapdepth);

                    if (result == map_result_retry)
                    {
                        continue;
                    }
                    if (result == map_result_fail)
                    {
                        c = -1;
                        break;
                    }
                    if (result == map_result_get)
                    {
                        c = typebuf.tb_buf[typebuf.tb_off];
                        if (advance)
                        {
                            cmd_silent = (typebuf.tb_silent > 0);
                            if (typebuf.tb_maplen > 0)
                            {
                                KeyTyped = FALSE;
                            }
                            else
                            {
                                KeyTyped = TRUE;
                                gotchars(typebuf.tb_buf + typebuf.tb_off, 1);
                            }
                            KeyNoremap = typebuf.tb_noremap[typebuf.tb_off]
                                                            & ~RM_SIMPLIFIED;
                            del_typebuf(1, 0);
                        }
                        break;
                    }

                }

                c = 0;
                new_wcol = curwin->w_wcol;
                new_wrow = curwin->w_wrow;
                if (       advance && typebuf.tb_len == 1 && typebuf.tb_buf[typebuf.tb_off] == ESC && !no_mapping && kitty_protocol_state != KKPS_ENABLED && ex_normal_busy == 0 && typebuf.tb_maplen == 0 && (State & MODE_INSERT) && (p_timeout || (keylen ==  (-1)  && p_ttimeout)) && (c = inchar(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len, 3, 25L)) == 0)
                {
                    colnr_T     col = 0;
                    char_u      *ptr;

                    if (mode_displayed)
                    {
                        unshowmode(TRUE);
                        mode_deleted = TRUE;
                    }
                    validate_cursor();
                    old_wcol = curwin->w_wcol;
                    old_wrow = curwin->w_wrow;

                    if (curwin->w_cursor.col != 0)
                    {
                        if (curwin->w_wcol > 0)
                        {
                            if (did_ai && *skipwhite(ml_get_curline() + curwin->w_cursor.col) == NUL)
                            {
                                chartabsize_T cts;

                                curwin->w_wcol = 0;
                                ptr = ml_get_curline();
                                init_chartabsize_arg(&cts, curwin, curwin->w_cursor.lnum, 0, ptr, ptr);
                                while (cts.cts_ptr < ptr + curwin->w_cursor.col)
                                {
                                    if (! ((*cts.cts_ptr) == ' ' || (*cts.cts_ptr) == '\t') )
                                    {
                                        curwin->w_wcol = cts.cts_vcol;
                                    }
                                    cts.cts_vcol += lbr_chartabsize(&cts);
                                    if (has_mbyte)
                                    {
                                        cts.cts_ptr +=
                                                   (*mb_ptr2len)(cts.cts_ptr);
                                    }
                                    else
                                    {
                                        ++cts.cts_ptr;
                                    }
                                }
                                clear_chartabsize_arg(&cts);

                                curwin->w_wrow = curwin->w_cline_row
                                           + curwin->w_wcol / curwin->w_width;
                                curwin->w_wcol %= curwin->w_width;
                                curwin->w_wcol += curwin_col_off();
                                col = 0;
                            }
                            else
                            {
                                --curwin->w_wcol;
                                col = curwin->w_cursor.col - 1;
                            }
                        }
                        else if (curwin-> w_onebuf_opt.wo_wrap  && curwin->w_wrow)
                        {
                            --curwin->w_wrow;
                            curwin->w_wcol = curwin->w_width - 1;
                            col = curwin->w_cursor.col - 1;
                        }
                        if (has_mbyte && col > 0 && curwin->w_wcol > 0)
                        {
                            ptr = ml_get_curline();
                            col -= (*mb_head_off)(ptr, ptr + col);
                            if ((*mb_ptr2cells)(ptr + col) > 1)
                            {
                                --curwin->w_wcol;
                            }
                        }
                    }
                    setcursor();
                    out_flush();
                    new_wcol = curwin->w_wcol;
                    new_wrow = curwin->w_wrow;
                    curwin->w_wcol = old_wcol;
                    curwin->w_wrow = old_wrow;
                }
                if (c < 0)
                {
                    continue;
                }

                for (n = 1; n <= c; ++n)
                {
                    typebuf.tb_noremap[typebuf.tb_off + n] = RM_YES;
                }
                typebuf.tb_len += c;

                if (typebuf.tb_len >= typebuf.tb_maplen + MAXMAPLEN)
                {
                    timedout = TRUE;
                    continue;
                }

                if (ex_normal_busy > 0)
                {
                    static int tc = 0;

                    if (typebuf.tb_len > 0)
                    {
                        timedout = TRUE;
                        continue;
                    }

                    if (p_im && (State & MODE_INSERT))
                    {
                        c = Ctrl_L;
                    }
                    else if ((State & MODE_CMDLINE) || (cmdwin_type > 0 && tc == ESC))
                    {
                        c = Ctrl_C;
                    }
                    else
                    {
                        c = ESC;
                    }
                    tc = c;
                    if (advance)
                    {
                        typebuf_was_empty = TRUE;
                    }

                    if (pending_exmode_active)
                    {
                        exmode_active = EXMODE_NORMAL;
                    }

                    typebuf.tb_no_abbr_cnt = 0;

                    break;
                }

                if (((State & MODE_INSERT) != 0 || p_lz) && (State & MODE_CMDLINE) == 0 && advance && must_redraw != 0 && !need_wait_return)
                {
                    update_screen(0);
                    setcursor();
                }

                showcmd_idx = 0;
                int showing_partial = FALSE;
                if (typebuf.tb_len > 0 && advance && !exmode_active)
                {
                    if (((State & (MODE_NORMAL | MODE_INSERT)) || State == MODE_LANGMAP) && State !=  (0x2000 | MODE_NORMAL) )
                    {
                        if (State & MODE_INSERT && ptr2cells(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len - 1) == 1)
                        {
                            edit_putchar(typebuf.tb_buf[typebuf.tb_off + typebuf.tb_len - 1], FALSE);
                            setcursor();
                            showing_partial = TRUE;
                        }
                        old_wcol = curwin->w_wcol;
                        old_wrow = curwin->w_wrow;
                        curwin->w_wcol = new_wcol;
                        curwin->w_wrow = new_wrow;
                        push_showcmd();
                        if (typebuf.tb_len > SHOWCMD_COLS)
                        {
                            showcmd_idx = typebuf.tb_len - SHOWCMD_COLS;
                        }
                        while (showcmd_idx < typebuf.tb_len)
                        {
                            add_byte_to_showcmd(typebuf.tb_buf[typebuf.tb_off + showcmd_idx++]);
                        }
                        curwin->w_wcol = old_wcol;
                        curwin->w_wrow = old_wrow;
                    }

                    if ((State & MODE_CMDLINE) && get_cmdline_info()->cmdbuff != NULL && ptr2cells(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len - 1) == 1)
                    {
                        putcmdline(typebuf.tb_buf[typebuf.tb_off + typebuf.tb_len - 1], FALSE);
                        showing_partial = TRUE;
                    }
                }

                if (typebuf.tb_len == 0)
                {
                    timedout = FALSE;
                }

                if (advance)
                {
                    if (typebuf.tb_len == 0 || !(p_timeout || (p_ttimeout && keylen ==  (-1) )))
                    {
                        wait_time = -1L;
                    }
                    else if (keylen ==  (-1)  && p_ttm >= 0)
                    {
                        wait_time = p_ttm;
                    }
                    else
                    {
                        wait_time = p_tm;
                    }
                }
                else
                {
                    wait_time = 0;
                }

                wait_tb_len = typebuf.tb_len;
                c = inchar(typebuf.tb_buf + typebuf.tb_off + typebuf.tb_len, typebuf.tb_buflen - typebuf.tb_off - typebuf.tb_len - 1, wait_time);

                if (showcmd_idx != 0)
                {
                    pop_showcmd();
                }
                if (showing_partial)
                {
                    if (State & MODE_INSERT)
                    {
                        edit_unputchar();
                    }
                    if ((State & MODE_CMDLINE) && get_cmdline_info()->cmdbuff != NULL)
                    {
                        unputcmdline();
                    }
                    else
                    {
                        setcursor();
                    }
                }

                if (c < 0)
                {
                    continue;
                }
                if (c == NUL)
                {
                    if (!advance)
                    {
                        break;
                    }
                    if (wait_tb_len > 0)
                    {
                        timedout = TRUE;
                        continue;
                    }
                }
                else
                {
                    while (typebuf.tb_buf[typebuf.tb_off + typebuf.tb_len] != NUL)
                    {
                        typebuf.tb_noremap[typebuf.tb_off + typebuf.tb_len++] = RM_YES;
                    }
                }
            }
        }

    } while ((c < 0 && c !=   (-((KS_EXTRA) + ((int)(KE_CANCEL) << 8)))  ) || (advance && c == NUL));

    if (advance && p_smd && msg_silent == 0 && (State & MODE_INSERT))
    {
        if (c == ESC && !mode_deleted && !no_mapping && mode_displayed)
        {
            if (typebuf.tb_len && !KeyTyped)
            {
                redraw_cmdline = TRUE;
            }
            else
            {
                unshowmode(FALSE);
            }
        }
        else if (c != ESC && mode_deleted)
        {
            if (typebuf.tb_len && !KeyTyped)
            {
                redraw_cmdline = TRUE;
            }
            else
            {
                showmode();
            }
        }
    }
    if (timedout && c == ESC)
    {
        gotchars_ignore();
    }

    --vgetc_busy;

    return c;
}

    static int
inchar(char_u      *buf, int         maxlen, long        wait_time)
{
    int         len = 0;
    int         retesc = FALSE;
    int         script_char;
    int         tb_change_cnt = typebuf.tb_change_cnt;

    if (wait_time == -1L || wait_time > 100L)
    {
        cursor_on();
        out_flush_cursor(FALSE, FALSE);
    }

    if (State !=  (0x2000 | MODE_NORMAL) )
    {
        did_outofmem_msg = FALSE;
        did_swapwrite_msg = FALSE;
    }
    undo_off = FALSE;

    script_char = -1;
    while (scriptin[curscript] != NULL && script_char < 0)
    {
        if (got_int || (script_char = getc(scriptin[curscript])) < 0)
        {
            closescript();
            if (got_int)
            {
                retesc = TRUE;
            }
            else
            {
                return -1;
            }
        }
        else
        {
            buf[0] = script_char;
            len = 1;
        }
    }

    if (script_char < 0)
    {
        if (got_int)
        {
            char_u      dum[ (MAXMAPLEN * 3 + 3)  + 1];

            for (;;)
            {
                len = ui_inchar(dum,  (MAXMAPLEN * 3 + 3) , 0L, 0);
                if (len == 0 || (len == 1 && dum[0] == Ctrl_C))
                {
                    break;
                }
            }
            return retesc;
        }

        if (wait_time == -1L || wait_time > 10L)
        {
            out_flush();
        }

        len = ui_inchar(buf, maxlen / 3, wait_time, tb_change_cnt);
    }

    if (typebuf_changed(tb_change_cnt))
    {
        return 0;
    }

    if (len > 0 && ++typebuf.tb_change_cnt == 0)
    {
        typebuf.tb_change_cnt = 1;
    }

    return fix_input_buffer(buf, len);
}

    static int
fix_input_buffer(char_u *buf, int len)
{
    int         i;
    char_u      *p = buf;

    for (i = len; --i >= 0; ++p)
    {
        if (p[0] == NUL || (p[0] ==  (0x80)  && (i < 2 || p[1] != KS_EXTRA || (p[2] != (int)KE_CURSORHOLD && p[2] != (int)KE_COMPLETE_DELAY))))
        {
             memmove((char *)(p + 3), (char *)(p + 1), (size_t)i) ;
            p[2] =  (((p[0]) ==  (0x80)  || (p[0]) == NUL) ?  ('X')  :  (((unsigned)(-(p[0])) >> 8) & 0xff) ) ;
            p[1] =  ((p[0]) ==  (0x80)  ? KS_SPECIAL : (p[0]) == NUL ? KS_ZERO :  ((-(p[0])) & 0xff) ) ;
            p[0] =  (0x80) ;
            p += 2;
            len += 2;
        }
    }
    *p = NUL;
    return len;
}

    static int
input_available(void)
{
    return (!vim_is_input_buf_empty());
}

    static char_u *
getcmdkeycmd(int             promptc  __attribute__((unused)) , void            *cookie  __attribute__((unused)) , int             indent  __attribute__((unused)) , getline_opt_T   do_concat  __attribute__((unused)) )
{
    garray_T    line_ga;
    int         c1 = -1;
    int         c2;
    int         cmod = 0;
    int         aborted = FALSE;

    ga_init2(&line_ga, 1, 32);

    no_mapping++;

    got_int = FALSE;
    while (c1 != NUL && !aborted)
    {
        if (ga_grow(&line_ga, 32) == FAIL)
        {
            aborted = TRUE;
            break;
        }

        if (vgetorpeek(FALSE) == NUL)
        {
            emsg(_(e_cmd_mapping_must_end_with_cr));
            aborted = TRUE;
            break;
        }

        c1 = vgetorpeek(TRUE);

        if (c1 ==  (0x80) )
        {
            c1 = vgetorpeek(TRUE);
            c2 = vgetorpeek(TRUE);
            if (c1 == KS_MODIFIER)
            {
                cmod = c2;
                continue;
            }
            c1 =  ((c1) == KS_SPECIAL ?  (0x80)  : (c1) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((c1) + ((int)(c2) << 8))) ) ;

            if (c1 ==   (-((KS_EXTRA) + ((int)(KE_ESC) << 8)))  )
            {
                c1 = ESC;
            }

        }

        if (got_int)
        {
            aborted = TRUE;
        }
        else if (c1 == '\r' || c1 == '\n')
        {
            c1 = NUL;
        }
        else if (c1 == ESC)
        {
            aborted = TRUE;
        }
        else if (c1 ==   (-((KS_EXTRA) + ((int)(KE_COMMAND) << 8)))   || c1 ==   (-((KS_EXTRA) + ((int)(KE_SCRIPT_COMMAND) << 8)))  )
        {
            emsg(_(e_cmd_mapping_must_end_with_cr_before_second_cmd));
            aborted = TRUE;
        }
        else if (c1 ==   (-((KS_EXTRA) + ((int)(KE_SNR) << 8)))  )
        {
             ga_concat_len((&line_ga), (char_u *)("<SNR>"),  (sizeof("<SNR>" "") - 1) ) ;
        }
        else
        {
            if (cmod != 0)
            {
                ga_append(&line_ga,  (0x80) );
                ga_append(&line_ga, KS_MODIFIER);
                ga_append(&line_ga, cmod);
            }
            if ( ((c1) < 0) )
            {
                ga_append(&line_ga,  (0x80) );
                ga_append(&line_ga,  ((c1) ==  (0x80)  ? KS_SPECIAL : (c1) == NUL ? KS_ZERO :  ((-(c1)) & 0xff) ) );
                ga_append(&line_ga,  (((c1) ==  (0x80)  || (c1) == NUL) ?  ('X')  :  (((unsigned)(-(c1)) >> 8) & 0xff) ) );
            }
            else
            {
                ga_append(&line_ga, c1);
            }
        }

        cmod = 0;
    }

    no_mapping--;

    if (aborted)
    {
        ga_clear(&line_ga);
    }

    return (char_u *)line_ga.ga_data;
}

    static int
do_cmdkey_command(int key  __attribute__((unused)) , int flags)
{
    int     res;

    res = do_cmdline(NULL, getcmdkeycmd, NULL, flags);

    return res;
}

// ==================== hashtab.c ====================

enum { PERTURB_SHIFT = 5 };

static int hash_may_resize(hashtab_T *ht, int minitems);

    static void
hash_init(hashtab_T *ht)
{
      memset(((ht)), (0), (sizeof(*(ht))))  ;
    ht->ht_array = ht->ht_smallarray;
    ht->ht_mask = HT_INIT_SIZE - 1;
}

    static int
check_hashtab_frozen(hashtab_T *ht, char *command)
{
    if ((ht->ht_flags & HTFLAGS_FROZEN) == 0)
    {
        return FALSE;
    }

    semsg(_(e_not_allowed_to_add_or_remove_entries_str), command);
    return TRUE;
}

    static void
hash_clear(hashtab_T *ht)
{
    if (ht->ht_array != ht->ht_smallarray)
    {
        vim_free(ht->ht_array);
    }
}

    static void
hash_clear_all(hashtab_T *ht, int off)
{
    long        todo;
    hashitem_T  *hi;

    todo = (long)ht->ht_used;
     for ((hi) = (ht)->ht_array; (todo) > 0; ++(hi)) 
    {
        if (! ((hi)->hi_key == NULL || (hi)->hi_key == &hash_removed) )
        {
            vim_free(hi->hi_key - off);
            --todo;
        }
    }
    hash_clear(ht);
}

    static hashitem_T *
hash_find(hashtab_T *ht, char_u *key)
{
    return hash_lookup(ht, key, hash_hash(key));
}

    static hashitem_T *
hash_lookup(hashtab_T *ht, char_u *key, hash_T hash)
{
    hash_T      perturb;
    hashitem_T  *freeitem;
    hashitem_T  *hi;
    unsigned    idx;

    idx = (unsigned)(hash & ht->ht_mask);
    hi = &ht->ht_array[idx];

    if (hi->hi_key == NULL)
    {
        return hi;
    }
    if (hi->hi_key ==  &hash_removed )
    {
        freeitem = hi;
    }
    else if (hi->hi_hash == hash &&  strcmp((char *)(hi->hi_key), (char *)(key))  == 0)
    {
        return hi;
    }
    else
    {
        freeitem = NULL;
    }

    for (perturb = hash; ; perturb >>= PERTURB_SHIFT)
    {
        idx = (unsigned)((idx << 2U) + idx + perturb + 1U);
        hi = &ht->ht_array[idx & ht->ht_mask];
        if (hi->hi_key == NULL)
        {
            return freeitem == NULL ? hi : freeitem;
        }
        if (hi->hi_hash == hash && hi->hi_key !=  &hash_removed  &&  strcmp((char *)(hi->hi_key), (char *)(key))  == 0)
        {
            return hi;
        }
        if (hi->hi_key ==  &hash_removed  && freeitem == NULL)
        {
            freeitem = hi;
        }
    }
}

    static int
hash_add(hashtab_T *ht, char_u *key, char *command)
{
    hash_T      hash = hash_hash(key);
    hashitem_T  *hi;

    if (check_hashtab_frozen(ht, command))
    {
        return FAIL;
    }
    hi = hash_lookup(ht, key, hash);
    if (! ((hi)->hi_key == NULL || (hi)->hi_key == &hash_removed) )
    {
        internal_error("hash_add()");
        return FAIL;
    }
    return hash_add_item(ht, hi, key, hash);
}

    static int
hash_add_item(hashtab_T   *ht, hashitem_T  *hi, char_u      *key, hash_T      hash)
{
    if (ht->ht_flags & HTFLAGS_ERROR)
    {
        return FAIL;
    }

    ++ht->ht_used;
    ++ht->ht_changed;
    if (hi->hi_key == NULL)
    {
        ++ht->ht_filled;
    }
    hi->hi_key = key;
    hi->hi_hash = hash;

    return hash_may_resize(ht, 0);
}

    static int
hash_remove(hashtab_T *ht, hashitem_T *hi, char *command)
{
    if (check_hashtab_frozen(ht, command))
    {
        return FAIL;
    }
    --ht->ht_used;
    ++ht->ht_changed;
    hi->hi_key =  &hash_removed ;
    hash_may_resize(ht, 0);
    return OK;
}

    static int
hash_may_resize(hashtab_T   *ht, int         minitems)
{
    hashitem_T  temparray[HT_INIT_SIZE];
    hashitem_T *oldarray;
    hashitem_T *newarray;
    hashitem_T *olditem;
    hashitem_T *newitem;
    unsigned    newi;
    int         todo;
    long_u      newsize;
    long_u      minsize;
    long_u      newmask;
    hash_T      perturb;

    if (ht->ht_locked > 0)
    {
        return OK;
    }

    long_u oldsize = ht->ht_mask + 1;
    if (minitems == 0)
    {
        if (ht->ht_filled < HT_INIT_SIZE - 1 && ht->ht_array == ht->ht_smallarray)
        {
            return OK;
        }

        if (ht->ht_filled * 3 < oldsize * 2 && ht->ht_used > oldsize / 5)
        {
            return OK;
        }

        if (ht->ht_used > 1000)
        {
            minsize = ht->ht_used * 2;
        }
        else
        {
            minsize = ht->ht_used * 4;
        }
    }
    else
    {
        if ((long_u)minitems < ht->ht_used)
        {
            minitems = (int)ht->ht_used;
        }
        minsize = (minitems * 3 + 1) / 2;
    }

    newsize = HT_INIT_SIZE;
    while (newsize < minsize)
    {
        newsize <<= 1;
        if (newsize == 0)
        {
            return FAIL;
        }
    }

    if (newsize == HT_INIT_SIZE)
    {
        newarray = ht->ht_smallarray;
        if (ht->ht_array == newarray)
        {
             memmove((char *)(temparray), (char *)(newarray), sizeof(temparray)) ;
            oldarray = temparray;
        }
        else
        {
            oldarray = ht->ht_array;
        }
          memset((&(ht->ht_smallarray)), (0), (sizeof(ht->ht_smallarray)))  ;
    }

    else if (newsize == oldsize && ht->ht_filled * 3 < oldsize * 2)
    {
        return OK;
    }

    else
    {
        newarray =  (hashitem_T *)alloc_clear(sizeof(hashitem_T) * (newsize)) ;
        if (newarray == NULL)
        {
            if (ht->ht_filled < ht->ht_mask)
            {
                return OK;
            }
            ht->ht_flags |= HTFLAGS_ERROR;
            return FAIL;
        }
        oldarray = ht->ht_array;
    }

    newmask = newsize - 1;
    todo = (int)ht->ht_used;
    for (olditem = oldarray; todo > 0; ++olditem)
    {
        if (! ((olditem)->hi_key == NULL || (olditem)->hi_key == &hash_removed) )
        {
            newi = (unsigned)(olditem->hi_hash & newmask);
            newitem = &newarray[newi];

            if (newitem->hi_key != NULL)
            {
                for (perturb = olditem->hi_hash; ; perturb >>= PERTURB_SHIFT)
                {
                    newi = (unsigned)((newi << 2U) + newi + perturb + 1U);
                    newitem = &newarray[newi & newmask];
                    if (newitem->hi_key == NULL)
                    {
                        break;
                    }
                }
            }
            *newitem = *olditem;
            --todo;
        }
    }

    if (ht->ht_array != ht->ht_smallarray)
    {
        vim_free(ht->ht_array);
    }
    ht->ht_array = newarray;
    ht->ht_mask = newmask;
    ht->ht_filled = ht->ht_used;
    ++ht->ht_changed;
    ht->ht_flags &= ~HTFLAGS_ERROR;

    return OK;
}

    static hash_T
hash_hash(char_u *key)
{
    hash_T      hash;
    char_u      *p;

    if ((hash = *key) == 0)
    {
        return (hash_T)0;
    }
    p = key + 1;

    while (*p != NUL)
    {
        hash = hash * 101 + *p++;
    }

    return hash;
}

