    static void
prepare_help_buffer(void)
{
    char_u      *p;

    curbuf->b_help = true;

    p = (char_u *)"!-~,^*,^|,^\",192-255";
    if ( strcmp((char *)(curbuf->b_p_isk), (char *)(p))  != 0)
    {
        set_string_option_direct((char_u *)"isk", -1, p, OPT_FREE|OPT_LOCAL, 0);
        check_buf_options(curbuf);
        (void)buf_init_chartab(curbuf, FALSE);
    }

    curbuf->b_p_ts = 8;
    curwin-> w_onebuf_opt.wo_list  = FALSE;

    curbuf->b_p_ma = FALSE;
    curbuf->b_p_bin = FALSE;
    curwin-> w_onebuf_opt.wo_nu  = 0;
    curwin-> w_onebuf_opt.wo_rnu  = 0;
     (curwin)-> w_onebuf_opt.wo_scb  = FALSE;
     (curwin)-> w_onebuf_opt.wo_crb  = FALSE;

    set_buflisted(FALSE);
}

    static void
fix_help_buffer(void)
{
    linenr_T    lnum;
    char_u      *line;
    int         in_example = FALSE;
    int         len;
    char_u      *fname;
    char_u      *p;
    char_u      *rt;
    int         mustfree;

    {
        for (lnum = 1; lnum <= curbuf->b_ml.ml_line_count; ++lnum)
        {
            line = ml_get_buf(curbuf, lnum, FALSE);
            len = ml_get_buf_len(curbuf, lnum);
            if (in_example && len > 0 && ! ((line[0]) == ' ' || (line[0]) == '\t') )
            {
                if (line[0] == '<')
                {
                    line = ml_get_buf(curbuf, lnum, TRUE);
                    line[0] = ' ';
                }
                in_example = FALSE;
            }
            if (!in_example && len > 0)
            {
                if (line[len - 1] == '>' && (len == 1 || line[len - 2] == ' '))
                {
                    line = ml_get_buf(curbuf, lnum, TRUE);
                    line[len - 1] = ' ';
                    in_example = TRUE;
                }
                else if (line[len - 1] == '~')
                {
                    line = ml_get_buf(curbuf, lnum, TRUE);
                    line[len - 1] = ' ';
                }
            }
        }
    }

    fname = gettail(curbuf->b_fname);
    if ( vim_fnamecmp((char_u *)(fname), (char_u *)("help.txt"))  == 0)
    {
        for (lnum = 1; lnum < curbuf->b_ml.ml_line_count; ++lnum)
        {
            line = ml_get_buf(curbuf, lnum, FALSE);
            if (strstr((char *)line, "*local-additions*") == NULL)
            {
                continue;
            }

            p = p_rtp;
            while (*p != NUL)
            {
                int NameBufflen;

                NameBufflen = copy_option_part(&p, NameBuff,  PATH_MAX , ",");
                mustfree = FALSE;
                rt = vim_getenv((char_u *)"VIMRUNTIME", &mustfree);
                if (rt != NULL && fullpathcmp(rt, NameBuff, FALSE, TRUE) != FPC_SAME)
                {
                    int         fcount;
                    char_u      **fnames;
                    FILE        *fd;
                    char_u      *s;
                    int         fi;
                    vimconv_T   vc;
                    char_u      *cp;

                    if (*NameBuff != NUL && !after_pathsep(NameBuff, NameBuff + NameBufflen))
                    {
                         strcpy((char *)(NameBuff + NameBufflen), (char *)( "/" )) ;
                        NameBufflen += sizeof( ((char_u)'/') );
                    }
                     strcpy((char *)(NameBuff + NameBufflen), (char *)("doc/*.txt")) ;
                    if (gen_expand_wildcards(1, &NameBuff, &fcount, &fnames, EW_FILE|EW_SILENT) == OK && fcount > 0)
                    {
                        for (fi = 0; fi < fcount; ++fi)
                        {
                            if (fnames[fi] == NULL)
                            {
                                continue;
                            }
                            fd =  fopen(((char *)fnames[fi]), ("r")) ;
                            if (fd != NULL)
                            {
                                vim_fgets(IObuff,  (1024+1) , fd);
                                if (IObuff[0] == '*' && (s = vim_strchr(IObuff + 1, '*')) != NULL)
                                {
                                    int this_utf = MAYBE;

                                    IObuff[0] = '|';
                                    *s = '|';
                                    while (*s != NUL)
                                    {
                                        if (*s == '\r' || *s == '\n')
                                        {
                                            *s = NUL;
                                        }
                                        if (*s >= 0x80 && this_utf != FALSE)
                                        {
                                            int l;

                                            this_utf = TRUE;
                                            l = utf_ptr2len(s);
                                            if (l == 1)
                                            {
                                                this_utf = FALSE;
                                            }
                                            s += l - 1;
                                        }
                                        ++s;
                                    }

                                    vc.vc_type = CONV_NONE;
                                    convert_setup(&vc, (char_u *)(this_utf == TRUE ? "utf-8" : "latin1"), p_enc);
                                    if (vc.vc_type == CONV_NONE)
                                    {
                                        cp = IObuff;
                                    }
                                    else
                                    {
                                        cp = string_convert(&vc, IObuff, NULL);
                                        if (cp == NULL)
                                        {
                                            cp = IObuff;
                                        }
                                    }
                                    convert_setup(&vc, NULL, NULL);

                                    ml_append(lnum, cp, (colnr_T)0, FALSE);
                                    if (cp != IObuff)
                                    {
                                        vim_free(cp);
                                    }
                                    ++lnum;
                                }
                                fclose(fd);
                            }
                        }
                        FreeWild(fcount, fnames);
                    }
                }
                if (mustfree)
                {
                    vim_free(rt);
                }
            }
            break;
        }
    }
}

