static void resolve_fallback_fg_to_rgb(void);
static void resolve_fallback_bg_to_rgb(void);

    static void
init_highlight(int         both, int         reset)
{
    int         i;
    char        **pp;
    static int  had_both = FALSE;

    if (both)
    {
        had_both = TRUE;
        pp = highlight_init_both;
        for (i = 0; pp[i] != NULL; ++i)
        {
            do_highlight((char_u *)pp[i], reset, TRUE);
        }
    }
    else if (!had_both)
    {
        return;
    }

    if (*p_bg == 'l')
    {
        pp = highlight_init_light;
    }
    else
    {
        pp = highlight_init_dark;
    }
    for (i = 0; pp[i] != NULL; ++i)
    {
        do_highlight((char_u *)pp[i], reset, TRUE);
    }

    if (t_colors < 8)
    {
        do_highlight((char_u *)"Visual term=reverse cterm=reverse ctermbg=NONE ctermfg=NONE", FALSE, TRUE);
    }
    if (t_colors <= 8)
    {
        if (*p_bg == 'l')
        {
            do_highlight((char_u *)"Search ctermfg=black", FALSE, TRUE);
        }
    }

    resolve_fallback_fg_to_rgb();
    resolve_fallback_bg_to_rgb();
}

    static int
load_colors(char_u *name)
{
    char_u      *buf;
    int         retval = FAIL;
    static int  recursive = FALSE;

    if (recursive)
    {
        return OK;
    }

    recursive = TRUE;
    buf = alloc( strlen((char *)(name))  + 12);
    if (buf != NULL)
    {
        apply_autocmds(EVENT_COLORSCHEMEPRE, name, curbuf->b_fname, FALSE, curbuf);
        sprintf((char *)buf, "colors/%s.vim", name);
        retval = source_runtime(buf, DIP_START + DIP_OPT);
        vim_free(buf);
        if (retval == OK)
        {
            apply_autocmds(EVENT_COLORSCHEME, name, curbuf->b_fname, FALSE, curbuf);
        }
    }
    recursive = FALSE;

    return retval;
}

static int color_numbers_16[28] = {0, 1, 2, 3,
                                 4, 5, 6, 6,
                                 7, 7, 7, 7,
                                 8, 8,
                                 9, 9, 10, 10,
                                 11, 11, 12, 12, 13,
                                 13, 14, 14, 15, -1};
static int color_numbers_88[28] = {0, 4, 2, 6,
                                 1, 5, 32, 72,
                                 84, 84, 7, 7,
                                 82, 82,
                                 12, 43, 10, 61,
                                 14, 63, 9, 74, 13,
                                 75, 11, 78, 15, -1};
static int color_numbers_256[28] = {0, 4, 2, 6,
                                 1, 5, 130, 3,
                                 248, 248, 7, 7,
                                 242, 242,
                                 12, 81, 10, 121,
                                 14, 159, 9, 224, 13,
                                 225, 11, 229, 15, -1};
static int color_numbers_8[28] = {0, 4, 2, 6,
                                 1, 5, 3, 3,
                                 7, 7, 7, 7,
                                 0+8, 0+8,
                                 4+8, 4+8, 2+8, 2+8,
                                 6+8, 6+8, 1+8, 1+8, 5+8,
                                 5+8, 3+8, 3+8, 7+8, -1};

    static int
lookup_color(int idx, int foreground, int *boldp)
{
    int         color = color_numbers_16[idx];
    char_u      *p;

    if (color < 0)
    {
        return -1;
    }

    if (t_colors == 8)
    {
            color = color_numbers_8[idx];
        if (foreground)
        {
            if (color & 8)
            {
                *boldp = TRUE;
            }
            else
            {
                *boldp = FALSE;
            }
        }
        color &= 7;
    }
    else if (t_colors == 16 || t_colors == 88 || t_colors >= 256)
    {
        if (* ( term_strings[(int)(KS_CAF)] )  != NUL)
        {
            p =  ( term_strings[(int)(KS_CAF)] ) ;
        }
        else
        {
            p =  ( term_strings[(int)(KS_CSF)] ) ;
        }
        if (*p != NUL && (t_colors > 256 || *(p +  strlen((char *)(p))  - 1) == 'm'))
        {
            if (t_colors == 88)
            {
                color = color_numbers_88[idx];
            }
            else if (t_colors >= 256)
            {
                color = color_numbers_256[idx];
            }
            else
            {
                color = color_numbers_8[idx];
            }
        }
    }
    return color;
}

    static void
highlight_group_link(char_u  *from_hg, int     from_len, char_u  *to_hg, int     to_len, int     dodefault, int     forceit, int     init)
{
    int         from_id;
    int         to_id;
    hl_group_T  *hlgroup = NULL;

    from_id = syn_check_group(from_hg, from_len);
    if ( strncmp((char *)(to_hg), (char *)("NONE"), (4))  == 0)
    {
        to_id = 0;
    }
    else
    {
        to_id = syn_check_group(to_hg, to_len);
    }

    if (from_id > 0)
    {
        hlgroup = & ((hl_group_T *)((highlight_ga.ga_data))) [from_id - 1];
        if (dodefault && (forceit || hlgroup->sg_deflink == 0))
        {
            hlgroup->sg_deflink = to_id;
        }
    }

    if (from_id > 0 && (!init || hlgroup->sg_set == 0))
    {
        if (to_id > 0 && !forceit && !init && hl_has_settings(from_id - 1, dodefault))
        {
            if ( (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_name)  == NULL && !dodefault)
            {
                emsg(_(e_group_has_settings_highlight_link_ignored));
            }
        }
        else if (hlgroup->sg_link != to_id || hlgroup->sg_cleared)
        {
            if (!init)
            {
                hlgroup->sg_set |= SG_LINK;
            }
            hlgroup->sg_link = to_id;
            hlgroup->sg_cleared = FALSE;
            redraw_all_later(UPD_SOME_VALID);

            need_highlight_changed = TRUE;
        }
    }

}

    static void
highlight_reset_all(void)
{
    int         idx;

    restore_cterm_colors();

    for (idx = 0; idx < highlight_ga.ga_len; ++idx)
    {
        highlight_clear(idx);
    }
    init_highlight(TRUE, TRUE);
        highlight_changed();
    redraw_later_clear();
}

    static int
highlight_set_termgui_attr(int idx, char_u *key, char_u *arg, int init)
{
    int         attr;
    size_t      off;
    keyvalue_T  target;
    keyvalue_T  *entry;

    attr = 0;
    off = 0;
    target.key = 0;
    target.value.length = 0;
    while (arg[off] != NUL)
    {
        target.value.string = arg + off;
        entry = (keyvalue_T *)bsearch(&target, &highlight_tab,  (sizeof(highlight_tab) / sizeof((highlight_tab)[0])) , sizeof(highlight_tab[0]), cmp_keyvalue_value_ni);
        if (entry == NULL)
        {
            semsg(_(e_illegal_value_str), arg);
            return FALSE;
        }

        attr |= entry->key;
        off += entry->value.length;
        if (arg[off] == ',')
        {
            ++off;
        }
    }
    if (*key == 'T')
    {
        if (!init || !( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set & SG_TERM))
        {
            if (!init)
            {
                 ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set |= SG_TERM;
            }
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_term = attr;
        }
    }
    else if (*key == 'C')
    {
        if (!init || !( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set & SG_CTERM))
        {
            if (!init)
            {
                 ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_set |= SG_CTERM;
            }
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm = attr;
             ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_bold = FALSE;
        }
    }

    return TRUE;
}

    static void
hl_set_ctermfg_normal_group(int color, int bold)
{
    cterm_normal_fg_color = color + 1;
    cterm_normal_fg_bold = bold;
    {
        set_must_redraw(UPD_CLEAR);
        if (termcap_active && color >= 0)
        {
            term_fg_color(color);
        }
    }
}

    static void
highlight_set_ctermfg(int idx, int color, int is_normal_group)
{
     ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_fg = color + 1;
    if (is_normal_group)
    {
        hl_set_ctermfg_normal_group(color, ( ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm & HL_BOLD));
    }
}

    static void
hl_set_ctermbg_normal_group(int color)
{
    cterm_normal_bg_color = color + 1;
    {
        set_must_redraw(UPD_CLEAR);
        if (color >= 0)
        {
            int dark = -1;

            if (termcap_active)
            {
                term_bg_color(color);
            }
            if (t_colors < 16)
            {
                dark = (color == 0 || color == 4);
            }
            else if (color < 16)
            {
                dark = (color < 7 || color == 8);
            }
            if (dark != -1 && dark != (*p_bg == 'd') && !option_was_set((char_u *)"bg"))
            {
                set_option_value_give_err((char_u *)"bg", 0L, (char_u *)(dark ? "dark" : "light"), 0);
                reset_option_was_set((char_u *)"bg");
            }
        }
    }
}

    static void
highlight_set_ctermbg(int idx, int color, int is_normal_group)
{
     ((hl_group_T *)((highlight_ga.ga_data))) [idx].sg_cterm_bg = color + 1;
    if (is_normal_group)
    {
        hl_set_ctermbg_normal_group(color);
    }
}

