    static long
get_sw_value(buf_T *buf)
{
    return get_sw_value_col(buf, 0, FALSE);
}

    static long
get_sw_value_pos(buf_T *buf, pos_T *pos, int left)
{
    pos_T save_cursor = curwin->w_cursor;
    long sw_value;

    curwin->w_cursor = *pos;
    sw_value = get_sw_value_col(buf, get_nolist_virtcol(), left);
    curwin->w_cursor = save_cursor;
    return sw_value;
}

    static long
get_sw_value_indent(buf_T *buf, int left)
{
    pos_T pos = curwin->w_cursor;

    pos.col = getwhitecols_curline();
    return get_sw_value_pos(buf, &pos, left);
}

    static long
get_sw_value_col(buf_T *buf, colnr_T col  __attribute__((unused)) , int left  __attribute__((unused)) )
{
    return buf->b_p_sw ? buf->b_p_sw :
        buf->b_p_ts;
}

    static long
get_sts_value(void)
{
    return curbuf->b_p_sts < 0 ? get_sw_value(curbuf) : curbuf->b_p_sts;
}

    static int
get_indent(void)
{
    return get_indent_str(ml_get_curline(), (int)curbuf->b_p_ts, FALSE);
}

    static int
get_indent_lnum(linenr_T lnum)
{
    return get_indent_str(ml_get(lnum), (int)curbuf->b_p_ts, FALSE);
}

    static int
get_indent_str(char_u      *ptr, int         ts, int         no_ts)
{
    int         count = 0;

    for ( ; *ptr; ++ptr)
    {
        if (*ptr == TAB)
        {
            if (!no_ts)
            {
                count += ts - (count % ts);
            }
            else
            {
                count += ptr2cells(ptr);
            }
        }
        else if (*ptr == ' ')
        {
            ++count;
        }
        else
        {
            break;
        }
    }
    return count;
}

    static int
set_indent(int         size, int         flags)
{
    char_u      *p;
    char_u      *newline;
    char_u      *oldline;
    char_u      *s;
    int         todo;
    int         ind_len;
    int         line_len;
    int         doit = FALSE;
    int         ind_done = 0;
    int         tab_pad;
    int         retval = FALSE;
    int         orig_char_len = -1;

    todo = size;
    ind_len = 0;
    p = oldline = ml_get_curline();
    line_len = ml_get_curline_len() + 1;

    if (!curbuf->b_p_et || (!(flags & SIN_INSERT) && curbuf->b_p_pi))
    {
        if (!(flags & SIN_INSERT) && curbuf->b_p_pi)
        {
            ind_done = 0;

            while (todo > 0 &&  ((*p) == ' ' || (*p) == '\t') )
            {
                if (*p == TAB)
                {
                    tab_pad = (int)curbuf->b_p_ts
                                           - (ind_done % (int)curbuf->b_p_ts);
                    if (todo < tab_pad)
                    {
                        break;
                    }
                    todo -= tab_pad;
                    ++ind_len;
                    ind_done += tab_pad;
                }
                else
                {
                    --todo;
                    ++ind_len;
                    ++ind_done;
                }
                ++p;
            }

            if (curbuf->b_p_et)
            {
                orig_char_len = ind_len;
            }

            tab_pad = (int)curbuf->b_p_ts - (ind_done % (int)curbuf->b_p_ts);
            if (todo >= tab_pad && orig_char_len == -1)
            {
                doit = TRUE;
                todo -= tab_pad;
                ++ind_len;
            }
        }

        while (todo >= (int)curbuf->b_p_ts)
        {
            if (*p != TAB)
            {
                doit = TRUE;
            }
            else
            {
                ++p;
            }
            todo -= (int)curbuf->b_p_ts;
            ++ind_len;
        }
    }
    while (todo > 0)
    {
        if (*p != ' ')
        {
            doit = TRUE;
        }
        else
        {
            ++p;
        }
        --todo;
        ++ind_len;
    }

    if (!doit && ! ((*p) == ' ' || (*p) == '\t')  && !(flags & SIN_INSERT))
    {
        return FALSE;
    }

    if (flags & SIN_INSERT)
    {
        p = oldline;
    }
    else
    {
        p = skipwhite(p);
        line_len -= (int)(p - oldline);
    }

    if (orig_char_len != -1)
    {
        newline = alloc(orig_char_len + size - ind_done + line_len);
        if (newline == NULL)
        {
            return FALSE;
        }
        todo = size - ind_done;
        ind_len = orig_char_len + todo;
        p = oldline;
        s = newline;
        while (orig_char_len > 0)
        {
            *s++ = *p++;
            orig_char_len--;
        }

        while ( ((*p) == ' ' || (*p) == '\t') )
        {
            ++p;
        }

    }
    else
    {
        todo = size;
        newline = alloc(ind_len + line_len);
        if (newline == NULL)
        {
            return FALSE;
        }
        s = newline;
    }

    if (!curbuf->b_p_et)
    {
        if (!(flags & SIN_INSERT) && curbuf->b_p_pi)
        {
            p = oldline;
            ind_done = 0;

            while (todo > 0 &&  ((*p) == ' ' || (*p) == '\t') )
            {
                if (*p == TAB)
                {
                    tab_pad = (int)curbuf->b_p_ts
                                           - (ind_done % (int)curbuf->b_p_ts);
                    if (todo < tab_pad)
                    {
                        break;
                    }
                    todo -= tab_pad;
                    ind_done += tab_pad;
                }
                else
                {
                    --todo;
                    ++ind_done;
                }
                *s++ = *p++;
            }

            tab_pad = (int)curbuf->b_p_ts - (ind_done % (int)curbuf->b_p_ts);
            if (todo >= tab_pad)
            {
                *s++ = TAB;
                todo -= tab_pad;
            }

            p = skipwhite(p);
        }

        while (todo >= (int)curbuf->b_p_ts)
        {
            *s++ = TAB;
            todo -= (int)curbuf->b_p_ts;
        }
    }
    while (todo > 0)
    {
        *s++ = ' ';
        --todo;
    }
     memmove((char *)(s), (char *)(p), (size_t)line_len) ;

    if (!(flags & SIN_UNDO) || u_savesub(curwin->w_cursor.lnum) == OK)
    {
        colnr_T old_offset = (colnr_T)(p - oldline);
        colnr_T new_offset = (colnr_T)(s - newline);

        ml_replace(curwin->w_cursor.lnum, newline, FALSE);
        if (flags & SIN_CHANGED)
        {
            changed_bytes(curwin->w_cursor.lnum, 0);
        }

        if (saved_cursor.lnum == curwin->w_cursor.lnum)
        {
            if (saved_cursor.col >= old_offset)
            {
                saved_cursor.col += ind_len - old_offset;
            }
            else if (saved_cursor.col >= new_offset)
            {
                saved_cursor.col = new_offset;
            }
        }
        retval = TRUE;
    }
    else
    {
        vim_free(newline);
    }

    curwin->w_cursor.col = ind_len;
    return retval;
}

    static int
get_number_indent(linenr_T lnum)
{
    colnr_T     col;
    pos_T       pos;

    regmatch_T  regmatch;
    int         lead_len = 0;

    if (lnum > curbuf->b_ml.ml_line_count)
    {
        return -1;
    }
    pos.lnum = 0;

    if ((State & MODE_INSERT) || has_format_option(FO_Q_COMS))
    {
        lead_len = get_leader_len(ml_get(lnum), NULL, FALSE, TRUE);
    }

    regmatch.regprog = vim_regcomp(curbuf->b_p_flp, RE_MAGIC);
    if (regmatch.regprog != NULL)
    {
        regmatch.rm_ic = FALSE;

        if (vim_regexec(&regmatch, ml_get(lnum) + lead_len, (colnr_T)0))
        {
            pos.lnum = lnum;
            pos.col = (colnr_T)(*regmatch.endp - ml_get(lnum));
            pos.coladd = 0;
        }
        vim_regfree(regmatch.regprog);
    }

    if (pos.lnum == 0 || *ml_get_pos(&pos) == NUL)
    {
        return -1;
    }
    getvcol(curwin, &pos, &col, NULL, NULL, 0);
    return (int)col;
}

    static int
inindent(int extra)
{
    char_u      *ptr;
    colnr_T     col;

    for (col = 0, ptr = ml_get_curline();  ((*ptr) == ' ' || (*ptr) == '\t') ; ++col)
    {
        ++ptr;
    }
    if (col >= curwin->w_cursor.col + extra)
    {
        return TRUE;
    }
    else
    {
        return FALSE;
    }
}

    static void
op_reindent(oparg_T *oap, int (*how)(void))
{
    long        i = 0;
    char_u      *l;
    int         amount;
    linenr_T    first_changed = 0;
    linenr_T    last_changed = 0;
    linenr_T    start_lnum = curwin->w_cursor.lnum;

    if (!curbuf->b_p_ma)
    {
        emsg(_(e_cannot_make_changes_modifiable_is_off));
        return;
    }

    if (u_savecommon(start_lnum - 1, start_lnum + oap->line_count, start_lnum + oap->line_count, FALSE) == OK)
    {
        for (i = oap->line_count; --i >= 0 && !got_int; )
        {
            if (i > 1 && (i % 50 == 0 || i == oap->line_count - 1) && oap->line_count > p_report)
            {
                smsg(_("%ld lines to indent... "), i);
            }

            if (i != oap->line_count - 1 || oap->line_count == 1 || how != get_lisp_indent)
            {
                l = skipwhite(ml_get_curline());
                if (*l == NUL)
                {
                    amount = 0;
                }
                else
                {
                    amount = how();
                }

                if (amount >= 0 && set_indent(amount, 0))
                {
                    if (first_changed == 0)
                    {
                        first_changed = curwin->w_cursor.lnum;
                    }
                    last_changed = curwin->w_cursor.lnum;
                }
            }
            ++curwin->w_cursor.lnum;
            curwin->w_cursor.col = 0;
        }
    }

    curwin->w_cursor.lnum = start_lnum;
    beginline(BL_SOL | BL_FIX);

    if (last_changed != 0)
    {
        changed_lines(first_changed, 0, oap->is_VIsual ? start_lnum + oap->line_count : last_changed + 1, 0L);
    }
    else if (oap->is_VIsual)
    {
        redraw_curbuf_later(UPD_INVERTED);
    }

    if (oap->line_count > p_report)
    {
        i = oap->line_count - (i + 1);
        smsg(NGETTEXT("%ld line indented ", "%ld lines indented ", i), i);
    }
    if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0)
    {
        curbuf->b_op_start = oap->start;
        curbuf->b_op_end = oap->end;
    }
}

    static int
preprocs_left(void)
{
    return
        (curbuf->b_p_si && !curbuf->b_p_cin) ||
        (curbuf->b_p_cin && in_cinkeys('#', ' ', TRUE) && curbuf->b_ind_hash_comment == 0)
        ;
}

    static int
may_do_si(void)
{
    return curbuf->b_p_si
        && !curbuf->b_p_cin
        && !p_paste;
}

    static void
ins_try_si(int c)
{
    pos_T *pos;
    pos_T old_pos;
    char_u      *ptr;
    int         i;
    int         temp;

    if (((did_si || can_si_back) && c == '{') || (can_si && c == '}' && inindent(0)))
    {
        if (c == '}' && (pos = findmatch(NULL, '{')) != NULL)
        {
            old_pos = curwin->w_cursor;
            ptr = ml_get(pos->lnum);
            i = pos->col;
            if (i > 0)
            {
                while (--i > 0 &&  ((ptr[i]) == ' ' || (ptr[i]) == '\t') )
                {
                    ;
                }
            }
            curwin->w_cursor.lnum = pos->lnum;
            curwin->w_cursor.col = i;
            if (ptr[i] == ')' && (pos = findmatch(NULL, '(')) != NULL)
            {
                curwin->w_cursor = *pos;
            }
            i = get_indent();
            curwin->w_cursor = old_pos;
            if (State & VREPLACE_FLAG)
            {
                change_indent(INDENT_SET, i, FALSE, NUL, TRUE);
            }
            else
            {
                (void)set_indent(i, SIN_CHANGED);
            }
        }
        else if (curwin->w_cursor.col > 0)
        {
            temp = TRUE;
            if (c == '{' && can_si_back && curwin->w_cursor.lnum > 1)
            {
                old_pos = curwin->w_cursor;
                i = get_indent();
                while (curwin->w_cursor.lnum > 1)
                {
                    ptr = skipwhite(ml_get(--(curwin->w_cursor.lnum)));

                    if (*ptr != '#' && *ptr != NUL)
                    {
                        break;
                    }
                }
                if (get_indent() >= i)
                {
                    temp = FALSE;
                }
                curwin->w_cursor = old_pos;
            }
            if (temp)
            {
                shift_line(TRUE, FALSE, 1, TRUE);
            }
        }
    }

    if (curwin->w_cursor.col > 0 && can_si && c == '#' && inindent(0))
    {
        old_indent = get_indent();
        (void)set_indent(0, SIN_CHANGED);
    }

    if (ai_col > curwin->w_cursor.col)
    {
        ai_col = curwin->w_cursor.col;
    }
}

    static void
change_indent(int         type, int         amount, int         round, int         replaced, int         call_changed_bytes)
{
    int         vcol;
    int         last_vcol;
    int         insstart_less;
    int         new_cursor_col;
    int         i;
    char_u      *ptr;
    int         save_p_list;
    int         start_col;
    colnr_T     vc;
    colnr_T     orig_col = 0;
    char_u *new_line;
    char_u *orig_line = NULL;

    if (State & VREPLACE_FLAG)
    {
        orig_line = vim_strnsave(ml_get_curline(), ml_get_curline_len());
        orig_col = curwin->w_cursor.col;
    }

    save_p_list = curwin-> w_onebuf_opt.wo_list ;
    curwin-> w_onebuf_opt.wo_list  = FALSE;
    vc = getvcol_nolist(&curwin->w_cursor);
    vcol = vc;

    start_col = curwin->w_cursor.col;

    new_cursor_col = curwin->w_cursor.col;
    beginline(BL_WHITE);
    new_cursor_col -= curwin->w_cursor.col;

    insstart_less = curwin->w_cursor.col;

    if (new_cursor_col < 0)
    {
        vcol = get_indent() - vcol;
    }

    if (new_cursor_col > 0)
    {
        start_col = -1;
    }

    if (type == INDENT_SET)
    {
        (void)set_indent(amount, call_changed_bytes ? SIN_CHANGED : 0);
    }
    else
    {
        int     save_State = State;

        if (State & VREPLACE_FLAG)
        {
            State = MODE_INSERT;
        }
        shift_line(type == INDENT_DEC, round, 1, call_changed_bytes);
        State = save_State;
    }
    insstart_less -= curwin->w_cursor.col;

    if (new_cursor_col >= 0)
    {
        if (new_cursor_col == 0)
        {
            insstart_less = MAXCOL;
        }
        new_cursor_col += curwin->w_cursor.col;
    }
    else if (!(State & MODE_INSERT))
    {
        new_cursor_col = curwin->w_cursor.col;
    }
    else
    {
        chartabsize_T cts;

        vcol = get_indent() - vcol;
        curwin->w_virtcol = (colnr_T)((vcol < 0) ? 0 : vcol);

        last_vcol = 0;
        ptr = ml_get_curline();
        init_chartabsize_arg(&cts, curwin, 0, 0, ptr, ptr);
        while (cts.cts_vcol <= (int)curwin->w_virtcol)
        {
            last_vcol = cts.cts_vcol;
            if (cts.cts_vcol > 0)
            {
                 cts.cts_ptr += (*mb_ptr2len)(cts.cts_ptr) ;
            }
            if (*cts.cts_ptr == NUL)
            {
                break;
            }
            cts.cts_vcol += lbr_chartabsize(&cts);
        }
        vcol = last_vcol;
        new_cursor_col = cts.cts_ptr - cts.cts_line;
        clear_chartabsize_arg(&cts);

        if (vcol != (int)curwin->w_virtcol)
        {
            curwin->w_cursor.col = (colnr_T)new_cursor_col;
            i = (int)curwin->w_virtcol - vcol;
            ptr = alloc(i + 1);
            if (ptr != NULL)
            {
                size_t ptrlen;
                new_cursor_col += i;
                ptr[i] = NUL;
                ptrlen = i;
                while (--i >= 0)
                {
                    ptr[i] = ' ';
                }
                ins_str(ptr, ptrlen);
                vim_free(ptr);
            }
        }

        insstart_less = MAXCOL;
    }

    curwin-> w_onebuf_opt.wo_list  = save_p_list;

    if (new_cursor_col <= 0)
    {
        curwin->w_cursor.col = 0;
    }
    else
    {
        curwin->w_cursor.col = (colnr_T)new_cursor_col;
    }
    curwin->w_set_curswant = true;
    changed_cline_bef_curs();

    if (State & MODE_INSERT)
    {
        if (curwin->w_cursor.lnum == Insstart.lnum && Insstart.col != 0)
        {
            if ((int)Insstart.col <= insstart_less)
            {
                Insstart.col = 0;
            }
            else
            {
                Insstart.col -= insstart_less;
            }
        }
        if ((int)ai_col <= insstart_less)
        {
            ai_col = 0;
        }
        else
        {
            ai_col -= insstart_less;
        }
    }

    if ( (((State) & REPLACE_FLAG) && !((State) & VREPLACE_FLAG))  && start_col >= 0)
    {
        while (start_col > (int)curwin->w_cursor.col)
        {
            replace_join(0);
            --start_col;
        }
        while (start_col < (int)curwin->w_cursor.col || replaced)
        {
            replace_push(NUL);
            if (replaced)
            {
                replace_push(replaced);
                replaced = NUL;
            }
            ++start_col;
        }
    }

    if (State & VREPLACE_FLAG)
    {
        if (orig_line == NULL)
        {
            return;
        }

        new_line = vim_strnsave(ml_get_curline(), ml_get_curline_len());
        if (new_line == NULL)
        {
            vim_free(orig_line);
            return;
        }

        new_line[curwin->w_cursor.col] = NUL;

        ml_replace(curwin->w_cursor.lnum, orig_line, FALSE);
        curwin->w_cursor.col = orig_col;

        backspace_until_column(0);

        ins_bytes(new_line);

        vim_free(new_line);
    }
}

    static int
copy_indent(int size, char_u *src)
{
    char_u      *p = NULL;
    char_u      *line = NULL;
    char_u      *s;
    int         todo;
    int         ind_len;
    int         line_len = 0;
    int         tab_pad;
    int         ind_done;
    int         round;

    for (round = 1; round <= 2; ++round)
    {
        todo = size;
        ind_len = 0;
        ind_done = 0;
        s = src;

        while (todo > 0 &&  ((*s) == ' ' || (*s) == '\t') )
        {
            if (*s == TAB)
            {
                tab_pad = (int)curbuf->b_p_ts
                                           - (ind_done % (int)curbuf->b_p_ts);
                if (todo < tab_pad)
                {
                    break;
                }
                todo -= tab_pad;
                ind_done += tab_pad;
            }
            else
            {
                --todo;
                ++ind_done;
            }
            ++ind_len;
            if (p != NULL)
            {
                *p++ = *s;
            }
            ++s;
        }

        tab_pad = (int)curbuf->b_p_ts - (ind_done % (int)curbuf->b_p_ts);
        if (todo >= tab_pad && !curbuf->b_p_et)
        {
            todo -= tab_pad;
            ++ind_len;
            if (p != NULL)
            {
                *p++ = TAB;
            }
        }

        if (!curbuf->b_p_et)
        {
            while (todo >= (int)curbuf->b_p_ts)
            {
                todo -= (int)curbuf->b_p_ts;
                ++ind_len;
                if (p != NULL)
                {
                    *p++ = TAB;
                }
            }
        }

        while (todo > 0)
        {
            --todo;
            ++ind_len;
            if (p != NULL)
            {
                *p++ = ' ';
            }
        }

        if (p == NULL)
        {
            line_len = ml_get_curline_len() + 1;
            line = alloc(ind_len + line_len);
            if (line == NULL)
            {
                return FALSE;
            }
            p = line;
        }
    }

     memmove((char *)(p), (char *)(ml_get_curline()), (size_t)line_len) ;

    ml_replace(curwin->w_cursor.lnum, line, FALSE);

    curwin->w_cursor.col = ind_len;
    return TRUE;
}

    static void
emsg_text_too_long(void)
{
    emsg(_(e_resulting_text_too_long));
        got_int = TRUE;
}

    static void
ex_retab(exarg_T *eap)
{
    linenr_T    lnum;
    int         got_tab = FALSE;
    long        num_spaces = 0;
    long        num_tabs;
    long        len;
    long        col;
    long        vcol;
    long        start_col = 0;
    long        start_vcol = 0;
    long        old_len;
    long        new_len;
    char_u      *ptr;
    char_u      *new_line = (char_u *)1;
    int         did_undo;
    int         temp;
    int         new_ts = 0;
    int         save_list;
    linenr_T    first_line = 0;
    linenr_T    last_line = 0;
    int         is_indent_only = 0;

    save_list = curwin-> w_onebuf_opt.wo_list ;
    curwin-> w_onebuf_opt.wo_list  = 0;

    ptr = eap->arg;
    if ( strncmp((char *)(ptr), (char *)("-indentonly"), (11))  == 0 &&  ((ptr[11]) == ' ' || (ptr[11]) == '\t' || (ptr[11]) == NUL) )
    {
        is_indent_only = 1;
        ptr = skipwhite(ptr + 11);
    }

    if (ptr[0] != NUL && (ptr[0] != '0' || ptr[1] != NUL))
    {
        char_u  *end;

        if (strtol((char *)ptr, (char **)&end, 10) <= 0)
        {
            if (ptr != end)
            {
                emsg(_(e_argument_must_be_positive));
            }
            else
            {
                semsg(_(e_invalid_argument_str), ptr);
            }
            return;
        }
        new_ts = getdigits(&ptr);
        if (new_ts < 0 || new_ts > TABSTOP_MAX)
        {
            semsg(_(e_invalid_argument_str), eap->arg);
            return;
        }
    }
    if (new_ts == 0)
    {
        new_ts = curbuf->b_p_ts;
    }
    for (lnum = eap->line1; !got_int && lnum <= eap->line2; ++lnum)
    {
        ptr = ml_get(lnum);
        old_len = ml_get_len(lnum);
        col = 0;
        vcol = 0;
        did_undo = FALSE;
        for (;;)
        {
            if ( ((ptr[col]) == ' ' || (ptr[col]) == '\t') )
            {
                if (!got_tab && num_spaces == 0)
                {
                    start_vcol = vcol;
                    start_col = col;
                }
                if (ptr[col] == ' ')
                {
                    num_spaces++;
                }
                else
                {
                    got_tab = TRUE;
                }
            }
            else
            {
                if (got_tab || (eap->forceit && num_spaces > 1))
                {
                    len = num_spaces = vcol - start_vcol;
                    num_tabs = 0;
                    if (!curbuf->b_p_et)
                    {
                        temp = new_ts - (start_vcol % new_ts);
                        if (num_spaces >= temp)
                        {
                            num_spaces -= temp;
                            num_tabs++;
                        }
                        num_tabs += num_spaces / new_ts;
                        num_spaces -= (num_spaces / new_ts) * new_ts;
                    }
                    if (curbuf->b_p_et || got_tab || (num_spaces + num_tabs < len))
                    {
                        if (did_undo == FALSE)
                        {
                            did_undo = TRUE;
                            if (u_save((linenr_T)(lnum - 1), (linenr_T)(lnum + 1)) == FAIL)
                            {
                                new_line = NULL;
                                break;
                            }
                        }

                        len = num_spaces + num_tabs;
                        new_len = old_len - col + start_col + len + 1;
                        if (new_len <= 0 || new_len >= MAXCOL)
                        {
                            emsg_text_too_long();
                            break;
                        }
                        new_line = alloc(new_len);
                        if (new_line == NULL)
                        {
                            break;
                        }
                        if (start_col > 0)
                        {
                             memmove((char *)(new_line), (char *)(ptr), (size_t)start_col) ;
                        }
                         memmove((char *)(new_line + start_col + len), (char *)(ptr + col), (size_t)(old_len - col + 1)) ;
                        ptr = new_line + start_col;
                        for (col = 0; col < len; col++)
                        {
                            ptr[col] = (col < num_tabs) ? '\t' : ' ';
                        }
                        if (ml_replace(lnum, new_line, FALSE) == OK)
                        {
                            new_line = curbuf->b_ml.ml_line_ptr;
                        }
                        if (first_line == 0)
                        {
                            first_line = lnum;
                        }
                        last_line = lnum;
                        ptr = new_line;
                        old_len = new_len - 1;
                        col = start_col + len;
                    }
                }
                got_tab = FALSE;
                num_spaces = 0;

                if (is_indent_only)
                {
                    break;
                }
            }
            if (ptr[col] == NUL)
            {
                break;
            }
            vcol += chartabsize(ptr + col, (colnr_T)vcol);
            if (vcol >= MAXCOL)
            {
                emsg_text_too_long();
                break;
            }
            if (has_mbyte)
            {
                col += (*mb_ptr2len)(ptr + col);
            }
            else
            {
                ++col;
            }
        }
        if (new_line == NULL)
        {
            break;
        }
        line_breakcheck();
    }
    if (got_int)
    {
        emsg(_(e_interrupted));
    }

    if (curbuf->b_p_ts != new_ts)
    {
        redraw_curbuf_later(UPD_NOT_VALID);
    }
    if (first_line != 0)
    {
        changed_lines(first_line, 0, last_line + 1, 0L);
    }

    curwin-> w_onebuf_opt.wo_list  = save_list;

    curbuf->b_p_ts = new_ts;
    coladvance(curwin->w_curswant);

    u_clearline();
}

    static int
lisp_match(char_u *p)
{
    char_u      buf[LSIZE];
    int         len;
    char_u      *word = *curbuf->b_p_lw != NUL ? curbuf->b_p_lw : p_lispwords;

    while (*word != NUL)
    {
        len = copy_option_part(&word, buf, LSIZE, ",");
        if ( strncmp((char *)(buf), (char *)(p), (len))  == 0 &&  ((p[len]) == ' ' || (p[len]) == '\t' || (p[len]) == NUL) )
        {
            return TRUE;
        }
    }
    return FALSE;
}

    static int
get_lisp_indent(void)
{
    pos_T *pos;
    pos_T realpos;
    pos_T paren;
    int         amount;
    char_u      *that;
    colnr_T     col;
    colnr_T     firsttry;
    int parencount;
    int quotecount;
    int         vi_lisp;

    vi_lisp = (vim_strchr(p_cpo, CPO_LISP) != NULL);

    realpos = curwin->w_cursor;
    curwin->w_cursor.col = 0;

    if ((pos = findmatch(NULL, '(')) == NULL)
    {
        pos = findmatch(NULL, '[');
    }
    else
    {
        paren = *pos;
        pos = findmatch(NULL, '[');
        if (pos == NULL ||  (((pos)->lnum != (&paren)->lnum)                    ? (pos)->lnum < (&paren)->lnum                 : (pos)->col != (&paren)->col                      ? (pos)->col < (&paren)->col                   : (pos)->coladd < (&paren)->coladd) )
        {
            pos = &paren;
        }
    }
    if (pos != NULL)
    {
        amount = -1;
        parencount = 0;

        while (--curwin->w_cursor.lnum >= pos->lnum)
        {
            if (linewhite(curwin->w_cursor.lnum))
            {
                continue;
            }
            for (that = ml_get_curline(); *that != NUL; ++that)
            {
                if (*that == ';')
                {
                    while (*(that + 1) != NUL)
                    {
                        ++that;
                    }
                    continue;
                }
                if (*that == '\\')
                {
                    if (*(that + 1) != NUL)
                    {
                        ++that;
                    }
                    continue;
                }
                if (*that == '"' && *(that + 1) != NUL)
                {
                    while (*++that && *that != '"')
                    {
                        if (*that == '\\')
                        {
                            if (*++that == NUL)
                            {
                                break;
                            }
                            if (that[1] == NUL)
                            {
                                ++that;
                                break;
                            }
                        }
                    }
                    if (*that == NUL)
                    {
                        break;
                    }
                }
                if (*that == '(' || *that == '[')
                {
                    ++parencount;
                }
                else if (*that == ')' || *that == ']')
                {
                    --parencount;
                }
            }
            if (parencount == 0)
            {
                amount = get_indent();
                break;
            }
        }

        if (amount == -1)
        {
            curwin->w_cursor.lnum = pos->lnum;
            curwin->w_cursor.col = pos->col;
            col = pos->col;

            that = ml_get_curline();

            if (vi_lisp && get_indent() == 0)
            {
                amount = 2;
            }
            else
            {
                char_u          *line = that;
                chartabsize_T   cts;

                init_chartabsize_arg(&cts, curwin, pos->lnum, 0, line, line);
                while (*cts.cts_ptr != NUL && col > 0)
                {
                    cts.cts_vcol += lbr_chartabsize_adv(&cts);
                    col--;
                }
                amount = cts.cts_vcol;
                that = cts.cts_ptr;
                clear_chartabsize_arg(&cts);

                if (!vi_lisp && (*that == '(' || *that == '[') && lisp_match(that + 1))
                {
                    amount += 2;
                }
                else
                {
                    if (*that != NUL)
                    {
                        that++;
                        amount++;
                    }
                    firsttry = amount;

                    init_chartabsize_arg(&cts, curwin, (colnr_T)(that - line), amount, line, that);
                    while ( ((*cts.cts_ptr) == ' ' || (*cts.cts_ptr) == '\t') )
                    {
                        cts.cts_vcol += lbr_chartabsize(&cts);
                        ++cts.cts_ptr;
                    }
                    that = cts.cts_ptr;
                    amount = cts.cts_vcol;
                    clear_chartabsize_arg(&cts);

                    if (*that && *that != ';')
                    {
                        if (!vi_lisp && *that != '(' && *that != '[')
                        {
                            firsttry++;
                        }

                        parencount = 0;
                        quotecount = 0;

                        init_chartabsize_arg(&cts, curwin, (colnr_T)(that - line), amount, line, that);
                        if (vi_lisp || (*that != '"' && *that != '\'' && *that != '#' && (*that < '0' || *that > '9')))
                        {
                            while (*cts.cts_ptr && (! ((*cts.cts_ptr) == ' ' || (*cts.cts_ptr) == '\t')  || quotecount || parencount) && (!((*cts.cts_ptr == '(' || *cts.cts_ptr == '[') && !quotecount && !parencount && vi_lisp)))
                            {
                                if (*cts.cts_ptr == '"')
                                {
                                    quotecount = !quotecount;
                                }
                                if ((*cts.cts_ptr == '(' || *cts.cts_ptr == '[') && !quotecount)
                                {
                                    ++parencount;
                                }
                                if ((*cts.cts_ptr == ')' || *cts.cts_ptr == ']') && !quotecount)
                                {
                                    --parencount;
                                }
                                if (*cts.cts_ptr == '\\' && *(cts.cts_ptr+1) != NUL)
                                {
                                    cts.cts_vcol += lbr_chartabsize_adv(&cts);
                                }
                                cts.cts_vcol += lbr_chartabsize_adv(&cts);
                            }
                        }
                        while ( ((*cts.cts_ptr) == ' ' || (*cts.cts_ptr) == '\t') )
                        {
                            cts.cts_vcol += lbr_chartabsize(&cts);
                            ++cts.cts_ptr;
                        }
                        that = cts.cts_ptr;
                        amount = cts.cts_vcol;
                        clear_chartabsize_arg(&cts);

                        if (!*that || *that == ';')
                        {
                            amount = firsttry;
                        }
                    }
                }
            }
        }
    }
    else
    {
        amount = 0;
    }

    curwin->w_cursor = realpos;

    return amount;
}

    static void
fixthisline(int (*get_the_indent)(void))
{
    int amount = get_the_indent();

    if (amount < 0)
    {
        return;
    }

    change_indent(INDENT_SET, amount, FALSE, 0, TRUE);
    if (linewhite(curwin->w_cursor.lnum))
    {
        did_ai = TRUE;
    }
}

    static int
use_indentexpr_for_lisp(void)
{
    return FALSE;
}

    static void
fix_indent(void)
{
    if (p_paste)
    {
        return;
    }
    if (curbuf->b_p_lisp && curbuf->b_p_ai)
    {
        if (use_indentexpr_for_lisp())
        {
            do_c_expr_indent();
        }
        else
        {
            fixthisline(get_lisp_indent);
        }
    }
    else if (cindent_on())
    {
        do_c_expr_indent();
    }
}

