// ==================== locale.c ====================

// ==================== map.c ====================

static mapblock_T       *first_abbr = NULL;

static mapblock_T       *(maphash[256]);
static int              maphash_valid = FALSE;

static int              map_locked = 0;

    static mapblock_T *
get_maphash_list(int state, int c)
{
    return maphash[ (((state) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (c) : ((c) ^ 0x80)) ];
}

    static mapblock_T *
get_buf_maphash_list(int state, int c)
{
    return curbuf->b_maphash[ (((state) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (c) : ((c) ^ 0x80)) ];
}

    static int
is_maphash_valid(void)
{
    return maphash_valid;
}

    static void
validate_maphash(void)
{
    if (maphash_valid)
    {
        return;
    }

      memset((&(maphash)), (0), (sizeof(maphash)))  ;
    maphash_valid = TRUE;
}

    static void
map_free(mapblock_T **mpp)
{
    mapblock_T  *mp;

    mp = *mpp;
    vim_free(mp->m_keys);
    if (mp->m_alt != NULL)
    {
        mp->m_alt->m_alt = NULL;
    }
    vim_free(mp->m_str);
    vim_free(mp->m_orig_str);
    *mpp = mp->m_next;
    vim_free(mp);
}

    static char_u *
map_mode_to_chars(int mode)
{
    garray_T    mapmode;

    ga_init2(&mapmode, 1, 7);

    if ((mode & (MODE_INSERT | MODE_CMDLINE)) == (MODE_INSERT | MODE_CMDLINE))
    {
        ga_append(&mapmode, '!');
    }
    else if (mode & MODE_INSERT)
    {
        ga_append(&mapmode, 'i');
    }
    else if (mode & MODE_LANGMAP)
    {
        ga_append(&mapmode, 'l');
    }
    else if (mode & MODE_CMDLINE)
    {
        ga_append(&mapmode, 'c');
    }
    else if ((mode & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING)) == (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING))
    {
        ga_append(&mapmode, ' ');
    }
    else
    {
        if (mode & MODE_NORMAL)
        {
            ga_append(&mapmode, 'n');
        }
        if (mode & MODE_OP_PENDING)
        {
            ga_append(&mapmode, 'o');
        }
        if (mode & MODE_TERMINAL)
        {
            ga_append(&mapmode, 't');
        }
        if ((mode & (MODE_VISUAL | MODE_SELECT)) == (MODE_VISUAL | MODE_SELECT))
        {
            ga_append(&mapmode, 'v');
        }
        else
        {
            if (mode & MODE_VISUAL)
            {
                ga_append(&mapmode, 'x');
            }
            if (mode & MODE_SELECT)
            {
                ga_append(&mapmode, 's');
            }
        }
    }

    ga_append(&mapmode, NUL);
    return (char_u *)mapmode.ga_data;
}

    static void
showmap(mapblock_T  *mp, int         local)
{
    int         len = 1;
    char_u      *mapchars;

    if (message_filtered(mp->m_keys) && message_filtered(mp->m_str))
    {
        return;
    }

    ++map_locked;

    if (msg_didout || msg_silent != 0)
    {
        msg_putchar('\n');
        if (got_int)
        {
            goto theend;
        }
    }

    mapchars = map_mode_to_chars(mp->m_mode);
    if (mapchars != NULL)
    {
        msg_puts((char *)mapchars);
        len = (int) strlen((char *)(mapchars)) ;
        vim_free(mapchars);
    }

    while (++len <= 3)
    {
        msg_putchar(' ');
    }

    len = msg_outtrans_special(mp->m_keys, TRUE, 0);
    do
    {
        msg_putchar(' ');
        ++len;
    } while (len < 12);

    if (mp->m_noremap ==  (-1) )
    {
        msg_puts_attr("*",  highlight_attr[(int)(HLF_8)] );
    }
    else if (mp->m_noremap ==  (-2) )
    {
        msg_puts_attr("&",  highlight_attr[(int)(HLF_8)] );
    }
    else
    {
        msg_putchar(' ');
    }

    if (local)
    {
        msg_putchar('@');
    }
    else
    {
        msg_putchar(' ');
    }

    if (*mp->m_str == NUL)
    {
        msg_puts_attr("<Nop>",  highlight_attr[(int)(HLF_8)] );
    }
    else
    {
        msg_outtrans_special(mp->m_str, FALSE, 0);
    }
    msg_clr_eos();
    out_flush();

theend:
    --map_locked;
}

    static mapblock_T *
map_add(mapblock_T  **map_table, mapblock_T  **abbr_table, char_u      *keys, char_u      *rhs, char_u      *orig_rhs, int         noremap, int         nowait, int         silent, int         mode, int         is_abbr, int         simplified)
{
    mapblock_T  *mp =  (mapblock_T *)alloc_clear(sizeof(mapblock_T)) ;

    if (mp == NULL)
    {
        return NULL;
    }

    if (*keys == Ctrl_C)
    {
        if (map_table == curbuf->b_maphash)
        {
            curbuf->b_mapped_ctrl_c |= mode;
        }
        else
        {
            mapped_ctrl_c |= mode;
        }
    }

    mp->m_keys = vim_strsave(keys);
    mp->m_str = vim_strsave(rhs);
    mp->m_orig_str = vim_strsave(orig_rhs);
    if (mp->m_keys == NULL || mp->m_str == NULL)
    {
        vim_free(mp->m_keys);
        vim_free(mp->m_str);
        vim_free(mp->m_orig_str);
        vim_free(mp);
        return NULL;
    }
    mp->m_keylen = (int) strlen((char *)(mp->m_keys)) ;
    mp->m_noremap = noremap;
    mp->m_nowait = nowait;
    mp->m_silent = silent;
    mp->m_mode = mode;
    mp->m_simplified = simplified;

    if (is_abbr)
    {
        mp->m_next = *abbr_table;
        *abbr_table = mp;
    }
    else
    {
        int n =  (((mp->m_mode) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (mp->m_keys[0]) : ((mp->m_keys[0]) ^ 0x80)) ;

        mp->m_next = map_table[n];
        map_table[n] = mp;
    }
    return mp;
}

    static void
list_mappings(int     keyround, int     abbrev, int     haskey, char_u  *keys, int     keys_len, int     mode, int     *did_local)
{
    ++map_locked;

    if (p_verbose > 0 && keyround == 1)
    {
        if (seenModifyOtherKeys)
        {
            msg_puts(_("Seen modifyOtherKeys: true\n"));
        }

        if (modify_otherkeys_state != MOKS_INITIAL)
        {
            char *name = _("Unknown");
            switch (modify_otherkeys_state)
            {
                case MOKS_INITIAL:
                    break;
                case MOKS_OFF:
                    name = _("Off");
                    break;
                case MOKS_ENABLED:
                    name = _("On");
                    break;
                case MOKS_DISABLED:
                    name = _("Disabled");
                    break;
                case MOKS_AFTER_T_TE:
                    name = _("Cleared");
                    break;
            }

            char buf[200];
            vim_snprintf(buf, sizeof(buf), _("modifyOtherKeys detected: %s\n"), name);
            msg_puts(buf);
        }

        if (kitty_protocol_state != KKPS_INITIAL)
        {
            char *name = _("Unknown");
            switch (kitty_protocol_state)
            {
                case KKPS_INITIAL:
                    break;
                case KKPS_OFF:
                    name = _("Off");
                    break;
                case KKPS_ENABLED:
                    name = _("On");
                    break;
                case KKPS_DISABLED:
                    name = _("Disabled");
                    break;
                case KKPS_AFTER_T_TE:
                    name = _("Cleared");
                    break;
            }

            char buf[200];
            vim_snprintf(buf, sizeof(buf), _("Kitty keyboard protocol: %s\n"), name);
            msg_puts(buf);
        }
    }

    for (int hash = 0; hash < 256 && !got_int; ++hash)
    {
        mapblock_T      *mp;

        if (abbrev)
        {
            if (hash != 0)
            {
                break;
            }
            mp = curbuf->b_first_abbr;
        }
        else
        {
            mp = curbuf->b_maphash[hash];
        }
        for ( ; mp != NULL && !got_int; mp = mp->m_next)
        {
            if (!mp->m_simplified && (mp->m_mode & mode) != 0)
            {
                if (!haskey)
                {
                    showmap(mp, TRUE);
                    *did_local = TRUE;
                }
                else
                {
                    int n = mp->m_keylen;
                    if ( strncmp((char *)(mp->m_keys), (char *)(keys), ((size_t)(n < keys_len ? n : keys_len)))  == 0)
                    {
                        showmap(mp, TRUE);
                        *did_local = TRUE;
                    }
                }
            }
        }
    }

    --map_locked;
}

    static int
do_map(int         maptype, char_u      *arg, int         mode, int         abbrev)
{
    char_u      *keys;
    mapblock_T *mp;
    mapblock_T **mpp;
    mapblock_T  *mp_result[2] = {NULL, NULL};
    char_u      *rhs;
    char_u      *p;
    int         n;
    int         len = 0;
    int         hasarg;
    int         haskey;
    int         do_print;
    int         keyround;
    char_u      *keys_buf = NULL;
    char_u      *alt_keys_buf = NULL;
    char_u      *arg_buf = NULL;
    int         retval = 0;
    int         do_backslash;
    mapblock_T  **abbr_table;
    mapblock_T  **map_table;
    int         unique = FALSE;
    int         nowait = FALSE;
    int         silent = FALSE;
    int         special = FALSE;
    int         did_simplify = FALSE;
    int         unmap_lhs_only = FALSE;
    int         noremap;
    char_u      *orig_rhs;

    keys = arg;
    map_table = maphash;
    abbr_table = &first_abbr;

    if (maptype == MAPTYPE_UNMAP_LHS)
    {
        unmap_lhs_only = TRUE;
        maptype = MAPTYPE_UNMAP;
    }

    if (maptype == MAPTYPE_NOREMAP)
    {
        noremap =  (-1) ;
    }
    else
    {
        noremap = REMAP_YES;
    }

    for (;;)
    {
        if ( strncmp((char *)(keys), (char *)("<buffer>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            map_table = curbuf->b_maphash;
            abbr_table = &curbuf->b_first_abbr;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<nowait>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            nowait = TRUE;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<silent>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            silent = TRUE;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<special>"), (9))  == 0)
        {
            keys = skipwhite(keys + 9);
            special = TRUE;
            continue;
        }

        if ( strncmp((char *)(keys), (char *)("<unique>"), (8))  == 0)
        {
            keys = skipwhite(keys + 8);
            unique = TRUE;
            continue;
        }
        break;
    }

    validate_maphash();

    p = keys;
    do_backslash = (vim_strchr(p_cpo, CPO_BSLASH) == NULL);
    while (*p && (maptype == MAPTYPE_UNMAP || ! ((*p) == ' ' || (*p) == '\t') ))
    {
        if ((p[0] == Ctrl_V || (do_backslash && p[0] == '\\')) && p[1] != NUL)
        {
            ++p;
        }
        ++p;
    }
    if (*p != NUL)
    {
        *p++ = NUL;
    }

    p = skipwhite(p);
    rhs = p;
    hasarg = (*rhs != NUL);
    haskey = (*keys != NUL);
    do_print = !haskey || (maptype != MAPTYPE_UNMAP && !hasarg);

    if (maptype == MAPTYPE_UNMAP && !haskey)
    {
        retval = 1;
        goto theend;
    }

    if (haskey)
    {
        char_u  *new_keys;
        int     flags = REPTERM_FROM_PART | REPTERM_DO_LT;

        if (special)
        {
            flags |= REPTERM_SPECIAL;
        }
        new_keys = replace_termcodes(keys, &keys_buf, 0, flags, &did_simplify);
        if (did_simplify)
        {
            (void)replace_termcodes(keys, &alt_keys_buf, 0, flags | REPTERM_NO_SIMPLIFY, NULL);
        }
        keys = new_keys;
    }
    orig_rhs = rhs;
    if (hasarg)
    {
        if ( strcasecmp((char *)(rhs), (char *)("<nop>"))  == 0)
        {
            rhs = (char_u *)"";
        }
        else
        {
            rhs = replace_termcodes(rhs, &arg_buf, 0, REPTERM_DO_LT | (special ? REPTERM_SPECIAL : 0), NULL);
        }
    }

    for (keyround = 1; keyround <= 2; ++keyround)
    {
        int     did_it = FALSE;
        int     did_local = FALSE;
        int     keyround1_simplified = keyround == 1 && did_simplify;
        int     round;
        int     num_rounds;

        if (keyround == 2)
        {
            if (alt_keys_buf == NULL)
            {
                break;
            }
            keys = alt_keys_buf;
        }
        else if (alt_keys_buf != NULL && do_print)
        {
            keys = alt_keys_buf;
        }

        if (haskey)
        {
            len = (int) strlen((char *)(keys)) ;
            if (len > MAXMAPLEN)
            {
                retval = 1;
                goto theend;
            }

            if (abbrev && maptype != MAPTYPE_UNMAP)
            {
                if (has_mbyte)
                {
                    int first;
                    int last;
                    int         same = -1;
                    char_u      keys_unescaped[MAXMAPLEN + 1];
                    size_t      keys_unescaped_len;

                     memmove((char *)(keys_unescaped), (char *)(keys), (size_t)(len + 1)) ;
                    keys_unescaped_len = vim_unescape_csi(keys_unescaped);
                    p = keys_unescaped;

                    first = vim_iswordp(p);
                    last = first;
                     p += (*mb_ptr2len)(p) ;
                    n = 1;
                    while (p < keys_unescaped + keys_unescaped_len)
                    {
                        ++n;
                        last = vim_iswordp(p);
                        if (same == -1 && last != first)
                        {
                            same = n - 1;
                        }
                         p += (*mb_ptr2len)(p) ;
                    }
                    if (last && n > 2 && same >= 0 && same < n - 1)
                    {
                        retval = 1;
                        goto theend;
                    }
                }
                else if (vim_iswordc(keys[len - 1]))
                {
                    for (n = 0; n < len - 2; ++n)
                    {
                        if (vim_iswordc(keys[n]) != vim_iswordc(keys[len - 2]))
                        {
                            retval = 1;
                            goto theend;
                        }
                    }
                }
                for (n = 0; n < len; ++n)
                {
                    if ( ((keys[n]) == ' ' || (keys[n]) == '\t') )
                    {
                        retval = 1;
                        goto theend;
                    }
                }
            }
        }

        if (haskey && hasarg && abbrev)
        {
            no_abbr = FALSE;
        }

        if (do_print)
        {
            msg_start();
        }

        if (unique && map_table == curbuf->b_maphash && haskey && hasarg && maptype != MAPTYPE_UNMAP)
        {
            for (int hash = 0; hash < 256 && !got_int; ++hash)
            {
                if (abbrev)
                {
                    if (hash != 0)
                    {
                        break;
                    }
                    mp = first_abbr;
                }
                else
                {
                    mp = maphash[hash];
                }
                for ( ; mp != NULL && !got_int; mp = mp->m_next)
                {
                    if ((mp->m_mode & mode) != 0 && mp->m_keylen == len &&  strncmp((char *)(mp->m_keys), (char *)(keys), ((size_t)len))  == 0)
                    {
                        if (abbrev)
                        {
                            semsg(_(e_global_abbreviation_already_exists_for_str), mp->m_keys);
                        }
                        else
                        {
                            semsg(_(e_global_mapping_already_exists_for_str), mp->m_keys);
                        }
                        retval = 5;
                        goto theend;
                    }
                }
            }
        }

        if (map_table != curbuf->b_maphash && !hasarg && maptype != MAPTYPE_UNMAP)
        {
            list_mappings(keyround, abbrev, haskey, keys, len, mode, &did_local);
        }

        num_rounds = maptype == MAPTYPE_UNMAP && !unmap_lhs_only ? 2 : 1;
        for (round = 0; round < num_rounds && !did_it && !got_int; ++round)
        {
            for (int hash = 0; hash < 256 && !got_int; ++hash)
            {
                if (abbrev)
                {
                    if (hash > 0)
                    {
                        break;
                    }
                    mpp = abbr_table;
                }
                else
                {
                    mpp = &(map_table[hash]);
                }
                for (mp = *mpp; mp != NULL && !got_int; mp = *mpp)
                {
                    if ((mp->m_mode & mode) == 0)
                    {
                        mpp = &(mp->m_next);
                        continue;
                    }
                    if (!haskey)
                    {
                        if (!mp->m_simplified)
                        {
                            showmap(mp, map_table != maphash);
                            did_it = TRUE;
                        }
                    }
                    else
                    {
                        if (round)
                        {
                            n = (int) strlen((char *)(mp->m_str)) ;
                            p = mp->m_str;
                        }
                        else
                        {
                            n = mp->m_keylen;
                            p = mp->m_keys;
                        }
                        if ( strncmp((char *)(p), (char *)(keys), ((size_t)(n < len ? n : len)))  == 0)
                        {
                            if (maptype == MAPTYPE_UNMAP)
                            {
                                if (n != len && (!abbrev || round || n > len || *skipwhite(keys + n) != NUL))
                                {
                                    mpp = &(mp->m_next);
                                    continue;
                                }
                                if (keyround1_simplified && !mp->m_simplified)
                                {
                                    break;
                                }
                                mp->m_mode &= ~mode;
                                did_it = TRUE;
                            }
                            else if (!hasarg)
                            {
                                if (!mp->m_simplified)
                                {
                                    showmap(mp, map_table != maphash);
                                    did_it = TRUE;
                                }
                            }
                            else if (n != len)
                            {
                                mpp = &(mp->m_next);
                                continue;
                            }
                            else if (unique)
                            {
                                if (abbrev)
                                {
                                    semsg(_(e_abbreviation_already_exists_for_str), p);
                                }
                                else
                                {
                                    semsg(_(e_mapping_already_exists_for_str), p);
                                }
                                retval = 5;
                                goto theend;
                            }
                            else
                            {
                                mp->m_mode &= ~mode;
                                if (mp->m_mode == 0 && !did_it)
                                {
                                    char_u *newstr = vim_strsave(rhs);

                                    if (newstr == NULL)
                                    {
                                        retval = 4;
                                        goto theend;
                                    }
                                    if (mp->m_alt != NULL)
                                    {
                                        mp->m_alt = mp->m_alt->m_alt = NULL;
                                    }
                                    vim_free(mp->m_str);
                                    mp->m_str = newstr;
                                    vim_free(mp->m_orig_str);
                                    mp->m_orig_str = vim_strsave(orig_rhs);
                                    mp->m_noremap = noremap;
                                    mp->m_nowait = nowait;
                                    mp->m_silent = silent;
                                    mp->m_mode = mode;
                                    mp->m_simplified = keyround1_simplified;
                                    mp_result[keyround - 1] = mp;
                                    did_it = TRUE;
                                }
                            }
                            if (mp->m_mode == 0)
                            {
                                map_free(mpp);
                                continue;
                            }

                            int new_hash =  (((mp->m_mode) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (mp->m_keys[0]) : ((mp->m_keys[0]) ^ 0x80)) ;
                            if (!abbrev && new_hash != hash)
                            {
                                *mpp = mp->m_next;
                                mp->m_next = map_table[new_hash];
                                map_table[new_hash] = mp;

                                continue;
                            }
                        }
                    }
                    mpp = &(mp->m_next);
                }
            }
        }

        if (maptype == MAPTYPE_UNMAP)
        {
            if (!did_it)
            {
                if (!keyround1_simplified)
                {
                    retval = 2;
                }
            }
            else if (*keys == Ctrl_C)
            {
                if (map_table == curbuf->b_maphash)
                {
                    curbuf->b_mapped_ctrl_c &= ~mode;
                }
                else
                {
                    mapped_ctrl_c &= ~mode;
                }
            }
            continue;
        }

        if (!haskey || !hasarg)
        {
            if (!did_it && !did_local)
            {
                if (abbrev)
                {
                    msg(_("No abbreviation found"));
                }
                else
                {
                    msg(_("No mapping found"));
                }
            }
            goto theend;
        }

        if (did_it)
        {
            continue;
        }

        mp_result[keyround - 1] = map_add(map_table, abbr_table, keys, rhs, orig_rhs, noremap, nowait, silent, mode, abbrev, keyround1_simplified);
        if (mp_result[keyround - 1] == NULL)
        {
            retval = 4;
            goto theend;
        }
    }

    if (mp_result[0] != NULL && mp_result[1] != NULL)
    {
        mp_result[0]->m_alt = mp_result[1];
        mp_result[1]->m_alt = mp_result[0];
    }

theend:
    vim_free(keys_buf);
    vim_free(alt_keys_buf);
    vim_free(arg_buf);
    return retval;
}

    static int
get_map_mode(char_u **cmdp, int forceit)
{
    char_u      *p;
    int         modec;
    int         mode;

    p = *cmdp;
    modec = *p++;
    if (modec == 'i')
    {
        mode = MODE_INSERT;
    }
    else if (modec == 'l')
    {
        mode = MODE_LANGMAP;
    }
    else if (modec == 'c')
    {
        mode = MODE_CMDLINE;
    }
    else if (modec == 'n' && *p != 'o')
    {
        mode = MODE_NORMAL;
    }
    else if (modec == 'v')
    {
        mode = MODE_VISUAL | MODE_SELECT;
    }
    else if (modec == 'x')
    {
        mode = MODE_VISUAL;
    }
    else if (modec == 's')
    {
        mode = MODE_SELECT;
    }
    else if (modec == 'o')
    {
        mode = MODE_OP_PENDING;
    }
    else if (modec == 't')
    {
        mode = MODE_TERMINAL;
    }
    else
    {
        --p;
        if (forceit)
        {
            mode = MODE_INSERT | MODE_CMDLINE;
        }
        else
        {
            mode = MODE_VISUAL | MODE_SELECT | MODE_NORMAL | MODE_OP_PENDING;
        }
    }

    *cmdp = p;
    return mode;
}

    static void
map_clear(char_u      *cmdp, char_u      *arg, int         forceit, int         abbr)
{
    int         mode;
    int         local;

    local = ( strcmp((char *)(arg), (char *)("<buffer>"))  == 0);
    if (!local && *arg != NUL)
    {
        emsg(_(e_invalid_argument));
        return;
    }

    mode = get_map_mode(&cmdp, forceit);
    map_clear_mode(curbuf, mode, local, abbr);
}

    static int
is_map_locked(void)
{
    if (map_locked > 0)
    {
        emsg(_(e_cannot_change_mappings_while_listing));
        return TRUE;
    }
    return FALSE;
}

    static void
map_clear_mode(buf_T       *buf, int         mode, int         local, int         abbr)
{
    mapblock_T *mp;
    mapblock_T **mpp;
    int         hash;
    int         new_hash;

    if (is_map_locked())
    {
        return;
    }

    validate_maphash();

    for (hash = 0; hash < 256; ++hash)
    {
        if (abbr)
        {
            if (hash > 0)
            {
                break;
            }
            if (local)
            {
                mpp = &buf->b_first_abbr;
            }
            else
            {
                mpp = &first_abbr;
            }
        }
        else
        {
            if (local)
            {
                mpp = &buf->b_maphash[hash];
            }
            else
            {
                mpp = &maphash[hash];
            }
        }
        while (*mpp != NULL)
        {
            mp = *mpp;
            if (mp->m_mode & mode)
            {
                mp->m_mode &= ~mode;
                if (mp->m_mode == 0)
                {
                    map_free(mpp);
                    continue;
                }
                new_hash =  (((mp->m_mode) & (MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING | MODE_TERMINAL)) ? (mp->m_keys[0]) : ((mp->m_keys[0]) ^ 0x80)) ;
                if (!abbr && new_hash != hash)
                {
                    *mpp = mp->m_next;
                    if (local)
                    {
                        mp->m_next = buf->b_maphash[new_hash];
                        buf->b_maphash[new_hash] = mp;
                    }
                    else
                    {
                        mp->m_next = maphash[new_hash];
                        maphash[new_hash] = mp;
                    }
                    continue;
                }
            }
            mpp = &(mp->m_next);
        }
    }
}

    static int
map_to_exists_mode(char_u *rhs, int mode, int abbr)
{
    mapblock_T  *mp;
    int         hash;
    int         exp_buffer = FALSE;

    validate_maphash();

    for (;;)
    {
        for (hash = 0; hash < 256; ++hash)
        {
            if (abbr)
            {
                if (hash > 0)
                {
                    break;
                }
                if (exp_buffer)
                {
                    mp = curbuf->b_first_abbr;
                }
                else
                {
                    mp = first_abbr;
                }
            }
            else if (exp_buffer)
            {
                mp = curbuf->b_maphash[hash];
            }
            else
            {
                mp = maphash[hash];
            }
            for (; mp; mp = mp->m_next)
            {
                if ((mp->m_mode & mode) && strstr((char *)mp->m_str, (char *)rhs) != NULL)
                {
                    return TRUE;
                }
            }
        }
        if (exp_buffer)
        {
            break;
        }
        exp_buffer = TRUE;
    }

    return FALSE;
}

static int      expand_mapmodes = 0;
static int      expand_isabbrev = 0;
static int      expand_buffer = FALSE;

    static char_u *
translate_mapping(char_u *str)
{
    garray_T    ga;
    int         c;
    int         modifiers;
    int         cpo_bslash;
    int         cpo_special;

    ga_init(&ga);
    ga.ga_itemsize = 1;
    ga.ga_growsize = 40;

    cpo_bslash = (vim_strchr(p_cpo, CPO_BSLASH) != NULL);
    cpo_special = (vim_strchr(p_cpo, CPO_SPECI) != NULL);

    for (; *str; ++str)
    {
        c = *str;
        if (c ==  (0x80)  && str[1] != NUL && str[2] != NUL)
        {
            modifiers = 0;
            if (str[1] == KS_MODIFIER)
            {
                str++;
                modifiers = *++str;
                c = *++str;
            }
            if (c ==  (0x80)  && str[1] != NUL && str[2] != NUL)
            {
                if (cpo_special)
                {
                    ga_clear(&ga);
                    return NULL;
                }
                c =  ((str[1]) == KS_SPECIAL ?  (0x80)  : (str[1]) == KS_ZERO ?   (-((KS_ZERO) + ((int)( ('X') ) << 8)))   :  (-((str[1]) + ((int)(str[2]) << 8))) ) ;
                if (c ==   (-((KS_ZERO) + ((int)( ('X') ) << 8)))  )
                {
                    c = NUL;
                }
                str += 2;
            }
            if ( ((c) < 0)  || modifiers)
            {
                if (cpo_special)
                {
                    ga_clear(&ga);
                    return NULL;
                }
                ga_concat(&ga, get_special_key_name(c, modifiers));
                continue;
            }
        }
        if (c == ' ' || c == '\t' || c == Ctrl_J || c == Ctrl_V || (c == '<' && !cpo_special) || (c == '\\' && !cpo_bslash))
        {
            ga_append(&ga, cpo_bslash ? Ctrl_V : '\\');
        }
        if (c)
        {
            ga_append(&ga, c);
        }
    }
    ga_append(&ga, NUL);
    return (char_u *)(ga.ga_data);
}

    static char_u *
set_context_in_map_cmd(expand_T    *xp, char_u      *cmd, char_u      *arg, int         forceit, int         isabbrev, int         isunmap, cmdidx_T    cmdidx)
{
    if (forceit && cmdidx != CMD_map && cmdidx != CMD_unmap)
    {
        xp->xp_context = EXPAND_NOTHING;
    }
    else
    {
        if (isunmap)
        {
            expand_mapmodes = get_map_mode(&cmd, forceit || isabbrev);
        }
        else
        {
            expand_mapmodes = MODE_INSERT | MODE_CMDLINE;
            if (!isabbrev)
            {
                expand_mapmodes += MODE_VISUAL | MODE_SELECT | MODE_NORMAL
                                                             | MODE_OP_PENDING;
            }
        }
        expand_isabbrev = isabbrev;
        xp->xp_context = EXPAND_MAPPINGS;
        expand_buffer = FALSE;
        for (;;)
        {
            if ( strncmp((char *)(arg), (char *)("<buffer>"), (8))  == 0)
            {
                expand_buffer = TRUE;
                arg = skipwhite(arg + 8);
                continue;
            }
            if ( strncmp((char *)(arg), (char *)("<unique>"), (8))  == 0)
            {
                arg = skipwhite(arg + 8);
                continue;
            }
            if ( strncmp((char *)(arg), (char *)("<nowait>"), (8))  == 0)
            {
                arg = skipwhite(arg + 8);
                continue;
            }
            if ( strncmp((char *)(arg), (char *)("<silent>"), (8))  == 0)
            {
                arg = skipwhite(arg + 8);
                continue;
            }
            if ( strncmp((char *)(arg), (char *)("<special>"), (9))  == 0)
            {
                arg = skipwhite(arg + 9);
                continue;
            }
            break;
        }
        xp->xp_pattern = arg;
    }

    return NULL;
}

    static int
ExpandMappings(char_u      *pat, regmatch_T  *regmatch, int         *numMatches, char_u      ***matches)
{
    mapblock_T  *mp;
    garray_T    ga;
    int         hash;
    int         count;
    char_u      *p;
    int         i;
    int         fuzzy;
    int         match;
    int         score = 0;
    fuzmatch_str_T  *fuzmatch;

    fuzzy = cmdline_fuzzy_complete(pat);

    validate_maphash();

    *numMatches = 0;
    *matches = NULL;

    if (!fuzzy)
    {
        ga_init2(&ga, sizeof(char *), 3);
    }
    else
    {
        ga_init2(&ga, sizeof(fuzmatch_str_T), 3);
    }

    for (i = 0; i < 7; ++i)
    {
        if (i == 0)
        {
            p = (char_u *)"<silent>";
        }
        else if (i == 1)
        {
            p = (char_u *)"<unique>";
        }
        else if (i == 4 && !expand_buffer)
        {
            p = (char_u *)"<buffer>";
        }
        else if (i == 5)
        {
            p = (char_u *)"<nowait>";
        }
        else if (i == 6)
        {
            p = (char_u *)"<special>";
        }
        else
        {
            continue;
        }

        if (!fuzzy)
        {
            match = vim_regexec(regmatch, p, (colnr_T)0);
        }
        else
        {
            score = fuzzy_match_str(p, pat);
            match = (score !=  INT_MIN );
        }

        if (!match)
        {
            continue;
        }

        if (ga_grow(&ga, 1) == FAIL)
        {
            break;
        }

        if (fuzzy)
        {
            fuzmatch = &((fuzmatch_str_T *)ga.ga_data)[ga.ga_len];
            fuzmatch->idx = ga.ga_len;
            fuzmatch->str = vim_strsave(p);
            fuzmatch->score = score;
        }
        else
        {
            ((char_u **)ga.ga_data)[ga.ga_len] = vim_strsave(p);
        }
        ++ga.ga_len;
    }

    for (hash = 0; hash < 256; ++hash)
    {
        if (expand_isabbrev)
        {
            if (hash > 0)
            {
                break;
            }
            mp = first_abbr;
        }
        else if (expand_buffer)
        {
            mp = curbuf->b_maphash[hash];
        }
        else
        {
            mp = maphash[hash];
        }
        for (; mp; mp = mp->m_next)
        {
            if (mp->m_simplified || !(mp->m_mode & expand_mapmodes))
            {
                continue;
            }

            p = translate_mapping(mp->m_keys);
            if (p == NULL)
            {
                continue;
            }

            if (!fuzzy)
            {
                match = vim_regexec(regmatch, p, (colnr_T)0);
            }
            else
            {
                score = fuzzy_match_str(p, pat);
                match = (score !=  INT_MIN );
            }

            if (!match)
            {
                vim_free(p);
                continue;
            }

            if (ga_grow(&ga, 1) == FAIL)
            {
                vim_free(p);
                break;
            }

            if (fuzzy)
            {
                fuzmatch = &((fuzmatch_str_T *)ga.ga_data)[ga.ga_len];
                fuzmatch->idx = ga.ga_len;
                fuzmatch->str = p;
                fuzmatch->score = score;
            }
            else
            {
                ((char_u **)ga.ga_data)[ga.ga_len] = p;
            }

            ++ga.ga_len;
        }
    }

    if (ga.ga_len == 0)
    {
        return FAIL;
    }

    if (!fuzzy)
    {
        *matches = ga.ga_data;
        *numMatches = ga.ga_len;
    }
    else
    {
        if (fuzzymatches_to_strmatches(ga.ga_data, matches, ga.ga_len, FALSE) == FAIL)
        {
            return FAIL;
        }
        *numMatches = ga.ga_len;
    }

    count = *numMatches;
    if (count > 1)
    {
        char_u  **ptr1;
        char_u  **ptr2;
        char_u  **ptr3;

        if (!fuzzy)
        {
            sort_strings(*matches, count);
        }

        ptr1 = *matches;
        ptr2 = ptr1 + 1;
        ptr3 = ptr1 + count;

        while (ptr2 < ptr3)
        {
            if ( strcmp((char *)(*ptr1), (char *)(*ptr2))  != 0)
            {
                *++ptr1 = *ptr2++;
            }
            else
            {
                vim_free(*ptr2++);
                count--;
            }
        }
    }

    *numMatches = count;
    return (count == 0 ? FAIL : OK);
}

    static int
check_abbr(int         c, char_u      *ptr, int         col, int         mincol)
{
    int         len;
    int         scol;
    int         j;
    char_u      *s;
    char_u      tb[MB_MAXBYTES + 4];
    mapblock_T  *mp;
    mapblock_T  *mp2;
    int         clen = 0;
    int         is_id = TRUE;
    int         vim_abbr;

    if (typebuf.tb_no_abbr_cnt)
    {
        return FALSE;
    }

    if (noremap_keys() && c != Ctrl_RSB)
    {
        return FALSE;
    }

    if (col == 0)
    {
        return FALSE;
    }

    if (has_mbyte)
    {
        char_u *p;

        p = mb_prevptr(ptr, ptr + col);
        if (!vim_iswordp(p))
        {
            vim_abbr = TRUE;
        }
        else
        {
            vim_abbr = FALSE;
            if (p > ptr)
            {
                is_id = vim_iswordp(mb_prevptr(ptr, p));
            }
        }
        clen = 1;
        while (p > ptr + mincol)
        {
            p = mb_prevptr(ptr, p);
            if (vim_isspace(*p) || (!vim_abbr && is_id != vim_iswordp(p)))
            {
                p += (*mb_ptr2len)(p);
                break;
            }
            ++clen;
        }
        scol = (int)(p - ptr);
    }
    else
    {
        if (!vim_iswordc(ptr[col - 1]))
        {
            vim_abbr = TRUE;
        }
        else
        {
            vim_abbr = FALSE;
            if (col > 1)
            {
                is_id = vim_iswordc(ptr[col - 2]);
            }
        }
        for (scol = col - 1; scol > 0 && !vim_isspace(ptr[scol - 1]) && (vim_abbr || is_id == vim_iswordc(ptr[scol - 1])); --scol)
        {
            ;
        }
    }

    if (scol < mincol)
    {
        scol = mincol;
    }
    if (scol < col)
    {
        ptr += scol;
        len = col - scol;
        mp = curbuf->b_first_abbr;
        mp2 = first_abbr;
        if (mp == NULL)
        {
            mp = mp2;
            mp2 = NULL;
        }
        for ( ; mp; mp->m_next == NULL ? (mp = mp2, mp2 = NULL) : (mp = mp->m_next))
        {
            int         qlen = mp->m_keylen;
            char_u      *q = mp->m_keys;
            int         match;

            if (vim_strbyte(mp->m_keys,  (0x80) ) != NULL)
            {
                char_u *qe = vim_strsave(mp->m_keys);

                if (qe != NULL)
                {
                    q = qe;
                    qlen = (int)vim_unescape_csi(q);
                }
            }

            match =    (mp->m_mode & State)
                    && qlen == len
                    &&  strncmp((char *)(q), (char *)(ptr), ((size_t)len))  == 0;
            if (q != mp->m_keys)
            {
                vim_free(q);
            }
            if (match)
            {
                break;
            }
        }
        if (mp != NULL)
        {
            int noremap;
            int silent;

            j = 0;
            if (c != Ctrl_RSB)
            {
                if ( ((c) < 0)  || c ==  (0x80) )
                {
                    tb[j++] =  (0x80) ;
                    tb[j++] =  ((c) ==  (0x80)  ? KS_SPECIAL : (c) == NUL ? KS_ZERO :  ((-(c)) & 0xff) ) ;
                    tb[j++] =  (((c) ==  (0x80)  || (c) == NUL) ?  ('X')  :  (((unsigned)(-(c)) >> 8) & 0xff) ) ;
                }
                else
                {
                    if (c < ABBR_OFF && (c < ' ' || c > '~'))
                    {
                        tb[j++] = Ctrl_V;
                    }
                    if (has_mbyte)
                    {
                        int     newlen;
                        char_u  *escaped;

                        if (c >= ABBR_OFF)
                        {
                            c -= ABBR_OFF;
                        }
                        newlen = (*mb_char2bytes)(c, tb + j);
                        tb[j + newlen] = NUL;
                        escaped = vim_strsave_escape_csi(tb + j);
                        if (escaped != NULL)
                        {
                            newlen = (int) strlen((char *)(escaped)) ;
                             memmove((char *)(tb + j), (char *)(escaped), newlen) ;
                            j += newlen;
                            vim_free(escaped);
                        }
                    }
                    else
                    {
                        tb[j++] = c;
                    }
                }
                tb[j] = NUL;
                (void)ins_typebuf(tb, 1, 0, TRUE, mp->m_silent);
            }

            noremap = mp->m_noremap;
            silent = mp->m_silent;
                s = mp->m_str;
            if (s != NULL)
            {
                (void)ins_typebuf(s, noremap, 0, TRUE, silent);
                typebuf.tb_no_abbr_cnt += (int) strlen((char *)(s))  + j + 1;
            }

            tb[0] = Ctrl_H;
            tb[1] = NUL;
            if (has_mbyte)
            {
                len = clen;
            }
            while (len-- > 0)
            {
                (void)ins_typebuf(tb, 1, 0, TRUE, silent);
            }
            return TRUE;
        }
    }
    return FALSE;
}

    static char_u *
vim_strsave_escape_csi(char_u *p)
{
    char_u      *res;
    char_u *s;
    char_u *d;

    res = alloc( strlen((char *)(p))  * 4 + 1);
    if (res == NULL)
    {
        return NULL;
    }

    d = res;
    for (s = p; *s != NUL; )
    {
        if ((s[0] ==  (0x80) ) && s[1] != NUL && s[2] != NUL)
        {
            *d++ = *s++;
            *d++ = *s++;
            *d++ = *s++;
        }
        else
        {
            d = add_char2buf( (has_mbyte ? mb_ptr2char(s) : (int)*(s)) , d);
            s +=  (enc_utf8 ? utf_ptr2len(s) : (*mb_ptr2len)(s)) ;
        }
    }
    *d = NUL;

    return res;
}

    static size_t
vim_unescape_csi(char_u *p)
{
    char_u *s = p;
    char_u *d = p;

    while (*s != NUL)
    {
        if (s[0] ==  (0x80)  && s[1] == KS_SPECIAL && s[2] ==  ('X') )
        {
            *d++ =  (0x80) ;
            s += 3;
        }
        else if ((s[0] ==  (0x80)  || s[0] == CSI) && s[1] == KS_EXTRA && s[2] == (int)KE_CSI)
        {
            *d++ = CSI;
            s += 3;
        }
        else
        {
            *d++ = *s++;
        }
    }
    *d = NUL;
    return (size_t)(d - p);
}

    static void
check_map_keycodes(void)
{
    mapblock_T  *mp;
    char_u      *p;
    int         i;
    char_u      buf[3];
    int         abbr;
    int         hash;
    buf_T       *bp;

    validate_maphash();
    estack_push(ETYPE_INTERNAL, (char_u *)"mappings", 0);

    for (bp = firstbuf; ; bp = bp->b_next)
    {
        for (abbr = 0; abbr <= 1; ++abbr)
        {
            for (hash = 0; hash < 256; ++hash)
            {
                if (abbr)
                {
                    if (hash)
                    {
                        break;
                    }
                    if (bp != NULL)
                    {
                        mp = bp->b_first_abbr;
                    }
                    else
                    {
                        mp = first_abbr;
                    }
                }
                else
                {
                    if (bp != NULL)
                    {
                        mp = bp->b_maphash[hash];
                    }
                    else
                    {
                        mp = maphash[hash];
                    }
                }
                for ( ; mp != NULL; mp = mp->m_next)
                {
                    for (i = 0; i <= 1; ++i)
                    {
                        if (i == 0)
                        {
                            p = mp->m_keys;
                        }
                        else
                        {
                            p = mp->m_str;
                        }
                        while (*p)
                        {
                            if (*p ==  (0x80) )
                            {
                                ++p;
                                if (*p < 128)
                                {
                                    buf[0] = p[0];
                                    buf[1] = p[1];
                                    buf[2] = NUL;
                                    (void)add_termcap_entry(buf, FALSE);
                                }
                                ++p;
                            }
                            ++p;
                        }
                    }
                }
            }
        }
        if (bp == NULL)
        {
            break;
        }
    }
    estack_pop();
}

struct initmap
{
    char_u      *arg;
    int         mode;
};

static struct initmap vimrc_mappings[] =
{
        {(char_u *)"<Tab> %", MODE_NORMAL | MODE_VISUAL | MODE_SELECT | MODE_OP_PENDING},
        {(char_u *)"\u00a7 <C-_>", MODE_INSERT | MODE_CMDLINE},
        {(char_u *)"\u00e9 u", MODE_NORMAL},
        {(char_u *)"\u00e1 <C-R>", MODE_NORMAL},
};

    static void
init_mappings(void)
{
    for (int i = 0; i < (int) (sizeof(vimrc_mappings) / sizeof((vimrc_mappings)[0])) ; ++i)
    {
        add_map(vimrc_mappings[i].arg, vimrc_mappings[i].mode, FALSE);
    }
}

    static void
add_map(char_u *map, int mode, int nore)
{
    char_u      *s;
    char_u      *cpo_save = p_cpo;

    p_cpo = empty_option;
    s = vim_strsave(map);
    if (s != NULL)
    {
        (void)do_map(nore ? MAPTYPE_NOREMAP : MAPTYPE_MAP, s, mode, FALSE);
        vim_free(s);
    }
    p_cpo = cpo_save;
}

    static void
do_exmap(exarg_T *eap, int isabbrev)
{
    int     mode;
    char_u  *cmdp;

    cmdp = eap->cmd;
    mode = get_map_mode(&cmdp, eap->forceit || isabbrev);

    switch (do_map(*cmdp == 'n' ? MAPTYPE_NOREMAP : *cmdp == 'u' ? MAPTYPE_UNMAP : MAPTYPE_MAP, eap->arg, mode, isabbrev))
    {
        case 1:
            emsg(_(e_invalid_argument));
                break;
        case 2:
            emsg((isabbrev ? _(e_no_such_abbreviation) : _(e_no_such_mapping)));
                break;
    }
}

    static void
ex_abbreviate(exarg_T *eap)
{
    do_exmap(eap, TRUE);
}

    static void
ex_map(exarg_T *eap)
{
    if (secure)
    {
        secure = 2;
        msg_outtrans(eap->cmd);
        msg_putchar('\n');
    }
    do_exmap(eap, FALSE);
}

    static void
ex_unmap(exarg_T *eap)
{
    do_exmap(eap, FALSE);
}

    static void
ex_mapclear(exarg_T *eap)
{
    map_clear(eap->cmd, eap->arg, eap->forceit, FALSE);
}

    static void
ex_abclear(exarg_T *eap)
{
    map_clear(eap->cmd, eap->arg, TRUE, TRUE);
}

