static xfmark_T namedfm[ ('z' - 'a' + 1)  + EXTRA_MARKS];

static void fname2fnum(xfmark_T *fm);
static void fmarks_check_one(xfmark_T *fm, char_u *name, buf_T *buf);
static char_u *mark_line(pos_T *mp, int lead_len);
static void show_one_mark(int, char_u *, pos_T *, char_u *, int current);
static void mark_adjust_internal(linenr_T line1, linenr_T line2, long amount, long amount_after, int adjust_folds);

    static int
setmark(int c)
{
    return setmark_pos(c, &curwin->w_cursor, curbuf->b_fnum);
}

    static int
setmark_pos(int c, pos_T *pos, int fnum)
{
    int         i;
    buf_T       *buf;

    if (c < 0)
    {
        return FAIL;
    }

    if (c == '\'' || c == '`')
    {
        if (pos == &curwin->w_cursor)
        {
            setpcmark();
            curwin->w_prev_pcmark = curwin->w_pcmark;
        }
        else
        {
            curwin->w_pcmark = *pos;
        }
        return OK;
    }

    buf = buflist_findnr(fnum);
    if (buf == NULL)
    {
        return FAIL;
    }

    if (c == '"')
    {
        buf->b_last_cursor = *pos;
        return OK;
    }

    if (c == '[')
    {
        buf->b_op_start = *pos;
        return OK;
    }
    if (c == ']')
    {
        buf->b_op_end = *pos;
        return OK;
    }

    if (c == '<' || c == '>')
    {
        if (c == '<')
        {
            buf->b_visual.vi_start = *pos;
        }
        else
        {
            buf->b_visual.vi_end = *pos;
        }
        if (buf->b_visual.vi_mode == NUL)
        {
            buf->b_visual.vi_mode = 'v';
        }
        return OK;
    }

    if ( ((unsigned)(c) - 'a' < 26) )
    {
        i = c - 'a';
        buf->b_namedm[i] = *pos;
        return OK;
    }
    if ( ((unsigned)(c) - 'A' < 26)  ||  ((unsigned)(c) - '0' < 10) )
    {
        if ( ((unsigned)(c) - '0' < 10) )
        {
            i = c - '0' +  ('z' - 'a' + 1) ;
        }
        else
        {
            i = c - 'A';
        }
        namedfm[i].fmark.mark = *pos;
        namedfm[i].fmark.fnum = fnum;
         vim_free(namedfm[i].fname);
         (namedfm[i].fname) = NULL;
        return OK;
    }
    return FAIL;
}

    static void
mark_forget_file(win_T *wp, int fnum)
{
    int         i;

    for (i = wp->w_jumplistlen - 1; i >= 0; --i)
    {
        if (wp->w_jumplist[i].fmark.fnum == fnum)
        {
            vim_free(wp->w_jumplist[i].fname);
            if (wp->w_jumplistidx > i)
            {
                --wp->w_jumplistidx;
            }
            --wp->w_jumplistlen;
             memmove((char *)(&wp->w_jumplist[i]), (char *)(&wp->w_jumplist[i + 1]), (wp->w_jumplistlen - i) * sizeof(wp->w_jumplist[i])) ;
        }
    }

    for (i = wp->w_tagstacklen - 1; i >= 0; --i)
    {
        if (wp->w_tagstack[i].fmark.fnum == fnum)
        {
            tagstack_clear_entry(&wp->w_tagstack[i]);
            if (wp->w_tagstackidx > i)
            {
                --wp->w_tagstackidx;
            }
            --wp->w_tagstacklen;
             memmove((char *)(&wp->w_tagstack[i]), (char *)(&wp->w_tagstack[i + 1]), (wp->w_tagstacklen - i) * sizeof(wp->w_tagstack[i])) ;
        }
    }
}

    static void
setpcmark(void)
{
    int         i;
    xfmark_T    *fm;

    if (global_busy || listcmd_busy || (cmdmod.cmod_flags & CMOD_KEEPJUMPS))
    {
        return;
    }

    curwin->w_prev_pcmark = curwin->w_pcmark;
    curwin->w_pcmark = curwin->w_cursor;

    if (jop_flags & JOP_STACK)
    {
        if (curwin->w_jumplistidx < curwin->w_jumplistlen - 1)
        {
            curwin->w_jumplistlen = curwin->w_jumplistidx + 1;
        }
    }

    if (++curwin->w_jumplistlen > JUMPLISTSIZE)
    {
        curwin->w_jumplistlen = JUMPLISTSIZE;
        vim_free(curwin->w_jumplist[0].fname);
        for (i = 1; i < JUMPLISTSIZE; ++i)
        {
            curwin->w_jumplist[i - 1] = curwin->w_jumplist[i];
        }
    }
    curwin->w_jumplistidx = curwin->w_jumplistlen;
    fm = &curwin->w_jumplist[curwin->w_jumplistlen - 1];

    fm->fmark.mark = curwin->w_pcmark;
    fm->fmark.fnum = curbuf->b_fnum;
    fm->fname = NULL;
}

    static void
checkpcmark(void)
{
    if (curwin->w_prev_pcmark.lnum != 0 && ( (((curwin->w_pcmark).lnum == (curwin->w_cursor).lnum) && ((curwin->w_pcmark).col == (curwin->w_cursor).col) && ((curwin->w_pcmark).coladd == (curwin->w_cursor).coladd))  || curwin->w_pcmark.lnum == 0))
    {
        curwin->w_pcmark = curwin->w_prev_pcmark;
    }
    curwin->w_prev_pcmark.lnum = 0;
}

    static pos_T *
movemark(int count)
{
    pos_T       *pos;
    xfmark_T    *jmp;

    cleanup_jumplist(curwin, TRUE);

    if (curwin->w_jumplistlen == 0)
    {
        return (pos_T *)NULL;
    }

    for (;;)
    {
        if (curwin->w_jumplistidx + count < 0 || curwin->w_jumplistidx + count >= curwin->w_jumplistlen)
        {
            return (pos_T *)NULL;
        }

        if (curwin->w_jumplistidx == curwin->w_jumplistlen)
        {
            setpcmark();
            --curwin->w_jumplistidx;
            if (curwin->w_jumplistidx + count < 0)
            {
                return (pos_T *)NULL;
            }
        }

        curwin->w_jumplistidx += count;

        jmp = curwin->w_jumplist + curwin->w_jumplistidx;
        if (jmp->fmark.fnum == 0)
        {
            fname2fnum(jmp);
        }
        if (jmp->fmark.fnum != curbuf->b_fnum)
        {
            fmark_T fmark = jmp->fmark;

            if (buflist_findnr(fmark.fnum) == NULL)
            {
                count += count < 0 ? -1 : 1;
                continue;
            }
            if (buflist_getfile(fmark.fnum, fmark.mark.lnum, 0, FALSE) == FAIL)
            {
                return (pos_T *)NULL;
            }
            curwin->w_cursor = fmark.mark;
            pos = (pos_T *)-1;
        }
        else
        {
            pos = &(jmp->fmark.mark);
        }
        return pos;
    }
}

    static pos_T *
movechangelist(int count)
{
    int         n;

    if (curbuf->b_changelistlen == 0)
    {
        return (pos_T *)NULL;
    }

    n = curwin->w_changelistidx;
    if (n + count < 0)
    {
        if (n == 0)
        {
            return (pos_T *)NULL;
        }
        n = 0;
    }
    else if (n + count >= curbuf->b_changelistlen)
    {
        if (n == curbuf->b_changelistlen - 1)
        {
            return (pos_T *)NULL;
        }
        n = curbuf->b_changelistlen - 1;
    }
    else
    {
        n += count;
    }
    curwin->w_changelistidx = n;
    return curbuf->b_changelist + n;
}

    static pos_T *
getmark_buf(buf_T *buf, int c, int changefile)
{
    return getmark_buf_fnum(buf, c, changefile, NULL);
}

    static pos_T *
getmark(int c, int changefile)
{
    return getmark_buf_fnum(curbuf, c, changefile, NULL);
}

    static pos_T *
getmark_buf_fnum(buf_T       *buf, int         c, int         changefile, int         *fnum)
{
    pos_T               *posp;
    pos_T *startp;
    pos_T *endp;
    static pos_T        pos_copy;

    posp = NULL;

    if (c < 0)
    {
        return posp;
    }
    if (c > '~')
    {
        ;
    }
    else if (c == '\'' || c == '`')
    {
        pos_copy = curwin->w_pcmark;
        posp = &pos_copy;
    }
    else if (c == '"')
    {
        posp = &(buf->b_last_cursor);
    }
    else if (c == '^')
    {
        posp = &(buf->b_last_insert);
    }
    else if (c == '.')
    {
        posp = &(buf->b_last_change);
    }
    else if (c == '[')
    {
        posp = &(buf->b_op_start);
    }
    else if (c == ']')
    {
        posp = &(buf->b_op_end);
    }
    else if (c == '{' || c == '}')
    {
        pos_T   pos;
        oparg_T oa;
        int     slcb = listcmd_busy;

        pos = curwin->w_cursor;
        listcmd_busy = TRUE;
        if (findpar(&oa.inclusive, c == '}' ? FORWARD :  (-1) , 1L, NUL, FALSE))
        {
            pos_copy = curwin->w_cursor;
            posp = &pos_copy;
        }
        curwin->w_cursor = pos;
        listcmd_busy = slcb;
    }
    else if (c == '(' || c == ')')
    {
        pos_T   pos;
        int     slcb = listcmd_busy;

        pos = curwin->w_cursor;
        listcmd_busy = TRUE;
        if (findsent(c == ')' ? FORWARD :  (-1) , 1L))
        {
            pos_copy = curwin->w_cursor;
            posp = &pos_copy;
        }
        curwin->w_cursor = pos;
        listcmd_busy = slcb;
    }
    else if (c == '<' || c == '>')
    {
        startp = &buf->b_visual.vi_start;
        endp = &buf->b_visual.vi_end;
        if (((c == '<') ==  (((*startp).lnum != (*endp).lnum)               ? (*startp).lnum < (*endp).lnum                   : (*startp).col != (*endp).col                        ? (*startp).col < (*endp).col                     : (*startp).coladd < (*endp).coladd)  || endp->lnum == 0) && startp->lnum != 0)
        {
            posp = startp;
        }
        else
        {
            posp = endp;
        }
        if (buf->b_visual.vi_mode == 'V')
        {
            pos_copy = *posp;
            posp = &pos_copy;
            if (c == '<')
            {
                pos_copy.col = 0;
            }
            else
            {
                pos_copy.col = MAXCOL;
            }
            pos_copy.coladd = 0;
        }
    }
    else if ( ((unsigned)(c) - 'a' < 26) )
    {
        posp = &(buf->b_namedm[c - 'a']);
    }
    else if ( ((unsigned)(c) - 'A' < 26)  ||  ((unsigned)(c) - '0' < 10) )
    {
        if ( ((unsigned)(c) - '0' < 10) )
        {
            c = c - '0' +  ('z' - 'a' + 1) ;
        }
        else
        {
            c -= 'A';
        }
        posp = &(namedfm[c].fmark.mark);

        if (namedfm[c].fmark.fnum == 0)
        {
            fname2fnum(&namedfm[c]);
        }

        if (fnum != NULL)
        {
            *fnum = namedfm[c].fmark.fnum;
        }
        else if (namedfm[c].fmark.fnum != buf->b_fnum)
        {
            posp = &pos_copy;

            if (namedfm[c].fmark.mark.lnum != 0 && changefile && namedfm[c].fmark.fnum)
            {
                if (buflist_getfile(namedfm[c].fmark.fnum, (linenr_T)1, GETF_SETMARK, FALSE) == OK)
                {
                    curwin->w_cursor = namedfm[c].fmark.mark;
                    return (pos_T *)-1;
                }
                pos_copy.lnum = -1;
            }
            else
            {
                pos_copy.lnum = 0;
            }
        }
    }

    return posp;
}

    static pos_T *
getnextmark(pos_T       *startpos, int         dir, int         begin_line)
{
    int         i;
    pos_T       *result = NULL;
    pos_T       pos;

    pos = *startpos;

    if (dir ==  (-1)  && begin_line)
    {
        pos.col = 0;
    }
    else if (dir == FORWARD && begin_line)
    {
        pos.col = MAXCOL;
    }

    for (i = 0; i <  ('z' - 'a' + 1) ; i++)
    {
        if (curbuf->b_namedm[i].lnum > 0)
        {
            if (dir == FORWARD)
            {
                if ((result == NULL ||  (((curbuf->b_namedm[i]).lnum != (*result).lnum)               ? (curbuf->b_namedm[i]).lnum < (*result).lnum                   : (curbuf->b_namedm[i]).col != (*result).col                        ? (curbuf->b_namedm[i]).col < (*result).col                     : (curbuf->b_namedm[i]).coladd < (*result).coladd) ) &&  (((pos).lnum != (curbuf->b_namedm[i]).lnum)               ? (pos).lnum < (curbuf->b_namedm[i]).lnum                   : (pos).col != (curbuf->b_namedm[i]).col                        ? (pos).col < (curbuf->b_namedm[i]).col                     : (pos).coladd < (curbuf->b_namedm[i]).coladd) )
                {
                    result = &curbuf->b_namedm[i];
                }
            }
            else
            {
                if ((result == NULL ||  (((*result).lnum != (curbuf->b_namedm[i]).lnum)               ? (*result).lnum < (curbuf->b_namedm[i]).lnum                   : (*result).col != (curbuf->b_namedm[i]).col                        ? (*result).col < (curbuf->b_namedm[i]).col                     : (*result).coladd < (curbuf->b_namedm[i]).coladd) ) &&  (((curbuf->b_namedm[i]).lnum != (pos).lnum)               ? (curbuf->b_namedm[i]).lnum < (pos).lnum                   : (curbuf->b_namedm[i]).col != (pos).col                        ? (curbuf->b_namedm[i]).col < (pos).col                     : (curbuf->b_namedm[i]).coladd < (pos).coladd) )
                {
                    result = &curbuf->b_namedm[i];
                }
            }
        }
    }

    return result;
}

    static void
fname2fnum(xfmark_T *fm)
{
    char_u      *p;

    if (fm->fname == NULL)
    {
        return;
    }

    if (fm->fname[0] == '~' && (fm->fname[1] == '/'))
    {
        size_t len;

        len = expand_env((char_u *)"~/", NameBuff,  PATH_MAX );
        vim_strncpy(NameBuff + len, fm->fname + 2,  PATH_MAX  - len - 1);
    }
    else
    {
        vim_strncpy(NameBuff, fm->fname,  PATH_MAX  - 1);
    }

    mch_dirname(IObuff,  (1024+1) );
    p = shorten_fname(NameBuff, IObuff);

    (void)buflist_new(NameBuff, p, (linenr_T)1, 0);
}

    static void
fmarks_check_names(buf_T *buf)
{
    char_u      *name;
    int         i;
    win_T       *wp;

    if (buf->b_ffname == NULL)
    {
        return;
    }

    name = home_replace_save(buf, buf->b_ffname);
    if (name == NULL)
    {
        return;
    }

    for (i = 0; i <  ('z' - 'a' + 1)  + EXTRA_MARKS; ++i)
    {
        fmarks_check_one(&namedfm[i], name, buf);
    }

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
    {
        for (i = 0; i < wp->w_jumplistlen; ++i)
        {
            fmarks_check_one(&wp->w_jumplist[i], name, buf);
        }
    }

    vim_free(name);
}

    static void
fmarks_check_one(xfmark_T *fm, char_u *name, buf_T *buf)
{
    if (fm->fmark.fnum == 0 && fm->fname != NULL &&  vim_fnamecmp((char_u *)(name), (char_u *)(fm->fname))  == 0)
    {
        fm->fmark.fnum = buf->b_fnum;
         vim_free(fm->fname);
         (fm->fname) = NULL;
    }
}

    static int
check_mark(pos_T *pos)
{
    if (pos == NULL)
    {
        emsg(_(e_unknown_mark));
        return FAIL;
    }
    if (pos->lnum <= 0)
    {
        if (pos->lnum == 0)
        {
            emsg(_(e_mark_not_set));
        }
        return FAIL;
    }
    if (pos->lnum > curbuf->b_ml.ml_line_count)
    {
        emsg(_(e_mark_has_invalid_line_number));
        return FAIL;
    }
    return OK;
}

    static void
clrallmarks(buf_T *buf)
{
    static int          i = -1;

    if (i == -1)
    {
        for (i = 0; i <  ('z' - 'a' + 1)  + 1; i++)
        {
            namedfm[i].fmark.mark.lnum = 0;
            namedfm[i].fname = NULL;
        }
    }

    for (i = 0; i <  ('z' - 'a' + 1) ; i++)
    {
        buf->b_namedm[i].lnum = 0;
    }
    buf->b_op_start.lnum = 0;
    buf->b_op_end.lnum = 0;
    buf->b_last_cursor.lnum = 1;
    buf->b_last_cursor.col = 0;
    buf->b_last_cursor.coladd = 0;
    buf->b_last_insert.lnum = 0;
    buf->b_last_change.lnum = 0;
    buf->b_changelistlen = 0;
}

    static char_u *
fm_getname(fmark_T *fmark, int lead_len)
{
    if (fmark->fnum == curbuf->b_fnum)
    {
        return mark_line(&(fmark->mark), lead_len);
    }
    return buflist_nr2name(fmark->fnum, FALSE, TRUE);
}

    static char_u *
mark_line(pos_T *mp, int lead_len)
{
    char_u *s;
    char_u *p;
    int         len;

    if (mp->lnum == 0 || mp->lnum > curbuf->b_ml.ml_line_count)
    {
        return vim_strsave((char_u *)"-invalid-");
    }
    s = vim_strnsave(skipwhite(ml_get(mp->lnum)), Columns * 5);
    if (s == NULL)
    {
        return NULL;
    }
    len = 0;
    for (p = s; *p != NUL;  p += (*mb_ptr2len)(p) )
    {
        len += ptr2cells(p);
        if (len >= Columns - lead_len)
        {
            break;
        }
    }
    *p = NUL;
    return s;
}

    static void
ex_marks(exarg_T *eap)
{
    char_u      *arg = eap->arg;
    int         i;
    char_u      *name;
    pos_T *posp;
    pos_T *startp;
    pos_T *endp;

    if (arg != NULL && *arg == NUL)
    {
        arg = NULL;
    }

    show_one_mark('\'', arg, &curwin->w_pcmark, NULL, TRUE);
    for (i = 0; i <  ('z' - 'a' + 1) ; ++i)
    {
        show_one_mark(i + 'a', arg, &curbuf->b_namedm[i], NULL, TRUE);
    }
    for (i = 0; i <  ('z' - 'a' + 1)  + EXTRA_MARKS; ++i)
    {
        if (namedfm[i].fmark.fnum != 0)
        {
            name = fm_getname(&namedfm[i].fmark, 15);
        }
        else
        {
            name = namedfm[i].fname;
        }
        if (name != NULL)
        {
            show_one_mark(i >=  ('z' - 'a' + 1)  ? i -  ('z' - 'a' + 1)  + '0' : i + 'A', arg, &namedfm[i].fmark.mark, name, namedfm[i].fmark.fnum == curbuf->b_fnum);
            if (namedfm[i].fmark.fnum != 0)
            {
                vim_free(name);
            }
        }
    }
    show_one_mark('"', arg, &curbuf->b_last_cursor, NULL, TRUE);
    show_one_mark('[', arg, &curbuf->b_op_start, NULL, TRUE);
    show_one_mark(']', arg, &curbuf->b_op_end, NULL, TRUE);
    show_one_mark('^', arg, &curbuf->b_last_insert, NULL, TRUE);
    show_one_mark('.', arg, &curbuf->b_last_change, NULL, TRUE);

    startp = &curbuf->b_visual.vi_start;
    endp = &curbuf->b_visual.vi_end;
    if (( (((*startp).lnum != (*endp).lnum)               ? (*startp).lnum < (*endp).lnum                   : (*startp).col != (*endp).col                        ? (*startp).col < (*endp).col                     : (*startp).coladd < (*endp).coladd)  || endp->lnum == 0) && startp->lnum != 0)
    {
        posp = startp;
    }
    else
    {
        posp = endp;
    }
    show_one_mark('<', arg, posp, NULL, TRUE);
    show_one_mark('>', arg, posp == startp ? endp : startp, NULL, TRUE);

    show_one_mark(-1, arg, NULL, NULL, FALSE);
}

    static void
show_one_mark(int         c, char_u      *arg, pos_T       *p, char_u      *name_arg, int         current)
{
    static int  did_title = FALSE;
    int         mustfree = FALSE;
    char_u      *name = name_arg;

    if (c == -1)
    {
        if (did_title)
        {
            did_title = FALSE;
        }
        else
        {
            if (arg == NULL)
            {
                msg(_("No marks set"));
            }
            else
            {
                semsg(_(e_no_marks_matching_str), arg);
            }
        }
    }
    else if (!got_int && (arg == NULL || vim_strchr(arg, c) != NULL) && p->lnum != 0)
    {
        if (name == NULL && current)
        {
            name = mark_line(p, 15);
            if (name == NULL)
            {
                emsg(_(e_out_of_memory));
                return;
            }
            mustfree = TRUE;
        }
        if (!message_filtered(name))
        {
            if (!did_title)
            {
                msg_puts_title(_("\nmark line  col file/text"));
                did_title = TRUE;
            }
            msg_putchar('\n');
            if (!got_int)
            {
                sprintf((char *)IObuff, " %c %6ld %4d ", c, p->lnum, p->col);
                msg_outtrans(IObuff);
                if (name != NULL)
                {
                    msg_outtrans_attr(name, current ?  highlight_attr[(int)(HLF_D)]  : 0);
                }
            }
            out_flush();
        }
        if (mustfree)
        {
            vim_free(name);
        }
    }
}

    static void
ex_delmarks(exarg_T *eap)
{
    char_u      *p;
    int from;
    int to;
    int         i;
    int         lower;
    int         digit;
    int         n;

    if (*eap->arg == NUL && eap->forceit)
    {
        clrallmarks(curbuf);
    }
    else if (eap->forceit)
    {
        emsg(_(e_invalid_argument));
    }
    else if (*eap->arg == NUL)
    {
        emsg(_(e_argument_required));
    }
    else
    {
        for (p = eap->arg; *p != NUL; ++p)
        {
            lower =  ((unsigned)(*p) - 'a' < 26) ;
            digit =  ((unsigned)(*p) - '0' < 10) ;
            if (lower || digit ||  ((unsigned)(*p) - 'A' < 26) )
            {
                if (p[1] == '-')
                {
                    from = *p;
                    to = p[2];
                    if (!(lower ?  ((unsigned)(p[2]) - 'a' < 26)  : (digit ?  ((unsigned)(p[2]) - '0' < 10)  :  ((unsigned)(p[2]) - 'A' < 26) )) || to < from)
                    {
                        semsg(_(e_invalid_argument_str), p);
                        return;
                    }
                    p += 2;
                }
                else
                {
                    from = to = *p;
                }

                for (i = from; i <= to; ++i)
                {
                    if (lower)
                    {
                        curbuf->b_namedm[i - 'a'].lnum = 0;
                    }
                    else
                    {
                        if (digit)
                        {
                            n = i - '0' +  ('z' - 'a' + 1) ;
                        }
                        else
                        {
                            n = i - 'A';
                        }
                        namedfm[n].fmark.mark.lnum = 0;
                        namedfm[n].fmark.fnum = 0;
                         vim_free(namedfm[n].fname);
                         (namedfm[n].fname) = NULL;
                    }
                }
            }
            else
            {
                switch (*p)
                {
                    case '"':
                        curbuf->b_last_cursor.lnum = 0;
                        break;
                    case '^':
                        curbuf->b_last_insert.lnum = 0;
                        break;
                    case '.':
                        curbuf->b_last_change.lnum = 0;
                        break;
                    case '[':
                        curbuf->b_op_start.lnum    = 0;
                        break;
                    case ']':
                        curbuf->b_op_end.lnum      = 0;
                        break;
                    case '<':
                        curbuf->b_visual.vi_start.lnum = 0;
                        break;
                    case '>':
                        curbuf->b_visual.vi_end.lnum   = 0;
                        break;
                    case ' ':
                        break;
                    default:
                        semsg(_(e_invalid_argument_str), p);
                              return;
                }
            }
        }
    }
}

    static void
ex_jumps(exarg_T *eap  __attribute__((unused)) )
{
    int         i;
    char_u      *name;

    cleanup_jumplist(curwin, TRUE);

    msg_puts_title(_("\n jump line  col file/text"));
    for (i = 0; i < curwin->w_jumplistlen && !got_int; ++i)
    {
        if (curwin->w_jumplist[i].fmark.mark.lnum != 0)
        {
            name = fm_getname(&curwin->w_jumplist[i].fmark, 16);

            if (name == NULL && i == curwin->w_jumplistidx)
            {
                name = vim_strsave((char_u *)"-invalid-");
            }
            if (name == NULL || message_filtered(name))
            {
                vim_free(name);
                continue;
            }

            msg_putchar('\n');
            if (got_int)
            {
                vim_free(name);
                break;
            }
            sprintf((char *)IObuff, "%c %2d %5ld %4d ", i == curwin->w_jumplistidx ? '>' : ' ', i > curwin->w_jumplistidx ? i - curwin->w_jumplistidx : curwin->w_jumplistidx - i, curwin->w_jumplist[i].fmark.mark.lnum, curwin->w_jumplist[i].fmark.mark.col);
            msg_outtrans(IObuff);
            msg_outtrans_attr(name, curwin->w_jumplist[i].fmark.fnum == curbuf->b_fnum ?  highlight_attr[(int)(HLF_D)]  : 0);
            vim_free(name);
            ui_breakcheck();
        }
        out_flush();
    }
    if (curwin->w_jumplistidx == curwin->w_jumplistlen)
    {
        msg_puts("\n>");
    }
}

    static void
ex_clearjumps(exarg_T *eap  __attribute__((unused)) )
{
    free_jumplist(curwin);
    curwin->w_jumplistlen = 0;
    curwin->w_jumplistidx = 0;
}

    static void
ex_changes(exarg_T *eap  __attribute__((unused)) )
{
    int         i;
    char_u      *name;

    msg_puts_title(_("\nchange line  col text"));

    for (i = 0; i < curbuf->b_changelistlen && !got_int; ++i)
    {
        if (curbuf->b_changelist[i].lnum != 0)
        {
            msg_putchar('\n');
            if (got_int)
            {
                break;
            }
            sprintf((char *)IObuff, "%c %3d %5ld %4d ", i == curwin->w_changelistidx ? '>' : ' ', i > curwin->w_changelistidx ? i - curwin->w_changelistidx : curwin->w_changelistidx - i, (long)curbuf->b_changelist[i].lnum, curbuf->b_changelist[i].col);
            msg_outtrans(IObuff);
            name = mark_line(&curbuf->b_changelist[i], 17);
            if (name == NULL)
            {
                break;
            }
            msg_outtrans_attr(name,  highlight_attr[(int)(HLF_D)] );
            vim_free(name);
            ui_breakcheck();
        }
        out_flush();
    }
    if (curwin->w_changelistidx == curbuf->b_changelistlen)
    {
        msg_puts("\n>");
    }
}

