     {   lp = &(curwin->w_pcmark.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = 0;            else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;

