                     {     lp = &(win->w_jumplist[i].fmark.mark.lnum);       if (*lp >= line1 && *lp <= line2)       {           if (amount ==  LONG_MAX )              *lp = line1;        else                *lp += amount;  }       else if (amount_after && *lp > line2)       *lp += amount_after;     } ;
