    static int
enc_canon_search(char_u *name)
{
    int         i;

    for (i = 0; i < IDX_COUNT; ++i)
    {
        if ( strcmp((char *)(name), (char *)(enc_canon_table[i].name))  == 0)
        {
            return i;
        }
    }
    return -1;
}

    static int
enc_canon_props(char_u *name)
{
    int         i;

    i = enc_canon_search(name);
    if (i >= 0)
    {
        return enc_canon_table[i].prop;
    }
    if ( strncmp((char *)(name), (char *)("2byte-"), (6))  == 0)
    {
        return ENC_DBCS;
    }
    if ( strncmp((char *)(name), (char *)("8bit-"), (5))  == 0 ||  strncmp((char *)(name), (char *)("iso-8859-"), (9))  == 0)
    {
        return ENC_8BIT;
    }
    return 0;
}

    static char *
mb_init(void)
{
    int         i;
    int         n;
    vimconv_T   vimconv;
    char_u      *p;

    if (p_enc == NULL)
    {
        for (i = 0; i < 256; ++i)
        {
            mb_bytelen_tab[i] = 1;
        }
        input_conv.vc_type = CONV_NONE;
        input_conv.vc_factor = 1;
        output_conv.vc_type = CONV_NONE;
        return NULL;
    }

    if ( strcmp((char *)(p_enc), (char *)("utf-8"))  != 0)
    {
        return e_invalid_argument;
    }

    enc_unicode = 0;
    enc_utf8 = TRUE;
    enc_dbcs = 0;
    has_mbyte = TRUE;
    enc_latin1like = TRUE;

    mb_ptr2len = utfc_ptr2len;
    mb_ptr2len_len = utfc_ptr2len_len;
    mb_char2len = utf_char2len;
    mb_char2bytes = utf_char2bytes;
    mb_ptr2cells = utf_ptr2cells;
    mb_ptr2cells_len = utf_ptr2cells_len;
    mb_char2cells = utf_char2cells;
    mb_off2cells = utf_off2cells;
    mb_ptr2char = utf_ptr2char;
    mb_head_off = utf_head_off;
    vimconv.vc_type = CONV_NONE;
for (i = 0; i < 256; ++i)
    {
        if (enc_utf8)
        {
            n = utf8len_tab[i];
        }
        else if (enc_dbcs == 0)
        {
            n = 1;
        }
        else
        {
            char buf[MB_MAXBYTES + 1];

            if (i == NUL)
            {
                n = 1;
            }
            else
            {
                buf[0] = i;
                buf[1] = 0;
                if (vimconv.vc_type != CONV_NONE)
                {
                    p = string_convert(&vimconv, (char_u *)buf, NULL);
                    if (p != NULL)
                    {
                        vim_free(p);
                        n = 1;
                    }
                    else
                    {
                        n = 2;
                    }
                }
                else
                {
                    vim_ignored = mblen(NULL, 0);
                    if (mblen(buf, (size_t)1) <= 0)
                    {
                        n = 2;
                    }
                    else
                    {
                        n = 1;
                    }
                }
            }
        }

        mb_bytelen_tab[i] = n;
    }

    convert_setup(&vimconv, NULL, NULL);

    (void)init_chartab();

    screenalloc(FALSE);

    apply_autocmds(EVENT_ENCODINGCHANGED, NULL, (char_u *)"", FALSE, curbuf);

    return NULL;
}

