bomb_size(void)
{
    return 0;
}

    static int
mb_get_class(char_u *p)
{
    return mb_get_class_buf(p, curbuf);
}

    static int
mb_get_class_buf(char_u *p, buf_T *buf)
{
    if ( mb_bytelen_tab[p[0]]  == 1)
    {
        if (p[0] == NUL ||  ((p[0]) == ' ' || (p[0]) == '\t') )
        {
            return 0;
        }
        if (vim_iswordc_buf(p[0], buf))
        {
            return 2;
        }
        return 1;
    }
    if (enc_dbcs != 0 && p[0] != NUL && p[1] != NUL)
    {
        return dbcs_class(p[0], p[1]);
    }
    if (enc_utf8)
    {
        return utf_class_buf(utf_ptr2char(p), buf);
    }
    return 0;
}

    static int
dbcs_class(unsigned lead, unsigned trail)
{
    switch (enc_dbcs)
    {
        case DBCS_JPNU:
        case DBCS_JPN:
            {
                unsigned char lb = lead;
                unsigned char tb = trail;

                lb &= 0x7f;
                tb &= 0x7f;
                switch (lb << 8 | tb)
                {
                    case 0x2121:
                        return 0;
                    case 0x2122:
                    case 0x2123:
                    case 0x2124:
                    case 0x2125:
                        return 1;
                    case 0x213c:
                        return 13;
                }
                switch (lb)
                {
                    case 0x21:
                    case 0x22:
                        return 10;
                    case 0x23:
                        return 11;
                    case 0x24:
                        return 12;
                    case 0x25:
                        return 13;
                    case 0x26:
                        return 14;
                    case 0x27:
                        return 15;
                    case 0x28:
                        return 16;
                    default:
                        return 17;
                }
            }

        case DBCS_KORU:
        case DBCS_KOR:
            {
                unsigned char c1 = lead;
                unsigned char c2 = trail;

                if (c1 >= 0xB0 && c1 <= 0xC8)
                {
                    return 20;
                }

                else if (c1 >= 0xCA && c1 <= 0xFD)
                {
                    return 21;
                }
                else
                {
                    switch (c1)
                {
                    case 0xA1:
                    case 0xA2:
                        return 22;
                    case 0xA3:
                        return 23;
                    case 0xA4:
                        return 24;
                    case 0xA5:
                        return 25;
                    case 0xA6:
                        return 26;
                    case 0xA7:
                        return 27;
                    case 0xA8:
                    case 0xA9:
                        if (c2 <= 0xAF)
                        {
                            return 25;
                        }
                        else if (c2 >= 0xF6)
                        {
                            return 22;
                        }
                        else
                        {
                            return 28;
                        }
                    case 0xAA:
                    case 0xAB:
                        return 29;
                    case 0xAC:
                        return 30;
                }
                }
            }
        default:
            break;
    }
    return 3;
}

    static int
latin_char2len(int c  __attribute__((unused)) )
{
    return 1;
}

    static int
latin_char2bytes(int c, char_u *buf)
{
    buf[0] = c;
    return 1;
}

    static int
latin_ptr2len(char_u *p)
{
    return *p == NUL ? 0 : 1;
}

    static int
dbcs_ptr2len(char_u *p)
{
    int         len;

    if (*p == NUL)
    {
        return 0;
    }

    len =  mb_bytelen_tab[*p] ;
    if (len == 2 && p[1] == NUL)
    {
        len = 1;
    }
    return len;
}

    static int
latin_ptr2len_len(char_u *p, int size)
{
    if (size < 1 || *p == NUL)
    {
        return 0;
    }
    return 1;
}

struct interval
{
    long first;
    long last;
};

    static int
intable(struct interval *table, size_t size, int c)
{
    int mid;
    int bot;
    int top;

    if (c < table[0].first)
    {
        return FALSE;
    }

    bot = 0;
    top = (int)(size / sizeof(struct interval) - 1);
    while (top >= bot)
    {
        mid = (bot + top) / 2;
        if (table[mid].last < c)
        {
            bot = mid + 1;
        }
        else if (table[mid].first > c)
        {
            top = mid - 1;
        }
        else
        {
            return TRUE;
        }
    }
    return FALSE;
}

