    static int
latin_ptr2cells(char_u *p  __attribute__((unused)) )
{
    return 1;
}

    static int
utf_ptr2cells(char_u      *p)
{
    int         c;
    int         len;

    if (*p >= 0x80)
    {
        c = utf_ptr2char_and_len(p, &len);
        if (len == 1 || c == NUL)
        {
            return 4;
        }
        if (c < 0x80)
        {
            return vim_isprintc(c) ? char2cells(c) : 4;
        }
        return utf_char2cells(c);
    }
    return 1;
}

    static int
latin_ptr2cells_len(char_u *p  __attribute__((unused)) , int size  __attribute__((unused)) )
{
    return 1;
}

    static int
utf_ptr2cells_len(char_u *p, int size)
{
    int         c;
    int         len;

    if (size > 0 && *p >= 0x80)
    {
        c = utf_ptr2char_and_len_len(p, size, &len);
        if (len > size)
        {
            return 1;
        }
        if (len == 1 || c == NUL)
        {
            return 4;
        }
        if (c < 0x80)
        {
            return vim_isprintc(c) ? char2cells(c) : 4;
        }
        return utf_char2cells(c);
    }
    return 1;
}

    static int
latin_char2cells(int c  __attribute__((unused)) )
{
    return 1;
}

    static int
mb_string2cells(char_u *p, int len)
{
    int i;
    int clen = 0;

    for (i = 0; (len < 0 || i < len) && p[i] != NUL; i += (*mb_ptr2len)(p + i))
    {
        clen += (*mb_ptr2cells)(p + i);
    }
    return clen;
}

    static int
latin_off2cells(unsigned off  __attribute__((unused)) , unsigned max_off  __attribute__((unused)) )
{
    return 1;
}

    static int
dbcs_off2cells(unsigned off, unsigned max_off)
{
    if (off >= max_off)
    {
        return 1;
    }

    if (enc_dbcs == DBCS_JPNU && ScreenLines[off] == 0x8e)
    {
        return 1;
    }
    return  mb_bytelen_tab[ScreenLines[off]] ;
}

    static int
utf_off2cells(unsigned off, unsigned max_off)
{
    return (off + 1 < max_off && ScreenLines[off + 1] == 0) ? 2 : 1;
}

    static int
latin_ptr2char(char_u *p)
{
    return *p;
}

    static inline int
utf_ptr2char_and_len(char_u *p, int *lenp)
{
    int         len;
    int         c;

    if (p[0] < 0x80)
    {
        *lenp = p[0] == NUL ? 0 : 1;
        return p[0];
    }

    len = utf8len_tab_zero[p[0]];
    if (len <= 1 || (p[1] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x1f) << 6) + (p[1] & 0x3f);
    if (len == 2)
    {
        *lenp = 2;
        return c;
    }
    if ((p[2] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x0f) << 12) + ((p[1] & 0x3f) << 6) + (p[2] & 0x3f);
    if (len == 3)
    {
        *lenp = 3;
        return c;
    }
    if ((p[3] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x07) << 18) + ((p[1] & 0x3f) << 12)
                                 + ((p[2] & 0x3f) << 6) + (p[3] & 0x3f);
    if (len == 4)
    {
        *lenp = 4;
        return c;
    }
    if ((p[4] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x03) << 24) + ((p[1] & 0x3f) << 18)
                                + ((p[2] & 0x3f) << 12)
                                + ((p[3] & 0x3f) << 6) + (p[4] & 0x3f);
    if (len == 5)
    {
        *lenp = 5;
        return c;
    }
    if ((p[5] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    *lenp = 6;
    return ((p[0] & 0x01) << 30) + ((p[1] & 0x3f) << 24)
                                + ((p[2] & 0x3f) << 18)
                                + ((p[3] & 0x3f) << 12)
                                + ((p[4] & 0x3f) << 6) + (p[5] & 0x3f);
}

    static inline int
utf_ptr2char_and_len_len(char_u *p, int size, int *lenp)
{
    int         len;
    int         c;

    if (size < 1)
    {
        *lenp = 1;
        return NUL;
    }
    if (p[0] < 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    len = utf8len_tab_zero[p[0]];
    if (len <= 1)
    {
        *lenp = 1;
        return p[0];
    }
    if (len > size)
    {
        int             i;

        for (i = 1; i < size; ++i)
        {
            if ((p[i] & 0xc0) != 0x80)
            {
                *lenp = 1;
                return p[0];
            }
        }
        *lenp = len;
        return p[0];
    }
    if ((p[1] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x1f) << 6) + (p[1] & 0x3f);
    if (len == 2)
    {
        *lenp = 2;
        return c;
    }
    if ((p[2] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x0f) << 12) + ((p[1] & 0x3f) << 6) + (p[2] & 0x3f);
    if (len == 3)
    {
        *lenp = 3;
        return c;
    }
    if ((p[3] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x07) << 18) + ((p[1] & 0x3f) << 12)
                                 + ((p[2] & 0x3f) << 6) + (p[3] & 0x3f);
    if (len == 4)
    {
        *lenp = 4;
        return c;
    }
    if ((p[4] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    c = ((p[0] & 0x03) << 24) + ((p[1] & 0x3f) << 18)
                                + ((p[2] & 0x3f) << 12)
                                + ((p[3] & 0x3f) << 6) + (p[4] & 0x3f);
    if (len == 5)
    {
        *lenp = 5;
        return c;
    }
    if ((p[5] & 0xc0) != 0x80)
    {
        *lenp = 1;
        return p[0];
    }

    *lenp = 6;
    return ((p[0] & 0x01) << 30) + ((p[1] & 0x3f) << 24)
                                + ((p[2] & 0x3f) << 18)
                                + ((p[3] & 0x3f) << 12)
                                + ((p[4] & 0x3f) << 6) + (p[5] & 0x3f);
}

    static inline int
utf_iscomposinglike_char(int c1, int c2)
{
    if (utf_iscomposing(c2))
    {
        return TRUE;
    }
    (void)c1;
    return FALSE;
}

    static int
utf_ptr2char(char_u *p)
{
    int         len;

    return utf_ptr2char_and_len(p, &len);
}

    static int
utf_safe_read_char_adv(char_u **s, size_t *n)
{
    int c;
    int k;

    if (*n == 0)
    {
        return 0;
    }

    k = utf8len_tab_zero[**s];

    if (k == 1)
    {
        (*n)--;
        return *(*s)++;
    }

    if ((size_t)k <= *n)
    {
        c = utf_ptr2char(*s);

        if (c != (int)(**s) || (c == 0xC3 && (*s)[1] == 0x83))
        {
            *s += k;
            *n -= k;
            return c;
        }
    }

    return -1;
}

    static int
mb_ptr2char_adv(char_u **pp)
{
    int         c;

    c = (*mb_ptr2char)(*pp);
    *pp += (*mb_ptr2len)(*pp);
    return c;
}

    static int
mb_cptr2char_adv(char_u **pp)
{
    int         c;

    c = (*mb_ptr2char)(*pp);
    if (enc_utf8)
    {
        *pp += utf_ptr2len(*pp);
    }
    else
    {
        *pp += (*mb_ptr2len)(*pp);
    }
    return c;
}

    static int
utfc_ptr2char(char_u      *p, int         *pcc)
{
    int         len;
    int         c;
    int         cc;
    int         cc_len;
    int         i = 0;

    c = utf_ptr2char_and_len(p, &len);

    if ((len > 1 || *p < 0x80) && p[len] >= 0x80)
    {
        cc = utf_ptr2char_and_len(p + len, &cc_len);
        if (utf_iscomposinglike_char(c, cc))
        {
            for (;;)
            {
                pcc[i++] = cc;
                if (i == MAX_MCO)
                {
                    break;
                }
                len += cc_len;
                if (p[len] < 0x80)
                {
                    break;
                }
                cc = utf_ptr2char_and_len(p + len, &cc_len);
                if (!utf_iscomposing(cc))
                {
                    break;
                }
            }
        }
    }

    if (i < MAX_MCO)
    {
        pcc[i] = 0;
    }

    return c;
}

    static int
utfc_ptr2char_len(char_u      *p, int         *pcc, int         maxlen)
{
    int         len;
    int         c;
    int         cc;
    int         cc_len;
    int         i = 0;

    c = utf_ptr2char_and_len_len(p, maxlen, &len);
    if ((len > 1 || *p < 0x80) && len < maxlen && p[len] >= 0x80)
    {
        cc = utf_ptr2char_and_len_len(p + len, maxlen - len, &cc_len);
        if (cc_len <= maxlen - len && utf_iscomposinglike_char(c, cc))
        {
            for (;;)
            {
                pcc[i++] = cc;
                if (i == MAX_MCO)
                {
                    break;
                }
                len += cc_len;
                if (len >= maxlen || p[len] < 0x80)
                {
                    break;
                }
                cc = utf_ptr2char_and_len_len(p + len, maxlen - len, &cc_len);
                if (cc_len > maxlen - len || !utf_iscomposing(cc))
                {
                    break;
                }
            }
        }
    }

    if (i < MAX_MCO)
    {
        pcc[i] = 0;
    }

    return c;
}

    static int
utfc_char2bytes(int off, char_u *buf)
{
    int         len;
    int         i;

    len = utf_char2bytes(ScreenLinesUC[off], buf);
    for (i = 0; i < Screen_mco; ++i)
    {
        if (ScreenLinesC[i][off] == 0)
        {
            break;
        }
        len += utf_char2bytes(ScreenLinesC[i][off], buf + len);
    }
    return len;
}

    static int
utf_ptr2len(char_u *p)
{
    int         len;

    utf_ptr2char_and_len(p, &len);
    return len;
}

    static int
utf_byte2len(int b)
{
    return utf8len_tab[b];
}

    static int
utf_ptr2len_len(char_u *p, int size)
{
    int         len;

    utf_ptr2char_and_len_len(p, size, &len);
    return len;
}

    static int
utfc_ptr2len(char_u *p)
{
    int         len;
    int         c;
    int         cc;
    int         cc_len;
    int         b0 = *p;

    if (b0 == NUL)
    {
        return 0;
    }
    if (b0 < 0x80 && p[1] < 0x80)
    {
        return 1;
    }

    c = utf_ptr2char_and_len(p, &len);

    if (len == 1 && b0 >= 0x80)
    {
        return 1;
    }

    if (p[len] < 0x80)
    {
        return len;
    }

    cc = utf_ptr2char_and_len(p + len, &cc_len);
    if (!utf_iscomposinglike_char(c, cc))
    {
        return len;
    }

    for (;;)
    {
        len += cc_len;
        if (p[len] < 0x80)
        {
            return len;
        }
        cc = utf_ptr2char_and_len(p + len, &cc_len);
        if (!utf_iscomposing(cc))
        {
            return len;
        }
    }
}

    static int
utfc_ptr2len_len(char_u *p, int size)
{
    int         len;
    int         c;
    int         cc;
    int         cc_len;

    if (size < 1 || *p == NUL)
    {
        return 0;
    }
    if (p[0] < 0x80 && (size == 1 || p[1] < 0x80))
    {
        return 1;
    }

    c = utf_ptr2char_and_len_len(p, size, &len);

    if ((len == 1 && p[0] >= 0x80) || len > size)
    {
        return 1;
    }

    if (len >= size || p[len] < 0x80)
    {
        return len;
    }

    cc = utf_ptr2char_and_len_len(p + len, size - len, &cc_len);
    if (cc_len > size - len || !utf_iscomposinglike_char(c, cc))
    {
        return len;
    }

    while (len < size)
    {
        len += cc_len;
        if (len >= size || p[len] < 0x80)
        {
            break;
        }
        cc = utf_ptr2char_and_len_len(p + len, size - len, &cc_len);
        if (cc_len > size - len)
        {
            break;
        }
        if (!utf_iscomposing(cc))
        {
            break;
        }
    }
    return len;
}

    static int
utf_char2len(int c)
{
    if (c < 0x80)
    {
        return 1;
    }
    if (c < 0x800)
    {
        return 2;
    }
    if (c < 0x10000)
    {
        return 3;
    }
    if (c < 0x200000)
    {
        return 4;
    }
    if (c < 0x4000000)
    {
        return 5;
    }
    return 6;
}

    static int
utf_char2bytes(int c, char_u *buf)
{
    if (c < 0x80)
    {
        buf[0] = c;
        return 1;
    }
    if (c < 0x800)
    {
        buf[0] = 0xc0 + ((unsigned)c >> 6);
        buf[1] = 0x80 + (c & 0x3f);
        return 2;
    }
    if (c < 0x10000)
    {
        buf[0] = 0xe0 + ((unsigned)c >> 12);
        buf[1] = 0x80 + (((unsigned)c >> 6) & 0x3f);
        buf[2] = 0x80 + (c & 0x3f);
        return 3;
    }
    if (c < 0x200000)
    {
        buf[0] = 0xf0 + ((unsigned)c >> 18);
        buf[1] = 0x80 + (((unsigned)c >> 12) & 0x3f);
        buf[2] = 0x80 + (((unsigned)c >> 6) & 0x3f);
        buf[3] = 0x80 + (c & 0x3f);
        return 4;
    }
    if (c < 0x4000000)
    {
        buf[0] = 0xf8 + ((unsigned)c >> 24);
        buf[1] = 0x80 + (((unsigned)c >> 18) & 0x3f);
        buf[2] = 0x80 + (((unsigned)c >> 12) & 0x3f);
        buf[3] = 0x80 + (((unsigned)c >> 6) & 0x3f);
        buf[4] = 0x80 + (c & 0x3f);
        return 5;
    }
    buf[0] = 0xfc + ((unsigned)c >> 30);
    buf[1] = 0x80 + (((unsigned)c >> 24) & 0x3f);
    buf[2] = 0x80 + (((unsigned)c >> 18) & 0x3f);
    buf[3] = 0x80 + (((unsigned)c >> 12) & 0x3f);
    buf[4] = 0x80 + (((unsigned)c >> 6) & 0x3f);
    buf[5] = 0x80 + (c & 0x3f);
    return 6;
}

