    static int
utf_toupper(int a)
{
    if (a < 128 && (cmp_flags & CMP_KEEPASCII))
    {
        return  (((a) < 'a' || (a) > 'z') ? (a) : (a) - ('a' - 'A')) ;
    }

    if (!(cmp_flags & CMP_INTERNAL))
    {
        return towupper(a);
    }

    if (a < 128)
    {
        return   (toupper ((unsigned char)(a))) ;
    }

    return utf_convert(a, toUpper, (int)sizeof(toUpper));
}

    static int
utf_islower(int a)
{
    return (utf_toupper(a) != a) || a == 0xdf;
}

    static int
utf_tolower(int a)
{
    if (a < 128 && (cmp_flags & CMP_KEEPASCII))
    {
        return  (((a) < 'A' || (a) > 'Z') ? (a) : (a) + ('a' - 'A')) ;
    }

    if (!(cmp_flags & CMP_INTERNAL))
    {
        return towlower(a);
    }

    if (a < 128)
    {
        return   (tolower ((unsigned char)(a))) ;
    }

    return utf_convert(a, toLower, (int)sizeof(toLower));
}

    static int
utf_isupper(int a)
{
    return (utf_tolower(a) != a);
}

    static int
utf_strnicmp(char_u      *s1, char_u      *s2, size_t      n1, size_t      n2)
{
    int c1;
    int c2;
    int cdiff;
    char_u      buffer[6];

    for (;;)
    {
        c1 = utf_safe_read_char_adv(&s1, &n1);
        c2 = utf_safe_read_char_adv(&s2, &n2);

        if (c1 <= 0 || c2 <= 0)
        {
            break;
        }

        if (c1 == c2)
        {
            continue;
        }

        cdiff = utf_fold(c1) - utf_fold(c2);
        if (cdiff != 0)
        {
            return cdiff;
        }
    }

    if (c1 == 0 || c2 == 0)
    {
        if (c1 == 0 && c2 == 0)
        {
            return 0;
        }
        return c1 == 0 ? -1 : 1;
    }

    if (c1 != -1 && c2 == -1)
    {
        n1 = utf_char2bytes(utf_fold(c1), buffer);
        s1 = buffer;
    }
    else if (c2 != -1 && c1 == -1)
    {
        n2 = utf_char2bytes(utf_fold(c2), buffer);
        s2 = buffer;
    }

    while (n1 > 0 && n2 > 0 && *s1 != NUL && *s2 != NUL)
    {
        cdiff = (int)(*s1) - (int)(*s2);
        if (cdiff != 0)
        {
            return cdiff;
        }

        s1++;
        s2++;
        n1--;
        n2--;
    }

    if (n1 > 0 && *s1 == NUL)
    {
        n1 = 0;
    }
    if (n2 > 0 && *s2 == NUL)
    {
        n2 = 0;
    }

    if (n1 == 0 && n2 == 0)
    {
        return 0;
    }
    return n1 == 0 ? -1 : 1;
}

    static int
mb_strnicmp2(char_u *s1, char_u *s2, size_t n1, size_t n2)
{
    if (n1 == n2 || !enc_utf8)
    {
        return mb_strnicmp(s1, s2, n1);
    }
    else
    {
        return utf_strnicmp(s1, s2, n1, n2);
    }
}

    static int
mb_strnicmp(char_u *s1, char_u *s2, size_t nn)
{
    int i;
    int l;
    int         cdiff;
    int         n = (int)nn;

    if (enc_utf8)
    {
        return utf_strnicmp(s1, s2, nn, nn);
    }
    else
    {
        for (i = 0; i < n; i += l)
        {
            if (s1[i] == NUL && s2[i] == NUL)
            {
                return 0;
            }

            l = (*mb_ptr2len)(s1 + i);
            if (l <= 1)
            {
                if (s1[i] != s2[i])
                {
                    cdiff =  vim_tolower(s1[i])  -  vim_tolower(s2[i]) ;
                    if (cdiff != 0)
                    {
                        return cdiff;
                    }
                }
            }
            else
            {
                if (l > n - i)
                {
                    l = n - i;
                }
                cdiff =  strncmp((char *)(s1 + i), (char *)(s2 + i), (l)) ;
                if (cdiff != 0)
                {
                    return cdiff;
                }
            }
        }
    }
    return 0;
}

    static void
show_utf8(void)
{
    int         len;
    int         rlen = 0;
    char_u      *line;
    int         clen;
    int         i;

    line = ml_get_cursor();
    len = utfc_ptr2len(line);
    if (len == 0)
    {
        msg("NUL");
        return;
    }

    clen = 0;
    for (i = 0; i < len; ++i)
    {
        if (clen == 0)
        {
            if (i > 0)
            {
                 strcpy((char *)(IObuff + rlen), (char *)("+ ")) ;
                rlen += 2;
            }
            clen = utf_ptr2len(line + i);
        }
        sprintf((char *)IObuff + rlen, "%02x ", (line[i] == NL) ? NUL : line[i]);
        --clen;
        rlen += (int) strlen((char *)(IObuff + rlen)) ;
        if (rlen >  (1024+1)  - 20)
        {
            break;
        }
    }

    msg((char *)IObuff);
}

    static int
latin_head_off(char_u *base  __attribute__((unused)) , char_u *p  __attribute__((unused)) )
{
    return 0;
}

    static int
dbcs_head_off(char_u *base, char_u *p)
{
    char_u      *q;

    if (p <= base ||  mb_bytelen_tab[p[-1]]  == 1 || *p == NUL)
    {
        return 0;
    }

    q = base;
    while (q < p)
    {
        q += dbcs_ptr2len(q);
    }
    return (q == p) ? 0 : 1;
}

    static int
dbcs_screen_head_off(char_u *base, char_u *p)
{
    char_u      *q;

    if (p <= base || (enc_dbcs == DBCS_JPNU && p[-1] == 0x8e) ||  mb_bytelen_tab[p[-1]]  == 1 || *p == NUL)
    {
        return 0;
    }

    q = base;
    while (q < p)
    {
        if (enc_dbcs == DBCS_JPNU && *q == 0x8e)
        {
            ++q;
        }
        else
        {
            q += dbcs_ptr2len(q);
        }
    }
    return (q == p) ? 0 : 1;
}

    static int
utf_head_off(char_u *base, char_u *p)
{
    char_u      *q;
    char_u      *s;
    int         c;
    int         len;

    if (*p < 0x80)
    {
        return 0;
    }

    for (q = p; ; --q)
    {
        for (s = q; (s[1] & 0xc0) == 0x80; ++s)
        {
            ;
        }
        while (q > base && (*q & 0xc0) == 0x80)
        {
            --q;
        }
        len = utf8len_tab[*q];
        if (len != (int)(s - q + 1) && len != (int)(p - q + 1))
        {
            return 0;
        }

        if (q <= base)
        {
            break;
        }

        c = utf_ptr2char(q);
        if (utf_iscomposing(c))
        {
            continue;
        }

        break;
    }

    return (int)(p - q);
}

    static int
utf_eat_space(int cc)
{
    return ((cc >= 0x2000 && cc <= 0x206F) || (cc >= 0x2e00 && cc <= 0x2e7f) || (cc >= 0x3000 && cc <= 0x303f) || (cc >= 0xff01 && cc <= 0xff0f) || (cc >= 0xff1a && cc <= 0xff20) || (cc >= 0xff3b && cc <= 0xff40) || (cc >= 0xff5b && cc <= 0xff65));
}

    static int
utf_allow_break_before(int cc)
{
    static const int BOL_prohibition_punct[] =
    {
        '!',
        '%',
        ')',
        ',',
        ':',
        ';',
        '>',
        '?',
        ']',
        '}',
        0x2019,
        0x201d,
        0x2020,
        0x2021,
        0x2026,
        0x2030,
        0x2031,
        0x203c,
        0x2047,
        0x2048,
        0x2049,
        0x2103,
        0x2109,
        0x3001,
        0x3002,
        0x3009,
        0x300b,
        0x300d,
        0x300f,
        0x3011,
        0x3015,
        0x3017,
        0x3019,
        0x301b,
        0xff01,
        0xff09,
        0xff0c,
        0xff0e,
        0xff1a,
        0xff1b,
        0xff1f,
        0xff3d,
        0xff5d,
    };

    int first = 0;
    int last  =  (sizeof(BOL_prohibition_punct) / sizeof((BOL_prohibition_punct)[0]))  - 1;
    int mid   = 0;

    while (first < last)
    {
        mid = (first + last)/2;

        if (cc == BOL_prohibition_punct[mid])
        {
            return FALSE;
        }
        else if (cc > BOL_prohibition_punct[mid])
        {
            first = mid + 1;
        }
        else
        {
            last = mid - 1;
        }
    }

    return cc != BOL_prohibition_punct[first];
}

    static int
utf_allow_break_after(int cc)
{
    static const int EOL_prohibition_punct[] =
    {
        '(',
        '<',
        '[',
        '`',
        '{',
        0x2018,
        0x201c,
        0x3008,
        0x300a,
        0x300c,
        0x300e,
        0x3010,
        0x3014,
        0x3016,
        0x3018,
        0x301a,
        0xff08,
        0xff3b,
        0xff5b,
    };

    int first = 0;
    int last  =  (sizeof(EOL_prohibition_punct) / sizeof((EOL_prohibition_punct)[0]))  - 1;
    int mid   = 0;

    while (first < last)
    {
        mid = (first + last)/2;

        if (cc == EOL_prohibition_punct[mid])
        {
            return FALSE;
        }
        else if (cc > EOL_prohibition_punct[mid])
        {
            first = mid + 1;
        }
        else
        {
            last = mid - 1;
        }
    }

    return cc != EOL_prohibition_punct[first];
}

    static int
utf_allow_break(int cc, int ncc)
{
    if (cc == ncc && (cc == 0x2014 || cc == 0x2026))
    {
        return FALSE;
    }

    return utf_allow_break_after(cc) && utf_allow_break_before(ncc);
}

    static void
mb_copy_char(char_u **fp, char_u **tp)
{
    int     l = (*mb_ptr2len)(*fp);

     memmove((char *)(*tp), (char *)(*fp), (size_t)l) ;
    *tp += l;
    *fp += l;
}

    static int
mb_off_next(char_u *base, char_u *p)
{
    int         head_off = (*mb_head_off)(base, p);

    if (head_off == 0)
    {
        return 0;
    }

    return (*mb_ptr2len)(p - head_off) - head_off;
}

    static int
mb_tail_off(char_u *base, char_u *p)
{
    int         i;
    int         j;

    if (*p == NUL)
    {
        return 0;
    }

    if (enc_utf8)
    {
        for (i = 0; (p[i + 1] & 0xc0) == 0x80; ++i)
        {
            ;
        }
        for (j = 0; p - j > base; ++j)
        {
            if ((p[-j] & 0xc0) != 0x80)
            {
                break;
            }
        }
        if (utf8len_tab[p[-j]] != i + j + 1)
        {
            return 0;
        }
        return i;
    }

    if (enc_dbcs == 0 || p[1] == NUL ||  mb_bytelen_tab[*p]  == 1)
    {
        return 0;
    }

    return 1 - dbcs_head_off(base, p);
}

    static void
utf_find_illegal(void)
{
    pos_T       pos = curwin->w_cursor;
    char_u      *p;
    int         len;
    vimconv_T   vimconv;
    char_u      *tofree = NULL;

    vimconv.vc_type = CONV_NONE;

    curwin->w_cursor.coladd = 0;
    for (;;)
    {
        p = ml_get_cursor();
        if (vimconv.vc_type != CONV_NONE)
        {
            vim_free(tofree);
            tofree = string_convert(&vimconv, p, NULL);
            if (tofree == NULL)
            {
                break;
            }
            p = tofree;
        }

        while (*p != NUL)
        {
            len = utf_ptr2len(p);
            if (*p >= 0x80 && (len == 1 || utf_char2len(utf_ptr2char(p)) != len))
            {
                if (vimconv.vc_type == CONV_NONE)
                {
                    curwin->w_cursor.col += (colnr_T)(p - ml_get_cursor());
                }
                else
                {
                    int     l;

                    len = (int)(p - tofree);
                    for (p = ml_get_cursor(); *p != NUL && len-- > 0; p += l)
                    {
                        l = utf_ptr2len(p);
                        curwin->w_cursor.col += l;
                    }
                }
                curwin->w_set_curswant = TRUE;
                goto theend;
            }
            p += len;
        }
        if (curwin->w_cursor.lnum == curbuf->b_ml.ml_line_count)
        {
            break;
        }
        ++curwin->w_cursor.lnum;
        curwin->w_cursor.col = 0;
    }

    curwin->w_cursor = pos;
    beep_flush();

theend:
    vim_free(tofree);
    convert_setup(&vimconv, NULL, NULL);
}

    static void
mb_adjust_cursor(void)
{
    mb_adjustpos(curbuf, &curwin->w_cursor);
}

    static void
mb_adjustpos(buf_T *buf, pos_T *lp)
{
    char_u      *p;

    if (lp->col > 0 || lp->coladd > 1)
    {
        p = ml_get_buf(buf, lp->lnum, FALSE);
        if (*p == NUL || ml_get_buf_len(buf, lp->lnum) < lp->col)
        {
            lp->col = 0;
        }
        else
        {
            lp->col -= (*mb_head_off)(p, p + lp->col);
        }
        if (lp->coladd == 1 && p[lp->col] != TAB && vim_isprintc((*mb_ptr2char)(p + lp->col)) && ptr2cells(p + lp->col) > 1)
        {
            lp->coladd = 0;
        }
    }
}

    static char_u *
mb_prevptr(char_u *line, char_u *p)
{
    if (p > line)
    {
         p -= has_mbyte ? ((*mb_head_off)(line, (p) - 1) + 1) : 1 ;
    }
    return p;
}

    static int
mb_charlen(char_u *str)
{
    char_u      *p = str;
    int         count;

    if (p == NULL)
    {
        return 0;
    }

    for (count = 0; *p != NUL; count++)
    {
        p += (*mb_ptr2len)(p);
    }

    return count;
}

    static char_u *
mb_unescape(char_u **pp)
{
    static char_u       buf[6];
    int                 n;
    int                 m = 0;
    char_u              *str = *pp;

    for (n = 0; str[n] != NUL && m < 4; ++n)
    {
        if (str[n] ==  (0x80)  && str[n + 1] == KS_SPECIAL && str[n + 2] ==  ('X') )
        {
            buf[m++] =  (0x80) ;
            n += 2;
        }
        else if ((str[n] ==  (0x80) ) && str[n + 1] == KS_EXTRA && str[n + 2] == (int)KE_CSI)
        {
            buf[m++] = CSI;
            n += 2;
        }
        else if (str[n] ==  (0x80) )
        {
            break;
        }
        else
        {
            buf[m++] = str[n];
        }
        buf[m] = NUL;

        if ((*mb_ptr2len)(buf) > 1)
        {
            *pp = str + n + 1;
            return buf;
        }

        if (buf[0] < 128)
        {
            break;
        }
    }
    return NULL;
}

    static int
mb_lefthalve(int row, int col)
{
    return (*mb_off2cells)(LineOffset[row] + col, LineOffset[row] + screen_Columns) > 1;
}

    static int
mb_fix_col(int col, int row)
{
    int off;

    col = check_col(col);
    row = check_row(row);
    off = LineOffset[row] + col;
    if (has_mbyte && ScreenLines != NULL && col > 0 && ((enc_dbcs && ScreenLines[off] != NUL && dbcs_screen_head_off(ScreenLines + LineOffset[row], ScreenLines + off)) || (enc_utf8 && ScreenLines[off] == 0 && ScreenLinesUC[off] == 0)))
    {
        return col - 1;
    }
    return col;
}

static int enc_alias_search(char_u *name);

    static char_u *
enc_skip(char_u *p)
{
    if ( strncmp((char *)(p), (char *)("2byte-"), (6))  == 0)
    {
        return p + 6;
    }
    if ( strncmp((char *)(p), (char *)("8bit-"), (5))  == 0)
    {
        return p + 5;
    }
    return p;
}

    static char_u *
enc_canonize(char_u *enc)
{
    char_u      *r;
    char_u *p;
    char_u *s;
    int         i;

    if ( strcmp((char *)(enc), (char *)("default"))  == 0)
    {
        r = get_encoding_default();
        if (r == NULL)
        {
            r = (char_u *) "latin1" ;
        }
        return vim_strsave(r);
    }

    r = alloc( strlen((char *)(enc))  + 3);
    if (r == NULL)
    {
        return NULL;
    }

    p = r;
    for (s = enc; *s != NUL; ++s)
    {
        if (*s == '_')
        {
            *p++ = '-';
        }
        else
        {
            *p++ =  (((*s) < 'A' || (*s) > 'Z') ? (*s) : (*s) + ('a' - 'A')) ;
        }
    }
    *p = NUL;

    p = enc_skip(r);

    if ( strncmp((char *)(p), (char *)("microsoft-cp"), (12))  == 0)
    {
          memmove((char *)((p)), (char *)((p + 10)),  strlen((char *)(p + 10))  + 1)  ;
    }

    if ( strncmp((char *)(p), (char *)("iso8859"), (7))  == 0)
    {
          memmove((char *)((p + 4)), (char *)((p + 3)),  strlen((char *)(p + 3))  + 1)  ;
        p[3] = '-';
    }

    if ( strncmp((char *)(p), (char *)("iso-8859"), (8))  == 0 &&  (isdigit ((unsigned char)(p[8]))) )
    {
          memmove((char *)((p + 9)), (char *)((p + 8)),  strlen((char *)(p + 8))  + 1)  ;
        p[8] = '-';
    }

    if ( strncmp((char *)(p), (char *)("latin-"), (6))  == 0)
    {
          memmove((char *)((p + 5)), (char *)((p + 6)),  strlen((char *)(p + 6))  + 1)  ;
    }

    if (enc_canon_search(p) >= 0)
    {
        if (p != r)
        {
              memmove((char *)((r)), (char *)((p)),  strlen((char *)(p))  + 1)  ;
        }
    }
    else if ((i = enc_alias_search(p)) >= 0)
    {
        vim_free(r);
        r = vim_strsave((char_u *)enc_canon_table[i].name);
    }
    return r;
}

    static int
enc_alias_search(char_u *name)
{
    int         i;

    for (i = 0; enc_alias_table[i].name != NULL; ++i)
    {
        if ( strcmp((char *)(name), (char *)(enc_alias_table[i].name))  == 0)
        {
            return enc_alias_table[i].canon;
        }
    }
    return -1;
}

