typedef struct block0           ZERO_BL;
typedef struct pointer_block    PTR_BL;
typedef struct data_block       DATA_BL;
typedef struct pointer_entry    PTR_EN;

enum { BLOCK0_ID0 = 'b' };
enum { BLOCK0_ID1 = '0' };
enum { BLOCK0_ID1_C0 = 'c' };
enum { BLOCK0_ID1_C1 = 'C' };
enum { BLOCK0_ID1_C2 = 'd' };
enum { BLOCK0_ID1_C3 = 'S' };
enum { BLOCK0_ID1_C4 = 's' };

