    static int
ml_open(buf_T *buf)
{
    memfile_T   *mfp;
    bhdr_T      *hp = NULL;
    ZERO_BL     *b0p;
    PTR_BL      *pp;
    DATA_BL     *dp;

    buf->b_ml.ml_stack_size = 0;
    buf->b_ml.ml_stack = NULL;
    buf->b_ml.ml_stack_top = 0;
    buf->b_ml.ml_locked = NULL;
    buf->b_ml.ml_line_lnum = 0;

    if (cmdmod.cmod_flags & CMOD_NOSWAPFILE)
    {
    }

    buf->b_may_swap = false;

    mfp = mf_open(NULL, 0);
    if (mfp == NULL)
    {
        goto error;
    }

    buf->b_ml.ml_mfp = mfp;
    buf->b_ml.ml_flags = ML_EMPTY;
    buf->b_ml.ml_line_count = 1;

    if ((hp = mf_new(mfp, FALSE, 1)) == NULL)
    {
        goto error;
    }
    if (hp-> bh_hashitem.mhi_key  != 0)
    {
        iemsg(e_didnt_get_block_nr_zero);
        goto error;
    }
    b0p = (ZERO_BL *)(hp->bh_data);

    b0p->b0_id[0] = BLOCK0_ID0;
    b0p->b0_id[1] = BLOCK0_ID1;
    b0p->b0_magic_long = (long)B0_MAGIC_LONG;
    b0p->b0_magic_int = (int)B0_MAGIC_INT;
    b0p->b0_magic_short = (short)B0_MAGIC_SHORT;
    b0p->b0_magic_char = B0_MAGIC_CHAR;
     memmove((char *)(b0p->b0_version), (char *)("VIM "), 4) ;
     strncpy((char *)(b0p->b0_version + 4), (char *)(Version), (6)) ;
    long_to_char((long)mfp->mf_page_size, b0p->b0_page_size);

    {
        b0p-> b0_fname[B0_FNAME_SIZE_ORG - 1]  = buf->b_changed ? B0_DIRTY : 0;
        b0p-> b0_fname[B0_FNAME_SIZE_ORG - 2]  = get_fileformat(buf) + 1;
        set_b0_fname(b0p, buf);
        (void)get_user_name(b0p->b0_uname, B0_UNAME_SIZE);
        b0p->b0_uname[B0_UNAME_SIZE - 1] = NUL;
        mch_get_host_name(b0p->b0_hname, B0_HNAME_SIZE);
        b0p->b0_hname[B0_HNAME_SIZE - 1] = NUL;
        long_to_char(mch_get_pid(), b0p->b0_pid);
    }

    mf_put(mfp, hp, TRUE, FALSE);
    if (!buf->b_help && ! (0) )
    {
        (void)mf_sync(mfp, 0);
    }

    if ((hp = ml_new_ptr(mfp)) == NULL)
    {
        goto error;
    }
    if (hp-> bh_hashitem.mhi_key  != 1)
    {
        iemsg(e_didnt_get_block_nr_one);
        goto error;
    }
    pp = (PTR_BL *)(hp->bh_data);
    pp->pb_count = 1;
    pp->pb_pointer[0].pe_bnum = 2;
    pp->pb_pointer[0].pe_page_count = 1;
    pp->pb_pointer[0].pe_old_lnum = 1;
    pp->pb_pointer[0].pe_line_count = 1;
    mf_put(mfp, hp, TRUE, FALSE);

    if ((hp = ml_new_data(mfp, FALSE, 1)) == NULL)
    {
        goto error;
    }
    if (hp-> bh_hashitem.mhi_key  != 2)
    {
        iemsg(e_didnt_get_block_nr_two);
        goto error;
    }

    dp = (DATA_BL *)(hp->bh_data);
    dp->db_index[0] = --dp->db_txt_start;
    dp->db_free -= 1 +  (sizeof(unsigned)) ;
    dp->db_line_count = 1;
    *((char_u *)dp + dp->db_txt_start) = NUL;

    return OK;

error:
    if (mfp != NULL)
    {
        if (hp)
        {
            mf_put(mfp, hp, FALSE, FALSE);
        }
        mf_close(mfp, TRUE);
    }
    buf->b_ml.ml_mfp = NULL;
    return FAIL;
}

    static void
ml_setname(buf_T *buf)
{
}

    static void
ml_open_file(buf_T *buf)
{
    buf->b_may_swap = FALSE;
}

    static void
check_need_swap(int     newfile)
{
    int old_msg_silent = msg_silent;

    if (curbuf->b_may_swap && (!curbuf->b_p_ro || !newfile))
    {
        ml_open_file(curbuf);
    }
    msg_silent = old_msg_silent;
}

    static void
ml_close(buf_T *buf, int del_file)
{
    if (buf->b_ml.ml_mfp == NULL)
    {
        return;
    }
    mf_close(buf->b_ml.ml_mfp, del_file);
    if (buf->b_ml.ml_line_lnum != 0 && (buf->b_ml.ml_flags & (ML_LINE_DIRTY | ML_ALLOCATED)))
    {
        vim_free(buf->b_ml.ml_line_ptr);
    }
    vim_free(buf->b_ml.ml_stack);
    buf->b_ml.ml_mfp = NULL;

    buf->b_flags &= ~BF_RECOVERED;
}

    static void
ml_close_all(int del_file)
{
    buf_T       *buf;

     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
     {
        ml_close(buf, del_file && ((buf->b_flags & BF_PRESERVED) == 0 || vim_strchr(p_cpo, CPO_PRESERVE) == NULL));
     }
}

    static void
ml_close_notmod(void)
{
    buf_T       *buf;

     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
     {
        if (!bufIsChanged(buf))
        {
            ml_close(buf, TRUE);
        }
     }
}

    static void
ml_timestamp(buf_T *buf)
{
    ml_upd_block0(buf, UB_FNAME);
}

    static int
ml_check_b0_id(ZERO_BL *b0p)
{
    if (b0p->b0_id[0] != BLOCK0_ID0 || (b0p->b0_id[1] != BLOCK0_ID1 && b0p->b0_id[1] != BLOCK0_ID1_C0 && b0p->b0_id[1] != BLOCK0_ID1_C1 && b0p->b0_id[1] != BLOCK0_ID1_C2 && b0p->b0_id[1] != BLOCK0_ID1_C3 && b0p->b0_id[1] != BLOCK0_ID1_C4))
    {
        return FAIL;
    }
    return OK;
}

    static void
ml_upd_block0(buf_T *buf, upd_block0_T what)
{
    memfile_T   *mfp;
    bhdr_T      *hp;
    ZERO_BL     *b0p;

    mfp = buf->b_ml.ml_mfp;
    if (mfp == NULL)
    {
        return;
    }
    hp = mf_get(mfp, (blocknr_T)0, 1);
    if (hp == NULL)
    {
        return;
    }

    b0p = (ZERO_BL *)(hp->bh_data);
    if (ml_check_b0_id(b0p) == FAIL)
    {
        iemsg(e_ml_upd_block0_didnt_get_block_zero);
    }
    else
    {
        if (what == UB_FNAME)
        {
            set_b0_fname(b0p, buf);
        }
        else
        {
            set_b0_dir_flag(b0p, buf);
        }
    }
    mf_put(mfp, hp, TRUE, FALSE);
}

    static void
set_b0_fname(ZERO_BL *b0p, buf_T *buf)
{
    stat_T      st;

    if (buf->b_ffname == NULL)
    {
        b0p->b0_fname[0] = NUL;
    }
    else
    {
        size_t  flen;
        char_u  uname[B0_UNAME_SIZE];

        flen = home_replace(NULL, buf->b_ffname, b0p->b0_fname, B0_FNAME_SIZE_CRYPT, TRUE);
        if (b0p->b0_fname[0] == '~')
        {
            size_t  ulen;

            if (get_user_name(uname, B0_UNAME_SIZE) == FAIL || (ulen =  strlen((char *)(uname)) ) + flen > B0_FNAME_SIZE_CRYPT - 1)
            {
                vim_strncpy(b0p->b0_fname, buf->b_ffname, B0_FNAME_SIZE_CRYPT - 1);
            }
            else
            {
                 memmove((char *)(b0p->b0_fname + ulen + 1), (char *)(b0p->b0_fname + 1), flen) ;
                 memmove((char *)(b0p->b0_fname + 1), (char *)(uname), ulen) ;
            }
        }
        if ( stat(((char *)buf->b_ffname), (&st))  >= 0)
        {
            long_to_char((long)st.st_mtime, b0p->b0_mtime);
            long_to_char((long)st.st_ino, b0p->b0_ino);
            buf_store_time(buf, &st, buf->b_ffname);
            buf->b_mtime_read = buf->b_mtime;
            buf->b_mtime_read_ns = buf->b_mtime_ns;
        }
        else
        {
            long_to_char(0L, b0p->b0_mtime);
            long_to_char(0L, b0p->b0_ino);
            buf->b_mtime = 0;
            buf->b_mtime_ns = 0;
            buf->b_mtime_read = 0;
            buf->b_mtime_read_ns = 0;
            buf->b_orig_size = 0;
            buf->b_orig_mode = 0;
        }
    }

    add_b0_fenc(b0p, curbuf);
}

    static void
set_b0_dir_flag(ZERO_BL *b0p, buf_T *buf)
{
    if (same_directory(buf->b_ml.ml_mfp->mf_fname, buf->b_ffname))
    {
        b0p-> b0_fname[B0_FNAME_SIZE_ORG - 2]  |= B0_SAME_DIR;
    }
    else
    {
        b0p-> b0_fname[B0_FNAME_SIZE_ORG - 2]  &= ~B0_SAME_DIR;
    }
}

    static void
add_b0_fenc(ZERO_BL     *b0p, buf_T       *buf)
{
}

    static int
swapfile_process_running(ZERO_BL *b0p, char_u *swap_fname  __attribute__((unused)) )
{
    stat_T          st;
    struct sysinfo  sinfo;

    if ( stat(((char *)swap_fname), (&st))  != -1 && sysinfo(&sinfo) == 0 && st.st_mtime < time(NULL) - (time_t)(sinfo.uptime))
    {
        return FALSE;
    }
    return mch_process_running(char_to_long(b0p->b0_pid));
}

    static void
ml_recover(int checkext)
{
    buf_T       *buf = NULL;
    memfile_T   *mfp = NULL;
    char_u      *fname;
    char_u      *fname_used = NULL;
    bhdr_T      *hp = NULL;
    ZERO_BL     *b0p;
    int         b0_ff;
    PTR_BL      *pp;
    DATA_BL     *dp;
    infoptr_T   *ip;
    blocknr_T   bnum;
    int         page_count;
    stat_T org_stat;
    stat_T swp_stat;
    int         len;
    int         directly;
    linenr_T    lnum;
    char_u      *p;
    int         i;
    long        error;
    int         cannot_open;
    linenr_T    line_count;
    int         has_error;
    int         idx;
    int         top;
    int         txt_start;
    off_T       size;
    int         called_from_main;
    int         serious_error = TRUE;
    long        mtime;
    int         attr;
    int         orig_file_status = NOTDONE;

    recoverymode = TRUE;
    called_from_main = (curbuf->b_ml.ml_mfp == NULL);
    attr =  highlight_attr[(int)(HLF_E)] ;

    fname = curbuf->b_fname;
    if (fname == NULL)
    {
        fname = (char_u *)"";
    }
    len = (int) strlen((char *)(fname)) ;
    if (checkext && len >= 4 &&  strncasecmp((char *)(fname + len - 4), (char *)(".s"), (2))  == 0 && vim_strchr((char_u *)"abcdefghijklmnopqrstuvw",  (((fname[len - 2]) < 'A' || (fname[len - 2]) > 'Z') ? (fname[len - 2]) : (fname[len - 2]) + ('a' - 'A')) ) != NULL &&  ( ((unsigned)(fname[len - 1]) - 'A' < 26)  ||  ((unsigned)(fname[len - 1]) - 'a' < 26) ) )
    {
        directly = TRUE;
        fname_used = vim_strsave(fname);
    }
    else
    {
        directly = FALSE;

        len = recover_names(fname, FALSE, NULL, 0, NULL);
        if (len == 0)
        {
            semsg(_(e_no_swap_file_found_for_str), fname);
            goto theend;
        }
        if (len == 1)
        {
            i = 1;
        }
        else
        {
            (void)recover_names(fname, TRUE, NULL, 0, NULL);
            msg_putchar('\n');
            msg_puts(_("Enter number of swap file to use (0 to quit): "));
            i = get_number(FALSE, NULL);
            if (i < 1 || i > len)
            {
                goto theend;
            }
        }
        (void)recover_names(fname, FALSE, NULL, i, &fname_used);
    }
    if (fname_used == NULL)
    {
        goto theend;
    }

    if (called_from_main && ml_open(curbuf) == FAIL)
    {
        getout(1);
    }

    buf =  (buf_T *)alloc(sizeof(buf_T)) ;
    if (buf == NULL)
    {
        goto theend;
    }

    buf->b_ml.ml_stack_size = 0;
    buf->b_ml.ml_stack = NULL;
    buf->b_ml.ml_stack_top = 0;
    buf->b_ml.ml_line_lnum = 0;
    buf->b_ml.ml_locked = NULL;
    buf->b_ml.ml_flags = 0;

    p = vim_strsave(fname_used);
    mfp = mf_open(fname_used, O_RDONLY);
    fname_used = p;
    if (mfp == NULL || mfp->mf_fd < 0)
    {
        if (fname_used != NULL)
        {
            semsg(_(e_cannot_open_str), fname_used);
        }
        goto theend;
    }
    buf->b_ml.ml_mfp = mfp;

    mfp->mf_page_size = MIN_SWAP_PAGE_SIZE;

    if ((hp = mf_get(mfp, (blocknr_T)0, 1)) == NULL)
    {
        msg_start();
        msg_puts_attr(_("Unable to read block 0 from "), attr | MSG_HIST);
        msg_outtrans_attr(mfp->mf_fname, attr | MSG_HIST);
        msg_puts_attr(_("\nMaybe no changes were made or Vim did not update the swap file."), attr | MSG_HIST);
        msg_end();
        goto theend;
    }
    b0p = (ZERO_BL *)(hp->bh_data);
    if ( strncmp((char *)(b0p->b0_version), (char *)("VIM 3.0"), (7))  == 0)
    {
        msg_start();
        msg_outtrans_attr(mfp->mf_fname, MSG_HIST);
        msg_puts_attr(_(" cannot be used with this version of Vim.\n"), MSG_HIST);
        msg_puts_attr(_("Use Vim version 3.0.\n"), MSG_HIST);
        msg_end();
        goto theend;
    }
    if (ml_check_b0_id(b0p) == FAIL)
    {
        semsg(_(e_str_does_not_look_like_vim_swap_file), mfp->mf_fname);
        goto theend;
    }
    if (b0_magic_wrong(b0p))
    {
        msg_start();
        msg_outtrans_attr(mfp->mf_fname, attr | MSG_HIST);
            msg_puts_attr(_(" cannot be used on this computer.\n"), attr | MSG_HIST);
        msg_puts_attr(_("The file was created on "), attr | MSG_HIST);
        b0p->b0_fname[0] = NUL;
        msg_puts_attr((char *)b0p->b0_hname, attr | MSG_HIST);
        msg_puts_attr(_(",\nor the file has been damaged."), attr | MSG_HIST);
        msg_end();
        goto theend;
    }

    if (b0p->b0_id[1] != BLOCK0_ID1)
    {
        semsg(_(e_str_is_encrypted_and_this_version_of_vim_does_not_support_encryption), mfp->mf_fname);
        goto theend;
    }

    if (mfp->mf_page_size != (unsigned)char_to_long(b0p->b0_page_size))
    {
        unsigned previous_page_size = mfp->mf_page_size;

        mf_new_page_size(mfp, (unsigned)char_to_long(b0p->b0_page_size));
        if (mfp->mf_page_size < previous_page_size)
        {
            msg_start();
            msg_outtrans_attr(mfp->mf_fname, attr | MSG_HIST);
            msg_puts_attr(_(" has been damaged (page size is smaller than minimum value).\n"), attr | MSG_HIST);
            msg_end();
            goto theend;
        }
        if ((size =  lseek (mfp->mf_fd, (off_T)0L, SEEK_END)) <= 0)
        {
            mfp->mf_blocknr_max = 0;
        }
        else
        {
            mfp->mf_blocknr_max = (blocknr_T)(size / mfp->mf_page_size);
        }
        mfp->mf_infile_count = mfp->mf_blocknr_max;

        p = alloc(mfp->mf_page_size);
        if (p == NULL)
        {
            goto theend;
        }
         memmove((char *)(p), (char *)(hp->bh_data), previous_page_size) ;
        vim_free(hp->bh_data);
        hp->bh_data = p;
        b0p = (ZERO_BL *)(hp->bh_data);
    }

    if (directly)
    {
        expand_env(b0p->b0_fname, NameBuff,  PATH_MAX );
        if (setfname(curbuf, NameBuff, NULL, TRUE) == FAIL)
        {
            goto theend;
        }
    }

    home_replace(NULL, mfp->mf_fname, NameBuff,  PATH_MAX , TRUE);
    smsg(_("Using swap file \"%s\""), NameBuff);

    if (buf_spname(curbuf) != NULL)
    {
        vim_strncpy(NameBuff, buf_spname(curbuf),  PATH_MAX  - 1);
    }
    else
    {
        home_replace(NULL, curbuf->b_ffname, NameBuff,  PATH_MAX , TRUE);
    }
    smsg(_("Original file \"%s\""), NameBuff);
    msg_putchar('\n');

    mtime = char_to_long(b0p->b0_mtime);
    if (curbuf->b_ffname != NULL &&  stat(((char *)curbuf->b_ffname), (&org_stat))  != -1 && (( stat(((char *)mfp->mf_fname), (&swp_stat))  != -1 && org_stat.st_mtime > swp_stat.st_mtime) || org_stat.st_mtime != mtime))
    {
        emsg(_(e_warning_original_file_may_have_been_changed));
    }
    out_flush();

    b0_ff = (b0p-> b0_fname[B0_FNAME_SIZE_ORG - 2]  & B0_FF_MASK);
    mf_put(mfp, hp, FALSE, FALSE);
    hp = NULL;

    while (!(curbuf->b_ml.ml_flags & ML_EMPTY))
    {
        ml_delete((linenr_T)1);
    }

    if (curbuf->b_ffname != NULL)
    {
        orig_file_status = readfile(curbuf->b_ffname, NULL, (linenr_T)0, (linenr_T)0, (linenr_T) LONG_MAX , NULL, READ_NEW);
    }

    if (b0_ff != 0)
    {
        set_fileformat(b0_ff - 1, OPT_LOCAL);
    }
    unchanged(curbuf, TRUE, TRUE);

    bnum = 1;
    page_count = 1;
    lnum = 0;
    line_count = 0;
    idx = 0;
    error = 0;
    buf->b_ml.ml_stack_top = 0;
    buf->b_ml.ml_stack = NULL;
    buf->b_ml.ml_stack_size = 0;

    if (curbuf->b_ffname == NULL)
    {
        cannot_open = TRUE;
    }
    else
    {
        cannot_open = FALSE;
    }

    serious_error = FALSE;
    for ( ; !got_int; line_breakcheck())
    {
        if (hp != NULL)
        {
            mf_put(mfp, hp, FALSE, FALSE);
        }

        if ((hp = mf_get(mfp, bnum, page_count)) == NULL)
        {
            if (bnum == 1)
            {
                semsg(_(e_unable_to_read_block_one_from_str), mfp->mf_fname);
                goto theend;
            }
            ++error;
            ml_append(lnum++, (char_u *)_("???MANY LINES MISSING"), (colnr_T)0, TRUE);
        }
        else
        {
            pp = (PTR_BL *)(hp->bh_data);
            if (pp->pb_id ==  (('p' << 8) + 't') )
            {
                int ptr_block_error = FALSE;
                if (pp->pb_count_max !=  (short_u)(((mfp)->mf_page_size - offsetof(PTR_BL, pb_pointer)) / sizeof(PTR_EN)) )
                {
                    ptr_block_error = TRUE;
                    pp->pb_count_max =  (short_u)(((mfp)->mf_page_size - offsetof(PTR_BL, pb_pointer)) / sizeof(PTR_EN)) ;
                }
                if (pp->pb_count > pp->pb_count_max)
                {
                    ptr_block_error = TRUE;
                    pp->pb_count = pp->pb_count_max;
                }
                if (ptr_block_error)
                {
                    emsg(_(e_warning_pointer_block_corrupted));
                }

                if (idx == 0 && line_count != 0)
                {
                    for (i = 0; i < (int)pp->pb_count; ++i)
                    {
                        line_count -= pp->pb_pointer[i].pe_line_count;
                    }
                    if (line_count != 0)
                    {
                        ++error;
                        ml_append(lnum++, (char_u *)_("???LINE COUNT WRONG"), (colnr_T)0, TRUE);
                    }
                }

                if (pp->pb_count == 0)
                {
                    ml_append(lnum++, (char_u *)_("???EMPTY BLOCK"), (colnr_T)0, TRUE);
                    ++error;
                }
                else if (idx < (int)pp->pb_count)
                {
                    if (pp->pb_pointer[idx].pe_bnum < 0)
                    {
                        if (!cannot_open)
                        {
                            line_count = pp->pb_pointer[idx].pe_line_count;
                            linenr_T pe_old_lnum = pp->pb_pointer[idx].pe_old_lnum;
                            if (line_count <= 0 || pe_old_lnum < 1 || readfile(curbuf->b_ffname, NULL, lnum, pe_old_lnum - 1, line_count, NULL, 0) != OK)
                            {
                                cannot_open = TRUE;
                            }
                            else
                            {
                                lnum += line_count;
                            }
                        }
                        if (cannot_open)
                        {
                            ++error;
                            ml_append(lnum++, (char_u *)_("???LINES MISSING"), (colnr_T)0, TRUE);
                        }
                        ++idx;
                        continue;
                    }

                    if ((top = ml_add_stack(buf)) < 0)
                    {
                        ++error;
                        break;
                    }
                    ip = &(buf->b_ml.ml_stack[top]);
                    ip->ip_bnum = bnum;
                    ip->ip_index = idx;

                    bnum = pp->pb_pointer[idx].pe_bnum;
                    line_count = pp->pb_pointer[idx].pe_line_count;
                    page_count = pp->pb_pointer[idx].pe_page_count;
                    if (page_count < 1 || bnum + page_count > mfp->mf_blocknr_max + 1)
                    {
                        ++error;
                        ml_append(lnum++, (char_u *)_("???ILLEGAL BLOCK NUMBER"), (colnr_T)0, TRUE);
                        idx = ip->ip_index + 1;
                        bnum = ip->ip_bnum;
                        page_count = 1;
                        --buf->b_ml.ml_stack_top;
                        continue;
                    }
                    idx = 0;
                    continue;
                }
            }
            else
            {
                dp = (DATA_BL *)(hp->bh_data);
                if (dp->db_id !=  (('d' << 8) + 'a') )
                {
                    if (bnum == 1)
                    {
                        semsg(_(e_block_one_id_wrong_str_not_swp_file), mfp->mf_fname);
                        goto theend;
                    }
                    ++error;
                    ml_append(lnum++, (char_u *)_("???BLOCK MISSING"), (colnr_T)0, TRUE);
                }
                else
                {
                    has_error = FALSE;

                    if (hp->bh_page_count != page_count)
                    {
                        ++error;
                        ml_append(lnum++, (char_u *)_("??? BLOCK PAGE COUNT MISMATCH"), (colnr_T)0, TRUE);
                        page_count = hp->bh_page_count;
                    }

                    if (page_count * mfp->mf_page_size != dp->db_txt_end)
                    {
                        ml_append(lnum++, (char_u *)_("??? from here until ???END lines may be messed up"), (colnr_T)0, TRUE);
                        ++error;
                        has_error = TRUE;
                        dp->db_txt_end = page_count * mfp->mf_page_size;
                    }

                    if (dp->db_txt_start <  (offsetof(DATA_BL, db_index))  || dp->db_txt_start > dp->db_txt_end)
                    {
                        ml_append(lnum++, (char_u *)_("??? block header corrupted"), (colnr_T)0, TRUE);
                        ++error;
                        has_error = TRUE;
                        dp->db_txt_start = dp->db_txt_end;
                    }
                    *((char_u *)dp + dp->db_txt_end - 1) = NUL;

                    if (line_count != dp->db_line_count)
                    {
                        ml_append(lnum++, (char_u *)_("??? from here until ???END lines may have been inserted/deleted"), (colnr_T)0, TRUE);
                        ++error;
                        has_error = TRUE;
                    }

                    int did_questions = FALSE;
                    for (i = 0; i < dp->db_line_count; ++i)
                    {
                        if ((char_u *)&(dp->db_index[i]) >= (char_u *)dp + dp->db_txt_start)
                        {
                            ++error;
                            ml_append(lnum++, (char_u *)_("??? lines may be missing"), (colnr_T)0, TRUE);
                            break;
                        }

                        txt_start = (dp->db_index[i] &  (~ ((unsigned)1 << ((sizeof(unsigned) * 8) - 1)) ) );
                        if (txt_start <= (int) (offsetof(DATA_BL, db_index))  || txt_start >= (int)dp->db_txt_end)
                        {
                            ++error;
                            if (did_questions)
                            {
                                continue;
                            }
                            did_questions = TRUE;
                            p = (char_u *)"???";
                        }
                        else
                        {
                            did_questions = FALSE;
                            p = (char_u *)dp + txt_start;
                        }
                        ml_append(lnum++, p, (colnr_T)0, TRUE);
                    }
                    if (has_error)
                    {
                        ml_append(lnum++, (char_u *)_("???END"), (colnr_T)0, TRUE);
                    }
                }
            }
        }

        if (buf->b_ml.ml_stack_top == 0)
        {
            break;
        }

        ip = &(buf->b_ml.ml_stack[--(buf->b_ml.ml_stack_top)]);
        bnum = ip->ip_bnum;
        idx = ip->ip_index + 1;
        page_count = 1;
    }

    if (orig_file_status != OK || curbuf->b_ml.ml_line_count != lnum * 2 + 1)
    {
        if (!(curbuf->b_ml.ml_line_count == 2 && *ml_get(1) == NUL))
        {
            changed_internal();
            ++ ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
        }
    }
    else
    {
        for (idx = 1; idx <= lnum; ++idx)
        {
            p = vim_strnsave(ml_get(idx), ml_get_len(idx));
            i =  strcmp((char *)(p), (char *)(ml_get(idx + lnum))) ;
            vim_free(p);
            if (i != 0)
            {
                changed_internal();
                ++ ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
                break;
            }
        }
    }

    while (curbuf->b_ml.ml_line_count > lnum && !(curbuf->b_ml.ml_flags & ML_EMPTY))
    {
        ml_delete(curbuf->b_ml.ml_line_count);
    }
    curbuf->b_flags |= BF_RECOVERED;
    check_cursor();

    recoverymode = FALSE;
    if (got_int)
    {
        emsg(_(e_recovery_interrupted));
    }
    else if (error)
    {
        ++no_wait_return;
        msg(">>>>>>>>>>>>>");
        emsg(_(e_errors_detected_while_recovering_look_for_lines_starting_with_questions));
        --no_wait_return;
        msg(_("See \":help E312\" for more information."));
        msg(">>>>>>>>>>>>>");
    }
    else
    {
        if (curbuf->b_changed)
        {
            msg(_("Recovery completed. You should check if everything is OK."));
            msg_puts(_("\n(You might want to write out this file under another name\n"));
            msg_puts(_("and run diff with the original file to check for changes)"));
        }
        else
        {
            msg(_("Recovery completed. Buffer contents equals file contents."));
        }
        msg_puts(_("\nYou may want to delete the .swp file now."));
        if (swapfile_process_running(b0p, fname_used))
        {
            msg_puts(_("\nNote: process STILL RUNNING: "));
            msg_outnum(char_to_long(b0p->b0_pid));
        }
        msg_puts("\n\n");
        cmdline_row = msg_row;
    }
    redraw_curbuf_later(UPD_NOT_VALID);

theend:
    vim_free(fname_used);
    recoverymode = FALSE;
    if (mfp != NULL)
    {
        if (hp != NULL)
        {
            mf_put(mfp, hp, FALSE, FALSE);
        }
        mf_close(mfp, FALSE);
    }
    if (buf != NULL)
    {
        vim_free(buf->b_ml.ml_stack);
        vim_free(buf);
    }
    if (serious_error && called_from_main)
    {
        ml_close(curbuf, TRUE);
    }
    else
    {
        apply_autocmds(EVENT_BUFREADPOST, NULL, curbuf->b_fname, FALSE, curbuf);
        apply_autocmds(EVENT_BUFWINENTER, NULL, curbuf->b_fname, FALSE, curbuf);
    }
}

    static int
recover_names(char_u      *fname, int         do_list, list_T      *ret_list  __attribute__((unused)) , int         nr, char_u      **fname_out)
{
    int         num_names;
    char_u      *(names[6]);
    char_u      *p;
    int         num_files;
    int         file_count = 0;
    char_u      **files;
    char_u      *dirp;
    string_T    dir_name;
    char_u      *fname_res = NULL;
    char_u      fname_buf[ PATH_MAX ];

    if (fname != NULL)
    {
        if (resolve_symlink(fname, fname_buf) == OK)
        {
            fname_res = fname_buf;
        }
        else
        {
            fname_res = fname;
        }
    }

    if (do_list)
    {
        msg(_("Swap files found:"));
        msg_putchar('\n');
    }

    dir_name.string = alloc( strlen((char *)(p_dir))  + 1);
    dirp = p_dir;
    while (dir_name.string != NULL && *dirp)
    {
        dir_name.length = (size_t)copy_option_part(&dirp, dir_name.string, 31000, ",");

        if (dir_name.string[0] == '.' && dir_name.string[1] == NUL)
        {
            if (fname == NULL)
            {
                names[0] = vim_strnsave((char_u *)"*.sw?",  (sizeof("*.sw?" "") - 1) );
                names[1] = vim_strnsave((char_u *)".*.sw?",  (sizeof(".*.sw?" "") - 1) );
                names[2] = vim_strnsave((char_u *)".sw?",  (sizeof(".sw?" "") - 1) );
                num_names = 3;
            }
            else
            {
                num_names = recov_file_names(names, fname_res, TRUE);
            }
        }
        else
        {
            if (fname == NULL)
            {
                string_T    ret;

                names[0] = concat_fnames(dir_name.string, dir_name.length, (char_u *)"*.sw?",  (sizeof("*.sw?" "") - 1) , TRUE, &ret);
                names[1] = concat_fnames(dir_name.string, dir_name.length, (char_u *)".*.sw?",  (sizeof(".*.sw?" "") - 1) , TRUE, &ret);
                names[2] = concat_fnames(dir_name.string, dir_name.length, (char_u *)".sw?",  (sizeof(".sw?" "") - 1) , TRUE, &ret);
                num_names = 3;
            }
            else
            {
                char_u  *tail;

                p = dir_name.string + dir_name.length;
                if (after_pathsep(dir_name.string, p) && dir_name.length > 1 && p[-1] == p[-2])
                {
                    tail = make_percent_swname(dir_name.string, p, fname_res);
                }
                else
                {
                    string_T    ret;

                    tail = gettail(fname_res);
                    tail = concat_fnames(dir_name.string, dir_name.length, tail,  strlen((char *)(tail)) , TRUE, &ret);
                }
                if (tail == NULL)
                {
                    num_names = 0;
                }
                else
                {
                    num_names = recov_file_names(names, tail, FALSE);
                    vim_free(tail);
                }
            }
        }

        for (int i = 0; i < num_names; ++i)
        {
            if (names[i] == NULL)
            {
                for (i = 0; i < num_names; ++i)
                {
                    vim_free(names[i]);
                }
                num_names = 0;
            }
        }
        if (num_names == 0)
        {
            num_files = 0;
        }
        else if (expand_wildcards(num_names, names, &num_files, &files, EW_NOTENV|EW_KEEPALL|EW_FILE|EW_SILENT) == FAIL)
        {
            num_files = 0;
        }

        if (*dirp == NUL && file_count + num_files == 0 && fname != NULL)
        {
            stat_T          st;
            char_u          *swapname;

            swapname = modname(fname_res, (char_u *)".swp", TRUE);
            if (swapname != NULL)
            {
                if ( stat(((char *)swapname), (&st))  != -1)
                {
                    files =  (char_u * *)alloc(sizeof(char_u *)) ;
                    if (files != NULL)
                    {
                        files[0] = swapname;
                        swapname = NULL;
                        num_files = 1;
                    }
                }
                vim_free(swapname);
            }
        }

        if (curbuf->b_ml.ml_mfp != NULL && (p = curbuf->b_ml.ml_mfp->mf_fname) != NULL && ret_list == NULL)
        {
            for (int i = 0; i < num_files; ++i)
            {
                if (fullpathcmp(p, files[i], TRUE, FALSE) & FPC_SAME)
                {
                    vim_free(files[i]);
                    if (--num_files == 0)
                    {
                        vim_free(files);
                    }
                    else
                    {
                        for ( ; i < num_files; ++i)
                        {
                            files[i] = files[i + 1];
                        }
                    }
                }
            }
        }
        if (nr > 0)
        {
            file_count += num_files;
            if (nr <= file_count)
            {
                *fname_out = vim_strsave(files[nr - 1 + num_files - file_count]);
                dirp = (char_u *)"";
            }
        }
        else if (do_list)
        {
            if (dir_name.string[0] == '.' && dir_name.string[1] == NUL)
            {
                if (fname == NULL)
                {
                    msg_puts(_("   In current directory:\n"));
                }
                else
                {
                    msg_puts(_("   Using specified name:\n"));
                }
            }
            else
            {
                msg_puts(_("   In directory "));
                msg_home_replace(dir_name.string);
                msg_puts(":\n");
            }

            if (num_files)
            {
                for (int i = 0; i < num_files; ++i)
                {
                    msg_outnum((long)++file_count);
                    msg_puts(".    ");
                    msg_puts((char *)gettail(files[i]));
                    msg_putchar('\n');
                    (void)swapfile_info(files[i]);
                }
            }
            else
            {
                msg_puts(_("      -- none --\n"));
            }
            out_flush();
        }
        else
        {
            file_count += num_files;
        }

        for (int i = 0; i < num_names; ++i)
        {
            vim_free(names[i]);
        }
        if (num_files > 0)
        {
            FreeWild(num_files, files);
        }
    }
    vim_free(dir_name.string);
    return file_count;
}

    static char_u *
make_percent_swname(char_u *dir, char_u *dir_end, char_u *name)
{
    string_T    d = {NULL, 0};
    string_T    fixed_fname;
    char_u      *p;

    fixed_fname.string = fix_fname(name != NULL ? name : (char_u *)"");
    if (fixed_fname.string == NULL)
    {
        return NULL;
    }

    for (p = fixed_fname.string; *p != NUL;  p += (*mb_ptr2len)(p) )
    {
        if (vim_ispathsep(*p))
        {
            *p = '%';
        }
    }
    fixed_fname.length = (size_t)(p - fixed_fname.string);

    p = &dir_end[-1];
    *p = NUL;
    concat_fnames(dir, (size_t)(p - dir), fixed_fname.string, fixed_fname.length, TRUE, &d);
    vim_free(fixed_fname.string);

    return d.string;
}

    static time_t
swapfile_info(char_u *fname)
{
    stat_T          st;
    int             fd;
    struct block0   b0;
    char_u          uname[B0_UNAME_SIZE];

    if ( stat(((char *)fname), (&st))  != -1)
    {
        if (mch_get_uname(st.st_uid, uname, B0_UNAME_SIZE) == OK)
        {
            msg_puts(_("          owned by: "));
            msg_outtrans(uname);
            msg_puts(_("   dated: "));
        }
        else
        {
            msg_puts(_("             dated: "));
        }
        msg_puts(get_ctime(st.st_mtime, TRUE));
    }
    else
    {
        st.st_mtime = 0;
    }

    fd =  open(((char *)fname), (O_RDONLY | O_EXTRA), (0)) ;
    if (fd >= 0)
    {
        if (read_eintr(fd, &b0, sizeof(b0)) == sizeof(b0))
        {
            if ( strncmp((char *)(b0.b0_version), (char *)("VIM 3.0"), (7))  == 0)
            {
                msg_puts(_("         [from Vim version 3.0]"));
            }
            else if (ml_check_b0_id(&b0) == FAIL)
            {
                msg_puts(_("         [does not look like a Vim swap file]"));
            }
            else
            {
                msg_puts(_("         file name: "));
                if (b0.b0_fname[0] == NUL)
                {
                    msg_puts(_("[No Name]"));
                }
                else
                {
                    msg_outtrans(b0.b0_fname);
                }

                msg_puts(_("\n          modified: "));
                msg_puts(b0. b0_fname[B0_FNAME_SIZE_ORG - 1]  ? _("YES") : _("no"));

                if (*(b0.b0_uname) != NUL)
                {
                    msg_puts(_("\n         user name: "));
                    msg_outtrans(b0.b0_uname);
                }

                if (*(b0.b0_hname) != NUL)
                {
                    if (*(b0.b0_uname) != NUL)
                    {
                        msg_puts(_("   host name: "));
                    }
                    else
                    {
                        msg_puts(_("\n         host name: "));
                    }
                    msg_outtrans(b0.b0_hname);
                }

                if (char_to_long(b0.b0_pid) != 0L)
                {
                    msg_puts(_("\n        process ID: "));
                    msg_outnum(char_to_long(b0.b0_pid));
                    if (swapfile_process_running(&b0, fname))
                    {
                        msg_puts(_(" (STILL RUNNING)"));
                    }
                }

                if (b0_magic_wrong(&b0))
                {
                        msg_puts(_("\n         [not usable on this computer]"));
                }
            }
        }
        else
        {
            msg_puts(_("         [cannot be read]"));
        }
        close(fd);
    }
    else
    {
        msg_puts(_("         [cannot be opened]"));
    }
    msg_putchar('\n');

    return st.st_mtime;
}

    static int
recov_file_names(char_u **names, char_u *path, int prepend_dot)
{
    int         num_names;

    char_u      *p;
    int         i;
    bool    shortname = curbuf->b_shortname;

    curbuf->b_shortname = false;
    string_T    ret;

    num_names = 0;

    if (prepend_dot)
    {
        names[num_names] = modname(path, (char_u *)".sw?", TRUE);
        if (names[num_names] == NULL)
        {
            goto end;
        }
        ++num_names;
    }

    names[num_names] = concat_fnames(path,  strlen((char *)(path)) , (char_u *)".sw?",  (sizeof(".sw?" "") - 1) , FALSE, &ret);
    if (names[num_names] == NULL)
    {
        goto end;
    }
    if (num_names >= 1)
    {
        p = names[num_names - 1];
        i = (int) strlen((char *)(names[num_names - 1]))  - (int) strlen((char *)(names[num_names])) ;
        if (i > 0)
        {
            p += i;
        }

        if ( strcmp((char *)(p), (char *)(names[num_names]))  != 0)
        {
            ++num_names;
        }
        else
        {
            vim_free(names[num_names]);
        }
    }
    else
    {
        ++num_names;
    }

    curbuf->b_shortname = true;
    names[num_names] = modname(path, (char_u *)".sw?", FALSE);
    if (names[num_names] == NULL)
    {
        goto end;
    }

    p = names[num_names];
    i =  strlen((char *)(names[num_names]))  -  strlen((char *)(names[num_names - 1])) ;
    if (i > 0)
    {
        p += i;
    }
    if ( strcmp((char *)(names[num_names - 1]), (char *)(p))  == 0)
    {
        vim_free(names[num_names]);
    }
    else
    {
        ++num_names;
    }

end:
    curbuf->b_shortname = shortname;

    return num_names;
}

