    static void
msg_source(int attr)
{
    char_u      *p;
    static int  recursive = FALSE;

    if (recursive)
    {
        return;
    }
    recursive = TRUE;

    ++no_wait_return;
    p = get_emsg_source();
    if (p != NULL)
    {
        msg_scroll = TRUE;
        msg_attr((char *)p, attr);
        vim_free(p);
    }
    p = get_emsg_lnum();
    if (p != NULL)
    {
        msg_attr((char *)p,  highlight_attr[(int)(HLF_N)] );
        vim_free(p);
        last_sourcing_lnum =  (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_lnum) ;
    }

    if ( (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_name)  == NULL || other_sourcing_name())
    {
         vim_free(last_sourcing_name);
         (last_sourcing_name) = NULL;
        if ( (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_name)  != NULL)
        {
            last_sourcing_name = vim_strsave( (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_name) );
        }
    }
    --no_wait_return;

    recursive = FALSE;
}

    static int
emsg_not_now(void)
{
    if ((emsg_off > 0 && vim_strchr(p_debug, 'm') == NULL && vim_strchr(p_debug, 't') == NULL))
    {
        return TRUE;
    }
    return FALSE;
}

    static int
emsg_core(const char *s)
{
    int         attr;
    char_u      *p;
    int         r;

    ++called_emsg;

    if (!emsg_off || vim_strchr(p_debug, 't') != NULL)
    {
        if (emsg_silent != 0)
        {
            if (emsg_noredir == 0)
            {
                msg_start();
                p = get_emsg_source();
                if (p != NULL)
                {
                     strcat((char *)(p), (char *)("\n")) ;
                    redir_write(p, -1);
                    vim_free(p);
                }
                p = get_emsg_lnum();
                if (p != NULL)
                {
                     strcat((char *)(p), (char *)("\n")) ;
                    redir_write(p, -1);
                    vim_free(p);
                }
                redir_write((char_u *)s, -1);
            }
            return TRUE;
        }

        ex_exitval = 1;

        msg_silent = 0;
        cmd_silent = FALSE;

        if (global_busy)
        {
            ++global_busy;
        }

        if (p_eb)
        {
            beep_flush();
        }
        else
        {
            flush_buffers(FLUSH_MINIMAL);
        }
        ++did_emsg;
    }

        emsg_on_display = TRUE;

    attr =  highlight_attr[(int)(HLF_E)] ;
    if (msg_scrolled != 0)
    {
        need_wait_return = TRUE;
    }

    msg_scroll = TRUE;
    msg_source(attr);

    msg_nowait = FALSE;
    r = msg_attr((char *)s, attr);

    return r;
}

    static int
emsg(char *s)
{
    if (emsg_not_now())
    {
        return TRUE;
    }

    return emsg_core(s);
}

    static int
semsg(const char *s, ...)
{
    if (emsg_not_now())
    {
        return TRUE;
    }

    if (IObuff == NULL)
    {
        return emsg_core(s);
    }

    va_list ap;

    va_start(ap, s);
    vim_vsnprintf((char *)IObuff,  (1024+1) , s, ap);
    va_end(ap);
    return emsg_core((char *)IObuff);
}

    static void
iemsg(char *s)
{
    if (emsg_not_now())
    {
        return;
    }

    emsg_core(_(e_internal_error_please_report_a_bug));

    emsg_core(s);
}

    static void
siemsg(const char *s, ...)
{
    if (emsg_not_now())
    {
        return;
    }

    emsg_core(_(e_internal_error_please_report_a_bug));

    if (IObuff == NULL)
    {
        emsg_core(s);
    }
    else
    {
        va_list ap;

        va_start(ap, s);
        vim_vsnprintf((char *)IObuff,  (1024+1) , s, ap);
        va_end(ap);
        emsg_core((char *)IObuff);
    }
}

