    static int
name_to_mod_mask(int c)
{
    int     i;

    c =  (((c) < 'a' || (c) > 'z') ? (c) : (c) - ('a' - 'A')) ;
    for (i = 0; mod_mask_table[i].mod_mask != 0; i++)
    {
        if (c == mod_mask_table[i].name)
        {
            return mod_mask_table[i].mod_flag;
        }
    }
    return 0;
}

    static int
simplify_key(int key, int *modifiers)
{
    int     i;
    int     key0;
    int     key1;

    if (!(*modifiers & (MOD_MASK_SHIFT | MOD_MASK_CTRL)))
    {
        return key;
    }

    if (key == TAB && (*modifiers & MOD_MASK_SHIFT))
    {
        *modifiers &= ~MOD_MASK_SHIFT;
        return   (-(('k') + ((int)('B') << 8)))  ;
    }
    key0 =  ((-(key)) & 0xff) ;
    key1 =  (((unsigned)(-(key)) >> 8) & 0xff) ;
    for (i = 0; modifier_keys_table[i] != NUL; i += MOD_KEYS_ENTRY_SIZE)
    {
        if (key0 == modifier_keys_table[i + 3] && key1 == modifier_keys_table[i + 4] && (*modifiers & modifier_keys_table[i]))
        {
            *modifiers &= ~modifier_keys_table[i];
            return  (-((modifier_keys_table[i + 1]) + ((int)(modifier_keys_table[i + 2]) << 8))) ;
        }
    }
    return key;
}

    static int
handle_x_keys(int key)
{
    switch (key)
    {
        case   (-((KS_EXTRA) + ((int)(KE_XUP) << 8)))  :
            return   (-(('k') + ((int)('u') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XDOWN) << 8)))  :
            return   (-(('k') + ((int)('d') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XLEFT) << 8)))  :
            return   (-(('k') + ((int)('l') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XRIGHT) << 8)))  :
            return   (-(('k') + ((int)('r') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XHOME) << 8)))  :
            return   (-(('k') + ((int)('h') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_ZHOME) << 8)))  :
            return   (-(('k') + ((int)('h') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XEND) << 8)))  :
            return   (-(('@') + ((int)('7') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_ZEND) << 8)))  :
            return   (-(('@') + ((int)('7') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF1) << 8)))  :
            return   (-(('k') + ((int)('1') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF2) << 8)))  :
            return   (-(('k') + ((int)('2') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF3) << 8)))  :
            return   (-(('k') + ((int)('3') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_XF4) << 8)))  :
            return   (-(('k') + ((int)('4') << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF1) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F1) << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF2) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F2) << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF3) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F3) << 8)))  ;
        case   (-((KS_EXTRA) + ((int)(KE_S_XF4) << 8)))  :
            return   (-((KS_EXTRA) + ((int)(KE_S_F4) << 8)))  ;
    }
    return key;
}

    static char_u *
get_special_key_name(int c, int modifiers)
{
    static char_u string[MAX_KEY_NAME_LEN + 1];
    int i;
    int idx;
    int len;
    int     table_idx;

    string[0] = '<';
    idx = 1;

    if ( ((c) < 0)  &&  ((-(c)) & 0xff)  == KS_KEY)
    {
        c =  (((unsigned)(-(c)) >> 8) & 0xff) ;
    }

    if ( ((c) < 0) )
    {
        for (i = 0; modifier_keys_table[i] != 0; i += MOD_KEYS_ENTRY_SIZE)
        {
            if (        ((-(c)) & 0xff)  == (int)modifier_keys_table[i + 1] && (int) (((unsigned)(-(c)) >> 8) & 0xff)  == (int)modifier_keys_table[i + 2])
            {
                modifiers |= modifier_keys_table[i];
                c =  (-((modifier_keys_table[i + 3]) + ((int)(modifier_keys_table[i + 4]) << 8))) ;
                break;
            }
        }
    }

    table_idx = find_special_key_in_table(c);

    if (c > 0 && (*mb_char2len)(c) == 1)
    {
        if (table_idx < 0 && (!vim_isprintc(c) || (c & 0x7f) == ' ') && (c & 0x80))
        {
            c &= 0x7f;
            modifiers |= MOD_MASK_ALT;
            table_idx = find_special_key_in_table(c);
        }
        if (table_idx < 0 && !vim_isprintc(c) && c < ' ')
        {
            c += '@';
            modifiers |= MOD_MASK_CTRL;
        }
    }

    for (i = 0; mod_mask_table[i].name != 'A'; i++)
    {
        if ((modifiers & mod_mask_table[i].mod_mask) == mod_mask_table[i].mod_flag)
        {
            string[idx++] = mod_mask_table[i].name;
            string[idx++] = (char_u)'-';
        }
    }

    if (table_idx < 0)
    {
        if ( ((c) < 0) )
        {
            string[idx++] = 't';
            string[idx++] = '_';
            string[idx++] =  ((-(c)) & 0xff) ;
            string[idx++] =  (((unsigned)(-(c)) >> 8) & 0xff) ;
        }
        else
        {
            len = (*mb_char2len)(c);
            if (len == 1 && vim_isprintc(c))
            {
                string[idx++] = c;
            }
            else if (has_mbyte && len > 1)
            {
                idx += (*mb_char2bytes)(c, string + idx);
            }
            else
            {
                char_u  *s = transchar(c);
                while (*s)
                {
                    string[idx++] = *s++;
                }
            }
        }
    }
    else
    {
        string_T    *s;

        s = &key_names_table[table_idx].name;

        if (s->length + idx + 2 <= MAX_KEY_NAME_LEN)
        {
             strcpy((char *)(string + idx), (char *)(s->string)) ;
            idx += (int)s->length;
        }
    }
    string[idx++] = '>';
    string[idx] = NUL;

    return string;
}

    static int
trans_special(char_u      **srcp, char_u      *dst, int         flags, int         escape_ks, int         *did_simplify)
{
    int         modifiers = 0;
    int         key;

    key = find_special_key(srcp, &modifiers, flags, did_simplify);
    if (key == 0)
    {
        return 0;
    }

    return special_to_buf(key, modifiers, escape_ks, dst);
}

    static int
special_to_buf(int key, int modifiers, int escape_ks, char_u *dst)
{
    int         dlen = 0;

    if (modifiers != 0)
    {
        dst[dlen++] =  (0x80) ;
        dst[dlen++] = KS_MODIFIER;
        dst[dlen++] = modifiers;
    }

    if ( ((key) < 0) )
    {
        dst[dlen++] =  (0x80) ;
        dst[dlen++] =  ((-(key)) & 0xff) ;
        dst[dlen++] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
    }
    else if (escape_ks)
    {
        dlen = (int)(add_char2buf(key, dst + dlen) - dst);
    }
    else if (has_mbyte)
    {
        dlen += (*mb_char2bytes)(key, dst + dlen);
    }
    else
    {
        dst[dlen++] = key;
    }

    return dlen;
}

    static int
find_special_key(char_u      **srcp, int         *modp, int         flags, int         *did_simplify)
{
    char_u      *last_dash;
    char_u      *end_of_name;
    char_u      *src;
    char_u      *bp;
    int         in_string = flags & FSK_IN_STRING;
    int         modifiers;
    int         bit;
    int         key;
    uvarnumber_T        n;
    int         l;

    src = *srcp;
    if (src[0] != '<')
    {
        return 0;
    }
    if (src[1] == '*')
    {
        ++src;
    }

    last_dash = src;
    for (bp = src + 1; *bp == '-' || vim_isNormalIDc(*bp); bp++)
    {
        if (*bp == '-')
        {
            last_dash = bp;
            if (bp[1] != NUL)
            {
                if (has_mbyte)
                {
                    l = mb_ptr2len(bp + 1);
                }
                else
                {
                    l = 1;
                }
                if (!(in_string && bp[1] == '"') && bp[l + 1] == '>')
                {
                    bp += l;
                }
                else if (in_string && bp[1] == '\\' && bp[2] == '"' && bp[3] == '>')
                {
                    bp += 2;
                }
            }
        }
        if (bp[0] == 't' && bp[1] == '_' && bp[2] && bp[3])
        {
            bp += 3;
        }
        else if ( strncasecmp((char *)(bp), (char *)("char-"), (5))  == 0)
        {
            vim_str2nr(bp + 5, NULL, &l,  (STR2NR_BIN + STR2NR_OCT + STR2NR_HEX + STR2NR_OOCT) , NULL, NULL, 0, TRUE, NULL);
            if (l == 0)
            {
                emsg(_(e_invalid_argument));
                return 0;
            }
            bp += l + 5;
            break;
        }
    }

    if (*bp == '>')
    {
        end_of_name = bp + 1;

        modifiers = 0x0;
        for (bp = src + 1; bp < last_dash; bp++)
        {
            if (*bp != '-')
            {
                bit = name_to_mod_mask(*bp);
                if (bit == 0x0)
                {
                    break;
                }
                modifiers |= bit;
            }
        }

        if (bp >= last_dash)
        {
            if ( strncasecmp((char *)(last_dash + 1), (char *)("char-"), (5))  == 0 &&  ((unsigned)(last_dash[6]) - '0' < 10) )
            {
                vim_str2nr(last_dash + 6, NULL, &l,  (STR2NR_BIN + STR2NR_OCT + STR2NR_HEX + STR2NR_OOCT) , NULL, &n, 0, TRUE, NULL);
                if (l == 0)
                {
                    emsg(_(e_invalid_argument));
                    return 0;
                }
                key = (int)n;
            }
            else
            {
                int off = 1;

                if (in_string && last_dash[1] == '\\' && last_dash[2] == '"')
                {
                    off = 2;
                }
                if (has_mbyte)
                {
                    l = mb_ptr2len(last_dash + off);
                }
                else
                {
                    l = 1;
                }
                if (modifiers != 0 && last_dash[l + off] == '>')
                {
                    key =  (has_mbyte ? mb_ptr2char(last_dash + off) : (int)*(last_dash + off)) ;
                }
                else
                {
                    key = get_special_key_code(last_dash + off);
                    if (!(flags & FSK_KEEP_X_KEY))
                    {
                        key = handle_x_keys(key);
                    }
                }
            }

            if (key != NUL)
            {
                key = simplify_key(key, &modifiers);

                if ((flags & FSK_KEYCODE) == 0)
                {
                    if (key ==   (-(('k') + ((int)('b') << 8)))  )
                    {
                        key = BS;
                    }
                    else if (key ==   (-(('k') + ((int)('D') << 8)))   || key ==   (-((KS_EXTRA) + ((int)(KE_KDEL) << 8)))  )
                    {
                        key = DEL;
                    }
                }
                else if (key == 27 && (flags & FSK_FROM_PART) != 0 && (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED))
                {
                    if ((flags & FSK_SIMPLIFY) != 0)
                    {
                        if (did_simplify != NULL)
                        {
                            *did_simplify = TRUE;
                        }
                    }
                    else
                    {
                        key =   (-((KS_EXTRA) + ((int)(KE_ESC) << 8)))  ;
                    }
                }

                if (! ((key) < 0) )
                {
                    key = extract_modifiers(key, &modifiers, flags & FSK_SIMPLIFY, did_simplify);
                }

                *modp = modifiers;
                *srcp = end_of_name;
                return key;
            }
        }
    }
    return 0;
}

    static int
may_adjust_key_for_ctrl(int modifiers, int key)
{
    if ((modifiers & MOD_MASK_CTRL) == 0)
    {
        return key;
    }

    if ( ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) )
    {
        return no_reduce_keys == 0 ?  (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A'))  : key;
    }
    if (key == '2')
    {
        return '@';
    }
    if (key == '6')
    {
        return '^';
    }
    if (key == '-')
    {
        return '_';
    }

    if (key == '$' && (modifiers & MOD_MASK_SHIFT) == 0)
    {
        return ']';
    }

    return key;
}

    static int
may_remove_shift_modifier(int modifiers, int key)
{
    if ((modifiers == MOD_MASK_SHIFT || modifiers == (MOD_MASK_SHIFT | MOD_MASK_ALT) || modifiers == (MOD_MASK_SHIFT | MOD_MASK_META)) && ((key >= '!' && key <= '/') || (key >= ':' && key <= 'Z') || vim_isdigit(key) || (key >= '[' && key <= '`') || (key >= '{' && key <= '~')))
    {
        return modifiers & ~MOD_MASK_SHIFT;
    }

    if (modifiers == (MOD_MASK_SHIFT | MOD_MASK_CTRL) && (key == '{' || key == '}' || key == '|'))
    {
        return modifiers & ~MOD_MASK_SHIFT;
    }

    return modifiers;
}

    static int
extract_modifiers(int key, int *modp, int simplify, int *did_simplify)
{
    int modifiers = *modp;

    if ((modifiers & MOD_MASK_SHIFT) &&  ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) )
    {
        key =  (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A')) ;
        if (simplify || modifiers == MOD_MASK_SHIFT || modifiers == (MOD_MASK_SHIFT | MOD_MASK_ALT) || modifiers == (MOD_MASK_SHIFT | MOD_MASK_META))
        {
            modifiers &= ~MOD_MASK_SHIFT;
        }
    }

    if ((modifiers & MOD_MASK_CTRL) &&  ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) )
    {
        key =  (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A')) ;
    }

    if (simplify && (modifiers & MOD_MASK_CTRL) && ((key >= '?' && key <= '_') ||  ( ((unsigned)(key) - 'A' < 26)  ||  ((unsigned)(key) - 'a' < 26) ) ))
    {
        key =  ( (((key) < 'a' || (key) > 'z') ? (key) : (key) - ('a' - 'A'))  ^ 0x40) ;
        modifiers &= ~MOD_MASK_CTRL;
        if (key == NUL)
        {
            key =   (-((KS_ZERO) + ((int)( ('X') ) << 8)))  ;
        }
        if (did_simplify != NULL)
        {
            *did_simplify = TRUE;
        }
    }

    if (simplify && (modifiers & MOD_MASK_ALT) && key < 0x80 && !enc_dbcs)
    {
        key |= 0x80;
        modifiers &= ~MOD_MASK_ALT;
        if (did_simplify != NULL)
        {
            *did_simplify = TRUE;
        }
    }

    *modp = modifiers;
    return key;
}

    static int
find_special_key_in_table(int c)
{
    int     i;

    for (i = 0; i < (int) (sizeof(key_names_table) / sizeof((key_names_table)[0])) ; i++)
    {
        if (c == key_names_table[i].key && !key_names_table[i].is_alt)
        {
            return key_names_table[i].enabled ? i : -1;
        }
    }

    return -1;
}

    static int
cmp_key_name_entry(const void *a, const void *b)
{
    char_u  *p1 = ((struct key_name_entry *)a)->name.string;
    char_u  *p2 = ((struct key_name_entry *)b)->name.string;
    int     result = 0;

    if (p1 == p2)
    {
        return 0;
    }

    while (vim_isNormalIDc(*p1) && *p2 != NUL)
    {
        if ((result =  (((*p1) < 'A' || (*p1) > 'Z') ? (*p1) : (*p1) + ('a' - 'A'))  -  (((*p2) < 'A' || (*p2) > 'Z') ? (*p2) : (*p2) + ('a' - 'A')) ) != 0)
        {
            break;
        }
        ++p1;
        ++p2;
    }

    if (result == 0)
    {
        if (*p2 == NUL)
        {
            if (vim_isNormalIDc(*p1))
            {
                result = 1;
            }
        }
        else
        {
            result = -1;
        }
    }

    return result;
}

    static int
get_special_key_code(char_u *name)
{
    if (name[0] == 't' && name[1] == '_' && name[2] != NUL && name[3] != NUL)
    {
        char_u  string[3];

        string[0] = name[2];
        string[1] = name[3];
        string[2] = NUL;
        if (add_termcap_entry(string, FALSE) == OK)
        {
            return  (-((name[2]) + ((int)(name[3]) << 8))) ;
        }
    }
    else
    {
        struct key_name_entry   target;
        struct key_name_entry   *entry;

        target.enabled = TRUE;
        target.key = 0;
        target.name.string = name;
        target.name.length = 0;

        entry = (struct key_name_entry *)bsearch(&target, &key_names_table,  (sizeof(key_names_table) / sizeof((key_names_table)[0])) , sizeof(key_names_table[0]), cmp_key_name_entry);
        if (entry != NULL && entry->enabled)
        {
            int key = entry->key;
            return key ==   (-((KS_EXTRA) + ((int)(KE_TAB) << 8)))   ? TAB : key;
        }
    }

    return 0;
}

    static char_u *
get_key_name(int i)
{
    if (i < 0 || i >= (int) (sizeof(key_names_table) / sizeof((key_names_table)[0])) )
    {
        return NULL;
    }

    return key_names_table[i].name.string;
}

    static int
get_fileformat(buf_T *buf)
{
    int         c = *buf->b_p_ff;

    if (buf->b_p_bin || c == 'u')
    {
        return EOL_UNIX;
    }
    if (c == 'm')
    {
        return EOL_MAC;
    }
    return EOL_DOS;
}

    static int
get_fileformat_force(buf_T       *buf, exarg_T     *eap)
{
    int         c;

    if (eap != NULL && eap->force_ff != 0)
    {
        c = eap->force_ff;
    }
    else
    {
        if ((eap != NULL && eap->force_bin != 0) ? (eap->force_bin == FORCE_BIN) : buf->b_p_bin)
        {
            return EOL_UNIX;
        }
        c = *buf->b_p_ff;
    }
    if (c == 'u')
    {
        return EOL_UNIX;
    }
    if (c == 'm')
    {
        return EOL_MAC;
    }
    return EOL_DOS;
}

    static void
set_fileformat(int         t, int         opt_flags)
{
    char        *p = NULL;

    switch (t)
    {
    case EOL_DOS:
        p =  "dos" ;
        curbuf->b_p_tx = TRUE;
        break;
    case EOL_UNIX:
        p =  "unix" ;
        curbuf->b_p_tx = FALSE;
        break;
    case EOL_MAC:
        p =  "mac" ;
        curbuf->b_p_tx = FALSE;
        break;
    }
    if (p != NULL)
    {
        set_string_option_direct((char_u *)"ff", -1, (char_u *)p, OPT_FREE | opt_flags, 0);
    }

    check_status(curbuf);
    redraw_tabline = TRUE;
    need_maketitle = TRUE;
}

    static int
default_fileformat(void)
{
    switch (*p_ffs)
    {
        case 'm':
            return EOL_MAC;
        case 'd':
            return EOL_DOS;
    }
    return EOL_UNIX;
}

    static int
get_real_state(void)
{
    if (State & MODE_NORMAL)
    {
        if (VIsual_active)
        {
            if (VIsual_select)
            {
                return MODE_SELECT;
            }
            return MODE_VISUAL;
        }
        else if (finish_op)
        {
            return MODE_OP_PENDING;
        }
    }
    return State;
}

    static int
after_pathsep(char_u *b, char_u *p)
{
    return p > b && vim_ispathsep(p[-1])
                             && (!has_mbyte || (*mb_head_off)(b, p - 1) == 0);
}

    static int
same_directory(char_u *f1, char_u *f2)
{
    char_u      ffname[ PATH_MAX ];
    char_u      *t1;
    char_u      *t2;

    if (f1 == NULL || f2 == NULL)
    {
        return FALSE;
    }

    (void)vim_FullName(f1, ffname,  PATH_MAX , FALSE);
    t1 = gettail_sep(ffname);
    t2 = gettail_sep(f2);
    return (t1 - ffname == t2 - f2 && pathcmp((char *)ffname, (char *)f2, (int)(t1 - ffname)) == 0);
}

    static int
get_user_name(char_u *buf, int len)
{
    if (username == NULL)
    {
        if (mch_get_user_name(buf, len) == FAIL)
        {
            return FAIL;
        }
        username = vim_strsave(buf);
    }
    else
    {
        vim_strncpy(buf, username, len - 1);
    }
    return OK;
}

    static long
elapsed(struct timeval *start_tv)
{
    struct timeval  now_tv;

    gettimeofday(&now_tv, NULL);
    return (now_tv.tv_sec - start_tv->tv_sec) * 1000L
         + (now_tv.tv_usec - start_tv->tv_usec) / 1000L;
}

    static int
cmp_keyvalue_value_n(const void *a, const void *b)
{
    keyvalue_T *kv1 = (keyvalue_T *)a;
    keyvalue_T *kv2 = (keyvalue_T *)b;

    return  strncmp((char *)(kv1->value.string), (char *)(kv2->value.string), (MAX(kv1->value.length, kv2->value.length))) ;
}

    static int
cmp_keyvalue_value_i(const void *a, const void *b)
{
    keyvalue_T *kv1 = (keyvalue_T *)a;
    keyvalue_T *kv2 = (keyvalue_T *)b;

    return  strcasecmp((char *)(kv1->value.string), (char *)(kv2->value.string)) ;
}

    static int
cmp_keyvalue_value_ni(const void *a, const void *b)
{
    keyvalue_T *kv1 = (keyvalue_T *)a;
    keyvalue_T *kv2 = (keyvalue_T *)b;

    return vim_strnicmp_asc((char *)kv1->value.string, (char *)kv2->value.string, MAX(kv1->value.length, kv2->value.length));
}

    static void *
mergesort_list(void        *head, void        *(*get_next)(void *), void        (*set_next)(void *, void *), void        *(*get_prev)(void *), void        (*set_prev)(void *, void *), int         (*compare)(const void *, const void *))
{
    if (!head || !get_next(head))
    {
        return head;
    }

    int     n = 0;
    void*   curr = head;
    while (curr)
    {
        n++;
        curr = get_next(curr);
    }

    int size;
    for (size = 1; size < n; size *= 2)
    {
        void*   new_head = NULL;
        void*   tail = NULL;
        curr = head;

        while (curr)
        {
            void    *left = curr;
            void    *right = left;
            int     i;
            for (i = 0; i < size && right; ++i)
            {
                right = get_next(right);
            }

            void    *next = right;
            for (i = 0; i < size && next; ++i)
            {
                next = get_next(next);
            }

            void    *l_end = right ? get_prev(right) : NULL;
            if (l_end)
            {
                set_next(l_end, NULL);
            }
            if (right)
            {
                set_prev(right, NULL);
            }

            void    *r_end = next ? get_prev(next) : NULL;
            if (r_end)
            {
                set_next(r_end, NULL);
            }
            if (next)
            {
                set_prev(next, NULL);
            }

            void    *merged = NULL;
            void    *merged_tail = NULL;

            while (left || right)
            {
                void    *chosen = NULL;
                if (!left)
                {
                    chosen = right;
                    right = get_next(right);
                }
                else if (!right)
                {
                    chosen = left;
                    left = get_next(left);
                }
                else if (compare(left, right) <= 0)
                {
                    chosen = left;
                    left = get_next(left);
                }
                else
                {
                    chosen = right;
                    right = get_next(right);
                }

                if (merged_tail)
                {
                    set_next(merged_tail, chosen);
                    set_prev(chosen, merged_tail);
                    merged_tail = chosen;
                }
                else
                {
                    merged = merged_tail = chosen;
                    set_prev(chosen, NULL);
                }
            }

            if (!new_head)
            {
                new_head = merged;
            }
            else
            {
                set_next(tail, merged);
                set_prev(merged, tail);
            }

            while (get_next(merged_tail))
            {
                merged_tail = get_next(merged_tail);
            }
            tail = merged_tail;

            curr = next;
        }

        head = new_head;
    }

    return head;
}

// ==================== mouse.c ====================

static long mouse_hor_step = 6;
static long mouse_vert_step = 3;
static win_T *dragwin = NULL;
static int stl_click_handler(win_T *wp, int mrow, int mcol, int which_button, int mods);
static int stl_click_handler_regions(stl_click_region_T *regions, int region_count, int winid, char_u *area_name, int mrow, int mcol, int which_button, int mods);

    static long
time_diff_ms(struct timeval *t1, struct timeval *t2)
{
    return (t2->tv_sec - t1->tv_sec) * 1000
         + (t2->tv_usec - t1->tv_usec) / 1000;
}

    static int
get_mouse_class(char_u *p)
{
    int         c;

    if (has_mbyte &&  mb_bytelen_tab[p[0]]  > 1)
    {
        return mb_get_class(p);
    }

    c = *p;
    if (c == ' ' || c == '\t')
    {
        return 0;
    }

    if (vim_iswordc(c))
    {
        return 2;
    }

    if (c != NUL && vim_strchr((char_u *)"-+*/%<>&|^!=", c) != NULL)
    {
        return 1;
    }
    return c;
}

    static void
find_start_of_word(pos_T *pos)
{
    char_u      *line;
    int         cclass;
    int         col;

    line = ml_get(pos->lnum);
    cclass = get_mouse_class(line + pos->col);

    while (pos->col > 0)
    {
        col = pos->col - 1;
        col -= (*mb_head_off)(line, line + col);
        if (get_mouse_class(line + col) != cclass)
        {
            break;
        }
        pos->col = col;
    }
}

    static void
find_end_of_word(pos_T *pos)
{
    char_u      *line;
    int         cclass;
    int         col;

    line = ml_get(pos->lnum);
    if (*p_sel == 'e' && pos->col > 0)
    {
        --pos->col;
        pos->col -= (*mb_head_off)(line, line + pos->col);
    }
    cclass = get_mouse_class(line + pos->col);
    while (line[pos->col] != NUL)
    {
        col = pos->col + (*mb_ptr2len)(line + pos->col);
        if (get_mouse_class(line + col) != cclass)
        {
            if (*p_sel == 'e')
            {
                pos->col = col;
            }
            break;
        }
        pos->col = col;
    }
}

    static int
do_mouse(oparg_T     *oap, int         c, int         dir, long        count, int         fixindent)
{
    static int  do_always = FALSE;
    static int  got_click = FALSE;

    int         which_button;
    int         is_click = FALSE;
    int         is_drag = FALSE;
    int         jump_flags = 0;
    pos_T       start_visual;
    int         moved;
    int         in_status_line;
    static int  in_tab_line = FALSE;
    static int  in_tabpanel = FALSE;
    int         in_sep_line;
    int c1;
    int c2;
    win_T       *old_curwin = curwin;
    static pos_T orig_cursor;
    colnr_T leftcol;
    colnr_T rightcol;
    pos_T       end_visual;
    int         diff;
    int         old_active = VIsual_active;
    int         old_mode = VIsual_mode;
    int         regname;

    if (do_always)
    {
        do_always = FALSE;
    }
    else
        {
            if (VIsual_active)
            {
                if (!mouse_has(MOUSE_VISUAL))
                {
                    return FALSE;
                }
            }
            else if (State == MODE_NORMAL && !mouse_has(MOUSE_NORMAL))
            {
                return FALSE;
            }
        }

    for (;;)
    {
        which_button = get_mouse_button( (((unsigned)(-(c)) >> 8) & 0xff) , &is_click, &is_drag);
        if (is_drag)
        {
            if (!KeyStuffed && vpeekc() != NUL)
            {
                int nc;
                int save_mouse_row = mouse_row;
                int save_mouse_col = mouse_col;

                nc = safe_vgetc();
                if (c == nc)
                {
                    continue;
                }
                vungetc(nc);
                mouse_row = save_mouse_row;
                mouse_col = save_mouse_col;
            }
        }
        break;
    }

    if (c ==   (-((KS_EXTRA) + ((int)(KE_MOUSEMOVE) << 8)))  )
    {
        return FALSE;
    }

    if (is_click)
    {
        got_click = TRUE;
        in_tab_line = FALSE;
        in_tabpanel = FALSE;
    }
    else
    {
        if (!got_click)
        {
            return FALSE;
        }
        if (!is_drag)
        {
            got_click = FALSE;
            if (in_tab_line || in_tabpanel)
            {
                in_tab_line = FALSE;
                in_tabpanel = FALSE;
                return FALSE;
            }
        }
    }

    if (is_click && (mod_mask & MOD_MASK_CTRL) && which_button == MOUSE_RIGHT)
    {
        if (State & MODE_INSERT)
        {
            stuffcharReadbuff(Ctrl_O);
        }
        if (count > 1)
        {
            stuffnumReadbuff(count);
        }
        stuffcharReadbuff(Ctrl_T);
        got_click = FALSE;
        return FALSE;
    }

    if ((mod_mask & MOD_MASK_CTRL) && which_button != MOUSE_LEFT)
    {
        return FALSE;
    }

    if ((mod_mask & (MOD_MASK_SHIFT | MOD_MASK_CTRL | MOD_MASK_ALT | MOD_MASK_META)) && (!is_click || (mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) || which_button == MOUSE_MIDDLE) && !((mod_mask & (MOD_MASK_SHIFT|MOD_MASK_ALT)) && mouse_model_popup() && which_button == MOUSE_LEFT) && !((mod_mask & MOD_MASK_ALT) && !mouse_model_popup() && which_button == MOUSE_RIGHT))
    {
        return FALSE;
    }

    if (!is_click && which_button == MOUSE_MIDDLE)
    {
        return FALSE;
    }

    if (oap != NULL)
    {
        regname = oap->regname;
    }
    else
    {
        regname = 0;
    }

    if (which_button == MOUSE_MIDDLE)
    {
        if (State == MODE_NORMAL)
        {
            if (oap != NULL && oap->op_type != OP_NOP)
            {
                clearopbeep(oap);
                return FALSE;
            }

            if (VIsual_active)
            {
                if (VIsual_select)
                {
                    stuffcharReadbuff(Ctrl_G);
                    stuffReadbuff((char_u *)"\"+p");
                }
                else
                {
                    stuffcharReadbuff('y');
                    stuffcharReadbuff(  (-((KS_EXTRA) + ((int)(KE_MIDDLEMOUSE) << 8)))  );
                }
                do_always = TRUE;
                return FALSE;
            }
        }

        else if ((State & MODE_INSERT) == 0)
        {
            return FALSE;
        }

        if ((State & MODE_INSERT) || !mouse_has(MOUSE_NORMAL))
        {
            if (regname == '.')
            {
                insert_reg(regname, TRUE);
            }
            else
            {
                if ((State & REPLACE_FLAG) && !yank_register_mline(regname))
                {
                    insert_reg(regname, TRUE);
                }
                else
                {
                    do_put(regname, NULL,  (-1) , 1L, fixindent | PUT_CURSEND);

                    AppendCharToRedobuff(Ctrl_R);
                    AppendCharToRedobuff(fixindent ? Ctrl_P : Ctrl_O);
                    AppendCharToRedobuff(regname == 0 ? '"' : regname);
                }
            }
            return FALSE;
        }
    }

    if (!is_click)
    {
        jump_flags |= MOUSE_FOCUS | MOUSE_DID_MOVE;
    }

    start_visual.lnum = 0;

    struct tabpage_label_info {
        bool is_panel;
        bool just_in;
        bool just_click;
        int nr;
    } tp_label = { false, false, false, 0 };

    if (TabPageIdxs != NULL && mouse_row == 0 && firstwin->w_winrow > 0)
    {
        if (is_click && !is_drag && stl_click_handler_regions(tabline_stl_click, tabline_stl_click_count, 0, (char_u *)"tabline", mouse_row, mouse_col, which_button, mod_mask))
        {
            return FALSE;
        }

        tp_label.just_in = true;
        tp_label.nr = TabPageIdxs[mouse_col];

        if (is_click && cmdwin_type == 0 && mouse_col < firstwin->w_wincol + topframe->fr_width)
        {
            tp_label.just_click = true;
        }
    }

    if (tp_label.just_in)
    {
        if (is_drag)
        {
            if (in_tabpanel || in_tab_line)
            {
                c1 = tp_label.nr;
                tabpage_move(c1 <= 0 ? 9999 : c1 < tabpage_index(curtab) ? c1 - 1 : c1);
            }
            return FALSE;
        }

        if (tp_label.just_click)
        {
            if (tp_label.is_panel)
            {
                in_tabpanel = TRUE;
            }
            else
            {
                in_tab_line = TRUE;
            }
            c1 = tp_label.nr;
            if (c1 >= 0)
            {
                if ((mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) == MOD_MASK_2CLICK && !tp_label.is_panel)
                {
                    end_visual_mode_keep_button();
                    tabpage_new();
                    tabpage_move(c1 == 0 ? 9999 : c1 - 1);
                }
                else
                {
                    goto_tabpage(c1);

                    if (curwin != old_curwin)
                    {
                        end_visual_mode_keep_button();
                    }
                }
            }
            else
            {
                tabpage_T       *tp;

                if (c1 == -999)
                {
                    tp = curtab;
                }
                else
                {
                    tp = find_tabpage(-c1);
                }
                if (tp == curtab)
                {
                    if (first_tabpage->tp_next != NULL)
                    {
                        tabpage_close(FALSE);
                    }
                }
                else if (tp != NULL)
                {
                    tabpage_close_other(tp, FALSE);
                }
            }
        }
        return TRUE;
    }
    else if (is_drag && (in_tabpanel || (in_tab_line && TabPageIdxs != NULL)))
    {
            c1 = TabPageIdxs[mouse_col];
        tabpage_move(c1 <= 0 ? 9999 : c1 - 1);
        return FALSE;
    }

    if (mouse_model_popup())
    {
        if (which_button == MOUSE_RIGHT && !(mod_mask & (MOD_MASK_SHIFT | MOD_MASK_CTRL)))
        {
            return FALSE;
        }
        if (which_button == MOUSE_LEFT && (mod_mask & (MOD_MASK_SHIFT|MOD_MASK_ALT)))
        {
            which_button = MOUSE_RIGHT;
            mod_mask &= ~MOD_MASK_SHIFT;
        }
    }

    if ((State & (MODE_NORMAL | MODE_INSERT)) && !(mod_mask & (MOD_MASK_SHIFT | MOD_MASK_CTRL)))
    {
        if (which_button == MOUSE_LEFT)
        {
            if (is_click)
            {
                if (VIsual_active)
                {
                    jump_flags |= MOUSE_MAY_STOP_VIS;
                }
            }
            else if (mouse_has(MOUSE_VISUAL))
            {
                jump_flags |= MOUSE_MAY_VIS;
            }
        }
        else if (which_button == MOUSE_RIGHT)
        {
            if (is_click && VIsual_active)
            {
                if ( (((curwin->w_cursor).lnum != (VIsual).lnum)               ? (curwin->w_cursor).lnum < (VIsual).lnum                   : (curwin->w_cursor).col != (VIsual).col                        ? (curwin->w_cursor).col < (VIsual).col                     : (curwin->w_cursor).coladd < (VIsual).coladd) )
                {
                    start_visual = curwin->w_cursor;
                    end_visual = VIsual;
                }
                else
                {
                    start_visual = VIsual;
                    end_visual = curwin->w_cursor;
                }
            }
            jump_flags |= MOUSE_FOCUS;
            if (mouse_has(MOUSE_VISUAL))
            {
                jump_flags |= MOUSE_MAY_VIS;
            }
        }
    }

    if (!is_drag && oap != NULL && oap->op_type != OP_NOP)
    {
        got_click = FALSE;
        oap->motion_type = MCHAR;
    }

    if (!is_click && !is_drag)
    {
        jump_flags |= MOUSE_RELEASED;
    }

    jump_flags = jump_to_mouse(jump_flags, oap == NULL ? NULL : &(oap->inclusive), which_button);

    moved = (jump_flags & CURSOR_MOVED);
    in_status_line = (jump_flags & IN_STATUS_LINE);
    in_sep_line = (jump_flags & IN_SEP_LINE);

    if (in_status_line && is_click && !is_drag && stl_click_handler(dragwin, mouse_row, mouse_col, which_button, mod_mask))
    {
        return FALSE;
    }

    if (curwin != old_curwin && oap != NULL && oap->op_type != OP_NOP)
    {
        clearop(oap);
    }

    if (VIsual_active && is_drag && get_scrolloff_value())
    {
        if (mouse_row == 0)
        {
            mouse_dragging = 2;
        }
        else
        {
            mouse_dragging = 1;
        }
    }

    if (is_drag && mouse_row < 0 && !in_status_line)
    {
        scroll_redraw(FALSE, 1L);
        mouse_row = 0;
    }

    if (start_visual.lnum)
    {
       if (mod_mask & MOD_MASK_ALT)
       {
           VIsual_mode = Ctrl_V;
       }

        if (VIsual_mode == Ctrl_V)
        {
            getvcols(curwin, &start_visual, &end_visual, &leftcol, &rightcol, 0);
            if (curwin->w_curswant > (leftcol + rightcol) / 2)
            {
                end_visual.col = leftcol;
            }
            else
            {
                end_visual.col = rightcol;
            }
            if (curwin->w_cursor.lnum >= (start_visual.lnum + end_visual.lnum) / 2)
            {
                end_visual.lnum = start_visual.lnum;
            }

            start_visual = curwin->w_cursor;
            curwin->w_cursor = end_visual;
            coladvance(end_visual.col);
            VIsual = curwin->w_cursor;
            curwin->w_cursor = start_visual;
        }
        else
        {
            if ( (((curwin->w_cursor).lnum != (start_visual).lnum)               ? (curwin->w_cursor).lnum < (start_visual).lnum                   : (curwin->w_cursor).col != (start_visual).col                        ? (curwin->w_cursor).col < (start_visual).col                     : (curwin->w_cursor).coladd < (start_visual).coladd) )
            {
                VIsual = end_visual;
            }
            else if ( (((end_visual).lnum != (curwin->w_cursor).lnum)               ? (end_visual).lnum < (curwin->w_cursor).lnum                   : (end_visual).col != (curwin->w_cursor).col                        ? (end_visual).col < (curwin->w_cursor).col                     : (end_visual).coladd < (curwin->w_cursor).coladd) )
            {
                VIsual = start_visual;
            }
            else
            {
                if (end_visual.lnum == start_visual.lnum)
                {
                    if (curwin->w_cursor.col - start_visual.col > end_visual.col - curwin->w_cursor.col)
                    {
                        VIsual = start_visual;
                    }
                    else
                    {
                        VIsual = end_visual;
                    }
                }

                else
                {
                    diff = (curwin->w_cursor.lnum - start_visual.lnum) -
                                (end_visual.lnum - curwin->w_cursor.lnum);

                    if (diff > 0)
                    {
                        VIsual = start_visual;
                    }
                    else if (diff < 0)
                    {
                        VIsual = end_visual;
                    }
                    else
                    {
                        if (curwin->w_cursor.col < (start_visual.col + end_visual.col) / 2)
                        {
                            VIsual = end_visual;
                        }
                        else
                        {
                            VIsual = start_visual;
                        }
                    }
                }
            }
        }
    }
    else if ((State & MODE_INSERT) && VIsual_active)
    {
        stuffcharReadbuff(Ctrl_O);
    }

    if (which_button == MOUSE_MIDDLE)
    {
        if (yank_register_mline(regname))
        {
            if (mouse_past_bottom)
            {
                dir = FORWARD;
            }
        }
        else if (mouse_past_eol)
        {
            dir = FORWARD;
        }

        if (fixindent)
        {
            c1 = (dir ==  (-1) ) ? '[' : ']';
            c2 = 'p';
        }
        else
        {
            c1 = (dir == FORWARD) ? 'p' : 'P';
            c2 = NUL;
        }
        prep_redo(regname, count, NUL, c1, NUL, c2, NUL);

        if (restart_edit != 0)
        {
            where_paste_started = curwin->w_cursor;
        }
        do_put(regname, NULL, dir, count, fixindent | PUT_CURSEND);
    }

    else if ((mod_mask & MOD_MASK_CTRL) || (curbuf->b_help && (mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) == MOD_MASK_2CLICK))
    {
        if (State & MODE_INSERT)
        {
            stuffcharReadbuff(Ctrl_O);
        }
        stuffcharReadbuff(Ctrl_RSB);
        got_click = FALSE;
    }

    else if ((mod_mask & MOD_MASK_SHIFT))
    {
        if ((State & MODE_INSERT) || (VIsual_active && VIsual_select))
        {
            stuffcharReadbuff(Ctrl_O);
        }
        if (which_button == MOUSE_LEFT)
        {
            stuffcharReadbuff('*');
        }
        else
        {
            stuffcharReadbuff('#');
        }
    }

    else if (in_status_line)
    {
    }
    else if (in_sep_line)
    {
    }
    else if ((mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) && (State & (MODE_NORMAL | MODE_INSERT)) && mouse_has(MOUSE_VISUAL))
    {
        if (is_click || !VIsual_active)
        {
            if (VIsual_active)
            {
                orig_cursor = VIsual;
            }
            else
            {
                check_visual_highlight();
                VIsual = curwin->w_cursor;
                orig_cursor = VIsual;
                VIsual_active = TRUE;
                VIsual_reselect = TRUE;
                may_start_select('o');
                setmouse();
            }
            if ((mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) == MOD_MASK_2CLICK)
            {
                if (mod_mask & MOD_MASK_ALT)
                {
                    VIsual_mode = Ctrl_V;
                }
                else
                {
                    VIsual_mode = 'v';
                }
            }
            else if ((mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) == MOD_MASK_3CLICK)
            {
                VIsual_mode = 'V';
            }
            else if ((mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) == MOD_MASK_4CLICK)
            {
                VIsual_mode = Ctrl_V;
            }
        }
        if ((mod_mask &  (MOD_MASK_2CLICK|MOD_MASK_3CLICK|MOD_MASK_4CLICK) ) == MOD_MASK_2CLICK)
        {
            pos_T       *pos = NULL;
            int         gc;

            if (is_click)
            {
                end_visual = curwin->w_cursor;
                while (gc = gchar_pos(&end_visual),  ((gc) == ' ' || (gc) == '\t') )
                {
                    inc(&end_visual);
                }
                if (oap != NULL)
                {
                    oap->motion_type = MCHAR;
                }
                if (oap != NULL && VIsual_mode == 'v' && !vim_iswordc(gchar_pos(&end_visual)) &&  (((curwin->w_cursor).lnum == (VIsual).lnum) && ((curwin->w_cursor).col == (VIsual).col) && ((curwin->w_cursor).coladd == (VIsual).coladd))  && (pos = findmatch(oap, NUL)) != NULL)
                {
                    curwin->w_cursor = *pos;
                    if (oap->motion_type == MLINE)
                    {
                        VIsual_mode = 'V';
                    }
                    else if (*p_sel == 'e')
                    {
                        if ( (((curwin->w_cursor).lnum != (VIsual).lnum)               ? (curwin->w_cursor).lnum < (VIsual).lnum                   : (curwin->w_cursor).col != (VIsual).col                        ? (curwin->w_cursor).col < (VIsual).col                     : (curwin->w_cursor).coladd < (VIsual).coladd) )
                        {
                            ++VIsual.col;
                        }
                        else
                        {
                            ++curwin->w_cursor.col;
                        }
                    }
                }
            }

            if (pos == NULL && (is_click || is_drag))
            {
                if ( (((curwin->w_cursor).lnum != (orig_cursor).lnum)               ? (curwin->w_cursor).lnum < (orig_cursor).lnum                   : (curwin->w_cursor).col != (orig_cursor).col                        ? (curwin->w_cursor).col < (orig_cursor).col                     : (curwin->w_cursor).coladd < (orig_cursor).coladd) )
                {
                    find_start_of_word(&curwin->w_cursor);
                    find_end_of_word(&VIsual);
                }
                else
                {
                    find_start_of_word(&VIsual);
                    if (*p_sel == 'e' && *ml_get_cursor() != NUL)
                    {
                        curwin->w_cursor.col +=
                                         (*mb_ptr2len)(ml_get_cursor());
                    }
                    find_end_of_word(&curwin->w_cursor);
                }
            }
            curwin->w_set_curswant = true;
        }
        if (is_click)
        {
            redraw_curbuf_later(UPD_INVERTED);
        }
    }
    else if (VIsual_active && !old_active)
    {
        if (mod_mask & MOD_MASK_ALT)
        {
            VIsual_mode = Ctrl_V;
        }
        else
        {
            VIsual_mode = 'v';
        }
    }

    if ((!VIsual_active && old_active && mode_displayed) || (VIsual_active && p_smd && msg_silent == 0 && (!old_active || VIsual_mode != old_mode)))
    {
        redraw_cmdline = TRUE;
    }

    return moved;
}

    static void
ins_mouse(int c)
{
    pos_T       tpos;
    win_T       *old_curwin = curwin;

        if (!mouse_has(MOUSE_INSERT))
        {
            return;
        }

    undisplay_dollar();
    tpos = curwin->w_cursor;
    if (do_mouse(NULL, c,  (-1) , 1L, 0))
    {
        win_T   *new_curwin = curwin;

        if (curwin != old_curwin && win_valid(old_curwin))
        {
            curwin = old_curwin;
            curbuf = curwin->w_buffer;
        }
        start_arrow(curwin == old_curwin ? &tpos : NULL);
        if (curwin != new_curwin && win_valid(new_curwin))
        {
            curwin = new_curwin;
            curbuf = curwin->w_buffer;
        }
        set_can_cindent(TRUE);
    }

    redraw_statuslines();
}

    static void
do_mousescroll(cmdarg_T *cap)
{
    int shift_or_ctrl = mod_mask & (MOD_MASK_SHIFT | MOD_MASK_CTRL);

    if (cap->arg == MSCR_UP || cap->arg == MSCR_DOWN)
    {
        if (!(State & MODE_INSERT) && (mouse_vert_step < 0 || shift_or_ctrl))
        {
            pagescroll(cap->arg == MSCR_UP ? FORWARD :  (-1) , 1L, FALSE);
        }
        else
        {
            if (mouse_vert_step < 0 || shift_or_ctrl)
            {
                cap->count1 = (long)(curwin->w_botline - curwin->w_topline);
            }
            else if (curwin->w_height < mouse_vert_step * 2)
            {
                cap->count1 = curwin->w_height / 2;
                if (cap->count1 == 0)
                {
                    cap->count1 = 1;
                }
            }
            else
            {
                cap->count1 = mouse_vert_step;
            }
            cap->count0 = cap->count1;
            nv_scroll_line(cap);
        }

    }
    else
    {
        long step = (mouse_hor_step < 0 || shift_or_ctrl)
                                            ? curwin->w_width : mouse_hor_step;
        long leftcol = curwin->w_leftcol
                                     + (cap->arg ==  (-2)  ? -step : step);
        if (leftcol < 0)
        {
            leftcol = 0;
        }
        do_mousescroll_horiz((long_u)leftcol);
    }
    may_trigger_win_scrolled_resized();
}

    static void
ins_mousescroll(int dir)
{
    cmdarg_T    cap;
    oparg_T     oa;
      memset((&(cap)), (0), (sizeof(cap)))  ;
    clear_oparg(&oa);
    cap.oap = &oa;
    cap.arg = dir;

    switch (dir)
    {
        case MSCR_UP:
            cap.cmdchar =   (-((KS_EXTRA) + ((int)(KE_MOUSEUP) << 8)))  ;
            break;
        case MSCR_DOWN:
            cap.cmdchar =   (-((KS_EXTRA) + ((int)(KE_MOUSEDOWN) << 8)))  ;
            break;
        case  (-1) :
            cap.cmdchar =   (-((KS_EXTRA) + ((int)(KE_MOUSELEFT) << 8)))  ;
            break;
        case  (-2) :
            cap.cmdchar =   (-((KS_EXTRA) + ((int)(KE_MOUSERIGHT) << 8)))  ;
            break;
        default:
            siemsg("Invalid ins_mousescroll() argument: %d", dir);
    }

    win_T *old_curwin = curwin;
    if (mouse_row >= 0 && mouse_col >= 0)
    {
        int row = mouse_row;
        int col = mouse_col;
        curwin = mouse_find_win(&row, &col, FIND_POPUP);
        if (curwin == NULL)
        {
            curwin = old_curwin;
            return;
        }
        curbuf = curwin->w_buffer;
    }

    if (curwin == old_curwin)
    {
        if (pum_visible())
        {
            return;
        }

        undisplay_dollar();
    }

    linenr_T    orig_topline = curwin->w_topline;
    colnr_T     orig_leftcol = curwin->w_leftcol;
    pos_T       orig_cursor = curwin->w_cursor;

    do_mousescroll(&cap);

    int did_scroll = (orig_topline != curwin->w_topline || orig_leftcol != curwin->w_leftcol);

    curwin->w_redr_status = true;
    curwin = old_curwin;
    curbuf = curwin->w_buffer;

    if (did_scroll && pum_visible())
    {
        redraw_all_later(UPD_NOT_VALID);
        ins_compl_show_pum();
    }

    if (! (((curwin->w_cursor).lnum == (orig_cursor).lnum) && ((curwin->w_cursor).col == (orig_cursor).col) && ((curwin->w_cursor).coladd == (orig_cursor).coladd)) )
    {
        start_arrow(&orig_cursor);
        set_can_cindent(TRUE);
    }
}

    static int
is_mouse_key(int c)
{
    return c ==   (-((KS_EXTRA) + ((int)(KE_LEFTMOUSE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_LEFTMOUSE_NM) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_LEFTDRAG) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_LEFTRELEASE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_LEFTRELEASE_NM) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MOUSEMOVE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MIDDLEMOUSE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MIDDLEDRAG) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MIDDLERELEASE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_RIGHTMOUSE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_RIGHTDRAG) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_RIGHTRELEASE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MOUSEDOWN) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MOUSEUP) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MOUSELEFT) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_MOUSERIGHT) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_X1MOUSE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_X1DRAG) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_X1RELEASE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_X2MOUSE) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_X2DRAG) << 8)))  
        || c ==   (-((KS_EXTRA) + ((int)(KE_X2RELEASE) << 8)))  ;
}

static struct mousetable
{
    int     pseudo_code;
    int     button;
    int     is_click;
    int     is_drag;
} mouse_table[] =
{
    {(int)KE_LEFTMOUSE,         MOUSE_LEFT,     TRUE,   FALSE},
    {(int)KE_LEFTDRAG,          MOUSE_LEFT,     FALSE,  TRUE},
    {(int)KE_LEFTRELEASE,       MOUSE_LEFT,     FALSE,  FALSE},
    {(int)KE_MIDDLEMOUSE,       MOUSE_MIDDLE,   TRUE,   FALSE},
    {(int)KE_MIDDLEDRAG,        MOUSE_MIDDLE,   FALSE,  TRUE},
    {(int)KE_MIDDLERELEASE,     MOUSE_MIDDLE,   FALSE,  FALSE},
    {(int)KE_RIGHTMOUSE,        MOUSE_RIGHT,    TRUE,   FALSE},
    {(int)KE_RIGHTDRAG,         MOUSE_RIGHT,    FALSE,  TRUE},
    {(int)KE_RIGHTRELEASE,      MOUSE_RIGHT,    FALSE,  FALSE},
    {(int)KE_X1MOUSE,           MOUSE_X1,       TRUE,   FALSE},
    {(int)KE_X1DRAG,            MOUSE_X1,       FALSE,  TRUE},
    {(int)KE_X1RELEASE,         MOUSE_X1,       FALSE,  FALSE},
    {(int)KE_X2MOUSE,           MOUSE_X2,       TRUE,   FALSE},
    {(int)KE_X2DRAG,            MOUSE_X2,       FALSE,  TRUE},
    {(int)KE_X2RELEASE,         MOUSE_X2,       FALSE,  FALSE},
    {(int)KE_MOUSEMOVE,         MOUSE_RELEASE,  FALSE,  TRUE},
    {(int)KE_IGNORE,            MOUSE_RELEASE,  FALSE,  FALSE},
    {0,                         0,              0,      0},
};

    static int
get_mouse_button(int code, int *is_click, int *is_drag)
{
    int     i;

    for (i = 0; mouse_table[i].pseudo_code; i++)
    {
        if (code == mouse_table[i].pseudo_code)
        {
            *is_click = mouse_table[i].is_click;
            *is_drag = mouse_table[i].is_drag;
            return mouse_table[i].button;
        }
    }
    return 0;
}

    static int
get_pseudo_mouse_code(int     button, int     is_click, int     is_drag)
{
    int     i;

    for (i = 0; mouse_table[i].pseudo_code; i++)
    {
        if (button == mouse_table[i].button && is_click == mouse_table[i].is_click && is_drag == mouse_table[i].is_drag)
        {
            return mouse_table[i].pseudo_code;
        }
    }
    return (int)KE_IGNORE;
}

enum { HMT_NORMAL = 1 };
enum { HMT_SGR = 128 };
enum { HMT_SGR_REL = 256 };
static int has_mouse_termcode = 0;

    static void
set_mouse_termcode(int         n, char_u      *s)
{
    char_u      name[2];

    name[0] = n;
    name[1] =  ('X') ;
    add_termcode(name, s, FALSE);
    if (n == KS_SGR_MOUSE)
    {
        has_mouse_termcode |= HMT_SGR;
    }
    else if (n == KS_SGR_MOUSE_RELEASE)
    {
        has_mouse_termcode |= HMT_SGR_REL;
    }
    else
    {
        has_mouse_termcode |= HMT_NORMAL;
    }
}

    static void
del_mouse_termcode(int         n)
{
    char_u      name[2];

    name[0] = n;
    name[1] =  ('X') ;
    del_termcode(name);
    if (n == KS_SGR_MOUSE)
    {
        has_mouse_termcode &= ~HMT_SGR;
    }
    else if (n == KS_SGR_MOUSE_RELEASE)
    {
        has_mouse_termcode &= ~HMT_SGR_REL;
    }
    else
    {
        has_mouse_termcode &= ~HMT_NORMAL;
    }
}

    static void
setmouse(void)
{
    int     checkfor;

    if (*p_mouse == NUL || has_mouse_termcode == 0)
    {
        return;
    }

    if (cur_tmode != TMODE_RAW)
    {
        mch_setmouse(FALSE);
        return;
    }

    if (VIsual_active)
    {
        checkfor = MOUSE_VISUAL;
    }
    else if (State ==  (0x2000 | MODE_NORMAL)  || State == MODE_ASKMORE || State == MODE_SETWSIZE)
    {
        checkfor = MOUSE_RETURN;
    }
    else if (State & MODE_INSERT)
    {
        checkfor = MOUSE_INSERT;
    }
    else if (State & MODE_CMDLINE)
    {
        checkfor = MOUSE_COMMAND;
    }
    else if (State == MODE_CONFIRM || State == MODE_EXTERNCMD)
    {
        checkfor = ' ';
    }
    else
    {
        checkfor = MOUSE_NORMAL;
    }

    if (mouse_has(checkfor))
    {
        mch_setmouse(TRUE);
    }
    else
    {
        mch_setmouse(FALSE);
    }
}

    static int
mouse_has(int c)
{
    char_u      *p;

    for (p = p_mouse; *p; ++p)
    {
        switch (*p)
        {
            case 'a':
                if (vim_strchr((char_u *) "nvich" , c) != NULL)
                {
                          return TRUE;
                }
                      break;
            case MOUSE_HELP:
                if (c != MOUSE_RETURN && curbuf->b_help)
                {
                                 return TRUE;
                }
                             break;
            default:
                if (c == *p)
                {
                    return TRUE;
                }
                break;
        }
    }
    return FALSE;
}

    static int
mouse_model_popup(void)
{
    return (p_mousem[0] == 'p');
}

    static int
stl_click_handler_regions(stl_click_region_T  *regions, int                 region_count, int                 winid, char_u              *area_name, int                 mrow, int                 mcol, int                 which_button, int                 mods)
{
    (void)regions;
    (void)region_count;
    (void)winid;
    (void)area_name;
    (void)mrow;
    (void)mcol;
    (void)which_button;
    (void)mods;
    return FALSE;
}

    static int
stl_click_handler(win_T *wp, int mrow, int mcol, int which_button, int mods)
{
    if (wp == NULL)
    {
        return FALSE;
    }
    return stl_click_handler_regions(wp->w_stl_click, wp->w_stl_click_count, wp->w_id, (char_u *)"statusline", mrow, mcol, which_button, mods);
}

    static void
reset_dragwin(void)
{
    dragwin = NULL;
}

    static int
jump_to_mouse(int         flags, int         *inclusive, int         which_button)
{
    static int  on_status_line = 0;
    static int  on_sep_line = 0;
    static int  prev_row = -1;
    static int  prev_col = -1;
    static int  did_drag = FALSE;

    win_T *wp;
    win_T *old_curwin;
    pos_T       old_cursor;
    int         count;
    int         first;
    int         row = mouse_row;
    int         col = mouse_col;
    colnr_T     col_from_screen = -1;

    mouse_past_bottom = FALSE;
    mouse_past_eol = FALSE;

    if (flags & MOUSE_RELEASED)
    {
        if (dragwin != NULL && !did_drag)
        {
            flags &= ~(MOUSE_FOCUS | MOUSE_DID_MOVE);
        }
        dragwin = NULL;
        did_drag = FALSE;
    }

    if ((flags & MOUSE_DID_MOVE) && prev_row == mouse_row && prev_col == mouse_col)
    {
retnomove:
        if (on_status_line)
        {
            return IN_STATUS_LINE;
        }
        if (on_sep_line)
        {
            return IN_SEP_LINE;
        }
        if (flags & MOUSE_MAY_STOP_VIS)
        {
            end_visual_mode_keep_button();
            redraw_curbuf_later(UPD_INVERTED);
        }
        return IN_BUFFER;
    }

    prev_row = mouse_row;
    prev_col = mouse_col;

    if (flags & MOUSE_SETPOS)
    {
        goto retnomove;
    }

    old_curwin = curwin;
    old_cursor = curwin->w_cursor;

    if (!(flags & MOUSE_FOCUS))
    {
        if (row < 0 || col < 0)
        {
            return IN_UNKNOWN;
        }

        wp = mouse_find_win(&row, &col, FIND_POPUP);
        if (wp == NULL)
        {
            return IN_UNKNOWN;
        }
        dragwin = NULL;

        if (row >= wp->w_height)
        {
            on_status_line = row - wp->w_height + 1;
            dragwin = wp;
        }
        else
        {
            on_status_line = 0;
        }
        if (col >= wp->w_width)
        {
            on_sep_line = col - wp->w_width + 1;
            dragwin = wp;
        }
        else
        {
            on_sep_line = 0;
        }

        if (on_status_line && on_sep_line)
        {
            if (stl_connected(wp))
            {
                on_sep_line = 0;
            }
            else
            {
                on_status_line = 0;
            }
        }

        if (VIsual_active && (wp->w_buffer != curwin->w_buffer || (!on_status_line && !on_sep_line && (flags & MOUSE_MAY_STOP_VIS))))
        {
            end_visual_mode_keep_button();
            redraw_curbuf_later(UPD_INVERTED);
        }
        if (cmdwin_type != 0 && wp != cmdwin_win)
        {
            on_sep_line = 0;
            row = 0;
            col += wp->w_wincol;
            wp = cmdwin_win;
        }
        if (dragwin == NULL || (flags & MOUSE_RELEASED))
        {
            win_enter(wp, TRUE);
        }

        if (curwin != old_curwin)
        {
            set_mouse_topline(curwin);
        }
        if (on_status_line)
        {
            if (curwin == old_curwin)
            {
                return IN_STATUS_LINE;
            }
            else
            {
                return IN_STATUS_LINE | CURSOR_MOVED;
            }
        }
        if (on_sep_line)
        {
            if (curwin == old_curwin)
            {
                return IN_SEP_LINE;
            }
            else
            {
                return IN_SEP_LINE | CURSOR_MOVED;
            }
        }

        curwin->w_cursor.lnum = curwin->w_topline;
    }
    else if (on_status_line && which_button == MOUSE_LEFT)
    {
        if (dragwin != NULL)
        {
            count = row -  (dragwin->w_winrow)  - dragwin->w_height + 1
                                                             - on_status_line;
            win_drag_status_line(dragwin, count);
            did_drag |= count;
        }
        return IN_STATUS_LINE;
    }
    else if (on_sep_line && which_button == MOUSE_LEFT)
    {
        if (dragwin != NULL)
        {
            count = col - dragwin->w_wincol - dragwin->w_width + 1
                                                                - on_sep_line;
            win_drag_vsep_line(dragwin, count);
            did_drag |= count;
        }
        return IN_SEP_LINE;
    }
    else
    {
        if (flags & MOUSE_MAY_STOP_VIS)
        {
            end_visual_mode_keep_button();
            redraw_curbuf_later(UPD_INVERTED);
        }

        row -=  (curwin->w_winrow) ;
        col -= curwin->w_wincol;

        if (row < 0)
        {
            count = 0;
            for (first = TRUE; curwin->w_topline > 1; )
            {
                    count += plines(curwin->w_topline - 1);
                if (!first && count > -row)
                {
                    break;
                }
                first = FALSE;
                {
                    --curwin->w_topline;
                }
            }
            curwin->w_valid &=
                      ~(VALID_WROW|VALID_CROW|VALID_BOTLINE|VALID_BOTLINE_AP);
            redraw_later(UPD_VALID);
            row = 0;
        }
        else if (row >= curwin->w_height)
        {
            count = 0;
            for (first = TRUE; curwin->w_topline < curbuf->b_ml.ml_line_count; )
            {
                    count += plines(curwin->w_topline);
                if (!first && count > row - curwin->w_height + 1)
                {
                    break;
                }
                first = FALSE;
                {
                    ++curwin->w_topline;
                }
            }
            redraw_later(UPD_VALID);
            curwin->w_valid &=
                      ~(VALID_WROW|VALID_CROW|VALID_BOTLINE|VALID_BOTLINE_AP);
            row = curwin->w_height - 1;
        }
        else if (row == 0)
        {
            if (mouse_dragging > 0 && curwin->w_cursor.lnum == curwin->w_buffer->b_ml.ml_line_count && curwin->w_cursor.lnum == curwin->w_topline)
            {
                curwin->w_valid &= ~(VALID_TOPLINE);
            }
        }
    }

    if (prev_row >=  (curwin->w_winrow)  && prev_row <  (curwin->w_winrow)  + curwin->w_height && prev_col >= curwin->w_wincol && prev_col <  ((curwin)->w_wincol + (curwin)->w_width)  && ScreenLines != NULL)
    {
        int off = LineOffset[prev_row] + prev_col;

        if (curwin->w_redr_type <= UPD_VALID_NO_UPDATE)
        {
            col_from_screen = ScreenCols[off];
        }
    }

    if (mouse_comp_pos(curwin, &row, &col, &curwin->w_cursor.lnum, NULL))
    {
        mouse_past_bottom = TRUE;
    }

    if ((flags & MOUSE_MAY_VIS) && !VIsual_active)
    {
        check_visual_highlight();
        VIsual = old_cursor;
        VIsual_active = TRUE;
        VIsual_reselect = TRUE;
        may_start_select('o');
        setmouse();
        if (p_smd && msg_silent == 0)
        {
            redraw_cmdline = TRUE;
        }
    }

    if (col_from_screen >= 0)
    {
        col = col_from_screen;
    }

    curwin->w_curswant = col;
    curwin->w_set_curswant = false;
    if (coladvance(col) == FAIL)
    {
        if (inclusive != NULL)
        {
            *inclusive = TRUE;
        }
        mouse_past_eol = TRUE;
    }
    else if (inclusive != NULL)
    {
        *inclusive = FALSE;
    }

    count = IN_BUFFER;
    if (curwin != old_curwin || curwin->w_cursor.lnum != old_cursor.lnum || curwin->w_cursor.col != old_cursor.col)
    {
        count |= CURSOR_MOVED;
    }

    return count;
}

    static int
do_mousescroll_horiz(long_u leftcol)
{
    if (curwin-> w_onebuf_opt.wo_wrap )
    {
        return FALSE;
    }

    if (curwin->w_leftcol == (colnr_T)leftcol)
    {
        return FALSE;
    }

    if (!virtual_active() && (long)leftcol > scroll_line_len(curwin->w_cursor.lnum))
    {
        curwin->w_cursor.lnum = ui_find_longest_lnum();
        curwin->w_cursor.col = 0;
    }

    return set_leftcol((colnr_T)leftcol);
}

    static void
nv_mousescroll(cmdarg_T *cap)
{
    win_T   *old_curwin = curwin;

    if (mouse_row >= 0 && mouse_col >= 0)
    {
        int row = mouse_row;
        int col = mouse_col;
        curwin = mouse_find_win(&row, &col, FIND_POPUP);
        if (curwin == NULL)
        {
            curwin = old_curwin;
            return;
        }

        curbuf = curwin->w_buffer;
    }

    do_mousescroll(cap);

    curwin->w_redr_status = true;
    curwin = old_curwin;
    curbuf = curwin->w_buffer;
}

    static void
nv_mouse(cmdarg_T *cap)
{
    (void)do_mouse(cap->oap, cap->cmdchar,  (-1) , cap->count1, 0);
}

static int      held_button = MOUSE_RELEASE;

    static void
reset_held_button(void)
{
    held_button = MOUSE_RELEASE;
}

    static int
check_termcode_mouse(char_u      *tp, int         *slen, char_u      *key_name, char_u      *modifiers_start, int         idx, int         *modifiers)
{
    int         j;
    char_u      *p;
    char_u      bytes[6];
    int         num_bytes;
    int         mouse_code = 0;
    int is_click;
    int is_drag;
    int is_release;
    int release_is_ambiguous;
    int         wheel_code = 0;
    int         current_button;
    static int  orig_num_clicks = 1;
    static int  orig_mouse_code = 0x0;
    static int  orig_mouse_col = 0;
    static int  orig_mouse_row = 0;
    static struct timeval  orig_mouse_time = {0, 0};
    struct timeval  mouse_time;
    long        timediff;

    is_click = is_drag = is_release = release_is_ambiguous = FALSE;

    if (key_name[0] == KS_MOUSE)
    {
        for (;;)
        {
            {
                num_bytes = get_bytes_from_buf(tp + *slen, bytes, 3);
                if (num_bytes == -1)
                {
                    return -1;
                }
                mouse_code = bytes[0];
                mouse_col = bytes[1] - ' ' - 1;
                mouse_row = bytes[2] - ' ' - 1;
            }
            *slen += num_bytes;

                j = get_termcode_len(idx);
            if ( strncmp((char *)(tp), (char *)(tp + *slen), ((size_t)j))  == 0 && tp[*slen + j] == mouse_code && tp[*slen + j + 1] != NUL && tp[*slen + j + 2] != NUL)
            {
                *slen += j;
            }
            else
            {
                break;
            }
        }
    }

    if (key_name[0] == KS_URXVT_MOUSE || key_name[0] == KS_SGR_MOUSE || key_name[0] == KS_SGR_MOUSE_RELEASE)
    {
        p = modifiers_start;
        if (p == NULL)
        {
            return -1;
        }

        mouse_code = getdigits(&p);
        if (*p++ != ';')
        {
            return -1;
        }

        if (key_name[0] == KS_SGR_MOUSE || key_name[0] == KS_SGR_MOUSE_RELEASE)
        {
            mouse_code += 32;
        }

        mouse_col = getdigits(&p) - 1;
        if (*p++ != ';')
        {
            return -1;
        }

        mouse_row = getdigits(&p) - 1;

        *modifiers = 0;
    }

    if (key_name[0] == KS_SGR_MOUSE || key_name[0] == KS_SGR_MOUSE_RELEASE)
    {
        if (key_name[0] == KS_SGR_MOUSE_RELEASE)
        {
            is_release = TRUE;
            mouse_code |= MOUSE_RELEASE;
        }
    }
    else
    {
        release_is_ambiguous = TRUE;
        if ((mouse_code & MOUSE_RELEASE) == MOUSE_RELEASE)
        {
            is_release = TRUE;
        }
    }

    if (key_name[0] == KS_MOUSE || key_name[0] == KS_SGR_MOUSE || key_name[0] == KS_SGR_MOUSE_RELEASE)
    {
        if (mouse_code >= MOUSEWHEEL_LOW && mouse_code < MOUSESIDEBUTTONS_LOW)
        {
            if (use_xterm_mouse() > 1 && mouse_code >= 0x80)
            {
                mouse_code =  (0x40 | MOUSE_RELEASE) ;
            }
            else
            {
                wheel_code = mouse_code;
            }
        }
        else if (held_button == MOUSE_RELEASE && (mouse_code == 0x23 || mouse_code == 0x24 || mouse_code == 0x40 || mouse_code == 0x41))
        {
            wheel_code = mouse_code - (mouse_code >= 0x40 ? 0x40 : 0x23)
                                                              + MOUSEWHEEL_LOW;
        }

        else if (use_xterm_mouse() > 1)
        {
            if (mouse_code & MOUSE_DRAG_XTERM)
            {
                mouse_code |=  (0x40 | MOUSE_RELEASE) ;
            }
        }
    }

    current_button = (mouse_code & MOUSE_CLICK_MASK);
    if (is_release)
    {
        current_button |= MOUSE_RELEASE;
    }

    if (current_button == MOUSE_RELEASE && wheel_code == 0)
    {
        if ((mouse_code &  (0x40 | MOUSE_RELEASE) ) ==  (0x40 | MOUSE_RELEASE) )
        {
            is_drag = TRUE;
        }
        current_button = held_button;
    }
    else
    {
      if (wheel_code == 0)
      {
                {
                    gettimeofday(&mouse_time, NULL);
                    if (orig_mouse_time.tv_sec == 0)
                    {
                        timediff = p_mouset;
                    }
                    else
                    {
                        timediff = time_diff_ms(&orig_mouse_time, &mouse_time);
                    }
                    orig_mouse_time = mouse_time;
                    if (mouse_code == orig_mouse_code && timediff < p_mouset && orig_num_clicks != 4 && orig_mouse_col == mouse_col && orig_mouse_row == mouse_row && (is_mouse_topline(curwin) || (mouse_row == 0 && firstwin->w_winrow > 0)))
                    {
                        ++orig_num_clicks;
                    }
                    else
                    {
                        orig_num_clicks = 1;
                    }
                    orig_mouse_col = mouse_col;
                    orig_mouse_row = mouse_row;
                    set_mouse_topline(curwin);
                }
        is_click = TRUE;
      }
      orig_mouse_code = mouse_code;
    }
    if (!is_drag)
    {
        held_button = mouse_code & MOUSE_CLICK_MASK;
    }

    if (orig_mouse_code & MOUSE_SHIFT)
    {
        *modifiers |= MOD_MASK_SHIFT;
    }
    if (orig_mouse_code & MOUSE_CTRL)
    {
        *modifiers |= MOD_MASK_CTRL;
    }
    if (orig_mouse_code & MOUSE_ALT)
    {
        *modifiers |= MOD_MASK_ALT;
    }
    if (orig_num_clicks == 2)
    {
        *modifiers |= MOD_MASK_2CLICK;
    }
    else if (orig_num_clicks == 3)
    {
        *modifiers |= MOD_MASK_3CLICK;
    }
    else if (orig_num_clicks == 4)
    {
        *modifiers |= MOD_MASK_4CLICK;
    }

    key_name[0] = KS_EXTRA;
    if (wheel_code != 0 && (!is_release || release_is_ambiguous))
    {
        if (wheel_code & MOUSE_CTRL)
        {
            *modifiers |= MOD_MASK_CTRL;
        }
        if (wheel_code & MOUSE_ALT)
        {
            *modifiers |= MOD_MASK_ALT;
        }

        if (wheel_code & 1 && wheel_code & 2)
        {
            key_name[1] = (int)KE_MOUSELEFT;
        }
        else if (wheel_code & 2)
        {
            key_name[1] = (int)KE_MOUSERIGHT;
        }
        else if (wheel_code & 1)
        {
            key_name[1] = (int)KE_MOUSEUP;
        }
        else
        {
            key_name[1] = (int)KE_MOUSEDOWN;
        }

        held_button = MOUSE_RELEASE;
    }
    else
    {
        if (use_xterm_mouse() && orig_mouse_code >= MOUSESIDEBUTTONS_LOW)
        {
            current_button = (current_button) ? MOUSE_X2 : MOUSE_X1;
        }
        key_name[1] = get_pseudo_mouse_code(current_button, is_click, is_drag);
    }

    if (mouse_col >= Columns)
    {
        mouse_col = Columns - 1;
    }
    if (mouse_row >= Rows)
    {
        mouse_row = Rows - 1;
    }

    return 0;
}

    static int
mouse_comp_pos(win_T       *win, int         *rowp, int         *colp, linenr_T    *lnump, int         *plines_cache)
{
    int         col = *colp;
    int         row = *rowp;
    linenr_T    lnum;
    int         retval = FALSE;
    int         off;
    int         count;

    lnum = win->w_topline;

    while (row > 0)
    {
        int cache_idx = lnum - win->w_topline;

        if (plines_cache != NULL && cache_idx < Rows && plines_cache[cache_idx] > 0)
        {
            count = plines_cache[cache_idx];
        }
        else
        {
                count = plines_win(win, lnum, FALSE);
            if (plines_cache != NULL && cache_idx < Rows)
            {
                plines_cache[cache_idx] = count;
            }
        }

        if (win->w_skipcol > 0 && lnum == win->w_topline)
        {
            int width1 = win->w_width - win_col_off(win);

            if (width1 > 0)
            {
                int skip_lines = 0;

                if (win->w_skipcol > width1)
                {
                    skip_lines = (win->w_skipcol - width1)
                                            / (width1 + win_col_off2(win)) + 1;
                }
                else if (win->w_skipcol > 0)
                {
                    skip_lines = 1;
                }

                count -= skip_lines;
            }
        }

        if (count > row)
        {
            break;
        }
        if (lnum == win->w_buffer->b_ml.ml_line_count)
        {
            retval = TRUE;
            break;
        }
        row -= count;
        ++lnum;
    }

    if (!retval)
    {
        off = win_col_off(win) - win_col_off2(win);
        if (col < off)
        {
            col = off;
        }
        col += row * (win->w_width - off);

        if (lnum == win->w_topline)
        {
            col += win->w_skipcol;
        }
    }

    if (!win-> w_onebuf_opt.wo_wrap )
    {
        col += win->w_leftcol;
    }

    col -= win_col_off(win);
    if (col <= 0)
    {
        col = 0;
    }

    *colp = col;
    *rowp = row;
    *lnump = lnum;
    return retval;
}

    static win_T *
mouse_find_win(int *rowp, int *colp, mouse_find_T popup  __attribute__((unused)) )
{
    frame_T     *fp;
    win_T       *wp;

    fp = topframe;

    if (*colp < firstwin->w_wincol || *colp >= firstwin->w_wincol + fp->fr_width || *rowp < firstwin->w_winrow)
    {
        return NULL;
    }

    *rowp -= firstwin->w_winrow;
    *colp -= firstwin->w_wincol;
    for (;;)
    {
        if (fp->fr_layout == FR_LEAF)
        {
            break;
        }
        if (fp->fr_layout == FR_ROW)
        {
            for (fp = fp->fr_child; fp->fr_next != NULL; fp = fp->fr_next)
            {
                if (*colp < fp->fr_width)
                {
                    break;
                }
                *colp -= fp->fr_width;
            }
        }
        else
        {
            for (fp = fp->fr_child; fp->fr_next != NULL; fp = fp->fr_next)
            {
                if (*rowp < fp->fr_height)
                {
                    break;
                }
                *rowp -= fp->fr_height;
            }
        }
    }
     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
     {
        if (wp == fp->fr_win)
        {
            return wp;
        }
     }
    return NULL;
}

// ==================== move.c ====================

static void redraw_for_cursorline(win_T *wp);
static int scrolljump_value(void);
static int check_top_offset(void);
typedef struct
{
    linenr_T        lnum;
    int             height;
} lineoff_T;

static void topline_back(lineoff_T *lp);
static void botline_forw(lineoff_T *lp);

    static int
adjust_plines_for_skipcol(win_T *wp)
{
    if (wp->w_skipcol == 0)
    {
        return 0;
    }

    int width = wp->w_width - win_col_off(wp);
    int w2 = width + win_col_off2(wp);
    if (wp->w_skipcol >= width && w2 > 0)
    {
        return (wp->w_skipcol - width) / w2 + 1;
    }

    return 0;
}

    static int
plines_correct_topline(win_T *wp, linenr_T lnum, int limit_winheight)
{
    int n;
        n = plines_win(wp, lnum, FALSE);
    if (lnum == wp->w_topline)
    {
        n -= adjust_plines_for_skipcol(wp);
    }
    if (limit_winheight && n > wp->w_height)
    {
        n = wp->w_height;
    }
    return n;
}

    static void
comp_botline(win_T *wp)
{
    int         n;
    linenr_T    lnum;
    int         done;

    check_cursor_moved(wp);
    if (wp->w_valid & VALID_CROW)
    {
        lnum = wp->w_cursor.lnum;
        done = wp->w_cline_row;
    }
    else
    {
        lnum = wp->w_topline;
        done = 0;
    }

    for ( ; lnum <= wp->w_buffer->b_ml.ml_line_count; ++lnum)
    {
        {
            n = plines_correct_topline(wp, lnum, TRUE);
        }
        if (lnum == wp->w_cursor.lnum)
        {
            wp->w_cline_row = done;
            wp->w_cline_height = n;
            redraw_for_cursorline(wp);
            wp->w_valid |= (VALID_CROW|VALID_CHEIGHT);
        }
        if (done + n > wp->w_height)
        {
            break;
        }
        done += n;
    }

    wp->w_botline = lnum;
    wp->w_valid |= VALID_BOTLINE|VALID_BOTLINE_AP;

    set_empty_rows(wp, done);
}

    static void
redraw_for_cursorline(win_T *wp)
{
    if ((wp-> w_onebuf_opt.wo_rnu ) && (wp->w_valid & VALID_CROW) == 0 && !pum_visible())
    {
        redraw_win_later(wp, UPD_VALID);
    }
}

    static void
set_valid_virtcol(win_T *wp, colnr_T vcol)
{
    wp->w_virtcol = vcol;
    wp->w_valid |= VALID_VIRTCOL;
}

    static int
sms_marker_overlap(win_T *wp, int extra2)
{
    if (extra2 == -1)
    {
        extra2 = win_col_off(wp) - win_col_off2(wp);
    }
    if (wp-> w_onebuf_opt.wo_list  && wp->w_lcs_chars.prec)
    {
        return 1;
    }

    return extra2 > 3 ? 0 : 3 - extra2;
}

    static int
skipcol_from_plines(win_T *wp, int plines_off)
{
    int width1 = wp->w_width - win_col_off(wp);

    int skipcol = 0;
    if (plines_off > 0)
    {
        skipcol += width1;
    }
    if (plines_off > 1)
    {
        skipcol += (width1 + win_col_off2(wp)) * (plines_off - 1);
    }
    return skipcol;
}

    static void
reset_skipcol(void)
{
    if (curwin->w_skipcol == 0)
    {
        return;
    }

    curwin->w_skipcol = 0;

    redraw_later(UPD_SOME_VALID);
}

    static void
update_topline_redraw(void)
{
    update_topline();
    if (must_redraw)
    {
        update_screen(0);
    }
}

    static bool
use_scrolloffpad(void)
{
    return get_scrolloff_value() > 0 && get_scrolloffpad_value() > 0;
}

    static bool
scrolloffpad_eof_pressure(linenr_T lnum, long so)
{
    if (!use_scrolloffpad() || so <= 0)
    {
        return false;
    }

    return lnum > curbuf->b_ml.ml_line_count - so;
}

    static void
update_topline(void)
{
    long        line_count;
    int         halfheight;
    int         n;
    int         check_topline = FALSE;
    int         check_botline = FALSE;
    long        *so_ptr = curwin-> w_onebuf_opt.wo_so  >= 0 ? &curwin-> w_onebuf_opt.wo_so  : &p_so;
    int         save_so = *so_ptr;
    bool        eof_pressure;

    if (skip_update_topline)
    {
        return;
    }

    if (!screen_valid(TRUE) || curwin->w_height == 0)
    {
        check_cursor_lnum();
        curwin->w_topline = curwin->w_cursor.lnum;
        curwin->w_botline = curwin->w_topline;
        curwin->w_scbind_pos = 1;
        return;
    }

    check_cursor_moved(curwin);
    if (curwin->w_valid & VALID_TOPLINE)
    {
        return;
    }

    if (mouse_dragging > 0)
    {
        *so_ptr = mouse_dragging - 1;
    }
    eof_pressure = scrolloffpad_eof_pressure(curwin->w_cursor.lnum, *so_ptr);

    linenr_T old_topline = curwin->w_topline;

    if ( (curbuf->b_ml.ml_line_count == 1 && *ml_get((linenr_T)1) == NUL) )
    {
        if (curwin->w_topline != 1)
        {
            redraw_later(UPD_NOT_VALID);
        }
        curwin->w_topline = 1;
        curwin->w_botline = 2;
        curwin->w_skipcol = 0;
        curwin->w_valid |= VALID_BOTLINE|VALID_BOTLINE_AP;
        curwin->w_scbind_pos = 1;
    }

    else
    {
        if (curwin->w_topline > 1 || curwin->w_skipcol > 0)
        {
            if (curwin->w_cursor.lnum < curwin->w_topline)
            {
                check_topline = TRUE;
            }
            else if (check_top_offset())
            {
                check_topline = TRUE;
            }
            else if (curwin->w_skipcol > 0 && curwin->w_cursor.lnum == curwin->w_topline)
            {
                colnr_T vcol;
                int overlap;

                getvvcol(curwin, &curwin->w_cursor, &vcol, NULL, NULL, 0);
                overlap = sms_marker_overlap(curwin, -1);
                if (curwin->w_skipcol + overlap > vcol)
                {
                    check_topline = TRUE;
                }
            }
        }

        if (check_topline)
        {
            halfheight = curwin->w_height / 2 - 1;
            if (halfheight < 2)
            {
                halfheight = 2;
            }

                n = curwin->w_topline + *so_ptr - curwin->w_cursor.lnum;

            int min_scroll = scrolljump_value();
            if (eof_pressure)
            {
                scroll_cursor_halfway(TRUE, TRUE);
            }
            else if (n >= halfheight && min_scroll < halfheight)
            {
                scroll_cursor_halfway(FALSE, FALSE);
            }
            else
            {
                scroll_cursor_top(min_scroll, FALSE);
                check_botline = TRUE;
            }
        }

        else
        {
            check_botline = TRUE;
        }
    }

    if (check_botline)
    {
        if (!(curwin->w_valid & VALID_BOTLINE_AP))
        {
            validate_botline();
        }

        if (curwin->w_botline <= curbuf->b_ml.ml_line_count || use_scrolloffpad())
        {
            if (curwin->w_cursor.lnum < curwin->w_botline)
            {
                if (((long)curwin->w_cursor.lnum >= (long)curwin->w_botline - *so_ptr))
                {
                    lineoff_T   loff;

                    n = eof_pressure ? 0 : curwin->w_empty_rows;
                    loff.lnum = curwin->w_cursor.lnum;
                    loff.height = 0;
                    while (loff.lnum < curwin->w_botline)
                    {
                        n += loff.height;
                        if (n >= *so_ptr)
                        {
                            break;
                        }
                        botline_forw(&loff);
                    }
                    if (n >= *so_ptr && !eof_pressure)
                    {
                        check_botline = FALSE;
                    }
                }
                else
                {
                    check_botline = FALSE;
                }
            }
            if (check_botline)
            {
                    line_count = curwin->w_cursor.lnum - curwin->w_botline
                                                                 + 1 + *so_ptr;
                if (line_count <= curwin->w_height + 1)
                {
                    if (eof_pressure)
                    {
                        scroll_cursor_halfway(TRUE, TRUE);
                    }
                    else
                    {
                        scroll_cursor_bot(scrolljump_value(), FALSE);
                    }
                }
                else
                {
                    scroll_cursor_halfway(eof_pressure, eof_pressure);
                }
            }
        }
    }
    curwin->w_valid |= VALID_TOPLINE;

    if (curwin->w_topline != old_topline)
    {
        dollar_vcol = -1;
        redraw_later(UPD_VALID);

        if (!curwin-> w_onebuf_opt.wo_sms )
        {
            reset_skipcol();
        }
        else if (curwin->w_skipcol != 0)
        {
            redraw_later(UPD_SOME_VALID);
        }

        if (curwin->w_cursor.lnum == curwin->w_topline)
        {
            validate_cursor();
        }
    }

    *so_ptr = save_so;
}

    static int
scrolljump_value(void)
{
    if (p_sj >= 0)
    {
        return (int)p_sj;
    }
    return (curwin->w_height * -p_sj) / 100;
}

    static int
check_top_offset(void)
{
    lineoff_T   loff;
    int         n;
    long        so = get_scrolloff_value();

    if (curwin->w_cursor.lnum < curwin->w_topline + so)
    {
        loff.lnum = curwin->w_cursor.lnum;
        n = 0;
        while (n < so)
        {
            topline_back(&loff);
            if (loff.lnum < curwin->w_topline)
            {
                break;
            }
            n += loff.height;
        }
        if (n < so)
        {
            return TRUE;
        }
    }
    return FALSE;
}

