    static void
validate_virtcol_win(win_T *wp)
{
    check_cursor_moved(wp);

    if (wp->w_valid & VALID_VIRTCOL)
    {
        return;
    }

    getvvcol(wp, &wp->w_cursor, NULL, &(wp->w_virtcol), NULL, 0);
    wp->w_valid |= VALID_VIRTCOL;
}

    static void
validate_cheight(void)
{
    check_cursor_moved(curwin);

    if (curwin->w_valid & VALID_CHEIGHT)
    {
        return;
    }

        curwin->w_cline_height = plines(curwin->w_cursor.lnum);
    curwin->w_valid |= VALID_CHEIGHT;
}

    static void
validate_cursor_col(void)
{
    colnr_T off;
    colnr_T col;
    int     width;

    validate_virtcol();

    if (curwin->w_valid & VALID_WCOL)
    {
        return;
    }

    col = curwin->w_virtcol;
    off = curwin_col_off();
    col += off;
    width = curwin->w_width - off + curwin_col_off2();

    if (curwin-> w_onebuf_opt.wo_wrap  && col >= (colnr_T)curwin->w_width && width > 0)
    {
        col -= ((col - curwin->w_width) / width + 1) * width;
    }
    if (col > (int)curwin->w_leftcol)
    {
        col -= curwin->w_leftcol;
    }
    else
    {
        col = 0;
    }
    curwin->w_wcol = col;

    curwin->w_valid |= VALID_WCOL;
}

    static int
win_col_off(win_T *wp)
{
    return (((wp-> w_onebuf_opt.wo_nu  || wp-> w_onebuf_opt.wo_rnu ) ?  7  + 1 : 0) + (wp != cmdwin_win ? 0 : 1));
}

    static int
curwin_col_off(void)
{
    return win_col_off(curwin);
}

    static int
win_col_off2(win_T *wp)
{
    if ((wp-> w_onebuf_opt.wo_nu  || wp-> w_onebuf_opt.wo_rnu ) && vim_strchr(p_cpo, CPO_NUMCOL) != NULL)
    {
        return  7  + 1;
    }
    return 0;
}

    static int
curwin_col_off2(void)
{
    return win_col_off2(curwin);
}

    static void
curs_columns(int         may_scroll)
{
    long        diff;
    int         extra;
    long off_left;
    long off_right;
    int         n;
    int         p_lines;
    int         width1;
    int         width2 = 0;
    int         new_leftcol;
    colnr_T     startcol;
    colnr_T     endcol;
    colnr_T     prev_skipcol;
    long        so = get_scrolloff_value();
    long        siso = get_sidescrolloff_value();
    int         did_sub_skipcol = FALSE;

    update_topline();

    if (!(curwin->w_valid & VALID_CROW))
    {
        curs_rows(curwin);
    }

        getvvcol(curwin, &curwin->w_cursor, &startcol, &(curwin->w_virtcol), &endcol, 0);

    if (startcol > dollar_vcol)
    {
        dollar_vcol = -1;
    }

    extra = curwin_col_off();
    curwin->w_wcol = curwin->w_virtcol + extra;
    endcol += extra;

    curwin->w_wrow = curwin->w_cline_row;

    width1 = curwin->w_width - extra;
    if (width1 <= 0)
    {
        curwin->w_wcol = curwin->w_width - 1;
        if (curwin-> w_onebuf_opt.wo_wrap )
        {
            curwin->w_wrow = curwin->w_height - 1;
        }
        else
        {
            curwin->w_wrow = curwin->w_height - 1 - curwin->w_empty_rows;
        }
    }
    else if (curwin-> w_onebuf_opt.wo_wrap  && curwin->w_width != 0)
    {
        width2 = width1 + curwin_col_off2();

        if (curwin->w_cursor.lnum == curwin->w_topline && curwin->w_skipcol > 0 && curwin->w_wcol >= curwin->w_skipcol)
        {
            if (curwin->w_skipcol <= width1)
            {
                curwin->w_wcol -= width2;
            }
            else
            {
                curwin->w_wcol -= width2
                               * (((curwin->w_skipcol - width1) / width2) + 1);
            }

            did_sub_skipcol = TRUE;
        }

        if (curwin->w_wcol >= curwin->w_width)
        {
            n = (curwin->w_wcol - curwin->w_width) / width2 + 1;
            curwin->w_wcol -= n * width2;
            curwin->w_wrow += n;
        }
    }

    else if (may_scroll)
    {
        off_left = startcol - curwin->w_leftcol - siso;
        off_right = endcol - curwin->w_leftcol - (curwin->w_width - siso) + 1;
        if (off_left < 0 || off_right > 0)
        {
            if (off_left < 0)
            {
                diff = -off_left;
            }
            else
            {
                diff = off_right;
            }

            if (p_ss == 0 || diff >= width1 / 2 || off_right >= off_left)
            {
                new_leftcol = curwin->w_wcol - extra - width1 / 2;
            }
            else
            {
                if (diff < p_ss)
                {
                    diff = p_ss;
                }
                if (off_left < 0)
                {
                    new_leftcol = curwin->w_leftcol - (int)diff;
                }
                else
                {
                    new_leftcol = curwin->w_leftcol + (int)diff;
                }
            }
            if (new_leftcol < 0)
            {
                new_leftcol = 0;
            }
            if (new_leftcol != (int)curwin->w_leftcol)
            {
                curwin->w_leftcol = new_leftcol;
                redraw_later(UPD_NOT_VALID);
            }
        }
        curwin->w_wcol -= curwin->w_leftcol;
    }
    else if (curwin->w_wcol > (int)curwin->w_leftcol)
    {
        curwin->w_wcol -= curwin->w_leftcol;
    }
    else
    {
        curwin->w_wcol = 0;
    }

    prev_skipcol = curwin->w_skipcol;

    p_lines = 0;

    if ((curwin->w_wrow >= curwin->w_height || ((prev_skipcol > 0 || curwin->w_wrow + so >= curwin->w_height) && (p_lines = plines_win (curwin, curwin->w_cursor.lnum, FALSE)) - 1 >= curwin->w_height)) && curwin->w_height != 0 && curwin->w_cursor.lnum == curwin->w_topline && width2 > 0 && curwin->w_width != 0)
    {
        extra = 0;
        if (curwin->w_skipcol + so * width2 > curwin->w_virtcol)
        {
            extra = 1;
        }
        if (p_lines == 0)
        {
            p_lines = plines_win(curwin, curwin->w_cursor.lnum, FALSE);
        }
        --p_lines;
        if (p_lines > curwin->w_wrow + so)
        {
            n = curwin->w_wrow + so;
        }
        else
        {
            n = p_lines;
        }
        if ((colnr_T)n >= curwin->w_height + curwin->w_skipcol / width2 - so)
        {
            extra += 2;
        }

        if (extra == 3 || curwin->w_height <= so * 2)
        {
            n = curwin->w_virtcol / width2;
            if (n > curwin->w_height / 2)
            {
                n -= curwin->w_height / 2;
            }
            else
            {
                n = 0;
            }
            if (n > p_lines - curwin->w_height + 1)
            {
                n = p_lines - curwin->w_height + 1;
            }
            if (n > 0)
            {
                curwin->w_skipcol = width1 + (n - 1) * width2;
            }
            else
            {
                curwin->w_skipcol = 0;
            }
        }
        else if (extra == 1)
        {
            extra = (curwin->w_skipcol + so * width2 - curwin->w_virtcol + width2 - 1) / width2;
            if (extra > 0)
            {
                if ((colnr_T)(extra * width2) > curwin->w_skipcol)
                {
                    extra = curwin->w_skipcol / width2;
                }
                curwin->w_skipcol -= extra * width2;
            }
        }
        else if (extra == 2)
        {
            endcol = (n - curwin->w_height + 1) * width2;
            while (endcol > curwin->w_virtcol)
            {
                endcol -= width2;
            }
            if (endcol > curwin->w_skipcol)
            {
                curwin->w_skipcol = endcol;
            }
        }

        if (did_sub_skipcol)
        {
            curwin->w_wrow -= (curwin->w_skipcol - prev_skipcol) / width2;
        }
        else
        {
            curwin->w_wrow -= curwin->w_skipcol / width2;
        }

        if (curwin->w_wrow >= curwin->w_height)
        {
            extra = curwin->w_wrow - curwin->w_height + 1;
            curwin->w_skipcol += extra * width2;
            curwin->w_wrow -= extra;
        }

        extra = ((int)prev_skipcol - (int)curwin->w_skipcol) / width2;
        if (extra > 0)
        {
            win_ins_lines(curwin, 0, extra, FALSE, FALSE);
        }
        else if (extra < 0)
        {
            win_del_lines(curwin, 0, -extra, FALSE, FALSE, 0);
        }
    }
    else if (!curwin-> w_onebuf_opt.wo_sms )
    {
        curwin->w_skipcol = 0;
    }
    if (prev_skipcol != curwin->w_skipcol)
    {
        redraw_later(UPD_SOME_VALID);
    }

    curwin->w_valid_leftcol = curwin->w_leftcol;
    curwin->w_valid_skipcol = curwin->w_skipcol;

    curwin->w_valid |= VALID_WCOL|VALID_WROW|VALID_VIRTCOL;
}

static void cursor_correct_sms(void)
{
    if (!curwin-> w_onebuf_opt.wo_sms  || !curwin-> w_onebuf_opt.wo_wrap  || curwin->w_cursor.lnum != curwin->w_topline)
    {
        return;
    }

    long    so = get_scrolloff_value();
    int     width1 = curwin->w_width - curwin_col_off();
    int     width2 = width1 + curwin_col_off2();
    int     so_cols = so == 0 ? 0 : width1 + (so - 1) * width2;
    int     space_cols = (curwin->w_height - 1) * width2;
    int overlap;
    int top;
    int bot;
    int     size = so == 0 ? 0 : linetabsize_eol(curwin, curwin->w_topline);

    if (curwin->w_topline == 1 && curwin->w_skipcol == 0)
    {
        so_cols = 0;
    }
    else if (so_cols > space_cols / 2)
    {
        so_cols = space_cols / 2;
    }

    while (so_cols > size && so_cols - width2 >= width1 && width1 > 0)
    {
        so_cols -= width2;
    }
    if (so_cols >= width1 && so_cols > size)
    {
        so_cols -= width1;
    }

    overlap = curwin->w_skipcol == 0 ? 0
                        : sms_marker_overlap(curwin, curwin->w_width - width2);
    top = curwin->w_skipcol + (so_cols != 0 ? so_cols : overlap);
    bot = curwin->w_skipcol + width1 + (curwin->w_height - 1) * width2
                                                                    - so_cols;
    validate_virtcol();
    colnr_T col = curwin->w_virtcol;

    if (col < top)
    {
        if (col < width1)
        {
            col += width1;
        }
        while (width2 > 0 && col < top)
        {
            col += width2;
        }
    }
    else
    {
        while (width2 > 0 && col >= bot)
        {
            col -= width2;
        }
    }

    if (col != curwin->w_virtcol)
    {
        int rc;

        curwin->w_curswant = col;
        rc = coladvance(curwin->w_curswant);
        curwin->w_valid &=
            ~(VALID_WROW|VALID_WCOL|VALID_CHEIGHT|VALID_CROW|VALID_VIRTCOL);
        if (rc == FAIL && curwin->w_skipcol > 0 && curwin->w_cursor.lnum < curbuf->b_ml.ml_line_count)
        {
            validate_virtcol();
            if (curwin->w_virtcol < curwin->w_skipcol + overlap)
            {
                curwin->w_cursor.lnum++;
                curwin->w_cursor.col = 0;
                curwin->w_cursor.coladd = 0;
                curwin->w_curswant = 0;
                curwin->w_valid &= ~VALID_VIRTCOL;
            }
        }
    }
}

    static void
scroll_redraw(int up, long count)
{
    linenr_T    prev_topline = curwin->w_topline;
    int         prev_skipcol = curwin->w_skipcol;
    linenr_T    prev_lnum = curwin->w_cursor.lnum;

    if (up)
    {
        scrollup(count, TRUE);
    }
    else
    {
        scrolldown(count, TRUE);
    }
    if (get_scrolloff_value() > 0)
    {
        cursor_correct();
        check_cursor_moved(curwin);
        curwin->w_valid |= VALID_TOPLINE;

        while (curwin->w_topline == prev_topline && curwin->w_skipcol == prev_skipcol)
        {
            if (up)
            {
                if (curwin->w_cursor.lnum > prev_lnum || cursor_down(1L, FALSE) == FAIL)
                {
                    break;
                }
            }
            else
            {
                if (curwin->w_cursor.lnum < prev_lnum || prev_topline == 1L || cursor_up(1L, FALSE) == FAIL)
                {
                    break;
                }
            }
            check_cursor_moved(curwin);
            curwin->w_valid |= VALID_TOPLINE;
        }
    }

    cursor_correct_sms();
    if (curwin->w_cursor.lnum != prev_lnum)
    {
        coladvance(curwin->w_curswant);
    }
    redraw_later(UPD_VALID);
}

    static void
scrolldown(long        line_count, int         byfold  __attribute__((unused)) )
{
    long        done = 0;
    int         wrow;
    int         moved = FALSE;
    int         do_sms = curwin-> w_onebuf_opt.wo_wrap  && curwin-> w_onebuf_opt.wo_sms ;
    int         width1 = 0;
    int         width2 = 0;

    if (do_sms)
    {
        width1 = curwin->w_width - curwin_col_off();
        width2 = width1 + curwin_col_off2();
    }

    validate_cursor();
    for (int todo = line_count; todo > 0; --todo)
    {
        {
            if (curwin->w_topline == 1 && (!do_sms || curwin->w_skipcol < width1))
            {
                break;
            }
            if (do_sms && curwin->w_skipcol >= width1)
            {
                if (curwin->w_skipcol >= width1 + width2)
                {
                    curwin->w_skipcol -= width2;
                }
                else
                {
                    curwin->w_skipcol -= width1;
                }
                redraw_later(UPD_NOT_VALID);
                ++done;
            }
            else
            {
                --curwin->w_topline;
                curwin->w_skipcol = 0;
                if (do_sms)
                {
                    int size = linetabsize_eol(curwin, curwin->w_topline);
                    if (size > width1)
                    {
                        curwin->w_skipcol = width1;
                        size -= width1;
                        redraw_later(UPD_NOT_VALID);
                    }
                    while (size > width2)
                    {
                        curwin->w_skipcol += width2;
                        size -= width2;
                    }
                    ++done;
                }
                else
                {
                    done +=  plines(curwin->w_topline) ;
                }
            }
        }
        --curwin->w_botline;
        invalidate_botline();
    }
    curwin->w_wrow += done;
    curwin->w_cline_row += done;

    wrow = curwin->w_wrow;
    if (curwin-> w_onebuf_opt.wo_wrap  && curwin->w_width != 0)
    {
        validate_virtcol();
        validate_cheight();
        wrow += curwin->w_cline_height - 1 -
            curwin->w_virtcol / curwin->w_width;
    }
    while (wrow >= curwin->w_height && curwin->w_cursor.lnum > 1)
    {
            wrow -= plines(curwin->w_cursor.lnum--);
        curwin->w_valid &=
              ~(VALID_WROW|VALID_WCOL|VALID_CHEIGHT|VALID_CROW|VALID_VIRTCOL);
        moved = TRUE;
    }
    if (moved)
    {
        coladvance(curwin->w_curswant);
    }
    if (curwin->w_cursor.lnum < curwin->w_topline)
    {
        curwin->w_cursor.lnum = curwin->w_topline;
    }
}

    static void
scrollup(long        line_count, int         byfold  __attribute__((unused)) )
{
    int         do_sms = curwin-> w_onebuf_opt.wo_wrap  && curwin-> w_onebuf_opt.wo_sms ;

    if (do_sms)
    {
        int         width1 = curwin->w_width - curwin_col_off();
        int         width2 = width1 + curwin_col_off2();
        int         size = 0;
        colnr_T     prev_skipcol = curwin->w_skipcol;

        if (do_sms)
        {
            size = linetabsize_eol(curwin, curwin->w_topline);
        }

        for (int todo = line_count; todo > 0; --todo)
        {
            {
                linenr_T lnum = curwin->w_topline;

                if (lnum == curwin->w_topline && do_sms)
                {
                    int add = curwin->w_skipcol > 0 ? width2 : width1;
                    curwin->w_skipcol += add;
                    if (curwin->w_skipcol >= size)
                    {
                        if (lnum == curbuf->b_ml.ml_line_count)
                        {
                            curwin->w_skipcol -= add;
                            break;
                        }
                        ++lnum;
                    }
                }
                else
                {
                    if (lnum >= curbuf->b_ml.ml_line_count)
                    {
                        break;
                    }
                    ++lnum;
                }

                if (lnum > curwin->w_topline)
                {
                    curwin->w_botline += lnum - curwin->w_topline;
                    curwin->w_topline = lnum;
                    curwin->w_skipcol = 0;
                    if (todo > 1 && do_sms)
                    {
                        size = linetabsize_eol(curwin, curwin->w_topline);
                    }
                }
            }
        }

        if (prev_skipcol > 0 || curwin->w_skipcol > 0)
        {
            redraw_later(UPD_NOT_VALID);
        }
    }
    else
    {
        curwin->w_topline += line_count;
        curwin->w_botline += line_count;
    }

    if (curwin->w_topline > curbuf->b_ml.ml_line_count)
    {
        curwin->w_topline = curbuf->b_ml.ml_line_count;
    }
    if (curwin->w_botline > curbuf->b_ml.ml_line_count + 1)
    {
        curwin->w_botline = curbuf->b_ml.ml_line_count + 1;
    }

    curwin->w_valid &= ~(VALID_WROW|VALID_CROW|VALID_BOTLINE);
    if (curwin->w_cursor.lnum < curwin->w_topline)
    {
        curwin->w_cursor.lnum = curwin->w_topline;
        curwin->w_valid &=
              ~(VALID_WROW|VALID_WCOL|VALID_CHEIGHT|VALID_CROW|VALID_VIRTCOL);
        coladvance(curwin->w_curswant);
    }
}

    static void
adjust_skipcol(void)
{
    if (!curwin-> w_onebuf_opt.wo_wrap  || !curwin-> w_onebuf_opt.wo_sms  || curwin->w_cursor.lnum != curwin->w_topline)
    {
        return;
    }

    int     width1 = curwin->w_width - curwin_col_off();
    if (width1 <= 0)
    {
        return;
    }

    int     width2 = width1 + curwin_col_off2();
    long    so = get_scrolloff_value();
    int     scrolloff_cols = so == 0 ? 0 : width1 + (so - 1) * width2;
    int     scrolled = FALSE;
    int     row = 0;
    int overlap;
    int col;

    validate_cheight();
    if (curwin->w_cline_height == curwin->w_height && plines_win(curwin, curwin->w_cursor.lnum, FALSE) <= curwin->w_height)
    {
        reset_skipcol();
        return;
    }

    validate_virtcol();
    overlap = sms_marker_overlap(curwin, curwin->w_width - width2);
    while (curwin->w_skipcol > 0 && curwin->w_virtcol < curwin->w_skipcol + overlap + scrolloff_cols)
    {
        if (curwin->w_skipcol >= width1 + width2)
        {
            curwin->w_skipcol -= width2;
        }
        else
        {
            curwin->w_skipcol -= width1;
        }
        scrolled = TRUE;
    }
    if (scrolled)
    {
        validate_virtcol();
        redraw_later(UPD_NOT_VALID);
        return;
    }

    col = curwin->w_virtcol + scrolloff_cols;

    if (scrolloff_cols > 0)
    {
        int size = linetabsize_eol(curwin, curwin->w_topline);
        size = width1 + width2 * ((size - width1 + width2 - 1) / width2);
        while (col > size)
        {
            col -= width2;
        }
    }
    col -= curwin->w_skipcol;

    if (col >= width1)
    {
        col -= width1;
        ++row;
    }
    if (col > width2)
    {
        row += col / width2;
        col = col % width2;
    }
    if (row >= curwin->w_height)
    {
        if (curwin->w_skipcol == 0)
        {
            curwin->w_skipcol += width1;
            --row;
        }
        if (row >= curwin->w_height)
        {
            curwin->w_skipcol += (row - curwin->w_height) * width2;
        }
        redraw_later(UPD_NOT_VALID);
    }
}

    static void
scrolldown_clamp(void)
{
    int         end_row;

    if (curwin->w_topline <= 1)
    {
        return;
    }

    validate_cursor();

    end_row = curwin->w_wrow;
    end_row += plines(curwin->w_topline - 1);
    if (curwin-> w_onebuf_opt.wo_wrap  && curwin->w_width != 0)
    {
        validate_cheight();
        validate_virtcol();
        end_row += curwin->w_cline_height - 1 -
            curwin->w_virtcol / curwin->w_width;
    }
    if (end_row < curwin->w_height - get_scrolloff_value())
    {
        --curwin->w_topline;
        --curwin->w_botline;
        curwin->w_valid &= ~(VALID_WROW|VALID_CROW|VALID_BOTLINE);
    }
}

    static void
scrollup_clamp(void)
{
    int     start_row;

    if (curwin->w_topline == curbuf->b_ml.ml_line_count)
    {
        return;
    }

    validate_cursor();

    start_row = curwin->w_wrow - plines(curwin->w_topline);
    if (curwin-> w_onebuf_opt.wo_wrap  && curwin->w_width != 0)
    {
        validate_virtcol();
        start_row -= curwin->w_virtcol / curwin->w_width;
    }
    if (start_row >= get_scrolloff_value())
    {
        {
            ++curwin->w_topline;
        }
        ++curwin->w_botline;
        curwin->w_valid &= ~(VALID_WROW|VALID_CROW|VALID_BOTLINE);
    }
}

    static void
topline_back_winheight(lineoff_T   *lp, int         winheight)
{
    {
        --lp->lnum;
        if (lp->lnum < 1)
        {
            lp->height = MAXCOL;
        }
        else
        {
            lp->height =  plines_win((curwin), (lp->lnum), (winheight)) ;
        }
    }
}

    static void
topline_back(lineoff_T *lp)
{
    topline_back_winheight(lp, TRUE);
}

    static void
botline_forw(lineoff_T *lp)
{
    {
        ++lp->lnum;
        if (lp->lnum > curbuf->b_ml.ml_line_count)
        {
            lp->height = MAXCOL;
        }
        else
        {
            lp->height =  plines(lp->lnum) ;
        }
    }
}

    static void
scroll_cursor_top(int min_scroll, int always)
{
    int         scrolled = 0;
    int         extra = 0;
    int         used;
    int         i;
    linenr_T    top;
    linenr_T    bot;
    linenr_T    old_topline = curwin->w_topline;
    int         old_skipcol = curwin->w_skipcol;
    linenr_T    new_topline;
    int         off = get_scrolloff_value();

    if (mouse_dragging > 0)
    {
        off = mouse_dragging - 1;
    }

    validate_cheight();
    used = curwin->w_cline_height;
    if (curwin->w_cursor.lnum < curwin->w_topline)
    {
        scrolled = used;
    }

    {
        top = curwin->w_cursor.lnum - 1;
        bot = curwin->w_cursor.lnum + 1;
    }
    new_topline = top + 1;

    while (top > 0)
    {
            i =  plines(top) ;
        if (top < curwin->w_topline)
        {
            scrolled += i;
        }

        if ((new_topline >= curwin->w_topline || scrolled > min_scroll) && extra >= off)
        {
            break;
        }

        used += i;
        if (extra + i <= off && bot < curbuf->b_ml.ml_line_count)
        {
                used += plines(bot);
        }
        if (used > curwin->w_height)
        {
            break;
        }

        extra += i;
        new_topline = top;
        --top;
        ++bot;
    }

    if (used > curwin->w_height)
    {
        scroll_cursor_halfway(FALSE, FALSE);
    }
    else
    {
        if (new_topline < curwin->w_topline || always)
        {
            curwin->w_topline = new_topline;
        }
        if (curwin->w_topline > curwin->w_cursor.lnum)
        {
            curwin->w_topline = curwin->w_cursor.lnum;
        }
        if (curwin->w_topline != old_topline)
        {
            reset_skipcol();
        }
        else if (curwin->w_topline == curwin->w_cursor.lnum)
        {
            validate_virtcol();
            if (curwin->w_skipcol >= curwin->w_virtcol)
            {
                int     width1 = curwin->w_width - curwin_col_off();
                int     width2 = width1 + curwin_col_off2();
                int     plines_off = 0;
                int     skipcol;

                if (width2 > 0 && curwin->w_virtcol >= (colnr_T)width1)
                {
                    plines_off = (curwin->w_virtcol - width1) / width2 + 1;
                }
                skipcol = skipcol_from_plines(curwin, plines_off);
                if (skipcol != curwin->w_skipcol)
                {
                    curwin->w_skipcol = skipcol;
                    redraw_later(UPD_SOME_VALID);
                }
            }
        }
        if (curwin->w_topline != old_topline || curwin->w_skipcol != old_skipcol)
        {
            curwin->w_valid &=
                      ~(VALID_WROW|VALID_CROW|VALID_BOTLINE|VALID_BOTLINE_AP);
        }
        curwin->w_valid |= VALID_TOPLINE;
    }
}

    static void
set_empty_rows(win_T *wp, int used)
{
    if (used == 0)
    {
        wp->w_empty_rows = 0;
    }
    else
    {
        wp->w_empty_rows = wp->w_height - used;
    }
}

    static void
scroll_cursor_bot(int min_scroll, int set_topbot)
{
    int         used;
    int         scrolled = 0;
    int         extra = 0;
    int         i;
    linenr_T    line_count;
    linenr_T    old_topline = curwin->w_topline;
    int         old_skipcol = curwin->w_skipcol;
    lineoff_T   loff;
    lineoff_T   boff;
    linenr_T    old_botline = curwin->w_botline;
    linenr_T    old_valid = curwin->w_valid;
    int         old_empty_rows = curwin->w_empty_rows;
    linenr_T    cln;
    long        so = get_scrolloff_value();
    int         do_sms = curwin-> w_onebuf_opt.wo_wrap  && curwin-> w_onebuf_opt.wo_sms ;

    cln = curwin->w_cursor.lnum;
    if (set_topbot)
    {
        used = 0;
        linenr_T cln_last = cln;
        curwin->w_botline = cln_last + 1;
        loff.lnum = cln_last + 1;
        while (TRUE)
        {
            topline_back_winheight(&loff, FALSE);
            if (loff.height == MAXCOL)
            {
                break;
            }
            if (used + loff.height > curwin->w_height)
            {
                if (do_sms)
                {
                    if (used < curwin->w_height)
                    {
                        int plines_offset = used + loff.height
                                                            - curwin->w_height;
                        used = curwin->w_height;
                        curwin->w_topline = loff.lnum;
                        curwin->w_skipcol = skipcol_from_plines(curwin, plines_offset);
                    }
                }
                break;
            }
            curwin->w_topline = loff.lnum;
            used += loff.height;
        }

        set_empty_rows(curwin, used);
        curwin->w_valid |= VALID_BOTLINE|VALID_BOTLINE_AP;
        if (curwin->w_topline != old_topline || curwin->w_skipcol != old_skipcol || curwin->w_skipcol != 0)
        {
            curwin->w_valid &= ~(VALID_WROW|VALID_CROW);
            if (curwin->w_skipcol != old_skipcol)
            {
                redraw_later(UPD_NOT_VALID);
            }
            else
            {
                reset_skipcol();
            }
        }
    }
    else
    {
        validate_botline();
    }

    validate_cheight();
    used = curwin->w_cline_height;

    if (do_sms && (dy_flags & DY_LASTLINE))
    {
        int upto_cursor = plines_win_col(curwin, cln, curwin->w_cursor.col);

        if (upto_cursor < used)
        {
            used = upto_cursor;
        }
    }

    if (cln >= curwin->w_botline)
    {
        scrolled = used;
        if (cln == curwin->w_botline)
        {
            scrolled -= curwin->w_empty_rows;
        }
        if (do_sms)
        {
            int top_plines =
                            plines_win
                                        (curwin, curwin->w_topline, FALSE);
            int width1 = curwin->w_width - curwin_col_off();

            if (width1 > 0)
            {
                int width2 = width1 + curwin_col_off2();
                int skip_lines = 0;

                if (curwin->w_skipcol > width1)
                {
                    skip_lines += (curwin->w_skipcol - width1) / width2 + 1;
                }
                else if (curwin->w_skipcol > 0)
                {
                    skip_lines = 1;
                }

                top_plines -= skip_lines;
                if (top_plines > curwin->w_height)
                {
                    scrolled += (top_plines - curwin->w_height);
                }
            }
        }
    }

    {
        loff.lnum = cln;
        boff.lnum = cln;
    }

    while (loff.lnum > 1)
    {
        if ((((scrolled <= 0 || scrolled >= min_scroll) && extra >= (mouse_dragging > 0 ? mouse_dragging - 1 : so)) || boff.lnum + 1 > curbuf->b_ml.ml_line_count) && loff.lnum <= curwin->w_botline)
        {
            break;
        }

        linenr_T loff_lnum_before = loff.lnum;
        topline_back(&loff);
        if (loff.height == MAXCOL)
        {
            used = MAXCOL;
        }
        else
        {
            used += loff.height;
        }
        if (used > curwin->w_height)
        {
            break;
        }
        if (loff.lnum >= curwin->w_botline)
        {
            scrolled += loff.height;
            if (loff.lnum == curwin->w_botline && loff_lnum_before > curwin->w_botline)
            {
                scrolled -= curwin->w_empty_rows;
            }
        }

        if (boff.lnum < curbuf->b_ml.ml_line_count)
        {
            linenr_T boff_lnum_before = boff.lnum;
            botline_forw(&boff);
            used += boff.height;
            if (used > curwin->w_height)
            {
                break;
            }
            if (extra < ( mouse_dragging > 0 ? mouse_dragging - 1 : so) || scrolled < min_scroll)
            {
                extra += boff.height;
                if (boff.lnum >= curwin->w_botline)
                {
                    scrolled += boff.height;
                    if (boff.lnum >= curwin->w_botline && boff_lnum_before < curwin->w_botline)
                    {
                        scrolled -= curwin->w_empty_rows;
                    }
                }
            }
        }
    }

    if (scrolled <= 0)
    {
        line_count = 0;
    }
    else if (used > curwin->w_height)
    {
        line_count = used;
    }
    else
    {
        line_count = 0;
        boff.lnum = curwin->w_topline - 1;
        for (i = 0; i < scrolled && boff.lnum < curwin->w_botline; )
        {
            botline_forw(&boff);
            i += boff.height;
            ++line_count;
        }
        if (i < scrolled)
        {
            line_count = 9999;
        }
    }

    bool eof_pressure = scrolloffpad_eof_pressure(cln, so);
    if (line_count >= curwin->w_height && line_count > min_scroll)
    {
        scroll_cursor_halfway(eof_pressure, TRUE);
    }
    else if (line_count > 0)
    {
        if (do_sms)
        {
            scrollup(scrolled, TRUE);
        }
        else
        {
            scrollup(line_count, TRUE);
        }
    }

    if (curwin->w_topline == old_topline && curwin->w_skipcol == old_skipcol && set_topbot)
    {
        curwin->w_botline = old_botline;
        curwin->w_empty_rows = old_empty_rows;
        curwin->w_valid = old_valid;
    }
    curwin->w_valid |= VALID_TOPLINE;

    if (set_topbot)
    {
        cursor_correct_sms();
    }
}

    static void
scroll_cursor_halfway(int atend, int prefer_above)
{
    int         above = 0;
    linenr_T    topline;
    colnr_T     skipcol = 0;
    int         below = 0;
    int         used;
    lineoff_T   loff;
    lineoff_T   boff;

    loff.lnum = boff.lnum = curwin->w_cursor.lnum;
    used = plines(loff.lnum);
    topline = loff.lnum;

    int want_height;
    int do_sms = curwin-> w_onebuf_opt.wo_wrap  && curwin-> w_onebuf_opt.wo_sms ;
    if (do_sms)
    {
        if (atend)
        {
            want_height = (curwin->w_height - used) / 2;
            used = 0;
        }
        else
        {
            want_height = curwin->w_height;
        }
    }

    while (topline > 1)
    {
        if (do_sms)
        {
            topline_back_winheight(&loff, FALSE);
            if (loff.height == MAXCOL)
            {
                break;
            }
            used += loff.height;
            if (!atend && boff.lnum < curbuf->b_ml.ml_line_count)
            {
                botline_forw(&boff);
                used += boff.height;
            }
            if (used > want_height)
            {
                if (used - loff.height < want_height)
                {
                    topline = loff.lnum;
                    skipcol = skipcol_from_plines(curwin, used - want_height);
                }
                break;
            }
            topline = loff.lnum;
            continue;
        }

        int done = FALSE;
        for (int round = 1; round <= 2; ++round)
        {
            if (prefer_above ? (round == 2 && below < above) : (round == 1 && below <= above))
            {
                if (boff.lnum < curbuf->b_ml.ml_line_count)
                {
                    botline_forw(&boff);
                    used += boff.height;
                    if (used > curwin->w_height)
                    {
                        done = TRUE;
                        break;
                    }
                    below += boff.height;
                }
                else
                {
                    ++below;
                    if (atend)
                    {
                        ++used;
                    }
                }
            }

            if (prefer_above ? (round == 1 && below >= above) : (round == 1 && below > above))
            {
                topline_back(&loff);
                if (loff.height == MAXCOL)
                {
                    used = MAXCOL;
                }
                else
                {
                    used += loff.height;
                }
                if (used > curwin->w_height)
                {
                    done = TRUE;
                    break;
                }
                above += loff.height;
                topline = loff.lnum;
            }
        }
        if (done)
        {
            break;
        }
    }

    {
        if (curwin->w_topline != topline || skipcol != 0 || curwin->w_skipcol != 0)
        {
            curwin->w_topline = topline;
            if (skipcol != 0)
            {
                curwin->w_skipcol = skipcol;
                redraw_later(UPD_NOT_VALID);
            }
            else if (do_sms)
            {
                reset_skipcol();
            }
        }
    }
    curwin->w_valid &= ~(VALID_WROW|VALID_CROW|VALID_BOTLINE|VALID_BOTLINE_AP);
    curwin->w_valid |= VALID_TOPLINE;
}

    static void
cursor_correct(void)
{
    int         above = 0;
    linenr_T    topline;
    int         below = 0;
    linenr_T    botline;
    int above_wanted;
    int below_wanted;
    linenr_T    cln;
    int         max_off;
    long        so = get_scrolloff_value();

    above_wanted = so;
    below_wanted = so;
    if (mouse_dragging > 0)
    {
        above_wanted = mouse_dragging - 1;
        below_wanted = mouse_dragging - 1;
    }
    if (curwin->w_topline == 1)
    {
        above_wanted = 0;
        max_off = curwin->w_height / 2;
        if (below_wanted > max_off)
        {
            below_wanted = max_off;
        }
    }
    validate_botline();
    if (curwin->w_botline == curbuf->b_ml.ml_line_count + 1 && mouse_dragging == 0)
    {
        below_wanted = 0;
        max_off = (curwin->w_height - 1) / 2;
        if (above_wanted > max_off)
        {
            above_wanted = max_off;
        }
    }

    cln = curwin->w_cursor.lnum;
    if (cln >= curwin->w_topline + above_wanted && cln < curwin->w_botline - below_wanted)
    {
        return;
    }

    topline = curwin->w_topline;
    botline = curwin->w_botline - 1;
    while ((above < above_wanted || below < below_wanted) && topline < botline)
    {
        if (below < below_wanted && (below <= above || above >= above_wanted))
        {
                below += plines(botline);
            --botline;
        }
        if (above < above_wanted && (above < below || below >= below_wanted))
        {
                above +=  plines(topline) ;
            ++topline;
        }
    }
    if (topline == botline || botline == 0)
    {
        curwin->w_cursor.lnum = topline;
    }
    else if (topline > botline)
    {
        curwin->w_cursor.lnum = botline;
    }
    else
    {
        if (cln < topline && curwin->w_topline > 1)
        {
            curwin->w_cursor.lnum = topline;
            curwin->w_valid &=
                            ~(VALID_WROW|VALID_WCOL|VALID_CHEIGHT|VALID_CROW);
        }
        if (cln > botline && curwin->w_botline <= curbuf->b_ml.ml_line_count)
        {
            curwin->w_cursor.lnum = botline;
            curwin->w_valid &=
                            ~(VALID_WROW|VALID_WCOL|VALID_CHEIGHT|VALID_CROW);
        }
    }
    check_cursor_moved(curwin);
    curwin->w_valid |= VALID_TOPLINE;
}

static int get_scroll_overlap(int dir)
{
    lineoff_T loff;
    int     min_height = curwin->w_height - 2;

    validate_botline();
    if ((dir ==  (-1)  && curwin->w_topline == 1) || (dir == FORWARD && curwin->w_botline > curbuf->b_ml.ml_line_count))
    {
        return min_height + 2;
    }

    loff.lnum = dir == FORWARD ? curwin->w_botline : curwin->w_topline - 1;
    loff.height = plines(loff.lnum);

    int h1 = loff.height;
    if (h1 > min_height)
    {
        return min_height + 2;
    }
    if (dir == FORWARD)
    {
        topline_back(&loff);
    }
    else
    {
        botline_forw(&loff);
    }

    int h2 = loff.height;
    if (h2 == MAXCOL || h2 + h1 > min_height)
    {
        return min_height + 2;
    }
    if (dir == FORWARD)
    {
        topline_back(&loff);
    }
    else
    {
        botline_forw(&loff);
    }

    int h3 = loff.height;
    if (h3 == MAXCOL || h3 + h2 > min_height)
    {
        return min_height + 2;
    }
    if (dir == FORWARD)
    {
        topline_back(&loff);
    }
    else
    {
        botline_forw(&loff);
    }

    int h4 = loff.height;
    if (h4 == MAXCOL || h4 + h3 + h2 > min_height || h3 + h2 + h1 > min_height)
    {
        return min_height + 1;
    }
    else
    {
        return min_height;
    }
}

static int scroll_with_sms(int dir, long count, long *curscount)
{
    int         prev_sms = curwin-> w_onebuf_opt.wo_sms ;
    colnr_T     prev_skipcol = curwin->w_skipcol;
    linenr_T    prev_topline = curwin->w_topline;

    curwin-> w_onebuf_opt.wo_sms  = TRUE;
    scroll_redraw(dir == FORWARD, count);

    if (!prev_sms && curwin->w_skipcol > 0)
    {
        int fixdir = dir;
        if (labs(curwin->w_topline - prev_topline) > (dir ==  (-1) ))
        {
            fixdir = dir * -1;
        }

        int width1 = curwin->w_width - curwin_col_off();
        int width2 = width1 + curwin_col_off2();
        count = 1 + (curwin->w_skipcol - width1 - 1) / width2;
        if (fixdir == FORWARD)
        {
            count = 1 + (linetabsize_eol(curwin, curwin->w_topline) - curwin->w_skipcol - width1 + width2 - 1) / width2;
        }
        scroll_redraw(fixdir == FORWARD, count);
        *curscount += count * (fixdir == dir ? 1 : -1);
    }
    curwin-> w_onebuf_opt.wo_sms  = prev_sms;

    return curwin->w_topline != prev_topline
        || curwin->w_skipcol != prev_skipcol;
}

    static int
pagescroll(int dir, long count, int half)
{
    int         did_move = FALSE;
    int         buflen = curbuf->b_ml.ml_line_count;
    colnr_T     prev_col = curwin->w_cursor.col;
    colnr_T     prev_curswant = curwin->w_curswant;
    linenr_T    prev_lnum = curwin->w_cursor.lnum;
    oparg_T     oa = { 0 };
    cmdarg_T    ca = { 0 };
    ca.oap = &oa;

    if (half)
    {
        if (count)
        {
            curwin-> w_onebuf_opt.wo_scr  = MIN(curwin->w_height, count);
        }
        count = MIN(curwin->w_height, curwin-> w_onebuf_opt.wo_scr );

        long curscount = count;
        if (dir == FORWARD && (curwin->w_topline + curwin->w_height + count > buflen))
        {
            int n = plines_correct_topline(curwin, curwin->w_topline, FALSE);
            if (n - count < curwin->w_height && curwin->w_topline < buflen)
            {
                n += plines_m_win(curwin, curwin->w_topline + 1, buflen, curwin->w_height + count);
            }
            if (n < curwin->w_height + count)
            {
                count = n - curwin->w_height;
            }
        }

        if (count > 0)
        {
            did_move = scroll_with_sms(dir, count, &curscount);
            curwin->w_cursor.lnum = prev_lnum;
            curwin->w_cursor.col = prev_col;
            curwin->w_curswant = prev_curswant;
        }

        if (curwin-> w_onebuf_opt.wo_wrap )
        {
            nv_screengo(&oa, dir, curscount);
        }
        else if (dir == FORWARD)
        {
            cursor_down_inner(curwin, curscount);
        }
        else
        {
            cursor_up_inner(curwin, curscount);
        }
    }
    else
    {
        count *= (( (firstwin == lastwin)  && p_window > 0 && p_window < Rows - 1) ? MAX(1, p_window - 2) : get_scroll_overlap(dir));
        did_move = scroll_with_sms(dir, count, &count);

        if (did_move)
        {
            validate_botline();
            linenr_T lnum = (dir == FORWARD ? curwin->w_topline : curwin->w_botline - 1);
            curwin->w_cursor.lnum = MAX(lnum, 1);
        }
    }

    if (get_scrolloff_value() > 0)
    {
        cursor_correct();
    }
    did_move = did_move
        || prev_col != curwin->w_cursor.col
        || prev_lnum != curwin->w_cursor.lnum;

    if (!did_move)
    {
        beep_flush();
    }
    else if (!curwin-> w_onebuf_opt.wo_sms )
    {
        beginline(BL_SOL | BL_FIX);
    }
    else if (p_sol)
    {
        nv_g_home_m_cmd(&ca);
    }

    return did_move ? OK : FAIL;
}

    static void
do_check_cursorbind(void)
{
    static win_T        *prev_curwin = NULL;
    static buf_T        *prev_curbuf = NULL;
    static varnumber_T  prev_changedtick = 0;
    static pos_T        prev_cursor = {0, 0, 0};

    if (curwin == prev_curwin && curbuf == prev_curbuf &&  ((curbuf)->b_ct_di.di_tv.vval.v_number)  == prev_changedtick &&  (((curwin->w_cursor).lnum == (prev_cursor).lnum) && ((curwin->w_cursor).col == (prev_cursor).col) && ((curwin->w_cursor).coladd == (prev_cursor).coladd)) )
    {
        return;
    }
    prev_curwin = curwin;
    prev_curbuf = curbuf;
    prev_changedtick =  ((curbuf)->b_ct_di.di_tv.vval.v_number) ;
    prev_cursor = curwin->w_cursor;

    linenr_T    line = curwin->w_cursor.lnum;
    colnr_T     col = curwin->w_cursor.col;
    colnr_T     coladd = curwin->w_cursor.coladd;
    colnr_T     curswant = curwin->w_curswant;
    int         set_curswant = curwin->w_set_curswant;
    win_T       *old_curwin = curwin;
    buf_T       *old_curbuf = curbuf;
    int         old_VIsual_select = VIsual_select;
    int         old_VIsual_active = VIsual_active;

    VIsual_select = VIsual_active = 0;
     for ((curwin) = firstwin; (curwin) != NULL; (curwin) = (curwin)->w_next) 
    {
        curbuf = curwin->w_buffer;
        if (curwin != old_curwin && curwin-> w_onebuf_opt.wo_crb )
        {
                curwin->w_cursor.lnum = line;
            curwin->w_cursor.col = col;
            curwin->w_cursor.coladd = coladd;
            curwin->w_curswant = curswant;
            curwin->w_set_curswant = set_curswant;

            int restart_edit_save = restart_edit;
            restart_edit = 'a';
            check_cursor();

            if (!curwin-> w_onebuf_opt.wo_scb )
            {
                validate_cursor();
            }

            restart_edit = restart_edit_save;
            if (has_mbyte)
            {
                mb_adjust_cursor();
            }
            redraw_later(UPD_VALID);

            if (!curwin-> w_onebuf_opt.wo_scb )
            {
                update_topline();
            }
            curwin->w_redr_status = true;
        }
    }

    VIsual_select = old_VIsual_select;
    VIsual_active = old_VIsual_active;
    curwin = old_curwin;
    curbuf = old_curbuf;
}

