    static void
clearop(oparg_T *oap)
{
    oap->op_type = OP_NOP;
    oap->regname = 0;
    oap->motion_force = NUL;
    oap->use_reg_one = FALSE;
    motion_force = NUL;
}

    static void
clearopbeep(oparg_T *oap)
{
    clearop(oap);
    beep_flush();
}

    static void
unshift_special(cmdarg_T *cap)
{
    switch (cap->cmdchar)
    {
        case   (-(('%') + ((int)('i') << 8)))  :
            cap->cmdchar =   (-(('k') + ((int)('r') << 8)))  ;
            break;
        case   (-(('#') + ((int)('4') << 8)))  :
            cap->cmdchar =   (-(('k') + ((int)('l') << 8)))  ;
            break;
        case   (-((KS_EXTRA) + ((int)(KE_S_UP) << 8)))  :
            cap->cmdchar =   (-(('k') + ((int)('u') << 8)))  ;
            break;
        case   (-((KS_EXTRA) + ((int)(KE_S_DOWN) << 8)))  :
            cap->cmdchar =   (-(('k') + ((int)('d') << 8)))  ;
            break;
        case   (-(('#') + ((int)('2') << 8)))  :
            cap->cmdchar =   (-(('k') + ((int)('h') << 8)))  ;
            break;
        case   (-(('*') + ((int)('7') << 8)))  :
            cap->cmdchar =   (-(('@') + ((int)('7') << 8)))  ;
            break;
    }
    cap->cmdchar = simplify_key(cap->cmdchar, &mod_mask);
}

    static void
may_clear_cmdline(void)
{
    if (mode_displayed)
    {
        clear_cmdline = TRUE;
    }
    else
    {
        clear_showcmd();
    }
}

static char_u   old_showcmd_buf[ (SHOWCMD_COLS + 1 + 30) ];
static int      showcmd_is_clear = TRUE;
static int      showcmd_visual = FALSE;

static void display_showcmd(void);

    static void
clear_showcmd(void)
{
    if (!p_sc)
    {
        return;
    }

    if (VIsual_active && stuff_empty() && typebuf.tb_len == 0 && !using_script())
    {
        int             cursor_bot =  (((VIsual).lnum != (curwin->w_cursor).lnum)               ? (VIsual).lnum < (curwin->w_cursor).lnum                   : (VIsual).col != (curwin->w_cursor).col                        ? (VIsual).col < (curwin->w_cursor).col                     : (VIsual).coladd < (curwin->w_cursor).coladd) ;
        long            lines;
        colnr_T leftcol;
        colnr_T rightcol;
        linenr_T top;
        linenr_T bot;

        if (cursor_bot)
        {
            top = VIsual.lnum;
            bot = curwin->w_cursor.lnum;
        }
        else
        {
            top = curwin->w_cursor.lnum;
            bot = VIsual.lnum;
        }
        lines = bot - top + 1;

        if (VIsual_mode == Ctrl_V)
        {
            getvcols(curwin, &curwin->w_cursor, &VIsual, &leftcol, &rightcol, GETVCOL_END_EXCL_LBR);
            vim_snprintf((char *)showcmd_buf,  (SHOWCMD_COLS + 1 + 30) , "%ldx%ld", lines, (long)(rightcol - leftcol + 1));
        }
        else if (VIsual_mode == 'V' || VIsual.lnum != curwin->w_cursor.lnum)
        {
            vim_snprintf((char *)showcmd_buf,  (SHOWCMD_COLS + 1 + 30) , "%ld", lines);
        }
        else
        {
            char_u *s;
            char_u *e;
            int     l;
            int     bytes = 0;
            int     chars = 0;

            if (cursor_bot)
            {
                s = ml_get_pos(&VIsual);
                e = ml_get_cursor();
            }
            else
            {
                s = ml_get_cursor();
                e = ml_get_pos(&VIsual);
            }
            while ((*p_sel != 'e') ? s <= e : s < e)
            {
                l = (*mb_ptr2len)(s);
                if (l == 0)
                {
                    ++bytes;
                    ++chars;
                    break;
                }
                bytes += l;
                ++chars;
                s += l;
            }
            if (bytes == chars)
            {
                vim_snprintf((char *)showcmd_buf,  (SHOWCMD_COLS + 1 + 30) , "%d", chars);
            }
            else
            {
                vim_snprintf((char *)showcmd_buf,  (SHOWCMD_COLS + 1 + 30) , "%d-%d", chars, bytes);
            }
        }
        showcmd_buf[SHOWCMD_COLS] = NUL;
        showcmd_visual = TRUE;
    }
    else
    {
        showcmd_buf[0] = NUL;
        showcmd_visual = FALSE;

        if (showcmd_is_clear)
        {
            return;
        }
    }

    display_showcmd();
}

    static int
add_to_showcmd(int c)
{
    char_u      *p;
    int         old_len;
    int         extra_len;
    int         overflow;
    int         i;
    char_u      mbyte_buf[MB_MAXBYTES];
    static int  ignore[] =
    {
          (-((KS_EXTRA) + ((int)(KE_IGNORE) << 8)))  ,   (-(('P') + ((int)('S') << 8)))  ,
          (-((KS_EXTRA) + ((int)(KE_LEFTMOUSE) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_LEFTDRAG) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_LEFTRELEASE) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_MOUSEMOVE) << 8)))  ,
          (-((KS_EXTRA) + ((int)(KE_MIDDLEMOUSE) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_MIDDLEDRAG) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_MIDDLERELEASE) << 8)))  ,
          (-((KS_EXTRA) + ((int)(KE_RIGHTMOUSE) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_RIGHTDRAG) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_RIGHTRELEASE) << 8)))  ,
          (-((KS_EXTRA) + ((int)(KE_MOUSEDOWN) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_MOUSEUP) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_MOUSELEFT) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_MOUSERIGHT) << 8)))  ,
          (-((KS_EXTRA) + ((int)(KE_X1MOUSE) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_X1DRAG) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_X1RELEASE) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_X2MOUSE) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_X2DRAG) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_X2RELEASE) << 8)))  ,
          (-((KS_EXTRA) + ((int)(KE_CURSORHOLD) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_COMMAND) << 8)))  ,   (-((KS_EXTRA) + ((int)(KE_SCRIPT_COMMAND) << 8)))  ,
        0
    };

    if (!p_sc || msg_silent != 0)
    {
        return FALSE;
    }

    if (showcmd_visual)
    {
        showcmd_buf[0] = NUL;
        showcmd_visual = FALSE;
    }

    if ( ((c) < 0) )
    {
        for (i = 0; ignore[i] != 0; ++i)
        {
            if (ignore[i] == c)
            {
                return FALSE;
            }
        }
    }

    if (c <= 0x7f || !vim_isprintc(c))
    {
        p = transchar(c);
        if (*p == ' ')
        {
             strcpy((char *)(p), (char *)("<20>")) ;
        }
    }
    else
    {
        mbyte_buf[(*mb_char2bytes)(c, mbyte_buf)] = NUL;
        p = mbyte_buf;
    }
    old_len = (int) strlen((char *)(showcmd_buf)) ;
    extra_len = (int) strlen((char *)(p)) ;
    overflow = old_len + extra_len - SHOWCMD_COLS;
    if (overflow > 0)
    {
         memmove((char *)(showcmd_buf), (char *)(showcmd_buf + overflow), old_len - overflow + 1) ;
    }
     strcat((char *)(showcmd_buf), (char *)(p)) ;

    if (char_avail())
    {
        return FALSE;
    }

    display_showcmd();

    return TRUE;
}

    static void
add_to_showcmd_c(int c)
{
    if (!add_to_showcmd(c))
    {
        setcursor();
    }
}

    static void
del_from_showcmd(int len)
{
    int     old_len;

    if (!p_sc)
    {
        return;
    }

    old_len = (int) strlen((char *)(showcmd_buf)) ;
    if (len > old_len)
    {
        len = old_len;
    }
    showcmd_buf[old_len - len] = NUL;

    if (!char_avail())
    {
        display_showcmd();
    }
}

    static void
push_showcmd(void)
{
    if (p_sc)
    {
         strcpy((char *)(old_showcmd_buf), (char *)(showcmd_buf)) ;
    }
}

    static void
pop_showcmd(void)
{
    if (!p_sc)
    {
        return;
    }

     strcpy((char *)(showcmd_buf), (char *)(old_showcmd_buf)) ;

    display_showcmd();
}

    static void
showcmd_update_clear_state(void)
{
    showcmd_is_clear = (showcmd_buf[0] == NUL);
}

    static void
display_showcmd(void)
{
    int     len = vim_strsize(showcmd_buf);

    showcmd_update_clear_state();
    cursor_off();

    if (*p_sloc == 's')
    {
        if (showcmd_is_clear && !vgetc_busy)
        {
            curwin->w_redr_status = true;
        }
        else
        {
            win_redr_status(curwin, FALSE);
        }
    }
    else if (*p_sloc == 't')
    {
        if (showcmd_is_clear && !vgetc_busy)
        {
            redraw_tabline = TRUE;
        }
        else
        {
            draw_tabline();
        }
    }
    else
    {
        if (!showcmd_is_clear)
        {
            screen_puts(showcmd_buf, (int)Rows - 1, cmdline_col_off + sc_col, 0);
        }

        screen_puts((char_u *)"          " + len, (int)Rows - 1, cmdline_col_off + sc_col + len, 0);
    }

    setcursor();
}

    static void
do_check_scrollbind(int check)
{
    static win_T        *old_curwin = NULL;
    static linenr_T     old_topline = 0;
    static buf_T        *old_buf = NULL;
    static colnr_T      old_leftcol = 0;

    if (check && curwin-> w_onebuf_opt.wo_scb )
    {
        if (did_syncbind)
        {
            did_syncbind = FALSE;
        }
        else if (curwin == old_curwin)
        {
            if ((curwin->w_buffer == old_buf) && (curwin->w_topline != old_topline || curwin->w_leftcol != old_leftcol))
            {
                check_scrollbind(curwin->w_topline - old_topline, (long)(curwin->w_leftcol - old_leftcol));
            }
        }
        else if (vim_strchr(p_sbo, 'j'))
        {
            check_scrollbind(curwin->w_topline - curwin->w_scbind_pos, 0L);
        }
        curwin->w_scbind_pos = curwin->w_topline;
    }

    old_curwin = curwin;
    old_topline = curwin->w_topline;
    old_buf = curwin->w_buffer;
    old_leftcol = curwin->w_leftcol;
}

    static void
check_scrollbind(linenr_T topline_diff, long leftcol_diff)
{
    int         want_ver;
    int         want_hor;
    win_T       *old_curwin = curwin;
    buf_T       *old_curbuf = curbuf;
    int         old_VIsual_select = VIsual_select;
    int         old_VIsual_active = VIsual_active;
    colnr_T     tgt_leftcol = curwin->w_leftcol;
    long        topline;
    long        y;

    want_ver = (vim_strchr(p_sbo, 'v') && topline_diff != 0);
    want_hor = (vim_strchr(p_sbo, 'h') && (leftcol_diff || topline_diff != 0));

    VIsual_select = VIsual_active = 0;
     for ((curwin) = firstwin; (curwin) != NULL; (curwin) = (curwin)->w_next) 
    {
        curbuf = curwin->w_buffer;
        if (curwin == old_curwin || !curwin-> w_onebuf_opt.wo_scb )
        {
            continue;
        }

        if (want_ver)
        {
            {
                curwin->w_scbind_pos += topline_diff;
                topline = curwin->w_scbind_pos;
                if (topline > curbuf->b_ml.ml_line_count)
                {
                    topline = curbuf->b_ml.ml_line_count;
                }
                if (topline < 1)
                {
                    topline = 1;
                }

                y = topline - curwin->w_topline;
                if (y > 0)
                {
                    scrollup(y, FALSE);
                }
                else
                {
                    scrolldown(-y, FALSE);
                }
            }

            redraw_later(UPD_VALID);
            cursor_correct();
            curwin->w_redr_status = true;
        }

        if (want_hor)
        {
            (void)set_leftcol(tgt_leftcol);
        }
    }

    VIsual_select = old_VIsual_select;
    VIsual_active = old_VIsual_active;
    curwin = old_curwin;
    curbuf = old_curbuf;
}

