    static void
set_init_default_backupskip(void)
{
    int         opt_idx;
    int         i;
    char_u      *p;
    int         plen;
    static char *(names[4]) = {"", "TMPDIR", "TEMP", "TMP"};
    garray_T    ga;

    opt_idx = findoption((char_u *)"backupskip");

    ga_init2(&ga, 1, 100);
    for (i = 0; i < (int) (sizeof(names) / sizeof((names)[0])) ; ++i)
    {
        int             mustfree = FALSE;
        if (*names[i] == NUL)
        {
            p = (char_u *)"/tmp";
            plen = (int) (sizeof("/tmp" "") - 1) ;
        }
        else
        {
            p = vim_getenv((char_u *)names[i], &mustfree);
            plen = 0;
        }
        if (p != NULL && *p != NUL)
        {
            char_u  *item;
            size_t  itemsize;
            int     has_trailing_path_sep = FALSE;

            if (plen == 0)
            {
                plen = (int) strlen((char *)(p)) ;
                if (after_pathsep(p, p + plen))
                {
                    has_trailing_path_sep = TRUE;
                }
            }

            itemsize = plen + (has_trailing_path_sep ? 0 : 1) + 2;
            item = alloc(itemsize);
            if (item != NULL)
            {
                size_t  itemseplen = (ga.ga_len == 0) ? 0 : 1;
                size_t  itemlen;

                itemlen = vim_snprintf((char *)item, itemsize, "%s%s*", p, (has_trailing_path_sep) ? "" :  "/" );

                if (find_dup_item(ga.ga_data, item, itemlen, options[opt_idx].flags) == NULL && ga_grow(&ga, (int)(itemseplen + itemlen + 1)) == OK)
                {
                    ga.ga_len += vim_snprintf((char *)ga.ga_data + ga.ga_len, itemseplen + itemlen + 1, "%s%s", (itemseplen > 0) ? "," : "", item);
                }
                vim_free(item);
            }
        }
        if (mustfree)
        {
            vim_free(p);
        }
    }
    if (ga.ga_data != NULL)
    {
        set_string_default("bsk", ga.ga_data);
        vim_free(ga.ga_data);
    }
}

    static void
set_init_default_maxmemtot(void)
{
    int         opt_idx;
    long_u      n;

    opt_idx = findoption((char_u *)"maxmemtot");
    if (opt_idx < 0)
    {
        return;
    }

    {
        n = (mch_total_mem(FALSE) >> 1);
        options[opt_idx].def_val[VI_DEFAULT] = (char_u *)n;
        opt_idx = findoption((char_u *)"maxmem");
        if (opt_idx >= 0)
        {
                options[opt_idx].def_val[VI_DEFAULT] = (char_u *)n;
        }
    }
}

    static void
set_init_default_cdpath(void)
{
    int         opt_idx;
    char_u      *cdpath;
    char_u      *buf;
    int i;
    int j;
    int mustfree = FALSE;

    cdpath = vim_getenv((char_u *)"CDPATH", &mustfree);
    if (cdpath == NULL)
    {
        return;
    }

    buf = alloc(( strlen((char *)(cdpath))  << 1) + 2);
    if (buf != NULL)
    {
        buf[0] = ',';
        j = 1;
        for (i = 0; cdpath[i] != NUL; ++i)
        {
            if (vim_ispathlistsep(cdpath[i]))
            {
                buf[j++] = ',';
            }
            else
            {
                if (cdpath[i] == ' ' || cdpath[i] == ',')
                {
                    buf[j++] = '\\';
                }
                buf[j++] = cdpath[i];
            }
        }
        buf[j] = NUL;
        opt_idx = findoption((char_u *)"cdpath");
        if (opt_idx >= 0)
        {
            options[opt_idx].def_val[VI_DEFAULT] = buf;
            options[opt_idx].flags |= P_DEF_ALLOCED;
        }
        else
        {
            vim_free(buf);
        }
    }
    if (mustfree)
    {
        vim_free(cdpath);
    }
}

