    static void
win_copy_options(win_T *wp_from, win_T *wp_to)
{
    copy_winopt(&wp_from->w_onebuf_opt, &wp_to->w_onebuf_opt);
    copy_winopt(&wp_from->w_allbuf_opt, &wp_to->w_allbuf_opt);
    after_copy_winopt(wp_to);
}

    static void
after_copy_winopt(win_T *wp)
{
    char *errmsg = update_winhighlight(wp, wp-> w_onebuf_opt.wo_whl );

    if (errmsg != NULL)
    {
        emsg(_(errmsg));
    }

    if (wp-> w_onebuf_opt.wo_wrap )
    {
        wp->w_leftcol = 0;
    }
    else
    {
        wp->w_skipcol = 0;
    }
    set_listchars_option(wp, wp-> w_onebuf_opt.wo_lcs , TRUE, NULL, 0);
    set_fillchars_option(wp, wp-> w_onebuf_opt.wo_fcs , TRUE, NULL, 0);
}

    static char_u *
copy_option_val(char_u *val)
{
    if (val == empty_option)
    {
        return empty_option;
    }
    return vim_strsave(val);
}

    static void
copy_winopt(winopt_T *from, winopt_T *to)
{
    to->wo_list = from->wo_list;
    to->wo_lcs = copy_option_val(from->wo_lcs);
    to->wo_fcs = copy_option_val(from->wo_fcs);
    to->wo_nu = from->wo_nu;
    to->wo_rnu = from->wo_rnu;
    to->wo_ve = copy_option_val(from->wo_ve);
    to->wo_ve_flags = from->wo_ve_flags;
    to->wo_wrap = from->wo_wrap;
    to->wo_wcr = copy_option_val(from->wo_wcr);
    to->wo_scb = from->wo_scb;
    to->wo_scb_save = from->wo_scb_save;
    to->wo_sms = from->wo_sms;
    to->wo_crb = from->wo_crb;
    to->wo_crb_save = from->wo_crb_save;
    to->wo_siso = from->wo_siso;
    to->wo_so = from->wo_so;
    to->wo_sop = from->wo_sop;
    to->wo_eiw = copy_option_val(from->wo_eiw);

    to->wo_wrap_flags = from->wo_wrap_flags;
    to->wo_whl = copy_option_val(from->wo_whl);

    check_winopt(to);
}

