static int expand_option_idx = -1;
static int expand_option_start_col = 0;
static char_u expand_option_name[5] = {'t', '_', NUL, NUL, NUL};
static int expand_option_flags = 0;
static int expand_option_append = FALSE;

    static void
set_context_in_set_cmd(expand_T    *xp, char_u      *arg, int         opt_flags)
{
    int         nextchar;
    long_u      flags = 0;
    int         opt_idx = 0;
    char_u      *p;
    char_u      *s;
    int         is_term_option = FALSE;
    int         key;
    char_u      *argend;

    expand_option_flags = opt_flags;

    xp->xp_context = EXPAND_SETTINGS;
    if (*arg == NUL)
    {
        xp->xp_pattern = arg;
        return;
    }
    argend = arg +  strlen((char *)(arg)) ;
    p = argend - 1;
    if (*p == ' ' && *(p - 1) != '\\')
    {
        xp->xp_pattern = p + 1;
        return;
    }
    while (p > arg)
    {
        s = p;
        if (*p == ' ' || *p == ',')
        {
            while (s > arg && *(s - 1) == '\\')
            {
                --s;
            }
        }
        if (*p == ' ' && ((p - s) & 1) == 0)
        {
            ++p;
            break;
        }
        --p;
    }
    if ( strncmp((char *)(p), (char *)("no"), (2))  == 0 &&  strncmp((char *)(p), (char *)("novice"), (6))  != 0)
    {
        xp->xp_context = EXPAND_BOOL_SETTINGS;
        xp->xp_prefix = XP_PREFIX_NO;
        p += 2;
    }
    else if ( strncmp((char *)(p), (char *)("inv"), (3))  == 0)
    {
        xp->xp_context = EXPAND_BOOL_SETTINGS;
        xp->xp_prefix = XP_PREFIX_INV;
        p += 3;
    }
    xp->xp_pattern = arg = p;
    if (*arg == '<')
    {
        while (*p != '>')
        {
            if (*p++ == NUL)
            {
                return;
            }
        }
        key = get_special_key_code(arg + 1);
        if (key == 0)
        {
            xp->xp_context = EXPAND_NOTHING;
            return;
        }
        nextchar = *++p;
        is_term_option = TRUE;
        expand_option_name[2] =  ((-(key)) & 0xff) ;
        expand_option_name[3] =  (((unsigned)(-(key)) >> 8) & 0xff) ;
    }
    else
    {
        if (p[0] == 't' && p[1] == '_')
        {
            p += 2;
            if (*p != NUL)
            {
                ++p;
            }
            if (*p == NUL)
            {
                return;
            }
            nextchar = *++p;
            is_term_option = TRUE;
            expand_option_name[2] = p[-2];
            expand_option_name[3] = p[-1];
        }
        else
        {
            while ( ( ( ((unsigned)(*p) - 'A' < 26)  ||  ((unsigned)(*p) - 'a' < 26) )  ||  ((unsigned)(*p) - '0' < 10) )  || *p == '_' || *p == '*')
            {
                p++;
            }
            if (*p == NUL)
            {
                return;
            }
            nextchar = *p;
            *p = NUL;
            opt_idx = findoption(arg);
            *p = nextchar;
            if (opt_idx == -1 || options[opt_idx].var == NULL)
            {
                xp->xp_context = EXPAND_NOTHING;
                return;
            }
            flags = options[opt_idx].flags;
            if (flags & P_BOOL)
            {
                xp->xp_context = EXPAND_NOTHING;
                return;
            }
        }
    }
    expand_option_append = FALSE;
    int expand_option_subtract = FALSE;
    if ((nextchar == '-' || nextchar == '+' || nextchar == '^') && p[1] == '=')
    {
        if (nextchar == '-')
        {
            expand_option_subtract = TRUE;
        }
        if (nextchar == '+' || nextchar == '^')
        {
            expand_option_append = TRUE;
        }
        ++p;
        nextchar = '=';
    }
    if ((nextchar != '=' && nextchar != ':') || xp->xp_context == EXPAND_BOOL_SETTINGS)
    {
        xp->xp_context =  (-2) ;
        return;
    }

    if (is_term_option)
    {
        expand_option_idx = -1;
    }
    else
    {
        expand_option_idx = opt_idx;
    }

    if (!is_term_option)
    {
        if (options[opt_idx].flags & P_NO_CMD_EXPAND)
        {
            xp->xp_context= (-2) ;
            return;
        }
    }

    xp->xp_pattern = p + 1;
    expand_option_start_col = (int)(p + 1 - xp->xp_line);

    if (options[opt_idx].var == (char_u *)&p_ft)
    {
        xp->xp_context = EXPAND_FILETYPE;
        return;
    }

    if (expand_option_subtract)
    {
        xp->xp_context = EXPAND_SETTING_SUBTRACT;
        return;
    }
    else if (expand_option_idx >= 0 && options[expand_option_idx].opt_expand_cb != NULL)
    {
        xp->xp_context = EXPAND_STRING_SETTING;
    }
    else if (*xp->xp_pattern == NUL)
    {
        xp->xp_context = EXPAND_OLD_SETTING;
        return;
    }
    else
    {
        xp->xp_context = EXPAND_NOTHING;
    }

    if (is_term_option || (flags & P_NUM))
    {
        return;
    }

    if (flags & P_EXPAND)
    {
        p = options[opt_idx].var;
        if (p == (char_u *)&p_bdir || p == (char_u *)&p_dir || p == (char_u *)&p_pp || p == (char_u *)&p_rtp || p == (char_u *)&p_cdpath)
        {
            xp->xp_context = EXPAND_DIRECTORIES;
            xp->xp_backslash = XP_BS_ONE;
        }
        else
        {
            xp->xp_context = EXPAND_FILES;
            xp->xp_backslash = XP_BS_ONE;
        }
        if (flags & P_COMMA)
        {
            xp->xp_backslash |= XP_BS_COMMA;
        }
    }

    if ((flags & P_EXPAND) || (flags & P_COMMA) || (flags & P_COLON))
    {
        for (p = argend - 1; p >= xp->xp_pattern; --p)
        {
            if (*p == ' ' || *p == ',' || (*p == ':' && (flags & P_COLON)))
            {
                s = p;
                while (s > xp->xp_pattern && *(s - 1) == '\\')
                {
                    --s;
                }
                if ((*p == ' ' && ((xp->xp_backslash & XP_BS_THREE) && (p - s) < 3)) || (*p == ',' && (flags & P_COMMA) && (p - s) < 2) || (*p == ':' && (flags & P_COLON)))
                {
                    xp->xp_pattern = p + 1;
                    break;
                }
            }
        }
    }

    if (flags & P_FLAGLIST)
    {
        xp->xp_pattern = argend;
    }

}

    static int
match_str(char_u          *str, regmatch_T      *regmatch, char_u          **matches, int             idx, int             test_only, int             fuzzy, char_u          *fuzzystr, fuzmatch_str_T  *fuzmatch)
{
    if (!fuzzy)
    {
        if (vim_regexec(regmatch, str, (colnr_T)0))
        {
            if (!test_only)
            {
                matches[idx] = vim_strsave(str);
            }
            return TRUE;
        }
    }
    else
    {
        int score;

        score = fuzzy_match_str(str, fuzzystr);
        if (score !=  INT_MIN )
        {
            if (!test_only)
            {
                fuzmatch[idx].idx = idx;
                fuzmatch[idx].str = vim_strsave(str);
                fuzmatch[idx].score = score;
            }

            return TRUE;
        }
    }

    return FALSE;
}

    static int
ExpandSettings(expand_T    *xp, regmatch_T  *regmatch, char_u      *fuzzystr, int         *numMatches, char_u      ***matches, int         can_fuzzy)
{
    int         num_normal = 0;
    int         num_term = 0;
    int         opt_idx;
    int         match;
    int         count = 0;
    char_u      *str;
    int         loop;
    int         is_term_opt;
    char_u      name_buf[MAX_KEY_NAME_LEN];
    static char *(names[]) = {"all", "termcap"};
    int         ic = regmatch->rm_ic;
    int         fuzzy;
    fuzmatch_str_T  *fuzmatch = NULL;

    fuzzy = can_fuzzy && cmdline_fuzzy_complete(fuzzystr);

    for (loop = 0; loop <= 1; ++loop)
    {
        regmatch->rm_ic = ic;
        if (xp->xp_context != EXPAND_BOOL_SETTINGS)
        {
            for (match = 0; match < (int) (sizeof(names) / sizeof((names)[0])) ; ++match)
            {
                if (match_str((char_u *)names[match], regmatch, *matches, count, (loop == 0), fuzzy, fuzzystr, fuzmatch))
                {
                    if (loop == 0)
                    {
                        num_normal++;
                    }
                    else
                    {
                        count++;
                    }
                }
            }
        }
        for (opt_idx = 0; (str = (char_u *)options[opt_idx].fullname) != NULL; opt_idx++)
        {
            if (options[opt_idx].var == NULL)
            {
                continue;
            }
            if (xp->xp_context == EXPAND_BOOL_SETTINGS && !(options[opt_idx].flags & P_BOOL))
            {
                continue;
            }
            is_term_opt = istermoption_idx(opt_idx);
            if (is_term_opt && num_normal > 0)
            {
                continue;
            }

            if (match_str(str, regmatch, *matches, count, (loop == 0), fuzzy, fuzzystr, fuzmatch))
            {
                if (loop == 0)
                {
                    if (is_term_opt)
                    {
                        num_term++;
                    }
                    else
                    {
                        num_normal++;
                    }
                }
                else
                {
                    count++;
                }
            }
            else if (!fuzzy && options[opt_idx].shortname != NULL && vim_regexec(regmatch, (char_u *)options[opt_idx].shortname, (colnr_T)0))
            {
                if (loop == 0)
                {
                    if (is_term_opt)
                    {
                        num_term++;
                    }
                    else
                    {
                        num_normal++;
                    }
                }
                else
                {
                    (*matches)[count++] = vim_strsave(str);
                }
            }
            else if (is_term_opt)
            {
                name_buf[0] = '<';
                name_buf[1] = 't';
                name_buf[2] = '_';
                name_buf[3] = str[2];
                name_buf[4] = str[3];
                name_buf[5] = '>';
                name_buf[6] = NUL;

                if (match_str(name_buf, regmatch, *matches, count, (loop == 0), fuzzy, fuzzystr, fuzmatch))
                {
                    if (loop == 0)
                    {
                        num_term++;
                    }
                    else
                    {
                        count++;
                    }
                }
            }
        }

        if (xp->xp_context != EXPAND_BOOL_SETTINGS  && num_normal == 0)
        {
            for (opt_idx = 0; (str = get_termcode(opt_idx)) != NULL; opt_idx++)
            {
                if (! (isprint ((unsigned char)(str[0])))  || ! (isprint ((unsigned char)(str[1]))) )
                {
                    continue;
                }

                name_buf[0] = 't';
                name_buf[1] = '_';
                name_buf[2] = str[0];
                name_buf[3] = str[1];
                name_buf[4] = NUL;

                if (match_str(name_buf, regmatch, *matches, count, (loop == 0), fuzzy, fuzzystr, fuzmatch))
                {
                    if (loop == 0)
                    {
                        num_term++;
                    }
                    else
                    {
                        count++;
                    }
                }
                else
                {
                    name_buf[0] = '<';
                    name_buf[1] = 't';
                    name_buf[2] = '_';
                    name_buf[3] = str[0];
                    name_buf[4] = str[1];
                    name_buf[5] = '>';
                    name_buf[6] = NUL;

                    if (match_str(name_buf, regmatch, *matches, count, (loop == 0), fuzzy, fuzzystr, fuzmatch))
                    {
                        if (loop == 0)
                        {
                            num_term++;
                        }
                        else
                        {
                            count++;
                        }
                    }
                }
            }

            regmatch->rm_ic = TRUE;
            for (opt_idx = 0; (str = get_key_name(opt_idx)) != NULL; opt_idx++)
            {
                name_buf[0] = '<';
                 strcpy((char *)(name_buf + 1), (char *)(str)) ;
                 strcat((char *)(name_buf), (char *)(">")) ;

                if (match_str(name_buf, regmatch, *matches, count, (loop == 0), fuzzy, fuzzystr, fuzmatch))
                {
                    if (loop == 0)
                    {
                        num_term++;
                    }
                    else
                    {
                        count++;
                    }
                }
            }
        }
        if (loop == 0)
        {
            if (num_normal > 0)
            {
                *numMatches = num_normal;
            }
            else if (num_term > 0)
            {
                *numMatches = num_term;
            }
            else
            {
                return OK;
            }
            if (!fuzzy)
            {
                *matches =  (char_u * *)alloc(sizeof(char_u *) * (*numMatches)) ;
                if (*matches == NULL)
                {
                    *matches = (char_u **)"";
                    return FAIL;
                }
            }
            else
            {
                fuzmatch =  (fuzmatch_str_T *)alloc(sizeof(fuzmatch_str_T) * (*numMatches)) ;
                if (fuzmatch == NULL)
                {
                    *matches = (char_u **)"";
                    return FAIL;
                }
            }
        }
    }

    if (fuzzy && fuzzymatches_to_strmatches(fuzmatch, matches, count, FALSE) == FAIL)
    {
        return FAIL;
    }

    return OK;
}

    static char_u*
escape_option_str_cmdline(char_u *var)
{
    char_u *buf;

    buf = vim_strsave_escaped(var, escape_chars);
    if (buf == NULL)
    {
        return NULL;
    }

    return buf;
}

    static int
ExpandOldSetting(int *numMatches, char_u ***matches)
{
    char_u  *var = NULL;
    char_u  *buf;

    *numMatches = 0;
    *matches =  (char_u * *)alloc(sizeof(char_u *) * (1)) ;
    if (*matches == NULL)
    {
        return FAIL;
    }

    if (expand_option_idx < 0)
    {
        var = find_termcode(expand_option_name + 2);
        if (var == NULL)
        {
            expand_option_idx = findoption(expand_option_name);
        }
    }

    if (expand_option_idx >= 0)
    {
        option_value2string(&options[expand_option_idx], expand_option_flags);
        var = NameBuff;
    }
    else if (var == NULL)
    {
        var = (char_u *)"";
    }

    buf = escape_option_str_cmdline(var);
    if (buf == NULL)
    {
         vim_free(*matches);
         (*matches) = NULL;
        return FAIL;
    }

    (*matches)[0] = buf;
    *numMatches = 1;
    return OK;
}

    static int
ExpandStringSetting(expand_T    *xp, regmatch_T  *regmatch, int         *numMatches, char_u      ***matches)
{
    char_u  *var = NULL;
    char_u  *buf;

    if (expand_option_idx < 0 || options[expand_option_idx].opt_expand_cb == NULL)
    {
        return FAIL;
    }

    optexpand_T args;
    args.oe_varp = get_varp_scope(&options[expand_option_idx], expand_option_flags);
    args.oe_append = expand_option_append;
    args.oe_regmatch = regmatch;
    args.oe_xp = xp;
    args.oe_set_arg = xp->xp_line + expand_option_start_col;
    args.oe_include_orig_val =
        !expand_option_append &&
        (*args.oe_set_arg == NUL);

    option_value2string(&options[expand_option_idx], expand_option_flags);
    var = NameBuff;
    buf = escape_option_str_cmdline(var);
    if (buf == NULL)
    {
        return FAIL;
    }

    args.oe_opt_value = buf;

    int num_ret = options[expand_option_idx].opt_expand_cb(&args, numMatches, matches);

    vim_free(buf);
    return num_ret;
}

    static int
ExpandSettingSubtract(expand_T    *xp, regmatch_T  *regmatch, int         *numMatches, char_u      ***matches)
{
    if (expand_option_idx < 0)
    {
        return ExpandOldSetting(numMatches, matches);
    }

    char_u *option_val = *(char_u**)get_option_varp_scope(expand_option_idx, expand_option_flags);

    long_u option_flags =  options[expand_option_idx].flags;

    if (option_flags & P_NUM)
    {
        return ExpandOldSetting(numMatches, matches);
    }
    else if (option_flags & P_COMMA)
    {
        garray_T    ga;

        char_u      *item;
        char_u      *option_copy;
        char_u      *next_val;
        char_u      *comma;

        if (*option_val == NUL)
        {
            return FAIL;
        }

        option_copy = vim_strsave(option_val);
        if (option_copy == NULL)
        {
            return FAIL;
        }
        next_val = option_copy;

        ga_init2(&ga, sizeof(char_u *), 10);

        do
        {
            item = next_val;
            comma = vim_strchr(next_val, ',');
            while (comma != NULL && comma != next_val && *(comma - 1) == '\\')
            {
                comma = vim_strchr(comma + 1, ',');
            }
            if (comma != NULL)
            {
                *comma = NUL;
                next_val = comma + 1;
            }
            else
            {
                next_val = NULL;
            }

            if (*item == NUL)
            {
                continue;
            }

            if (!vim_regexec(regmatch, item, (colnr_T)0))
            {
                continue;
            }

            char_u *buf = escape_option_str_cmdline(item);
            if (buf == NULL)
            {
                vim_free(option_copy);
                ga_clear_strings(&ga);
                return FAIL;
            }
            if (ga_add_string(&ga, buf) != OK)
            {
                vim_free(buf);
                break;
            }
        } while (next_val != NULL);

        vim_free(option_copy);

        *matches = ga.ga_data;
        *numMatches = ga.ga_len;
        return OK;
    }
    else if (option_flags & P_FLAGLIST)
    {
        if (*xp->xp_pattern != NUL)
        {
            return FAIL;
        }

        size_t num_flags =  strlen((char *)(option_val)) ;
        if (num_flags == 0)
        {
            return FAIL;
        }

        *matches =  (char_u * *)alloc(sizeof(char_u *) * (num_flags + 1)) ;
        if (*matches == NULL)
        {
            return FAIL;
        }

        int count = 0;
        char_u *p;

        p = vim_strnsave(option_val, num_flags);
        if (p == NULL)
        {
             vim_free(*matches);
             (*matches) = NULL;
            return FAIL;
        }
        (*matches)[count++] = p;

        if (num_flags > 1)
        {
            for (char_u *flag = option_val; *flag != NUL; flag++)
            {
                p = vim_strnsave(flag, 1);
                if (p == NULL)
                {
                    break;
                }
                (*matches)[count++] = p;
            }
        }

        *numMatches = count;
        return OK;
    }

    return ExpandOldSetting(numMatches, matches);
}

    static void
option_value2string(struct vimoption    *opp, int                 scope)
{
    char_u      *varp;

    varp = get_varp_scope(opp, scope);

    if (opp->flags & P_NUM)
    {
        long wc = 0;

        if (wc_use_keyname(varp, &wc))
        {
             strcpy((char *)(NameBuff), (char *)(get_special_key_name((int)wc, 0))) ;
        }
        else if (wc != 0)
        {
             strcpy((char *)(NameBuff), (char *)(transchar((int)wc))) ;
        }
        else
        {
            sprintf((char *)NameBuff, "%ld", *(long *)varp);
        }
    }
    else
    {
        varp = *(char_u **)(varp);
        if (varp == NULL)
        {
            NameBuff[0] = NUL;
        }
        else if (opp->flags & P_EXPAND)
        {
            home_replace(NULL, varp, NameBuff,  PATH_MAX , FALSE);
        }
        else if ((char_u **)opp->var == &p_pt)
        {
            str2specialbuf(p_pt, NameBuff,  PATH_MAX );
        }
        else
        {
            vim_strncpy(NameBuff, varp,  PATH_MAX  - 1);
        }
    }
}

    static int
wc_use_keyname(char_u *varp, long *wcp)
{
    if (((long *)varp == &p_wc) || ((long *)varp == &p_wcm))
    {
        *wcp = *(long *)varp;
        if ( ((*wcp) < 0)  || find_special_key_in_table((int)*wcp) >= 0)
        {
            return TRUE;
        }
    }
    return FALSE;
}

    static int
shortmess(int x)
{
    return p_shm != NULL &&
            (   vim_strchr(p_shm, x) != NULL || (vim_strchr(p_shm, 'a') != NULL && vim_strchr((char_u *) "rmfixlnw" , x) != NULL));
}

    static void
vimrc_found(char_u *fname, char_u *envname)
{
    int         opt_idx;
    int         dofree = FALSE;
    char_u      *p;

    if (!option_was_set((char_u *)"cp"))
    {
        p_cp = FALSE;
        for (opt_idx = 0; !istermoption_idx(opt_idx); opt_idx++)
        {
            if (!(options[opt_idx].flags & (P_WAS_SET|P_VI_DEF)))
            {
                set_option_default(opt_idx, OPT_FREE, FALSE);
            }
        }
        didset_options();
        didset_options2();
    }

    if (fname != NULL)
    {
        p = vim_getenv(envname, &dofree);
        if (p == NULL)
        {
            p = FullName_save(fname, FALSE);
            if (p != NULL)
            {
                vim_setenv(envname, p);
                vim_free(p);
            }
            export_myvimdir();
        }
        else if (dofree)
        {
            vim_free(p);
        }
    }
}

    static void
change_compatible(int on)
{
    int     opt_idx;

    if (p_cp != on)
    {
        p_cp = on;
        compatible_set();
    }
    opt_idx = findoption((char_u *)"cp");
    if (opt_idx >= 0)
    {
        options[opt_idx].flags |= P_WAS_SET;
    }
}

    static int
option_was_set(char_u *name)
{
    int idx;

    idx = findoption(name);
    if (idx < 0)
    {
        return FALSE;
    }
    if (options[idx].flags & P_WAS_SET)
    {
        return TRUE;
    }
    return FALSE;
}

    static int
reset_option_was_set(char_u *name)
{
    int idx = findoption(name);

    if (idx < 0)
    {
        return FAIL;
    }

    options[idx].flags &= ~P_WAS_SET;
    return OK;
}

    static void
compatible_set(void)
{
    int     opt_idx;

    for (opt_idx = 0; !istermoption_idx(opt_idx); opt_idx++)
    {
        if (       ((options[opt_idx].flags & P_VIM) && p_cp) || (!(options[opt_idx].flags & P_VI_DEF) && !p_cp))
        {
            set_option_default(opt_idx, OPT_FREE, p_cp);
        }
    }
    didset_options();
    didset_options2();
}

    static int
can_bs(int         what)
{
    switch (*p_bs)
    {
        case '3':
            return TRUE;
        case '2':
            return (what != BS_NOSTOP);
        case '1':
            return (what != BS_START);
        case '0':
            return FALSE;
    }
    return vim_strchr(p_bs, what) != NULL;
}

