    static void
free_string_option(char_u *p)
{
    if (p != empty_option)
    {
        vim_free(p);
    }
}

    static void
clear_string_option(char_u **pp)
{
    if (*pp != empty_option)
    {
        vim_free(*pp);
    }
    *pp = empty_option;
}

    static void
check_string_option(char_u **pp)
{
    if (*pp == NULL)
    {
        *pp = empty_option;
    }
}

    static void
set_string_option_global(int         opt_idx, char_u      **varp)
{
    char_u **p;
    char_u *s;

    if (is_window_local_option(opt_idx))
    {
        p = (char_u **) ((char *)(varp) + sizeof(winopt_T)) ;
    }
    else
    {
        p = (char_u **)get_option_var(opt_idx);
    }
    if (!is_global_option(opt_idx) && p != varp && (s = vim_strsave(*varp)) != NULL)
    {
        free_string_option(*p);
        *p = s;
    }
}

    static void
set_string_option_direct(char_u      *name, int         opt_idx, char_u      *val, int         opt_flags, int         set_sid  __attribute__((unused)) )
{
    char_u      *s;
    char_u      **varp;
    int         both = (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0;
    int         idx = opt_idx;

    if (idx == -1)
    {
        idx = findoption(name);
        if (idx < 0)
        {
            semsg(_(e_internal_error_str), "set_string_option_direct()");
            siemsg("For option %s", name);
            return;
        }
    }

    if (is_hidden_option(idx))
    {
        return;
    }

    s = vim_strsave(val);
    if (s == NULL)
    {
        return;
    }

    varp = (char_u **)get_option_varp_scope(idx, both ? OPT_LOCAL : opt_flags);
    if ((opt_flags & OPT_FREE) && (get_option_flags(idx) & P_ALLOCED))
    {
        free_string_option(*varp);
    }
    *varp = s;

    if (both)
    {
        set_string_option_global(idx, varp);
    }

    set_option_flag(idx, P_ALLOCED);

    if (is_global_local_option(idx) && both)
    {
        free_string_option(*varp);
        *varp = empty_option;
    }
}

    static void
set_string_option_direct_in_win(win_T           *wp, char_u          *name, int             opt_idx, char_u          *val, int             opt_flags, int             set_sid)
{
    win_T       *save_curwin = curwin;

    block_autocmds();
    curwin = wp;
    curbuf = curwin->w_buffer;
    set_string_option_direct(name, opt_idx, val, opt_flags, set_sid);
    curwin = save_curwin;
    curbuf = curwin->w_buffer;
    unblock_autocmds();
}

    static char *
set_string_option(int         opt_idx, char_u      *value, int         opt_flags, char        *errbuf, size_t      errbuflen)
{
    char_u      *s;
    char_u      **varp;
    char_u      *oldval;
    char        *errmsg = NULL;
    int         value_checked = FALSE;

    if (is_hidden_option(opt_idx))
    {
        return NULL;
    }

    s = vim_strsave(value == NULL ? (char_u *)"" : value);
    if (s == NULL)
    {
        return NULL;
    }

    varp = (char_u **)get_option_varp_scope(opt_idx, (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0 ? (is_global_local_option(opt_idx) ? OPT_GLOBAL : OPT_LOCAL) : opt_flags);
    oldval = *varp;
    *varp = s;

    if ((errmsg = did_set_string_option(opt_idx, varp, oldval, value, errbuf, errbuflen, opt_flags, OP_NONE, &value_checked)) == NULL)
    {
        did_set_option(opt_idx, opt_flags, TRUE, value_checked);
    }

    return errmsg;
}

