    static char *
did_set_comments(optset_T *args)
{
    char_u      **varp = (char_u **)args->os_varp;
    char_u      *s;
    char        *errmsg = NULL;

    for (s = *varp; *s; )
    {
        while (*s && *s != ':')
        {
            if (vim_strchr((char_u *) "nbsmexflrO" , *s) == NULL && ! ((unsigned)(*s) - '0' < 10)  && *s != '-')
            {
                errmsg = illegal_char(args->os_errbuf, args->os_errbuflen, *s);
                break;
            }
            ++s;
        }
        if (*s++ == NUL)
        {
            errmsg = e_missing_colon;
        }
        else if (*s == ',' || *s == NUL)
        {
            errmsg = e_zero_length_string;
        }
        if (errmsg != NULL)
        {
            break;
        }
        while (*s && *s != ',')
        {
            if (*s == '\\' && s[1] != NUL)
            {
                ++s;
            }
            ++s;
        }
        s = skip_to_option_part(s);
    }

    return errmsg;
}

    static char *
did_set_commentstring(optset_T *args)
{
    char_u      **varp = (char_u **)args->os_varp;

    if (**varp != NUL && strstr((char *)*varp, "%s") == NULL)
    {
        return e_commentstring_must_be_empty_or_contain_str;
    }

    return NULL;
}

    static char *
did_set_complete(optset_T *args)
{
    char_u      **varp = (char_u **)args->os_varp;
    char_u *p;
    char_u *t;
    char_u      buffer[LSIZE];
    char_u      *buf_ptr;
    char_u      char_before = NUL;
    int         escape;

    for (p = *varp; *p; )
    {
         memset((buffer), (0), (LSIZE)) ;
        buf_ptr = buffer;
        escape = 0;

        while (*p && (*p != ',' || escape) && buf_ptr < (buffer + LSIZE - 1))
        {
            if (*p == '\\' && *(p + 1) == ',')
            {
                escape = 1;
                p++;
            }
            else
            {
                escape = 0;
                *buf_ptr++ = *p;
            }
            p++;
        }
        *buf_ptr = NUL;

        if (vim_strchr((char_u *)".wbuksid]tUFo", *buffer) == NULL)
        {
            return illegal_char(args->os_errbuf, args->os_errbuflen, *buffer);
        }

        if (vim_strchr((char_u *)"ksF", *buffer) == NULL && *(buffer + 1) != NUL && *(buffer + 1) != '^')
        {
            char_before = *buffer;
        }
        else
        {
            if ((t = vim_strchr(buffer, '^')) != NULL)
            {
                *t++ = NUL;
                if (!*t)
                {
                    char_before = '^';
                }
                else
                {
                    for (; *t; t++)
                    {
                        if (!vim_isdigit(*t))
                        {
                            char_before = '^';
                            break;
                        }
                    }
                }
            }
        }
        if (char_before != NUL)
        {
            return illegal_char_after_chr(args->os_errbuf, args->os_errbuflen, char_before);
        }
        while (*p == ',' || *p == ' ')
        {
            p++;
        }
    }

    return NULL;
}

