    static char *
did_set_matchpairs(optset_T *args)
{
    char_u      **varp = (char_u **)args->os_varp;
    char_u      *p;

    if (has_mbyte)
    {
        for (p = *varp; *p != NUL; ++p)
        {
            int x2 = -1;
            int x3 = -1;

            p += mb_ptr2len(p);
            if (*p != NUL)
            {
                x2 = *p++;
            }
            if (*p != NUL)
            {
                x3 = mb_ptr2char(p);
                p += mb_ptr2len(p);
            }
            if (x2 != ':' || x3 == -1 || (*p != NUL && *p != ','))
            {
                return e_invalid_argument;
            }
            if (*p == NUL)
            {
                break;
            }
        }
    }
    else
    {
        for (p = *varp; *p != NUL; p += 4)
        {
            if (p[1] != ':' || p[2] == NUL || (p[3] != NUL && p[3] != ','))
            {
                return e_invalid_argument;
            }
            if (p[3] == NUL)
            {
                break;
            }
        }
    }

    return NULL;
}

