    static char *
did_set_term_option(optset_T *args)
{
    char_u      **varp = (char_u **)args->os_varp;

    if (!full_screen)
    {
        return NULL;
    }

    if (varp == & ( term_strings[(int)(KS_CCO)] ) )
    {
        int colors = atoi((char *) ( term_strings[(int)(KS_CCO)] ) );

        if (colors != t_colors)
        {
            t_colors = colors;
            if (t_colors <= 1)
            {
                vim_free( ( term_strings[(int)(KS_CCO)] ) );
                 ( term_strings[(int)(KS_CCO)] )  = empty_option;
            }
            init_highlight(TRUE, FALSE);
        }
    }
    ttest(FALSE);
    if (varp == & ( term_strings[(int)(KS_ME)] ) )
    {
        out_str( ( term_strings[(int)(KS_ME)] ) );
        redraw_later(UPD_CLEAR);
    }
    if (varp == & ( term_strings[(int)(KS_CBE)] )  && termcap_active)
    {
          ;

        if (* ( term_strings[(int)(KS_CBE)] )  == NUL)
        {
            out_str( ( term_strings[(int)(KS_CBD)] ) );
        }
        else
        {
            out_str( ( term_strings[(int)(KS_CBE)] ) );
        }
    }

    if (varp == & ( term_strings[(int)(KS_BSU)] )  || varp == & ( term_strings[(int)(KS_ESU)] ) )
    {
        term_set_sync_output(TERM_SYNC_OUTPUT_OFF);
    }

    return NULL;
}

