    static long_u
mch_total_mem(int special  __attribute__((unused)) )
{
    long_u      mem = 0;
    long_u      shiftright = 10;

    if (mem == 0)
    {
        struct sysinfo sinfo;

        if (sysinfo(&sinfo) == 0)
        {
            while (shiftright > 0 && (sinfo.mem_unit & 1) == 0)
            {
                sinfo.mem_unit = sinfo.mem_unit >> 1;
                --shiftright;
            }
            mem = sinfo.totalram * sinfo.mem_unit;
        }
    }

    if (mem == 0)
    {
        long pagesize;
        long pagecount;

        pagesize = sysconf(_SC_PAGESIZE);
        pagecount = sysconf(_SC_PHYS_PAGES);
        if (pagesize > 0 && pagecount > 0)
        {
            while (shiftright > 0 && (pagesize & 1) == 0)
            {
                pagesize = (long_u)pagesize >> 1;
                --shiftright;
            }
            mem = (long_u)pagesize * pagecount;
        }
    }

    {
        struct rlimit   rlp;

        if (getrlimit(RLIMIT_DATA, &rlp) == 0 && rlp.rlim_cur < ((rlim_t)1 << (sizeof(long_u) * 8 - 1)) && rlp.rlim_cur != RLIM_INFINITY && ((long_u)rlp.rlim_cur >> 10) < (mem >> shiftright))
        {
            mem = (long_u)rlp.rlim_cur;
            shiftright = 10;
        }
    }

    if (mem > 0)
    {
        return mem >> shiftright;
    }
    return (long_u)0x1fffff;
}

    static void
mch_delay(long msec, int flags)
{
    tmode_T     old_tmode;
    int         call_settmode;

    if (flags & MCH_DELAY_IGNOREINPUT)
    {
        in_mch_delay = TRUE;
        call_settmode = mch_cur_tmode == TMODE_RAW
                               && (msec > 500 || (flags & MCH_DELAY_SETTMODE));
        if (call_settmode)
        {
            old_tmode = mch_cur_tmode;
            settmode(TMODE_SLEEP);
        }

        {
            struct timespec ts;

            ts.tv_sec = msec / 1000;
            ts.tv_nsec = (msec % 1000) * 1000000;
            (void)nanosleep(&ts, NULL);
        }

        if (call_settmode)
        {
            settmode(old_tmode);
        }
        in_mch_delay = FALSE;
    }
    else
    {
        WaitForChar(msec, NULL, FALSE);
    }
}

static stack_t sigstk;

static long int get_signal_stack_size(void)
{
    long int size = -1;

    if ((size = sysconf(_SC_SIGSTKSZ)) > -1)
    {
        return size;
    }

    return SIGSTKSZ;

    return 8000;
}

static char *signal_stack;

    static void
init_signal_stack(void)
{
    if (signal_stack == NULL)
    {
        return;
    }

    sigstk.ss_sp = signal_stack;
    sigstk.ss_size = get_signal_stack_size();
    sigstk.ss_flags = 0;
    (void)sigaltstack(&sigstk, NULL);
}

    static void
sig_winch  (int sigarg  __attribute__((unused)) ) 
{
    mch_signal(SIGWINCH, sig_winch);
    do_resize = TRUE;
}

    static void
sig_tstp  (int sigarg  __attribute__((unused)) ) 
{
    if (in_mch_suspend)
    {
        mch_signal(SIGTSTP, ignore_sigtstp ? SIG_IGN : SIG_DFL);
        raise(sigarg);
    }
    else
    {
        got_tstp = TRUE;
    }

    mch_signal(SIGTSTP, sig_tstp);
}

    static void
catch_sigint  (int sigarg  __attribute__((unused)) ) 
{
    mch_signal(SIGINT, catch_sigint);
    got_int = TRUE;
}

    static void
catch_sigusr1  (int sigarg  __attribute__((unused)) ) 
{
    mch_signal(SIGUSR1, catch_sigusr1);
    got_sigusr1 = TRUE;
}

    static void
catch_sigpwr  (int sigarg  __attribute__((unused)) ) 
{
    mch_signal(SIGPWR, catch_sigpwr);
    ml_sync_all(FALSE, FALSE);
}

    static void
deathtrap  (int sigarg  __attribute__((unused)) ) 
{
    static int  entered = 0;
    int         i;

    if (in_mch_delay && sigarg == SIGQUIT)
    {
        return;
    }

    if (entered == 0 && (0 || sigarg == SIGHUP || sigarg == SIGQUIT || sigarg == SIGTERM || sigarg == SIGPWR || sigarg == SIGUSR1 || sigarg == SIGUSR2) && !vim_handle_signal(sigarg))
    {
        return;
    }

    ++entered;

    block_autocmds();

    v_dying = entered;

    for (i = 0; signal_info[i].sig != -1; i++)
    {
        if (sigarg == signal_info[i].sig)
        {
            break;
        }
    }
    deadly_signal = sigarg;

    full_screen = FALSE;
    if (entered >= 3)
    {
        reset_signals();
        may_core_dump();
        if (entered >= 4)
        {
            _exit(8);
        }
        exit(7);
    }
    if (entered == 2)
    {
         out_str((char_u *)("Vim: Double signal, exiting\n")) ;
        out_flush();
        getout(1);
    }

    sprintf((char *)IObuff, "Vim: Caught deadly signal %s\r\n", signal_info[i].name);

    preserve_exit();

}

    static void
after_sigcont(void)
{
    oldtitle_outdated = TRUE;

    settmode(TMODE_RAW);
    need_check_timestamps = TRUE;
    did_check_timestamps = FALSE;
}

static void sigcont_handler  (int) ;

static volatile sig_atomic_t sigcont_received;
static void sigcont_handler  (int) ;

    static void
sigcont_handler  (int sigarg  __attribute__((unused)) ) 
{
    if (in_mch_suspend)
    {
        sigcont_received = TRUE;
    }
    else
    {
        after_sigcont();
        redraw_later(UPD_CLEAR);
        cursor_on_force();
        out_flush();
    }
}

    static void
mch_suspend(void)
{
    if (ignore_sigtstp)
    {
        return;
    }

    in_mch_suspend = TRUE;

    out_flush();
    settmode(TMODE_COOK);
    out_flush();

    sigcont_received = FALSE;

    kill(0, SIGTSTP);

    {
        long wait_time;

        for (wait_time = 0; !sigcont_received && wait_time <= 3L; wait_time++)
        {
            mch_delay(wait_time, 0);
        }
    }
    in_mch_suspend = FALSE;

    after_sigcont();
}

