    static void
set_signals(void)
{
    mch_signal(SIGWINCH, sig_winch);

    mch_signal(SIGTSTP, ignore_sigtstp ? SIG_IGN : sig_tstp);
    mch_signal(SIGCONT, sigcont_handler);
    mch_signal(SIGPIPE, SIG_IGN);

    catch_int_signal();

    mch_signal(SIGUSR1, catch_sigusr1);

    mch_signal(SIGALRM, SIG_IGN);

    mch_signal(SIGPWR, catch_sigpwr);

    catch_signals(deathtrap, SIG_ERR);

}

    static void
catch_int_signal(void)
{
    mch_signal(SIGINT, catch_sigint);
}

    static void
reset_signals(void)
{
    catch_signals(SIG_DFL, SIG_DFL);
    mch_signal(SIGCONT, SIG_DFL);
}

    static void
catch_signals(void (*func_deadly)(int), void (*func_other)(int))
{
    int     i;

    for (i = 0; signal_info[i].sig != -1; i++)
    {
        if (signal_info[i].deadly)
        {
            struct sigaction sa;

            sa.sa_handler = func_deadly;
            sigemptyset(&sa.sa_mask);
            sa.sa_flags = SA_ONSTACK;
            sigaction(signal_info[i].sig, &sa, NULL);
        }
        else if (func_other != SIG_ERR)
        {
            mch_signal(signal_info[i].sig, signal_info[i].sig == SIGTSTP && ignore_sigtstp ? SIG_IGN : func_other);
        }
    }
}

    static int
vim_handle_signal(int sig)
{
    static int got_signal = 0;
    static int blocked = TRUE;

    switch (sig)
    {
        case  (-1) :
            blocked = TRUE;
                             break;

        case  (-2) :
            blocked = FALSE;
                             if (got_signal != 0)
                             {
                                 kill(getpid(), got_signal);
                                 got_signal = 0;
                             }
                             break;

        default:
            if (!blocked)
            {
                                 return TRUE;
            }
                             got_signal = sig;
                             if (sig != SIGPWR)
                             {
                                 got_int = TRUE;
                             }
                             break;
    }
    return FALSE;
}

