    static void
mch_settitle(char_u *title, char_u *icon)
{
    int         type = 0;
    static int  recursive = 0;

    if ( ( term_strings[(int)(KS_NAME)] )  == NULL)
    {
        return;
    }
    if (title == NULL && icon == NULL)
    {
        return;
    }

    if (recursive)
    {
        return;
    }
    ++recursive;

    if ((type || * ( term_strings[(int)(KS_TS)] )  != NUL) && title != NULL)
    {
        if (oldtitle_outdated)
        {
            oldtitle_outdated = FALSE;
             vim_free(oldtitle);
             (oldtitle) = NULL;
        }
        if (oldtitle == NULL)
        {
            (void)get_x11_title(FALSE);
        }

        if (* ( term_strings[(int)(KS_TS)] )  != NUL)
        {
            term_settitle(title);
        }
        unix_did_set_title = TRUE;
    }

    if ((type || * ( term_strings[(int)(KS_CIS)] )  != NUL) && icon != NULL)
    {
        if (oldicon == NULL)
        {
            get_x11_icon(FALSE);
        }

        if (* ( term_strings[(int)(KS_CIS)] )  != NUL)
        {
            out_str( ( term_strings[(int)(KS_CIS)] ) );
            out_str_nf(icon);
            out_str( ( term_strings[(int)(KS_CIE)] ) );
            out_flush();
        }
        did_set_icon = TRUE;
    }
    --recursive;
}

    static void
mch_restore_title(int which)
{
    int do_push_pop = unix_did_set_title || did_set_icon;

    char_u *title = ((which & SAVE_RESTORE_TITLE) && unix_did_set_title)
                        ? (oldtitle ? oldtitle : p_titleold) : NULL;
    char_u *tofree = NULL;
    if (title == oldtitle && oldtitle != NULL)
    {
        tofree = vim_strsave(title);
        if (tofree != NULL)
        {
            title = tofree;
        }
    }
    mch_settitle(title, ((which & SAVE_RESTORE_ICON) && did_set_icon) ? oldicon : NULL);
    vim_free(tofree);

    if (do_push_pop)
    {
        term_pop_title(which);
        term_push_title(which);
    }
}

    static int
vim_is_xterm(char_u *name)
{
    if (name == NULL)
    {
        return FALSE;
    }
    return (( strncasecmp((char *)(name), (char *)("xterm"), (5))  == 0 &&  strncasecmp((char *)(name), (char *)("xterm-kitty"), (11))  != 0) ||  strncasecmp((char *)(name), (char *)("nxterm"), (6))  == 0 ||  strncasecmp((char *)(name), (char *)("kterm"), (5))  == 0 ||  strncasecmp((char *)(name), (char *)("mlterm"), (6))  == 0 ||  strncasecmp((char *)(name), (char *)("rxvt"), (4))  == 0 ||  strncasecmp((char *)(name), (char *)("screen.xterm"), (12))  == 0 ||  strcmp((char *)(name), (char *)("builtin_xterm"))  == 0);
}

    static int
use_xterm_like_mouse(char_u *name)
{
    return (name != NULL && (term_is_xterm ||  strncasecmp((char *)(name), (char *)("screen"), (6))  == 0 ||  strncasecmp((char *)(name), (char *)("tmux"), (4))  == 0 ||  strncasecmp((char *)(name), (char *)("gnome"), (5))  == 0 ||  strcasecmp((char *)(name), (char *)("st"))  == 0 ||  strncasecmp((char *)(name), (char *)("st-"), (3))  == 0 ||  strncasecmp((char *)(name), (char *)("stterm"), (6))  == 0));
}

    static int
use_xterm_mouse(void)
{
    if (ttym_flags == TTYM_SGR)
    {
        return 4;
    }
    if (ttym_flags == TTYM_URXVT)
    {
        return 3;
    }
    if (ttym_flags == TTYM_XTERM2)
    {
        return 2;
    }
    if (ttym_flags == TTYM_XTERM)
    {
        return 1;
    }
    return 0;
}

    static int
mch_get_user_name(char_u *s, int len)
{
    return mch_get_uname(getuid(), s, len);
}

    static int
mch_get_uname(uid_t uid, char_u *s, int len)
{
    struct passwd   *pw;

    if ((pw = getpwuid(uid)) != NULL && pw->pw_name != NULL && *(pw->pw_name) != NUL)
    {
        vim_strncpy(s, (char_u *)pw->pw_name, len - 1);
        return OK;
    }
    sprintf((char *)s, "%d", (int)uid);
    return FAIL;
}

