    static void
exit_scroll(void)
{
    if (silent_mode)
    {
        return;
    }
    if (newline_on_exit || msg_didout)
    {
        if (msg_use_printf())
        {
            if (info_message)
            {
                 printf("%s", ("\n")) ;
            }
            else
            {
                 fprintf(stderr, "%s", ("\r\n")) ;
            }
        }
        else
        {
            out_char('\n');
        }
    }
    else if (!is_not_a_term())
    {
        restore_cterm_colors();
        msg_clr_eos_force();
        windgoto((int)Rows - 1, cmdline_col_off);
    }
}

    static void
mch_exit(int r)
{
    exiting = TRUE;

    {
        settmode(TMODE_COOK);
        if (!is_not_a_term())
        {
            mch_restore_title( (SAVE_RESTORE_TITLE | SAVE_RESTORE_ICON) );
            term_pop_title( (SAVE_RESTORE_TITLE | SAVE_RESTORE_ICON) );
        }

        if (swapping_screen() && !newline_on_exit)
        {
            exit_scroll();
        }

        stoptermcap();

        if (!swapping_screen() || newline_on_exit)
        {
            exit_scroll();
        }

        if (full_screen)
        {
            cursor_on();
        }
    }
    out_flush();
    ml_close_all(TRUE);

    may_core_dump();

    exit(r);
}

    static void
may_core_dump(void)
{
    if (deadly_signal != 0)
    {
        mch_signal(deadly_signal, SIG_DFL);
        kill(getpid(), deadly_signal);
    }
}

    static int
get_tty_fd(int fd)
{
    int         tty_fd = fd;

    return tty_fd;
}

    static int
mch_tcgetattr(int fd, void *term)
{
    int         tty_fd;
    int         retval = -1;

    tty_fd = get_tty_fd(fd);
    if (tty_fd < 0)
    {
        return -1;
    }

    retval = tcgetattr(tty_fd, (struct termios *)term);
    if (tty_fd != fd)
    {
        close(tty_fd);
    }
    return retval;
}

    static void
mch_settmode(tmode_T tmode)
{
    static int first = TRUE;

    static struct termios told;
           struct termios tnew;

    if (first)
    {
        first = FALSE;
        mch_tcgetattr(read_cmd_fd, &told);
    }

    tnew = told;
    if (tmode == TMODE_RAW)
    {
        tnew.c_iflag &= ~(ICRNL | ( ( term_strings[(int)(KS_XON)] )  == NULL || * ( term_strings[(int)(KS_XON)] )  == NUL ? IXON : 0));
        tnew.c_lflag &= ~(ICANON | ECHO | ISIG | ECHOE | IEXTEN);
        tnew.c_oflag &= ~(ONLCR | XTABS);
        tnew.c_cc[VMIN] = 1;
        tnew.c_cc[VTIME] = 0;
    }
    else if (tmode == TMODE_SLEEP)
    {
        tnew.c_lflag &= ~(ICANON | ECHO);
        tnew.c_cc[VMIN] = 1;
        tnew.c_cc[VTIME] = 0;
    }

    {
        int     n = 10;

        while (tcsetattr(read_cmd_fd, TCSANOW, &tnew) == -1 && errno == EINTR && n > 0)
        {
            --n;
        }
    }

    mch_cur_tmode = tmode;
}

    static void
get_stty(void)
{
    ttyinfo_T   info;
    char_u      buf[2];
    char_u      *p;

    if (get_tty_info(read_cmd_fd, &info) != OK)
    {
        return;
    }

    intr_char = info.interrupt;
    buf[0] = info.backspace;
    buf[1] = NUL;
    add_termcode((char_u *)"kb", buf, FALSE);

    p = find_termcode((char_u *)"kD");
    if (p != NULL && p[0] == buf[0] && p[1] == buf[1])
    {
        do_fixdel(NULL);
    }
}

    static int
get_tty_info(int fd, ttyinfo_T *info)
{
    struct termios keys;

    if (mch_tcgetattr(fd, &keys) != -1)
    {
        info->backspace = keys.c_cc[VERASE];
        info->interrupt = keys.c_cc[VINTR];
        if (keys.c_iflag & ICRNL)
        {
            info->enter = NL;
        }
        else
        {
            info->enter = CAR;
        }
        if (keys.c_oflag & ONLCR)
        {
            info->nl_does_cr = TRUE;
        }
        else
        {
            info->nl_does_cr = FALSE;
        }
        return OK;
    }
    return FAIL;
}

static int      mouse_ison = FALSE;

    static void
mch_setmouse(int on)
{
    int         xterm_mouse_vers;

    if (on == mouse_ison)
    {
        return;
    }

    xterm_mouse_vers = use_xterm_mouse();

    if ( ( term_strings[(int)(KS_CXM)] )  != NULL && * ( term_strings[(int)(KS_CXM)] )  != NUL)
    {
        term_enable_mouse(on);
    }
    else if (ttym_flags == TTYM_SGR)
    {
        out_str_nf((char_u *)(on ? "\033[?1006h" : "\033[?1006l"));
        mouse_ison = on;
    }

    if (xterm_mouse_vers > 0)
    {
        if (on)
        {
            out_str_nf((char_u *) (xterm_mouse_vers > 1 ? ("\033[?1002h") : "\033[?1000h"));
        }
        else
        {
            out_str_nf((char_u *) (xterm_mouse_vers > 1 ? "\033[?1002l" : "\033[?1000l"));
        }
        mouse_ison = on;
    }

}

    static void
check_mouse_termcode(void)
{
    if (use_xterm_mouse())
    {
        set_mouse_termcode(KS_MOUSE, (char_u *)(term_is_8bit( ( term_strings[(int)(KS_NAME)] ) ) ? "\233M" : "\033[M"));
        if (*p_mouse != NUL)
        {
            mch_setmouse(FALSE);
            setmouse();
        }
    }
    else
    {
        del_mouse_termcode(KS_MOUSE);
    }

    if (use_xterm_mouse() == 4)
    {
        set_mouse_termcode(KS_SGR_MOUSE, (char_u *)(term_is_8bit( ( term_strings[(int)(KS_NAME)] ) ) ? "\233<*M" : "\033[<*M"));

        set_mouse_termcode(KS_SGR_MOUSE_RELEASE, (char_u *)(term_is_8bit( ( term_strings[(int)(KS_NAME)] ) ) ? "\233<*m" : "\033[<*m"));

        if (*p_mouse != NUL)
        {
            mch_setmouse(FALSE);
            setmouse();
        }
    }
    else
    {
        del_mouse_termcode(KS_SGR_MOUSE);
        del_mouse_termcode(KS_SGR_MOUSE_RELEASE);
    }
}

    static int
mch_get_shellsize(void)
{
    long        rows = 0;
    long        columns = 0;

    {
        struct winsize  ws;
        int fd = 1;

        if (!isatty(fd) && isatty(read_cmd_fd))
        {
            fd = read_cmd_fd;
        }
        if (ioctl(fd, TIOCGWINSZ, &ws) == 0)
        {
            columns = ws.ws_col;
            rows = ws.ws_row;
        }
    }

    if (columns <= 0 || rows <= 0)
    {
        return FAIL;
    }

    Rows = rows;
    Columns = columns;
    limit_screen_size();
    return OK;
}

