    static int
WaitForChar(long msec, int *interrupted, int ignore_input)
{
    return WaitForCharOrMouse(msec, interrupted, ignore_input);
}

    static int
WaitForCharOrMouse(long msec, int *interrupted, int ignore_input)
{
    int         avail;

    if (!ignore_input && input_available())
    {
        return 1;
    }

    avail = RealWaitForChar(read_cmd_fd, msec, NULL, interrupted);
    return avail;
}

    static int
RealWaitForChar(int fd, long msec, int *check_for_gpm  __attribute__((unused)) , int *interrupted)
{
    int         ret;
    int         result;

    {
        struct timeval  tv;
        struct timeval  *tvp;
        static fd_set rfds;
        static fd_set wfds;
        static fd_set efds;
        int             maxfd;
        long            towait = msec;

        if (towait >= 0)
        {
            tv.tv_sec = towait / 1000;
            tv.tv_usec = (towait % 1000) * (1000000/1000);
            tvp = &tv;
        }
        else
        {
            tvp = NULL;
        }

select_eintr:
        FD_ZERO(&rfds);
        FD_ZERO(&wfds);
        FD_ZERO(&efds);
        FD_SET(fd, &rfds);
        FD_SET(fd, &efds);
        maxfd = fd;

        if (interrupted != NULL)
        {
            *interrupted = FALSE;
        }

        ret = select(maxfd + 1,  (fd_set *)  &rfds,  (fd_set *)  &wfds,  (fd_set *)  &efds, tvp);
        result = ret > 0 && FD_ISSET(fd, &rfds);
        if (result)
        {
            --ret;
        }
        else if (interrupted != NULL && ret > 0)
        {
            *interrupted = TRUE;
        }

        if (ret == -1 && errno == EINTR)
        {
            if (got_tstp && !in_mch_suspend)
            {
                exarg_T ea;

                ea.forceit = TRUE;
                ex_stop(&ea);
                got_tstp = FALSE;
            }

            if (do_resize)
            {
                handle_resize();
            }

            goto select_eintr;
        }

    }

    return result;
}

    static int
save_patterns(int         num_pat, char_u      **pat, int         *num_file, char_u      ***file)
{
    int         i;
    char_u      *s;

    *file =  (char_u * *)alloc(sizeof(char_u *) * (num_pat)) ;
    if (*file == NULL)
    {
        return FAIL;
    }
    for (i = 0; i < num_pat; i++)
    {
        s = vim_strsave(pat[i]);
        if (s != NULL)
        {
            backslash_halve(s);
        }
        (*file)[i] = s;
    }
    *num_file = num_pat;
    return OK;
}

    static int
mch_has_wildcard(char_u *p)
{
    for ( ; *p;  p += (*mb_ptr2len)(p) )
    {
        if (*p == '\\' && p[1] != NUL)
        {
            ++p;
        }
        else
        {
            if (vim_strchr((char_u *) "*?[{`'$", *p) != NULL || (*p == '~' && p[1] != NUL))
            {
            return TRUE;
            }
        }
    }
    return FALSE;
}

