    static int
no_Magic(int x)
{
    if ( ((x) < 0) )
    {
        return  ((x) + 256) ;
    }
    return x;
}

    static int
toggle_Magic(int x)
{
    if ( ((x) < 0) )
    {
        return  ((x) + 256) ;
    }
    return  ((int)(x) - 256) ;
}

