    static int
get_equi_class(char_u **pp)
{
    int         c;
    int         l = 1;
    char_u      *p = *pp;

    if (p[1] == '=' && p[2] != NUL)
    {
        if (has_mbyte)
        {
            l = (*mb_ptr2len)(p + 2);
        }
        if (p[l + 2] == '=' && p[l + 3] == ']')
        {
            if (has_mbyte)
            {
                c = mb_ptr2char(p + 2);
            }
            else
            {
                c = p[2];
            }
            *pp += l + 4;
            return c;
        }
    }
    return 0;
}

    static int
get_coll_element(char_u **pp)
{
    int         c;
    int         l = 1;
    char_u      *p = *pp;

    if (p[0] != NUL && p[1] == '.' && p[2] != NUL)
    {
        if (has_mbyte)
        {
            l = (*mb_ptr2len)(p + 2);
        }
        if (p[l + 2] == '.' && p[l + 3] == ']')
        {
            if (has_mbyte)
            {
                c = mb_ptr2char(p + 2);
            }
            else
            {
                c = p[2];
            }
            *pp += l + 4;
            return c;
        }
    }
    return 0;
}

static int reg_cpo_lit;
static int reg_cpo_bsl;

    static void
get_cpo_flags(void)
{
    reg_cpo_lit = vim_strchr(p_cpo, CPO_LITERAL) != NULL;
    reg_cpo_bsl = vim_strchr(p_cpo, CPO_BACKSL) != NULL;
}

    static char_u *
skip_anyof(char_u *p)
{
    int         l;

    if (*p == '^')
    {
        ++p;
    }
    if (*p == ']' || *p == '-')
    {
        ++p;
    }
    while (*p != NUL && *p != ']')
    {
        if (has_mbyte && (l = (*mb_ptr2len)(p)) > 1)
        {
            p += l;
        }
        else
        {
            if (*p == '-')
            {
                ++p;
                if (*p != ']' && *p != NUL)
                {
                     p += (*mb_ptr2len)(p) ;
                }
            }
        else if (*p == '\\' && !reg_cpo_bsl && (vim_strchr(REGEXP_INRANGE, p[1]) != NULL || (!reg_cpo_lit && vim_strchr(REGEXP_ABBR, p[1]) != NULL)))
        {
            p += 2;
        }
        else if (*p == '[')
        {
            if (get_char_class(&p) == CLASS_NONE && get_equi_class(&p) == 0 && get_coll_element(&p) == 0 && *p != NUL)
            {
                ++p;
            }
        }
        else
        {
            ++p;
        }
        }
    }

    return p;
}

    static char_u *
skip_regexp(char_u      *startp, int         delim, int         magic)
{
    return skip_regexp_ex(startp, delim, magic, NULL, NULL, NULL);
}

    static char_u *
skip_regexp_err(char_u      *startp, int         delim, int         magic)
{
    char_u *p = skip_regexp(startp, delim, magic);

    if (*p != delim)
    {
        semsg(_(e_missing_delimiter_after_search_pattern_str), startp);
        return NULL;
    }
    return p;
}

    static char_u *
skip_regexp_ex(char_u      *startp, int         dirc, int         magic, char_u      **newp, int         *dropped, magic_T     *magic_val)
{
    magic_T     mymagic;
    char_u      *p = startp;
    size_t      startplen = 0;

    if (magic)
    {
        mymagic = MAGIC_ON;
    }
    else
    {
        mymagic = MAGIC_OFF;
    }
    get_cpo_flags();

    for (; p[0] != NUL;  p += (*mb_ptr2len)(p) )
    {
        if (p[0] == dirc)
        {
            break;
        }
        if ((p[0] == '[' && mymagic >= MAGIC_ON) || (p[0] == '\\' && p[1] == '[' && mymagic <= MAGIC_OFF))
        {
            p = skip_anyof(p + 1);
            if (p[0] == NUL)
            {
                break;
            }
        }
        else if (p[0] == '\\' && p[1] != NUL)
        {
            if (dirc == '?' && newp != NULL && p[1] == '?')
            {
                if (startplen == 0)
                {
                    startplen =  strlen((char *)(startp)) ;
                }
                if (*newp == NULL)
                {
                    *newp = vim_strnsave(startp, startplen);
                    if (*newp != NULL)
                    {
                        p = *newp + (p - startp);
                        startp = *newp;
                    }
                }
                if (dropped != NULL)
                {
                    ++*dropped;
                }
                if (*newp != NULL)
                {
                     memmove((char *)(p), (char *)(p + 1), startplen - ((p + 1) - startp) + 1) ;
                }
                else
                {
                    ++p;
                }
            }
            else
            {
                ++p;
            }
            if (*p == 'v')
            {
                mymagic = MAGIC_ALL;
            }
            else if (*p == 'V')
            {
                mymagic = MAGIC_NONE;
            }
        }
    }
    if (magic_val != NULL)
    {
        *magic_val = mymagic;
    }
    return p;
}

static int      prevchr_len;
static int      at_start;
static int      prev_at_start;

    static void
initchr(char_u *str)
{
    regparse = str;
    prevchr_len = 0;
    curchr = prevprevchr = prevchr = nextchr = -1;
    at_start = TRUE;
    prev_at_start = FALSE;
}

    static int
peekchr(void)
{
    static int  after_slash = FALSE;

    if (curchr != -1)
    {
        return curchr;
    }

    switch (curchr = regparse[0])
    {
        case '.':
        case '[':
        case '~':
            if (reg_magic >= MAGIC_ON)
            {
                curchr =  ((int)(curchr) - 256) ;
            }
            break;
        case '(':
        case ')':
        case '{':
        case '%':
        case '+':
        case '=':
        case '?':
        case '@':
        case '!':
        case '&':
        case '|':
        case '<':
        case '>':
        case '#':
        case '"':
        case '\'':
        case ',':
        case '-':
        case ':':
        case ';':
        case '`':
        case '/':
            if (reg_magic == MAGIC_ALL)
            {
                curchr =  ((int)(curchr) - 256) ;
            }
            break;
        case '*':
            if (reg_magic >= MAGIC_ON && !at_start && !(prev_at_start && prevchr ==  ((int)('^') - 256) ) && (after_slash || (prevchr !=  ((int)('(') - 256)  && prevchr !=  ((int)('&') - 256)  && prevchr !=  ((int)('|') - 256) )))
            {
                curchr =  ((int)('*') - 256) ;
            }
            break;
        case '^':
            if (reg_magic >= MAGIC_OFF && (at_start || reg_magic == MAGIC_ALL || prevchr ==  ((int)('(') - 256)  || prevchr ==  ((int)('|') - 256)  || prevchr ==  ((int)('&') - 256)  || prevchr ==  ((int)('n') - 256)  || (no_Magic(prevchr) == '(' && prevprevchr ==  ((int)('%') - 256) )))
            {
                curchr =  ((int)('^') - 256) ;
                at_start = TRUE;
                prev_at_start = FALSE;
            }
            break;
        case '$':
            if (reg_magic >= MAGIC_OFF)
            {
                char_u *p = regparse + 1;
                int is_magic_all = (reg_magic == MAGIC_ALL);

                while (p[0] == '\\' && (p[1] == 'c' || p[1] == 'C' || p[1] == 'm' || p[1] == 'M' || p[1] == 'v' || p[1] == 'V' || p[1] == 'Z'))
                {
                    if (p[1] == 'v')
                    {
                        is_magic_all = TRUE;
                    }
                    else if (p[1] == 'm' || p[1] == 'M' || p[1] == 'V')
                    {
                        is_magic_all = FALSE;
                    }
                    p += 2;
                }
                if (p[0] == NUL || (p[0] == '\\' && (p[1] == '|' || p[1] == '&' || p[1] == ')' || p[1] == 'n')) || (is_magic_all && (p[0] == '|' || p[0] == '&' || p[0] == ')')) || reg_magic == MAGIC_ALL)
                {
                    curchr =  ((int)('$') - 256) ;
                }
            }
            break;
        case '\\':
            {
                int c = regparse[1];

                if (c == NUL)
                {
                    curchr = '\\';
                }
                else if (c <= '~' && META_flags[c])
                {
                    curchr = -1;
                    prev_at_start = at_start;
                    at_start = FALSE;
                    ++regparse;
                    ++after_slash;
                    peekchr();
                    --regparse;
                    --after_slash;
                    curchr = toggle_Magic(curchr);
                }
                else if (vim_strchr(REGEXP_ABBR, c))
                {
                    curchr = backslash_trans(c);
                }
                else if (reg_magic == MAGIC_NONE && (c == '$' || c == '^'))
                {
                    curchr = toggle_Magic(c);
                }
                else
                {
                    if (has_mbyte)
                    {
                        curchr = (*mb_ptr2char)(regparse + 1);
                    }
                    else
                    {
                        curchr = c;
                    }
                }
                break;
            }

        default:
            if (has_mbyte)
            {
                curchr = (*mb_ptr2char)(regparse);
            }
    }

    return curchr;
}

    static void
skipchr(void)
{
    if (*regparse == '\\')
    {
        prevchr_len = 1;
    }
    else
    {
        prevchr_len = 0;
    }
    if (regparse[prevchr_len] != NUL)
    {
        if (enc_utf8)
        {
            prevchr_len += utf_ptr2len(regparse + prevchr_len);
        }
        else if (has_mbyte)
        {
            prevchr_len += (*mb_ptr2len)(regparse + prevchr_len);
        }
        else
        {
            ++prevchr_len;
        }
    }
    regparse += prevchr_len;
    prev_at_start = at_start;
    at_start = FALSE;
    prevprevchr = prevchr;
    prevchr = curchr;
    curchr = nextchr;
    nextchr = -1;
}

    static void
skipchr_keepstart(void)
{
    int as = prev_at_start;
    int pr = prevchr;
    int prpr = prevprevchr;

    skipchr();
    at_start = as;
    prevchr = pr;
    prevprevchr = prpr;
}

    static int
getchr(void)
{
    int chr = peekchr();

    skipchr();
    return chr;
}

    static void
ungetchr(void)
{
    nextchr = curchr;
    curchr = prevchr;
    prevchr = prevprevchr;
    at_start = prev_at_start;
    prev_at_start = FALSE;

    regparse -= prevchr_len;
}

    static vimlong_T
gethexchrs(int maxinputlen)
{
    long_u      nr = 0;
    int         c;
    int         i;

    for (i = 0; i < maxinputlen; ++i)
    {
        c = regparse[0];
        if (!vim_isxdigit(c))
        {
            break;
        }
        nr <<= 4;
        nr |= hex2nr(c);
        ++regparse;
    }

    if (i == 0)
    {
        return -1;
    }
    return nr;
}

    static vimlong_T
getdecchrs(void)
{
    long_u      nr = 0;
    int         c;
    int         i;

    for (i = 0; ; ++i)
    {
        c = regparse[0];
        if (c < '0' || c > '9')
        {
            break;
        }
        nr *= 10;
        nr += c - '0';
        ++regparse;
        curchr = -1;
    }

    if (i == 0)
    {
        return -1;
    }
    return nr;
}

    static long
getoctchrs(void)
{
    long_u      nr = 0;
    int         c;
    int         i;

    for (i = 0; i < 3 && nr < 040; ++i)
    {
        c = regparse[0];
        if (c < '0' || c > '7')
        {
            break;
        }
        nr <<= 3;
        nr |= hex2nr(c);
        ++regparse;
    }

    if (i == 0)
    {
        return -1;
    }
    return (long)nr;
}

    static int
read_limits(long *minval, long *maxval)
{
    int         reverse = FALSE;
    char_u      *first_char;
    long        tmp;

    if (*regparse == '-')
    {
        regparse++;
        reverse = TRUE;
    }
    first_char = regparse;
    *minval = getdigits(&regparse);
    if (*regparse == ',')
    {
        if (vim_isdigit(*++regparse))
        {
            *maxval = getdigits(&regparse);
        }
        else
        {
            *maxval =  (32767L << 16L) ;
        }
    }
    else if ( ((unsigned)(*first_char) - '0' < 10) )
    {
        *maxval = *minval;
    }
    else
    {
        *maxval =  (32767L << 16L) ;
    }
    if (*regparse == '\\')
    {
        regparse++;
    }
    if (*regparse != '}')
    {
         return (semsg((const char *)(_(e_syntax_error_in_str_curlies)), (reg_magic == MAGIC_ALL) ? "" : "\\"), rc_did_emsg = TRUE, FAIL) ;
    }

    if ((!reverse && *minval > *maxval) || (reverse && *minval < *maxval))
    {
        tmp = *minval;
        *minval = *maxval;
        *maxval = tmp;
    }
    skipchr();
    return OK;
}

static char_u   *reg_tofree = NULL;
static unsigned reg_tofreelen;

typedef struct {
    regmatch_T          *reg_match;
    regmmatch_T         *reg_mmatch;

    char_u              **reg_startp;
    char_u              **reg_endp;
    lpos_T              *reg_startpos;
    lpos_T              *reg_endpos;

    win_T               *reg_win;
    buf_T               *reg_buf;
    linenr_T            reg_firstlnum;
    linenr_T            reg_maxline;
    int                 reg_line_lbr;

    linenr_T    lnum;
    char_u      *line;
    char_u      *input;

    int need_clear_subexpr;

    int                 reg_ic;

    int                 reg_icombine;

    colnr_T             reg_maxcol;

    int nfa_has_zend;
    int nfa_has_backref;
    int nfa_nsubexpr;
    int nfa_listid;
    int nfa_alt_listid;

} regexec_T;

static regexec_T        rex;
static int              rex_in_use = FALSE;

    static int
reg_iswordc(int c)
{
    return vim_iswordc_buf(c, rex.reg_buf);
}

typedef enum
{
    RGLF_LINE = 0x01,
    RGLF_LENGTH = 0x02
} reg_getline_flags_T;

    static void
reg_getline_common(linenr_T            lnum, reg_getline_flags_T flags, char_u              **line, colnr_T             *length)
{
    int get_line = flags & RGLF_LINE;
    int get_length = flags & RGLF_LENGTH;
    linenr_T firstlnum;
    linenr_T maxline;

    {
        firstlnum = rex.reg_firstlnum + lnum;
        maxline = rex.reg_maxline;
    }

    if (firstlnum < 1)
    {
        if (get_line)
        {
            *line = NULL;
        }
        if (get_length)
        {
            *length = 0;
        }

        return;
    }

    if (lnum > maxline)
    {
        if (get_line)
        {
            *line = (char_u *)"";
        }
        if (get_length)
        {
            *length = 0;
        }

        return;
    }

    if (get_line)
    {
        *line = ml_get_buf(rex.reg_buf, firstlnum, FALSE);
    }
    if (get_length)
    {
        *length = ml_get_buf_len(rex.reg_buf, firstlnum);
    }
}

    static char_u *
reg_getline(linenr_T lnum)
{
    char_u *line;

    reg_getline_common(lnum, RGLF_LINE, &line, NULL);

    return line;
}

    static colnr_T
reg_getline_len(linenr_T lnum)
{
    colnr_T length;

    reg_getline_common(lnum, RGLF_LENGTH, NULL, &length);

    return length;
}

    static int
reg_prev_class(void)
{
    if (rex.input > rex.line)
    {
        return mb_get_class_buf(rex.input - 1 - (*mb_head_off)(rex.line, rex.input - 1), rex.reg_buf);
    }
    return -1;
}

    static int
reg_match_visual(void)
{
    pos_T top;
    pos_T bot;
    linenr_T    lnum;
    colnr_T     col;
    win_T       *wp = rex.reg_win == NULL ? curwin : rex.reg_win;
    int         mode;
    colnr_T start;
    colnr_T end;
    colnr_T start2;
    colnr_T end2;
    colnr_T     cols;
    colnr_T     curswant;

    if (rex.reg_buf != curbuf || VIsual.lnum == 0 || ! (rex.reg_match == NULL) )
    {
        return FALSE;
    }

    if (VIsual_active)
    {
        if ( (((VIsual).lnum != (wp->w_cursor).lnum)               ? (VIsual).lnum < (wp->w_cursor).lnum                   : (VIsual).col != (wp->w_cursor).col                        ? (VIsual).col < (wp->w_cursor).col                     : (VIsual).coladd < (wp->w_cursor).coladd) )
        {
            top = VIsual;
            bot = wp->w_cursor;
        }
        else
        {
            top = wp->w_cursor;
            bot = VIsual;
        }
        mode = VIsual_mode;
        curswant = wp->w_curswant;
    }
    else
    {
        if ( (((curbuf->b_visual.vi_start).lnum != (curbuf->b_visual.vi_end).lnum)               ? (curbuf->b_visual.vi_start).lnum < (curbuf->b_visual.vi_end).lnum                   : (curbuf->b_visual.vi_start).col != (curbuf->b_visual.vi_end).col                        ? (curbuf->b_visual.vi_start).col < (curbuf->b_visual.vi_end).col                     : (curbuf->b_visual.vi_start).coladd < (curbuf->b_visual.vi_end).coladd) )
        {
            top = curbuf->b_visual.vi_start;
            bot = curbuf->b_visual.vi_end;
        }
        else
        {
            top = curbuf->b_visual.vi_end;
            bot = curbuf->b_visual.vi_start;
        }
        if (bot.lnum > curbuf->b_ml.ml_line_count)
        {
            bot.lnum = curbuf->b_ml.ml_line_count;
        }
        mode = curbuf->b_visual.vi_mode;
        curswant = curbuf->b_visual.vi_curswant;
    }
    lnum = rex.lnum + rex.reg_firstlnum;
    if (lnum < top.lnum || lnum > bot.lnum)
    {
        return FALSE;
    }

    col = (colnr_T)(rex.input - rex.line);
    if (mode == 'v')
    {
        if ((lnum == top.lnum && col < top.col) || (lnum == bot.lnum && col >= bot.col + (*p_sel != 'e')))
        {
            return FALSE;
        }
    }
    else if (mode == Ctrl_V)
    {
        getvvcol(wp, &top, &start, NULL, &end, 0);
        getvvcol(wp, &bot, &start2, NULL, &end2, 0);
        if (start2 < start)
        {
            start = start2;
        }
        if (end2 > end)
        {
            end = end2;
        }
        if (top.col == MAXCOL || bot.col == MAXCOL || curswant == MAXCOL)
        {
            end = MAXCOL;
        }

        rex.line = reg_getline(rex.lnum);
        rex.input = rex.line + col;

        cols = win_linetabsize(wp, rex.reg_firstlnum + rex.lnum, rex.line, col);
        if (cols < start || cols > end - (*p_sel == 'e'))
        {
            return FALSE;
        }
    }
    return TRUE;
}

    static int
prog_magic_wrong(void)
{
    regprog_T   *prog;

    prog =  (rex.reg_match == NULL)  ? rex.reg_mmatch->regprog : rex.reg_match->regprog;
    if ( ((int)*(char_u *)(((bt_regprog_T *)prog)->program))  != REGMAGIC)
    {
        iemsg(e_corrupted_regexp_program);
        return TRUE;
    }
    return FALSE;
}

    static void
cleanup_subexpr(void)
{
    if (!rex.need_clear_subexpr)
    {
        return;
    }

    if ( (rex.reg_match == NULL) )
    {
         memset((rex.reg_startpos), (0xff), (sizeof(lpos_T) * NSUBEXP)) ;
         memset((rex.reg_endpos), (0xff), (sizeof(lpos_T) * NSUBEXP)) ;
    }
    else
    {
         memset((rex.reg_startp), (0), (sizeof(char_u *) * NSUBEXP)) ;
         memset((rex.reg_endp), (0), (sizeof(char_u *) * NSUBEXP)) ;
    }
    rex.need_clear_subexpr = FALSE;
}

    static void
reg_nextline(void)
{
    rex.line = reg_getline(++rex.lnum);
    rex.input = rex.line;
    fast_breakcheck();
}

    static int
match_with_backref(linenr_T start_lnum, colnr_T  start_col, linenr_T end_lnum, colnr_T  end_col, int      *bytelen)
{
    linenr_T    clnum = start_lnum;
    colnr_T     ccol = start_col;
    int         len;
    char_u      *p;

    if (bytelen != NULL)
    {
        *bytelen = 0;
    }
    for (;;)
    {
        if (rex.line != reg_tofree)
        {
            len = (int) strlen((char *)(rex.line)) ;
            if (reg_tofree == NULL || len >= (int)reg_tofreelen)
            {
                len += 50;
                vim_free(reg_tofree);
                reg_tofree = alloc(len);
                if (reg_tofree == NULL)
                {
                    return RA_FAIL;
                }
                reg_tofreelen = len;
            }
             strcpy((char *)(reg_tofree), (char *)(rex.line)) ;
            rex.input = reg_tofree + (rex.input - rex.line);
            rex.line = reg_tofree;
        }

        p = reg_getline(clnum);
        if (clnum == end_lnum)
        {
            len = end_col - ccol;
        }
        else
        {
            len = (int)reg_getline_len(clnum) - ccol;
        }

        if ((!rex.reg_ic && cstrncmp(p + ccol, rex.input, &len) != 0) || (rex.reg_ic &&  mb_strnicmp((char_u *)(p + ccol), (char_u *)(rex.input), (int)(len))  != 0))
        {
            return RA_NOMATCH;
        }
        if (bytelen != NULL)
        {
            *bytelen += len;
        }
        if (clnum == end_lnum)
        {
            break;
        }
        if (rex.lnum >= rex.reg_maxline)
        {
            return RA_NOMATCH;
        }

        reg_nextline();
        if (bytelen != NULL)
        {
            *bytelen = 0;
        }
        ++clnum;
        ccol = 0;
        if (got_int)
        {
            return RA_FAIL;
        }
    }

    return RA_MATCH;
}

    static int
re_mult_next(char *what)
{
    if (re_multi_type(peekchr()) == MULTI_MULT)
    {
        semsg(_(e_nfa_regexp_cannot_repeat_str), what);
        rc_did_emsg = TRUE;
        return FAIL;
    }
    return OK;
}

typedef struct
{
    int a;
    int b;
    int c;
} decomp_T;

static decomp_T decomp_table[0xfb4f-0xfb20+1] =
{
    {0x5e2,0,0},
    {0x5d0,0,0},
    {0x5d3,0,0},
    {0x5d4,0,0},
    {0x5db,0,0},
    {0x5dc,0,0},
    {0x5dd,0,0},
    {0x5e8,0,0},
    {0x5ea,0,0},
    {'+', 0, 0},
    {0x5e9, 0x5c1, 0},
    {0x5e9, 0x5c2, 0},
    {0x5e9, 0x5c1, 0x5bc},
    {0x5e9, 0x5c2, 0x5bc},
    {0x5d0, 0x5b7, 0},
    {0x5d0, 0x5b8, 0},
    {0x5d0, 0x5b4, 0},
    {0x5d1, 0x5bc, 0},
    {0x5d2, 0x5bc, 0},
    {0x5d3, 0x5bc, 0},
    {0x5d4, 0x5bc, 0},
    {0x5d5, 0x5bc, 0},
    {0x5d6, 0x5bc, 0},
    {0xfb37, 0, 0},
    {0x5d8, 0x5bc, 0},
    {0x5d9, 0x5bc, 0},
    {0x5da, 0x5bc, 0},
    {0x5db, 0x5bc, 0},
    {0x5dc, 0x5bc, 0},
    {0xfb3d, 0, 0},
    {0x5de, 0x5bc, 0},
    {0xfb3f, 0, 0},
    {0x5e0, 0x5bc, 0},
    {0x5e1, 0x5bc, 0},
    {0xfb42, 0, 0},
    {0x5e3, 0x5bc, 0},
    {0x5e4, 0x5bc,0},
    {0xfb45, 0, 0},
    {0x5e6, 0x5bc, 0},
    {0x5e7, 0x5bc, 0},
    {0x5e8, 0x5bc, 0},
    {0x5e9, 0x5bc, 0},
    {0x5ea, 0x5bc, 0},
    {0x5d5, 0x5b9, 0},
    {0x5d1, 0x5bf, 0},
    {0x5db, 0x5bf, 0},
    {0x5e4, 0x5bf, 0},
    {0x5d0, 0x5dc, 0}
};

    static void
mb_decompose(int c, int *c1, int *c2, int *c3)
{
    decomp_T d;

    if (c >= 0xfb20 && c <= 0xfb4f)
    {
        d = decomp_table[c - 0xfb20];
        *c1 = d.a;
        *c2 = d.b;
        *c3 = d.c;
    }
    else
    {
        *c1 = c;
        *c2 = 0;
        *c3 = 0;
    }
}

    static int
cstrncmp(char_u *s1, char_u *s2, int *n)
{
    int         result;

    if (!rex.reg_ic)
    {
        result =  strncmp((char *)(s1), (char *)(s2), (*n)) ;
    }
    else if (enc_utf8)
    {
        char_u *p = s1;
        int n2 = 0;
        int n1 = *n;
        while (n1 > 0 && *p != NUL)
        {
            n1 -= mb_ptr2len(s1);
             p += (*mb_ptr2len)(p) ;
            n2++;
        }
        p = s2;
        while (n2-- > 0 && *p != NUL)
        {
             p += (*mb_ptr2len)(p) ;
        }

        n2 = p - s2;

        result =  mb_strnicmp2((char_u *)(s1), (char_u *)(s2), (*n), (n2)) ;
        if (result == 0 && n2 < *n)
        {
            *n = n2;
        }
    }
    else
    {
        result =  mb_strnicmp((char_u *)(s1), (char_u *)(s2), (int)(*n)) ;
    }

    if (result != 0 && enc_utf8 && rex.reg_icombine)
    {
        char_u *str1;
        char_u *str2;
        int c1;
        int c2;
        int c11;
        int c12;
        int     junk;

        str1 = s1;
        str2 = s2;
        c1 = c2 = 0;
        while ((int)(str1 - s1) < *n)
        {
            c1 = mb_ptr2char_adv(&str1);
            c2 = mb_ptr2char_adv(&str2);

            if (c1 != c2 && (!rex.reg_ic || utf_fold(c1) != utf_fold(c2)))
            {
                mb_decompose(c1, &c11, &junk, &junk);
                mb_decompose(c2, &c12, &junk, &junk);
                c1 = c11;
                c2 = c12;
                if (c11 != c12 && (!rex.reg_ic || utf_fold(c11) != utf_fold(c12)))
                {
                    break;
                }
            }
        }
        result = c2 - c1;
        if (result == 0)
        {
            *n = (int)(str2 - s2);
        }
    }

    return result;
}

    static char_u *
cstrchr(char_u *s, int c)
{
    char_u      *p;
    int cc;
    int lc;

    if (!rex.reg_ic || (!enc_utf8 && mb_char2len(c) > 1))
    {
        return vim_strchr(s, c);
    }

    if (enc_utf8 && c > 0x80)
    {
        cc = utf_fold(c);
        lc = cc;
    }
    else
    {
        if ( vim_isupper(c) )
        {
            cc =  vim_tolower(c) ;
            lc = cc;
        }
        else if ( vim_islower(c) )
        {
            cc =  vim_toupper(c) ;
            lc = c;
        }
        else
        {
            return vim_strchr(s, c);
        }
    }

    if (has_mbyte)
    {
        for (p = s; *p != NUL; p += (*mb_ptr2len)(p))
        {
            int uc = utf_ptr2char(p);
            if (enc_utf8 && (c > 0x80 || uc > 0x80))
            {
                if ((uc < 0x80 || uc != *p) && utf_fold(uc) == lc)
                {
                    return p;
                }
            }
            else if (*p == c || *p == cc)
            {
                return p;
            }
        }
    }
    else
    {
        for (p = s; *p != NUL; ++p)
        {
            if (*p == c || *p == cc)
            {
                return p;
            }
        }
    }

    return NULL;
}

typedef void (*fptr_T)(int *, int);

static int vim_regsub_both(char_u *source, typval_T *expr, char_u *dest, int destlen, int flags);

    static void
do_upper(int *d, int c)
{
    *d =  vim_toupper(c) ;
}

    static void
do_lower(int *d, int c)
{
    *d =  vim_tolower(c) ;
}

    static char_u *
regtilde(char_u *source, int magic)
{
    char_u      *newsub = source;
    char_u      *p;
    size_t      newsublen = 0;
    char_u      tilde[3] = {'~', NUL, NUL};
    size_t      tildelen = 1;
    int         error = FALSE;

    if (!magic)
    {
        tilde[0] = '\\';
        tilde[1] = '~';
        tilde[2] = NUL;
        tildelen = 2;
    }

    for (p = newsub; *p; ++p)
    {
        if ( strncmp((char *)(p), (char *)(tilde), (tildelen))  == 0)
        {
            size_t prefixlen = p - newsub;
            char_u *postfix = p + tildelen;
            size_t postfixlen;
            size_t tmpsublen;

            if (newsublen == 0)
            {
                newsublen =  strlen((char *)(newsub)) ;
            }
            newsublen -= tildelen;
            postfixlen = newsublen - prefixlen;
            tmpsublen = prefixlen + reg_prev_sublen + postfixlen;

            if (tmpsublen > 0 && reg_prev_sub != NULL)
            {
                char_u *tmpsub;

                if (tmpsublen > MAXCOL)
                {
                    emsg(_(e_resulting_text_too_long));
                    error = TRUE;
                    break;
                }

                tmpsub = alloc(tmpsublen + 1);
                if (tmpsub == NULL)
                {
                    emsg(_(e_out_of_memory));
                    error = TRUE;
                    break;
                }

                 memmove((char *)(tmpsub), (char *)(newsub), prefixlen) ;
                 memmove((char *)(tmpsub + prefixlen), (char *)(reg_prev_sub), reg_prev_sublen) ;
                 strcpy((char *)(tmpsub + prefixlen + reg_prev_sublen), (char *)(postfix)) ;

                if (newsub != source)
                {
                    vim_free(newsub);
                }
                newsub = tmpsub;
                newsublen = tmpsublen;
                p = newsub + prefixlen + reg_prev_sublen;
            }
            else
            {
                 memmove((char *)(p), (char *)(postfix), postfixlen + 1) ;
            }

            --p;
        }
        else
        {
            if (*p == '\\' && p[1])
            {
                ++p;
            }
            if (has_mbyte)
            {
                p += (*mb_ptr2len)(p) - 1;
            }
        }
    }

    if (error)
    {
        if (newsub != source)
        {
            vim_free(newsub);
        }
        return source;
    }

    newsublen = p - newsub;
    if (newsublen == 0)
    {
         vim_free(reg_prev_sub);
         (reg_prev_sub) = NULL;
    }
    else
    {
        vim_free(reg_prev_sub);
        reg_prev_sub = vim_strnsave(newsub, newsublen);
    }

    if (reg_prev_sub == NULL)
    {
        reg_prev_sublen = 0;
    }
    else
    {
        reg_prev_sublen = newsublen;
    }

    return newsub;
}

    static int
vim_regsub(regmatch_T  *rmp, char_u      *source, typval_T    *expr, char_u      *dest, int         destlen, int         flags)
{
    int         result;
    regexec_T   rex_save;
    int         rex_in_use_save = rex_in_use;

    if (rex_in_use)
    {
        rex_save = rex;
    }
    rex_in_use = TRUE;

    rex.reg_match = rmp;
    rex.reg_mmatch = NULL;
    rex.reg_maxline = 0;
    rex.reg_buf = curbuf;
    rex.reg_line_lbr = TRUE;
    result = vim_regsub_both(source, expr, dest, destlen, flags);

    rex_in_use = rex_in_use_save;
    if (rex_in_use)
    {
        rex = rex_save;
    }

    return result;
}

    static int
vim_regsub_multi(regmmatch_T *rmp, linenr_T    lnum, char_u      *source, char_u      *dest, int         destlen, int         flags)
{
    int         result;
    regexec_T   rex_save;
    int         rex_in_use_save = rex_in_use;

    if (rex_in_use)
    {
        rex_save = rex;
    }
    rex_in_use = TRUE;

    rex.reg_match = NULL;
    rex.reg_mmatch = rmp;
    rex.reg_buf = curbuf;
    rex.reg_firstlnum = lnum;
    rex.reg_maxline = curbuf->b_ml.ml_line_count - lnum;
    rex.reg_line_lbr = FALSE;
    result = vim_regsub_both(source, NULL, dest, destlen, flags);

    rex_in_use = rex_in_use_save;
    if (rex_in_use)
    {
        rex = rex_save;
    }

    return result;
}

    static int
vim_regsub_both(char_u      *source, typval_T    *expr, char_u      *dest, int         destlen, int         flags)
{
    char_u      *src;
    char_u      *dst;
    char_u      *s;
    int         c;
    int         cc;
    int         no = -1;
    fptr_T      func_all = (fptr_T)NULL;
    fptr_T      func_one = (fptr_T)NULL;
    linenr_T    clnum = 0;
    int         len = 0;
    int         copy = flags & REGSUB_COPY;

    if ((source == NULL && expr == NULL) || dest == NULL)
    {
        iemsg(e_null_argument);
        return 0;
    }
    if (prog_magic_wrong())
    {
        return 0;
    }
    src = source;
    dst = dest;

    if (expr != NULL || (source[0] == '\\' && source[1] == '='))
    {
    }
    else
    {
      while ((c = *src++) != NUL)
      {
        if (c == '&' && (flags & REGSUB_MAGIC))
        {
            no = 0;
        }
        else if (c == '\\' && *src != NUL)
        {
            if (*src == '&' && !(flags & REGSUB_MAGIC))
            {
                ++src;
                no = 0;
            }
            else if ('0' <= *src && *src <= '9')
            {
                no = *src++ - '0';
            }
            else if (vim_strchr((char_u *)"uUlLeE", *src))
            {
                switch (*src++)
                {
                case 'u':
                    func_one = do_upper;
                            continue;
                case 'U':
                    func_all = do_upper;
                            continue;
                case 'l':
                    func_one = do_lower;
                            continue;
                case 'L':
                    func_all = do_lower;
                            continue;
                case 'e':
                case 'E':
                    func_one = func_all = (fptr_T)NULL;
                            continue;
                }
            }
        }
        if (no < 0)
        {
            if (c ==  (0x80)  && src[0] != NUL && src[1] != NUL)
            {
                if (copy)
                {
                    if (dst + 3 > dest + destlen)
                    {
                        iemsg("vim_regsub_both(): not enough space");
                        return 0;
                    }
                    *dst++ = c;
                    *dst++ = *src++;
                    *dst++ = *src++;
                }
                else
                {
                    dst += 3;
                    src += 2;
                }
                continue;
            }

            if (c == '\\' && *src != NUL)
            {
                switch (*src)
                {
                    case 'r':
                        c = CAR;
                        ++src;
                        break;
                    case 'n':
                        c = NL;
                        ++src;
                        break;
                    case 't':
                        c = TAB;
                        ++src;
                        break;
                    case 'b':
                        c = Ctrl_H;
                        ++src;
                        break;

                    default:
                        if (flags & REGSUB_BACKSLASH)
                                {
                                    if (copy)
                                    {
                                        if (dst + 1 > dest + destlen)
                                        {
                                            iemsg("vim_regsub_both(): not enough space");
                                            return 0;
                                        }
                                        *dst = '\\';
                                    }
                                    ++dst;
                                }
                                c = *src++;
                }
            }
            else if (has_mbyte)
            {
                c = mb_ptr2char(src - 1);
            }

            if (func_one != (fptr_T)NULL)
            {
                func_one(&cc, c);
                func_one = NULL;
            }
            else if (func_all != (fptr_T)NULL)
            {
                func_all(&cc, c);
            }
            else
            {
                cc = c;
            }

            if (has_mbyte)
            {
                int totlen = mb_ptr2len(src - 1);
                int charlen = mb_char2len(cc);

                if (copy)
                {
                    if (dst + charlen > dest + destlen)
                    {
                        iemsg("vim_regsub_both(): not enough space");
                        return 0;
                    }
                    mb_char2bytes(cc, dst);
                }
                dst += charlen - 1;
                if (enc_utf8)
                {
                    int clen = utf_ptr2len(src - 1);

                    if (clen < totlen)
                    {
                        if (copy)
                        {
                            if (dst + totlen - clen > dest + destlen)
                            {
                                iemsg("vim_regsub_both(): not enough space");
                                return 0;
                            }
                             memmove((char *)(dst + 1), (char *)(src - 1 + clen), (size_t)(totlen - clen)) ;
                        }
                        dst += totlen - clen;
                    }
                }
                src += totlen - 1;
            }
            else if (copy)
            {
                if (dst + 1 > dest + destlen)
                {
                    iemsg("vim_regsub_both(): not enough space");
                    return 0;
                }
                *dst = cc;
            }
            dst++;
        }
        else
        {
            if ( (rex.reg_match == NULL) )
            {
                clnum = rex.reg_mmatch->startpos[no].lnum;
                if (clnum < 0 || rex.reg_mmatch->endpos[no].lnum < 0)
                {
                    s = NULL;
                }
                else
                {
                    s = reg_getline(clnum) + rex.reg_mmatch->startpos[no].col;
                    if (rex.reg_mmatch->endpos[no].lnum == clnum)
                    {
                        len = rex.reg_mmatch->endpos[no].col
                                            - rex.reg_mmatch->startpos[no].col;
                    }
                    else
                    {
                        len = (int)reg_getline_len(clnum) - rex.reg_mmatch->startpos[no].col;
                    }
                }
            }
            else
            {
                s = rex.reg_match->startp[no];
                if (rex.reg_match->endp[no] == NULL)
                {
                    s = NULL;
                }
                else
                {
                    len = (int)(rex.reg_match->endp[no] - s);
                }
            }
            if (s != NULL)
            {
                for (;;)
                {
                    if (len == 0)
                    {
                        if ( (rex.reg_match == NULL) )
                        {
                            if (rex.reg_mmatch->endpos[no].lnum == clnum)
                            {
                                break;
                            }
                            if (copy)
                            {
                                if (dst + 1 > dest + destlen)
                                {
                                    iemsg("vim_regsub_both(): not enough space");
                                    return 0;
                                }
                                *dst = CAR;
                            }
                            ++dst;
                            s = reg_getline(++clnum);
                            if (rex.reg_mmatch->endpos[no].lnum == clnum)
                            {
                                len = rex.reg_mmatch->endpos[no].col;
                            }
                            else
                            {
                                len = (int)reg_getline_len(clnum);
                            }
                        }
                        else
                        {
                            break;
                        }
                    }
                    else if (*s == NUL)
                    {
                        if (copy)
                        {
                            iemsg(e_damaged_match_string);
                        }
                        goto exit;
                    }
                    else
                    {
                        if ((flags & REGSUB_BACKSLASH) && (*s == CAR || *s == '\\'))
                        {
                            if (copy)
                            {
                                if (dst + 2 > dest + destlen)
                                {
                                    iemsg("vim_regsub_both(): not enough space");
                                    return 0;
                                }
                                dst[0] = '\\';
                                dst[1] = *s;
                            }
                            dst += 2;
                        }
                        else
                        {
                            if (has_mbyte)
                            {
                                c = mb_ptr2char(s);
                            }
                            else
                            {
                                c = *s;
                            }

                            if (func_one != (fptr_T)NULL)
                            {
                                func_one(&cc, c);
                                func_one = NULL;
                            }
                            else if (func_all != (fptr_T)NULL)
                            {
                                func_all(&cc, c);
                            }
                            else
                            {
                                cc = c;
                            }

                            if (has_mbyte)
                            {
                                int l;
                                int charlen;

                                if (enc_utf8)
                                {
                                    l = utf_ptr2len(s) - 1;
                                }
                                else
                                {
                                    l = mb_ptr2len(s) - 1;
                                }

                                s += l;
                                len -= l;
                                charlen = mb_char2len(cc);
                                if (copy)
                                {
                                    if (dst + charlen > dest + destlen)
                                    {
                                        iemsg("vim_regsub_both(): not enough space");
                                        return 0;
                                    }
                                    mb_char2bytes(cc, dst);
                                }
                                dst += charlen - 1;
                            }
                            else if (copy)
                            {
                                if (dst + 1 > dest + destlen)
                                {
                                    iemsg("vim_regsub_both(): not enough space");
                                    return 0;
                                }
                                *dst = cc;
                            }
                            dst++;
                        }

                        ++s;
                        --len;
                    }
                }
            }
            no = -1;
        }
      }
    }
    if (copy)
    {
        *dst = NUL;
    }

exit:
    return (int)((dst - dest) + 1);
}

    static void
init_regexec_multi(regmmatch_T     *rmp, win_T           *win, buf_T           *buf, linenr_T        lnum)
{
    rex.reg_match = NULL;
    rex.reg_mmatch = rmp;
    rex.reg_buf = buf;
    rex.reg_win = win;
    rex.reg_firstlnum = lnum;
    rex.reg_maxline = rex.reg_buf->b_ml.ml_line_count - lnum;
    rex.reg_line_lbr = FALSE;
    rex.reg_ic = rmp->rmm_ic;
    rex.reg_icombine = FALSE;
    rex.reg_maxcol = rmp->rmm_maxcol;
}

