                      regmbc(0xc7);
                      regmbc(0x106);
                      regmbc(0x108);
                      regmbc(0x10a);
                      regmbc(0x10c);
                      regmbc(0x187);
                      regmbc(0x23b);
                      regmbc(0x1e08);
                      regmbc(0xa792);
