            case 'D':
                case 0x10e:
                    case 0x110:
                        case 0x18a:
            case 0x1e0a:
                case 0x1e0c:
                    case 0x1e0e:
                        case 0x1e10:
            case 0x1e12:
                      regmbc('D');
                      regmbc(0x10e);
                      regmbc(0x110);
                      regmbc(0x18a);
                      regmbc(0x1e0a);
                      regmbc(0x1e0c);
                      regmbc(0x1e0e);
                      regmbc(0x1e10);
