                            case 0xcb:
            case 0x112:
                case 0x114:
                    case 0x116:
                        case 0x118:
                            case 0x11a:
            case 0x204:
                case 0x206:
                    case 0x228:
                        case 0x246:
                            case 0x1e14:
            case 0x1e16:
                case 0x1e18:
                    case 0x1e1a:
                        case 0x1e1c:
            case 0x1eb8:
                case 0x1eba:
                    case 0x1ebc:
