typedef struct {
    char    *tpr_name;
    int     tpr_set_by_termresponse;
    int     tpr_status;
} termprop_T;

enum { TPR_UNKNOWN = 'u' };
enum { TPR_YES = 'y' };
enum { TPR_NO = 'n' };
enum { TPR_MOUSE_XTERM = 'x' };
enum { TPR_MOUSE_XTERM2 = '2' };
enum { TPR_MOUSE_SGR = 's' };

enum { TPR_CURSOR_STYLE = 0 };
enum { TPR_CURSOR_BLINK = 1 };
enum { TPR_UNDERLINE_RGB = 2 };
enum { TPR_MOUSE = 3 };
enum { TPR_KITTY = 4 };
enum { TPR_DECRQM = 5 };
enum { TPR_COUNT = 6 };

static termprop_T term_props[TPR_COUNT];

    static void
init_term_props(int all)
{
    int i;

    term_props[TPR_CURSOR_STYLE].tpr_name = "cursor_style";
    term_props[TPR_CURSOR_STYLE].tpr_set_by_termresponse = FALSE;
    term_props[TPR_CURSOR_BLINK].tpr_name = "cursor_blink_mode";
    term_props[TPR_CURSOR_BLINK].tpr_set_by_termresponse = FALSE;
    term_props[TPR_UNDERLINE_RGB].tpr_name = "underline_rgb";
    term_props[TPR_UNDERLINE_RGB].tpr_set_by_termresponse = TRUE;
    term_props[TPR_MOUSE].tpr_name = "mouse";
    term_props[TPR_MOUSE].tpr_set_by_termresponse = TRUE;
    term_props[TPR_KITTY].tpr_name = "kitty";
    term_props[TPR_KITTY].tpr_set_by_termresponse = FALSE;
    term_props[TPR_DECRQM].tpr_name = "decrqm";
    term_props[TPR_DECRQM].tpr_set_by_termresponse = TRUE;

    for (i = 0; i < TPR_COUNT; ++i)
    {
        if (all || term_props[i].tpr_set_by_termresponse)
        {
            term_props[i].tpr_status = TPR_UNKNOWN;
        }
    }
}

    static tcap_entry_T *
find_builtin_term(char_u *term)
{
    for (int i = 0; ; ++i)
    {
        char_u *name = (char_u *)builtin_terminals[i].bitc_name;
        if (name == NULL)
        {
            break;
        }
        if ( strcmp((char *)(name), (char *)("xterm"))  == 0 && vim_is_xterm(term))
        {
            return builtin_terminals[i].bitc_table;
        }
        if ( strcmp((char *)(term), (char *)(name))  == 0)
        {
            return builtin_terminals[i].bitc_table;
        }
    }
    return NULL;
}

    static void
apply_builtin_tcap(char_u *term, tcap_entry_T *entries, int overwrite)
{
    int term_8bit = term_is_8bit(term);

    for (tcap_entry_T *p = entries; p->bt_entry != (int)KS_NAME && p->bt_entry != BT_EXTRA_KEYS; ++p)
    {
        if ((int)p->bt_entry >= 0)
        {
            if (term_strings[p->bt_entry] == NULL || term_strings[p->bt_entry] == empty_option || overwrite)
            {
                if (term_8bit && term_7to8bit((char_u *)p->bt_string) != 0)
                {
                    char_u *s;
                    char_u *t;

                    s = vim_strsave((char_u *)p->bt_string);
                    if (s != NULL)
                    {
                        for (t = s; *t; ++t)
                        {
                            if (term_7to8bit(t))
                            {
                                *t = term_7to8bit(t);
                                  memmove((char *)((t + 1)), (char *)((t + 2)),  strlen((char *)(t + 2))  + 1)  ;
                            }
                        }
                        term_strings[p->bt_entry] = s;
                                  set_term_option_alloced(&term_strings[p->bt_entry]);
                    }
                }
                else
                {
                    term_strings[p->bt_entry] = (char_u *)p->bt_string;
                }
            }
        }
        else
        {
            char_u  name[2];
            name[0] =  ((-((int)p->bt_entry)) & 0xff) ;
            name[1] =  (((unsigned)(-((int)p->bt_entry)) >> 8) & 0xff) ;
            if (find_termcode(name) == NULL || overwrite)
            {
                add_termcode(name, (char_u *)p->bt_string, term_8bit);
            }
        }
    }
}

    static void
apply_keyprotocol(char_u *term, keyprot_T prot)
{
    if (prot == KEYPROTOCOL_KITTY)
    {
        apply_builtin_tcap(term, builtin_kitty, TRUE);
    }
    if (prot == KEYPROTOCOL_MOK2)
    {
        apply_builtin_tcap(term, builtin_mok2, TRUE);
    }

    if (prot != KEYPROTOCOL_NONE)
    {
        accept_modifiers_for_function_keys();
    }
}

    static void
parse_builtin_tcap(char_u *term)
{
    tcap_entry_T *entries = find_builtin_term(term);
    if (entries != NULL)
    {
        apply_builtin_tcap(term, entries, FALSE);
    }
}

    static void
set_color_count(int nr)
{
    char_u      nr_colors[20];

    t_colors = nr;
    if (t_colors > 1)
    {
        sprintf((char *)nr_colors, "%d", t_colors);
    }
    else
    {
        *nr_colors = NUL;
    }
    set_string_option_direct((char_u *)"t_Co", -1, nr_colors, OPT_FREE, 0);
}

    static void
may_adjust_color_count(int val)
{
    if (val == t_colors)
    {
        return;
    }

    set_keep_msg_from_hist();
    set_color_count(val);
    init_highlight(TRUE, FALSE);
    redraw_asap(UPD_CLEAR);
}

    static int
term_strings_not_set(enum SpecialKey idx)
{
    return  term_strings[(int)(idx)]  == NULL ||  term_strings[(int)(idx)]  == empty_option;
}

    static void
report_term_error(char *error_msg, char_u *term)
{
     fprintf(stderr, "%s", ("\r\n")) ;
    if (error_msg != NULL)
    {
         fprintf(stderr, "%s", (error_msg)) ;
         fprintf(stderr, "%s", ("\r\n")) ;
    }
     fprintf(stderr, "%s", ("'")) ;
     fprintf(stderr, "%s", ((char *)term)) ;
     fprintf(stderr, "%s", (_("' not known, defaulting to 'xterm'"))) ;
     fprintf(stderr, "%s", ("\r\n")) ;
}

    static void
report_default_term(char_u *term)
{
    if (emsg_silent == 0 && !in_assert_fails)
    {
        screen_start();
        out_flush();
    }
}

    static keyprot_T
match_keyprotocol(char_u *term)
{
    int         len = (int) strlen((char *)(p_kpc))  + 1;
    char_u      *buf = alloc(len);
    if (buf == NULL)
    {
        return KEYPROTOCOL_FAIL;
    }

    keyprot_T   ret = KEYPROTOCOL_FAIL;
    char_u      *p = p_kpc;
    while (*p != NUL)
    {
        (void)copy_option_part(&p, buf, len, ",");
        char_u *colon = vim_strchr(buf, ':');
        if (colon == NULL || colon == buf || colon[1] == NUL)
        {
            goto theend;
        }
        *colon = NUL;

        keyprot_T prot;
        if ( strcmp((char *)(colon + 1), (char *)("none"))  == 0)
        {
            prot = KEYPROTOCOL_NONE;
        }
        else if ( strcmp((char *)(colon + 1), (char *)("mok2"))  == 0)
        {
            prot = KEYPROTOCOL_MOK2;
        }
        else if ( strcmp((char *)(colon + 1), (char *)("kitty"))  == 0)
        {
            prot = KEYPROTOCOL_KITTY;
        }
        else
        {
            goto theend;
        }

        regmatch_T regmatch;
          memset((&(regmatch)), (0), (sizeof(regmatch)))  ;
        regmatch.rm_ic = TRUE;
        regmatch.regprog = vim_regcomp(buf, RE_MAGIC);
        if (regmatch.regprog == NULL)
        {
            goto theend;
        }

        int match = term != NULL && vim_regexec(&regmatch, term, (colnr_T)0);
        vim_regfree(regmatch.regprog);
        if (match)
        {
            ret = prot;
            goto theend;
        }

    }

    ret = KEYPROTOCOL_NONE;

theend:
    vim_free(buf);
    return ret;
}

    static int
set_termname(char_u *term)
{
    int width = 0;
    int height = 0;
    char        *error_msg = NULL;
    char_u *bs_p;
    char_u *del_p;
    char_u      *requested = term;

    if (silent_mode)
    {
        return OK;
    }

    detected_8bit = FALSE;

    if (term_is_builtin(term))
    {
        term += 8;
    }

        {
            tcap_entry_T *termp = find_builtin_term(term);
            if (termp == NULL)
            {
                report_term_error(error_msg, term);

                if (starting != NO_SCREEN)
                {
                    screen_start();
                    wait_return(TRUE);
                    return FAIL;
                }
                term =  (char_u *)"xterm" ;
                report_default_term(term);
                set_string_option_direct((char_u *)"term", -1, term, OPT_FREE, 0);
                 fflush(stderr) ;
            }
            out_flush();
                clear_termoptions();
            parse_builtin_tcap(term);

            if (strstr((char *)requested, "256color") != NULL && (term_strings_not_set(KS_CCO) || atoi((char *) ( term_strings[(int)(KS_CCO)] ) ) < 256))
            {
                apply_builtin_tcap(term, builtin_256colors, TRUE);
            }

        }

    {
        keyprot_T kpc = match_keyprotocol(term);
        apply_keyprotocol(term, kpc);

    }

    if ( strcmp((char *)(term), (char *)("pcterm"))  == 0)
    {
         ( term_strings[(int)(KS_CCS)] )  = (char_u *)"yes";
    }
    else
    {
         ( term_strings[(int)(KS_CCS)] )  = empty_option;
    }

    if (strstr((char *)term, "kitty") != NULL && ( ( term_strings[(int)(KS_CRV)] )  == NULL || * ( term_strings[(int)(KS_CRV)] )  == NUL))
    {
         ( term_strings[(int)(KS_CRV)] )  = (char_u *)"\033[>c";
    }

        get_stty();

    {
        bs_p = find_termcode((char_u *)"kb");
        del_p = find_termcode((char_u *)"kD");
        if (bs_p == NULL || *bs_p == NUL)
        {
            add_termcode((char_u *)"kb", (bs_p = (char_u *) "\010" ), FALSE);
        }
        if ((del_p == NULL || *del_p == NUL) && (bs_p == NULL || *bs_p != DEL))
        {
            add_termcode((char_u *)"kD", (char_u *) (char_u *)"\177" , FALSE);
        }
    }

    term_is_xterm = vim_is_xterm(term);

    int did_set_ttym = FALSE;
    if ( ( term_strings[(int)(KS_CXM)] )  != NULL && * ( term_strings[(int)(KS_CXM)] )  != NUL && !option_was_set((char_u *)"ttym"))
    {
        char_u *p =  ( term_strings[(int)(KS_CXM)] ) ;

        while (*p != NUL && ! ((unsigned)(*p) - '0' < 10) )
        {
            ++p;
        }
        if (getdigits(&p) == 1006)
        {
            did_set_ttym = TRUE;
            set_option_value_give_err((char_u *)"ttym", 0L, (char_u *)"sgr", 0);
        }
    }

    {
        char_u  *p = (char_u *)"";

        if (use_xterm_like_mouse(term))
        {
            if (use_xterm_mouse())
            {
                p = NULL;
            }
            else
            {
                p = (char_u *)"xterm";
            }
        }
        if (p != NULL && !did_set_ttym)
        {
            set_option_value_give_err((char_u *)"ttym", 0L, p, 0);
            reset_option_was_set((char_u *)"ttym");
        }
        if (p == NULL)
        {
            check_mouse_termcode();
        }
    }

    {
        char_u name[3];

        name[0] = KS_EXTRA;
        name[1] = KE_FOCUSGAINED;
        name[2] = NUL;
        add_termcode(name, (char_u *)"\033[I", FALSE);

        name[1] = KE_FOCUSLOST;
        add_termcode(name, (char_u *)"\033[O", FALSE);

        need_gather = TRUE;
    }
    focus_state = MAYBE;

    ttest(TRUE);

    full_screen = TRUE;
    set_term_defaults();

    if (starting != NO_SCREEN)
    {
        starttermcap();
        setmouse();
        maketitle();
    }

    if (width <= 0 || height <= 0)
    {
        width = 80;
        height = 24;
    }
    set_shellsize(width, height, FALSE);
    if (starting != NO_SCREEN)
    {
        if (scroll_region)
        {
            scroll_region_reset();
        }
        check_map_keycodes();

        {
            buf_T       *buf;
            aco_save_T  aco;

             for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
            {
                if (curbuf->b_ml.ml_mfp != NULL)
                {
                    aucmd_prepbuf(&aco, buf);
                    if (curbuf == buf)
                    {
                        apply_autocmds(EVENT_TERMCHANGED, NULL, NULL, FALSE, curbuf);
                        aucmd_restbuf(&aco);
                    }
                }
            }
        }
    }

    return OK;
}

    static int
add_termcap_entry(char_u *name, int force)
{
    char_u  *term;
    int     key;

    if (!force && find_termcode(name) != NULL)
    {
        return OK;
    }

    term =  ( term_strings[(int)(KS_NAME)] ) ;
    if (term == NULL || *term == NUL)
    {
        return FAIL;
    }

    if (term_is_builtin(term))
    {
        term += 8;
    }

        {
            tcap_entry_T *termp = find_builtin_term(term);
            if (termp != NULL)
            {
                key =  (-((name[0]) + ((int)(name[1]) << 8))) ;
                ++termp;
                while (termp->bt_entry != (int)KS_NAME)
                {
                    if ((int)termp->bt_entry == key)
                    {
                        add_termcode(name, (char_u *)termp->bt_string, term_is_8bit(term));
                        return OK;
                    }
                    ++termp;
                }
            }
        }

    if ( (((estack_T *)exestack.ga_data)[exestack.ga_len - 1].es_name)  == NULL)
    {
            semsg(_(e_no_str_entry_in_termcap), name);
    }
    return FAIL;
}

    static int
term_is_builtin(char_u *name)
{
    return ( strncmp((char *)(name), (char *)("builtin_"), ((size_t)8))  == 0);
}

    static int
term_is_8bit(char_u *name)
{
    return (detected_8bit || strstr((char *)name, "8bit") != NULL);
}

    static int
term_7to8bit(char_u *p)
{
    if (*p != ESC)
    {
        return 0;
    }

    if (p[1] == '[')
    {
        return CSI;
    }
    else if (p[1] == ']')
    {
        return OSC;
    }
    else if (p[1] == 'O')
    {
        return 0x8f;
    }
    return 0;
}

    static char_u *
tltoa(unsigned long i)
{
    static char_u buf[16];
    char_u      *p;

    p = buf + 15;
    *p = '\0';
    do
    {
        --p;
        *p = (char_u) (i % 10 + '0');
        i /= 10;
    }
    while (i > 0 && p > buf)
        ;
    return p;
}

    static char *
tgoto(char *cm, int x, int y)
{
    static char buf[30];
    char *p;
    char *s;
    char *e;

    if (!cm)
    {
        return "OOPS";
    }
    e = buf + 29;
    for (s = buf; s < e && *cm; cm++)
    {
        if (*cm != '%')
        {
            *s++ = *cm;
            continue;
        }
        switch (*++cm)
        {
        case 'd':
            p = (char *)tltoa((unsigned long)y);
            y = x;
            while (*p)
            {
                *s++ = *p++;
            }
            break;
        case 'i':
            x++;
            y++;
            break;
        case '+':
            *s++ = (char)(*++cm + y);
            y = x;
            break;
        case '%':
            *s++ = *cm;
            break;
        default:
            return "OOPS";
        }
    }
    *s = '\0';
    return buf;
}

