    static void
ttest(int pairs)
{

    check_options();

    if (* ( term_strings[(int)(KS_CM)] )  == NUL)
    {
        emsg(_(e_terminal_capability_cm_required));
    }

    if (* ( term_strings[(int)(KS_CS)] )  != NUL)
    {
        scroll_region = TRUE;
    }
    else
    {
        scroll_region = FALSE;
    }

    if (pairs)
    {
        if (* ( term_strings[(int)(KS_ME)] )  == NUL)
        {
             ( term_strings[(int)(KS_ME)] )  =  ( term_strings[(int)(KS_MR)] )  =  ( term_strings[(int)(KS_MD)] )  =  ( term_strings[(int)(KS_MB)] )  = empty_option;
        }
        if (* ( term_strings[(int)(KS_SO)] )  == NUL || * ( term_strings[(int)(KS_SE)] )  == NUL)
        {
             ( term_strings[(int)(KS_SO)] )  =  ( term_strings[(int)(KS_SE)] )  = empty_option;
        }
        if (* ( term_strings[(int)(KS_US)] )  == NUL || * ( term_strings[(int)(KS_UE)] )  == NUL)
        {
             ( term_strings[(int)(KS_US)] )  =  ( term_strings[(int)(KS_UE)] )  = empty_option;
        }
        if (* ( term_strings[(int)(KS_CZH)] )  == NUL || * ( term_strings[(int)(KS_CZR)] )  == NUL)
        {
             ( term_strings[(int)(KS_CZH)] )  =  ( term_strings[(int)(KS_CZR)] )  = empty_option;
        }

        if (* ( term_strings[(int)(KS_VE)] )  == NUL)
        {
             ( term_strings[(int)(KS_VI)] )  = empty_option;
        }

        if (* ( term_strings[(int)(KS_ME)] )  == NUL)
        {
             ( term_strings[(int)(KS_ME)] )  =  ( term_strings[(int)(KS_SE)] ) ;
             ( term_strings[(int)(KS_MR)] )  =  ( term_strings[(int)(KS_SO)] ) ;
             ( term_strings[(int)(KS_MD)] )  =  ( term_strings[(int)(KS_SO)] ) ;
        }

        if (* ( term_strings[(int)(KS_SO)] )  == NUL)
        {
             ( term_strings[(int)(KS_SE)] )  =  ( term_strings[(int)(KS_ME)] ) ;
            if (* ( term_strings[(int)(KS_MR)] )  == NUL)
            {
                 ( term_strings[(int)(KS_SO)] )  =  ( term_strings[(int)(KS_MD)] ) ;
            }
            else
            {
                 ( term_strings[(int)(KS_SO)] )  =  ( term_strings[(int)(KS_MR)] ) ;
            }
        }

        if (* ( term_strings[(int)(KS_CZH)] )  == NUL)
        {
             ( term_strings[(int)(KS_CZR)] )  =  ( term_strings[(int)(KS_ME)] ) ;
            if (* ( term_strings[(int)(KS_MR)] )  == NUL)
            {
                 ( term_strings[(int)(KS_CZH)] )  =  ( term_strings[(int)(KS_MD)] ) ;
            }
            else
            {
                 ( term_strings[(int)(KS_CZH)] )  =  ( term_strings[(int)(KS_MR)] ) ;
            }
        }

        if (* ( term_strings[(int)(KS_CSB)] )  == NUL || * ( term_strings[(int)(KS_CSF)] )  == NUL)
        {
             ( term_strings[(int)(KS_CSB)] )  = empty_option;
             ( term_strings[(int)(KS_CSF)] )  = empty_option;
        }

        if (* ( term_strings[(int)(KS_CAB)] )  == NUL || * ( term_strings[(int)(KS_CAF)] )  == NUL)
        {
             ( term_strings[(int)(KS_CAB)] )  = empty_option;
             ( term_strings[(int)(KS_CAF)] )  = empty_option;
        }

        if (* ( term_strings[(int)(KS_CSB)] )  == NUL && * ( term_strings[(int)(KS_CAB)] )  == NUL)
        {
            free_one_termoption( ( term_strings[(int)(KS_CCO)] ) );
        }

        p_wiv = (* ( term_strings[(int)(KS_XS)] )  != NUL);
    }
    need_gather = TRUE;

    t_colors = atoi((char *) ( term_strings[(int)(KS_CCO)] ) );
}

    static int
get_bytes_from_buf(char_u *buf, char_u *bytes, int num_bytes)
{
    int     len = 0;
    int     i;
    char_u  c;

    for (i = 0; i < num_bytes; i++)
    {
        if ((c = buf[len++]) == NUL)
        {
            return -1;
        }
        if (c ==  (0x80) )
        {
            if (buf[len] == NUL || buf[len + 1] == NUL)
            {
                return -1;
            }
            if (buf[len++] == (int)KS_ZERO)
            {
                c = NUL;
            }
            if (buf[len++] == (int)KE_CSI)
            {
                c = CSI;
            }
        }
        else if (c == CSI && buf[len] == KS_EXTRA && buf[len + 1] == (int)KE_CSI)
        {
            len += 2;
        }
        bytes[i] = c;
    }
    return len;
}

    static void
check_shellsize(void)
{
    if (Rows < min_rows_for_all_tabpages())
    {
        Rows = min_rows_for_all_tabpages();
    }
    limit_screen_size();

    if (cmdline_row >= Rows)
    {
        cmdline_row = Rows - 1;
    }
    if (msg_row >= Rows)
    {
        msg_row = Rows - 1;
    }
}

    static void
limit_screen_size(void)
{
    if (Columns < MIN_COLUMNS)
    {
        Columns = MIN_COLUMNS;
    }
    else if (Columns > 10000)
    {
        Columns = 10000;
    }
    if (Rows > 1000)
    {
        Rows = 1000;
    }
}

    static void
win_new_shellsize(void)
{
    static int  old_Rows = 0;
    static int  old_Columns = 0;
    static int  old_coloff = 0;

    if (old_Rows != Rows || old_Columns !=  Columns  || old_coloff !=  0 )
    {
        ui_new_shellsize();
    }
    if (old_Columns !=  Columns  || old_coloff !=  0 )
    {
        old_Columns =  Columns ;
        old_coloff =  0 ;

        shell_new_columns();
    }
    if (old_Rows != Rows)
    {
        if (p_window == old_Rows - 1 || (old_Rows == 0 && !option_was_set((char_u *)"window")))
        {
            p_window = Rows - 1;
        }
        old_Rows = Rows;
        shell_new_rows();
    }
}

    static void
shell_resized(void)
{
    set_shellsize(0, 0, FALSE);
}

    static void
set_shellsize_inner(int width, int height, int mustset)
{
    if (updating_screen)
    {
        return;
    }

    if (curwin->w_buffer == NULL || curwin->w_lines == NULL)
    {
        return;
    }

    if (mustset || (ui_get_shellsize() == FAIL && height != 0))
    {
        Rows = height;
        Columns = width;
        check_shellsize();
        ui_set_shellsize(mustset);
    }
    else
    {
        check_shellsize();
    }

    if (State != MODE_ASKMORE && State != MODE_EXTERNCMD && State != MODE_CONFIRM)
    {
        screenclear();
    }
    else
    {
        screen_start();
    }

    if (starting != NO_SCREEN)
    {
        maketitle();

        changed_line_abv_curs();
        invalidate_botline();

        if (State == MODE_ASKMORE || State == MODE_EXTERNCMD || State == MODE_CONFIRM || exmode_active)
        {
            screenalloc(FALSE);
            repeat_message();
        }
        else
        {
            if (curwin-> w_onebuf_opt.wo_scb )
            {
                do_check_scrollbind(TRUE);
            }
            if (State & MODE_CMDLINE)
            {
                update_screen(UPD_NOT_VALID);
                redrawcmdline();
            }
            else
            {
                update_topline();
                if (pum_visible())
                {
                    redraw_later(UPD_NOT_VALID);
                    ins_compl_show_pum();
                }
                update_screen(UPD_NOT_VALID);
                if (redrawing())
                {
                    setcursor();
                }
            }
        }
        cursor_on();
    }
    out_flush();
}

    static void
set_shellsize(int width, int height, int mustset)
{
    static int  busy = FALSE;
    static int  do_run = FALSE;

    if (width < 0 || height < 0)
    {
        return;
    }

    if (State ==  (0x2000 | MODE_NORMAL)  || State == MODE_SETWSIZE)
    {
        State = MODE_SETWSIZE;
        return;
    }

    do_run = TRUE;
    if (busy)
    {
        return;
    }

    while (do_run)
    {
        do_run = FALSE;
        busy = TRUE;
        set_shellsize_inner(width, height, mustset);
        busy = FALSE;
    }
}

    static void
out_str_t_TE(void)
{
    out_str( ( term_strings[(int)(KS_CTE)] ) );

    if (modify_otherkeys_state == MOKS_ENABLED || modify_otherkeys_state == MOKS_DISABLED)
    {
        modify_otherkeys_state = MOKS_DISABLED;
    }
    else if (modify_otherkeys_state != MOKS_INITIAL)
    {
        modify_otherkeys_state = MOKS_AFTER_T_TE;
    }

    if (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED)
    {
        kitty_protocol_state = KKPS_DISABLED;
    }
    else
    {
        kitty_protocol_state = KKPS_AFTER_T_TE;
    }
}

static int send_t_RK = FALSE;

    static void
out_str_t_TI(void)
{
    out_str( ( term_strings[(int)(KS_CTI)] ) );

    send_t_RK = TRUE;
}

    static void
out_str_t_BE(void)
{
    char_u *p;

    if ( ( term_strings[(int)(KS_CBE)] )  == NULL || * ( term_strings[(int)(KS_CBE)] )  == NUL || (p = find_termcode((char_u *)"PS")) == NULL || *p == NUL || (p = find_termcode((char_u *)"PE")) == NULL || *p == NUL)
    {
        return;
    }
    out_str( ( term_strings[(int)(KS_CBE)] ) );
}

