    static void
settmode(tmode_T tmode)
{
    if (!full_screen)
    {
        return;
    }

    if (tmode != cur_tmode)
    {
        if (tmode != TMODE_RAW)
        {
            mch_setmouse(FALSE);
        }

        if (termcap_active && tmode != TMODE_SLEEP && cur_tmode != TMODE_SLEEP)
        {
              ;

            if (tmode != TMODE_RAW)
            {
                out_str( ( term_strings[(int)(KS_CBD)] ) );
                out_str_t_TE();
            }
            else
            {
                out_str_t_BE();
                out_str_t_TI();
            }
        }
        out_flush();
        mch_settmode(tmode);
        cur_tmode = tmode;
        if (tmode == TMODE_RAW)
        {
            setmouse();
        }
        out_flush();
    }
}

    static void
starttermcap(void)
{
    if (!full_screen || termcap_active)
    {
        return;
    }

      ;

    out_str( ( term_strings[(int)(KS_TI)] ) );
    out_str_t_TI();
    out_str( ( term_strings[(int)(KS_KS)] ) );
    out_str_t_BE();

    if (p_ek && * ( term_strings[(int)(KS_FE)] )  != NUL)
    {
        out_str( ( term_strings[(int)(KS_FE)] ) );
    }

    out_flush();
    termcap_active = TRUE;
    screen_start();
}

    static void
stoptermcap(void)
{
    screen_stop_highlight();
    reset_cterm_colors();

    if (!termcap_active)
    {
        return;
    }

      ;

    if (p_ek && * ( term_strings[(int)(KS_FD)] )  != NUL)
    {
        out_str( ( term_strings[(int)(KS_FD)] ) );
    }

    out_str( ( term_strings[(int)(KS_CBD)] ) );
    out_str( ( term_strings[(int)(KS_KE)] ) );
    out_flush();
    termcap_active = FALSE;

    if (* ( term_strings[(int)(KS_TE)] )  != NUL && (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED))
    {
        out_str_t_TE();
    }

    out_str( ( term_strings[(int)(KS_TE)] ) );
    cursor_on();
    out_str_t_TE();
    screen_start();
    out_flush();
}

    static int
swapping_screen(void)
{
    return (full_screen && * ( term_strings[(int)(KS_TI)] )  != NUL);
}

    static void
scroll_start(void)
{
    if (* ( term_strings[(int)(KS_VS)] )  == NUL || * ( term_strings[(int)(KS_CVS)] )  == NUL)
    {
        return;
    }

      ;
    out_str( ( term_strings[(int)(KS_VS)] ) );
    out_str( ( term_strings[(int)(KS_CVS)] ) );
    screen_start();
}

