    static void
ui_write(char_u *s, int len, int console  __attribute__((unused)) )
{
    if (!(silent_mode && p_verbose == 0))
    {
        char_u  *tofree = NULL;

        if (output_conv.vc_type != CONV_NONE)
        {
            tofree = string_convert(&output_conv, s, &len);
            if (tofree != NULL)
            {
                s = tofree;
            }
        }

        mch_write(s, len);
        if (console && s[len - 1] == '\n')
        {
            vim_fsync(1);
        }

        if (output_conv.vc_type != CONV_NONE)
        {
            vim_free(tofree);
        }
    }
}

    static int
ui_inchar(char_u      *buf, int         maxlen, long        wtime, int         tb_change_cnt)
{
    int         retval = 0;

    if (wtime == -1 || wtime > 100L)
    {
        (void)vim_handle_signal( (-2) );

        if ((mapped_ctrl_c | curbuf->b_mapped_ctrl_c) & get_real_state())
        {
            ctrl_c_interrupts = FALSE;
        }
    }

        retval = mch_inchar(buf, maxlen, wtime, tb_change_cnt);

    if (wtime == -1 || wtime > 100L)
    {
        (void)vim_handle_signal( (-1) );
    }

    ctrl_c_interrupts = TRUE;

    return retval;
}

    static int
inchar_loop(char_u      *buf, int         maxlen, long        wtime, int         tb_change_cnt, int         (*wait_func)(long wtime, int *interrupted, int ignore_input), int         (*resize_func)(int check_only))
{
    int         len;
    int         interrupted = FALSE;
    int         did_call_wait_func = FALSE;
    int         did_start_blocking = FALSE;
    long        wait_time;
    long        elapsed_time = 0;
    elapsed_T   start_tv;

     gettimeofday(&(start_tv), NULL) ;

    for (;;)
    {
        if (resize_func != NULL)
        {
            resize_func(FALSE);
        }

        bool delay_pending = ins_compl_autocomplete_pending() && p_acl > 0
                && typebuf.tb_len == 0
                && !ins_compl_active()
                && (get_real_state() & MODE_INSERT) != 0;
        long acl_elapsed = delay_pending ? ins_compl_autocomplete_elapsed() : 0;

        if (wtime < 0 && did_start_blocking && !delay_pending)
        {
            wait_time = -1;
        }
        else
        {
            elapsed_time =  elapsed(&(start_tv)) ;
            if (wtime >= 0)
            {
                wait_time = wtime - elapsed_time;
            }
            else if (delay_pending)
            {
                long delay_left = p_acl - acl_elapsed;
                long ut_left = p_ut - elapsed_time;

                if (did_start_blocking)
                {
                    wait_time = delay_left;
                }
                else
                {
                    wait_time = MIN(delay_left, ut_left);
                }
            }
            else
            {
                wait_time = p_ut - elapsed_time;
            }

            if (wait_time <= 0 && did_call_wait_func)
            {
                if (wtime >= 0)
                {
                    return 0;
                }

                if (delay_pending && acl_elapsed >= p_acl && maxlen >= 3 && !typebuf_changed(tb_change_cnt))
                {
                    if (buf == NULL)
                    {
                        char_u  ibuf[3];

                        ibuf[0] = CSI;
                        ibuf[1] = KS_EXTRA;
                        ibuf[2] = (int)KE_COMPLETE_DELAY;
                        add_to_input_buf(ibuf, 3);
                    }
                    else
                    {
                        buf[0] =  (0x80) ;
                        buf[1] = KS_EXTRA;
                        buf[2] = (int)KE_COMPLETE_DELAY;
                    }
                    return 3;
                }

                did_start_blocking = TRUE;
                if (trigger_cursorhold() && maxlen >= 3 && !typebuf_changed(tb_change_cnt))
                {
                    if (buf == NULL)
                    {
                        char_u  ibuf[3];

                        ibuf[0] = CSI;
                        ibuf[1] = KS_EXTRA;
                        ibuf[2] = (int)KE_CURSORHOLD;
                        add_to_input_buf(ibuf, 3);
                    }
                    else
                    {
                        buf[0] =  (0x80) ;
                        buf[1] = KS_EXTRA;
                        buf[2] = (int)KE_CURSORHOLD;
                    }
                    return 3;
                }

                before_blocking();
                continue;
            }
        }

        did_call_wait_func = TRUE;
        if (wait_func(wait_time, &interrupted, FALSE))
        {
            if (typebuf_changed(tb_change_cnt))
            {
                return 0;
            }

            if (buf == NULL)
            {
                return input_available();
            }

            len = read_from_input_buf(buf, (long)maxlen);
            if (len > 0)
            {
                return len;
            }
            continue;
        }

        if ((resize_func != NULL && resize_func(TRUE)) || wait_time > 0 || (wtime < 0 && !did_start_blocking))
        {
            continue;
        }

        break;
    }
    return 0;
}

    static int
ui_char_avail(void)
{
    return mch_char_avail();
}

    static void
ui_delay(long msec_arg, int ignoreinput)
{
    long msec = msec_arg;

        mch_delay(msec, ignoreinput ? MCH_DELAY_IGNOREINPUT : 0);
}

    static void
ui_suspend(void)
{
    mch_suspend();
}

