    static char_u *
find_ucmd(exarg_T     *eap, char_u      *p, int         *full, expand_T    *xp, int         *complp)
{
    int         len = (int)(p - eap->cmd);
    int j;
    int k;
    int matchlen = 0;
    ucmd_T      *uc;
    int         found = FALSE;
    int         possible = FALSE;
    char_u *cp;
    char_u *np;
    garray_T    *gap;
    int         amb_local = FALSE;

    gap = &prevwin_curwin()->w_buffer->b_ucmds;
    for (;;)
    {
        for (j = 0; j < gap->ga_len; ++j)
        {
            uc =  (&((ucmd_T *)((gap)->ga_data))[j]) ;
            cp = eap->cmd;
            np = uc->uc_name;
            k = 0;
            while (k < len && *np != NUL && *cp++ == *np++)
            {
                k++;
            }
            if (k == len || (*np == NUL && vim_isdigit(eap->cmd[k])))
            {
                if (k == len && found && *np != NUL)
                {
                    if (gap == &ucmds)
                    {
                        return NULL;
                    }
                    amb_local = TRUE;
                }

                if (!found || (k == len && *np == NUL))
                {
                    if (k == len)
                    {
                        found = TRUE;
                    }
                    else
                    {
                        possible = TRUE;
                    }

                    if (gap == &ucmds)
                    {
                        eap->cmdidx = CMD_USER;
                    }
                    else
                    {
                        eap->cmdidx = CMD_USER_BUF;
                    }
                    eap->argt = (long)uc->uc_argt;
                    eap->useridx = j;
                    eap->addr_type = uc->uc_addr_type;

                    if (complp != NULL)
                    {
                        *complp = uc->uc_compl;
                    }
                    matchlen = k;
                    if (k == len && *np == NUL)
                    {
                        if (full != NULL)
                        {
                            *full = TRUE;
                        }
                        amb_local = FALSE;
                        break;
                    }
                }
            }
        }

        if (j < gap->ga_len || gap == &ucmds)
        {
            break;
        }
        gap = &ucmds;
    }

    if (amb_local)
    {
        if (xp != NULL)
        {
            xp->xp_context =  (-2) ;
        }
        return NULL;
    }

    if (found || possible)
    {
        return p + (matchlen - len);
    }
    return p;
}

    static char_u *
set_context_in_user_cmd(expand_T *xp, char_u *arg_in)
{
    char_u      *arg = arg_in;
    char_u      *p;

    while (*arg == '-')
    {
        arg++;
        p = skiptowhite(arg);
        if (*p == NUL)
        {
            p = vim_strchr(arg, '=');
            if (p == NULL)
            {
                xp->xp_context = EXPAND_USER_CMD_FLAGS;
                xp->xp_pattern = arg;
                return NULL;
            }

            if ( strncasecmp((char *)(arg), (char *)("complete"), (p - arg))  == 0)
            {
                xp->xp_context = EXPAND_USER_COMPLETE;
                xp->xp_pattern = p + 1;
            }
            else if ( strncasecmp((char *)(arg), (char *)("completeopt"), (p - arg))  == 0)
            {
                xp->xp_context = EXPAND_USER_COMPLETEOPT;
                xp->xp_pattern = p + 1;
                for (char_u *c = p + 1; *c != NUL; ++c)
                {
                    if (*c == ',')
                    {
                        xp->xp_pattern = c + 1;
                    }
                }
            }
            else if ( strncasecmp((char *)(arg), (char *)("nargs"), (p - arg))  == 0)
            {
                xp->xp_context = EXPAND_USER_NARGS;
                xp->xp_pattern = p + 1;
            }
            else if ( strncasecmp((char *)(arg), (char *)("addr"), (p - arg))  == 0)
            {
                xp->xp_context = EXPAND_USER_ADDR_TYPE;
                xp->xp_pattern = p + 1;
            }
            return NULL;
        }
        arg = skipwhite(p);
    }

    p = skiptowhite(arg);
    if (*p == NUL)
    {
        xp->xp_context = EXPAND_USER_COMMANDS;
        xp->xp_pattern = arg;
        return NULL;
    }

    return skipwhite(p);
}

    static char_u *
set_context_in_user_cmdarg(char_u          *cmd  __attribute__((unused)) , char_u          *arg, long            argt, int             context, expand_T        *xp, int             forceit)
{
    char_u      *p;

    if (context == EXPAND_NOTHING)
    {
        return NULL;
    }

    if (argt & EX_XFILE)
    {
        return NULL;
    }

    if (context == EXPAND_COMMANDS)
    {
        return arg;
    }
    if (context == EXPAND_MAPPINGS)
    {
        return set_context_in_map_cmd(xp, (char_u *)"map", arg, forceit, FALSE, FALSE, CMD_map);
    }
    if (!(argt & EX_ARGSPACE))
    {
        p = arg;
        while (*p)
        {
            if (*p == ' ')
            {
                arg = p + 1;
            }
            else if (*p == '\\' && *(p + 1) != NUL)
            {
                ++p;
            }
             p += (*mb_ptr2len)(p) ;
        }
    }
    xp->xp_pattern = arg;
    xp->xp_context = context;

    return NULL;
}

    static char_u *
expand_user_command_name(int idx)
{
    return get_user_commands(NULL, idx - (int)CMD_SIZE);
}

    static char_u *
get_user_commands(expand_T *xp  __attribute__((unused)) , int idx)
{
    buf_T *buf = prevwin_curwin()->w_buffer;

    if (idx < buf->b_ucmds.ga_len)
    {
        return  (&((ucmd_T *)((&buf->b_ucmds)->ga_data))[idx]) ->uc_name;
    }

    idx -= buf->b_ucmds.ga_len;
    if (idx < ucmds.ga_len)
    {
        int     i;
        char_u  *name =  (&((ucmd_T *)(ucmds.ga_data))[idx]) ->uc_name;

        for (i = 0; i < buf->b_ucmds.ga_len; ++i)
        {
            if ( strcmp((char *)(name), (char *)( (&((ucmd_T *)((&buf->b_ucmds)->ga_data))[i]) ->uc_name))  == 0)
            {
                return (char_u *)"";
            }
        }
        return name;
    }
    return NULL;
}

