static char *m_onlyone =  "Already only one window" ;

static int split_disallowed = 0;

static int close_disallowed = 0;

static int frame_locked = 0;

    static void
window_layout_lock(void)
{
    ++split_disallowed;
    ++close_disallowed;
}

    static void
window_layout_unlock(void)
{
    --split_disallowed;
    --close_disallowed;
}

    static int
window_layout_locked(enum CMD_index cmd)
{
    if (split_disallowed > 0 || close_disallowed > 0)
    {
        if (close_disallowed == 0 && cmd == CMD_tabnew)
        {
            emsg(_(e_cannot_split_window_when_closing_buffer));
        }
        else
        {
            emsg(_(e_not_allowed_to_change_window_layout_in_this_autocmd));
        }
        return TRUE;
    }
    return FALSE;
}

    static int
check_can_set_curbuf_disabled(void)
{
    if (curwin-> w_onebuf_opt.wo_wfb )
    {
        emsg(_(e_winfixbuf_cannot_go_to_buffer));
        return FALSE;
    }
    return TRUE;
}

    static int
check_can_set_curbuf_forceit(int forceit)
{
    if (!forceit && curwin-> w_onebuf_opt.wo_wfb )
    {
        emsg(_(e_winfixbuf_cannot_go_to_buffer));
        return FALSE;
    }
    return TRUE;
}

    static win_T *
prevwin_curwin(void)
{
    return is_in_cmdwin() && prevwin != NULL ? prevwin : curwin;
}

    static win_T *
swbuf_goto_win_with_buf(buf_T *buf)
{
    win_T   *wp = NULL;

    if (buf == NULL)
    {
        return wp;
    }

    if (swb_flags & SWB_USEOPEN)
    {
        wp = buf_jump_open_win(buf);
    }

    if (wp == NULL && (swb_flags & SWB_USETAB))
    {
        wp = buf_jump_open_tab(buf);
    }

    return wp;
}

    static void
do_window(int         nchar, long        Prenum, int         xchar)
{
    long        Prenum1;
    win_T       *wp;
    char_u      *ptr;
    linenr_T    lnum = -1;
    char_u      cbuf[40];

    if (ERROR_IF_ANY_POPUP_WINDOW)
    {
        return;
    }

    Prenum1 = Prenum == 0 ? 1 : Prenum;

    switch (nchar)
    {
    case 'S':
    case Ctrl_S:
    case 's':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                reset_VIsual_and_resel();
                if (bt_quickfix(curbuf))
                {
                    goto newwindow;
                }
                (void)win_split((int)Prenum, 0);
                break;

    case Ctrl_V:
    case 'v':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                reset_VIsual_and_resel();
                if (bt_quickfix(curbuf))
                {
                    goto newwindow;
                }
                (void)win_split((int)Prenum, WSP_VERT);
                break;

    case Ctrl_HAT:
    case '^':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                reset_VIsual_and_resel();

                if (buflist_findnr(Prenum == 0 ? curwin->w_alt_fnum : Prenum) == NULL)
                {
                    if (Prenum == 0)
                    {
                        emsg(_(e_no_alternate_file));
                    }
                    else
                    {
                        semsg(_(e_buffer_nr_not_found), Prenum);
                    }
                    break;
                }

                if (!curbuf_locked() && win_split(0, 0) == OK)
                {
                    (void)buflist_getfile(Prenum == 0 ? curwin->w_alt_fnum : Prenum, (linenr_T)0, GETF_ALT, FALSE);
                }
                break;

    case Ctrl_N:
    case 'n':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                reset_VIsual_and_resel();
newwindow:
                if (Prenum)
                {
                    vim_snprintf((char *)cbuf, sizeof(cbuf) - 5, "%ld", Prenum);
                }
                else
                {
                    cbuf[0] = NUL;
                }
                 strcat((char *)(cbuf), (char *)("new")) ;
                do_cmdline_cmd(cbuf);
                break;

    case Ctrl_Q:
    case 'q':
                reset_VIsual_and_resel();
                cmd_with_count("quit", cbuf, sizeof(cbuf), Prenum);
                do_cmdline_cmd(cbuf);
                break;

    case Ctrl_C:
    case 'c':
                reset_VIsual_and_resel();
                cmd_with_count("close", cbuf, sizeof(cbuf), Prenum);
                do_cmdline_cmd(cbuf);
                break;

    case Ctrl_O:
    case 'o':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                reset_VIsual_and_resel();
                cmd_with_count("only", cbuf, sizeof(cbuf), Prenum);
                do_cmdline_cmd(cbuf);
                break;

    case Ctrl_W:
    case 'w':
    case 'W':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                if ( (firstwin == lastwin)  && Prenum != 1)
                {
                    beep_flush();
                }
                else
                {
                    if (Prenum)
                    {
                        for (wp = firstwin; --Prenum > 0; )
                        {
                            if (wp->w_next == NULL)
                            {
                                break;
                            }
                            else
                            {
                                wp = wp->w_next;
                            }
                        }
                    }
                    else
                    {
                        if (nchar == 'W')
                        {
                            wp = curwin->w_prev;
                            if (wp == NULL)
                            {
                                wp = lastwin;
                            }
                        }
                        else
                        {
                            wp = curwin->w_next;
                            if (wp == NULL)
                            {
                                wp = firstwin;
                            }
                        }
                    }
                    win_goto(wp);
                }
                break;

    case 'j':
    case   (-(('k') + ((int)('d') << 8)))  :
    case Ctrl_J:
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                win_goto_ver(FALSE, Prenum1);
                break;

    case 'k':
    case   (-(('k') + ((int)('u') << 8)))  :
    case Ctrl_K:
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                win_goto_ver(TRUE, Prenum1);
                break;

    case 'h':
    case   (-(('k') + ((int)('l') << 8)))  :
    case Ctrl_H:
    case   (-(('k') + ((int)('b') << 8)))  :
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                win_goto_hor(TRUE, Prenum1);
                break;

    case 'l':
    case   (-(('k') + ((int)('r') << 8)))  :
    case Ctrl_L:
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                win_goto_hor(FALSE, Prenum1);
                break;

    case 'T':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                if (one_window())
                {
                    msg(_(m_onlyone));
                }
                else
                {
                    tabpage_T   *oldtab = curtab;
                    tabpage_T   *newtab;

                    wp = curwin;
                    if (win_new_tabpage((int)Prenum) == OK && valid_tabpage(oldtab))
                    {
                        newtab = curtab;
                        goto_tabpage_tp(oldtab, TRUE, TRUE);
                        if (curwin == wp)
                        {
                            win_close(curwin, FALSE);
                        }
                        if (valid_tabpage(newtab))
                        {
                            goto_tabpage_tp(newtab, TRUE, TRUE);
                        }
                    }
                }
                break;

    case 't':
    case Ctrl_T:
                win_goto(firstwin);
                break;

    case 'b':
    case Ctrl_B:
                win_goto(lastwin);
                break;

    case 'p':
    case Ctrl_P:
                if (!win_valid(prevwin))
                {
                    beep_flush();
                }
                else
                {
                    win_goto(prevwin);
                }
                break;

    case 'x':
    case Ctrl_X:
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                win_exchange(Prenum);
                break;

    case Ctrl_R:
    case 'r':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                reset_VIsual_and_resel();
                win_rotate(FALSE, (int)Prenum1);
                break;

    case 'R':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                reset_VIsual_and_resel();
                win_rotate(TRUE, (int)Prenum1);
                break;

    case 'K':
    case 'J':
    case 'H':
    case 'L':
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                if ( (firstwin == lastwin) )
                {
                    beep_flush();
                }
                else
                {
                    int dir = ((nchar == 'H' || nchar == 'L') ? WSP_VERT : 0)
                         | ((nchar == 'H' || nchar == 'K') ? WSP_TOP : WSP_BOT);

                    (void)win_splitmove(curwin, (int)Prenum, dir);
                }
                break;

    case '=':
                {
                    int mod = cmdmod.cmod_split & (WSP_VERT | WSP_HOR);
                    win_equal(NULL, FALSE, mod == WSP_VERT ? 'v' : mod == WSP_HOR ? 'h' : 'b');
                }
                break;

    case '+':
                win_setheight(curwin->w_height + (int)Prenum1);
                break;

    case '-':
                win_setheight(curwin->w_height - (int)Prenum1);
                break;

    case Ctrl__:
    case '_':
                win_setheight(Prenum ? (int)Prenum : 9999);
                break;

    case '>':
                win_setwidth(curwin->w_width + (int)Prenum1);
                break;

    case '<':
                win_setwidth(curwin->w_width - (int)Prenum1);
                break;

    case '|':
                win_setwidth(Prenum != 0 ? (int)Prenum : 9999);
                break;

    case ']':
    case Ctrl_RSB:
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                if (Prenum)
                {
                    postponed_split = Prenum;
                }
                else
                {
                    postponed_split = -1;
                }

                do_nv_ident(Ctrl_RSB, NUL);
                postponed_split = 0;
                break;

    case 'f':
    case 'F':
    case Ctrl_F:
wingotofile:
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                if (check_text_or_curbuf_locked(NULL))
                {
                    break;
                }

                ptr = grab_file_name(Prenum1, &lnum);
                if (ptr != NULL)
                {
                    tabpage_T   *oldtab = curtab;
                    win_T       *oldwin = curwin;
                    setpcmark();

                    wp = NULL;
                    if ((swb_flags & (SWB_USEOPEN | SWB_USETAB)) && cmdmod.cmod_tab == 0)
                    {
                        wp = swbuf_goto_win_with_buf(buflist_findname_exp(ptr));
                    }

                    if (wp == NULL && win_split(0, 0) == OK)
                    {
                         (curwin)-> w_onebuf_opt.wo_scb  = FALSE;
                         (curwin)-> w_onebuf_opt.wo_crb  = FALSE;
                        if (do_ecmd(0, ptr, NULL, NULL,  (linenr_T)0 , ECMD_HIDE, NULL) == FAIL)
                        {
                            sig_atomic_t    old_got_int = got_int;
                            got_int = FALSE;

                            win_close(curwin, FALSE);
                            got_int = got_int || old_got_int;

                            goto_tabpage_win(oldtab, oldwin);
                        }
                        else
                        {
                            wp = curwin;
                        }
                    }

                    if (wp != NULL && nchar == 'F' && lnum >= 0)
                    {
                        curwin->w_cursor.lnum = lnum;
                        check_cursor_lnum();
                        beginline(BL_SOL | BL_FIX);
                    }
                    vim_free(ptr);
                }
                break;

    case 'g':
    case Ctrl_G:
                 if (cmdwin_type != 0)
                     {           emsg(_(e_invalid_in_cmdline_window));           return;     }
                ++no_mapping;
                ++allow_keys;
                if (xchar == NUL)
                {
                    xchar = plain_vgetc();
                }
                  ;
                --no_mapping;
                --allow_keys;
                (void)add_to_showcmd(xchar);

                switch (xchar)
                {
                    case ']':
                    case Ctrl_RSB:
                        if (Prenum)
                        {
                            postponed_split = Prenum;
                        }
                        else
                        {
                            postponed_split = -1;
                        }

                        do_nv_ident('g', xchar);
                        postponed_split = 0;
                        break;

                    case 'f':
                    case 'F':
                        cmdmod.cmod_tab = tabpage_index(curtab) + 1;
                        nchar = xchar;
                        goto wingotofile;

                    case 't':
                        goto_tabpage((int)Prenum);
                        break;

                    case 'T':
                        goto_tabpage(-(int)Prenum1);
                        break;

                    case TAB:
                        if (goto_tabpage_lastused() == FAIL)
                        {
                            beep_flush();
                        }
                        break;

                    default:
                        beep_flush();
                        break;
                }
                break;

    default:
        beep_flush();
                break;
    }
}

    static void
get_wincmd_addr_type(char_u *arg, exarg_T *eap)
{
    switch (*arg)
    {
    case 'S':
    case Ctrl_S:
    case 's':
    case Ctrl_N:
    case 'n':
    case 'j':
    case Ctrl_J:
    case 'k':
    case Ctrl_K:
    case 'T':
    case Ctrl_R:
    case 'r':
    case 'R':
    case 'K':
    case 'J':
    case '+':
    case '-':
    case Ctrl__:
    case '_':
    case '|':
    case ']':
    case Ctrl_RSB:
    case 'g':
    case Ctrl_G:
    case Ctrl_V:
    case 'v':
    case 'h':
    case Ctrl_H:
    case 'l':
    case Ctrl_L:
    case 'H':
    case 'L':
    case '>':
    case '<':
    case 'f':
    case 'F':
    case Ctrl_F:
                eap->addr_type = ADDR_OTHER;
                break;

    case Ctrl_HAT:
    case '^':
                eap->addr_type = ADDR_BUFFERS;
                break;

    case Ctrl_Q:
    case 'q':
    case Ctrl_C:
    case 'c':
    case Ctrl_O:
    case 'o':
    case Ctrl_W:
    case 'w':
    case 'W':
    case 'x':
    case Ctrl_X:
                eap->addr_type = ADDR_WINDOWS;
                break;

    case 't':
    case Ctrl_T:
    case 'b':
    case Ctrl_B:
    case 'p':
    case Ctrl_P:
    case '=':
    case CAR:
                eap->addr_type = ADDR_NONE;
                break;
    }
}

    static void
cmd_with_count(char        *cmd, char_u      *bufp, size_t      bufsize, long        Prenum)
{
    if (Prenum > 0)
    {
        vim_snprintf((char *)bufp, bufsize, "%s %ld", cmd, Prenum);
    }
    else
    {
         strcpy((char *)(bufp), (char *)(cmd)) ;
    }
}

    static int
check_split_disallowed(win_T *wp)
{
    if (split_disallowed > 0)
    {
        emsg(_(e_cant_split_window_while_closing_another));
        return FAIL;
    }
    if (wp->w_buffer->b_locked_split)
    {
        emsg(_(e_cannot_split_window_when_closing_buffer));
        return FAIL;
    }
    return OK;
}

    static int
win_split(int size, int flags)
{
    if (ERROR_IF_ANY_POPUP_WINDOW)
    {
        return FAIL;
    }

    if (check_split_disallowed(curwin) == FAIL)
    {
        return FAIL;
    }

    if (may_open_tabpage() == OK)
    {
        return OK;
    }

    flags |= cmdmod.cmod_split;
    if ((flags & WSP_TOP) && (flags & WSP_BOT))
    {
        emsg(_(e_cant_split_topleft_and_botright_at_the_same_time));
        return FAIL;
    }

    if (flags & WSP_HELP)
    {
        make_snapshot(SNAP_HELP_IDX);
    }
    else
    {
        clear_snapshot(curtab, SNAP_HELP_IDX);
    }

    if (flags & WSP_QUICKFIX)
    {
        make_snapshot(SNAP_QUICKFIX_IDX);
    }
    else
    {
        clear_snapshot(curtab, SNAP_QUICKFIX_IDX);
    }

    return win_split_ins(size, flags, NULL, 0, NULL);
}

    static int
win_split_ins(int         size, int         flags, win_T       *new_wp, int         dir, frame_T     *to_flatten)
{
    win_T       *wp = new_wp;
    win_T       *oldwin;
    int         new_size = size;
    int         i;
    int         need_status = 0;
    int         do_equal = FALSE;
    int         needed;
    int         available;
    int         oldwin_height = 0;
    int         layout;
    frame_T *frp;
    frame_T *curfrp;
    frame_T *frp2;
    frame_T *prevfrp;
    int         before;
    int         minheight;
    int         wmh1;
    int         did_set_fraction = FALSE;
    int         retval = FAIL;

    ++RedrawingDisabled;

    if (new_wp == NULL)
    {
        trigger_winnewpre();
    }

    if (flags & WSP_TOP)
    {
        oldwin = firstwin;
    }
    else if (flags & WSP_BOT)
    {
        oldwin = lastwin;
    }
    else
    {
        oldwin = curwin;
    }

    if ( (firstwin == lastwin)  && p_ls == 1 && oldwin->w_status_height == 0)
    {
        if (!(flags & WSP_FORCE_ROOM) &&  (oldwin)->w_height  <= p_wmh)
        {
            emsg(_(e_not_enough_room));
            goto theend;
        }
        need_status = statusline_height(oldwin);
    }

    if (flags & WSP_VERT)
    {
        int     wmw1;
        int     minwidth;

        layout = FR_ROW;

        wmw1 = (p_wmw == 0 ? 1 : p_wmw);
        needed = wmw1 + 1;
        if (flags & WSP_ROOM)
        {
            needed += p_wiw - wmw1;
        }
        if (flags & (WSP_BOT | WSP_TOP))
        {
            minwidth = frame_minwidth(topframe,  ((win_T *)-1) );
            available = topframe->fr_width;
            needed += minwidth;
        }
        else if (p_ea)
        {
            minwidth = frame_minwidth(oldwin->w_frame,  ((win_T *)-1) );
            prevfrp = oldwin->w_frame;
            for (frp = oldwin->w_frame->fr_parent; frp != NULL; frp = frp->fr_parent)
            {
                if (frp->fr_layout == FR_ROW)
                {
                     for ((frp2) = frp->fr_child; (frp2) != NULL; (frp2) = (frp2)->fr_next) 
                     {
                        if (frp2 != prevfrp)
                        {
                            minwidth += frame_minwidth(frp2,  ((win_T *)-1) );
                        }
                     }
                }
                prevfrp = frp;
            }
            available = topframe->fr_width;
            needed += minwidth;
        }
        else
        {
            minwidth = frame_minwidth(oldwin->w_frame,  ((win_T *)-1) );
            available = oldwin->w_frame->fr_width;
            needed += minwidth;
        }
        if (!(flags & WSP_FORCE_ROOM) && available < needed)
        {
            emsg(_(e_not_enough_room));
            goto theend;
        }
        if (new_size == 0)
        {
            new_size = oldwin->w_width / 2;
        }
        if (new_size > available - minwidth - 1)
        {
            new_size = available - minwidth - 1;
        }
        if (new_size < wmw1)
        {
            new_size = wmw1;
        }

        if (oldwin->w_width - new_size - 1 < p_wmw)
        {
            do_equal = TRUE;
        }

        if (oldwin-> w_onebuf_opt.wo_wfw )
        {
            win_setwidth_win(oldwin->w_width + new_size + 1, oldwin);
        }

        if (!do_equal && p_ea && size == 0 && *p_ead != 'v' && oldwin->w_frame->fr_parent != NULL)
        {
            frp = oldwin->w_frame->fr_parent->fr_child;
            while (frp != NULL)
            {
                if (frp->fr_win != oldwin && frp->fr_win != NULL && (frp->fr_win->w_width > new_size || frp->fr_win->w_width > oldwin->w_width - new_size - 1))
                {
                    do_equal = TRUE;
                    break;
                }
                frp = frp->fr_next;
            }
        }
    }
    else
    {
        layout = FR_COL;

        wmh1 = (p_wmh == 0 ? 1 : p_wmh) +  0 ;
        needed = wmh1 + statusline_height(oldwin);
        if (flags & WSP_ROOM)
        {
            needed += p_wh - wmh1;
        }
        if (flags & (WSP_BOT | WSP_TOP))
        {
            minheight = frame_minheight(topframe,  ((win_T *)-1) ) + need_status;
            available = topframe->fr_height;
            needed += minheight;
        }
        else if (p_ea)
        {
            minheight = frame_minheight(oldwin->w_frame,  ((win_T *)-1) ) + need_status;
            prevfrp = oldwin->w_frame;
            for (frp = oldwin->w_frame->fr_parent; frp != NULL; frp = frp->fr_parent)
            {
                if (frp->fr_layout == FR_COL)
                {
                     for ((frp2) = frp->fr_child; (frp2) != NULL; (frp2) = (frp2)->fr_next) 
                     {
                        if (frp2 != prevfrp)
                        {
                            minheight += frame_minheight(frp2,  ((win_T *)-1) );
                        }
                     }
                }
                prevfrp = frp;
            }
            available = topframe->fr_height;
            needed += minheight;
        }
        else
        {
            minheight = frame_minheight(oldwin->w_frame,  ((win_T *)-1) ) + need_status;
            available = oldwin->w_frame->fr_height;
            needed += minheight;
        }
        if (!(flags & WSP_FORCE_ROOM) && available < needed)
        {
            emsg(_(e_not_enough_room));
            goto theend;
        }
        oldwin_height = oldwin->w_height;
        if (need_status)
        {
            oldwin->w_status_height = statusline_height(oldwin);
            oldwin_height -= oldwin->w_status_height;
        }
        int new_win_stlh = need_status != 0 ? need_status
                        : statusline_height(new_wp != NULL ? new_wp : curwin);
        if (new_size == 0)
        {
            new_size = (oldwin_height - new_win_stlh + 1) / 2;
        }
        if (new_size > available - minheight - new_win_stlh)
        {
            new_size = available - minheight - new_win_stlh;
        }
        if (new_size < wmh1)
        {
            new_size = wmh1;
        }

        if (oldwin_height - new_size - new_win_stlh < p_wmh)
        {
            do_equal = TRUE;
        }

        if (oldwin-> w_onebuf_opt.wo_wfh )
        {
            set_fraction(oldwin);
            did_set_fraction = TRUE;

            win_setheight_win(oldwin->w_height + new_size + statusline_height(oldwin), oldwin);
            oldwin_height = oldwin->w_height;
        }

        if (!do_equal && p_ea && size == 0 && *p_ead != 'h' && oldwin->w_frame->fr_parent != NULL)
        {
            frp = oldwin->w_frame->fr_parent->fr_child;
            while (frp != NULL)
            {
                if (frp->fr_win != oldwin && frp->fr_win != NULL && (frp->fr_win->w_height > new_size || frp->fr_win->w_height > oldwin_height - new_size - statusline_height(oldwin)))
                {
                    do_equal = TRUE;
                    break;
                }
                frp = frp->fr_next;
            }
        }
    }

    if ((flags & WSP_TOP) == 0 && ((flags & WSP_BOT) || (flags & WSP_BELOW) || (!(flags & WSP_ABOVE) && ( (flags & WSP_VERT) ? p_spr : p_sb))))
    {
        if (new_wp == NULL)
        {
            wp = win_alloc(oldwin, FALSE);
        }
        else
        {
            win_append(oldwin, wp);
        }
    }
    else
    {
        if (new_wp == NULL)
        {
            wp = win_alloc(oldwin->w_prev, FALSE);
        }
        else
        {
            win_append(oldwin->w_prev, wp);
        }
    }

    if (new_wp == NULL)
    {
        if (wp == NULL)
        {
            goto theend;
        }

        new_frame(wp);
        if (wp->w_frame == NULL)
        {
            win_free(wp, NULL);
            goto theend;
        }

        win_init(wp, curwin, flags);
    }

    if (to_flatten != NULL)
    {
        frame_flatten(to_flatten);
    }

    if (flags & (WSP_TOP | WSP_BOT))
    {
        if ((topframe->fr_layout == FR_COL && (flags & WSP_VERT) == 0) || (topframe->fr_layout == FR_ROW && (flags & WSP_VERT) != 0))
        {
            curfrp = topframe->fr_child;
            if (flags & WSP_BOT)
            {
                while (curfrp->fr_next != NULL)
                {
                    curfrp = curfrp->fr_next;
                }
            }
        }
        else
        {
            curfrp = topframe;
        }
        before = (flags & WSP_TOP);
    }
    else
    {
        curfrp = oldwin->w_frame;
        if (flags & WSP_BELOW)
        {
            before = FALSE;
        }
        else if (flags & WSP_ABOVE)
        {
            before = TRUE;
        }
        else if (flags & WSP_VERT)
        {
            before = !p_spr;
        }
        else
        {
            before = !p_sb;
        }
    }
    if (curfrp->fr_parent == NULL || curfrp->fr_parent->fr_layout != layout)
    {
        frp =  (frame_T *)alloc_clear(sizeof(frame_T)) ;
        *frp = *curfrp;
        curfrp->fr_layout = layout;
        frp->fr_parent = curfrp;
        frp->fr_next = NULL;
        frp->fr_prev = NULL;
        curfrp->fr_child = frp;
        curfrp->fr_win = NULL;
        curfrp = frp;
        if (frp->fr_win != NULL)
        {
            oldwin->w_frame = frp;
        }
        else
        {
             for ((frp) = frp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
             {
                frp->fr_parent = curfrp;
             }
        }
    }

    if (new_wp == NULL)
    {
        frp = wp->w_frame;
    }
    else
    {
        frp = new_wp->w_frame;
    }
    frp->fr_parent = curfrp->fr_parent;

    if (before)
    {
        frame_insert(curfrp, frp);
    }
    else
    {
        frame_append(curfrp, frp);
    }

    if (!did_set_fraction)
    {
        set_fraction(oldwin);
    }
    wp->w_fraction = oldwin->w_fraction;

    if (flags & WSP_VERT)
    {
        wp-> w_onebuf_opt.wo_scr  = curwin-> w_onebuf_opt.wo_scr ;

        if (need_status)
        {
            win_new_height(oldwin, oldwin->w_height - need_status);
            oldwin->w_status_height = need_status;
        }
        if (flags & (WSP_TOP | WSP_BOT))
        {
            int stl_height = p_ls > 0 ? statusline_height(curfrp->fr_win) : 0;

            wp->w_winrow = tabline_height();
            win_new_height(wp, curfrp->fr_height - stl_height -  0 );
            wp->w_status_height = stl_height;
        }
        else
        {
            wp->w_winrow = oldwin->w_winrow;
            win_new_height(wp,  (oldwin)->w_height );
            wp->w_status_height = oldwin->w_status_height;
        }
        frp->fr_height = curfrp->fr_height;

        win_new_width(wp, new_size);
        if (before)
        {
            wp->w_vsep_width = 1;
        }
        else
        {
            wp->w_vsep_width = oldwin->w_vsep_width;
            oldwin->w_vsep_width = 1;
        }
        if (flags & (WSP_TOP | WSP_BOT))
        {
            if (flags & WSP_BOT)
            {
                frame_set_vsep(curfrp, TRUE);
            }
            frame_new_width(curfrp, curfrp->fr_width - (new_size + ((flags & WSP_TOP) != 0)), flags & WSP_TOP, FALSE);
        }
        else
        {
            win_new_width(oldwin, oldwin->w_width - (new_size + 1));
        }
        if (before)
        {
            wp->w_wincol = oldwin->w_wincol;
            oldwin->w_wincol += new_size + 1;
        }
        else
        {
            wp->w_wincol = oldwin->w_wincol + oldwin->w_width + 1;
        }
        frame_fix_width(oldwin);
        frame_fix_width(wp);
    }
    else
    {
        if (flags & (WSP_TOP | WSP_BOT))
        {
            wp->w_wincol = firstwin->w_wincol;
            win_new_width(wp, topframe->fr_width);
            wp->w_vsep_width = 0;
        }
        else
        {
            wp->w_wincol = oldwin->w_wincol;
            win_new_width(wp, oldwin->w_width);
            wp->w_vsep_width = oldwin->w_vsep_width;
        }
        frp->fr_width = curfrp->fr_width;

        win_new_height(wp, new_size);
        int old_status_height = oldwin->w_status_height;
        if (flags & (WSP_TOP | WSP_BOT))
        {
            int new_fr_height = curfrp->fr_height - new_size
                                                          +  0 ;

            if (!((flags & WSP_BOT) && p_ls == 0))
            {
                new_fr_height -= statusline_height(curfrp->fr_win);
            }
            if (flags & WSP_BOT)
            {
                frame_add_statusline(curfrp);
            }
            frame_new_height(curfrp, new_fr_height, flags & WSP_TOP, FALSE, FALSE);
        }
        else
        {
            win_new_height(oldwin, oldwin_height - (new_size + statusline_height(wp)));
        }
        if (before)
        {
            wp->w_winrow = oldwin->w_winrow;
            wp->w_status_height = statusline_height(wp);
            oldwin->w_winrow += wp->w_height + statusline_height(wp);
        }
        else
        {
            wp->w_winrow = oldwin->w_winrow +  (oldwin)->w_height 
                                                    + statusline_height(oldwin);
            wp->w_status_height = old_status_height;
            if (!(flags & WSP_BOT))
            {
                oldwin->w_status_height = statusline_height(oldwin);
            }
        }
        frame_fix_height(wp);
        frame_fix_height(oldwin);
    }

    if (flags & (WSP_TOP | WSP_BOT))
    {
        win_comp_pos();
    }

    redraw_win_later(wp, UPD_NOT_VALID);
    redraw_win_later(oldwin, UPD_NOT_VALID);
    status_redraw_all();

    if (need_status)
    {
        msg_row = Rows - 1;
        msg_col = sc_col;
        msg_clr_eos_force();
        comp_col();
        msg_row = Rows - 1;
        msg_col = 0;
    }

    if (do_equal || dir != 0)
    {
        win_equal(wp, TRUE, (flags & WSP_VERT) ? (dir == 'v' ? 'b' : 'h') : dir == 'h' ? 'b' : 'v');
    }
    else if (!is_aucmd_win(wp))
    {
        win_fix_scroll(FALSE);
    }

    if (flags & WSP_VERT)
    {
        i = p_wiw;
        if (size != 0)
        {
            p_wiw = size;
        }

    }
    else
    {
        i = p_wh;
        if (size != 0)
        {
            p_wh = size;
        }
    }

    (void)win_enter_ext(wp, (new_wp == NULL ? WEE_TRIGGER_NEW_AUTOCMDS : 0) | WEE_TRIGGER_ENTER_AUTOCMDS | WEE_TRIGGER_LEAVE_AUTOCMDS);
    if (flags & WSP_VERT)
    {
        p_wiw = i;
    }
    else
    {
        p_wh = i;
    }
    retval = OK;

theend:
    if (RedrawingDisabled > 0)
    {
        --RedrawingDisabled;
    }
    return retval;
}

    static void
win_init(win_T *newp, win_T *oldp, int flags  __attribute__((unused)) )
{
    int         i;

    newp->w_buffer = oldp->w_buffer;
    oldp->w_buffer->b_nwindows++;
    newp->w_cursor = oldp->w_cursor;
    newp->w_valid = 0;
    newp->w_curswant = oldp->w_curswant;
    newp->w_set_curswant = oldp->w_set_curswant;
    newp->w_topline = oldp->w_topline;
    newp->w_leftcol = oldp->w_leftcol;
    newp->w_pcmark = oldp->w_pcmark;
    newp->w_prev_pcmark = oldp->w_prev_pcmark;
    newp->w_alt_fnum = oldp->w_alt_fnum;
    newp->w_wrow = oldp->w_wrow;
    newp->w_fraction = oldp->w_fraction;
    newp->w_prev_fraction_row = oldp->w_prev_fraction_row;

    remove_highlight_overrides(newp->w_hl);
     vim_free(newp->w_hl);
     (newp->w_hl) = NULL;

    copy_jumplist(oldp, newp);
    newp->w_localdir = (oldp->w_localdir == NULL)
                                    ? NULL : vim_strsave(oldp->w_localdir);
    newp->w_prevdir = (oldp->w_prevdir == NULL)
                                    ? NULL : vim_strsave(oldp->w_prevdir);

    if (*p_spk != 'c')
    {
        if (*p_spk == 't')
        {
            newp->w_skipcol = oldp->w_skipcol;
        }
        newp->w_botline = oldp->w_botline;
        newp->w_prev_height = oldp->w_height -  0 ;
        newp->w_prev_winrow = oldp->w_winrow + 2 *  0 ;
    }

    for (i = 0; i < oldp->w_tagstacklen; i++)
    {
        taggy_T *tag = &newp->w_tagstack[i];
        *tag = oldp->w_tagstack[i];
        if (tag->tagname != NULL)
        {
            tag->tagname = vim_strsave(tag->tagname);
        }
        if (tag->user_data != NULL)
        {
            tag->user_data = vim_strsave(tag->user_data);
        }
    }
    newp->w_tagstackidx = oldp->w_tagstackidx;
    newp->w_tagstacklen = oldp->w_tagstacklen;

    newp->w_changelistidx = oldp->w_changelistidx;

    win_init_some(newp, oldp);

}

    static void
win_init_some(win_T *newp, win_T *oldp)
{
    newp->w_alist = oldp->w_alist;
    ++newp->w_alist->al_refcount;
    newp->w_arg_idx = oldp->w_arg_idx;

    win_copy_options(oldp, newp);
}

    static int
win_valid_popup(win_T *win  __attribute__((unused)) )
{
    return FALSE;
}

    static int
win_valid(win_T *win)
{
    win_T       *wp;

    if (win == NULL)
    {
        return FALSE;
    }
     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
     {
        if (wp == win)
        {
            return TRUE;
        }
     }
    return win_valid_popup(win);
}

    static win_T *
win_find_by_id(int id)
{
    win_T   *wp;

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
     {
        if (wp->w_id == id)
        {
            return wp;
        }
     }
    return NULL;
}

    static int
win_valid_any_tab(win_T *win)
{
    win_T       *wp;
    tabpage_T   *tp;

    if (win == NULL)
    {
        return FALSE;
    }
     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
    {
         for ((wp) = ((tp) == NULL || (tp) == curtab)             ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next) 
        {
            if (wp == win)
            {
                return TRUE;
            }
        }
    }
    return win_valid_popup(win);
}

    static int
win_count(void)
{
    win_T       *wp;
    int         count = 0;

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
     {
        ++count;
     }
    return count;
}

    static int
make_windows(int         count, int         vertical)
{
    int         maxcount;
    int         todo;

    if (vertical)
    {
        maxcount = (curwin->w_width + curwin->w_vsep_width - (p_wiw - p_wmw)) / (p_wmw + 1);
    }
    else
    {
        maxcount = ( (curwin)->w_height  + curwin->w_status_height - (p_wh - p_wmh)) / (p_wmh + statusline_height(curwin));
    }

    if (maxcount < 2)
    {
        maxcount = 2;
    }
    if (count > maxcount)
    {
        count = maxcount;
    }

    if (count > 1)
    {
        last_status(TRUE);
    }

    block_autocmds();

    for (todo = count - 1; todo > 0; --todo)
    {
        if (vertical)
        {
            if (win_split(curwin->w_width - (curwin->w_width - todo) / (todo + 1) - 1, WSP_VERT | WSP_ABOVE) == FAIL)
            {
                break;
            }
        }
        else
        {
            if (win_split(curwin->w_height - (curwin->w_height - todo * statusline_height(curwin)) / (todo + 1) - statusline_height(curwin), WSP_ABOVE) == FAIL)
            {
                break;
            }
        }
    }

    unblock_autocmds();

    return (count - todo);
}

    static void
win_exchange(long Prenum)
{
    frame_T     *frp;
    frame_T     *frp2;
    win_T       *wp;
    win_T       *wp2;
    int         temp;

    if (ERROR_IF_ANY_POPUP_WINDOW)
    {
        return;
    }
    if ( (firstwin == lastwin) )
    {
        beep_flush();
        return;
    }
    if (text_or_buf_locked())
    {
        beep_flush();
        return;
    }

    if (Prenum)
    {
        frp = curwin->w_frame->fr_parent->fr_child;
        while (frp != NULL && --Prenum > 0)
        {
            frp = frp->fr_next;
        }
    }
    else if (curwin->w_frame->fr_next != NULL)
    {
        frp = curwin->w_frame->fr_next;
    }
    else
    {
        frp = curwin->w_frame->fr_prev;
    }

    if (frp == NULL || frp->fr_win == NULL || frp->fr_win == curwin)
    {
        return;
    }
    wp = frp->fr_win;

    wp2 = curwin->w_prev;
    frp2 = curwin->w_frame->fr_prev;
    if (wp->w_prev != curwin)
    {
        win_remove(curwin, NULL);
        frame_remove(curwin->w_frame);
        win_append(wp->w_prev, curwin);
        frame_insert(frp, curwin->w_frame);
    }
    if (wp != wp2)
    {
        win_remove(wp, NULL);
        frame_remove(wp->w_frame);
        win_append(wp2, wp);
        if (frp2 == NULL)
        {
            frame_insert(wp->w_frame->fr_parent->fr_child, wp->w_frame);
        }
        else
        {
            frame_append(frp2, wp->w_frame);
        }
    }
    temp = curwin->w_status_height;
    if (temp != wp->w_status_height)
    {
        win_new_height(curwin, curwin->w_height + temp - wp->w_status_height);
        win_new_height(wp, wp->w_height + wp->w_status_height - temp);
    }
    curwin->w_status_height = wp->w_status_height;
    wp->w_status_height = temp;
    temp = curwin->w_vsep_width;
    curwin->w_vsep_width = wp->w_vsep_width;
    wp->w_vsep_width = temp;

    frame_fix_height(curwin);
    frame_fix_height(wp);
    frame_fix_width(curwin);
    frame_fix_width(wp);

    win_comp_pos();

    if (wp->w_buffer != curbuf)
    {
        reset_VIsual_and_resel();
    }
    else if (VIsual_active)
    {
        wp->w_cursor = curwin->w_cursor;
    }

    win_enter(wp, TRUE);
    redraw_all_later(UPD_NOT_VALID);
}

    static void
win_rotate(int upwards, int count)
{
    win_T       *wp1;
    win_T       *wp2;
    frame_T     *frp;
    int         n;

    if ( (firstwin == lastwin) )
    {
        beep_flush();
        return;
    }

     for ((frp) = curwin->w_frame->fr_parent->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
     {
        if (frp->fr_win == NULL)
        {
            emsg(_(e_cannot_rotate_when_another_window_is_split));
            return;
        }
     }

    while (count--)
    {
        if (upwards)
        {
            frp = curwin->w_frame->fr_parent->fr_child;
            wp1 = frp->fr_win;
            win_remove(wp1, NULL);
            frame_remove(frp);

            for ( ; frp->fr_next != NULL; frp = frp->fr_next)
            {
                ;
            }
            win_append(frp->fr_win, wp1);
            frame_append(frp, wp1->w_frame);

            wp2 = frp->fr_win;
        }
        else
        {
            for (frp = curwin->w_frame; frp->fr_next != NULL; frp = frp->fr_next)
            {
                ;
            }
            wp1 = frp->fr_win;
            wp2 = wp1->w_prev;
            win_remove(wp1, NULL);
            frame_remove(frp);

            win_append(frp->fr_parent->fr_child->fr_win->w_prev, wp1);
            frame_insert(frp->fr_parent->fr_child, frp);
        }

        n = wp2->w_status_height;
        if (n != wp1->w_status_height)
        {
            win_new_height(wp2, wp2->w_height + n - wp1->w_status_height);
            win_new_height(wp1, wp1->w_height + wp1->w_status_height - n);
        }
        wp2->w_status_height = wp1->w_status_height;
        wp1->w_status_height = n;
        frame_fix_height(wp1);
        frame_fix_height(wp2);
        n = wp2->w_vsep_width;
        wp2->w_vsep_width = wp1->w_vsep_width;
        wp1->w_vsep_width = n;
        frame_fix_width(wp1);
        frame_fix_width(wp2);

        win_comp_pos();
    }

    redraw_all_later(UPD_NOT_VALID);
}

    static int
win_splitmove(win_T *wp, int size, int flags)
{
    int         dir;
    int         height = wp->w_height;
    frame_T     *unflat_altfr;

    if ( (firstwin == lastwin) )
    {
        return OK;
    }
    if (check_split_disallowed(wp) == FAIL)
    {
        return FAIL;
    }

    winframe_remove(wp, &dir, NULL, &unflat_altfr);
    win_remove(wp, NULL);
    last_status(FALSE);
    win_comp_pos();

    if (win_split_ins(size, flags, wp, dir, unflat_altfr) == FAIL)
    {
        winframe_restore(wp, dir, unflat_altfr);
        win_append(wp->w_prev, wp);
        return FAIL;
    }

    if (size == 0 && !(flags & WSP_VERT) && win_valid(wp))
    {
        win_setheight_win(height, wp);
        if (p_ea)
        {
            win_equal(curwin, curwin == wp, 'v');
        }
    }

    return OK;
}

    static void
win_move_after(win_T *win1, win_T *win2)
{
    int         height;

    if (win1 == win2)
    {
        return;
    }

    if (win2->w_next != win1)
    {
        if (win1->w_frame->fr_parent != win2->w_frame->fr_parent)
        {
            iemsg("Trying to move a window into another frame");
            return;
        }

        if (win1 == lastwin)
        {
            height = win1->w_prev->w_status_height;
            win1->w_prev->w_status_height = win1->w_status_height;
            win1->w_status_height = height;
            if (win1->w_prev->w_vsep_width == 1)
            {
                win1->w_prev->w_vsep_width = 0;
                win1->w_prev->w_frame->fr_width -= 1;
                win1->w_vsep_width = 1;
                win1->w_frame->fr_width += 1;
            }
        }
        else if (win2 == lastwin)
        {
            height = win1->w_status_height;
            win1->w_status_height = win2->w_status_height;
            win2->w_status_height = height;
            if (win1->w_vsep_width == 1)
            {
                win2->w_vsep_width = 1;
                win2->w_frame->fr_width += 1;
                win1->w_vsep_width = 0;
                win1->w_frame->fr_width -= 1;
            }
        }
        win_remove(win1, NULL);
        frame_remove(win1->w_frame);
        win_append(win2, win1);
        frame_append(win2->w_frame, win1->w_frame);

        win_comp_pos();
        redraw_later(UPD_NOT_VALID);
    }
    win_enter(win1, FALSE);
}

    static void
win_equal(win_T       *next_curwin, int         current, int         dir)
{
    if (dir == 0)
    {
        dir = *p_ead;
    }
    win_equal_rec(next_curwin == NULL ? curwin : next_curwin, current, topframe, dir, firstwin->w_wincol, tabline_height(), topframe->fr_width, topframe->fr_height);
    if (!is_aucmd_win(next_curwin))
    {
        win_fix_scroll(TRUE);
    }
}

    static void
win_equal_rec(win_T       *next_curwin, int         current, frame_T     *topfr, int         dir, int         col, int         row, int         width, int         height)
{
    int n;
    int m;
    int         extra_sep = 0;
    int wincount;
    int totwincount = 0;
    frame_T     *fr;
    int         next_curwin_size = 0;
    int         room = 0;
    int         new_size;
    int         has_next_curwin = 0;
    int         hnc;

    if (topfr->fr_layout == FR_LEAF)
    {
        if (topfr->fr_height != height || topfr->fr_win->w_winrow != row || topfr->fr_width != width || topfr->fr_win->w_wincol != col)
        {
            topfr->fr_win->w_winrow = row;
            frame_new_height(topfr, height, FALSE, FALSE, FALSE);
            topfr->fr_win->w_wincol = col;
            frame_new_width(topfr, width, FALSE, FALSE);
            redraw_all_later(UPD_NOT_VALID);
        }
    }
    else if (topfr->fr_layout == FR_ROW)
    {
        topfr->fr_width = width;
        topfr->fr_height = height;

        if (dir != 'v')
        {
            n = frame_minwidth(topfr,  ((win_T *)-1) );
            if (col + width >= firstwin->w_wincol + topframe->fr_width)
            {
                extra_sep = 1;
            }
            else
            {
                extra_sep = 0;
            }
            totwincount = (n + extra_sep) / (p_wmw + 1);
            has_next_curwin = frame_has_win(topfr, next_curwin);

            m = frame_minwidth(topfr, next_curwin);
            room = width - m;
            if (room < 0)
            {
                next_curwin_size = p_wiw + room;
                room = 0;
            }
            else
            {
                next_curwin_size = -1;
                 for ((fr) = topfr->fr_child; (fr) != NULL; (fr) = (fr)->fr_next) 
                {
                    if (!frame_fixed_width(fr))
                    {
                        continue;
                    }
                    n = frame_minwidth(fr,  ((win_T *)-1) );
                    new_size = fr->fr_width;
                    if (frame_has_win(fr, next_curwin))
                    {
                        room += p_wiw - p_wmw;
                        next_curwin_size = 0;
                        if (new_size < p_wiw)
                        {
                            new_size = p_wiw;
                        }
                    }
                    else
                    {
                        totwincount -= (n + (fr->fr_next == NULL ? extra_sep : 0)) / (p_wmw + 1);
                    }
                    room -= new_size - n;
                    if (room < 0)
                    {
                        new_size += room;
                        room = 0;
                    }
                    fr->fr_newwidth = new_size;
                }
                if (next_curwin_size == -1)
                {
                    if (!has_next_curwin)
                    {
                        next_curwin_size = 0;
                    }
                    else if (totwincount > 1 && (room + (totwincount - 2)) / (totwincount - 1) > p_wiw)
                    {
                        next_curwin_size = (room + p_wiw + (totwincount - 1) * p_wmw + (totwincount - 1)) / totwincount;
                        room -= next_curwin_size - p_wiw;
                    }
                    else
                    {
                        next_curwin_size = p_wiw;
                    }
                }
            }

            if (has_next_curwin)
            {
                --totwincount;
            }
        }

         for ((fr) = topfr->fr_child; (fr) != NULL; (fr) = (fr)->fr_next) 
        {
            wincount = 1;
            if (fr->fr_next == NULL)
            {
                new_size = width;
            }
            else if (dir == 'v')
            {
                new_size = fr->fr_width;
            }
            else if (frame_fixed_width(fr))
            {
                new_size = fr->fr_newwidth;
                wincount = 0;
            }
            else
            {
                n = frame_minwidth(fr,  ((win_T *)-1) );
                wincount = (n + (fr->fr_next == NULL ? extra_sep : 0))
                                                                / (p_wmw + 1);
                m = frame_minwidth(fr, next_curwin);
                if (has_next_curwin)
                {
                    hnc = frame_has_win(fr, next_curwin);
                }
                else
                {
                    hnc = FALSE;
                }
                if (hnc)
                {
                    --wincount;
                }
                if (totwincount == 0)
                {
                    new_size = room;
                }
                else
                {
                    new_size = (wincount * room + ((unsigned)totwincount >> 1))
                                                                / totwincount;
                }
                if (hnc)
                {
                    next_curwin_size -= p_wiw - (m - n);
                    if (next_curwin_size < 0)
                    {
                        next_curwin_size = 0;
                    }
                    new_size += next_curwin_size;
                    room -= new_size - next_curwin_size;
                }
                else
                {
                    room -= new_size;
                }
                new_size += n;
            }

            if (!current || dir != 'v' || topfr->fr_parent != NULL || (new_size != fr->fr_width) || frame_has_win(fr, next_curwin))
            {
                win_equal_rec(next_curwin, current, fr, dir, col, row, new_size, height);
            }
            col += new_size;
            width -= new_size;
            totwincount -= wincount;
        }
    }
    else
    {
        topfr->fr_width = width;
        topfr->fr_height = height;

        if (dir != 'h')
        {
            totwincount = frame_wincount_in_height(topfr);
            has_next_curwin = frame_has_win(topfr, next_curwin);

            m = frame_minheight(topfr, next_curwin);
            room = height - m;
            if (room < 0)
            {
                next_curwin_size = p_wh + room;
                room = 0;
            }
            else
            {
                next_curwin_size = -1;
                 for ((fr) = topfr->fr_child; (fr) != NULL; (fr) = (fr)->fr_next) 
                {
                    if (!frame_fixed_height(fr))
                    {
                        continue;
                    }
                    n = frame_minheight(fr,  ((win_T *)-1) );
                    new_size = fr->fr_height;
                    if (frame_has_win(fr, next_curwin))
                    {
                        room += p_wh - p_wmh;
                        next_curwin_size = 0;
                        if (new_size < n + (p_wh - p_wmh))
                        {
                            new_size = n + (p_wh - p_wmh);
                        }
                    }
                    else
                    {
                        totwincount -= frame_wincount_in_height(fr);
                    }
                    room -= new_size - n;
                    if (room < 0)
                    {
                        new_size += room;
                        room = 0;
                    }
                    fr->fr_newheight = new_size;
                }
                if (next_curwin_size == -1)
                {
                    if (!has_next_curwin)
                    {
                        next_curwin_size = 0;
                    }
                    else if (totwincount > 1 && (room + (totwincount - 2)) / (totwincount - 1) > p_wh)
                    {
                        next_curwin_size = (room + p_wh + (totwincount - 1) * p_wmh + (totwincount - 1)) / totwincount;
                        room -= next_curwin_size - p_wh;
                    }
                    else
                    {
                        next_curwin_size = p_wh;
                    }
                }
            }

            if (has_next_curwin)
            {
                --totwincount;
            }
        }

         for ((fr) = topfr->fr_child; (fr) != NULL; (fr) = (fr)->fr_next) 
        {
            wincount = 1;
            if (fr->fr_next == NULL)
            {
                new_size = height;
            }
            else if (dir == 'h')
            {
                new_size = fr->fr_height;
            }
            else if (frame_fixed_height(fr))
            {
                new_size = fr->fr_newheight;
                wincount = 0;
            }
            else
            {
                n = frame_minheight(fr,  ((win_T *)-1) );
                wincount = frame_wincount_in_height(fr);
                m = frame_minheight(fr, next_curwin);
                if (has_next_curwin)
                {
                    hnc = frame_has_win(fr, next_curwin);
                }
                else
                {
                    hnc = FALSE;
                }
                if (hnc)
                {
                    --wincount;
                }
                if (totwincount == 0)
                {
                    new_size = room;
                }
                else
                {
                    new_size = (wincount * room + ((unsigned)totwincount >> 1))
                                                                / totwincount;
                }
                if (hnc)
                {
                    next_curwin_size -= p_wh - (m - n);
                    new_size += next_curwin_size;
                    room -= new_size - next_curwin_size;
                }
                else
                {
                    room -= new_size;
                }
                new_size += n;
            }
            if (!current || dir != 'h' || topfr->fr_parent != NULL || (new_size != fr->fr_height) || frame_has_win(fr, next_curwin))
            {
                win_equal_rec(next_curwin, current, fr, dir, col, row, width, new_size);
            }
            row += new_size;
            height -= new_size;
            totwincount -= wincount;
        }
    }
}

    static void
win_init_empty(win_T *wp)
{
    redraw_win_later(wp, UPD_NOT_VALID);
    wp->w_lines_valid = 0;
    wp->w_cursor.lnum = 1;
    wp->w_curswant = wp->w_cursor.col = 0;
    wp->w_cursor.coladd = 0;
    wp->w_pcmark.lnum = 1;
    wp->w_pcmark.col = 0;
    wp->w_prev_pcmark.lnum = 0;
    wp->w_prev_pcmark.col = 0;
    wp->w_topline = 1;
    wp->w_botline = 2;
    wp->w_valid = 0;
}

    static void
curwin_init(void)
{
    win_init_empty(curwin);
}

    static void
close_windows(buf_T       *buf, int         keep_curwin)
{
    win_T       *wp;
    tabpage_T *tp;
    tabpage_T *nexttp;
    int         count = tabpage_index(NULL);

    ++RedrawingDisabled;

    for (wp = firstwin; wp != NULL && ! (firstwin == lastwin) ; )
    {
        if (wp->w_buffer == buf && (!keep_curwin || wp != curwin) && !(win_locked(wp) || wp->w_buffer->b_locked > 0))
        {
            if (window_layout_locked(CMD_SIZE))
            {
                goto theend;
            }
            if (win_close(wp, FALSE) == FAIL)
            {
                break;
            }

            wp = firstwin;
        }
        else
        {
            wp = wp->w_next;
        }
    }

    for (tp = first_tabpage; tp != NULL; tp = nexttp)
    {
        nexttp = tp->tp_next;
        if (tp != curtab)
        {
             for ((wp) = ((tp) == NULL || (tp) == curtab)             ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next) 
             {
                if (wp->w_buffer == buf && !(win_locked(wp) || wp->w_buffer->b_locked > 0))
                {
                    if (window_layout_locked(CMD_SIZE))
                    {
                        goto theend;
                    }
                    win_close_othertab(wp, FALSE, tp);

                    nexttp = first_tabpage;
                    break;
                }
             }
        }
    }

theend:
    if (RedrawingDisabled > 0)
    {
        --RedrawingDisabled;
    }

    if (count != tabpage_index(NULL))
    {
        apply_autocmds(EVENT_TABCLOSED, NULL, NULL, FALSE, curbuf);
    }
}

    static int
last_window(void)
{
    return (one_window() && first_tabpage->tp_next == NULL);
}

    static int
one_window(void)
{
    win_T       *wp;
    int         seen_one = FALSE;

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
    {
        if (!is_aucmd_win(wp))
        {
            if (seen_one)
            {
                return FALSE;
            }
            seen_one = TRUE;
        }
    }
    return TRUE;
}

    static int
close_last_window_tabpage(win_T       *win, int         free_buf, tabpage_T   *prev_curtab)
{
    if (! (firstwin == lastwin) )
    {
        return FALSE;
    }

    buf_T       *old_curbuf = curbuf;
    tabpage_T   *save_lastused = lastused_tabpage;

    goto_tabpage_tp(alt_tabpage(), FALSE, win->w_buffer != NULL);

    if (valid_tabpage(prev_curtab) && prev_curtab->tp_firstwin == win)
    {
        win_close_othertab(win, free_buf, prev_curtab);
    }

    if (valid_tabpage(save_lastused) && save_lastused != curtab)
    {
        lastused_tabpage = save_lastused;
    }
    apply_autocmds(EVENT_TABCLOSED, NULL, NULL, FALSE, curbuf);
    apply_autocmds(EVENT_WINENTER, NULL, NULL, FALSE, curbuf);
    apply_autocmds(EVENT_TABENTER, NULL, NULL, FALSE, curbuf);
    if (old_curbuf != curbuf)
    {
        apply_autocmds(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf);
    }
    return TRUE;
}

    static void
win_close_buffer(win_T *win, int action, int abort_if_last)
{
    if (win->w_buffer != NULL)
    {
        bufref_T    bufref;

        set_bufref(&bufref, curbuf);
        ++win->w_locked;
        close_buffer(win, win->w_buffer, action, abort_if_last, TRUE, TRUE);
        if (win_valid_any_tab(win))
        {
            --win->w_locked;
        }
        if (!bufref_valid(&bufref))
        {
            curbuf = firstbuf;
        }
    }
}

    static int
win_close(win_T *win, int free_buf)
{
    win_T       *wp;
    int         other_buffer = FALSE;
    int         close_curwin = FALSE;
    int         dir;
    int         help_window = FALSE;
    int         quickfix_window = FALSE;
    tabpage_T   *prev_curtab = curtab;
    frame_T     *win_frame = win->w_frame->fr_parent;

    if (ERROR_IF_ANY_POPUP_WINDOW)
    {
        return FAIL;
    }

    if (last_window())
    {
        emsg(_(e_cannot_close_last_window));
        return FAIL;
    }
    if (window_layout_locked(CMD_close))
    {
        return FAIL;
    }

    if (win_locked(win) || (win->w_buffer != NULL && win->w_buffer->b_locked > 0))
    {
        return FAIL;
    }
    if (win_unlisted(win))
    {
        emsg(_(e_cannot_close_autocmd_or_popup_window));
        return FAIL;
    }
    if ((is_aucmd_win(firstwin) || is_aucmd_win(lastwin)) && one_window())
    {
        emsg(_(e_cannot_close_window_only_autocmd_window_would_remain));
        return FAIL;
    }

    if (close_last_window_tabpage(win, free_buf, prev_curtab))
    {
        return FAIL;
    }

    if (bt_help(win->w_buffer))
    {
        help_window = TRUE;
    }
    else
    {
        clear_snapshot(curtab, SNAP_HELP_IDX);
    }

    if (bt_quickfix(win->w_buffer))
    {
        quickfix_window = TRUE;
    }
    else
    {
        clear_snapshot(curtab, SNAP_QUICKFIX_IDX);
    }

    if (win == curwin)
    {
        wp = frame2win(win_altframe(win, NULL));

        if (wp->w_buffer != curbuf)
        {
            reset_VIsual_and_resel();

            other_buffer = TRUE;
            if (!win_valid(win))
            {
                return FAIL;
            }
            ++win->w_locked;
            apply_autocmds(EVENT_BUFLEAVE, NULL, NULL, FALSE, curbuf);
            if (!win_valid(win))
            {
                return FAIL;
            }
            --win->w_locked;
            if (last_window())
            {
                return FAIL;
            }
        }
        ++win->w_locked;
        apply_autocmds(EVENT_WINLEAVE, NULL, NULL, FALSE, curbuf);
        if (!win_valid(win))
        {
            return FAIL;
        }
        --win->w_locked;
        if (last_window())
        {
            return FAIL;
        }
    }

    trigger_winclosed(win);
    if (!win_valid_any_tab(win))
    {
        return OK;
    }

    win_close_buffer(win, free_buf ? DOBUF_UNLOAD : 0, TRUE);

    if (win_valid(win) && win->w_buffer == NULL && last_window())
    {
        if (curwin->w_buffer == NULL)
        {
            curwin->w_buffer = curbuf;
        }
        getout(0);
    }

    if (curtab != prev_curtab && win_valid_any_tab(win) && win->w_buffer == NULL)
    {
        win_close_othertab(win, FALSE, prev_curtab);
        return FAIL;
    }

    if (!win_valid(win) || last_window() || close_last_window_tabpage(win, free_buf, prev_curtab))
    {
        return FAIL;
    }

    ++split_disallowed;

    if (win->w_buffer != NULL)
    {
        --win->w_buffer->b_nwindows;
    }

    wp = win_free_mem(win, &dir, NULL);

    if (help_window || quickfix_window)
    {
        win_T *prev_win = get_snapshot_curwin(help_window ? SNAP_HELP_IDX : SNAP_QUICKFIX_IDX);

        if (win_valid(prev_win))
        {
            wp = prev_win;
        }
    }

    if (win == curwin)
    {
        curwin = wp;
        curbuf = curwin->w_buffer;
        close_curwin = TRUE;

        check_cursor();
    }

    last_status(FALSE);

    if (p_ea && (*p_ead == 'b' || *p_ead == dir))
    {
        win_equal(curwin, curwin->w_frame->fr_parent == win_frame, dir);
    }
    else
    {
        win_comp_pos();
        win_fix_scroll(FALSE);
    }

    if (close_curwin)
    {
        (void)
            win_enter_ext(wp, WEE_CURWIN_INVALID | WEE_TRIGGER_ENTER_AUTOCMDS | WEE_TRIGGER_LEAVE_AUTOCMDS | WEE_ALLOW_PARSE_MESSAGES);
        if (other_buffer)
        {
            apply_autocmds(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf);
        }
    }

    if ( (firstwin == lastwin)  && curwin->w_locked && curbuf->b_locked_split && first_tabpage->tp_next != NULL)
    {
        apply_autocmds(EVENT_TABLEAVE, NULL, NULL, FALSE, curbuf);
    }

    --split_disallowed;

    if (help_window || quickfix_window)
    {
        restore_snapshot(help_window ? SNAP_HELP_IDX : SNAP_QUICKFIX_IDX, close_curwin);
    }

    redraw_all_later(UPD_NOT_VALID);
    return OK;
}

    static void
trigger_winnewpre(void)
{
    window_layout_lock();
    apply_autocmds(EVENT_WINNEWPRE, NULL, NULL, FALSE, NULL);
    window_layout_unlock();
}

    static void
trigger_winclosed(win_T *win)
{
    static int  recursive = FALSE;
    char_u      winid[NUMBUFLEN];

    if (recursive)
    {
        return;
    }
    recursive = TRUE;
    vim_snprintf((char *)winid, sizeof(winid), "%d", win->w_id);
    apply_autocmds(EVENT_WINCLOSED, winid, winid, FALSE, win->w_buffer);
    recursive = FALSE;
}

    static void
trigger_tabclosedpre(tabpage_T *tp)
{
    static int  recursive = FALSE;
    tabpage_T   *ptp = curtab;

    if (!has_tabclosedpre() || recursive)
    {
        return;
    }

    if (valid_tabpage(tp))
    {
        goto_tabpage_tp(tp, FALSE, FALSE);
    }
    recursive = TRUE;
    window_layout_lock();
    apply_autocmds(EVENT_TABCLOSEDPRE, NULL, NULL, FALSE, NULL);
    window_layout_unlock();
    recursive = FALSE;
    if (valid_tabpage(ptp))
    {
        goto_tabpage_tp(ptp, FALSE, FALSE);
    }
    else
    {
        goto_tabpage_tp(first_tabpage, FALSE, FALSE);
    }
}

    static void
snapshot_windows_scroll_size(void)
{
    win_T *wp;
     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
    {
        wp->w_last_topline = wp->w_topline;
        wp->w_last_leftcol = wp->w_leftcol;
        wp->w_last_skipcol = wp->w_skipcol;
        wp->w_last_width = wp->w_width;
        wp->w_last_height = wp->w_height;
    }
}

static int did_initial_scroll_size_snapshot = FALSE;

    static void
may_make_initial_scroll_size_snapshot(void)
{
    if (!did_initial_scroll_size_snapshot)
    {
        did_initial_scroll_size_snapshot = TRUE;
        snapshot_windows_scroll_size();
    }
}

    static void
check_window_scroll_resize(int     *size_count, win_T   **first_scroll_win, win_T   **first_size_win, list_T  *winlist  __attribute__((unused)) , dict_T  *v_event  __attribute__((unused)) )
{
    win_T *wp;
     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
    {
        int ignore_scroll = event_ignored(EVENT_WINSCROLLED, wp-> w_onebuf_opt.wo_eiw );
        int size_changed = !event_ignored(EVENT_WINRESIZED, wp-> w_onebuf_opt.wo_eiw )
                            && (wp->w_last_width != wp->w_width || wp->w_last_height != wp->w_height);
        if (size_changed)
        {
                if (size_count != NULL)
            {
                ++*size_count;
                if (*first_size_win == NULL)
                {
                    *first_size_win = wp;
                }
                if (*first_scroll_win == NULL && !ignore_scroll)
                {
                    *first_scroll_win = wp;
                }
            }
        }

        int scroll_changed = !ignore_scroll
                                && (wp->w_last_topline != wp->w_topline || wp->w_last_leftcol != wp->w_leftcol || wp->w_last_skipcol != wp->w_skipcol);
        if (scroll_changed && first_scroll_win != NULL && *first_scroll_win == NULL)
        {
            *first_scroll_win = wp;
        }

    }

}

    static void
may_trigger_win_scrolled_resized(void)
{
    static int      recursive = FALSE;
    int             do_resize = has_winresized();
    int             do_scroll = has_winscrolled();

    if (recursive || !(do_scroll || do_resize) || !did_initial_scroll_size_snapshot)
    {
        return;
    }

    int size_count = 0;
    win_T *first_scroll_win = NULL;
    win_T *first_size_win = NULL;
    check_window_scroll_resize(&size_count, &first_scroll_win, &first_size_win, NULL, NULL);
    int trigger_resize = do_resize && size_count > 0;
    int trigger_scroll = do_scroll && first_scroll_win != NULL;
    if (!trigger_resize && !trigger_scroll)
    {
        return;
    }

    snapshot_windows_scroll_size();

    window_layout_lock();
    recursive = TRUE;

    if (trigger_resize)
    {
            char_u winid[NUMBUFLEN];
            vim_snprintf((char *)winid, sizeof(winid), "%d", first_size_win->w_id);
            apply_autocmds(EVENT_WINRESIZED, winid, winid, FALSE, first_size_win->w_buffer);
    }

    if (trigger_scroll)
    {
        char_u winid[NUMBUFLEN];
        vim_snprintf((char *)winid, sizeof(winid), "%d", first_scroll_win->w_id);
        apply_autocmds(EVENT_WINSCROLLED, winid, winid, FALSE, first_scroll_win->w_buffer);
    }

    recursive = FALSE;
    window_layout_unlock();
}

    static void
win_close_othertab(win_T *win, int free_buf, tabpage_T *tp)
{
    win_T       *wp;
    int         dir;
    tabpage_T   *ptp = NULL;
    int         free_tp = FALSE;

    if (window_layout_locked(CMD_SIZE))
    {
        return;
    }
    if (win_locked(win) || (win->w_buffer != NULL && win->w_buffer->b_locked > 0))
    {
        return;
    }

    if (win->w_buffer != NULL)
    {
        trigger_winclosed(win);
        if (!win_valid_any_tab(win))
        {
            return;
        }
    }

    if (tp->tp_firstwin == tp->tp_lastwin && !tp->tp_did_tabclosedpre)
    {
        trigger_tabclosedpre(tp);
        if (!win_valid_any_tab(win))
        {
            return;
        }
    }

    if (win->w_buffer != NULL)
    {
        close_buffer(win, win->w_buffer, free_buf ? DOBUF_UNLOAD : 0, FALSE, TRUE, TRUE);
    }

    for (ptp = first_tabpage; ptp != NULL && ptp != tp; ptp = ptp->tp_next)
    {
        ;
    }
    if (ptp == NULL || tp == curtab)
    {
        if (win_valid_any_tab(win) && win->w_buffer == NULL)
        {
            win->w_buffer = firstbuf;
            ++firstbuf->b_nwindows;
            if (win == curwin)
            {
                curbuf = curwin->w_buffer;
            }
            win_init_empty(win);
        }
        return;
    }

    for (wp = tp->tp_firstwin; wp != NULL && wp != win; wp = wp->w_next)
    {
        ;
    }
    if (wp == NULL)
    {
        return;
    }

    if (tp->tp_firstwin == tp->tp_lastwin)
    {
        int     h = tabline_height();

        if (tp == first_tabpage)
        {
            first_tabpage = tp->tp_next;
        }
        else
        {
            for (ptp = first_tabpage; ptp != NULL && ptp->tp_next != tp; ptp = ptp->tp_next)
            {
                ;
            }
            if (ptp == NULL)
            {
                internal_error("win_close_othertab()");
                return;
            }
            ptp->tp_next = tp->tp_next;
        }
        free_tp = TRUE;
        redraw_tabline = TRUE;
        shell_new_columns();
        if (h != tabline_height())
        {
            shell_new_rows();
        }
    }

    if (win->w_buffer != NULL)
    {
        --win->w_buffer->b_nwindows;
    }

    win_free_mem(win, &dir, tp);

    if (free_tp)
    {
        free_tabpage(tp);
    }
}

    static win_T *
win_free_mem(win_T       *win, int         *dirp, tabpage_T   *tp)
{
    frame_T     *frp;
    win_T       *wp;
    tabpage_T   *win_tp = tp == NULL ? curtab : tp;

    frp = win->w_frame;
    wp = winframe_remove(win, dirp, tp, NULL);
    vim_free(frp);
    win_free(win, tp);

    if (win == win_tp->tp_curwin)
    {
        win_tp->tp_curwin = wp;
    }

    return wp;
}

    static win_T *
winframe_remove(win_T       *win, int         *dirp, tabpage_T   *tp, frame_T     **unflat_altfr)
{
    frame_T *frp;
    frame_T *frp2;
    frame_T *frp3;
    frame_T     *frp_close = win->w_frame;
    win_T       *wp;
    int row;
    int col;

    if (tp == NULL ?  (firstwin == lastwin)  : tp->tp_firstwin == tp->tp_lastwin)
    {
        return NULL;
    }

    frame_locked++;

    wp = frame2win(frp_close->fr_parent);
    row = wp->w_winrow;
    col = wp->w_wincol;

    frp2 = win_altframe(win, tp);
    wp = frame2win(frp2);

    if (win->w_vsep_width == 0 && frp_close->fr_parent->fr_layout == FR_ROW && frp_close->fr_prev != NULL)
    {
        frame_set_vsep(frp_close->fr_prev, FALSE);
    }

    frame_remove(frp_close);

    if (frp_close->fr_parent->fr_layout == FR_COL)
    {
        if (frp2->fr_win != NULL && frp2->fr_win-> w_onebuf_opt.wo_wfh )
        {
            frp = frp_close->fr_prev;
            frp3 = frp_close->fr_next;
            while (frp != NULL || frp3 != NULL)
            {
                if (frp != NULL)
                {
                    if (!frame_fixed_height(frp))
                    {
                        frp2 = frp;
                        wp = frame2win(frp2);
                        break;
                    }
                    frp = frp->fr_prev;
                }
                if (frp3 != NULL)
                {
                    if (frp3->fr_win != NULL && !frp3->fr_win-> w_onebuf_opt.wo_wfh )
                    {
                        frp2 = frp3;
                        wp = frp3->fr_win;
                        break;
                    }
                    frp3 = frp3->fr_next;
                }
            }
        }
        frame_new_height(frp2, frp2->fr_height + frp_close->fr_height, frp2 == frp_close->fr_next, FALSE, FALSE);
        *dirp = 'v';
    }
    else
    {
        if (frp2->fr_win != NULL && frp2->fr_win-> w_onebuf_opt.wo_wfw )
        {
            frp = frp_close->fr_prev;
            frp3 = frp_close->fr_next;
            while (frp != NULL || frp3 != NULL)
            {
                if (frp != NULL)
                {
                    if (!frame_fixed_width(frp))
                    {
                        frp2 = frp;
                        wp = frame2win(frp2);
                        break;
                    }
                    frp = frp->fr_prev;
                }
                if (frp3 != NULL)
                {
                    if (frp3->fr_win != NULL && !frp3->fr_win-> w_onebuf_opt.wo_wfw )
                    {
                        frp2 = frp3;
                        wp = frp3->fr_win;
                        break;
                    }
                    frp3 = frp3->fr_next;
                }
            }
        }
        frame_new_width(frp2, frp2->fr_width + frp_close->fr_width, frp2 == frp_close->fr_next, FALSE);
        *dirp = 'h';
    }

    if (frp2 != frp_close->fr_prev)
    {
        frame_comp_pos(frp_close->fr_parent, &row, &col);
    }

    if (unflat_altfr == NULL)
    {
        frame_flatten(frp2);
    }
    else
    {
        *unflat_altfr = frp2;
    }

    frame_locked--;

    return wp;
}

    static void
frame_flatten(frame_T *frp)
{
    frame_T *frp2;
    frame_T *frp3;

    if (frp->fr_next != NULL || frp->fr_prev != NULL)
    {
        return;
    }

    frp->fr_parent->fr_layout = frp->fr_layout;
    frp->fr_parent->fr_child = frp->fr_child;
     for ((frp2) = frp->fr_child; (frp2) != NULL; (frp2) = (frp2)->fr_next) 
     {
        frp2->fr_parent = frp->fr_parent;
     }
    frp->fr_parent->fr_win = frp->fr_win;
    if (frp->fr_win != NULL)
    {
        frp->fr_win->w_frame = frp->fr_parent;
    }
    frp2 = frp->fr_parent;
    if (topframe->fr_child == frp)
    {
        topframe->fr_child = frp2;
    }
    vim_free(frp);

    frp = frp2->fr_parent;
    if (frp != NULL && frp->fr_layout == frp2->fr_layout)
    {
        if (frp->fr_child == frp2)
        {
            frp->fr_child = frp2->fr_child;
        }
        frp2->fr_child->fr_prev = frp2->fr_prev;
        if (frp2->fr_prev != NULL)
        {
            frp2->fr_prev->fr_next = frp2->fr_child;
        }
        for (frp3 = frp2->fr_child; ; frp3 = frp3->fr_next)
        {
            frp3->fr_parent = frp;
            if (frp3->fr_next == NULL)
            {
                frp3->fr_next = frp2->fr_next;
                if (frp2->fr_next != NULL)
                {
                    frp2->fr_next->fr_prev = frp3;
                }
                break;
            }
        }
        if (topframe->fr_child == frp2)
        {
            topframe->fr_child = frp;
        }
        vim_free(frp2);
    }
}

    static void
winframe_restore(win_T *wp, int dir, frame_T *unflat_altfr)
{
    frame_T     *frp = wp->w_frame;

    if (frp->fr_prev != NULL)
    {
        frame_append(frp->fr_prev, frp);
    }
    else
    {
        frame_insert(frp->fr_next, frp);
    }

    if (wp->w_vsep_width == 0 && frp->fr_parent->fr_layout == FR_ROW && frp->fr_prev != NULL)
    {
        frame_set_vsep(frp->fr_prev, TRUE);
    }

    if (wp->w_status_height == 0 && frp->fr_parent->fr_layout == FR_COL && frp->fr_prev != NULL)
    {
        frame_add_statusline(frp->fr_prev);
    }

    if (dir == 'v')
    {
        frame_new_height(unflat_altfr, unflat_altfr->fr_height - frp->fr_height, unflat_altfr == frp->fr_next, FALSE, FALSE);
    }
    else if (dir == 'h')
    {
        frame_new_width(unflat_altfr, unflat_altfr->fr_width - frp->fr_width, unflat_altfr == frp->fr_next, FALSE);
    }

    if (unflat_altfr != frp->fr_prev)
    {
        win_T   *topleft = frame2win(frp->fr_parent);
        int     row = topleft->w_winrow;
        int     col = topleft->w_wincol;

        frame_comp_pos(frp->fr_parent, &row, &col);
    }
}

    static frame_T *
win_altframe(win_T       *win, tabpage_T   *tp)
{
    frame_T     *frp;
    frame_T *other_fr;
    frame_T *target_fr;

    if (tp == NULL ?  (firstwin == lastwin)  : tp->tp_firstwin == tp->tp_lastwin)
    {
        return alt_tabpage()->tp_curwin->w_frame;
    }

    frp = win->w_frame;

    if (frp->fr_prev == NULL)
    {
        return frp->fr_next;
    }
    if (frp->fr_next == NULL)
    {
        return frp->fr_prev;
    }

    target_fr = frp->fr_next;
    other_fr  = frp->fr_prev;

    if (frp->fr_parent != NULL && frp->fr_parent->fr_layout == FR_COL && p_sb)
    {
        target_fr = frp->fr_prev;
        other_fr  = frp->fr_next;
    }

    if (frp->fr_parent != NULL && frp->fr_parent->fr_layout == FR_ROW && p_spr)
    {
        target_fr = frp->fr_prev;
        other_fr  = frp->fr_next;
    }

    if (frp->fr_parent != NULL && frp->fr_parent->fr_layout == FR_ROW)
    {
        if (frame_fixed_width(target_fr) && !frame_fixed_width(other_fr))
        {
            target_fr = other_fr;
        }
    }
    else
    {
        if (frame_fixed_height(target_fr) && !frame_fixed_height(other_fr))
        {
            target_fr = other_fr;
        }
    }

    return target_fr;
}

    static tabpage_T *
alt_tabpage(void)
{
    tabpage_T   *tp = NULL;
    int         forward;

    if ((tcl_flags & TCL_USELAST) && valid_tabpage(lastused_tabpage))
    {
        return lastused_tabpage;
    }

    forward = curtab->tp_next != NULL &&
            ((tcl_flags & TCL_LEFT) == 0 || curtab == first_tabpage);

    if (forward)
    {
        tp = curtab->tp_next;
    }
    else
    {
        for (tp = first_tabpage; tp->tp_next != curtab; tp = tp->tp_next)
        {
            ;
        }
    }

    return tp;
}

    static win_T *
frame2win(frame_T *frp)
{
    while (frp->fr_win == NULL)
    {
        frp = frp->fr_child;
    }
    return frp->fr_win;
}

    static int
frame_has_win(frame_T *frp, win_T *wp)
{
    frame_T     *p;

    if (frp->fr_layout == FR_LEAF)
    {
        return frp->fr_win == wp;
    }

     for ((p) = frp->fr_child; (p) != NULL; (p) = (p)->fr_next) 
     {
        if (frame_has_win(p, wp))
        {
            return TRUE;
        }
     }
    return FALSE;
}

static int min_set_ch = 1;

    static void
frame_new_height(frame_T     *topfrp, int         height, int         topfirst, int         wfh, int         set_ch)
{
    frame_T     *frp;
    int         extra_lines;
    int         h;

    if (topfrp->fr_parent == NULL && set_ch)
    {
        int new_ch = MAX(min_set_ch, p_ch + topfrp->fr_height - height);
        int save_ch = min_set_ch;
        if (new_ch != p_ch)
        {
            set_option_value((char_u *)"cmdheight", new_ch, NULL, 0);
        }
        min_set_ch = save_ch;
        height = MIN(height,  (Rows - p_ch - tabline_height()) );
    }
    if (topfrp->fr_win != NULL)
    {
        win_new_height(topfrp->fr_win, height - topfrp->fr_win->w_status_height -  0 );
    }
    else if (topfrp->fr_layout == FR_ROW)
    {
        do
        {
             for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
            {
                frame_new_height(frp, height, topfirst, wfh, set_ch);
                if (frp->fr_height > height)
                {
                    height = frp->fr_height;
                    break;
                }
            }
        }
        while (frp != NULL)
            ;
    }
    else
    {
        frp = topfrp->fr_child;
        if (wfh)
        {
            while (frame_fixed_height(frp))
            {
                frp = frp->fr_next;
                if (frp == NULL)
                {
                    return;
                }
            }
        }
        if (!topfirst)
        {
            while (frp->fr_next != NULL)
            {
                frp = frp->fr_next;
            }
            if (wfh)
            {
                while (frame_fixed_height(frp))
                {
                    frp = frp->fr_prev;
                }
            }
        }

        extra_lines = height - topfrp->fr_height;
        if (extra_lines < 0)
        {
            while (frp != NULL)
            {
                h = frame_minheight(frp, NULL);
                if (frp->fr_height + extra_lines < h)
                {
                    extra_lines += frp->fr_height - h;
                    frame_new_height(frp, h, topfirst, wfh, set_ch);
                }
                else
                {
                    frame_new_height(frp, frp->fr_height + extra_lines, topfirst, wfh, set_ch);
                    break;
                }
                if (topfirst)
                {
                    do
                    {
                        frp = frp->fr_next;
                    }
                    while (wfh && frp != NULL && frame_fixed_height(frp))
                        ;
                }
                else
                {
                    do
                    {
                        frp = frp->fr_prev;
                    }
                    while (wfh && frp != NULL && frame_fixed_height(frp))
                        ;
                }
                if (frp == NULL)
                {
                    height -= extra_lines;
                }
            }
        }
        else if (extra_lines > 0)
        {
            frame_new_height(frp, frp->fr_height + extra_lines, topfirst, wfh, set_ch);
        }
    }
    topfrp->fr_height = height;
}

    static int
frame_fixed_height(frame_T *frp)
{
    if (frp->fr_win != NULL)
    {
        return frp->fr_win-> w_onebuf_opt.wo_wfh ;
    }

    if (frp->fr_layout == FR_ROW)
    {
         for ((frp) = frp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            if (frame_fixed_height(frp))
            {
                return TRUE;
            }
         }
        return FALSE;
    }

     for ((frp) = frp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
     {
        if (!frame_fixed_height(frp))
        {
            return FALSE;
        }
     }
    return TRUE;
}

    static int
frame_fixed_width(frame_T *frp)
{
    if (frp->fr_win != NULL)
    {
        return frp->fr_win-> w_onebuf_opt.wo_wfw ;
    }

    if (frp->fr_layout == FR_COL)
    {
         for ((frp) = frp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            if (frame_fixed_width(frp))
            {
                return TRUE;
            }
         }
        return FALSE;
    }

     for ((frp) = frp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
     {
        if (!frame_fixed_width(frp))
        {
            return FALSE;
        }
     }
    return TRUE;
}

    static void
frame_add_statusline(frame_T *frp)
{
    win_T       *wp;

    if (frp->fr_layout == FR_LEAF)
    {
        wp = frp->fr_win;
        wp->w_status_height = statusline_height(wp);
    }
    else if (frp->fr_layout == FR_ROW)
    {
         for ((frp) = frp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            frame_add_statusline(frp);
         }
    }
    else
    {
        for (frp = frp->fr_child; frp->fr_next != NULL; frp = frp->fr_next)
        {
            ;
        }
        frame_add_statusline(frp);
    }
}

    static void
frame_new_width(frame_T     *topfrp, int         width, int         leftfirst, int         wfw)
{
    frame_T     *frp;
    int         extra_cols;
    int         w;
    win_T       *wp;

    if (topfrp->fr_layout == FR_LEAF)
    {
        wp = topfrp->fr_win;
        for (frp = topfrp; frp->fr_parent != NULL; frp = frp->fr_parent)
        {
            if (frp->fr_parent->fr_layout == FR_ROW && frp->fr_next != NULL)
            {
                break;
            }
        }
        if (frp->fr_parent == NULL)
        {
            wp->w_vsep_width = 0;
        }
        win_new_width(wp, width - wp->w_vsep_width);
    }
    else if (topfrp->fr_layout == FR_COL)
    {
        do
        {
             for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
            {
                frame_new_width(frp, width, leftfirst, wfw);
                if (frp->fr_width > width)
                {
                    width = frp->fr_width;
                    break;
                }
            }
        } while (frp != NULL);
    }
    else
    {
        frp = topfrp->fr_child;
        if (wfw)
        {
            while (frame_fixed_width(frp))
            {
                frp = frp->fr_next;
                if (frp == NULL)
                {
                    return;
                }
            }
        }
        if (!leftfirst)
        {
            while (frp->fr_next != NULL)
            {
                frp = frp->fr_next;
            }
            if (wfw)
            {
                while (frame_fixed_width(frp))
                {
                    frp = frp->fr_prev;
                }
            }
        }

        extra_cols = width - topfrp->fr_width;
        if (extra_cols < 0)
        {
            while (frp != NULL)
            {
                w = frame_minwidth(frp, NULL);
                if (frp->fr_width + extra_cols < w)
                {
                    extra_cols += frp->fr_width - w;
                    frame_new_width(frp, w, leftfirst, wfw);
                }
                else
                {
                    frame_new_width(frp, frp->fr_width + extra_cols, leftfirst, wfw);
                    break;
                }
                if (leftfirst)
                {
                    do
                    {
                        frp = frp->fr_next;
                    }
                    while (wfw && frp != NULL && frame_fixed_width(frp))
                        ;
                }
                else
                {
                    do
                    {
                        frp = frp->fr_prev;
                    }
                    while (wfw && frp != NULL && frame_fixed_width(frp))
                        ;
                }
                if (frp == NULL)
                {
                    width -= extra_cols;
                }
            }
        }
        else if (extra_cols > 0)
        {
            frame_new_width(frp, frp->fr_width + extra_cols, leftfirst, wfw);
        }
    }
    topfrp->fr_width = width;
}

    static void
frame_set_vsep(frame_T *frp, int add)
{
    win_T       *wp;

    if (frp->fr_layout == FR_LEAF)
    {
        wp = frp->fr_win;
        if (add && wp->w_vsep_width == 0)
        {
            if (wp->w_width > 0)
            {
                win_new_width(wp, wp->w_width - 1);
            }
            wp->w_vsep_width = 1;
        }
        else if (!add && wp->w_vsep_width == 1)
        {
            win_new_width(wp, wp->w_width + 1);
            wp->w_vsep_width = 0;
        }
    }
    else if (frp->fr_layout == FR_COL)
    {
         for ((frp) = frp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            frame_set_vsep(frp, add);
         }
    }
    else
    {
        frp = frp->fr_child;
        while (frp->fr_next != NULL)
        {
            frp = frp->fr_next;
        }
        frame_set_vsep(frp, add);
    }
}

    static void
frame_fix_width(win_T *wp)
{
    wp->w_frame->fr_width = wp->w_width + wp->w_vsep_width;
}

    static void
frame_fix_height(win_T *wp)
{
    wp->w_frame->fr_height =  (wp)->w_height  + wp->w_status_height;
}

    static int
frame_minheight(frame_T *topfrp, win_T *next_curwin)
{
    frame_T     *frp;
    int         m;
    int         n;

    if (topfrp->fr_win != NULL)
    {
        if (topfrp->fr_win == next_curwin)
        {
            m = p_wh + topfrp->fr_win->w_status_height;
        }
        else
        {
            m = p_wmh + topfrp->fr_win->w_status_height;
            if (topfrp->fr_win == curwin && next_curwin == NULL)
            {
                if (p_wmh == 0)
                {
                    ++m;
                }
                m +=  0 ;
            }
        }
    }
    else if (topfrp->fr_layout == FR_ROW)
    {
        m = 0;
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
        {
            n = frame_minheight(frp, next_curwin);
            if (n > m)
            {
                m = n;
            }
        }
    }
    else
    {
        m = 0;
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            m += frame_minheight(frp, next_curwin);
         }
    }

    return m;
}

static int
frame_wincount_in_height(frame_T *topfrp)
{
    frame_T     *frp;
    int         c = 0;
    int         n;

    if (topfrp->fr_win != NULL)
    {
        c = 1;
    }
    else if (topfrp->fr_layout == FR_ROW)
    {
        c = 0;
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
        {
            n = frame_wincount_in_height(frp);
            if (n > c)
            {
                c = n;
            }
        }
    }
    else
    {
        c = 0;
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            c += frame_wincount_in_height(frp);
         }
    }

    return c;
}

    static int
frame_minwidth(frame_T     *topfrp, win_T       *next_curwin)
{
    frame_T     *frp;
    int m;
    int n;

    if (topfrp->fr_win != NULL)
    {
        if (topfrp->fr_win == next_curwin)
        {
            m = p_wiw + topfrp->fr_win->w_vsep_width;
        }
        else
        {
            m = p_wmw + topfrp->fr_win->w_vsep_width;
            if (p_wmw == 0 && topfrp->fr_win == curwin && next_curwin == NULL)
            {
                ++m;
            }
        }
    }
    else if (topfrp->fr_layout == FR_COL)
    {
        m = 0;
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
        {
            n = frame_minwidth(frp, next_curwin);
            if (n > m)
            {
                m = n;
            }
        }
    }
    else
    {
        m = 0;
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            m += frame_minwidth(frp, next_curwin);
         }
    }

    return m;
}

    static void
close_others(int         message, int         forceit)
{
    win_T       *wp;
    win_T       *nextwp;
    win_T       *old_curwin = curwin;
    int         r;

    if (one_window())
    {
        if (message && !autocmd_busy)
        {
            msg(_(m_onlyone));
        }
        return;
    }

    for (wp = firstwin; win_valid(wp); wp = nextwp)
    {
        nextwp = wp->w_next;

        if (old_curwin != curwin && win_valid(old_curwin))
        {
            curwin = old_curwin;
            curbuf = curwin->w_buffer;
        }

        if (wp == curwin)
        {
            continue;
        }

        if (!buf_valid(wp->w_buffer) && win_valid(wp))
        {
            wp->w_buffer = NULL;
            win_close(wp, 0);
            continue;
        }
        r = can_abandon(wp->w_buffer, forceit);
        if (!win_valid(wp))
        {
            nextwp = firstwin;
            continue;
        }
        if (!r)
        {
                continue;
        }
        win_close(wp, !buf_hide(wp->w_buffer) && !bufIsChanged(wp->w_buffer));
    }

    if (message && ! (firstwin == lastwin) )
    {
        emsg(_(e_other_window_contains_changes));
    }
}

    static void
unuse_tabpage(tabpage_T *tp)
{
    tp->tp_topframe = topframe;
    tp->tp_firstwin = firstwin;
    tp->tp_lastwin = lastwin;
    tp->tp_curwin = curwin;
}

static int command_frame_height = TRUE;

    static void
use_tabpage(tabpage_T *tp)
{
    curtab = tp;
    topframe = curtab->tp_topframe;
    firstwin = curtab->tp_firstwin;
    lastwin = curtab->tp_lastwin;
    curwin = curtab->tp_curwin;
}

    static int
win_alloc_first(void)
{
    if (win_alloc_firstwin(NULL) == FAIL)
    {
        return FAIL;
    }

    first_tabpage = alloc_tabpage();
    if (first_tabpage == NULL)
    {
        return FAIL;
    }
    curtab = first_tabpage;
    unuse_tabpage(first_tabpage);

    return OK;
}

    static win_T *
win_alloc_popup_win(void)
{
    win_T *wp;

    wp = win_alloc(NULL, TRUE);
    if (wp == NULL)
    {
        return NULL;
    }
    win_init_some(wp, curwin);

     (wp)-> w_onebuf_opt.wo_scb  = FALSE;
     (wp)-> w_onebuf_opt.wo_crb  = FALSE;
    new_frame(wp);
    return wp;
}

    static void
win_init_popup_win(win_T *wp, buf_T *buf)
{
    wp->w_buffer = buf;
    ++buf->b_nwindows;
    win_init_empty(wp);

     vim_free(wp->w_localdir);
     (wp->w_localdir) = NULL;
}

    static int
win_alloc_firstwin(win_T *oldwin)
{
    curwin = win_alloc(NULL, FALSE);
    if (curwin == NULL)
    {
        return FAIL;
    }
    if (oldwin == NULL)
    {
        curbuf = buflist_new(NULL, NULL, 1L, BLN_LISTED);
        if (curwin == NULL || curbuf == NULL)
        {
            return FAIL;
        }
        curwin->w_buffer = curbuf;
        curbuf->b_nwindows = 1;
        curwin->w_alist = &global_alist;
        curwin_init();
    }
    else
    {
        win_init(curwin, oldwin, 0);

         (curwin)-> w_onebuf_opt.wo_scb  = FALSE;
         (curwin)-> w_onebuf_opt.wo_crb  = FALSE;
    }

    new_frame(curwin);
    if (curwin->w_frame == NULL)
    {
        return FAIL;
    }
    topframe = curwin->w_frame;
    topframe->fr_width =  Columns ;
    topframe->fr_height = Rows - p_ch;

    return OK;
}

    static void
new_frame(win_T *wp)
{
    frame_T *frp =  (frame_T *)alloc_clear(sizeof(frame_T)) ;

    wp->w_frame = frp;
    if (frp == NULL)
    {
        return;
    }
    frp->fr_layout = FR_LEAF;
    frp->fr_win = wp;
}

    static void
win_init_size(void)
{
    firstwin->w_height =  (Rows - p_ch - tabline_height()) ;
    firstwin->w_prev_height =  (Rows - p_ch - tabline_height()) ;
    topframe->fr_height =  (Rows - p_ch - tabline_height()) ;
    firstwin->w_width = topframe->fr_width;
}

    static tabpage_T *
alloc_tabpage(void)
{
    tabpage_T   *tp;

    tp =  (tabpage_T *)alloc_clear(sizeof(tabpage_T)) ;
    if (tp == NULL)
    {
        return NULL;
    }

    tp->tp_ch_used = p_ch;

    return tp;
}

    static void
free_tabpage(tabpage_T *tp)
{
    int idx;

    for (idx = 0; idx < SNAP_COUNT; ++idx)
    {
        clear_snapshot(tp, idx);
    }

    if (tp == lastused_tabpage)
    {
        lastused_tabpage = NULL;
    }

    vim_free(tp->tp_localdir);
    vim_free(tp->tp_prevdir);

    vim_free(tp);
}

    static int
win_new_tabpage(int after)
{
    tabpage_T   *tp = curtab;
    tabpage_T   *prev_tp = curtab;
    tabpage_T   *newtp;
    int         n;

    if (cmdwin_type != 0)
    {
        emsg(_(e_invalid_in_cmdline_window));
        return FAIL;
    }
    if (window_layout_locked(CMD_tabnew))
    {
        return FAIL;
    }

    newtp = alloc_tabpage();
    if (newtp == NULL)
    {
        return FAIL;
    }

    if (leave_tabpage(curbuf, TRUE) == FAIL)
    {
        vim_free(newtp);
        return FAIL;
    }
    curtab = newtp;

    newtp->tp_localdir = (tp->tp_localdir == NULL)
                                    ? NULL : vim_strsave(tp->tp_localdir);

    if (win_alloc_firstwin(tp->tp_curwin) == OK)
    {
        if (after == 1)
        {
            newtp->tp_next = first_tabpage;
            first_tabpage = newtp;
        }
        else
        {
            if (after > 0)
            {
                n = 2;
                for (tp = first_tabpage; tp->tp_next != NULL && n < after; tp = tp->tp_next)
                {
                    ++n;
                }
            }
            newtp->tp_next = tp->tp_next;
            tp->tp_next = newtp;
        }
        newtp->tp_firstwin = newtp->tp_lastwin = newtp->tp_curwin = curwin;

        win_init_size();
        firstwin->w_winrow = tabline_height();
        firstwin->w_prev_winrow = firstwin->w_winrow;
        win_comp_scroll(curwin);

        newtp->tp_topframe = topframe;
        last_status(FALSE);

        lastused_tabpage = prev_tp;

        redraw_all_later(UPD_NOT_VALID);
        apply_autocmds(EVENT_WINNEW, NULL, NULL, FALSE, curbuf);
        apply_autocmds(EVENT_WINENTER, NULL, NULL, FALSE, curbuf);
        apply_autocmds(EVENT_TABNEW, NULL, NULL, FALSE, curbuf);
        apply_autocmds(EVENT_TABENTER, NULL, NULL, FALSE, curbuf);
        return OK;
    }

    enter_tabpage(curtab, curbuf, TRUE, TRUE);
    return FAIL;
}

    static int
may_open_tabpage(void)
{
    int         n = (cmdmod.cmod_tab == 0)
                                       ? postponed_split_tab : cmdmod.cmod_tab;

    if (n == 0)
    {
        return FAIL;
    }

    cmdmod.cmod_tab = 0;
    postponed_split_tab = 0;
    return win_new_tabpage(n);
}

    static int
make_tabpages(int maxcount)
{
    int         count = maxcount;
    int         todo;

    if (count > p_tpm)
    {
        count = p_tpm;
    }

    block_autocmds();

    for (todo = count - 1; todo > 0; --todo)
    {
        if (win_new_tabpage(0) == FAIL)
        {
            break;
        }
    }

    unblock_autocmds();

    return (count - todo);
}

    static int
valid_tabpage(tabpage_T *tpc)
{
    tabpage_T   *tp;

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
     {
        if (tp == tpc)
        {
            return TRUE;
        }
     }
    return FALSE;
}

    static int
valid_tabpage_win(tabpage_T *tpc)
{
    tabpage_T   *tp;
    win_T       *wp;

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
    {
        if (tp == tpc)
        {
             for ((wp) = ((tp) == NULL || (tp) == curtab)             ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next) 
            {
                if (win_valid_any_tab(wp))
                {
                    return TRUE;
                }
            }
            return FALSE;
        }
    }
    return FALSE;
}

    static void
close_tabpage(tabpage_T *tab)
{
    tabpage_T   *ptp;

    if (tab == first_tabpage)
    {
        first_tabpage = tab->tp_next;
        ptp = first_tabpage;
    }
    else
    {
        for (ptp = first_tabpage; ptp != NULL && ptp->tp_next != tab; ptp = ptp->tp_next)
        {
            ;
        }
        ptp->tp_next = tab->tp_next;
    }

    goto_tabpage_tp(ptp, FALSE, FALSE);
    free_tabpage(tab);
}

    static tabpage_T *
find_tabpage(int n)
{
    tabpage_T   *tp;
    int         i = 1;

    if (n == 0)
    {
        return curtab;
    }

    for (tp = first_tabpage; tp != NULL && i != n; tp = tp->tp_next)
    {
        ++i;
    }
    return tp;
}

    static int
tabpage_index(tabpage_T *ftp)
{
    int         i = 1;
    tabpage_T   *tp;

    for (tp = first_tabpage; tp != NULL && tp != ftp; tp = tp->tp_next)
    {
        ++i;
    }
    return i;
}

    static int
leave_tabpage(buf_T       *new_curbuf, int         trigger_leave_autocmds)
{
    tabpage_T   *tp = curtab;

    reset_VIsual_and_resel();
    if (trigger_leave_autocmds)
    {
        if (new_curbuf != curbuf)
        {
            apply_autocmds(EVENT_BUFLEAVE, NULL, NULL, FALSE, curbuf);
            if (curtab != tp)
            {
                return FAIL;
            }
        }
        apply_autocmds(EVENT_WINLEAVE, NULL, NULL, FALSE, curbuf);
        if (curtab != tp)
        {
            return FAIL;
        }
        apply_autocmds(EVENT_TABLEAVE, NULL, NULL, FALSE, curbuf);
        if (curtab != tp)
        {
            return FAIL;
        }
    }

    reset_dragwin();
    tp->tp_curwin = curwin;
    tp->tp_prevwin = prevwin;
    tp->tp_firstwin = firstwin;
    tp->tp_lastwin = lastwin;
    tp->tp_old_Rows =  (Rows - p_ch - tabline_height()) ;
    if (tp->tp_old_Columns != -1)
    {
        tp->tp_old_Columns = topframe->fr_width;
        tp->tp_old_coloff = firstwin->w_wincol;
    }
    firstwin = NULL;
    lastwin = NULL;
    return OK;
}

    static void
enter_tabpage(tabpage_T   *tp, buf_T       *old_curbuf, int         trigger_enter_autocmds, int         trigger_leave_autocmds)
{
    int         old_off = tp->tp_firstwin->w_winrow;
    win_T       *next_prevwin = tp->tp_prevwin;
    tabpage_T   *last_tab = curtab;

    use_tabpage(tp);

    if (p_ch != curtab->tp_ch_used)
    {
        int new_ch = curtab->tp_ch_used;
        curtab->tp_ch_used = p_ch;
        command_frame_height = FALSE;
        set_option_value((char_u *)"cmdheight", new_ch, NULL, 0);
        command_frame_height = TRUE;
    }

    (void)win_enter_ext(tp->tp_curwin, WEE_CURWIN_INVALID | (trigger_enter_autocmds ? WEE_TRIGGER_ENTER_AUTOCMDS : 0) | (trigger_leave_autocmds ? WEE_TRIGGER_LEAVE_AUTOCMDS : 0));
    prevwin = next_prevwin;

    last_status(FALSE);
    win_comp_pos();

    reset_dragwin();

    if (curtab->tp_old_Rows !=  (Rows - p_ch - tabline_height())  || (old_off != firstwin->w_winrow))
    {
        shell_new_rows();
    }
    if (curtab->tp_old_Columns !=  Columns  || curtab->tp_old_coloff !=  0 )
    {
        if (starting == 0)
        {
            shell_new_columns();
            curtab->tp_old_Columns = topframe->fr_width;
            curtab->tp_old_coloff = firstwin->w_wincol;
        }
        else
        {
            curtab->tp_old_Columns = -1;
        }
    }

    lastused_tabpage = last_tab;

    if (trigger_enter_autocmds)
    {
        apply_autocmds(EVENT_TABENTER, NULL, NULL, FALSE, curbuf);
        if (old_curbuf != curbuf)
        {
            apply_autocmds(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf);
        }
    }

    redraw_all_later(UPD_NOT_VALID);
}

    static void
goto_tabpage(int n)
{
    tabpage_T   *tp = NULL;
    tabpage_T   *ttp;
    int         i;

    if (text_locked())
    {
        text_locked_msg();
        return;
    }

    if (first_tabpage->tp_next == NULL)
    {
        if (n > 1)
        {
            beep_flush();
        }
        return;
    }

    if (n == 0)
    {
        if (curtab->tp_next == NULL)
        {
            tp = first_tabpage;
        }
        else
        {
            tp = curtab->tp_next;
        }
    }
    else if (n < 0)
    {
        ttp = curtab;
        for (i = n; i < 0; ++i)
        {
            for (tp = first_tabpage; tp->tp_next != ttp && tp->tp_next != NULL; tp = tp->tp_next)
            {
                ;
            }
            ttp = tp;
        }
    }
    else if (n == 9999)
    {
        for (tp = first_tabpage; tp->tp_next != NULL; tp = tp->tp_next)
        {
            ;
        }
    }
    else
    {
        tp = find_tabpage(n);
        if (tp == NULL)
        {
            beep_flush();
            return;
        }
    }

    goto_tabpage_tp(tp, TRUE, TRUE);

}

    static void
goto_tabpage_tp(tabpage_T   *tp, int         trigger_enter_autocmds, int         trigger_leave_autocmds)
{
    if (trigger_enter_autocmds || trigger_leave_autocmds)
    {
         if (cmdwin_type != 0)
             {           emsg(_(e_invalid_in_cmdline_window));           return;     }
    }

    set_keep_msg(NULL, 0);

    skip_win_fix_scroll = TRUE;
    if (tp != curtab && leave_tabpage(tp->tp_curwin->w_buffer, trigger_leave_autocmds) == OK)
    {
        if (valid_tabpage(tp))
        {
            enter_tabpage(tp, curbuf, trigger_enter_autocmds, trigger_leave_autocmds);
        }
        else
        {
            enter_tabpage(curtab, curbuf, trigger_enter_autocmds, trigger_leave_autocmds);
        }
    }
    skip_win_fix_scroll = FALSE;
}

    static int
goto_tabpage_lastused(void)
{
    if (!valid_tabpage(lastused_tabpage))
    {
        return FAIL;
    }

    goto_tabpage_tp(lastused_tabpage, TRUE, TRUE);
    return OK;
}

    static void
goto_tabpage_win(tabpage_T *tp, win_T *wp)
{
    goto_tabpage_tp(tp, TRUE, TRUE);
    if (curtab == tp && win_valid(wp))
    {
        win_enter(wp, TRUE);
    }
}

    static void
tabpage_move(int nr)
{
    int         n = 1;
    tabpage_T *tp;
    tabpage_T *tp_dst;

    if (first_tabpage->tp_next == NULL)
    {
        return;
    }

    if (tabpage_move_disallowed)
    {
        return;
    }

    for (tp = first_tabpage; tp->tp_next != NULL && n < nr; tp = tp->tp_next)
    {
        ++n;
    }

    if (tp == curtab || (nr > 0 && tp->tp_next != NULL && tp->tp_next == curtab))
    {
        return;
    }

    tp_dst = tp;

    if (curtab == first_tabpage)
    {
        first_tabpage = curtab->tp_next;
    }
    else
    {
         for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
         {
            if (tp->tp_next == curtab)
            {
                break;
            }
         }
        if (tp == NULL)
        {
            return;
        }
        tp->tp_next = curtab->tp_next;
    }

    if (nr <= 0)
    {
        curtab->tp_next = first_tabpage;
        first_tabpage = curtab;
    }
    else
    {
        curtab->tp_next = tp_dst->tp_next;
        tp_dst->tp_next = curtab;
    }

    redraw_tabline = TRUE;
}

    static void
win_goto(win_T *wp)
{
    if (text_or_buf_locked())
    {
        beep_flush();
        return;
    }

    if (wp->w_buffer != curbuf)
    {
        reset_VIsual_and_resel();
    }
    else if (VIsual_active)
    {
        wp->w_cursor = curwin->w_cursor;
    }

    if (!win_valid(wp))
    {
        return;
    }

    win_enter(wp, TRUE);

}

    static win_T *
win_vert_neighbor(tabpage_T *tp, win_T *wp, int up, long count)
{
    frame_T     *fr;
    frame_T     *nfr;
    frame_T     *foundfr;

    foundfr = wp->w_frame;
    while (count--)
    {
        fr = foundfr;
        for (;;)
        {
            if (fr == tp->tp_topframe)
            {
                goto end;
            }
            if (up)
            {
                nfr = fr->fr_prev;
            }
            else
            {
                nfr = fr->fr_next;
            }
            if (fr->fr_parent->fr_layout == FR_COL && nfr != NULL)
            {
                break;
            }
            fr = fr->fr_parent;
        }

        for (;;)
        {
            if (nfr->fr_layout == FR_LEAF)
            {
                foundfr = nfr;
                break;
            }
            fr = nfr->fr_child;
            if (nfr->fr_layout == FR_ROW)
            {
                while (fr->fr_next != NULL && frame2win(fr)->w_wincol + fr->fr_width <= wp->w_wincol + wp->w_wcol)
                {
                    fr = fr->fr_next;
                }
            }
            if (nfr->fr_layout == FR_COL && up)
            {
                while (fr->fr_next != NULL)
                {
                    fr = fr->fr_next;
                }
            }
            nfr = fr;
        }
    }
end:
    return foundfr != NULL ? foundfr->fr_win : NULL;
}

    static void
win_goto_ver(int         up, long        count)
{
    win_T       *win;

    win = win_vert_neighbor(curtab, curwin, up, count);
    if (win != NULL)
    {
        win_goto(win);
    }
}

    static win_T *
win_horz_neighbor(tabpage_T *tp, win_T *wp, int left, long count)
{
    frame_T     *fr;
    frame_T     *nfr;
    frame_T     *foundfr;

    foundfr = wp->w_frame;
    while (count--)
    {
        fr = foundfr;
        for (;;)
        {
            if (fr == tp->tp_topframe)
            {
                goto end;
            }
            if (left)
            {
                nfr = fr->fr_prev;
            }
            else
            {
                nfr = fr->fr_next;
            }
            if (fr->fr_parent->fr_layout == FR_ROW && nfr != NULL)
            {
                break;
            }
            fr = fr->fr_parent;
        }

        for (;;)
        {
            if (nfr->fr_layout == FR_LEAF)
            {
                foundfr = nfr;
                break;
            }
            fr = nfr->fr_child;
            if (nfr->fr_layout == FR_COL)
            {
                while (fr->fr_next != NULL && frame2win(fr)->w_winrow + fr->fr_height <= wp->w_winrow + wp->w_wrow)
                {
                    fr = fr->fr_next;
                }
            }
            if (nfr->fr_layout == FR_ROW && left)
            {
                while (fr->fr_next != NULL)
                {
                    fr = fr->fr_next;
                }
            }
            nfr = fr;
        }
    }
end:
    return foundfr != NULL ? foundfr->fr_win : NULL;
}

    static void
win_goto_hor(int         left, long        count)
{
    win_T       *win;

    win = win_horz_neighbor(curtab, curwin, left, count);
    if (win != NULL)
    {
        win_goto(win);
    }
}

    static void
win_enter(win_T *wp, int undo_sync)
{
    (void)win_enter_ext(wp, (undo_sync ? WEE_UNDO_SYNC : 0) | WEE_TRIGGER_ENTER_AUTOCMDS | WEE_TRIGGER_LEAVE_AUTOCMDS);
}

    static void
win_fix_current_dir(void)
{
    if (curwin->w_localdir != NULL || curtab->tp_localdir != NULL)
    {
        char_u  *dirname;

        if (globaldir == NULL)
        {
            char_u      cwd[ PATH_MAX ];

            if (mch_dirname(cwd,  PATH_MAX ) == OK)
            {
                globaldir = vim_strsave(cwd);
            }
        }
        if (curwin->w_localdir != NULL)
        {
            dirname = curwin->w_localdir;
        }
        else
        {
            dirname = curtab->tp_localdir;
        }

        if (mch_chdir((char *)dirname) == 0)
        {
            last_chdir_reason = NULL;
            shorten_fnames(TRUE);
        }
    }
    else if (globaldir != NULL)
    {
        vim_ignored = mch_chdir((char *)globaldir);
         vim_free(globaldir);
         (globaldir) = NULL;
        last_chdir_reason = NULL;
        shorten_fnames(TRUE);
    }
}

    static int
win_enter_ext(win_T *wp, int flags)
{
    int         other_buffer = FALSE;
    int         curwin_invalid = (flags & WEE_CURWIN_INVALID);
    int         did_decrement = FALSE;

    if (wp == curwin && curwin_invalid == 0)
    {
        return FALSE;
    }

    if (curwin_invalid == 0 && (flags & WEE_TRIGGER_LEAVE_AUTOCMDS))
    {
        if (wp->w_buffer != curbuf)
        {
            apply_autocmds(EVENT_BUFLEAVE, NULL, NULL, FALSE, curbuf);
            other_buffer = TRUE;
            if (!win_valid(wp))
            {
                return FALSE;
            }
        }
        apply_autocmds(EVENT_WINLEAVE, NULL, NULL, FALSE, curbuf);
        if (!win_valid(wp))
        {
            return FALSE;
        }
    }

    if ((flags & WEE_UNDO_SYNC) && curbuf != wp->w_buffer)
    {
        u_sync(FALSE);
    }

    if (*p_spk == 'c' && curwin_invalid == 0)
    {
        update_topline();
    }

    if (wp->w_buffer != curbuf)
    {
        buf_copy_options(wp->w_buffer, BCO_ENTER | BCO_NOHELP);
    }
    if (curwin_invalid == 0)
    {
        prevwin = curwin;
        curwin->w_redr_status = true;
    }
    curwin = wp;
    curbuf = wp->w_buffer;
    check_cursor();
    if (!virtual_active())
    {
        curwin->w_cursor.coladd = 0;
    }
    if (*p_spk == 'c')
    {
        changed_line_abv_curs();
    }
    else
    {
        win_fix_cursor(get_real_state() & (MODE_NORMAL|MODE_CMDLINE|MODE_TERMINAL));
    }

    win_fix_current_dir();

    if (flags & WEE_TRIGGER_NEW_AUTOCMDS)
    {
        apply_autocmds(EVENT_WINNEW, NULL, NULL, FALSE, curbuf);
    }
    if (flags & WEE_TRIGGER_ENTER_AUTOCMDS)
    {
        apply_autocmds(EVENT_WINENTER, NULL, NULL, FALSE, curbuf);
        if (other_buffer)
        {
            apply_autocmds(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf);
        }
    }

    maketitle();
    curwin->w_redr_status = true;
    redraw_tabline = TRUE;
    redraw_vseps = TRUE;
    redraw_later(UPD_VALID);
    if (restart_edit)
    {
        redraw_later(UPD_VALID);
    }

    if (curwin->w_height < p_wh && !curwin-> w_onebuf_opt.wo_wfh )
    {
        win_setheight((int)p_wh);
    }
    else if (curwin->w_height == 0)
    {
        win_setheight(1);
    }

    if (curwin->w_width < p_wiw && !curwin-> w_onebuf_opt.wo_wfw )
    {
        win_setwidth((int)p_wiw);
    }

    setmouse();

    return did_decrement;
}

    static win_T *
buf_jump_open_win(buf_T *buf)
{
    win_T       *wp = NULL;

    if (curwin->w_buffer == buf)
    {
        wp = curwin;
    }
    else
    {
         for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
         {
            if (wp->w_buffer == buf)
            {
                break;
            }
         }
    }
    if (wp != NULL)
    {
        win_enter(wp, FALSE);
    }
    return wp;
}

    static win_T *
buf_jump_open_tab(buf_T *buf)
{
    win_T       *wp = buf_jump_open_win(buf);
    tabpage_T   *tp;

    if (wp != NULL)
    {
        return wp;
    }

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
     {
        if (tp != curtab)
        {
             for ((wp) = ((tp) == NULL || (tp) == curtab)             ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next) 
             {
                if (wp->w_buffer == buf)
                {
                    break;
                }
             }
            if (wp != NULL)
            {
                goto_tabpage_win(tp, wp);
                if (curwin != wp)
                {
                    wp = NULL;
                }
                break;
            }
        }
     }
    return wp;
}

static int last_win_id = LOWEST_WIN_ID - 1;

    static win_T *
win_alloc(win_T *after, int hidden)
{
    win_T       *new_wp;

    new_wp =  (win_T *)alloc_clear(sizeof(win_T)) ;
    if (new_wp == NULL)
    {
        return NULL;
    }

    if (win_alloc_lines(new_wp) == FAIL)
    {
        vim_free(new_wp);
        return NULL;
    }

    new_wp->w_id = ++last_win_id;

    block_autocmds();

    if (!hidden)
    {
        win_append(after, new_wp);
    }
    new_wp->w_wincol =  0 ;
    new_wp->w_width =  Columns ;

    new_wp->w_topline = 1;
    new_wp->w_botline = 2;
    new_wp->w_cursor.lnum = 1;
    new_wp->w_scbind_pos = 1;

    new_wp->w_allbuf_opt.wo_so = new_wp-> w_onebuf_opt.wo_so  = -1;
    new_wp->w_allbuf_opt.wo_sop = new_wp-> w_onebuf_opt.wo_sop  = -1;
    new_wp->w_allbuf_opt.wo_siso = new_wp-> w_onebuf_opt.wo_siso  = -1;

    new_wp->w_fraction = 0;
    new_wp->w_prev_fraction_row = -1;

    unblock_autocmds();
    new_wp->w_next_match_id = 1000;
    return new_wp;
}

    static void
win_free(win_T       *wp, tabpage_T   *tp)
{
    int         i;
    buf_T       *buf;
    wininfo_T   *wip;

    alist_unlink(wp->w_alist);

    block_autocmds();

    remove_highlight_overrides(wp->w_hl);
    vim_free(wp->w_hl);

    if (wp->w_stl_click != NULL)
    {
        for (i = 0; i < wp->w_stl_click_count; i++)
        {
            vim_free(wp->w_stl_click[i].funcname);
        }
        vim_free(wp->w_stl_click);
    }

    clear_winopt(&wp->w_onebuf_opt);
    clear_winopt(&wp->w_allbuf_opt);

    vim_free(wp->w_lcs_chars.multispace);
    vim_free(wp->w_lcs_chars.leadmultispace);

    {
        tabpage_T       *ttp;

        if (prevwin == wp)
        {
            prevwin = NULL;
        }
         for ((ttp) = first_tabpage; (ttp) != NULL; (ttp) = (ttp)->tp_next) 
         {
            if (ttp->tp_prevwin == wp)
            {
                ttp->tp_prevwin = NULL;
            }
         }
    }
    win_free_lsize(wp);

    for (i = 0; i < wp->w_tagstacklen; ++i)
    {
        tagstack_clear_entry(&wp->w_tagstack[i]);
    }
    vim_free(wp->w_localdir);
    vim_free(wp->w_prevdir);

     for ((buf) = firstbuf; (buf) != NULL; (buf) = (buf)->b_next) 
     {
         for ((wip) = (buf)->b_wininfo; (wip) != NULL; (wip) = (wip)->wi_next) 
         {
            if (wip->wi_win == wp)
            {
                wininfo_T       *wip2;

                 for ((wip2) = (buf)->b_wininfo; (wip2) != NULL; (wip2) = (wip2)->wi_next) 
                 {
                    if (wip2 != wip && wip2->wi_win == NULL)
                    {
                        if (wip2->wi_next != NULL)
                        {
                            wip2->wi_next->wi_prev = wip2->wi_prev;
                        }
                        if (wip2->wi_prev == NULL)
                        {
                            buf->b_wininfo = wip2->wi_next;
                        }
                        else
                        {
                            wip2->wi_prev->wi_next = wip2->wi_next;
                        }
                        free_wininfo(wip2);
                        break;
                    }
                 }

                wip->wi_win = NULL;
            }
         }
     }

    clear_matches(wp);

    free_jumplist(wp);

    if (win_valid_any_tab(wp))
    {
        win_remove(wp, tp);
    }
    if (autocmd_busy)
    {
        wp->w_next = au_pending_free_win;
        au_pending_free_win = wp;
    }
    else
    {
        vim_free(wp);
    }

    unblock_autocmds();
}

    static int
win_unlisted(win_T *wp)
{
    return is_aucmd_win(wp) ||  0 ;
}

    static void
win_append(win_T *after, win_T *wp)
{
    win_T       *before;

    if (after == NULL)
    {
        before = firstwin;
    }
    else
    {
        before = after->w_next;
    }

    wp->w_next = before;
    wp->w_prev = after;
    if (after == NULL)
    {
        firstwin = wp;
    }
    else
    {
        after->w_next = wp;
    }
    if (before == NULL)
    {
        lastwin = wp;
    }
    else
    {
        before->w_prev = wp;
    }
}

    static void
win_remove(win_T       *wp, tabpage_T   *tp)
{
    if (wp->w_prev != NULL)
    {
        wp->w_prev->w_next = wp->w_next;
    }
    else if (tp == NULL)
    {
        firstwin = curtab->tp_firstwin = wp->w_next;
    }
    else
    {
        tp->tp_firstwin = wp->w_next;
    }

    if (wp->w_next != NULL)
    {
        wp->w_next->w_prev = wp->w_prev;
    }
    else if (tp == NULL)
    {
        lastwin = curtab->tp_lastwin = wp->w_prev;
    }
    else
    {
        tp->tp_lastwin = wp->w_prev;
    }
}

    static void
frame_append(frame_T *after, frame_T *frp)
{
    frp->fr_next = after->fr_next;
    after->fr_next = frp;
    if (frp->fr_next != NULL)
    {
        frp->fr_next->fr_prev = frp;
    }
    frp->fr_prev = after;
}

    static void
frame_insert(frame_T *before, frame_T *frp)
{
    frp->fr_next = before;
    frp->fr_prev = before->fr_prev;
    before->fr_prev = frp;
    if (frp->fr_prev != NULL)
    {
        frp->fr_prev->fr_next = frp;
    }
    else
    {
        frp->fr_parent->fr_child = frp;
    }
}

    static void
frame_remove(frame_T *frp)
{
    if (frp->fr_prev != NULL)
    {
        frp->fr_prev->fr_next = frp->fr_next;
    }
    else
    {
        frp->fr_parent->fr_child = frp->fr_next;
    }
    if (frp->fr_next != NULL)
    {
        frp->fr_next->fr_prev = frp->fr_prev;
    }
}

    static int
win_alloc_lines(win_T *wp)
{
    wp->w_lines_valid = 0;
    wp->w_lines =  (wline_T *)alloc_clear(sizeof(wline_T) * (Rows)) ;
    if (wp->w_lines == NULL)
    {
        return FAIL;
    }
    return OK;
}

    static void
win_free_lsize(win_T *wp)
{
    if (wp != NULL)
    {
         vim_free(wp->w_lines);
         (wp->w_lines) = NULL;
    }
}

    static void
shell_new_rows(void)
{
    int         h = (int) (Rows - p_ch - tabline_height()) ;

    if (firstwin == NULL)
    {
        return;
    }
    if (h < frame_minheight(topframe, NULL))
    {
        h = frame_minheight(topframe, NULL);
    }

    frame_new_height(topframe, h, FALSE, TRUE, FALSE);
    if (!frame_check_height(topframe, h))
    {
        frame_new_height(topframe, h, FALSE, FALSE, FALSE);
    }

    win_comp_pos();
    compute_cmdrow();
    curtab->tp_ch_used = p_ch;

    if (!skip_win_fix_scroll)
    {
        win_fix_scroll(TRUE);
    }

    redraw_tabline = TRUE;
}

    static void
shell_new_columns(void)
{
    if (firstwin == NULL)
    {
        return;
    }

    int w =  Columns ;

    frame_new_width(topframe, w, FALSE, TRUE);
    if (!frame_check_width(topframe, w))
    {
        frame_new_width(topframe, w, FALSE, FALSE);
    }

    win_comp_pos();

    cmdline_col_off = firstwin->w_wincol;
    cmdline_width = topframe->fr_width;
    comp_col();
    if (!skip_win_fix_scroll)
    {
        win_fix_scroll(TRUE);
    }

    redraw_tabline = TRUE;
}

    static void
win_size_save(garray_T *gap)
{
    win_T       *wp;

    ga_init2(gap, sizeof(int), 1);
    if (ga_grow(gap, win_count() * 2 + 1) == FAIL)
    {
        return;
    }

    ((int *)gap->ga_data)[gap->ga_len++] =  (Rows - p_ch - tabline_height())  - last_stl_height(FALSE);

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
    {
        ((int *)gap->ga_data)[gap->ga_len++] =
            wp->w_width + wp->w_vsep_width;
        ((int *)gap->ga_data)[gap->ga_len++] = wp->w_height;
    }
}

    static void
win_size_restore(garray_T *gap)
{
    win_T       *wp;
    int i;
    int j;

    if (win_count() * 2 + 1 == gap->ga_len && ((int *)gap->ga_data)[0] ==  (Rows - p_ch - tabline_height())  - last_stl_height(FALSE))
    {
        for (j = 0; j < 2; ++j)
        {
            i = 1;
             for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
            {
                frame_setwidth(wp->w_frame, ((int *)gap->ga_data)[i++]);
                win_setheight_win(((int *)gap->ga_data)[i++], wp);
            }
        }
        win_comp_pos();
    }
}

    static void
win_comp_pos(void)
{
    int         row = tabline_height();
    int         col =  0 ;

    frame_comp_pos(topframe, &row, &col);
}

    static void
frame_comp_pos(frame_T *topfrp, int *row, int *col)
{
    win_T       *wp;
    frame_T     *frp;
    int         startcol;
    int         startrow;
    int         h;

    wp = topfrp->fr_win;
    if (wp != NULL)
    {
        if (wp->w_winrow != *row || wp->w_wincol != *col)
        {
            wp->w_winrow = *row;
            wp->w_wincol = *col;
            redraw_win_later(wp, UPD_NOT_VALID);
            wp->w_redr_status = true;
        }
        h =  (wp)->w_height  + wp->w_status_height;
        *row += h > topfrp->fr_height ? topfrp->fr_height : h;
        *col += wp->w_width + wp->w_vsep_width;
    }
    else
    {
        startrow = *row;
        startcol = *col;
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
        {
            if (topfrp->fr_layout == FR_ROW)
            {
                *row = startrow;
            }
            else
            {
                *col = startcol;
            }
            frame_comp_pos(frp, row, col);
        }
    }
}

    static void
win_ensure_size(void)
{
    if (curwin->w_height == 0)
    {
        win_setheight(1);
    }
    if (curwin->w_width == 0)
    {
        win_setwidth(1);
    }
}

    static void
win_setheight(int height)
{
    win_setheight_win(height, curwin);
}

    static void
win_setheight_win(int height, win_T *win)
{
    if (win == curwin)
    {
        if (height < p_wmh)
        {
            height = p_wmh;
        }
        if (height == 0)
        {
            height = 1;
        }
        height +=  0 ;
    }

    frame_setheight(win->w_frame, height + win->w_status_height);

    win_comp_pos();
    win_fix_scroll(TRUE);

    redraw_all_later(UPD_NOT_VALID);
}

    static void
frame_setheight(frame_T *curfrp, int height)
{
    int         room;
    int         take;
    int         room_cmdline;
    int         run;
    frame_T     *frp;
    int         h;
    int         room_reserved;

    if (curfrp->fr_height == height)
    {
        return;
    }

    if (curfrp->fr_parent == NULL)
    {
        if (height > 0)
        {
            frame_new_height(curfrp, height, FALSE, FALSE, TRUE);
        }
    }
    else if (curfrp->fr_parent->fr_layout == FR_ROW)
    {
        h = frame_minheight(curfrp->fr_parent, NULL);
        if (height < h)
        {
            height = h;
        }
        frame_setheight(curfrp->fr_parent, height);
    }
    else
    {
        for (run = 1; run <= 2; ++run)
        {
            room = 0;
            room_reserved = 0;
             for ((frp) = curfrp->fr_parent->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
            {
                if (frp != curfrp && frp->fr_win != NULL && frp->fr_win-> w_onebuf_opt.wo_wfh )
                {
                    room_reserved += frp->fr_height;
                }
                room += frp->fr_height;
                if (frp != curfrp)
                {
                    room -= frame_minheight(frp, NULL);
                }
            }
            if (curfrp->fr_width != topframe->fr_width)
            {
                room_cmdline = 0;
            }
            else
            {
                room_cmdline = Rows - p_ch - (lastwin->w_winrow +  (lastwin)->w_height  + lastwin->w_status_height);
                if (room_cmdline < 0)
                {
                    room_cmdline = 0;
                }
            }

            if (height <= room + room_cmdline)
            {
                break;
            }
            if (run == 2 || curfrp->fr_width == topframe->fr_width)
            {
                height = room + room_cmdline;
                break;
            }
            frame_setheight(curfrp->fr_parent, height + frame_minheight(curfrp->fr_parent,  ((win_T *)-1) ) - (int)p_wmh - 1);
        }

        take = height - curfrp->fr_height;

        if (height > room + room_cmdline - room_reserved)
        {
            room_reserved = room + room_cmdline - height;
        }
        if (take < 0 && room - curfrp->fr_height <= room_reserved)
        {
            room_reserved = 0;
        }

        if (take > 0 && room_cmdline > 0)
        {
            if (take < room_cmdline)
            {
                room_cmdline = take;
            }
            take -= room_cmdline;
            topframe->fr_height += room_cmdline;
        }

        frame_new_height(curfrp, height, FALSE, FALSE, TRUE);

        for (run = 0; run < 2; ++run)
        {
            if (run == 0)
            {
                frp = curfrp->fr_next;
            }
            else
            {
                frp = curfrp->fr_prev;
            }
            while (frp != NULL && take != 0)
            {
                h = frame_minheight(frp, NULL);
                if (room_reserved > 0 && frp->fr_win != NULL && frp->fr_win-> w_onebuf_opt.wo_wfh )
                {
                    if (room_reserved >= frp->fr_height)
                    {
                        room_reserved -= frp->fr_height;
                    }
                    else
                    {
                        if (frp->fr_height - room_reserved > take)
                        {
                            room_reserved = frp->fr_height - take;
                        }
                        take -= frp->fr_height - room_reserved;
                        frame_new_height(frp, room_reserved, FALSE, FALSE, TRUE);
                        room_reserved = 0;
                    }
                }
                else
                {
                    if (frp->fr_height - take < h)
                    {
                        take -= frp->fr_height - h;
                        frame_new_height(frp, h, FALSE, FALSE, TRUE);
                    }
                    else
                    {
                        frame_new_height(frp, frp->fr_height - take, FALSE, FALSE, TRUE);
                        take = 0;
                    }
                }
                if (run == 0)
                {
                    frp = frp->fr_next;
                }
                else
                {
                    frp = frp->fr_prev;
                }
            }
        }
    }
}

    static void
win_setwidth(int width)
{
    win_setwidth_win(width, curwin);
}

    static void
win_setwidth_win(int width, win_T *wp)
{
    if (wp == curwin)
    {
        if (width < p_wmw)
        {
            width = p_wmw;
        }
        if (width == 0)
        {
            width = 1;
        }
    }
    else if (width < 0)
    {
        width = 0;
    }

    frame_setwidth(wp->w_frame, width + wp->w_vsep_width);

    win_comp_pos();

    redraw_all_later(UPD_NOT_VALID);
}

    static void
frame_setwidth(frame_T *curfrp, int width)
{
    int         room;
    int         take;
    int         run;
    frame_T     *frp;
    int         w;
    int         room_reserved;

    if (curfrp->fr_width == width)
    {
        return;
    }

    if (curfrp->fr_parent == NULL)
    {
        return;
    }

    if (curfrp->fr_parent->fr_layout == FR_COL)
    {
        w = frame_minwidth(curfrp->fr_parent, NULL);
        if (width < w)
        {
            width = w;
        }
        frame_setwidth(curfrp->fr_parent, width);
    }
    else
    {
        for (run = 1; run <= 2; ++run)
        {
            room = 0;
            room_reserved = 0;
             for ((frp) = curfrp->fr_parent->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
            {
                if (frp != curfrp && frp->fr_win != NULL && frp->fr_win-> w_onebuf_opt.wo_wfw )
                {
                    room_reserved += frp->fr_width;
                }
                room += frp->fr_width;
                if (frp != curfrp)
                {
                    room -= frame_minwidth(frp, NULL);
                }
            }

            if (width <= room)
            {
                break;
            }
            if (run == 2 || curfrp->fr_height >=  (Rows - p_ch - tabline_height()) )
            {
                width = room;
                break;
            }
            frame_setwidth(curfrp->fr_parent, width + frame_minwidth(curfrp->fr_parent,  ((win_T *)-1) ) - (int)p_wmw - 1);
        }

        take = width - curfrp->fr_width;

        if (width > room - room_reserved)
        {
            room_reserved = room - width;
        }
        if (take < 0 && room - curfrp->fr_width < room_reserved)
        {
            room_reserved = 0;
        }

        frame_new_width(curfrp, width, FALSE, FALSE);

        for (run = 0; run < 2; ++run)
        {
            if (run == 0)
            {
                frp = curfrp->fr_next;
            }
            else
            {
                frp = curfrp->fr_prev;
            }
            while (frp != NULL && take != 0)
            {
                w = frame_minwidth(frp, NULL);
                if (room_reserved > 0 && frp->fr_win != NULL && frp->fr_win-> w_onebuf_opt.wo_wfw )
                {
                    if (room_reserved >= frp->fr_width)
                    {
                        room_reserved -= frp->fr_width;
                    }
                    else
                    {
                        if (frp->fr_width - room_reserved > take)
                        {
                            room_reserved = frp->fr_width - take;
                        }
                        take -= frp->fr_width - room_reserved;
                        frame_new_width(frp, room_reserved, FALSE, FALSE);
                        room_reserved = 0;
                    }
                }
                else
                {
                    if (frp->fr_width - take < w)
                    {
                        take -= frp->fr_width - w;
                        frame_new_width(frp, w, FALSE, FALSE);
                    }
                    else
                    {
                        frame_new_width(frp, frp->fr_width - take, FALSE, FALSE);
                        take = 0;
                    }
                }
                if (run == 0)
                {
                    frp = frp->fr_next;
                }
                else
                {
                    frp = frp->fr_prev;
                }
            }
        }
    }
}

    static void
win_setminheight(void)
{
    int         room;
    int         needed;
    int         first = TRUE;

    while (p_wmh > 0)
    {
        room = Rows - p_ch;
        needed = min_rows_for_all_tabpages() - 1;
        if (room >= needed)
        {
            break;
        }
        --p_wmh;
        if (first)
        {
            emsg(_(e_not_enough_room));
            first = FALSE;
        }
    }
}

    static void
win_setminwidth(void)
{
    int         room;
    int         needed;
    int         first = TRUE;

    while (p_wmw > 0)
    {
        room = topframe->fr_width;
        needed = frame_minwidth(topframe, NULL);
        if (room >= needed)
        {
            break;
        }
        --p_wmw;
        if (first)
        {
            emsg(_(e_not_enough_room));
            first = FALSE;
        }
    }
}

    static void
win_drag_status_line(win_T *dragwin, int offset)
{
    frame_T     *curfr;
    frame_T     *fr;
    int         room;
    int         up;
    int         n;

    fr = dragwin->w_frame;
    curfr = fr;
    if (fr != topframe)
    {
        fr = fr->fr_parent;
        if (fr->fr_layout != FR_COL)
        {
            curfr = fr;
            if (fr != topframe)
            {
                fr = fr->fr_parent;
            }
        }
    }

    while (curfr != topframe && curfr->fr_next == NULL)
    {
        if (fr != topframe)
        {
            fr = fr->fr_parent;
        }
        curfr = fr;
        if (fr != topframe)
        {
            fr = fr->fr_parent;
        }
    }

    if (offset < 0)
    {
        up = TRUE;
        offset = -offset;
        if (fr == curfr)
        {
            room = fr->fr_height - frame_minheight(fr, NULL);
        }
        else
        {
            room = 0;
            for (fr = fr->fr_child; ; fr = fr->fr_next)
            {
                room += fr->fr_height - frame_minheight(fr, NULL);
                if (fr == curfr)
                {
                    break;
                }
            }
        }
        fr = curfr->fr_next;
    }
    else
    {
        up = FALSE;
        room = Rows - cmdline_row;
        if (curfr->fr_next == NULL)
        {
            --room;
        }
        else
        {
            room -= p_ch;
        }
        if (room < 0)
        {
            room = 0;
        }
         for ((fr) = curfr->fr_next; (fr) != NULL; (fr) = (fr)->fr_next) 
         {
            room += fr->fr_height - frame_minheight(fr, NULL);
         }
        fr = curfr;
    }

    if (room < offset)
    {
        offset = room;
    }
    if (offset <= 0)
    {
        return;
    }

    if (fr != NULL)
    {
        frame_new_height(fr, fr->fr_height + offset, up, FALSE, TRUE);
    }

    if (up)
    {
        fr = curfr;
    }
    else
    {
        fr = curfr->fr_next;
    }

    while (fr != NULL && offset > 0)
    {
        n = frame_minheight(fr, NULL);
        if (fr->fr_height - offset <= n)
        {
            offset -= fr->fr_height - n;
            frame_new_height(fr, n, !up, FALSE, TRUE);
        }
        else
        {
            frame_new_height(fr, fr->fr_height - offset, !up, FALSE, TRUE);
            break;
        }
        if (up)
        {
            fr = fr->fr_prev;
        }
        else
        {
            fr = fr->fr_next;
        }
    }
    win_comp_pos();
    win_fix_scroll(TRUE);

    redraw_all_later(UPD_SOME_VALID);
    showmode();
}

    static void
win_drag_vsep_line(win_T *dragwin, int offset)
{
    frame_T     *curfr;
    frame_T     *fr;
    int         room;
    int         left;
    int         n;

    fr = dragwin->w_frame;
    if (fr == topframe)
    {
        return;
    }
    curfr = fr;
    fr = fr->fr_parent;
    if (fr->fr_layout != FR_ROW)
    {
        if (fr == topframe)
        {
            return;
        }
        curfr = fr;
        fr = fr->fr_parent;
    }

    while (curfr->fr_next == NULL)
    {
        if (fr == topframe)
        {
            break;
        }
        curfr = fr;
        fr = fr->fr_parent;
        if (fr != topframe)
        {
            curfr = fr;
            fr = fr->fr_parent;
        }
    }

    if (offset < 0)
    {
        left = TRUE;
        offset = -offset;
        room = 0;
        for (fr = fr->fr_child; ; fr = fr->fr_next)
        {
            room += fr->fr_width - frame_minwidth(fr, NULL);
            if (fr == curfr)
            {
                break;
            }
        }
        fr = curfr->fr_next;
    }
    else
    {
        left = FALSE;
        room = 0;
         for ((fr) = curfr->fr_next; (fr) != NULL; (fr) = (fr)->fr_next) 
         {
            room += fr->fr_width - frame_minwidth(fr, NULL);
         }
        fr = curfr;
    }

    if (room < offset)
    {
        offset = room;
    }
    if (offset <= 0)
    {
        return;
    }
    if (fr == NULL)
    {
        return;
    }

    frame_new_width(fr, fr->fr_width + offset, left, FALSE);

    if (left)
    {
        fr = curfr;
    }
    else
    {
        fr = curfr->fr_next;
    }

    while (fr != NULL && offset > 0)
    {
        n = frame_minwidth(fr, NULL);
        if (fr->fr_width - offset <= n)
        {
            offset -= fr->fr_width - n;
            frame_new_width(fr, n, !left, FALSE);
        }
        else
        {
            frame_new_width(fr, fr->fr_width - offset, !left, FALSE);
            break;
        }
        if (left)
        {
            fr = fr->fr_prev;
        }
        else
        {
            fr = fr->fr_next;
        }
    }
    win_comp_pos();
    redraw_all_later(UPD_NOT_VALID);
}

enum { FRACTION_MULT = 16384L };

    static void
set_fraction(win_T *wp)
{
    if (wp->w_height > 1)
    {
        wp->w_fraction = ((long)wp->w_wrow * FRACTION_MULT + FRACTION_MULT / 2) / (long)wp->w_height;
    }
}

    static void
win_fix_scroll(int resize)
{
    if (*p_spk == 'c')
    {
        return;
    }

    skip_update_topline = TRUE;
    win_T       *wp;
     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
    {
        if (wp->w_height != wp->w_prev_height)
        {
            wp->w_do_win_fix_cursor = true;

            if (*p_spk == 's' && wp->w_winrow != wp->w_prev_winrow && wp->w_botline - 1 <= wp->w_buffer->b_ml.ml_line_count)
            {
                int diff = (wp->w_winrow - wp->w_prev_winrow)
                                          + (wp->w_height - wp->w_prev_height);
                pos_T cursor = wp->w_cursor;
                linenr_T topline = wp->w_topline;
                colnr_T skipcol = wp->w_skipcol;

                wp->w_cursor.lnum = wp->w_botline - 1;

                if (diff > 0)
                {
                    cursor_down_inner(wp, diff);
                }
                else
                {
                    cursor_up_inner(wp, -diff);
                }

                wp->w_fraction = FRACTION_MULT;
                scroll_to_fraction(wp, wp->w_prev_height);

                wp->w_cursor = cursor;
                if (wp->w_topline == topline)
                {
                    wp->w_skipcol = skipcol;
                }
                wp->w_valid &= ~VALID_WCOL;
            }
            else if (wp == curwin)
            {
                wp->w_valid &= ~VALID_CROW;
            }

            invalidate_botline_win(wp);
            validate_botline_win(wp);
        }
        wp->w_prev_height = wp->w_height;
        wp->w_prev_winrow = wp->w_winrow;
    }
    skip_update_topline = FALSE;
    if (!(get_real_state() & (MODE_NORMAL|MODE_CMDLINE|MODE_TERMINAL)))
    {
        win_fix_cursor(FALSE);
    }
    else if (resize)
    {
        win_fix_cursor(TRUE);
    }
}

    static void
win_fix_cursor(int normal)
{
    win_T       *wp = curwin;

    if (skip_win_fix_cursor || !wp->w_do_win_fix_cursor || wp->w_buffer->b_ml.ml_line_count < wp->w_height)
    {
        return;
    }

    wp->w_do_win_fix_cursor = false;
    long so = MIN(wp->w_height / 2, get_scrolloff_value());
    linenr_T lnum = wp->w_cursor.lnum;

    wp->w_cursor.lnum = wp->w_topline;
    cursor_down_inner(wp, so);
    linenr_T top = wp->w_cursor.lnum;

    wp->w_cursor.lnum = wp->w_botline - 1;
    cursor_up_inner(wp, so);
    linenr_T bot = wp->w_cursor.lnum;

    wp->w_cursor.lnum = lnum;

    linenr_T nlnum = 0;
    if (lnum > bot && (wp->w_botline - wp->w_buffer->b_ml.ml_line_count) != 1)
    {
        nlnum = bot;
    }
    else if (lnum < top && wp->w_topline != 1)
    {
        nlnum = (so == wp->w_height / 2) ? bot : top;
    }

    if (nlnum != 0)
    {
        if (normal)
        {
            setmark('\'');
            wp->w_cursor.lnum = nlnum;
        }
        else
        {
            wp->w_fraction = (nlnum == bot) ? FRACTION_MULT : 0;
            scroll_to_fraction(wp, wp->w_prev_height);
            validate_botline();
        }
    }
}

    static void
win_new_height(win_T *wp, int height)
{
    int         prev_height = wp->w_height;

    if (height < 0)
    {
        height = 0;
    }
    if (wp->w_height == height)
    {
        return;
    }

    if (wp->w_height > 0)
    {
        if (wp == curwin && *p_spk == 'c')
        {
            validate_cursor();
        }
        if (wp->w_height != prev_height)
        {
            return;
        }
        if (wp->w_wrow != wp->w_prev_fraction_row)
        {
            set_fraction(wp);
        }
    }

    wp->w_height = height;
    wp->w_redr_status = true;
    win_comp_scroll(wp);

    if (!exiting && *p_spk == 'c')
    {
        if (!wp-> w_onebuf_opt.wo_sms )
        {
            wp->w_skipcol = 0;
        }
        scroll_to_fraction(wp, prev_height);
    }
}

    static void
scroll_to_fraction(win_T *wp, int prev_height)
{
    linenr_T    lnum;
    int sline;
    int line_size;
    int         height = wp->w_height;

    if (height > 0 && (!wp-> w_onebuf_opt.wo_scb  || wp == curwin) && (height < wp->w_buffer->b_ml.ml_line_count || wp->w_topline > 1))
    {
        lnum = wp->w_cursor.lnum;
        if (lnum < 1)
        {
            lnum = 1;
        }
        wp->w_wrow = ((long)wp->w_fraction * (long)height - 1L)
                                                               / FRACTION_MULT;
        line_size = plines_win_col(wp, lnum, (long)(wp->w_cursor.col)) - 1;
        sline = wp->w_wrow - line_size;

        if (sline >= 0)
        {
            int rows = plines_win(wp, lnum, FALSE);

            if (sline > wp->w_height - rows)
            {
                sline = wp->w_height - rows;
                wp->w_wrow -= rows - line_size;
            }
        }

        if (sline < 0)
        {
            int         want_row = wp->w_wrow;

            wp->w_wrow = line_size;
            if (wp->w_wrow >= wp->w_height && (wp->w_width - win_col_off(wp)) > 0)
            {
                colnr_T skipcol = wp->w_width - win_col_off(wp);

                --wp->w_wrow;
                while (wp->w_wrow > want_row)
                {
                    skipcol += wp->w_width - win_col_off(wp) + win_col_off2(wp);
                    --wp->w_wrow;
                }
                wp->w_skipcol = skipcol;
            }
        }
        else if (sline > 0)
        {
            while (sline > 0 && lnum > 1)
            {
                --lnum;
                    line_size = plines_win(wp, lnum, TRUE);
                sline -= line_size;
            }

            if (sline < 0)
            {
                lnum++;
                wp->w_wrow -= line_size + sline;
            }
            else if (sline > 0)
            {
                lnum = 1;
                wp->w_wrow -= sline;
            }
        }
        set_topline(wp, lnum);
    }

    if (wp == curwin)
    {
        curs_columns(FALSE);
    }

    if (prev_height > 0)
    {
        wp->w_prev_fraction_row = wp->w_wrow;
    }

    redraw_win_later(wp, UPD_SOME_VALID);
    invalidate_botline_win(wp);
}

    static void
win_new_width(win_T *wp, int width)
{
    wp->w_width = width < 0 ? 0 : width;
    wp->w_lines_valid = 0;
    changed_line_abv_curs_win(wp);
    invalidate_botline_win(wp);

    if (wp == curwin && *p_spk == 'c')
    {
        curs_columns(TRUE);
    }

    redraw_win_later(wp, UPD_NOT_VALID);
    wp->w_redr_status = true;
}

    static void
win_comp_scroll(win_T *wp)
{
    wp-> w_onebuf_opt.wo_scr  = ((unsigned)wp->w_height >> 1);
    if (wp-> w_onebuf_opt.wo_scr  == 0)
    {
        wp-> w_onebuf_opt.wo_scr  = 1;
    }
}

    static void
command_height(void)
{
    int         old_p_ch = curtab->tp_ch_used;

    frame_T *frp = lastwin->w_frame;
    while (frp->fr_width != topframe->fr_width && frp->fr_parent != NULL)
    {
        frp = frp->fr_parent;
    }

    while (frp->fr_prev != NULL && frp->fr_layout == FR_LEAF && frp->fr_win-> w_onebuf_opt.wo_wfh )
    {
        frp = frp->fr_prev;
    }

    while (p_ch > old_p_ch && command_frame_height)
    {
        if (frp == NULL)
        {
            emsg(_(e_not_enough_room));
            p_ch = old_p_ch;
            break;
        }
        int h = MIN(p_ch - old_p_ch, frp->fr_height - frame_minheight(frp, NULL));
        frame_add_height(frp, -h);
        old_p_ch += h;
        frp = frp->fr_prev;
    }
    if (p_ch < old_p_ch && command_frame_height && frp != NULL)
    {
        frame_add_height(frp, (int)(old_p_ch - p_ch));
    }

    win_comp_pos();
    win_fix_scroll(true);
    cmdline_row = Rows - p_ch;
    redraw_cmdline = TRUE;

    if (msg_scrolled == 0 && full_screen)
    {
        screen_fill(cmdline_row, (int)Rows, 0, (int)Columns, ' ', ' ', 0);
        msg_row = cmdline_row;
    }

    curtab->tp_ch_used = p_ch;
    min_set_ch = p_ch;
}

    static void
frame_add_height(frame_T *frp, int n)
{
    frame_new_height(frp, frp->fr_height + n, FALSE, FALSE, FALSE);
    for (;;)
    {
        frp = frp->fr_parent;
        if (frp == NULL)
        {
            break;
        }
        frp->fr_height += n;
    }
}

    static void
last_status(int         morewin)
{
    last_status_rec(topframe, last_stl_height(morewin) > 0);
}

    static void
last_status_rec(frame_T *fr, int statusline)
{
    frame_T     *fp;
    win_T       *wp;

    if (fr->fr_layout == FR_LEAF)
    {
        wp = fr->fr_win;
        if (wp->w_status_height != 0 && !statusline)
        {
            win_new_height(wp, wp->w_height + wp->w_status_height);
            wp->w_status_height = 0;
            comp_col();
        }
        else if (wp->w_status_height == 0 && statusline)
        {
            fp = fr;
            while (fp->fr_height <= frame_minheight(fp, NULL))
            {
                if (fp == topframe)
                {
                    emsg(_(e_not_enough_room));
                    return;
                }
                if (fp->fr_parent->fr_layout == FR_COL && fp->fr_prev != NULL)
                {
                    fp = fp->fr_prev;
                }
                else
                {
                    fp = fp->fr_parent;
                }
            }
            wp->w_status_height = statusline_height(wp);
            if (fp != fr)
            {
                frame_new_height(fp, fp->fr_height - wp->w_status_height, FALSE, FALSE, FALSE);
                frame_fix_height(wp);
                win_comp_pos();
            }
            else
            {
                win_new_height(wp, wp->w_height - wp->w_status_height);
            }
            comp_col();
            redraw_all_later(UPD_SOME_VALID);
        }
        if (abs(wp->w_height - wp->w_prev_height) == 1)
        {
            wp->w_prev_height = wp->w_height;
        }
    }
    else if (fr->fr_layout == FR_ROW)
    {
        if (!statusline)
        {
             for ((fp) = fr->fr_child; (fp) != NULL; (fp) = (fp)->fr_next) 
             {
                last_status_rec(fp, statusline);
             }
        }
        else
        {
            frame_T     *fp2;
            int         max_stlh = 0;
            int         new_row_height;

             for ((fp) = fr->fr_child; (fp) != NULL; (fp) = (fp)->fr_next) 
             {
                if (fp->fr_win != NULL && fp->fr_win->w_status_height == 0)
                {
                    int h = statusline_height(fp->fr_win);
                    if (h > max_stlh)
                    {
                        max_stlh = h;
                    }
                }
             }
            if (max_stlh == 0)
            {
                return;
            }

            fp2 = fr;
            while (fp2->fr_height - frame_minheight(fp2, NULL) < max_stlh)
            {
                if (fp2 == topframe)
                {
                    emsg(_(e_not_enough_room));
                    return;
                }
                if (fp2->fr_parent->fr_layout == FR_COL && fp2->fr_prev != NULL)
                {
                    fp2 = fp2->fr_prev;
                }
                else
                {
                    fp2 = fp2->fr_parent;
                }
            }

            if (fp2 != fr)
            {
                frame_new_height(fp2, fp2->fr_height - max_stlh, FALSE, FALSE, FALSE);
                new_row_height = fr->fr_height + max_stlh;
            }
            else
            {
                new_row_height = fr->fr_height;
            }

             for ((fp) = fr->fr_child; (fp) != NULL; (fp) = (fp)->fr_next) 
            {
                if (fp->fr_win != NULL)
                {
                    wp = fp->fr_win;
                    if (wp->w_status_height == 0)
                    {
                        wp->w_status_height = statusline_height(wp);
                        win_new_height(wp, new_row_height - wp->w_status_height);
                        frame_fix_height(wp);
                        comp_col();
                        redraw_all_later(UPD_SOME_VALID);
                        if (abs(wp->w_height - wp->w_prev_height) == 1)
                        {
                            wp->w_prev_height = wp->w_height;
                        }
                    }
                }
                else
                {
                    last_status_rec(fp, statusline);
                }
            }

            fr->fr_height = new_row_height;
            win_comp_pos();
        }
    }
    else
    {
        for (fp = fr->fr_child; fp->fr_next != NULL; fp = fp->fr_next)
        {
            ;
        }
        last_status_rec(fp, statusline);
    }
}

    static int
statusline_height(win_T *wp  __attribute__((unused)) )
{
    int stl_height = 1;

    return stl_height;
}

    static int
tabline_height(void)
{
    switch (p_stal)
    {
        case 0:
            return 0;
        case 1:
            return (first_tabpage->tp_next == NULL) ? 0 : 1;
    }
    return 1;
}

    static int
last_stl_height(int         morewin)
{
    return (p_ls == 2 || (p_ls == 1 && (morewin || ! (firstwin == lastwin) )))
                ? STATUS_HEIGHT : 0;
}

    static int
min_rows(void)
{
    if (firstwin == NULL)
    {
        return MIN_LINES;
    }

    return frame_minheight(curtab->tp_topframe, NULL) + tabline_height()
        + MIN_CMDHEIGHT;
}

    static int
min_rows_for_all_tabpages(void)
{
    int         total;
    tabpage_T   *tp;
    int         n;

    if (firstwin == NULL)
    {
        return MIN_LINES;
    }

    total = 0;
     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next) 
    {
        n = frame_minheight(tp->tp_topframe, NULL);
        if (total < n)
        {
            total = n;
        }
    }
    total += tabline_height();
    total += MIN_CMDHEIGHT;
    return total;
}

    static int
only_one_window(void)
{
    int         count = 0;
    win_T       *wp;

    if (first_tabpage->tp_next != NULL)
    {
        return FALSE;
    }

     for ((wp) = firstwin; (wp) != NULL; (wp) = (wp)->w_next) 
     {
        if (wp->w_buffer != NULL && (!((bt_help(wp->w_buffer) && !bt_help(curbuf))) || wp == curwin) && !is_aucmd_win(wp))
        {
            ++count;
        }
     }
    return (count <= 1);
}

    static void
check_lnums_both(int do_curwin, int nested)
{
    win_T       *wp;
    tabpage_T   *tp;

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
     {
         for ((wp) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next)
         {
        if ((do_curwin || wp != curwin) && wp->w_buffer == curbuf)
        {
            int need_adjust;

            if (!nested)
            {
                wp->w_save_cursor.w_cursor_save = wp->w_cursor;
                wp->w_save_cursor.w_topline_save = wp->w_topline;
            }

            need_adjust = wp->w_cursor.lnum > curbuf->b_ml.ml_line_count;
            if (need_adjust)
            {
                wp->w_cursor.lnum = curbuf->b_ml.ml_line_count;
            }
            if (need_adjust || !nested)
            {
                wp->w_save_cursor.w_cursor_corr = wp->w_cursor;
            }

            need_adjust = wp->w_topline > curbuf->b_ml.ml_line_count;
            if (need_adjust)
            {
                wp->w_topline = curbuf->b_ml.ml_line_count;
            }
            if (need_adjust || !nested)
            {
                wp->w_save_cursor.w_topline_corr = wp->w_topline;
            }
        }
         }
     }
}

    static void
check_lnums(int do_curwin)
{
    check_lnums_both(do_curwin, FALSE);
}

    static void
check_lnums_nested(int do_curwin)
{
    check_lnums_both(do_curwin, TRUE);
}

    static void
reset_lnums(void)
{
    win_T       *wp;
    tabpage_T   *tp;

     for ((tp) = first_tabpage; (tp) != NULL; (tp) = (tp)->tp_next)
     {
         for ((wp) = ((tp) == curtab)            ? firstwin : (tp)->tp_firstwin; (wp); (wp) = (wp)->w_next)
         {
        if (wp->w_buffer == curbuf)
        {
            if ( (((wp->w_save_cursor.w_cursor_corr).lnum == (wp->w_cursor).lnum) && ((wp->w_save_cursor.w_cursor_corr).col == (wp->w_cursor).col) && ((wp->w_save_cursor.w_cursor_corr).coladd == (wp->w_cursor).coladd))  && wp->w_save_cursor.w_cursor_save.lnum != 0)
            {
                wp->w_cursor = wp->w_save_cursor.w_cursor_save;
            }
            if (wp->w_save_cursor.w_topline_corr == wp->w_topline && wp->w_save_cursor.w_topline_save != 0)
            {
                wp->w_topline = wp->w_save_cursor.w_topline_save;
            }
            if (wp->w_save_cursor.w_topline_save > wp->w_buffer->b_ml.ml_line_count)
            {
                wp->w_valid &= ~VALID_TOPLINE;
            }
        }
         }
     }
}

    static int
make_snapshot(int idx)
{
    clear_snapshot(curtab, idx);
    if (make_snapshot_rec(topframe, &curtab->tp_snapshot[idx]) == FAIL)
    {
        clear_snapshot(curtab, idx);
        return FAIL;
    }
    return OK;
}

    static int
make_snapshot_rec(frame_T *fr, frame_T **frp)
{
    *frp =  (frame_T *)alloc_clear(sizeof(frame_T)) ;
    if (*frp == NULL)
    {
        return FAIL;
    }
    (*frp)->fr_layout = fr->fr_layout;
    (*frp)->fr_width = fr->fr_width;
    (*frp)->fr_height = fr->fr_height;
    if (fr->fr_next != NULL)
    {
        if (make_snapshot_rec(fr->fr_next, &((*frp)->fr_next)) == FAIL)
        {
            return FAIL;
        }
    }
    if (fr->fr_child != NULL)
    {
        if (make_snapshot_rec(fr->fr_child, &((*frp)->fr_child)) == FAIL)
        {
            return FAIL;
        }
    }
    if (fr->fr_layout == FR_LEAF && fr->fr_win == curwin)
    {
        (*frp)->fr_win = curwin;
    }
    return OK;
}

    static void
clear_snapshot(tabpage_T *tp, int idx)
{
    clear_snapshot_rec(tp->tp_snapshot[idx]);
    tp->tp_snapshot[idx] = NULL;
}

    static void
clear_snapshot_rec(frame_T *fr)
{
    if (fr == NULL)
    {
        return;
    }
    clear_snapshot_rec(fr->fr_next);
    clear_snapshot_rec(fr->fr_child);
    vim_free(fr);
}

    static win_T *
get_snapshot_curwin_rec(frame_T *ft)
{
    win_T       *wp;

    if (ft->fr_next != NULL)
    {
        if ((wp = get_snapshot_curwin_rec(ft->fr_next)) != NULL)
        {
            return wp;
        }
    }
    if (ft->fr_child != NULL)
    {
        if ((wp = get_snapshot_curwin_rec(ft->fr_child)) != NULL)
        {
            return wp;
        }
    }

    return ft->fr_win;
}

    static win_T *
get_snapshot_curwin(int idx)
{
    if (curtab->tp_snapshot[idx] == NULL)
    {
        return NULL;
    }

    return get_snapshot_curwin_rec(curtab->tp_snapshot[idx]);
}

    static void
restore_snapshot(int         idx, int         close_curwin)
{
    win_T       *wp;

    if (curtab->tp_snapshot[idx] != NULL && curtab->tp_snapshot[idx]->fr_width == topframe->fr_width && curtab->tp_snapshot[idx]->fr_height == topframe->fr_height && check_snapshot_rec(curtab->tp_snapshot[idx], topframe) == OK)
    {
        wp = restore_snapshot_rec(curtab->tp_snapshot[idx], topframe);
        win_comp_pos();
        if (wp != NULL && close_curwin)
        {
            win_goto(wp);
        }
        redraw_all_later(UPD_NOT_VALID);
    }
    clear_snapshot(curtab, idx);
}

    static int
check_snapshot_rec(frame_T *sn, frame_T *fr)
{
    if (sn->fr_layout != fr->fr_layout || (sn->fr_next == NULL) != (fr->fr_next == NULL) || (sn->fr_child == NULL) != (fr->fr_child == NULL) || (sn->fr_next != NULL && check_snapshot_rec(sn->fr_next, fr->fr_next) == FAIL) || (sn->fr_child != NULL && check_snapshot_rec(sn->fr_child, fr->fr_child) == FAIL) || (sn->fr_win != NULL && !win_valid(sn->fr_win)))
    {
        return FAIL;
    }
    return OK;
}

    static win_T *
restore_snapshot_rec(frame_T *sn, frame_T *fr)
{
    win_T       *wp = NULL;
    win_T       *wp2;

    fr->fr_height = sn->fr_height;
    fr->fr_width = sn->fr_width;
    if (fr->fr_layout == FR_LEAF)
    {
        frame_new_height(fr, fr->fr_height, FALSE, FALSE, FALSE);
        frame_new_width(fr, fr->fr_width, FALSE, FALSE);
        wp = sn->fr_win;
    }
    if (sn->fr_next != NULL)
    {
        wp2 = restore_snapshot_rec(sn->fr_next, fr->fr_next);
        if (wp2 != NULL)
        {
            wp = wp2;
        }
    }
    if (sn->fr_child != NULL)
    {
        wp2 = restore_snapshot_rec(sn->fr_child, fr->fr_child);
        if (wp2 != NULL)
        {
            wp = wp2;
        }
    }
    return wp;
}

    static int
frame_check_height(frame_T *topfrp, int height)
{
    frame_T *frp;

    if (topfrp->fr_height != height)
    {
        return FALSE;
    }

    if (topfrp->fr_layout == FR_ROW)
    {
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            if (frp->fr_height != height)
            {
                return FALSE;
            }
         }
    }

    return TRUE;
}

    static int
frame_check_width(frame_T *topfrp, int width)
{
    frame_T *frp;

    if (topfrp->fr_width != width)
    {
        return FALSE;
    }

    if (topfrp->fr_layout == FR_COL)
    {
         for ((frp) = topfrp->fr_child; (frp) != NULL; (frp) = (frp)->fr_next) 
         {
            if (frp->fr_width != width)
            {
                return FALSE;
            }
         }
    }

    return TRUE;
}

   static int
win_locked(win_T *wp)
{
    return wp->w_locked;
}

