    static int
vim_main2(void)
{
    if (recoverymode && params.fname == NULL)
    {
        recover_names(NULL, TRUE, NULL, 0, NULL);
        mch_exit(0);
    }

    set_init_3();

    if (params.no_swap_file)
    {
        p_uc = 0;
    }

    starting = NO_BUFFERS;
    no_wait_return = FALSE;
    if (!exmode_active)
    {
        msg_scroll = FALSE;
    }

    if (params.edit_type == EDIT_STDIN && !recoverymode)
    {
        read_stdin();
    }

    if ((did_emsg || msg_didout) && * ( term_strings[(int)(KS_TI)] )  != NUL && params.edit_type != EDIT_STDIN)
    {
        newline_on_exit = TRUE;
    }

    settmode(TMODE_RAW);

    if (need_wait_return || msg_didany)
    {
        wait_return(TRUE);
    }

    starttermcap();

    setmouse();
    if (scroll_region)
    {
        scroll_region_reset();
    }
    scroll_start();

    term_push_title( (SAVE_RESTORE_TITLE | SAVE_RESTORE_ICON) );

    if (exmode_active)
    {
        set_must_redraw(UPD_CLEAR);
    }
    else
    {
        screenclear();
    }

    no_wait_return = TRUE;

    create_windows(&params);

    if (exmode_active)
    {
        curwin->w_cursor.lnum = curbuf->b_ml.ml_line_count;
    }

    apply_autocmds(EVENT_BUFENTER, NULL, NULL, FALSE, curbuf);
    setpcmark();

    edit_buffers(&params, start_dir);
    vim_free(start_dir);

    shorten_fnames(FALSE);

        if (params.n_commands > 0)
        {
            exe_commands(&params);
        }

    starting = 0;

    RedrawingDisabled = 0;
    redraw_all_later(UPD_NOT_VALID);
    no_wait_return = FALSE;

    if (p_im)
    {
        need_start_insertmode = TRUE;
    }

    apply_autocmds(EVENT_VIMENTER, NULL, NULL, FALSE, curbuf);

    if (restart_edit != 0)
    {
        stuffcharReadbuff(  (-((KS_EXTRA) + ((int)(KE_NOP) << 8)))  );
    }

    do_redraw = TRUE;

    main_loop(FALSE, FALSE);

    return 0;
}

